window.LISP_DATA = {"items":[{"no":1,"file":"00-importMLeaders.lsp","cmd":"importMLeaders","cat":"標註","desc":"建立多重引線樣式，並依選擇的字型（Arial/Simplex）與是否斜體建立對應文字樣式後匯入樣式字典。","usage":"執行 importMLeaders → 輸入字型 [Arial/Simplex] → 輸入是否斜體 [Y/N] → 完成樣式建立","level":5,"lt":"✅","ver":"2025-09-25 (檔案日期)","author":"—","video":"","fas":"fas/00-importMLeaders.fas"},{"no":2,"file":"2d-section-rc-s2.lsp","cmd":"2d-section-rc-s2","cat":"剖面/結構","desc":"依資料表圖塊的樓層、結構系統、板厚、柱梁尺寸等屬性，自動繪製 RC 結構 2D 剖面（柱、梁、樓板、小梁投影線）。","usage":"執行 2d-section-rc-s2 → 選取資料表圖塊 → 指定基準點 → 自動繪製各樓層剖面","level":8,"lt":"✅","ver":"20251126","author":"chengshunyi / ChengBar","video":"","fas":"fas/2d-section-rc-s2.fas"},{"no":3,"file":"2d-section-wall.lsp","cmd":"2d-section-wall","cat":"剖面/結構","desc":"依資料表圖塊的樓高、牆厚、結構別等屬性，自動繪製牆體剖面，含女兒牆、泛水、防水收頭溝槽與尺寸標註。","usage":"執行 2d-section-wall → 選取資料表圖塊 → 指定基準點 → 自動繪製牆剖面與標註","level":7,"lt":"✅","ver":"20220702","author":"chengshunyi / ChengBar","video":"","fas":"fas/2d-section-wall.fas"},{"no":4,"file":"2DTOLW.LSP","cmd":"2DTOLW","cat":"修改","desc":"將選取的 2D 多段線（POLYLINE）轉換為輕量多段線（LWPOLYLINE），保留頂點與圖元屬性。","usage":"執行 2DTOLW → 選取 2D 多段線 → 自動轉換","level":4,"lt":"✅","ver":"20230710","author":"chengshunyi","video":"","fas":"fas/2DTOLW.fas"},{"no":5,"file":"2line-draw-CL.LSP","cmd":"2line-draw-CL","cat":"繪圖","desc":"選取同圖層雙線物件，在兩線之間自動畫出中心線（含短線忽略距離、CENTER 線型）。","usage":"執行 2line-draw-CL → 點選符合圖層的物件 → 輸入忽略短線長度 → 自動產生中心線","level":5,"lt":"✅","ver":"hanhphuc 13/10/2014","author":"hanhphuc（cadtutor 網路程式）","video":"","fas":"fas/2line-draw-CL.fas"},{"no":6,"file":"2LINE2-DRAW-CL.lsp","cmd":"wf1、wtee、wcl","cat":"繪圖","desc":"牆體雙線中心線工具：wcl 切兩線畫中心線，wf1 畫中心線並倒角接合，wtee 處理 T 型牆線接合。","usage":"執行 wcl / wf1 / wtee → 於牆內或牆外點選第一點 → 拖曳點選第二點 → 自動畫中心線並接合","level":5,"lt":"✅","ver":"20240422","author":"Alanh (March 2021) / chengshunyi","video":"","fas":"fas/2LINE2-DRAW-CL.fas"},{"no":7,"file":"2p-div-line.LSP","cmd":"2p-div-line、2p-div-line-l、S-L-div-line","cat":"繪圖","desc":"在兩點或一條線上等分，並依選取的目標線畫出延伸線到等分點（放在「等分線」圖層）。","usage":"執行 2p-div-line → 輸入等分數 → 點選第一點與第二點 → 選取目標延伸線 → 產生等分線","level":4,"lt":"✅","ver":"20240208","author":"chengshunyi","video":"","fas":"fas/2p-div-line.fas"},{"no":8,"file":"2polydrawhatch-s.LSP","cmd":"2polydrawhatch-s","cat":"繪圖","desc":"選取兩條封閉多段線，在兩者之間產生實心填充（雙線區域），可由 DCL 設定圖層、顏色、透明度。","usage":"執行 2polydrawhatch-s → DCL 設定圖層/顏色/透明度 → 選取兩條多段線（點近起點）→ 自動產生填充","level":6,"lt":"✅","ver":"20230405","author":"chengshunyi","video":"https://youtu.be/MvYVHodI_00","fas":"fas/2polydrawhatch-s.fas"},{"no":9,"file":"2polydrawhatch.LSP","cmd":"2polydrawhatch","cat":"繪圖","desc":"選取兩條多段線，在其間產生實心塗黑填充，並由 DCL 設定填充圖層、顏色與透明度。","usage":"執行 2polydrawhatch → DCL 設定圖層/顏色/透明度 → 選取兩條多段線 → 產生填充並調整繪圖順序","level":6,"lt":"✅","ver":"20230404","author":"chengshunyi（改自 offhat.lsp）","video":"","fas":"fas/2polydrawhatch.fas"},{"no":10,"file":"2ts.LSP","cmd":"2ts","cat":"文字","desc":"將選取的單行/多行文字批次改成指定的文字樣式（預設 TG-TEXT），樣式不存在時提示。","usage":"執行 2ts → 輸入目標文字樣式 → 選取文字物件 → 自動套用樣式","level":2,"lt":"✅","ver":"Tharwat 14.10.16","author":"Tharwat","video":"","fas":"fas/2ts.fas"},{"no":11,"file":"3DFA2SOL.LSP","cmd":"3dfa2sol","cat":"修改","desc":"將選取的 3DFACE 三維面轉換成 SOLID 實心填色物件（2D Solid），可用 UNDO BACK 還原。","usage":"執行 3dfa2sol → 選取 3DFACE → 自動轉換為 SOLID","level":3,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"Theo L.A. Groenenberg","video":"","fas":"fas/3DFA2SOL.fas"},{"no":12,"file":"3p-draw-arc.lsp","cmd":"3p-draw-arc","cat":"繪圖","desc":"輸入三個 3D 點，建立通過這三點平面的 UCS 後在該平面上畫弧，再還原 UCS。","usage":"執行 3p-draw-arc → 依序點選三點 → 自動切 UCS 畫弧並還原","level":1,"lt":"✅","ver":"2025-11-04 (檔案日期)","author":"—","video":"","fas":"fas/3p-draw-arc.fas"},{"no":13,"file":"3P-Rec-c.lsp","cmd":"3pr-c、3prd-c","cat":"繪圖","desc":"以三點建立矩形：前兩點定第一組邊，第三點定另一邊長度與方向，3prd-c 為動態預覽版。","usage":"執行 3pr-c 或 3prd-c → 指定第 1、2 點 → 指定第 3 點 → 產生矩形多段線","level":5,"lt":"⚠️","ver":"2024-10-17 (檔案日期)","author":"Lee Mac","video":"","fas":"fas/3P-Rec-c.fas"},{"no":14,"file":"3P-Rec.lsp","cmd":"3prd-td、3prd-t、3pr、3prd、3prd-open、3prd-open-up、3prd-open-hid","cat":"繪圖","desc":"三點矩形（標準/動態預覽），並擴充 3prd-open 系列以三點畫出開口（上開/隱藏線）矩形。","usage":"執行 3pr / 3prd / 3prd-open → 指定三點 → 產生矩形或開口矩形","level":5,"lt":"⚠️","ver":"2025-03-23 (檔案日期)","author":"Lee Mac（chengshunyi 擴充）","video":"https://youtu.be/bZvTLzI9ijw","fas":"fas/3P-Rec.fas"},{"no":15,"file":"3PD.lsp","cmd":"3pds、3pd、interset","cat":"查詢","desc":"以方格線與等高線計算交點、各格平均坡度並依坡度分級標示（5% 以下為一級坡等），自動建立 3PD 圖層與文字。","usage":"執行 3pd → 選取方格線與首曲線 → 輸入首曲線間距與方格邊長 → 自動計算並標註坡度分級","level":7,"lt":"✅","ver":"2025-03-09 (檔案日期)","author":"—","video":"","fas":"fas/3PD.fas"},{"no":16,"file":"7test0.lsp","cmd":"7test0","cat":"圖面管理","desc":"依輸入的圖紙大小（預設 A3）與比例尺，在模型空間畫出對應圖紙範圍的矩形圖框並 ZOOM。","usage":"執行 7test0 → 輸入圖紙大小 → 輸入比例尺（如 1:100）→ 自動畫矩形並縮放","level":3,"lt":"✅","ver":"20221230","author":"—","video":"","fas":"fas/7test0.fas"},{"no":17,"file":"A-A-N.LSP","cmd":"a-n","cat":"文字","desc":"依起迄號碼連續寫出「A-號碼」文字，向下每列間距 80，文字高度隨 LTSCALE 縮放。","usage":"執行 a-n → 指定起點 → 輸入起始號與結束號 → 自動排出 A-1、A-2…","level":2,"lt":"✅","ver":"84.2.23","author":"—","video":"","fas":"fas/A-A-N.fas"},{"no":18,"file":"A-AM-N.LSP","cmd":"am-n","cat":"文字","desc":"依 M 範圍與每組 N 數量，連續寫出「A M-N」格式的雙層編號文字，向下排列。","usage":"執行 am-n → 輸入起始 M 與結束 M → 指定起點 → 逐組輸入 N 數量 → 自動寫出編號","level":2,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/A-AM-N.fas"},{"no":19,"file":"A-AREA.LSP","cmd":"a-area","cat":"修改","desc":"輸入目標面積，以基準點量測 AREA 現有面積，計算比例後以窗選物件縮放成指定面積。","usage":"執行 a-area → 輸入目標面積 → 指定基準點 → 指定窗選兩角 → 自動縮放","level":2,"lt":"✅","ver":"84.3.14","author":"—","video":"","fas":"fas/A-AREA.fas"},{"no":20,"file":"A-E-N.LSP","cmd":"e-n","cat":"文字","desc":"依起迄號碼連續寫出「E - 號碼」格式的編號文字，向下每列間距 80。","usage":"執行 e-n → 輸入起始與結束號碼 → 指定起點 → 自動排出編號","level":2,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/A-E-N.fas"},{"no":21,"file":"A-EM-N.LSP","cmd":"em-n","cat":"文字","desc":"依 M 範圍與每組 N 數量，連續寫出「E M-N」格式的雙層編號文字。","usage":"執行 em-n → 輸入起始與結束 M → 指定起點 → 逐組輸入 N 數量 → 自動寫出編號","level":2,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/A-EM-N.fas"},{"no":22,"file":"A-S-N.LSP","cmd":"s-n","cat":"文字","desc":"依起迄號碼連續寫出「S - 號碼」格式的編號文字，向下每列間距 80。","usage":"執行 s-n → 輸入起始與結束號碼 → 指定起點 → 自動排出編號","level":2,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/A-S-N.fas"},{"no":23,"file":"A-SM-N.LSP","cmd":"sm-n","cat":"文字","desc":"依 M 範圍與每組 N 數量，連續寫出「S M-N」格式的雙層編號文字。","usage":"執行 sm-n → 輸入起始與結束 M → 指定起點 → 逐組輸入 N 數量 → 自動寫出編號","level":2,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/A-SM-N.fas"},{"no":24,"file":"A2W.LSP","cmd":"A2W、Arc2Wipeout","cat":"修改","desc":"將圓、弧、含弧或純直線的多段線離散化成多邊形，轉成 Wipeout 遮罩，並可保留原物件、置頂與繼承圖層屬性。","usage":"執行 A2W → DCL 設定等分數、是否刪除原物件、邊框顯示 → 選取圓/弧/多段線 → 產生 Wipeout","level":6,"lt":"✅","ver":"2026-08-29 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/A2W.fas"},{"no":25,"file":"AAC-pl.lsp","cmd":"AAC、ArchiAreaCal","cat":"面積/數量統計","desc":"建築面積計算：連續選取多段線，自動判斷矩形、三角形、梯形、圓等形狀，產生面積算式、編號、尺寸標註與虛線/紅線。","usage":"執行 AAC → DCL 設定單位/比例/起始編號 → 連續選取多段線 → 自動標註面積算式與編號","level":7,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"MyCAD / ChengBar（推測）","video":"","fas":"fas/AAC-pl.fas"},{"no":26,"file":"AB2L-V2.lsp","cmd":"AB2L","cat":"對齊/排列","desc":"選取一條對齊線與兩個圖塊，將圖塊對齊到線的頭尾端點。","usage":"執行 AB2L → 選取對齊線 → 選取兩個圖塊（限 2 個）→ 自動移到線兩端","level":4,"lt":"✅","ver":"20240308","author":"chengshunyi","video":"","fas":"fas/AB2L-V2.fas"},{"no":27,"file":"ACAD_VarInit.LSP","cmd":"ACAD_VarInit","cat":"系統/授權","desc":"以 DCL 設定外參、標註、文字、填充等物件圖層（XREFLAYER 等），設定存於 TEMP 文字檔並可載入建議值。","usage":"執行 ACAD_VarInit → DCL 檢視/輸入各類物件預設圖層 → 按確定寫入設定檔並建立圖層","level":6,"lt":"✅","ver":"2025-12-21 (檔案日期)","author":"MyCAD","video":"","fas":""},{"no":28,"file":"ACAD_VarInit_2024.lsp","cmd":"ACAD_VarInit_2024","cat":"系統/授權","desc":"以 DCL 設定外參、標註、文字、填充等物件預設圖層，儲存/載入 TEMP 設定檔，僅限 AutoCAD 2024 以上。","usage":"執行 ACAD_VarInit_2024 → DCL 設定各物件圖層（可套用建議值）→ 確定後套用","level":6,"lt":"✅","ver":"2025-12-21 (檔案日期)","author":"MyCAD","video":"","fas":""},{"no":29,"file":"AD-ALIGN.lsp","cmd":"AD-ALIGN","cat":"標註","desc":"對選取的多段線/線/弧，沿各頂點自動畫對齊尺寸，弧線段加標弧長，可由選項對話框設定標註位置。","usage":"執行 AD-ALIGN → 選取多段線（Enter 或 Options 設定）→ 自動標註各段尺寸","level":6,"lt":"✅","ver":"Stefan M. 10.11.2015","author":"Stefan M.（KimProjects.com）","video":"","fas":"fas/AD-ALIGN.fas"},{"no":30,"file":"AD-HV.LSP","cmd":"AD-HV","cat":"標註","desc":"自動標註多段線：改用水平/垂直線性尺寸，可設定標註在線內或線外，斜線段兩向皆標。","usage":"執行 AD-HV → 選取多段線 → 視需要進入 Options 設定內/外側 → 自動標註","level":6,"lt":"✅","ver":"Pkenewell 11 Dec 2019","author":"Stefan M. / Pkenewell","video":"","fas":"fas/AD-HV.fas"},{"no":31,"file":"AD.LSP","cmd":"AD","cat":"標註","desc":"自動標註多段線：沿頂點畫尺寸，弧線段加註弧長，Options 可設定標註位置。","usage":"執行 AD → 選取多段線 → 視需要進入 Options → 自動標註各段","level":6,"lt":"✅","ver":"Stefan M. 10.11.2015","author":"Stefan M.（KimProjects.com）","video":"","fas":"fas/AD.fas"},{"no":32,"file":"add-Layouts-bymtext.lsp","cmd":"add-Layouts-bymtext","cat":"出圖/列印","desc":"選取多個 MText，依文字內容批次新增配置（Layout）、套用 DWG to PDF 與 A3 滿版紙張並建立視埠。","usage":"執行 add-Layouts-bymtext → 選取 MText → 自動以文字內容建立各配置與視埠","level":5,"lt":"✅","ver":"20230801","author":"chengshunyi","video":"","fas":"fas/add-Layouts-bymtext.fas"},{"no":33,"file":"add-My-Layout.lsp","cmd":"add-My-Layout、plotsetupcheck","cat":"出圖/列印","desc":"新增特定名稱的配置，指派灰階 CTB、PDF/DWF 印表機與紙張，並可由範本匯入頁面設定。","usage":"執行 add-My-Layout → 自動建立並設定配置（plotsetupcheck 為檢查範例）","level":4,"lt":"✅","ver":"20240405","author":"chengshunyi","video":"","fas":"fas/add-My-Layout.fas"},{"no":34,"file":"add-rows2table.LSP","cmd":"（無，副程式庫）","cat":"修改","desc":"選取表格後，在表格末端插入一列指定高度的空白列。","usage":"載入後直接執行 → 選取表格 → 自動於最後插入空白列","level":1,"lt":"✅","ver":"2021-11-19 (檔案日期)","author":"—","video":"","fas":"fas/add-rows2table.fas"},{"no":35,"file":"add-text.lsp","cmd":"add_m2、add_m3、add_cl、add_pl、add_BE、add_SE、add_u、add_up3、add_up2、add_d、add_pm、add_dr","cat":"文字","desc":"對選取的文字加字首或字尾，預設有 m²、m³、CL、PL、±、直徑等多種常用符號指令。","usage":"執行 add_m2 等指令 → 選取文字/MText/屬性 → 自動加上對應字尾或字首","level":4,"lt":"✅","ver":"20230221","author":"Lee Mac（pstext）/ chengshunyi","video":"","fas":"fas/add-text.fas"},{"no":36,"file":"add-win-dor-dim.lsp","cmd":"add-win-dor-dim","cat":"標註","desc":"門窗詳圖標尺寸：依點選的線以固定箭頭偏移量連續標註尺寸，Enter 結束。","usage":"執行 add-win-dor-dim → 點選線 → 重複點選 → Enter 結束","level":3,"lt":"✅","ver":"20231205","author":"chengshunyi","video":"","fas":"fas/add-win-dor-dim.fas"},{"no":37,"file":"ADD_PROPS.LSP","cmd":"ADD_PROPS、GET_PROPS","cat":"圖面管理","desc":"寫入與讀取 DWG 摘要資訊（作者、備註、關鍵字、超連結）與自訂屬性（如「繪圖單位」）。","usage":"執行 ADD_PROPS → 自動寫入摘要與自訂屬性；執行 GET_PROPS → 列出現有屬性","level":5,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"Autodesk 範例（改寫）","video":"","fas":"fas/ADD_PROPS.fas"},{"no":38,"file":"AddMLineStyle-m.LSP","cmd":"test","cat":"繪圖","desc":"以 DXF 資料建立並加入 MLINE 樣式至 ACAD_MLINESTYLE 字典，附刪除樣式函式，test 指令示範畫多線。","usage":"執行 test → 依提示點選起點與下一點 → 以範例多線樣式繪製","level":5,"lt":"✅","ver":"20240727","author":"Lee Mac / chengshunyi","video":"","fas":"fas/AddMLineStyle-m.fas"},{"no":39,"file":"addmlinestyle.LSP","cmd":"（無，副程式庫）","cat":"繪圖","desc":"以 entmake 建立名為「SPEC Pipe」的多線樣式，已存在則提示。","usage":"載入後呼叫其函式建立多線樣式","level":3,"lt":"✅","ver":"2022-07-30 (檔案日期)","author":"—","video":"","fas":"fas/addmlinestyle.fas"},{"no":40,"file":"AddObjectsToBlock.lsp","cmd":"addtoblock","cat":"圖塊/屬性","desc":"選取多個物件後再選一個圖塊，將物件加入該圖塊定義，並檢查動態、非等比例與自我參照限制。","usage":"執行 addtoblock → 選取要加入的物件 → 點選目標圖塊 → 自動更新圖塊定義","level":5,"lt":"✅","ver":"Version 1.2","author":"Lee Mac","video":"","fas":"fas/AddObjectsToBlock.fas"},{"no":41,"file":"ADDTAB-dwglist.LSP","cmd":"addtab-dwglist","cat":"轉檔/匯出入","desc":"讀取 dwg-list.csv 圖紙清單，在指定位置建立含標題列的 AutoCAD 表格並設定字高與對齊。","usage":"執行 addtab-dwglist → 選取 CSV 檔 → 指定表格插入點 → 自動建立圖紙清單表","level":6,"lt":"✅","ver":"20230429","author":"chengshunyi","video":"","fas":"fas/ADDTAB-dwglist.fas"},{"no":42,"file":"ADDTAB.LSP","cmd":"ADDTAB","cat":"面積/數量統計","desc":"依選取的物件建立 AREA TABLE 表格，列出編號與面積等欄位，並設定標題與儲存格字高對齊。","usage":"執行 ADDTAB → 選取物件 → 指定表格插入點 → 自動建立表格","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"—","video":"","fas":"fas/ADDTAB.fas"},{"no":43,"file":"AddTable-sample.LSP","cmd":"AddTable、SelectTableCell","cat":"其他","desc":"示範以 ActiveX 建立 5x3 表格，並用 HitTest 點選儲存格修改其文字。","usage":"執行 AddTable → 指定表格插入點；執行 SelectTableCell → 點選儲存格 → 修改文字","level":6,"lt":"✅","ver":"202402","author":"網路範例（AutoCAD 表格教學）","video":"","fas":"fas/AddTable-sample.fas"},{"no":44,"file":"AddVertex-pl.lsp","cmd":"AddVertex-pl、wall-open-win-pl、get-line-Vertex1、get-line-Vertex2、get-seg-Vertex1、get-seg-Vertex2","cat":"修改","desc":"在多段線指定位置加頂點；wall-open-win-pl 於牆線/多段線上依開口寬度與離牆距離開窗開門並畫門窗框。","usage":"執行 AddVertex-pl → 點選多段線靠近位置 → 加頂點；或執行 wall-open-win-pl → 選牆線 → 指定開口位置/方向","level":7,"lt":"✅","ver":"2025-01-09 (檔案日期)","author":"—","video":"","fas":"fas/AddVertex-pl.fas"},{"no":45,"file":"AdjustLayoutText.lsp","cmd":"AdjustLayoutText","cat":"文字","desc":"DCL 設定圖稱（MText）與圖號（Text）的座標、字高、框寬、字寬比例，批次調整各配置文字並修正 frame_text 樣式為微軟正黑體。","usage":"執行 AdjustLayoutText → DCL 輸入座標/字高/寬度比例 → 確定後批次處理所有配置","level":6,"lt":"✅","ver":"2026-04-26","author":"Gemini AI","video":"","fas":"fas/AdjustLayoutText.fas"},{"no":46,"file":"AdjustPlineArea.lsp","cmd":"AdjustPlineArea","cat":"修改","desc":"選取封閉多段線，顯示原始面積並輸入目標面積，依形心自動計算倍數縮放使面積符合目標。","usage":"執行 AdjustPlineArea → 選取封閉多段線 → DCL 輸入目標面積 → 確定後自動縮放","level":6,"lt":"✅","ver":"20220716更新","author":"MyCAD","video":"","fas":"fas/AdjustPlineArea.fas"},{"no":47,"file":"ae_projectsearchpath.lsp","cmd":"（無，副程式庫）","cat":"系統/授權","desc":"透過登錄機碼建立、刪除專案並設定專案搜尋路徑（RefSearchPath），供 PROJECTNAME 使用。","usage":"載入後呼叫函式 → 指定專案名稱與路徑（以分號分隔）","level":5,"lt":"✅","ver":"2023-06-29 (檔案日期)","author":"網路程式","video":"","fas":""},{"no":48,"file":"align-block-boundary-ui.LSP","cmd":"align-block-boundary-ui","cat":"對齊/排列","desc":"DCL 選擇上緣/下緣/左緣/右緣，將多個圖塊依邊界框對齊到指定基準點，並記憶上次模式。","usage":"執行 align-block-boundary-ui → DCL 選對齊方式 → 選取圖塊 → 指定基準點 → 自動對齊","level":6,"lt":"✅","ver":"2025-11-05 (檔案日期)","author":"MyCAD","video":"","fas":"fas/align-block-boundary-ui.fas"},{"no":49,"file":"align-block-boundary.lsp","cmd":"align-block-boundary","cat":"對齊/排列","desc":"以命令列選擇 Top/Bottom/Left/Right，將選取圖塊的邊界框邊緣對齊到指定基準點。","usage":"執行 align-block-boundary → 輸入對齊方式 → 選取圖塊 → 指定基準點 → 自動對齊","level":4,"lt":"✅","ver":"2025-11-05 (檔案日期)","author":"MyCAD","video":"","fas":"fas/align-block-boundary.fas"},{"no":50,"file":"align-block.lsp","cmd":"align-block-y、align-block-X、align-block","cat":"對齊/排列","desc":"選取多個圖塊，依插入點對齊到水平線或垂直線（X/Y/Z 軸）上。","usage":"執行 align-block / align-block-X / align-block-y → 選取圖塊 → 指定對齊點","level":3,"lt":"✅","ver":"20220826","author":"chengshunyi","video":"","fas":"fas/align-block.fas"},{"no":51,"file":"align-mtext-2pt.LSP","cmd":"align-mtext-2pt-c、align-mtext-2pt-l、align-mtext-2pt-r、align-mtext-2pt、atx、aty","cat":"對齊/排列","desc":"先選線（或指定兩點範圍），再選文字，將文字依插入點沿線對齊，提供置中/靠左/靠右及 X、Y 軸對齊版本。","usage":"執行 align-mtext-2pt-c/l/r 或 atx/aty → 選線或指定兩點 → 選取文字 → 自動對齊","level":5,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"Tharwat（chengshunyi 修改）","video":"https://youtu.be/PY5gnvM5dSY","fas":"fas/align-mtext-2pt.fas"},{"no":52,"file":"align-mtext.lsp","cmd":"align-mtext-c、align-mtext-l、align-mtext-r、align-mtext、atx、aty","cat":"對齊/排列","desc":"選取一條線後選取文字，將文字依插入點對齊到線上，可選置中、靠左、靠右，atx/aty 為 X、Y 軸對齊。","usage":"執行 align-mtext-c/l/r 或 atx/aty → 選取線 → 選取文字 → 自動對齊","level":5,"lt":"✅","ver":"20241129","author":"Tharwat / chengshunyi","video":"https://youtu.be/3QNGtFiwLJo","fas":"fas/align-mtext.fas"},{"no":53,"file":"align-text.LSP","cmd":"align-text","cat":"對齊/排列","desc":"將一群同旋轉角的文字沿垂直於文字方向重新對齊，並依字高倍數等距排列。","usage":"執行 align-text → 選取文字物件 → 指定間距 → 自動對齊並等距","level":5,"lt":"✅","ver":"Version 1.3 / 20241128","author":"Lee Mac","video":"","fas":"fas/align-text.fas"},{"no":54,"file":"ALIGN-XYZ.lsp","cmd":"ab-H、ab-V","cat":"對齊/排列","desc":"選取圖塊或文字，依插入點對齊到指定對齊點的水平或垂直線上，並可等距分佈。","usage":"執行 ab-H 或 ab-V → 選取圖塊/文字 → 選取參考物件或指定對齊點 → 自動移動對齊","level":4,"lt":"✅","ver":"2026-10-18 (檔案日期)","author":"RJP（2018）/ chengshunyi","video":"","fas":"fas/ALIGN-XYZ.fas"},{"no":55,"file":"AlignDoorNo.lsp","cmd":"AlignDoorNo","cat":"對齊/排列","desc":"依門圖塊位置自動將門牌圖塊對齊到門旁，可自動掃描全圖、設定圖塊名稱、搜尋偏移，並可補插門牌。","usage":"執行 AlignDoorNo → DCL 設定門圖塊/門牌圖塊名稱與偏移 → 選取範圍或全圖 → 自動對齊門牌","level":7,"lt":"✅","ver":"2026-02-08 (檔案日期)","author":"MyCAD","video":"","fas":"fas/AlignDoorNo.fas"},{"no":56,"file":"AlignMText.lsp","cmd":"AlignMText","cat":"對齊/排列","desc":"依實際邊界框高/寬加上間距，將多個 MText 依 Y 由上而下或 X 由左而右重新排列，並記住間距設定。","usage":"執行 AlignMText → 選擇水平(X)或垂直(Y) → 輸入淨空距離 → 選取 MText → 自動排列","level":7,"lt":"✅","ver":"2026/04/05","author":"Gemini AI Assistant","video":"","fas":"fas/AlignMText.fas"},{"no":57,"file":"AlignText.lsp","cmd":"at-auto、at","cat":"對齊/排列","desc":"將單行文字依對齊點沿垂直文字旋轉方向對齊，可依字高倍數等距；at-auto 自動依序排列。","usage":"執行 at 或 at-auto → 選取文字 → 輸入行距（以行為單位）→ 自動對齊","level":5,"lt":"✅","ver":"Version 1.4 / 2016-01-16","author":"Lee Mac","video":"https://youtu.be/JUisD8YKDeM","fas":"fas/AlignText.fas"},{"no":58,"file":"AlignView.LSP","cmd":"AlignView","cat":"圖面管理","desc":"點選兩點，以 DVIEW 旋轉視圖使該線成為水平，方便對齊斜向圖面。","usage":"執行 AlignView → 指定第一點與第二點 → 視圖自動旋轉對齊","level":1,"lt":"✅","ver":"20211212","author":"—","video":"","fas":"fas/AlignView.fas"},{"no":59,"file":"AMD.lsp","cmd":"AMD","cat":"面積/數量統計","desc":"面積自動標註：DCL 選擇多重引線樣式與單位，以射線掃描求出物件內部中心，建立引用面積的 Field 多重引線，可加前綴、單位與流水編號。","usage":"執行 AMD → DCL 選樣式/單位/前綴/編號 → 點選封閉區域 → 自動產生面積引線標註","level":7,"lt":"✅","ver":"2026-03-26 (檔案日期)","author":"MyCAD","video":"","fas":"fas/AMD.fas"},{"no":60,"file":"AMTP.lsp","cmd":"AMTP","cat":"文字","desc":"AnnoMText Pro：切換 MText 可註解屬性，設定 5 組（XL/L/M/S/XS）基準字高、正中對齊、寬度歸零與字體，可一鍵繪製五圖層範例。","usage":"執行 AMTP → DCL 設定五組字高/圖層/顏色 → 選取 MText → 套用註解比例與字高","level":7,"lt":"✅","ver":"2026/07/11","author":"ChengBar (MyCAD)","video":"","fas":"fas/AMTP.fas"},{"no":61,"file":"ANNO_TOOLKIT.lsp","cmd":"ANNO_TOOLKIT","cat":"標註","desc":"可註解（Annotative）疑難排解對話框，一鍵執行 ANNOALLVISIBLE、ANNORESET、OBJECTSCALE、SELECTIONANNODISPLAY 等相關設定。","usage":"執行 ANNO_TOOLKIT → 在對話框點選要執行的註解工具 → 自動套用並顯示結果","level":6,"lt":"✅","ver":"2025-12-14 (檔案日期)","author":"MyCAD","video":"","fas":"fas/ANNO_TOOLKIT.fas"},{"no":62,"file":"AnnoUtil-txt.lsp","cmd":"AnnoUtil-txt","cat":"文字","desc":"註解優化控制面板：依繪圖單位、比例與樣式計算註解文字字高，並控制 SELECTIONANNODISPLAY 等註解顯示設定。","usage":"執行 AnnoUtil-txt → DCL 選單位/比例/文字樣式 → 確定後套用或計算字高","level":6,"lt":"✅","ver":"2026-04-26 (檔案日期)","author":"MyCAD","video":"","fas":"fas/AnnoUtil-txt.fas"},{"no":63,"file":"ApplyDimStyleToSel-SCA.LSP","cmd":"ApplyDimStyleToSel-SCA","cat":"標註","desc":"以 DCL 選擇比例（預設 1:100）組合尺寸型式名稱，將選取的尺寸物件套用該型式，並搭配設定/還原指令。","usage":"執行 ApplyDimStyleToSel-SCA → DCL 選比例 → 選取尺寸物件 → 套用尺寸型式","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"MyCAD","video":"","fas":"fas/ApplyDimStyleToSel-SCA.fas"},{"no":64,"file":"ApplyDimStyleToSelection.lsp","cmd":"ApplyDimStyleToSelection","cat":"標註","desc":"以 DCL 選擇比例組合尺寸型式名稱，將選取的尺寸物件批次套用該尺寸型式，型式不存在即終止。","usage":"執行 ApplyDimStyleToSelection → DCL 選比例 → 選取尺寸物件 → 套用尺寸型式","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"MyCAD","video":"https://youtu.be/unx3hh6urM4","fas":"fas/ApplyDimStyleToSelection.fas"},{"no":65,"file":"ApplyMLStyleToSelection.lsp","cmd":"ApplymlStyleToSelection","cat":"標註","desc":"以 DCL 選擇比例組合多重引線樣式名稱（JH_M_ 前綴），將選取的多重引線批次套用該樣式。","usage":"執行 ApplymlStyleToSelection → DCL 選比例 → 選取多重引線 → 套用樣式","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"MyCAD","video":"https://youtu.be/IOYo7umO7Fk","fas":"fas/ApplyMLStyleToSelection.fas"},{"no":66,"file":"arc-line-v.LSP","cmd":"arc-line-v2、arc-line-v3、arc-line-v4、arc-line-v5、arc-line-v6、arc-line-v7、arc-line-v8、arc-line-v","cat":"繪圖","desc":"弧形牆畫漸進線：點選左、右、上三點，依 2～8 等分/段數產生由疏到密的漸進線條。","usage":"執行 arc-line-v2 ~ v8 → 指定左點 → 指定右點 → 指定上點 → 自動畫出漸進線","level":4,"lt":"✅","ver":"20250315","author":"chengshunyi","video":"","fas":"fas/arc-line-v.fas"},{"no":67,"file":"ARC.LSP","cmd":"（無，副程式庫）","cat":"查詢","desc":"選取圓弧後，以 DXF 與 VLA 兩種方法取得圓心、起訖角、半徑及起訖點座標的範例。","usage":"載入後直接執行 → 選取圓弧 → 取得座標資料（無輸出）","level":2,"lt":"✅","ver":"2023-09-17 (檔案日期)","author":"—","video":"","fas":"fas/ARC.fas"},{"no":68,"file":"ArchiAreaCal-PLM.lsp","cmd":"AAC-PLM、ArchiAreaCal-PLM","cat":"面積/數量統計","desc":"建築面積計算精簡版：判定圓、矩形、平行四邊形、梯形、三角形，產生面積算式、編號並排版，DCL 設定單位、比例與起始編號。","usage":"執行 AAC-PLM → DCL 選單位/標註比例/起始編號/是否列算式 → 選取多段線 → 自動標註","level":7,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"MyCAD / ChengBar（推測）","video":"","fas":"fas/ArchiAreaCal-PLM.fas"},{"no":69,"file":"ArchiAreaCal.LSP","cmd":"AAC、ArchiAreaCal","cat":"面積/數量統計","desc":"建築面積計算完整版：連續選取多段線，判斷圓、矩形、平行四邊形、梯形、三角形等形狀，依取位規則產生面積算式、尺寸、編號與紅線虛線標示。","usage":"執行 AAC → DCL 設定單位/比例/起始編號 → 連續選取多段線 → 自動產生算式與標註","level":9,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"MyCAD / ChengBar（推測）","video":"","fas":"fas/ArchiAreaCal.fas"},{"no":70,"file":"area-box-ui.lsp","cmd":"Area-box-UI、areabox、areaang、areatra","cat":"面積/數量統計","desc":"面積計算 DCL 版：選擇矩形、三角形或梯形與繪圖單位，點選角點後自動畫輔助線並寫出面積計算式文字。","usage":"執行 Area-box-UI → DCL 選形狀/單位/比例 → 按執行 → 依提示點選角點 → 寫出面積","level":7,"lt":"✅","ver":"2025-08-09 (檔案日期)","author":"MyCAD","video":"","fas":"fas/area-box-ui.fas"},{"no":71,"file":"AREA-BOX.LSP","cmd":"areabox、areaang、areatra","cat":"面積/數量統計","desc":"以角點量取矩形、三角形、梯形面積並寫出算式文字，可設定起始編號，畫線於 dim-ind 圖層。","usage":"執行 areabox / areaang / areatra → 點選左上/左下/右上/右下角點 → 指定文字位置 → 寫出面積","level":6,"lt":"✅","ver":"83.4.10 / 84.4.24","author":"Cheng Shun Yi","video":"","fas":"fas/AREA-BOX.fas"},{"no":72,"file":"area-m-dy-to-p5.lsp","cmd":"area-m-dy-to-p5","cat":"修改","desc":"選取動態圖塊，將尺寸值依單位（cm 取 0/5 小數、mm 取尾數 0/5）調整為整數並更新欄位。","usage":"執行 area-m-dy-to-p5 → 確認目前單位 → 選取動態圖塊 → 自動取捨並更新 Field","level":5,"lt":"✅","ver":"20251228","author":"chengshunyi","video":"","fas":"fas/area-m-dy-to-p5.fas"},{"no":73,"file":"area-poly.lsp","cmd":"area-poly","cat":"面積/數量統計","desc":"選取多段線，以網格搜尋最大內切圓位置，將面積文字寫在該圓心處。","usage":"執行 area-poly → 選取 LWPOLYLINE → 自動算面積並寫在最大內切圓中心","level":7,"lt":"✅","ver":"19.01.2013","author":"Gian Paolo Cattaneo（Lee Mac 函式）","video":"","fas":"fas/area-poly.fas"},{"no":74,"file":"AREA-TO-TABL.lsp","cmd":"AREA-TO-TABLE","cat":"面積/數量統計","desc":"選取多段線，判斷為矩形或三角形（或詢問），計算長寬與面積算式並彙整填入 AutoCAD 表格。","usage":"執行 AREA-TO-TABLE → 選取多段線 → 指定表格插入點 → 自動建立面積表","level":7,"lt":"⚠️","ver":"rlx 11-mrt-2019","author":"rlx / Gile / Lee Mac（cadtutor 網路程式）","video":"","fas":"fas/AREA-TO-TABL.fas"},{"no":75,"file":"AREA_MEASURE-P.lsp","cmd":"AREA_MEASURE、AREA_RELABEL","cat":"面積/數量統計","desc":"區域面積量測與標註：點選區域自動 BOUNDARY 產生面積，DCL 設定單位、換算（m²/坪/才）、Field、編號、加總與列算式；RELABEL 可框選既有 PLINE 重標。","usage":"執行 AREA_MEASURE → DCL 設定 → 點選區域；或 AREA_RELABEL → 框選封閉 PLINE → 自動重標","level":8,"lt":"✅","ver":"2024 更新","author":"ChengBar (MyCAD)","video":"","fas":"fas/AREA_MEASURE-P.fas"},{"no":76,"file":"AREA_MEASURE.lsp","cmd":"AREA_MEASURE、AREA_RELABEL","cat":"面積/數量統計","desc":"區域面積量測與標註自動化：點選或框選區域產生面積標註，支援單位/坪/才換算、Field、編號、加總與列計算式，RELABEL 可批次重標。","usage":"執行 AREA_MEASURE → DCL 設定 → 點選區域；或 AREA_RELABEL → 框選 PLINE → 自動重標","level":8,"lt":"✅","ver":"2024 更新","author":"ChengBar (MyCAD)","video":"","fas":"fas/AREA_MEASURE.fas"},{"no":77,"file":"AreaBB.lsp","cmd":"AreaBB","cat":"面積/數量統計","desc":"選取圓或多段線，在重心位置以 Field 建立置中面積 MText，面積加千分位並顯示 m²。","usage":"執行 AreaBB → 選取圓/多段線 → 自動於重心寫出面積 Field","level":5,"lt":"✅","ver":"20231009","author":"BlackBox / Tom Beauford / chengshunyi","video":"","fas":"fas/AreaBB.fas"},{"no":78,"file":"AreaInfoReport.lsp","cmd":"AreaInfoReport","cat":"面積/數量統計","desc":"聚合線分析工具：選擇毫米/公分/公尺單位後，統計選取多段線面積與周長，圖面合計標註並輸出報表檔後開啟。","usage":"執行 AreaInfoReport → DCL 選繪圖單位 → 選取多段線 → 產生合計標註與報表","level":7,"lt":"✅","ver":"20250712","author":"ShunYi & Copilot","video":"","fas":"fas/AreaInfoReport.fas"},{"no":79,"file":"AreaLabel.lsp","cmd":"AT、AF","cat":"面積/數量統計","desc":"點選區域或物件標註面積，可用 Field 連動編號並輸出到 AutoCAD 表格或檔案（含 Excel 開啟），依 LTSCALE 調整文字大小。","usage":"執行 AT（或 AF）→ 選取區域或物件 → 指定標註位置 → 結束後選擇輸出表格/檔案","level":8,"lt":"⚠️","ver":"Version 1.9 / 20210815","author":"Lee Mac（chengshunyi 修改）","video":"","fas":"fas/AreaLabel.fas"},{"no":80,"file":"AreaPro-adv2.LSP","cmd":"AreaPro-adv2","cat":"面積/數量統計","desc":"AreaPro v3.2：自動辨識圓、弓形等幾何，寫出含公式的面積標註，以 DCL 設定單位、精度、比例、圖層，並產生分類彙整報表。","usage":"執行 AreaPro-adv2 → DCL 設定單位/精度/比例/面積類別 → 選取多段線 → 標註面積並可產生彙整報表","level":7,"lt":"✅","ver":"AreaPro v3_2 / 2026-03-22 (檔案日期)","author":"MyCAD","video":"","fas":"fas/AreaPro-adv2.fas"},{"no":81,"file":"AreaPro.LSP","cmd":"AreaPro","cat":"面積/數量統計","desc":"專業面積計算與表格生成：DCL 設定單位、小數、比例與圖層，多重選取區域後計算面積（可含坪數）並產生報表表格。","usage":"執行 AreaPro → DCL 設定單位/小數/比例/圖層 → 多選區域 → 指定表格位置 → 產生報表","level":6,"lt":"✅","ver":"2026-03-15 (檔案日期)","author":"MyCAD","video":"","fas":"fas/AreaPro.fas"},{"no":82,"file":"AreaPro_Adv.lsp","cmd":"AreaPro_Adv","cat":"面積/數量統計","desc":"AreaPro 整合版 v2.4：辨識幾何形狀並標註（文字偏移 0.8 倍字高），弓形加強，可依 AREA_TAG 圖塊產生分類彙整報表。","usage":"執行 AreaPro_Adv → DCL 設定繪圖單位/精度/比例 → 選取區域 → 標註並產生分類彙整報表","level":7,"lt":"✅","ver":"AreaPro_Integrated v2.4 / 2026-03-21 (檔案日期)","author":"MyCAD","video":"","fas":"fas/AreaPro_Adv.fas"},{"no":83,"file":"Areas2Attribute.lsp","cmd":"a2a","cat":"圖塊/屬性","desc":"選取一或多個物件，將其面積（或總和）以 Field 運算式寫入選定的屬性或屬性圖塊。","usage":"執行 a2a → 選取要取面積的物件 → 選取屬性或屬性圖塊（多屬性時以對話框選擇）→ 寫入 Field","level":6,"lt":"✅","ver":"20230513","author":"Lee Mac / chengshunyi","video":"","fas":"fas/Areas2Attribute.fas"},{"no":84,"file":"Areas2Field-text.lsp","cmd":"Areas2Field-text","cat":"面積/數量統計","desc":"選取多個物件，建立引用面積總和的 Field 文字（單行文字）；若點在表格儲存格內則填入該儲存格。","usage":"執行 Areas2Field-text → 選取物件 → 指定文字位置或表格儲存格 → 自動建立面積 Field","level":5,"lt":"✅","ver":"20220716更新","author":"Lee Mac / chengshunyi","video":"","fas":"fas/Areas2Field-text.fas"},{"no":85,"file":"Areas2Field-TW.lsp","cmd":"a2f-tw","cat":"面積/數量統計","desc":"面積 Field 文字台灣版：選取物件建立面積 Field，並可選繪圖單位、平方公尺、台灣坪與單位係數，DCL 設定標註圖層與文字樣式。","usage":"執行 a2f-tw → DCL 設定單位/圖層/字高/樣式/坪 → 選取物件 → 指定位置或表格儲存格 → 建立面積 Field","level":9,"lt":"✅","ver":"2024-10-06 (檔案日期)","author":"Lee Mac / chengshunyi (MyCAD)","video":"","fas":"fas/Areas2Field-TW.fas"},{"no":86,"file":"AreaText.lsp","cmd":"AML、AT-AP、AT-mtext、ATC、ATM、AT1、AT2、AT3、AT3T、AT","cat":"面積/數量統計","desc":"以 Field 在物件上建立面積文字，AT 為一般，ATC 置於形心，ATM 置於邊界框中心，並支援不同圖塊/樣式與 ZWCAD 格式。","usage":"執行 AT / ATC / ATM（或 AT1~AT3）→ 選取物件 → 自動寫入面積 Field","level":8,"lt":"✅","ver":"ver 4.0 / 2018-11-11","author":"Jimmy Bergmark（JTB World）/ chengshunyi","video":"","fas":"fas/AreaText.fas"},{"no":87,"file":"AreaToML.LSP","cmd":"AreaToML","cat":"面積/數量統計","desc":"多選聚合線後選多重引線，建立面積加總或相減的標註（Field 或靜態文字），DCL 設定單位、前綴與編號。","usage":"執行 AreaToML → DCL 設定單位/前綴/編號 → 選取多條聚合線 → 選取 MLeader → 產生面積標註","level":7,"lt":"✅","ver":"2026-03-26 (檔案日期)","author":"MyCAD","video":"","fas":"fas/AreaToML.fas"},{"no":88,"file":"arpoly.LSP","cmd":"text-area-poly","cat":"面積/數量統計","desc":"選取多段線，在最大內切圓中心標註面積文字（pline area tag）。","usage":"執行 text-area-poly → 選取 LWPOLYLINE → 自動寫入面積文字","level":7,"lt":"✅","ver":"20230520","author":"Gian Paolo Cattaneo / chengshunyi","video":"","fas":"fas/arpoly.fas"},{"no":89,"file":"array-R.lsp","cmd":"array-R-V、array-R-H、array-R-HV、arrayS-R-V、arrayS-R-H、arrayS-R-HV","cat":"對齊/排列","desc":"選取物件取得範圍後做矩形陣列：水平、垂直或水平加垂直，arrayS 系列為另一種間距版本。","usage":"執行 array-R-H / V / HV → 選取物件 → 輸入數量與間距 → 自動陣列","level":5,"lt":"✅","ver":"20250503","author":"chengshunyi","video":"","fas":"fas/array-R.fas"},{"no":90,"file":"ARROW.LSP","cmd":"arr-up、arr-dn、arr-up-dn","cat":"繪圖","desc":"點 A、點 B 依階寬畫出向上、向下或上下階梯方向箭頭符號（含線、圓與圖塊）。","usage":"執行 arr-up / arr-dn / arr-up-dn → 指定 A 點 → 指定 B 點 → 輸入階寬 → 自動繪製","level":4,"lt":"✅","ver":"90.09.05","author":"—","video":"","fas":"fas/ARROW.fas"},{"no":91,"file":"arrow_on_polyline.lsp","cmd":"arrow_on_polyline","cat":"繪圖","desc":"沿多段線依間距與比例插入箭頭圖塊，用於排水方向箭頭。","usage":"執行 arrow_on_polyline → 輸入箭頭間距 → 選取多段線 → 自動沿線插入箭頭","level":5,"lt":"✅","ver":"20250614","author":"chengshunyi","video":"","fas":"fas/arrow_on_polyline.fas"},{"no":92,"file":"ASCTEXT.LSP","cmd":"ASCTEXT","cat":"轉檔/匯出入","desc":"將 ASCII 文字檔匯入圖面為單行文字，可設定對齊方式、行距、起始行、讀取行數與大小寫轉換。","usage":"執行 ASCTEXT → 輸入檔名 → 指定起點與對齊 → 設定高度/旋轉 → 自動寫入文字","level":6,"lt":"✅","ver":"4 July 1986","author":"Simon Jones（Autodesk Ltd, London）","video":"","fas":"fas/ASCTEXT.fas"},{"no":93,"file":"ASQCHR.lsp","cmd":"ASQCHR","cat":"圖塊/屬性","desc":"依序點選圖塊，將屬性依字母順序（A、B、C…）自動編號。","usage":"執行 ASQCHR → 輸入起始字母 → 依序點選圖塊 → 屬性自動寫入字母","level":3,"lt":"✅","ver":"202003","author":"Cheng Bar","video":"","fas":"fas/ASQCHR.fas"},{"no":94,"file":"ASQNUM-w.lsp","cmd":"ASQNUM-w","cat":"圖塊/屬性","desc":"批次選取圖塊，先依 Y 分行門檻再依 X 由左到右排序，依前置碼、起始號與位數寫入第一個屬性編號。","usage":"執行 ASQNUM-w → 輸入前置碼/起始編號/位數/Y 分行門檻 → 窗選圖塊 → 自動排序編號","level":6,"lt":"✅","ver":"2025-11-20 (檔案日期)","author":"MyCAD","video":"","fas":"fas/ASQNUM-w.fas"},{"no":95,"file":"ASQNUM.lsp","cmd":"ASQNUM","cat":"圖塊/屬性","desc":"依序點選圖塊，將屬性以前置碼加流水號（不足 10 補 0）自動編號。","usage":"執行 ASQNUM → 輸入前置碼 → 輸入起始編號 → 依序點選圖塊 → 自動寫入","level":3,"lt":"✅","ver":"202003","author":"Cheng Bar","video":"","fas":"fas/ASQNUM.fas"},{"no":96,"file":"Assembly_Table.lsp","cmd":"Assembly_Table","cat":"面積/數量統計","desc":"選取屬性圖塊，統計各項目順序、數量與說明並建立零件清單表格。","usage":"執行 Assembly_Table → 選取屬性圖塊 → 指定表格插入點 → 自動建立數量統計表","level":6,"lt":"✅","ver":"20231010","author":"Tharwat Al Choufi / chengshunyi","video":"","fas":"fas/Assembly_Table.fas"},{"no":97,"file":"AT-Auto.LSP","cmd":"AT-Auto、AT1、AT2、AT3","cat":"面積/數量統計","desc":"AreaText v9.2 專業版：單一 DCL 設定偏移量與標註模式，對圓、多段線、填充等標註面積/周長 Field 動態文字或圖塊標籤，相容 ZWCAD。","usage":"執行 AT-Auto → DCL 選擇標註模式與偏移量 → 選取物件 → 自動標註面積/周長","level":8,"lt":"⚠️","ver":"v9.2 / 2026-10-16","author":"ChengBar (MyCAD)","video":"","fas":"fas/AT-Auto.fas"},{"no":98,"file":"ATL.lsp","cmd":"ATL","cat":"對齊/排列","desc":"文字排列對齊參考線工具：將 TEXT/MTEXT 沿線、弧或圓以等間距排列，支援多種對齊點、水平保持與指定圖面起迄點，頂端顯示 Slide 預覽。","usage":"執行 ATL → DCL 選模式/對齊點/間距 → 選取參考線或指定起迄點 → 選取文字 → 自動排列","level":8,"lt":"✅","ver":"V4.4 / 2026-10-01","author":"ChengBar (MyCAD)","video":"","fas":"fas/ATL.fas"},{"no":99,"file":"ATT-2-TABLE-Test.lsp","cmd":"ATT-2-TABLE-Test","cat":"圖塊/屬性","desc":"選取圖塊（預設 TitleBar）將 DRAWINGNO.、PARTNAME、MATERIAL 等屬性寫入 AutoCAD 表格。","usage":"執行 ATT-2-TABLE-Test → 選取圖塊 → 輸入字高 → 指定表格基準點 → 建立表格","level":6,"lt":"✅","ver":"20241212","author":"Tharwat Al Shoufi（2015）/ chengshunyi","video":"","fas":"fas/ATT-2-TABLE-Test.fas"},{"no":100,"file":"Att-V.LSP","cmd":"Att-V","cat":"圖塊/屬性","desc":"點選屬性圖塊或多重引線，於清單多選要隱藏的屬性，修改圖塊定義並同步更新圖面所有一般圖塊與 MLeader。","usage":"執行 Att-V → 點選圖塊或 MLeader → DCL 多選要隱藏的屬性 → 確定後全圖同步","level":7,"lt":"✅","ver":"20260308","author":"MyCAD","video":"","fas":"fas/Att-V.fas"},{"no":101,"file":"att2cell.LSP","cmd":"att2cell-f、att2cell","cat":"圖塊/屬性","desc":"點選屬性後再點選表格儲存格，將屬性值貼入儲存格；att2cell-f 版本以 Field 連動屬性，屬性變更時表格自動更新。","usage":"執行 att2cell 或 att2cell-f → 點選屬性 → 點選表格儲存格 → 重複，Enter 結束","level":6,"lt":"✅","ver":"20220202","author":"AlanH（協助：Lee Mac、Grrr）/ chengshunyi","video":"","fas":"fas/att2cell.fas"},{"no":102,"file":"attable_CDA_A.lsp","cmd":"attable_CDA_A","cat":"圖塊/屬性","desc":"擷取放樣座標屬性圖塊（CDN-A）資料，依數值排序後以 Field 連動文字網格、原生 Table 或 CSV 輸出，DCL 設定欄寬與標題。","usage":"執行 attable_CDA_A → DCL 設定圖塊名/標題/輸出模式 → 選取屬性圖塊 → 指定位置 → 產生座標表","level":8,"lt":"⚠️","ver":"2026-09-14 (檔案日期)","author":"ChengBar (MyCAD Studio)","video":"","fas":"fas/attable_CDA_A.fas"},{"no":103,"file":"attable_CDA_A_W.lsp","cmd":"attable_CDA_W","cat":"圖塊/屬性","desc":"將專屬圖塊 CDN-A 的屬性座標依編號排序後，以 Field 連動建立放樣座標表格。","usage":"執行 attable_CDA_W → 選取 CDN-A 圖塊 → 指定表格插入點 → 自動建立連動表格","level":7,"lt":"✅","ver":"2019.11.01 / 20220716更新","author":"Cheng BAR（GET_ATTS 為 Bill Kramer）","video":"","fas":"fas/attable_CDA_A_W.fas"},{"no":104,"file":"AttChSwap.lsp","cmd":"AttChSwap","cat":"圖塊/屬性","desc":"對全圖所有含屬性圖塊，將 D-NUM 屬性值只保留前 7 個字元。","usage":"執行 AttChSwap（載入時也會自動執行）→ 全圖自動處理","level":2,"lt":"✅","ver":"20220404","author":"—","video":"","fas":"fas/AttChSwap.fas"},{"no":105,"file":"AttDefToText.lsp","cmd":"AttDefToText、AttDefToMText","cat":"圖塊/屬性","desc":"將屬性定義（ATTDEF）轉換成單行文字或多行文字物件。","usage":"執行 AttDefToText 或 AttDefToMText → 選取屬性定義 → 自動轉換","level":4,"lt":"✅","ver":"Created 2008-03-31","author":"Jimmy Bergmark（JTB World）","video":"","fas":"fas/AttDefToText.fas"},{"no":106,"file":"attHW.lsp","cmd":"attHW","cat":"圖塊/屬性","desc":"選取屬性後，可手動輸入字高與寬度比例，或選一個文字複製其性質（MatchProp）。","usage":"執行 attHW → 選取屬性 → 選 Yes（手動輸入高/寬）或 No（選取參考文字複製性質）","level":3,"lt":"✅","ver":"20220522","author":"Cheng Bar","video":"","fas":"fas/attHW.fas"},{"no":107,"file":"attman.LSP","cmd":"attman","cat":"圖塊/屬性","desc":"選取屬性圖塊後以 DCL 列表顯示屬性清單，逐項編輯屬性值。","usage":"執行 attman → 選取圖塊 → DCL 選屬性並編輯 → 確定寫回","level":6,"lt":"✅","ver":"20220101","author":"Cheng BAR","video":"","fas":"fas/attman.fas"},{"no":108,"file":"AttModSuite.lsp","cmd":"mvAtt、roAtt、roAtt-0、roAtt-blk-ang180、roAtt-blk-ang0、roAtt-blk-ang0180、edAtt","cat":"圖塊/屬性","desc":"屬性修改套件：批次移動、旋轉屬性（含依圖塊角度轉 0/180 度）、以 DCL 同時編輯多項屬性內容、字高等性質。","usage":"執行 mvAtt / roAtt / edAtt 等 → 選屬性標籤 → 選取圖塊 → 指定位移/角度或在 DCL 修改 → 套用","level":8,"lt":"⚠️","ver":"20241215","author":"Lee Mac / chengshunyi","video":"","fas":"fas/AttModSuite.fas"},{"no":109,"file":"ATTR_EXPORT-dy.lsp","cmd":"ATTR_EXPORT-dy","cat":"轉檔/匯出入","desc":"選取屬性圖塊（支援動態圖塊 EffectiveName）為樣板，DCL 調整欄位順序後匯出 CSV 或畫成 AutoCAD 表格。","usage":"執行 ATTR_EXPORT-dy → 選樣板圖塊 → DCL 排序/刪除欄位、選自動過濾 → 輸出 CSV 或表格","level":7,"lt":"✅","ver":"20220716更新 / 2026-01-21 (檔案日期)","author":"MyCAD","video":"","fas":"fas/ATTR_EXPORT-dy.fas"},{"no":110,"file":"ATTR_EXPORT.lsp","cmd":"ATTR_EXPORT","cat":"轉檔/匯出入","desc":"選取屬性圖塊作為樣板，DCL 自訂欄位順序，窗選或全圖自動過濾後匯出 CSV 或繪製自動欄寬的表格。","usage":"執行 ATTR_EXPORT → 選樣板圖塊 → DCL 調整欄位/字高/自動過濾 → 匯出 CSV 或表格","level":7,"lt":"✅","ver":"20220716更新 / 2026-01-19 (檔案日期)","author":"MyCAD","video":"","fas":"fas/ATTR_EXPORT.fas"},{"no":111,"file":"ATTRIB2TABLE.LSP","cmd":"ATTRIB-TABLE","cat":"圖塊/屬性","desc":"選取含屬性圖塊，指定表格位置與大小，將屬性資料寫入 AutoCAD 表格，含調整列高欄寬函式。","usage":"執行 ATTRIB-TABLE → 選取屬性圖塊 → 指定表格插入點與大小 → 自動填表","level":6,"lt":"✅","ver":"2026-10-18 (檔案日期)","author":"Reinaldo N. Togores（《AutoCAD expert's Visual LISP》Ch.24）","video":"","fas":""},{"no":112,"file":"AttributeColour.lsp","cmd":"AttCol","cat":"圖塊/屬性","desc":"選取屬性圖塊後，以 DCL 勾選特定屬性標籤並統一變更其顏色。","usage":"執行 AttCol → 選取屬性圖塊 → DCL 選標籤與顏色 → 確定套用","level":6,"lt":"✅","ver":"Version 1.0 / 24-02-2011","author":"Lee Mac","video":"","fas":"fas/AttributeColour.fas"},{"no":113,"file":"AttributeHeight.lsp","cmd":"AttHei","cat":"圖塊/屬性","desc":"選取屬性圖塊後，以 DCL 勾選特定屬性標籤並統一變更其字高。","usage":"執行 AttHei → 選取屬性圖塊 → DCL 選標籤並輸入字高 → 確定套用","level":6,"lt":"✅","ver":"Version 1.0 / 24-02-2011","author":"Lee Mac","video":"","fas":"fas/AttributeHeight.fas"},{"no":114,"file":"Atts-table.lsp","cmd":"atts-table","cat":"面積/數量統計","desc":"依圖塊名稱選取屬性圖塊，依指定屬性遞增排序製作清單表，並依另一屬性分類加總產生統計表。","usage":"執行 atts-table → 點選排序屬性與加總屬性 → 輸入圖塊名稱 → 指定清單表與統計表位置","level":7,"lt":"✅","ver":"Version 1.0 / 20230527","author":"Cheng BAR","video":"","fas":"fas/atts-table.fas"},{"no":115,"file":"atts2table.lsp","cmd":"atts2table","cat":"圖塊/屬性","desc":"選取屬性圖塊與既有表格第一格，自動補足列/欄並以 Field 填入各屬性值，字高預設 0.35cm。","usage":"執行 atts2table → 選取圖塊 → 點選表格第一個儲存格 → 自動新增列欄並填入","level":6,"lt":"✅","ver":"20241210","author":"chengshunyi","video":"","fas":"fas/atts2table.fas"},{"no":116,"file":"AuditoriumSeating.lsp","cmd":"AuditoriumSeating","cat":"對齊/排列","desc":"表演廳座位排列：DCL 設定座椅尺寸、中心距、排數、偏移與起/中/終對齊與交錯，點選偏移側後沿路徑放置座椅圖塊。","usage":"執行 AuditoriumSeating → DCL 設定座椅/排列參數與對齊模式 → 選取排列路徑 → 點選偏移側 → 自動排座位","level":7,"lt":"✅","ver":"2026-05-17 (檔案日期)","author":"MyCAD","video":"","fas":"fas/AuditoriumSeating.fas"},{"no":117,"file":"author.lsp","cmd":"author","cat":"系統/授權","desc":"授權檢查模組（舊版）：讀取 132author.txt 授權檔，依年度判斷是否過期。","usage":"由其他程式載入呼叫，無需手動操作","level":3,"lt":"✅","ver":"2024-01-01 (檔案日期)","author":"MyCAD","video":"","fas":""},{"no":118,"file":"author_ymd.lsp","cmd":"author_ymd","cat":"系統/授權","desc":"授權檢查模組：讀取 MyAuthor.txt，依年月日判斷 MyCAD 授權是否有效，並提示授權年度。","usage":"由各程式載入呼叫 checkauthor，無需手動操作","level":4,"lt":"✅","ver":"2024-08-11 (檔案日期)","author":"MyCAD / chengshunyi","video":"","fas":""},{"no":119,"file":"author_ymd_t.lsp","cmd":"author_ymd_t","cat":"系統/授權","desc":"授權檢查模組試用版：除授權檔檢查外，記錄試用次數（預設 49 次）於 AppData，超過後提示。","usage":"由各程式載入呼叫，無需手動操作","level":5,"lt":"✅","ver":"20231206","author":"chengshunyi","video":"","fas":""},{"no":120,"file":"AUTOAREA-GPL.lsp","cmd":"AUTOAREA-GPL","cat":"繪圖","desc":"專業分區工具：DCL 選擇圖層、設定多段線寬度與是否自動群組，選取外框 Pline 後合併、改圖層並編群組。","usage":"執行 AUTOAREA-GPL → DCL 選圖層/寬度/群組 → 選取外框 Pline → 自動處理","level":6,"lt":"✅","ver":"3.0 / 2026-05-06 (檔案日期)","author":"Gemini AI 協作","video":"https://youtu.be/D9pdvnLmfIk","fas":"fas/AUTOAREA-GPL.fas"},{"no":121,"file":"AUTOCAD-COLOR256.lsp","cmd":"AUTOCAD-COLOR256、test-hatch","cat":"其他","desc":"繪製 AutoCAD 1~255 色索引色票（多段線、文字與實心填充），test-hatch 為填充類型測試。","usage":"執行 AUTOCAD-COLOR256 → 指定基點 → 自動畫出色票；test-hatch → 選取填充 → 顯示類型","level":5,"lt":"✅","ver":"20240306","author":"ElpanovEvgeniy / chengshunyi","video":"","fas":"fas/AUTOCAD-COLOR256.fas"},{"no":122,"file":"AutoDB(切線標尺寸).lsp","cmd":"AutoDB","cat":"標註","desc":"切線標尺寸：點兩點畫線並建立線性標註，再接續基線標註，操作後以 UNDO 群組可一次復原。","usage":"執行 AutoDB → 指定第一點與第二點 → 依序點選下一尺寸點 → Enter 結束","level":2,"lt":"✅","ver":"2023-01-15 (檔案日期)","author":"—","video":"","fas":"fas/AutoDB(切線標尺寸).fas"},{"no":123,"file":"AutoIncr.LSP","cmd":"PurgeGroups、AutoIncr、EditIncr、RenumIncr","cat":"圖塊/屬性","desc":"屬性/文字自動遞增編號系統，支援數字、字母、羅馬數字、進位制格式，可編輯與重新編號群組，並清理無效群組。","usage":"執行 AutoIncr → DCL 設定格式/起始值 → 逐一點選物件自動遞增；EditIncr 編輯、RenumIncr 重編","level":9,"lt":"✅","ver":"v0.2 / 2010-07-10","author":"Irné Barnard（Caddons，GPL v3）","video":"","fas":"fas/AutoIncr.fas"},{"no":124,"file":"AutoLabelAttributes.lsp","cmd":"autolabelon、autolabeloff","cat":"圖塊/屬性","desc":"以物件與命令 Reactor 監控符合名稱的屬性圖塊，新增、複製或刪除時自動重新編號指定屬性（如 CARNUM）。","usage":"執行 autolabelon 開啟自動編號 → 之後增刪複製圖塊自動重編；autolabeloff 關閉","level":8,"lt":"✅","ver":"2021-07-27 (檔案日期)","author":"Lee Mac","video":"","fas":"fas/AutoLabelAttributes.fas"},{"no":125,"file":"AutoNoMleaderVal.lsp","cmd":"AutoNoMleaderVal、ReviewMleader、FindMleader","cat":"圖塊/屬性","desc":"多重引線圖塊屬性自動編號工具：DCL 設定屬性 Tag、前綴、位數、換列與同列排序方向，可檢視與尋找已編號的 MLeader。","usage":"執行 AutoNoMleaderVal → DCL 設定 Tag/前綴/位數/排序 → 選取 MLeader → 自動編號","level":8,"lt":"✅","ver":"2026-07-19 (檔案日期)","author":"MyCAD","video":"","fas":"fas/AutoNoMleaderVal.fas"},{"no":126,"file":"AUTONUM2D.lsp","cmd":"AUTONUM2D","cat":"圖塊/屬性","desc":"依序點選圖塊，將第一個屬性自動寫入兩位數遞增編號（01、02、03），並記憶下一個編號。","usage":"執行 AUTONUM2D → 輸入起始編號 → 選取圖塊 → 自動編號","level":5,"lt":"✅","ver":"2025-11-20 (檔案日期)","author":"—","video":"","fas":"fas/AUTONUM2D.fas"},{"no":127,"file":"AutoNumberMLEADER.lsp","cmd":"AutoNumberMLEADER","cat":"標註","desc":"選取全圖多重引線，依由上而下、由左而右排序後自動編號並更新文字，可選擇是否覆蓋原文字。","usage":"執行 AutoNumberMLEADER → 選擇是否覆蓋原文字 [Y/N] → 自動排序編號","level":6,"lt":"✅","ver":"2025-08-06 (檔案日期)","author":"—","video":"","fas":"fas/AutoNumberMLEADER.fas"},{"no":128,"file":"AUTOPL1S.LSP","cmd":"autopl1s","cat":"出圖/列印","desc":"A1 圖幅批次出圖：DCL 列出圖檔並選取排序，自動寫出 SCRIPT 檔批次開圖列印。","usage":"執行 autopl1s → DCL 選取圖檔清單 → 確定後產生並執行出圖 script","level":6,"lt":"✅","ver":"84.7.12","author":"—","video":"","fas":"fas/AUTOPL1S.fas"},{"no":129,"file":"AUTOPL3S.LSP","cmd":"autopl3s","cat":"出圖/列印","desc":"A3 圖幅批次出圖：DCL 列出圖檔並選取排序，自動寫出 SCRIPT 檔批次開圖列印。","usage":"執行 autopl3s → DCL 選取圖檔清單 → 確定後產生並執行出圖 script","level":6,"lt":"✅","ver":"84.7.12","author":"—","video":"","fas":"fas/AUTOPL3S.fas"},{"no":130,"file":"autoSetLayoutFinal.lsp","cmd":"autoSetLayoutFinal","cat":"出圖/列印","desc":"輸入新配置名稱，複製目前配置並移到最後，切換後解鎖視埠、縮放到指定範圍再鎖定。","usage":"執行 autoSetLayoutFinal → 輸入配置名稱 → 自動複製配置、設定視埠並鎖定","level":5,"lt":"✅","ver":"2025-12-13 (檔案日期)","author":"—","video":"","fas":"fas/autoSetLayoutFinal.fas"},{"no":131,"file":"AvgZ-ui.lsp","cmd":"AvgZ-ui","cat":"查詢","desc":"測量圖平均高程計算 DCL 版：設定單位、比例、字高、小數位後，框選範圍內 TEXT/MTEXT/圖塊 Z 值計算平均並寫出明細。","usage":"執行 AvgZ-ui → DCL 設定單位/比例/字高/小數位 → 點選樣本與 Pline 範圍 → 寫出平均結果","level":7,"lt":"✅","ver":"20260207","author":"MyCAD","video":"","fas":"fas/AvgZ-ui.fas"},{"no":132,"file":"AvgZ.LSP","cmd":"AvgZ","cat":"查詢","desc":"測量圖平均高程計算命令列版：點選樣本取圖層，以 Pline 範圍選取高程文字，四捨五入後計算平均並寫出結果與明細。","usage":"執行 AvgZ → 輸入單位/比例/小數位 → 點選樣本 → 點選 Pline 範圍 → 寫出平均值","level":6,"lt":"✅","ver":"20260207","author":"MyCAD","video":"","fas":"fas/AvgZ.fas"},{"no":133,"file":"B2C.LSP","cmd":"B2C","cat":"對齊/排列","desc":"圖塊移至選取物件中心：DCL 選 2D 或 3D 對齊，連續選來源圖塊後以目標邊界盒中心（或兩點中點）定位。","usage":"執行 B2C → DCL 選 2D/3D → 選取來源圖塊 → 選取目標物件或指定兩點 → 自動對齊，Enter 結束","level":7,"lt":"✅","ver":"2026","author":"ChengBar (MyCAD)","video":"","fas":"fas/B2C.fas"},{"no":134,"file":"B2WG.LSP","cmd":"B2WG","cat":"修改","desc":"將指定圖層的 LINE、LWPOLYLINE 顏色改為真彩白（255,255,255），常用於黑底轉白底。","usage":"執行 B2WG → 自動依圖層清單選取線與多段線並改色","level":2,"lt":"✅","ver":"20240608","author":"—","video":"","fas":"fas/B2WG.fas"},{"no":135,"file":"backgroundchanger.lsp","cmd":"BGGrey、BGWhite、BGBlack、bgt","cat":"系統/授權","desc":"一鍵切換模型/配置空間背景為灰、白、黑色，bgt 在黑白間切換。","usage":"執行 BGGrey / BGWhite / BGBlack → 背景立即變色；bgt 切換黑白","level":4,"lt":"✅","ver":"ver 1.0 / 2003-07-01","author":"Jimmy Bergmark（JTB World）","video":"","fas":""},{"no":136,"file":"basepurge.lsp","cmd":"basepurge","cat":"圖面管理","desc":"批次清底圖：選目錄後依檔案清單產生 SCR 草稿檔，內容含拆離外參、purge 與 zoom e 等，用於一批 DWG 清理。","usage":"執行 basepurge → 選擇輸出目錄 → Enter 開始產生 SCR → 以 SCRIPT 執行","level":8,"lt":"❌","ver":"2008.06.18 / 20250512","author":"Cheng Shun-Yi","video":"","fas":"fas/basepurge.fas"},{"no":137,"file":"basepurgeoff.LSP","cmd":"basepurgeoff","cat":"圖面管理","desc":"批次清底圖（含關閉圖層功能）：選目錄後產生 SCR，包含 purge、關圖層、另存 2007 格式並關閉。","usage":"執行 basepurgeoff → 選擇目錄 → Enter 產生 SCR → 以 SCRIPT 執行","level":8,"lt":"❌","ver":"202501208","author":"Cheng Shun-Yi","video":"","fas":"fas/basepurgeoff.fas"},{"no":138,"file":"Bat-Recover-audit.lsp","cmd":"Bat-Recover-audit","cat":"圖面管理","desc":"批次修復圖檔：選目錄後逐一開啟 DWG 執行 RECOVER 與 AUDIT 再關閉。","usage":"執行 Bat-Recover-audit（目前圖須先存檔）→ 選擇目錄 → 自動逐檔處理","level":5,"lt":"❌","ver":"20240831","author":"chengshunyi","video":"","fas":"fas/Bat-Recover-audit.fas"},{"no":139,"file":"bat-titleblk-layout.lsp","cmd":"bat-titleblk-layout","cat":"出圖/列印","desc":"逐一切換配置，將圖框外部參考附加到各配置並縮放，用於批次加圖框。","usage":"執行 bat-titleblk-layout → 選取圖框 xref 檔 → 自動逐配置附加","level":3,"lt":"✅","ver":"2021-11-17 (檔案日期)","author":"—","video":"","fas":"fas/bat-titleblk-layout.fas"},{"no":140,"file":"BATATT.lsp","cmd":"BATATT、BATTMOD","cat":"圖塊/屬性","desc":"批次修改圖塊屬性：DCL（中英雙語、動態示意圖）三步驟選圖塊與屬性、模糊排序、起始號與位數，自動依位置排序編號。","usage":"執行 BATATT → DCL Step1 選圖塊與屬性 → Step2 選範圍 → Step3 設排序/編號 → 確定套用","level":9,"lt":"✅","ver":"2026-09-29 (檔案日期)","author":"MyCAD","video":"","fas":"fas/BATATT.fas"},{"no":141,"file":"batch-make-slide.LSP","cmd":"batch-make-slide","cat":"轉檔/匯出入","desc":"批次製作幻燈片：選目錄後產生 SCR，逐檔開啟 DWG、縮放置中並以 MSLIDE 輸出 .sld。","usage":"執行 batch-make-slide → 選擇目錄 → Enter 產生 SCR → 以 SCRIPT 執行","level":7,"lt":"❌","ver":"20220716更新 / 2024-11-14 (檔案日期)","author":"Cheng Shun-Yi","video":"","fas":"fas/batch-make-slide.fas"},{"no":142,"file":"BatchExportLayers.LSP","cmd":"BatchExportLayers","cat":"轉檔/匯出入","desc":"批次圖層資訊匯出：以 ObjectDBX 背景讀取資料夾內所有 DWG，將不重複的圖層名稱與顏色、線型、開關等匯到 Excel 並依顏色填色。","usage":"執行 BatchExportLayers → DCL 勾選匯出屬性 → 選擇 DWG 資料夾 → 自動輸出至 Excel","level":8,"lt":"❌","ver":"v23.6 / 2026-03-10 (檔案日期)","author":"MyCAD","video":"","fas":"fas/BatchExportLayers.fas"},{"no":143,"file":"BatchImportDXF.lsp","cmd":"BatchImportDXF","cat":"轉檔/匯出入","desc":"選擇資料夾後，將其中所有 DXF 檔以 -INSERT 依序匯入目前圖面原點。","usage":"執行 BatchImportDXF → 選擇 DXF 資料夾 → 自動逐檔匯入","level":3,"lt":"❌","ver":"2026-03-30 (檔案日期)","author":"—","video":"","fas":"fas/BatchImportDXF.fas"},{"no":144,"file":"BatchLayerFreeze.lsp","cmd":"BLAYFRZ、BatchLayerFreeze","cat":"圖層","desc":"不開圖檔，以 ObjectDBX 批次凍結資料夾內所有 DWG 中符合萬用字元名稱的圖層。","usage":"執行 BLAYFRZ → 選擇資料夾 → 輸入圖層名稱（萬用字元）→ 自動批次凍結並存檔","level":8,"lt":"❌","ver":"20250524","author":"chengshunyi","video":"","fas":"fas/BatchLayerFreeze.fas"},{"no":145,"file":"BatchPurge.lsp","cmd":"BatchPurge","cat":"圖面管理","desc":"批次清理指定目錄（可含次目錄）下 DWG 的未使用項目，以 ObjectDBX 不開檔處理，DCL 設定目錄與選項。","usage":"執行 BatchPurge → DCL 選目錄與是否含次目錄 → 確定後批次 Purge","level":8,"lt":"❌","ver":"v2.0 / 2026-03-30","author":"ChengBar (MyCAD)","video":"","fas":"fas/BatchPurge.fas"},{"no":146,"file":"BatchReplaceWithBlock.LSP","cmd":"BatchReplaceWithBlock、CopyAttrToMLeader","cat":"圖塊/屬性","desc":"以選定來源圖塊與目標 MLeader 為樣板，將全圖同名圖塊替換為含圖塊的多重引線並同步屬性值，可選擇刪除舊圖塊。","usage":"執行 BatchReplaceWithBlock → 選來源圖塊 → 選目標 MLeader → 自動搜尋替換；CopyAttrToMLeader 單次複製屬性","level":7,"lt":"✅","ver":"20220716更新 / 2026-02-15 (檔案日期)","author":"MyCAD","video":"","fas":"fas/BatchReplaceWithBlock.fas"},{"no":147,"file":"BatchReplaceXref.lsp","cmd":"BatchReplaceXref","cat":"圖面管理","desc":"DCL 輸入舊/新關鍵字，從外參檔名右側搜尋並批次替換外部參考路徑，找不到檔案自動跳過，設定存檔記憶。","usage":"執行 BatchReplaceXref → DCL 輸入搜尋與替換關鍵字 → 確定 → 自動替換所有外參","level":6,"lt":"✅","ver":"2026-03-22 (檔案日期)","author":"MyCAD","video":"","fas":"fas/BatchReplaceXref.fas"},{"no":148,"file":"BatchSetPus.lsp","cmd":"BatchSetPus","cat":"圖面管理","desc":"選擇目錄後，批次對所有 DWG 寫入單位與比例設定（SET-PUS），逐檔錯誤隔離、可備份原檔、略過已開啟圖檔。","usage":"執行 BatchSetPus → DCL 設定目錄/單位/圖紙/比例/備份 → 確定後批次寫入","level":8,"lt":"⚠️","ver":"v1.0.2 / 2026-10-29 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/BatchSetPus.fas"},{"no":149,"file":"bb_inc.lsp","cmd":"bb_inc、exp14","cat":"標註","desc":"序號球：DCL 設定圖層、前置文字、起始值與字高/直徑控制，點選位置繪製圓球與序號文字並自動遞增。","usage":"執行 bb_inc → DCL 設定圖層/前置字/字高 → 連續點選位置 → 畫序號球與編號","level":7,"lt":"✅","ver":"20241006","author":"chengshunyi","video":"","fas":"fas/bb_inc.fas"},{"no":150,"file":"BBdim.lsp","cmd":"BBdim","cat":"標註","desc":"選取圖塊後考慮其旋轉角，計算旋轉邊界框，在圖塊左側與上方標註尺寸。","usage":"執行 BBdim → 輸入標註比例係數 → 選取圖塊 → 自動標註左側與上方尺寸","level":6,"lt":"✅","ver":"20251225","author":"MyCAD","video":"https://youtu.be/d72SDBKgIBI","fas":"fas/BBdim.fas"},{"no":151,"file":"bbpoly&hatch.lsp","cmd":"bbpoly&hatch","cat":"繪圖","desc":"對選取的線與多段線所圍出的每個封閉區域批次產生多段線邊界，並可為結果多段線建立實心填充。","usage":"執行 bbpoly&hatch → 選取線與多段線 → 自動產生各區域邊界與填充","level":7,"lt":"✅","ver":"20220716更新 / 2023-04-02 (檔案日期)","author":"Lee Mac（Batch BPoly）/ Stefan M. / M.R. / ElpanovEvgeniy","video":"","fas":"fas/bbpoly&hatch.fas"},{"no":152,"file":"bd2layouts-TG.LSP","cmd":"bd2layouts-TG、GetLineFullData、SETVPNAME","cat":"出圖/列印","desc":"選取圖框圖塊，依各圖框位置與圖名屬性自動複製建立配置、設定視埠縮放並鎖定，支援 TG、TSMC、CH 等多種專案圖框。","usage":"執行 bd2layouts-TG → 選取圖框圖塊（A1-BORDER-TG 等）→ 自動建立配置與視埠並命名","level":8,"lt":"✅","ver":"2026-03-28 (檔案日期)","author":"chengshunyi / MyCAD","video":"","fas":"fas/bd2layouts-TG.fas"},{"no":153,"file":"bd2layouts.lsp","cmd":"bd2layouts、GetLineFullData","cat":"出圖/列印","desc":"依選取的 A3 圖框圖塊自動建立對應配置並設定視埠，圖框依位置排序，已存在配置則切換。","usage":"執行 bd2layouts → 選取圖框圖塊（A3-outline-A/B 等）→ 自動複製配置、建視埠、縮放","level":7,"lt":"✅","ver":"20251213","author":"chengshunyi","video":"https://youtu.be/EMR9rHlzxbk","fas":"fas/bd2layouts.fas"},{"no":154,"file":"BDPSM.LSP","cmd":"BDPSM","cat":"出圖/列印","desc":"PSM：以雙清單選擇多個配置，批次更新頁面設定並穩定附加外部參考（先拆離同名外參），設定自動讀寫 TEMP 檔。","usage":"執行 BDPSM → DCL 左右清單選配置 → 設定頁面設定與外參 → 確定後批次套用","level":8,"lt":"✅","ver":"2026-09-06 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/BDPSM.fas"},{"no":155,"file":"BDS.lsp","cmd":"BDS","cat":"繪圖","desc":"自動門檻線/標記繪製：選門圖塊後取其寬度與底線，依七種模式與倍數畫出門檻平行四邊形等線條，放在 DOOR-SILL 圖層。","usage":"執行 BDS → DCL 設定圖層/顏色/畫線模式與倍數 → 選取門圖塊（動態）→ 自動畫門檻線","level":7,"lt":"✅","ver":"2026 (檔案日期 2026-06-13)","author":"ChengBar (MyCAD)","video":"","fas":"fas/BDS.fas"},{"no":156,"file":"BDT.LSP","cmd":"BDT","cat":"面積/數量統計","desc":"建立圖塊清冊：統計圖塊定義與數量，以 AutoCAD 表格列出（Block-Count），設定表格樣式與顏色，處理較慢。","usage":"執行 BDT → 指定表格插入點 → 自動統計並建立圖塊數量表","level":7,"lt":"⚠️","ver":"202402","author":"chengshunyi","video":"","fas":"fas/BDT.fas"},{"no":157,"file":"BE-plot-AXB.lsp","cmd":"be-plot-AXB、MODEL-PLOT-A","cat":"出圖/列印","desc":"模型空間框選範圍出圖：DCL 選擇圖紙尺寸（A0/A1/A3/A4）與筆寬表，依框選範圍縮放並執行 PLOT。","usage":"執行 be-plot-AXB 或 MODEL-PLOT-A → DCL 選紙張/筆寬表 → 框選範圍 → 自動列印","level":7,"lt":"✅","ver":"2024-04-27 (檔案日期)","author":"—","video":"","fas":"fas/BE-plot-AXB.fas"},{"no":158,"file":"BEAM.LSP","cmd":"beam","cat":"剖面/結構","desc":"以 DCL 選擇四種梁型式（含幻燈片預覽），輸入梁寬與梁深，依點選位置畫出梁線並打斷穿過牆柱的線段。","usage":"執行 beam → DCL 選梁型式與寬度/深度 → 依型式點選各點 → 自動畫梁線","level":6,"lt":"✅","ver":"84.4.24","author":"—","video":"","fas":"fas/BEAM.fas"},{"no":159,"file":"BeamDraw.lsp","cmd":"BeamDraw、BeamCheck","cat":"剖面/結構","desc":"選中心線畫梁線：依指定中心線圖層雙向偏移梁寬，產生梁線並做單階段干涉檢查，遇牆柱即停，中心線圖層不參與碰撞。","usage":"執行 BeamDraw → DCL 設定中心線/梁線圖層、顏色、梁寬 → 選取中心線 → 自動產生梁線；BeamCheck 檢查","level":8,"lt":"✅","ver":"2026-10-04 (檔案日期)","author":"ChengBar (MyCAD)","video":"https://youtu.be/E7z6yrNoSOA","fas":"fas/BeamDraw.fas"},{"no":160,"file":"BeamPair.LSP","cmd":"BeamPair","cat":"剖面/結構","desc":"RC 結構梁尺寸整理：選取梁編號與尺寸文字，依 Y、X 排序，橫向合併同列編號並依星號展開輸出整理後的梁配對表。","usage":"執行 BeamPair → DCL 設定星號展開/字高/行距/單位/比例 → 選取文字物件 → 自動整理輸出","level":7,"lt":"✅","ver":"20260425","author":"MyCAD","video":"","fas":"fas/BeamPair.fas"},{"no":161,"file":"BEAN-1.LSP","cmd":"bean-1","cat":"剖面/結構","desc":"依三點與梁寬、梁深，畫出梁（BEAN 應為 BEAM）平面線並打斷相交線段（型式 1）。","usage":"執行 bean-1 → 指定 A、B、C 點 → 輸入梁寬與梁深 → 自動畫線與打斷","level":3,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/BEAN-1.fas"},{"no":162,"file":"BEAN-2.LSP","cmd":"bean-2","cat":"剖面/結構","desc":"依兩點與梁寬、梁深，畫出梁平面線並打斷相交線段（型式 2）。","usage":"執行 bean-2 → 指定 A、B 點 → 輸入梁寬與梁深 → 自動畫線與打斷","level":3,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/BEAN-2.fas"},{"no":163,"file":"BEAN-4.LSP","cmd":"bean-4","cat":"剖面/結構","desc":"依三點與梁寬、梁深及高度 H、寬度 W，畫出梁平面線並打斷相交線段（型式 4）。","usage":"執行 bean-4 → 指定 A、B、C 點 → 輸入梁寬/梁深/H/W → 自動畫線與打斷","level":3,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/BEAN-4.fas"},{"no":164,"file":"Bevel.LSP","cmd":"BVS、BV、Bevel","cat":"標註","desc":"斜面（Bevel）標註：以 DCL 設定文字高、分數格式等後，繪製含分數文字的斜角尺寸標註。","usage":"執行 BVS 設定樣式 → 執行 BV 或 Bevel → 依提示指定斜面點位 → 自動繪製標註","level":9,"lt":"✅","ver":"Rev 1 / 1-20-06 (檔案日期 2023-02-27)","author":"Terry Miller（autolisp-exchange.com）","video":"","fas":"fas/Bevel.fas"},{"no":165,"file":"BFV-G.lsp","cmd":"BFV-G","cat":"圖塊/屬性","desc":"Block Filter by Value 通用版：點選屬性後窗選範圍，過濾出相同屬性標籤與屬性值的圖塊（不限圖塊名稱）。","usage":"執行 BFV-G → 點選目標屬性 → 窗選搜尋範圍 → 自動選出相符圖塊","level":5,"lt":"✅","ver":"2026-02-02 (檔案日期)","author":"MyCAD","video":"","fas":"fas/BFV-G.fas"},{"no":166,"file":"BFV.lsp","cmd":"BFV","cat":"圖塊/屬性","desc":"Block Filter by Value：點選屬性後窗選範圍，過濾出相同圖塊名稱（含動態圖塊）且屬性值相同的圖塊。","usage":"執行 BFV → 點選目標屬性 → 窗選搜尋範圍 → 自動選出相符圖塊","level":6,"lt":"✅","ver":"2026-02-02 (檔案日期)","author":"MyCAD","video":"","fas":"fas/BFV.fas"},{"no":167,"file":"bind-la-rename.lsp","cmd":"bind-la-rename","cat":"圖層","desc":"將綁定外參後產生的 $0$ 前綴圖層、圖塊、文字型式、線型、標註型式批次改名。","usage":"執行 bind-la-rename → 自動掃描並重新命名各符號表項目","level":4,"lt":"✅","ver":"20240830","author":"Shashikant（2018）/ chengshunyi","video":"","fas":"fas/bind-la-rename.fas"},{"no":168,"file":"BindFix.LSP","cmd":"BindFix","cat":"圖面管理","desc":"清除外部參考綁定後殘留的 xref$0$ 名稱前綴，處理圖塊、標註型式、圖層、線型、字型，重名時自動加序號，並以 DCL 顯示使用說明。","usage":"執行 BindFix → DCL 顯示說明按確定 → 自動改名並顯示成功/失敗統計（可 U 一次復原）","level":8,"lt":"⚠️","ver":"v2.1.0 / 2026-11-14","author":"Michael Puckett（原著 BindFix15）/ ChengBar","video":"https://youtu.be/G4HEFJNhkUI","fas":"fas/BindFix.fas"},{"no":169,"file":"BindFix_v1_backup.LSP","cmd":"BindFix","cat":"圖面管理","desc":"BindFix 舊版：清除外部參考綁定後的 $0$ 前綴名稱，處理圖塊、圖層、線型、字型、標註型式（支援 AutoCAD 2000 以上）。","usage":"執行 BindFix → 自動掃描並改名，顯示 Renamed 與 Could not rename 訊息","level":5,"lt":"✅","ver":"20220716更新 / 2024-02-23 (檔案日期)","author":"Michael Puckett","video":"https://youtu.be/G4HEFJNhkUI","fas":""},{"no":170,"file":"Bisector(畫等分線).lsp","cmd":"BI","cat":"繪圖","desc":"選兩個直線物件，畫出角平分線或平行線間距中線（XLINE），位置依點選處方向決定。","usage":"執行 BI → 選取第一個直線物件 → 選取第二個直線物件 → 自動產生平分 XLINE","level":6,"lt":"✅","ver":"August 2011 (檔案日期 2011-10-17)","author":"Kent Cooper","video":"","fas":"fas/Bisector(畫等分線).fas"},{"no":171,"file":"BKL.LSP","cmd":"BKL","cat":"繪圖","desc":"畫出斷裂線（Break Line）：指定起訖點產生帶折線的寬多段線符號。","usage":"執行 BKL → 指定起點 → 指定終點 → 自動畫斷裂線","level":2,"lt":"✅","ver":"2022-07-30 (檔案日期)","author":"Jeffery P Sanders","video":"","fas":"fas/BKL.fas"},{"no":172,"file":"bl-att-renum.lsp","cmd":"bl-att-renum-0、bl-att-renum-2、bl-att-renum-3","cat":"圖塊/屬性","desc":"依圖塊名稱選取屬性圖塊，點選屬性後重新編號（無補零、2 位、3 位），可設前綴/後綴與起始號，支援動態圖塊。","usage":"執行 bl-att-renum-0/2/3 → 點選屬性 → 輸入圖塊名稱 → 輸入前綴後綴與起始號 → 依序點選圖塊編號","level":6,"lt":"✅","ver":"20230520","author":"chengshunyi","video":"","fas":"fas/bl-att-renum.fas"},{"no":173,"file":"BL0.lsp","cmd":"BL0","cat":"圖塊/屬性","desc":"將指定圖塊定義內所有物件圖層改為 0（顏色 ByLayer）並 REGEN，顯示變更統計。","usage":"執行 BL0 → 選取圖塊 → 自動改為 0 層並顯示結果","level":4,"lt":"✅","ver":"20220909","author":"—","video":"","fas":"fas/BL0.fas"},{"no":174,"file":"blk-2excel.LSP","cmd":"blk-2excel","cat":"轉檔/匯出入","desc":"圖塊計數結果與 Excel 互通：開啟或連接 Excel 活頁簿，讀取/寫入圖塊名稱與數量欄位。","usage":"執行 blk-2excel → 指定 Excel 檔 → 自動讀寫圖塊數量","level":8,"lt":"❌","ver":"2024-11-16 (檔案日期)","author":"—","video":"","fas":"fas/blk-2excel.fas"},{"no":175,"file":"blk-any-explode.lsp","cmd":"blk-any-explode、iburst","cat":"圖塊/屬性","desc":"炸開任意圖塊（含匿名圖塊）並保留屬性為文字，等同 Burst，內含匿名圖塊參照處理。","usage":"執行 blk-any-explode 或 iburst → 選取圖塊 → 自動炸開並轉屬性為文字","level":7,"lt":"✅","ver":"20240208","author":"Lee Mac（Burst）/ chengshunyi","video":"","fas":"fas/blk-any-explode.fas"},{"no":176,"file":"blk-area-type-c.LSP","cmd":"blk-area-type-c","cat":"面積/數量統計","desc":"依屬性欄位分類統計面積：點選分類屬性與加總屬性，依圖塊名稱選取後分類加總並寫入圖面，字高依 textsize。","usage":"執行 blk-area-type-c → 點選分類屬性 → 點選加總屬性 → 輸入圖塊名稱 → 指定寫出位置","level":7,"lt":"✅","ver":"20240805","author":"chengshunyi","video":"","fas":"fas/blk-area-type-c.fas"},{"no":177,"file":"blk-at-l-mid.LSP","cmd":"blk-at-l-mid","cat":"圖塊/屬性","desc":"選取弧、線、多段線或雲形線，在其中點插入牆體類型標記圖塊（FSVFS 棒棒糖）。","usage":"執行 blk-at-l-mid → 選取線段 → 自動於中點插入圖塊","level":3,"lt":"✅","ver":"20241127","author":"chengshunyi","video":"","fas":"fas/blk-at-l-mid.fas"},{"no":178,"file":"blk-at-mpl.lsp","cmd":"blk-at-mpl","cat":"圖塊/屬性","desc":"選取線/弧/多段線，在其中點插入圖塊並對齊線的角度，依圖檔單位比例係數縮放。","usage":"執行 blk-at-mpl → 選取線段 → 自動於中點插入圖塊並旋轉對齊","level":5,"lt":"✅","ver":"20230531","author":"chengshunyi","video":"","fas":"fas/blk-at-mpl.fas"},{"no":179,"file":"blk-att-cnt-car-lr.lsp","cmd":"blk-att-cnt-car-lr、blk-2att-cnt","cat":"面積/數量統計","desc":"停車位圖塊統計（左右版）：依名稱判別汽車、機車、大客貨車等，含機械停車多層計數，製作統計表格，可複選圖塊。","usage":"執行 blk-att-cnt-car-lr → DCL 設定 → 複選停車位圖塊 → 指定表格位置 → 自動統計並建表","level":8,"lt":"✅","ver":"20250329","author":"chengshunyi","video":"","fas":"fas/blk-att-cnt-car-lr.fas"},{"no":180,"file":"blk-att-cnt.lsp","cmd":"blk-att-cnt-car、blk-2att-cnt、blk-att-cnt-dw、blk-att-cnt、blk-att-cnt-dw-a1、blk-att-cnt-a1","cat":"面積/數量統計","desc":"屬性值計數統計：停車位（含機械車位 1~3 層）、門窗、一般屬性圖塊分類數量，依屬性組合製作統計表格，A1 系列為不同圖幅版型。","usage":"執行 blk-att-cnt / -car / -dw → DCL 設定 → 複選圖塊 → 指定表格位置 → 自動統計建表","level":8,"lt":"✅","ver":"20241204 / 20250329","author":"chengshunyi","video":"","fas":"fas/blk-att-cnt.fas"},{"no":181,"file":"blk-AttSum.lsp","cmd":"blk-AttSum","cat":"面積/數量統計","desc":"灌木統計：選取 KEY-PLANT 屬性圖塊，依植物類別加總數量，輸出為 CSV 報表檔。","usage":"執行 blk-AttSum → 選取圖塊 → 指定輸出檔 → 自動加總並寫出","level":6,"lt":"✅","ver":"20241206","author":"Lee Mac（01.02.10）/ chengshunyi","video":"","fas":"fas/blk-AttSum.fas"},{"no":182,"file":"blk-bm-iblk.lsp","cmd":"blk-bm-iblk-A、blk-bm-iblk-B、blk-bm-iblk","cat":"圖塊/屬性","desc":"選取門圖塊，於其下緣中點/中心插入門號圖塊（DOOR-TAG）並以字高 0.8 倍比例建立 MText 門號。","usage":"執行 blk-bm-iblk-A / B → 選取門圖塊 → 輸入比例 → 自動插入門號標籤","level":5,"lt":"✅","ver":"20250317","author":"chengshunyi","video":"","fas":"fas/blk-bm-iblk.fas"},{"no":183,"file":"blk-bom.lsp","cmd":"blk-bom","cat":"面積/數量統計","desc":"計算圖塊並列表：選取圖塊後過濾匿名與鎖定圖層圖塊，依屬性組合統計數量，畫出含圖例的 BOM 清單。","usage":"執行 blk-bom → 選取並過濾圖塊 → 指定清單位置 → 自動統計並繪製清單","level":8,"lt":"✅","ver":"20240121","author":"chengshunyi","video":"","fas":"fas/blk-bom.fas"},{"no":184,"file":"blk-cnt-entitys.LSP","cmd":"blk-cnt-entitys","cat":"查詢","desc":"列出圖塊定義內各類物件（線、弧、屬性等）的個別數量。","usage":"執行 blk-cnt-entitys → 選取圖塊 → 顯示物件數量","level":3,"lt":"✅","ver":"20241116","author":"chengshunyi","video":"","fas":"fas/blk-cnt-entitys.fas"},{"no":185,"file":"blk-cnt-Visibility.LSP","cmd":"blk-cnt-Visibility","cat":"面積/數量統計","desc":"動態圖塊可見性狀態統計數量：取得可見性參數名稱與目前值，按狀態計數。","usage":"執行 blk-cnt-Visibility → 選取圖塊 → 顯示各可見性狀態數量","level":5,"lt":"✅","ver":"2024-11-16 (檔案日期)","author":"Lee Mac / chengshunyi","video":"","fas":"fas/blk-cnt-Visibility.fas"},{"no":186,"file":"blk-count-byname-byzone.LSP","cmd":"blk-count-byname-byzone","cat":"面積/數量統計","desc":"依 ZONE* 圖層的多段線區域，分區分類統計圖塊名稱的數量。","usage":"執行 blk-count-byname-byzone → 自動依各區域統計 → 顯示結果","level":6,"lt":"✅","ver":"20231105","author":"chengshunyi","video":"","fas":"fas/blk-count-byname-byzone.fas"},{"no":187,"file":"Blk-Dim-auto.lsp","cmd":"Blk-Dim-auto","cat":"標註","desc":"選取多個圖塊，依水平垂直方向對相鄰圖塊插入點自動標註線性尺寸，可設定最大距離控制。","usage":"執行 Blk-Dim-auto → 輸入最大距離 → 選取圖塊 → 指定尺寸線位置 → 自動標註","level":6,"lt":"✅","ver":"202309902 (推測 20230902)","author":"chengshunyi","video":"","fas":"fas/Blk-Dim-auto.fas"},{"no":188,"file":"Blk-dim-seq-m.lsp","cmd":"Blk-dim-seq-m","cat":"標註","desc":"依圖塊插入點順序標註對齊尺寸，改為 m 單位顯示，使用 MY-DIM 文字型式。","usage":"執行 Blk-dim-seq-m → 選取圖塊 → 指定尺寸線位置 → 自動標註","level":6,"lt":"✅","ver":"20240421","author":"chengshunyi","video":"","fas":"fas/Blk-dim-seq-m.fas"},{"no":189,"file":"BLK-DIM-SEQ-UI.lsp","cmd":"blk-dim-seq-ui","cat":"標註","desc":"圖塊順序標註 DCL 版：設定相鄰距離、尺寸偏移、繪圖比例與單位，掃描全圖圖塊後依序標註對齊尺寸。","usage":"執行 blk-dim-seq-ui → DCL 設定距離/偏移/比例/單位 → 確定 → 自動標註","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"MyCAD","video":"","fas":"fas/BLK-DIM-SEQ-UI.fas"},{"no":190,"file":"Blk-dim-seq.LSP","cmd":"Blk-dim-seq","cat":"標註","desc":"依圖塊插入點順序標註對齊尺寸，使用 MY-DIM 文字型式與 danny-s4 字型。","usage":"執行 Blk-dim-seq → 選取圖塊 → 指定尺寸線位置 → 自動標註","level":6,"lt":"✅","ver":"20220716更新 / 2024-04-13 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/Blk-dim-seq.fas"},{"no":191,"file":"blk-f-d-att-link.lsp","cmd":"blk-f-d-att-link-s、blk-f-d-att-link","cat":"圖塊/屬性","desc":"選取重複的屬性值，以線連結相同屬性值的圖塊，可排除指定值（如 NUM）。","usage":"執行 blk-f-d-att-link → 點選屬性 → 自動找相同值並畫連線","level":6,"lt":"✅","ver":"20240319","author":"chengshunyi（RJP 修改）","video":"","fas":"fas/blk-f-d-att-link.fas"},{"no":192,"file":"blk-f-d-att.LSP","cmd":"blk-f-d-att","cat":"圖塊/屬性","desc":"搜尋屬性圖塊中相同屬性值：點選屬性後以 DCL 列表顯示相同值，亮顯並以多段線連線，必要時縮放。","usage":"執行 blk-f-d-att → 點選屬性圖塊 → 點選屬性查找相同值 → DCL 選取 → 亮顯並連線","level":6,"lt":"✅","ver":"20240319","author":"chengshunyi","video":"","fas":"fas/blk-f-d-att.fas"},{"no":193,"file":"blk-hatch-color.LSP","cmd":"blk-hatch-color","cat":"圖塊/屬性","desc":"變更圖塊定義內填充（Hatch）的顏色。","usage":"執行 blk-hatch-color → 選取圖塊 → 自動改變填充顏色","level":3,"lt":"✅","ver":"20220909","author":"—","video":"","fas":"fas/blk-hatch-color.fas"},{"no":194,"file":"blk-ImintheZone.LSP","cmd":"blk-ImintheZone","cat":"面積/數量統計","desc":"依多段線圖層（zone*）分區分類統計圖塊數量，於指定位置寫出報表文字。","usage":"執行 blk-ImintheZone → 選取圖塊 → 指定報表位置 → 自動寫出各區統計","level":6,"lt":"✅","ver":"20241116","author":"pBe（June 2021）/ chengshunyi","video":"","fas":"fas/blk-ImintheZone.fas"},{"no":195,"file":"blk-name-recount.LSP","cmd":"blk-name-recount","cat":"面積/數量統計","desc":"統計指定名稱圖塊（NORMAL PUSH BUTTON、ELDB、SPDB、ESPDB、MODULE_PLATE 等）數量並寫出 BLOCK_COUNT_ 結果。","usage":"執行 blk-name-recount → 自動統計指定名稱圖塊 → 更新計數","level":4,"lt":"✅","ver":"20241116","author":"chengshunyi","video":"","fas":"fas/blk-name-recount.fas"},{"no":196,"file":"BLK-NUMS.LSP","cmd":"blk-nums","cat":"面積/數量統計","desc":"統計圖面圖塊名稱與數量，寫入與圖檔同名的 .blk 文字清單檔。","usage":"執行 blk-nums → 選取圖塊（Enter 全選）→ 寫出 .blk 清單","level":3,"lt":"✅","ver":"84.4.25","author":"—","video":"","fas":"fas/BLK-NUMS.fas"},{"no":197,"file":"blk-outline.lsp","cmd":"blk-outline","cat":"圖塊/屬性","desc":"選取圖塊，依旋轉角與 OCS 計算並建立圖塊外框輪廓（改自 Lee Mac 的 Attach Block Boundary）。","usage":"執行 blk-outline → 選取圖塊 → 自動產生外框輪廓","level":7,"lt":"✅","ver":"20220716更新 / 2024-11-03 (檔案日期)","author":"Lee Mac（ABB）/ chengshunyi","video":"","fas":"fas/blk-outline.fas"},{"no":198,"file":"blk-prev.LSP","cmd":"blk-prev","cat":"圖塊/屬性","desc":"將圖面所有圖塊定義依高度排序，逐一插入並排成一列，方便預覽目前圖面有哪些圖塊。","usage":"執行 blk-prev → 指定插入點 → 自動排列所有圖塊","level":5,"lt":"✅","ver":"2022-12-25 (檔案日期)","author":"—","video":"","fas":"fas/blk-prev.fas"},{"no":199,"file":"blk-sel-listbox-LR.lsp","cmd":"blk-sel-listbox-LR","cat":"圖塊/屬性","desc":"左右雙清單對話框，可在圖塊清單間新增、刪除、上移下移排序，作為收集並排序項目的範本。","usage":"執行 blk-sel-listbox-LR → 在對話框中選取圖塊加入右側 → 調整順序 → 確定","level":6,"lt":"✅","ver":"20241208","author":"chengshunyi","video":"","fas":"fas/blk-sel-listbox-LR.fas"},{"no":200,"file":"blk-tag-count.lsp","cmd":"blk-tag-count","cat":"面積/數量統計","desc":"依選定的圖塊屬性標籤組合統計圖塊數量，結果可寫入 AutoCAD 表格或 Excel（含 CSV 備援）。","usage":"執行 blk-tag-count → 選圖塊 → 對話框選標籤與輸出方式 → 窗選統計範圍 → 指定表格插入點或輸出 Excel","level":8,"lt":"⚠️","ver":"20241116 (最新修改 20260109)","author":"chengshunyi","video":"","fas":"fas/blk-tag-count.fas"},{"no":201,"file":"blka-exph.lsp","cmd":"BLKA-EXPH","cat":"圖塊/屬性","desc":"BLOCK 圖庫管理器（建築圖框標題欄風格），以幻燈片分頁瀏覽、插入圖塊，並可新增、刪除、更名與批次更新幻燈片。","usage":"執行 BLKA-EXPH → 選圖庫目錄與圖檔 → 點幻燈片 → 指定插入點；亦可新增或刪除圖檔","level":9,"lt":"⚠️","ver":"v1.9.2 2026-11-05","author":"ChengBar (MyCAD)","video":"https://youtu.be/zMZkAvqKeOw","fas":"fas/blka-exph.fas"},{"no":202,"file":"BLKAnnoScaleManager.lsp","cmd":"BLKAnnoScaleManager","cat":"圖塊/屬性","desc":"對話框多選註解比例清單，一次將所選比例加入多個選取圖塊的註解比例中。","usage":"執行 BLKAnnoScaleManager → 對話框多選比例 → 確定 → 選取圖塊 → Enter 結束","level":6,"lt":"✅","ver":"2026-06-27 (檔案日期)","author":"—","video":"","fas":"fas/BLKAnnoScaleManager.fas"},{"no":203,"file":"BlkColorOptAll.lsp","cmd":"BlkColorOptAll","cat":"圖塊/屬性","desc":"遞迴處理圖塊內所有物件（含巢狀圖塊），批次改為指定顏色或恢復 ByLayer。","usage":"執行 BlkColorOptAll → 選取一個圖塊 → 選模式 C 或 B → 輸入顏色號碼 (1-255)","level":5,"lt":"✅","ver":"20251125","author":"—","video":"","fas":"fas/BlkColorOptAll.fas"},{"no":204,"file":"blkcount.lsp","cmd":"blkcount、countsettings","cat":"面積/數量統計","desc":"進階圖塊計數器，統計一般與動態圖塊數量，可輸出到命令列、文字檔、CSV 或 AutoCAD 表格，並附設定對話框。","usage":"執行 blkcount → 選取圖塊（Enter 全選）→ 依設定輸出表格插入點或檔案；countsettings 調整輸出設定","level":8,"lt":"⚠️","ver":"2022-07-16 (檔案日期)","author":"Lee Mac (Count.lsp 改版)","video":"","fas":"fas/blkcount.fas"},{"no":205,"file":"blkman-ui.lsp","cmd":"blkman-ui","cat":"圖塊/屬性","desc":"簡易圖塊管理對話框，列出圖面圖塊與數量，可設定比例並選取後插入。","usage":"執行 blkman-ui → 從清單選圖塊 → 設定比例 → 確定 → 指定插入點","level":6,"lt":"✅","ver":"20251021","author":"—","video":"","fas":"fas/blkman-ui.fas"},{"no":206,"file":"blkman.LSP","cmd":"blkman","cat":"圖塊/屬性","desc":"簡易圖塊管理，對話框列出圖塊並可設定 XYZ 比例後插入圖面。","usage":"執行 blkman → 對話框選圖塊與比例 → 確定 → 指定插入點","level":6,"lt":"✅","ver":"20220716","author":"Cheng BAR","video":"","fas":"fas/blkman.fas"},{"no":207,"file":"BLKMGR.lsp","cmd":"BLKMGR","cat":"圖塊/屬性","desc":"MyCAD 使用者 BLOCK 圖庫管理系統，幻燈片每頁 50 格瀏覽、插入圖塊，含屬性強制控制與縮圖標準化。","usage":"執行 BLKMGR → 選圖庫目錄 → 翻頁點選幻燈片 → 指定插入點","level":9,"lt":"⚠️","ver":"v3.9.2","author":"ChengBar (MyCAD)","video":"","fas":"fas/BLKMGR.fas"},{"no":208,"file":"blkmng-archi.lsp","cmd":"BLKA","cat":"圖塊/屬性","desc":"BLOCK 圖庫管理器（建築圖框標題欄風格），幻燈片分頁瀏覽插入圖塊，可新增刪除更名圖檔與批次更新幻燈片。","usage":"執行 BLKA → 選圖庫目錄與圖檔 → 點幻燈片 → 指定插入點","level":9,"lt":"⚠️","ver":"v1.9.2 2026-11-05","author":"ChengBar (MyCAD)","video":"https://youtu.be/wKyJtD75P3Y","fas":"fas/blkmng-archi.fas"},{"no":209,"file":"BLKMNG.LSP","cmd":"BLKMNG","cat":"圖塊/屬性","desc":"使用者 BLOCK 圖庫管理 v2.9，以幻燈片瀏覽插入圖塊，支援搜尋、新增刪除更名圖檔與目錄、更新幻燈片。","usage":"執行 BLKMNG → 選目錄 → 翻頁選幻燈片 → 指定插入點","level":9,"lt":"⚠️","ver":"v2.9 2013/12/26（2026/11/05 更新）","author":"俞雲霨","video":"","fas":"fas/BLKMNG.fas"},{"no":210,"file":"BLKMNG100.LSP","cmd":"BLKMNG","cat":"圖塊/屬性","desc":"BLOCK 圖庫管理（100 格版），每頁最多 100 格幻燈片，其餘功能同 BLKMNG。","usage":"執行 BLKMNG → 選目錄 → 翻頁選幻燈片 → 指定插入點","level":9,"lt":"⚠️","ver":"v2.3 2026/11/04","author":"俞雲霨","video":"","fas":"fas/BLKMNG100.fas"},{"no":211,"file":"BLKMNG60.LSP","cmd":"BLKMNG","cat":"圖塊/屬性","desc":"BLOCK 圖庫管理（60 格版），每頁 60 格幻燈片，其餘功能同 BLKMNG。","usage":"執行 BLKMNG → 選目錄 → 翻頁選幻燈片 → 指定插入點","level":9,"lt":"⚠️","ver":"v2.3 2026/11/04","author":"俞雲霨","video":"","fas":"fas/BLKMNG60.fas"},{"no":212,"file":"BLKMNG70.LSP","cmd":"BLKMNG","cat":"圖塊/屬性","desc":"BLOCK 圖庫管理（70 格版），每頁 70 格幻燈片，其餘功能同 BLKMNG。","usage":"執行 BLKMNG → 選目錄 → 翻頁選幻燈片 → 指定插入點","level":9,"lt":"⚠️","ver":"v2.3 2026/11/04","author":"俞雲霨","video":"","fas":"fas/BLKMNG70.fas"},{"no":213,"file":"BLKMNG80.LSP","cmd":"BLKMNG","cat":"圖塊/屬性","desc":"BLOCK 圖庫管理（80 格版），每頁 80 格幻燈片，其餘功能同 BLKMNG。","usage":"執行 BLKMNG → 選目錄 → 翻頁選幻燈片 → 指定插入點","level":9,"lt":"⚠️","ver":"v2.3 2026/11/04","author":"俞雲霨","video":"","fas":"fas/BLKMNG80.fas"},{"no":214,"file":"BLKMNG90.LSP","cmd":"BLKMNG","cat":"圖塊/屬性","desc":"BLOCK 圖庫管理（90 格版），每頁 90 格幻燈片，其餘功能同 BLKMNG。","usage":"執行 BLKMNG → 選目錄 → 翻頁選幻燈片 → 指定插入點","level":9,"lt":"⚠️","ver":"v2.3 2026/11/04","author":"俞雲霨","video":"","fas":"fas/BLKMNG90.fas"},{"no":215,"file":"BlkQty.lsp","cmd":"BlkQty-LD-Excel、BlkQty-Desc、BlkQty","cat":"面積/數量統計","desc":"統計圖面所有圖塊依圖層與名稱的數量，可輸出 CSV 供 Excel 開啟或在圖面建立含備註欄的表格。","usage":"執行 BlkQty → 選輸出方式 → 輸入字高 → 指定表格位置或 CSV 檔名","level":8,"lt":"✅","ver":"20250501","author":"chengshunyi（原作 Tharwat 2015）","video":"","fas":"fas/BlkQty.fas"},{"no":216,"file":"blks-bom.lsp","cmd":"blks-bom","cat":"面積/數量統計","desc":"選取圖塊後統計數量並於圖面繪製 BOM 列表，依屬性值分欄顯示，可排除鎖定圖層與動態圖塊。","usage":"執行 blks-bom（指令 dbom）→ 選取圖塊 → 指定列表插入點","level":7,"lt":"✅","ver":"20240123","author":"chengshunyi","video":"","fas":"fas/blks-bom.fas"},{"no":217,"file":"BlkTagAutoEncoder.LSP","cmd":"BlkTagAutoEncoder、TestDCLOnly、ShowDCLError、TestDCL_PlanB","cat":"圖塊/屬性","desc":"圖塊屬性自動編碼工具，對話框設定前置碼、碼數、起始編號並預覽編碼，另含測試用 DCL 指令。","usage":"執行 BlkTagAutoEncoder → 對話框設定前置碼與編號 → 選取圖塊 → 自動編號","level":6,"lt":"✅","ver":"2025-07-20 (檔案日期)","author":"—","video":"","fas":"fas/BlkTagAutoEncoder.fas"},{"no":218,"file":"blkto0.LSP","cmd":"blkto0c8","cat":"圖塊/屬性","desc":"將選取圖塊定義內的物件改到 0 層並設為 ByLayer 顏色。","usage":"執行 blkto0c8 → 選取圖塊 → 自動修改並重生","level":3,"lt":"✅","ver":"20220909","author":"—","video":"","fas":"fas/blkto0.fas"},{"no":219,"file":"blkto0c8.LSP","cmd":"blkto0c8","cat":"圖塊/屬性","desc":"將選取圖塊定義內的物件改到 0 層並設為 ByLayer 顏色。","usage":"執行 blkto0c8 → 選取圖塊 → 自動修改並重生","level":3,"lt":"✅","ver":"20220909","author":"—","video":"","fas":"fas/blkto0c8.fas"},{"no":220,"file":"blky2a.lsp","cmd":"blky2a-cm2M4、blky2a-cm2M、blky2a-M2M、blky2a","cat":"標註","desc":"取圖塊插入點 Y 座標做單位轉換，以欄位連結寫入屬性，並依正負顯示 +、-、±（高程標註）。","usage":"執行 blky2a → 對話框設定除數與小數位 → 選來源圖塊 → 選目標屬性","level":6,"lt":"✅","ver":"2026-08-23 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/blky2a.fas"},{"no":221,"file":"BlkY2Attribute.lsp","cmd":"blky2a-cm2M4、blky2a-cm2M、blky2a-M2M","cat":"標註","desc":"改自 Lee Mac 的 Area Field to Attribute，將圖塊插入點 Y 座標（高程）以欄位寫入屬性並轉為公尺。","usage":"執行 blky2a-cm2M → 選圖塊 → 選屬性或含屬性圖塊","level":6,"lt":"✅","ver":"2025-06-25 (檔案日期)","author":"Lee Mac（chengshunyi 修改）","video":"","fas":"fas/BlkY2Attribute.fas"},{"no":222,"file":"bln2lan.LSP","cmd":"bln2lan","cat":"圖層","desc":"將選取的圖塊逐一改到與其名稱相同的圖層。","usage":"執行 bln2lan → 選取圖塊 → 圖塊自動移到同名圖層","level":3,"lt":"✅","ver":"20210617","author":"cheng bar","video":"","fas":"fas/bln2lan.fas"},{"no":223,"file":"block-cc.lsp","cmd":"blcc、encc","cat":"圖塊/屬性","desc":"blcc 變更所選圖塊的顏色；encc 變更所選物件（可為圖塊內元素）的顏色。","usage":"執行 blcc 或 encc → 選取圖塊或物件 → 輸入顏色","level":5,"lt":"✅","ver":"2024-11-03 (檔案日期)","author":"Alaspher（forum.dwg.ru 網路程式）","video":"","fas":"fas/block-cc.fas"},{"no":224,"file":"block-color.lsp","cmd":"blcc、encc","cat":"圖塊/屬性","desc":"blcc 變更所選圖塊的顏色；encc 變更所選物件（可為圖塊內元素）的顏色。","usage":"執行 blcc 或 encc → 選取圖塊或物件 → 輸入顏色","level":5,"lt":"✅","ver":"20220402","author":"Alaspher（網路程式）","video":"","fas":"fas/block-color.fas"},{"no":225,"file":"BLOCK-I-TEXT.lsp","cmd":"tni、GO","cat":"文字","desc":"尋找圖塊並依其位置插入文字，或依圖塊名稱插入車位符號（小車、中車、大車），可設距離、字高、角度。","usage":"執行 tni → 窗選圖塊 → 輸入文字與距離、字高、角度 → 自動標註；GO 為插入圖塊功能","level":6,"lt":"✅","ver":"20240930","author":"CHENGSHUNYI","video":"","fas":"fas/BLOCK-I-TEXT.fas"},{"no":226,"file":"block-lock-unlock.lsp","cmd":"block-lock、block-unlock","cat":"圖塊/屬性","desc":"鎖定或解鎖所選圖塊所在的圖層，圖層 0 不處理。","usage":"執行 block-lock 或 block-unlock → 選取圖塊 → 完成","level":2,"lt":"✅","ver":"20211017","author":"cheng bar","video":"","fas":"fas/block-lock-unlock.fas"},{"no":227,"file":"block-recount.lsp","cmd":"block-recount","cat":"面積/數量統計","desc":"依內建的電氣盤箱與按鈕圖塊名稱清單，統計模型空間內各圖塊數量並列出。","usage":"執行 block-recount → 自動統計並於命令列顯示","level":4,"lt":"✅","ver":"2022-12-25 (檔案日期)","author":"—","video":"","fas":"fas/block-recount.fas"},{"no":228,"file":"BLOCK-SCALE-CEN.lsp","cmd":"SAC","cat":"修改","desc":"多個物件各自以自身範圍中心為基準點，一次以相同比例縮放，略過鎖定圖層與無限物件。","usage":"執行 SAC → 選取物件 → 輸入比例（記憶上次值）","level":4,"lt":"✅","ver":"2014-05-06","author":"Kent Cooper","video":"","fas":"fas/BLOCK-SCALE-CEN.fas"},{"no":229,"file":"BLOCK.LSP","cmd":"blo","cat":"圖塊/屬性","desc":"以指定比例插入圖塊，並將中文文字放在指定圖層。","usage":"執行 blo → 輸入比例 → 輸入中文文字圖層 → 指定插入點","level":2,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/BLOCK.fas"},{"no":230,"file":"BLOCK2MLEADER-M.LSP","cmd":"BLOCK2MLEADER-M","cat":"標註","desc":"以選取的樣板圖塊與引線，批次將圖面同名圖塊換成多重引線，並同步屬性值，可選擇是否刪除來源圖塊。","usage":"執行 BLOCK2MLEADER-M → 選來源圖塊 → 選目標 MLeader 樣板 → 選擇是否刪除來源 → 批次轉換","level":6,"lt":"✅","ver":"2026-03-08 (檔案日期)","author":"—","video":"","fas":"fas/BLOCK2MLEADER-M.fas"},{"no":231,"file":"BLOCK2MLEADER-M2.lsp","cmd":"BLOCK2MLEADER-M2","cat":"標註","desc":"將圖塊換成多重引線，依顯示模式切換引線樣式（如房間名稱），並同步屬性，模式長度為 1 時移除引線。","usage":"執行 BLOCK2MLEADER-M2 → 選來源圖塊 → 選目標 MLeader 樣板 → 選擇是否刪除來源 → 批次轉換","level":6,"lt":"✅","ver":"20260308","author":"chengshunyi","video":"","fas":"fas/BLOCK2MLEADER-M2.fas"},{"no":232,"file":"BLOCK2MLEADER-S.lsp","cmd":"BLOCK2MLEADER-S","cat":"標註","desc":"選取單一動態圖塊，依其房間名稱位置偏移值產生多重引線並同步屬性值。","usage":"執行 BLOCK2MLEADER-S → 選取動態圖塊 → 自動產生引線","level":6,"lt":"✅","ver":"2026-03-08 (檔案日期)","author":"—","video":"","fas":"fas/BLOCK2MLEADER-S.fas"},{"no":233,"file":"BlockByBlock-2.lsp","cmd":"BBB、t1","cat":"圖塊/屬性","desc":"將選取圖塊及其巢狀圖塊內所有物件的顏色等屬性設為 ByBlock，可選擇要處理的巢狀圖塊。","usage":"執行 BBB → 選取圖塊 → 對話框選巢狀圖塊 → 確定更新","level":6,"lt":"⚠️","ver":"Rlx 20 Oct 2020","author":"Rlx（cadtutor 論壇）","video":"","fas":"fas/BlockByBlock-2.fas"},{"no":234,"file":"BlockDim+.LSP","cmd":"BlockDim","cat":"標註","desc":"選取至少兩個圖塊，依插入點建立水平、垂直或對齊標註。","usage":"執行 BlockDim → 選取兩個以上圖塊 → 選標註型式 → 完成","level":4,"lt":"✅","ver":"2024-08-01 (檔案日期)","author":"—","video":"","fas":"fas/BlockDim+.fas"},{"no":235,"file":"BlockDim-2-m.lsp","cmd":"BlockDim-2-m、BlockDim-2HV","cat":"標註","desc":"連續標註圖塊，依單位與比例係數設定標註樣式，可水平垂直對齊。","usage":"執行 BlockDim-2-m → 選取圖塊 → 指定標註位置 → 連續標註","level":5,"lt":"✅","ver":"20240807","author":"chengshunyi","video":"","fas":"fas/BlockDim-2-m.fas"},{"no":236,"file":"BlockDim-2.lsp","cmd":"BlockDim-2i、BlockDim-2c、BlockDim-2、BlockDim-2HV","cat":"標註","desc":"圖塊連續標註，可抓插入點或形心，並檢查試用到期日。","usage":"執行 BlockDim-2 → 選取圖塊 → 指定標註位置 → 連續標註","level":5,"lt":"✅","ver":"20240919","author":"chengshunyi","video":"","fas":"fas/BlockDim-2.fas"},{"no":237,"file":"BlockDim-HVA.lsp","cmd":"BlockDim-HVA","cat":"標註","desc":"選取圖塊後可選水平、垂直或對齊標註，並可指定標註方向（左/右）。","usage":"執行 BlockDim-HVA → 選取圖塊 → 指定標註方向點 → 選型式","level":5,"lt":"✅","ver":"20240801","author":"CHENGSHUNYI","video":"","fas":"fas/BlockDim-HVA.fas"},{"no":238,"file":"Blocknumber.lsp","cmd":"（無，副程式庫）","cat":"圖塊/屬性","desc":"以 reactor 監控圖塊插入、複製、貼上，自動遞增屬性編號並於刪除後重排，可加前綴。","usage":"載入後依提示設定圖塊與屬性 → 插入或複製圖塊 → 編號自動遞增","level":8,"lt":"✅","ver":"20230429","author":"Tlindell 2008（chengshunyi 修改）","video":"","fas":"fas/Blocknumber.fas"},{"no":239,"file":"BlockReviewer.LSP","cmd":"BlockReviewer","cat":"圖塊/屬性","desc":"MyCAD 圖塊快速尋找定位，從清單選圖塊後逐一縮放檢視每個插入實體，支援動態圖塊。","usage":"執行 BlockReviewer → 選圖塊名稱 → 確定 → 逐一審查定位，Enter 下一個","level":6,"lt":"✅","ver":"2026 (版權年)","author":"ChengBar (MyCAD)","video":"","fas":"fas/BlockReviewer.fas"},{"no":240,"file":"blocksummary.LSP","cmd":"blocksummary","cat":"面積/數量統計","desc":"統計動態圖塊的可見性（顯示狀態）數量，並列出圖塊清單與門顯示角度。","usage":"執行 blocksummary → 選取圖塊 → 顯示統計結果","level":5,"lt":"✅","ver":"20230820","author":"chengshunyi（原作 Clint Moore 2017）","video":"","fas":"fas/blocksummary.fas"},{"no":241,"file":"BlockToXref.lsp","cmd":"btx、BlockToXref","cat":"圖面管理","desc":"將選取的一或多個圖塊改為對應檔案的外部參考，需先備妥 xref 檔，支援巢狀與多版面。","usage":"執行 btx → 選取圖塊 → 指定對應檔案 → 圖塊轉為外部參考","level":4,"lt":"✅","ver":"2014-12-15（chengshunyi 2024-02-18 修改）","author":"Jimmy Bergmark (JTB World)","video":"","fas":"fas/BlockToXref.fas"},{"no":242,"file":"blvert.LSP","cmd":"blvert","cat":"繪圖","desc":"選取矩形聚合線，依其頂點插入 Plate_Outline 圖塊，研發中。","usage":"執行 blvert → 選聚合線 → 選矩形 → 自動插入圖塊","level":4,"lt":"✅","ver":"20231001","author":"Ranjit Singh（網路程式）","video":"","fas":"fas/blvert.fas"},{"no":243,"file":"BOH-U-I.LSP","cmd":"BOH-UI、CLEARCHK","cat":"面積/數量統計","desc":"擷取動態圖塊內指定圖層線段，生成輪廓與填充並檢核面積，結果可輸出至文字、表格或 CSV；CLEARCHK 清除檢核圖層。","usage":"執行 BOH-UI → 對話框設定圖層與係數 → 選取圖塊 → 輸出統計","level":7,"lt":"✅","ver":"20220716 (最新 2026-09-29 檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/BOH-U-I.fas"},{"no":244,"file":"BOH-UI.LSP","cmd":"BOH-UI、CLEARCHK","cat":"面積/數量統計","desc":"BOH-U-I 的改進版，增加填充透明度設定，擷取動態圖塊內線段生成輪廓並統計面積。","usage":"執行 BOH-UI → 對話框設定圖層、透明度與係數 → 選取圖塊 → 輸出統計","level":7,"lt":"✅","ver":"2026-09-29 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/BOH-UI.fas"},{"no":245,"file":"BOH.lsp","cmd":"BOH","cat":"面積/數量統計","desc":"擷取圖塊內指定圖層線段生成輪廓，計算面積並乘單位與比例係數，輸出至 F2、文字、表格或 CSV。","usage":"執行 BOH → 輸入圖層與係數 → 選取圖塊 → 選輸出方式","level":7,"lt":"✅","ver":"2026-02-01 (檔案日期)","author":"—","video":"","fas":"fas/BOH.fas"},{"no":246,"file":"bolt-LT.LSP","cmd":"bolt-LT","cat":"圖塊/屬性","desc":"對話框選螺栓尺寸（M4～M6）並顯示幻燈片預覽，插入螺栓動態圖塊，LT 相容版。","usage":"執行 bolt-LT → 對話框選尺寸 → 確定 → 指定插入點","level":6,"lt":"✅","ver":"2026-06-21 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/bolt-LT.fas"},{"no":247,"file":"bolt.LSP","cmd":"bolt","cat":"圖塊/屬性","desc":"對話框選螺栓尺寸並預覽，利用 ObjectDBX 從來源圖檔匯入並插入螺栓動態圖塊。","usage":"執行 bolt → 對話框選尺寸 → 確定 → 指定插入點","level":6,"lt":"❌","ver":"2026-06-21 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/bolt.fas"},{"no":248,"file":"BOMLengths.lsp","cmd":"bomlengths、bom_lines、bom_circles、bom_arcs、bom_ellipses、bom_polylines、bom_splines","cat":"查詢","desc":"統計選取物件的長度總和，可依線、圓、弧、橢圓、聚合線、雲形線分類，並以目前單位顯示結果。","usage":"執行 bomlengths → 選取物件 → 輸入類型選項（預設 ALL）→ 顯示各類與總長度","level":5,"lt":"✅","ver":"2017-06-14","author":"Jimmy Bergmark (JTB World)","video":"","fas":"fas/BOMLengths.fas"},{"no":249,"file":"border.lsp","cmd":"border","cat":"出圖/列印","desc":"對話框以幻燈片挑選標題欄圖框，依比例與單位係數插入模型空間或圖紙空間並縮放顯示。","usage":"執行 border → 對話框選圖框幻燈片 → 確定 → 自動插入圖框","level":6,"lt":"✅","ver":"90.6.5（20220716 更新）","author":"—","video":"","fas":"fas/border.fas"},{"no":250,"file":"BOX-1.LSP","cmd":"box-1","cat":"標註","desc":"繪製虛線圓角矩形範圍框並拉出引線，插入含圖名與圖號屬性的詳圖符號。","usage":"執行 box-1 → 指定框左下角與右上角 → 指定引線點 C → 輸入圖名與圖號","level":4,"lt":"✅","ver":"84.4.12（20220716 更新）","author":"—","video":"","fas":"fas/BOX-1.fas"},{"no":251,"file":"BOX-2.LSP","cmd":"box-2","cat":"標註","desc":"繪製虛線圓角矩形範圍框，並以直線引出標示詳圖符號。","usage":"執行 box-2 → 指定框左下角與右上角 → 指定引線點 C → 輸入圖名與圖號","level":4,"lt":"✅","ver":"84.4.12（20220716 更新）","author":"—","video":"","fas":"fas/BOX-2.fas"},{"no":252,"file":"BOX-3.LSP","cmd":"box-3","cat":"標註","desc":"以虛線圓圈圈選範圍並以聚合線連出，插入含圖名圖號的詳圖符號。","usage":"執行 box-3 → 指定圓心 A → 指定點 B → 輸入圖名與圖號","level":4,"lt":"✅","ver":"84.4.12（20220716 更新）","author":"—","video":"","fas":"fas/BOX-3.fas"},{"no":253,"file":"box-i.lsp","cmd":"box-i","cat":"標註","desc":"整合 box-1/2/3 與新增的多種詳圖框樣式，對話框選型後以 entmake 繪製虛線範圍框並插入圖名圖號符號。","usage":"執行 box-i → 對話框選樣式 → 指定範圍與引線點 → 輸入圖名與圖號","level":7,"lt":"✅","ver":"20250329","author":"chengshunyi","video":"https://youtu.be/R0_OIXOTOhY","fas":"fas/box-i.fas"},{"no":254,"file":"BoxText.lsp","cmd":"BoxText","cat":"文字","desc":"為選取的單行或多行文字建立矩形聚合線外框，可設定向外偏移與線寬（改自 Express Tools TCircle 概念）。","usage":"執行 BT → 對話框設定偏移量與線寬 → 選取文字 → 自動加框","level":6,"lt":"✅","ver":"20220716","author":"Lee Mac（chengshunyi 修改）","video":"","fas":"fas/BoxText.fas"},{"no":255,"file":"bpoly-custom.LSP","cmd":"bpoly-custom","cat":"繪圖","desc":"在局部範圍內以 BOUNDARY 建立邊界，避免全圖運算以提升效能。","usage":"執行 bpoly-custom → 點選內部點 → 產生邊界","level":3,"lt":"✅","ver":"20240422","author":"chengshunyi","video":"","fas":"fas/bpoly-custom.fas"},{"no":256,"file":"bpoly-pp.lsp","cmd":"bpoly-pp","cat":"繪圖","desc":"在封閉聚合線範圍內以兩點畫線，找出與其他線的交點並建立封閉聚合線。","usage":"執行 bpoly-pp → 點選第一點 → 點選下一點 → 產生封閉聚合線","level":4,"lt":"✅","ver":"20240408","author":"chengshunyi","video":"","fas":"fas/bpoly-pp.fas"},{"no":257,"file":"bpoly2area.lsp","cmd":"bpoly2area","cat":"面積/數量統計","desc":"點選區域內部建立邊界聚合線，並以欄位文字顯示其面積（平方公尺）。","usage":"執行 bpoly2area → 點選區域內部 → 指定文字位置 → 完成","level":3,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"—","video":"","fas":"fas/bpoly2area.fas"},{"no":258,"file":"bpolycheck234-V1.lsp","cmd":"bpolycheck234","cat":"面積/數量統計","desc":"點選封閉區域自動判斷矩形、梯形、三角形、弧形、平行四邊形，並插入對應的面積計算動態圖塊。","usage":"執行 bpolycheck234 → 點選區域內部 → 自動判斷形狀並插入標註圖塊","level":9,"lt":"✅","ver":"2025-12-30 (檔案日期)","author":"—","video":"","fas":"fas/bpolycheck234-V1.fas"},{"no":259,"file":"bpolycheck234-VH.LSP","cmd":"bpolycheck234","cat":"面積/數量統計","desc":"點選封閉區域判斷形狀，不用圖塊而直接繪製交叉線、編號圓、高度線與面積計算式文字。","usage":"執行 bpolycheck234 → 點選區域內部 → 自動繪製標註與算式","level":7,"lt":"✅","ver":"2025-12-30 (檔案日期)","author":"—","video":"","fas":"fas/bpolycheck234-VH.fas"},{"no":260,"file":"bpolycheck234-ZW.LSP","cmd":"bpolycheck234","cat":"面積/數量統計","desc":"點選封閉區域，以向量運算判斷矩形、三角形、梯形、弧形、平行四邊形並插入面積圖塊與更新欄位。","usage":"執行 bpolycheck234 → 點選封閉區域 → 自動判斷並插入面積圖塊","level":7,"lt":"✅","ver":"20260928 重構版（初版 20231206）","author":"chengshunyi","video":"","fas":"fas/bpolycheck234-ZW.fas"},{"no":261,"file":"bpolycheck234.LSP","cmd":"bpolycheck234","cat":"面積/數量統計","desc":"點選封閉區域判斷形狀並插入面積圖塊，整合 DCL 設定介面並記住上次設定。","usage":"執行 bpolycheck234 → 對話框設定參數 → 點選封閉區域 → 自動插入面積圖塊","level":8,"lt":"⚠️","ver":"20260928 優化整合（初版 20231206）","author":"chengshunyi","video":"","fas":"fas/bpolycheck234.fas"},{"no":262,"file":"bpolycheck234pl-m.LSP","cmd":"bpolycheck234pl-m","cat":"面積/數量統計","desc":"選取封閉聚合線，自動修正方向與起點後判斷形狀，插入面積圖塊並更新欄位，修正梯形與平行四邊形誤判。","usage":"執行 bpolycheck234pl-m → 選封閉聚合線 → 自動插入面積圖塊","level":9,"lt":"✅","ver":"20241027","author":"chengshunyi","video":"","fas":"fas/bpolycheck234pl-m.fas"},{"no":263,"file":"bpolycheck234pl.LSP","cmd":"bpolycheck234pl","cat":"面積/數量統計","desc":"選取封閉聚合線，修正順逆時針與起點為左下角後判斷形狀，插入面積圖塊並更新欄位。","usage":"執行 bpolycheck234pl → 選封閉聚合線 → 自動插入面積圖塊","level":9,"lt":"✅","ver":"20250622（初版 20231206）","author":"chengshunyi","video":"","fas":"fas/bpolycheck234pl.fas"},{"no":264,"file":"bpolycheck235.lsp","cmd":"bpolycheck235","cat":"面積/數量統計","desc":"點選區域自動識別矩形、梯形、三角形、平行四邊形、弓形，並修正弧度近零的除以零錯誤後繪製標註。","usage":"執行 bpolycheck235 → 點選區域內部 → 自動繪製標註","level":7,"lt":"✅","ver":"2025-12-30 (檔案日期)","author":"—","video":"","fas":"fas/bpolycheck235.fas"},{"no":265,"file":"bpolycheck236.lsp","cmd":"bpolycheck236","cat":"面積/數量統計","desc":"點選區域判斷形狀，繪製高度虛線、紅色交叉線、編號圓與面積算式，支援含弧段的聚合線。","usage":"執行 bpolycheck236 → 依目前編號點選區域內部 → 自動標註","level":7,"lt":"✅","ver":"2025-12-31 (檔案日期)","author":"—","video":"","fas":"fas/bpolycheck236.fas"},{"no":266,"file":"bpolycheck237.LSP","cmd":"bpolycheck237","cat":"面積/數量統計","desc":"面積形狀判斷標註，建立專用圖層並將算式文字置於線段中點，保持易讀角度，附 DCL 設定。","usage":"執行 bpolycheck237 → 對話框設定 → 點選區域內部 → 自動標註","level":7,"lt":"✅","ver":"2025-12-31 (檔案日期)","author":"—","video":"","fas":"fas/bpolycheck237.fas"},{"no":267,"file":"bpolycheck250.lsp","cmd":"bpolycheck250","cat":"面積/數量統計","desc":"面積形狀判斷標註，新增繪製總計與底線，依各區面積累加並於列表下方寫出合計。","usage":"執行 bpolycheck250 → 對話框設定 → 逐一點選區域 → 結束後寫出總計","level":7,"lt":"✅","ver":"2026-01-01 (檔案日期)","author":"—","video":"","fas":"fas/bpolycheck250.fas"},{"no":268,"file":"bpolycheck262-AAC.LSP","cmd":"AAC、ArchiAreaCal","cat":"面積/數量統計","desc":"建築面積計算整合程式，支援圓形、矩形、平行四邊形等形狀的邊界識別、算式標註與總計。","usage":"執行 AAC → 對話框設定 → 點選區域 → 自動標註算式與編號","level":9,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"—","video":"","fas":"fas/bpolycheck262-AAC.fas"},{"no":269,"file":"BR-L.LSP","cmd":"br-l","cat":"繪圖","desc":"指定兩點繪製斷裂線（Z 字折線），折線大小隨 LTSCALE 調整。","usage":"執行 br-l → 指定第一點 → 指定第二點 → 繪出斷裂線","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/BR-L.fas"},{"no":270,"file":"BR-L2.LSP","cmd":"br-l2","cat":"繪圖","desc":"指定兩點繪製雙層斷裂線（兩條平行 Z 字折線），折線大小隨 LTSCALE 調整。","usage":"執行 br-l2 → 指定第一點 → 指定第二點 → 繪出雙斷裂線","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/BR-L2.fas"},{"no":271,"file":"BREAK-2.LSP","cmd":"break-2","cat":"修改","desc":"關閉物件鎖點後以兩點打斷物件。","usage":"執行 break-2 → 指定打斷第一點 → 指定第二點 → 完成","level":1,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/BREAK-2.fas"},{"no":272,"file":"Break-At-Dis.LSP","cmd":"Break-At-Dis","cat":"修改","desc":"依輸入距離逐步在曲線（線、弧、聚合線、雲形線）上打斷，並顯示總長度，可復原。","usage":"執行 Break-At-Dis → 選取曲線 → 輸入打斷距離（可 undo）→ 重複打斷","level":5,"lt":"✅","ver":"20240208","author":"chengshunyi（含 Alan J. Thompson 函式）","video":"","fas":"fas/Break-At-Dis.fas"},{"no":273,"file":"breakall.lsp","cmd":"breakall、BreakObject、breakwobjects、BreakWith、BreakTouching、BreakSelected","cat":"修改","desc":"在交點處打斷物件：全部相交打斷、單一物件被多物件打斷、多物件被單一物件打斷或指定物件互相打斷。","usage":"執行 breakall → 選取要打斷的物件 → Enter → 自動於交點打斷","level":5,"lt":"✅","ver":"20230902（原 v1.3 2007）","author":"Charles Alan Butler（chengshunyi 修改）","video":"","fas":"fas/breakall.fas"},{"no":274,"file":"brename.lsp","cmd":"BRename","cat":"圖塊/屬性","desc":"選取圖塊後顯示目前名稱並重新命名圖塊定義，名稱重複或不合法會提示。","usage":"執行 BRename → 選取圖塊 → 輸入新名稱","level":3,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"CAD Studio (cadstudio.cz)","video":"","fas":"fas/brename.fas"},{"no":275,"file":"BringThisTwoTogether.lsp","cmd":"BringThisTwoTogether","cat":"繪圖","desc":"選取兩條平行等長線段，在中間畫中心線並在端點打叉。","usage":"執行 BringThisTwoTogether → 選取兩條線 → 自動畫出中心線與 X","level":4,"lt":"✅","ver":"20241106","author":"—","video":"","fas":"fas/BringThisTwoTogether.fas"},{"no":276,"file":"brk-l-60d.LSP","cmd":"brk-l2-75d、brk-l1-75d、brk-l2-60d、brk-l1-60d","cat":"繪圖","desc":"繪製詳圖截斷線（60 度與 75 度折角，單線或雙線），尺寸依 LTSCALE 比例自動判斷。","usage":"執行 brk-l1-60d 等 → 指定截斷線兩端點 → 自動畫出截斷線","level":5,"lt":"✅","ver":"20231215（20240218 更新）","author":"chengshunyi","video":"","fas":"fas/brk-l-60d.fas"},{"no":277,"file":"brk-l.LSP","cmd":"brk-l2-s100、brk-l2、brk-l1","cat":"繪圖","desc":"繪製詳圖截斷線（90 度折角，單線或雙線，另有 1:100 版），長度間隔依 LTSCALE 區間判斷。","usage":"執行 brk-l1 或 brk-l2 → 指定截斷線兩端點 → 自動畫出截斷線","level":5,"lt":"✅","ver":"20231215（20240218 更新）","author":"chengshunyi","video":"https://youtu.be/67ZSuSEj9Ns","fas":"fas/brk-l.fas"},{"no":278,"file":"brk-pip.LSP","cmd":"brk-pip","cat":"繪圖","desc":"繪製管狀物（如管線）的截斷線。","usage":"執行 brk-pip → 指定截斷位置 → 繪出管狀截斷線","level":3,"lt":"✅","ver":"20231215","author":"CHENGSHUNYI","video":"https://youtu.be/8DmQyQuc0GQ","fas":"fas/brk-pip.fas"},{"no":279,"file":"bro.lsp","cmd":"BRo、BRo-ns、BRo-c、BRo-c-ns","cat":"圖塊/屬性","desc":"將選取圖塊的旋轉角度歸零，提供多種變體選擇處理方式。","usage":"執行 BRo → 選取圖塊 → 旋轉角自動歸零","level":3,"lt":"✅","ver":"2025-05-29 (檔案日期)","author":"—","video":"https://youtu.be/X0-Et1bM3RE","fas":"fas/bro.fas"},{"no":280,"file":"BRS.LSP","cmd":"BRS","cat":"圖塊/屬性","desc":"對話框確認後，選取圖塊並復原其旋轉與鏡射狀態，支援動態與匿名圖塊。","usage":"執行 BRS → 對話框按執行 → 選取圖塊 → 自動復原旋轉與鏡射","level":6,"lt":"✅","ver":"2026-06-06 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/BRS.fas"},{"no":281,"file":"BT.LSP","cmd":"bt","cat":"出圖/列印","desc":"對話框以幻燈片挑選封面、目錄、標題欄圖框，並插入對應圖塊。","usage":"執行 bt → 對話框選幻燈片（封面、圖框、目錄）→ 確定 → 指定插入點","level":6,"lt":"✅","ver":"90.06.06（20220716 更新）","author":"—","video":"","fas":"fas/BT.fas"},{"no":282,"file":"BubbleInc.LSP","cmd":"AA、QQ、ZZ","cat":"標註","desc":"連續遞增編號的多重引線氣泡標註，AA、QQ、ZZ 分別對應 A4、A3、A5 圖紙簡碼，可復原。","usage":"輸入 AA（或 QQ、ZZ）→ 輸入起始編號 → 點選標註點 → 點選編號位置 → 連續標註（可 Undo）","level":6,"lt":"✅","ver":"20250616 正式版","author":"Cheng BAR (MyCAD)","video":"","fas":"fas/BubbleInc.fas"},{"no":283,"file":"BuildDimStyles-27.lsp","cmd":"BuildDimStyles-27","cat":"標註","desc":"依小、中、大尺寸分類批次建立或更新所有 DIMSTYLE，設定文字與箭頭大小並套用指定圖塊箭頭。","usage":"執行 BuildDimStyles-27 → 自動建立各尺寸標註樣式","level":5,"lt":"✅","ver":"2025-09-06 (檔案日期)","author":"—","video":"","fas":"fas/BuildDimStyles-27.fas"},{"no":284,"file":"BuildDimStyles-Vl.LSP","cmd":"BuildDimStyles-Vl","cat":"標註","desc":"將目前系統變數強制套用到指定箭頭的 DIMSTYLE，缺樣式則建立並更新。","usage":"執行 BuildDimStyles-Vl → 自動強制更新標註樣式","level":5,"lt":"✅","ver":"2025-10-06 (檔案日期)","author":"—","video":"","fas":"fas/BuildDimStyles-Vl.fas"},{"no":285,"file":"BuilDIMStyles.lsp","cmd":"DimConfigSetup","cat":"標註","desc":"對話框選擇繪圖比例與單位，一次建立標準型與大中小各種組合的標註樣式。","usage":"執行 DimConfigSetup → 對話框選比例與單位 → 確定 → 自動建立所有標註樣式","level":6,"lt":"✅","ver":"20250914","author":"—","video":"https://youtu.be/lsFgxnQAjr4","fas":"fas/BuilDIMStyles.fas"},{"no":286,"file":"building.LSP","cmd":"building","cat":"其他","desc":"網路範例程式，示範以兩個下拉清單顯示建築名稱與地址的 DCL 對話框。","usage":"執行 building → 在對話框選取名稱與地址 → 確定","level":6,"lt":"✅","ver":"2024-12-27 (檔案日期)","author":"網路範例","video":"","fas":"fas/building.fas"},{"no":287,"file":"Burst.lsp","cmd":"pburst、nburst、burstall","cat":"圖塊/屬性","desc":"類似 Express Tools Burst 的分解圖塊，將可見屬性轉成文字後再分解，隱藏屬性不顯示。","usage":"執行 pburst → 選取圖塊 → 自動分解並保留屬性文字；burstall 處理全圖","level":6,"lt":"✅","ver":"2010（檔案日期 2025-12-03）","author":"Lee Mac","video":"https://youtu.be/2eE1vlP1jss","fas":"fas/Burst.fas"},{"no":288,"file":"BVTOLAYOUT.lsp","cmd":"BVTOLAYOUT","cat":"出圖/列印","desc":"對話框選取模型空間外框與內框範圍，依單位換算比例在指定配置建立視埠並放入 DEFPOINTS 圖層。","usage":"執行 BVTOLAYOUT → 對話框選單位與配置 → 點選外框與內框 → 自動建立視埠","level":7,"lt":"✅","ver":"2026-05-16 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/BVTOLAYOUT.fas"},{"no":289,"file":"C-BEAM.LSP","cmd":"（無，副程式庫）","cat":"剖面/結構","desc":"（加密檔 PROTECTED LISP，無法讀取原始碼）檔案為加密或編譯過的內容，無法讀取，依檔名推測為梁（C-BEAM）繪製相關程式。","usage":"載入後依檔名推測為梁相關指令（無法確認）","level":5,"lt":"❓","ver":"2021-03-28 (檔案日期)","author":"—","video":"","fas":"fas/C-BEAM.fas"},{"no":290,"file":"c-cal-eq.lsp","cmd":"c-cal-eq-A、c-cal-eq-S、c-cal-eq-M、c-cal-eq-D、c-cal-eq","cat":"文字","desc":"選取多個文字物件，擷取其中的數字進行加、減、乘、除運算，將算式與結果寫成新文字。","usage":"執行 c-cal-eq → 選 A/S/M/D → 依序選取文字 → 指定結果插入點","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/c-cal-eq.fas"},{"no":291,"file":"c-cal.LSP","cmd":"c-cal-A、c-cal-S、c-cal-M、c-cal-D、c-cal","cat":"文字","desc":"文字計算機，擷取選取文字中的數字（支援負值與單位後綴）做加減乘除並產生結果文字。","usage":"執行 c-cal-A（或 S、M、D）→ 依序選取文字 → 指定結果插入點","level":5,"lt":"✅","ver":"2024 更新（檔案日期 2026-02-08）","author":"—","video":"","fas":"fas/c-cal.fas"},{"no":292,"file":"C2TXT.LSP","cmd":"c2txt","cat":"文字","desc":"點選位置後將字元碼轉成文字逐一寫入圖面，字高固定 0.3。","usage":"執行 c2txt → 點選位置 → 自動寫入文字","level":2,"lt":"✅","ver":"2021-02-24 (檔案日期)","author":"—","video":"","fas":"fas/C2TXT.fas"},{"no":293,"file":"C_layj.lsp","cmd":"layj","cat":"圖層","desc":"選取物件後以 Lee Mac 清單對話框挑選線型，更改該物件所在圖層的線型。","usage":"執行 layj → 選取物件 → 對話框選線型 → 確定","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"Lee Mac（清單對話框）","video":"","fas":"fas/C_layj.fas"},{"no":294,"file":"cab3d.lsp","cmd":"cab3d","cat":"3D","desc":"對話框從 cab3d.dat 資料檔挑選櫃體樣式與尺寸，繪製剖面、拉伸並布林減去，產生 3D 櫃體實體。","usage":"執行 cab3d → 對話框選櫃體樣式與尺寸 → 確定 → 指定位置 → 產生 3D 櫃體","level":7,"lt":"❌","ver":"2025-10-24 (檔案日期)","author":"—","video":"","fas":"fas/cab3d.fas"},{"no":295,"file":"cal-mline.lsp","cmd":"cal-mline","cat":"面積/數量統計","desc":"計算選取多線（MLINE）的長度合計，並將結果寫入文字檔或 Excel。","usage":"執行 cal-mline → 選取多線 → 指定輸出檔案 → 寫出結果","level":8,"lt":"⚠️","ver":"20220716","author":"—","video":"","fas":"fas/cal-mline.fas"},{"no":296,"file":"CalcPlineLength.lsp","cmd":"CalcPlineLength","cat":"查詢","desc":"計算選取聚合線的總周長，依全域單位係數（cm 換 m）換算並四捨五入顯示。","usage":"執行 CalcPlineLength → 選取聚合線 → 顯示總周長","level":4,"lt":"✅","ver":"2025-08-17 (檔案日期)","author":"—","video":"","fas":"fas/CalcPlineLength.fas"},{"no":297,"file":"CALDLG.LSP","cmd":"caldlg","cat":"查詢","desc":"以對話框數字鍵盤提供簡易計算機，可於圖面計算並顯示結果。","usage":"執行 caldlg → 在對話框按鍵輸入算式 → 查看結果","level":6,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/CALDLG.fas"},{"no":298,"file":"calender.lsp","cmd":"calendar、calendar-m-lastday、calendar-lastm-lastday、calendar-lastyy-lastmm、calendar-curyy-lastmm","cat":"其他","desc":"以聚合線與文字在圖面繪製任意年份的月曆，可選多種排列方式與比例，另有以月底日期為基準的快捷指令。","usage":"執行 calendar → 輸入年份與排列方式 → 指定位置與比例 → 自動繪出月曆","level":7,"lt":"✅","ver":"28-08-91（檔案日期 2024-08-18）","author":"James Tunstall (Autodesk Australia)","video":"","fas":"fas/calender.fas"},{"no":299,"file":"CAR-BLK-COLOR-PL-V1.lsp","cmd":"CAR-BLK-COLOR-PL","cat":"圖塊/屬性","desc":"對話框設定比例、透明度、線寬與法定/自設/其他顏色，將停車位圖塊內聚合線偏移套色並寫入 INI 記憶。","usage":"執行 CAR-BLK-COLOR-PL → 對話框設定參數 → 點選車位圖塊 → 自動套色","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/CAR-BLK-COLOR-PL-V1.fas"},{"no":300,"file":"CAR-BLK-COLOR-PL.lsp","cmd":"CAR-BLK-COLOR-PL","cat":"圖塊/屬性","desc":"對話框設定比例、透明度、線寬，點選停車位圖塊後處理圖塊定義中的聚合線，偏移套色並置底。","usage":"執行 CAR-BLK-COLOR-PL → 對話框設定比例、透明度、線寬 → 點選車位圖塊 → 自動套色","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/CAR-BLK-COLOR-PL.fas"},{"no":301,"file":"CAR-BLK-COLOR-SOLID.lsp","cmd":"CAR-BLK-COLOR-SOLID","cat":"圖塊/屬性","desc":"對話框設定參數後，點選停車位圖塊，以實心填充（HATCH）為車位套色並調整透明度與線寬。","usage":"執行 CAR-BLK-COLOR-SOLID → 對話框設定 → 點選車位圖塊 → 自動產生實心填充","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/CAR-BLK-COLOR-SOLID.fas"},{"no":302,"file":"CAR-BLK-COLOR-UI-W.LSP","cmd":"CAR-BLK-COLOR-UI-W","cat":"圖塊/屬性","desc":"停車空間套色整合介面（出圖線寬版），含法定/自設/其他顏色預覽，可選 PL 或實心填充並記憶 INI 設定。","usage":"執行 CAR-BLK-COLOR-UI-W → 對話框設定比例、透明度、線寬、顏色與模式 → 選取車位圖塊 → 套色","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/CAR-BLK-COLOR-UI-W.fas"},{"no":303,"file":"CAR-BLK-COLOR-UI.LSP","cmd":"CAR-BLK-COLOR-UI","cat":"圖塊/屬性","desc":"停車空間套色整合介面，含顏色預覽，可選聚合線或實心填充模式，並記憶 INI 設定。","usage":"執行 CAR-BLK-COLOR-UI → 對話框設定比例、透明度、線寬、顏色與模式 → 選取車位圖塊 → 套色","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/CAR-BLK-COLOR-UI.fas"},{"no":304,"file":"CAR-BLK-COLORxx.lsp","cmd":"CAR-BLK-COLOR-UI、CAR-BLK-COLOR","cat":"圖塊/屬性","desc":"停車空間套色設定介面的舊版，對話框設定比例、透明度、線寬與顏色，可選只做聚合線（PL）。","usage":"執行 CAR-BLK-COLOR-UI → 對話框設定 → 選取車位圖塊 → 套色","level":6,"lt":"✅","ver":"2025-10-31 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/CAR-BLK-COLORxx.fas"},{"no":305,"file":"CAR-DYBLK-COLOR.lsp","cmd":"car-dyblk-color","cat":"圖塊/屬性","desc":"對話框選模式，依屬性 CAT1 批次切換車位動態圖塊的可見性（法定、自設、其它）並寫出紀錄檔。","usage":"執行 car-dyblk-color → 對話框選模式 → 確定 → 自動切換所有車位圖塊可見性","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/CAR-DYBLK-COLOR.fas"},{"no":306,"file":"CAR-NU.LSP","cmd":"car-nu","cat":"文字","desc":"連續插入車位編號，記住上次號碼並可指定起始編號與車位方向。","usage":"執行 car-nu → 輸入起始編號 → 點選車位位置 → 輸入方向 → 連續編號","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/CAR-NU.fas"},{"no":307,"file":"car-p.lsp","cmd":"car-p、car-p-main","cat":"繪圖","desc":"對話框選擇四角、上緣、下緣、左右兩側位置，於柱邊連續放置防撞護角圖塊並支援旋轉柱。","usage":"執行 car-p → 對話框選位置 → 確定 → 連續點選柱的矩形 → 自動放置護角","level":6,"lt":"✅","ver":"2026-04-03 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/car-p.fas"},{"no":308,"file":"CARS-NU.LSP","cmd":"cars-nu","cat":"文字","desc":"連續插入小型車位編號，記住上次號碼並可指定起始編號。","usage":"執行 cars-nu → 輸入起始編號 → 點選車位位置 → 輸入方向 → 連續編號","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/CARS-NU.fas"},{"no":309,"file":"CarSort-ppl.lsp","cmd":"CarSort-ppl","cat":"文字","desc":"車位自動編號系統，可用聚合線或兩點切選車位，依路徑連續編號，支援 CARNUM、CARNUM2、CARNUM3 多屬性續編。","usage":"執行 CarSort-ppl → 對話框設定起始編號與位數 → 選取方式（聚合線或兩點）→ 選取車位 → 自動排序編號","level":8,"lt":"✅","ver":"v7.0","author":"ChengBar (Shun_Yi Studio)","video":"","fas":"fas/CarSort-ppl.fas"},{"no":310,"file":"CB_AMTP.lsp","cmd":"CB_AMTP","cat":"文字","desc":"AnnoMText Pro，切換與調整多行文字可註解屬性、字高、正中對齊、寬度歸零與字體，支援五組空間名稱圖層與字高預設。","usage":"執行 CB_AMTP → 對話框設定五組圖層與字高 → 選取多行文字 → 套用調整","level":8,"lt":"✅","ver":"2026/07/11","author":"ChengBar (Shun_Yi Studio)","video":"","fas":"fas/CB_AMTP.fas"},{"no":311,"file":"CB_LAYOUTPLOTTOPDF.lsp","cmd":"CB_LAYOUTPLOTTOPDF","cat":"出圖/列印","desc":"Layout 批次出圖 PDF 介面，選 PC3、紙張、CTB 與要輸出的配置，加入清單後批次列印並記住設定。","usage":"執行 CB_LAYOUTPLOTTOPDF → 選 PC3、紙張、CTB → 加入配置清單 → 確定 → 批次輸出 PDF","level":8,"lt":"✅","ver":"2026-08-19 (檔案日期)","author":"ChengBar","video":"","fas":"fas/CB_LAYOUTPLOTTOPDF.fas"},{"no":312,"file":"CB_VIEWSIM.lsp","cmd":"CB_VIEWSIM","cat":"系統/授權","desc":"視圖模擬鏡射與旋轉工具，對話框選水平／垂直鏡射與 0/90/180/270 度或自訂角度，模擬檢視視圖。","usage":"執行 CB_VIEWSIM → 對話框選鏡射模式與旋轉角度 → 確定 → 視圖依設定翻轉","level":6,"lt":"✅","ver":"2026-07-30 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":""},{"no":313,"file":"CBAREA.lsp","cmd":"CBAREA、CB_AREA、PLAREA","cat":"面積/數量統計","desc":"封閉聚合線面積標示與計算系統，支援多種單位（含坪、才）、自動編號、填色、計算式加總，並檢查與修復重複編號。","usage":"執行 CBAREA → 對話框設定單位、字高、編號與填色 → 選取封閉聚合線 → 標示面積與總計","level":9,"lt":"⚠️","ver":"2026-09-28 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/CBAREA.fas"},{"no":314,"file":"CBV.lsp","cmd":"CBV","cat":"系統/授權","desc":"座標與視窗轉正整合工具箱，以 UCS 與 DVIEW 對齊物件或三點，並可命名儲存 UCS、快速扭轉視窗。","usage":"執行 CBV → 對話框選使用已命名 UCS、點選物件或三點對齊、設定扭轉角度 → 執行","level":7,"lt":"⚠️","ver":"v6.0","author":"ChengBar (Shun_Yi Studio)","video":"","fas":""},{"no":315,"file":"CDA-B-F.lsp","cmd":"CDA-B-F","cat":"標註","desc":"選取 CDN-A 座標圖塊，將其屬性依序填入放樣座標表格，並以欄位連動屬性值。","usage":"執行 CDA-B-F → 選取 CDN-A 圖塊 → 指定表格位置 → 產生放樣座標表","level":8,"lt":"✅","ver":"20230322","author":"chengshunyi（改自 CADTutor 論壇）","video":"","fas":"fas/CDA-B-F.fas"},{"no":316,"file":"CDA-B-W-F.lsp","cmd":"CDA-B-W-F","cat":"標註","desc":"窗選 CDN-A 座標圖塊，依單位與比例係數輸出放樣座標表格，並以欄位連動屬性值。","usage":"執行 CDA-B-W-F → 窗選 CDN-A 圖塊 → 指定表格位置 → 產生放樣座標表","level":8,"lt":"✅","ver":"20240423","author":"chengshunyi（改自 CADTutor 論壇）","video":"","fas":"fas/CDA-B-W-F.fas"},{"no":317,"file":"CDA-B-W.lsp","cmd":"CDA-B-W","cat":"標註","desc":"窗選 CDN-A 座標圖塊，將座標屬性依序寫入放樣座標表格（含匿名動態圖塊）。","usage":"執行 CDA-B-W → 窗選 CDN-A 圖塊 → 指定表格位置 → 產生放樣座標表","level":8,"lt":"✅","ver":"20240423","author":"chengshunyi","video":"","fas":"fas/CDA-B-W.fas"},{"no":318,"file":"CDA-B.lsp","cmd":"CDA-B","cat":"標註","desc":"選取 CDN-A 座標圖塊，依屬性排序後寫入放樣座標表格，支援外部參考內的圖塊。","usage":"執行 CDA-B → 選取 CDN-A 圖塊 → 指定表格位置 → 產生放樣座標表","level":8,"lt":"✅","ver":"20230322","author":"chengshunyi（改自 CADTutor 論壇）","video":"","fas":"fas/CDA-B.fas"},{"no":319,"file":"cdgplot4.lsp","cmd":"CPL2","cat":"出圖/列印","desc":"CDG 圖紙批次出圖工具，對話框選圖紙頁籤與輸出目的（PLT、PDF、DWF、印表機），自動偵測紙張尺寸後列印。","usage":"執行 CPL2 → 對話框選頁籤與輸出類別 → 確定 → 自動批次出圖","level":8,"lt":"✅","ver":"2014-06-30（檔案日期 2023-06-29）","author":"CDG 公司（CWB、SMO 修改）","video":"","fas":"fas/cdgplot4.fas"},{"no":320,"file":"CDNINS.lsp","cmd":"CDNINS","cat":"標註","desc":"選聚合線依節點插入座標圖塊，可將平面座標轉為經緯度（TWD97 TM2 轉 WGS84），可自動標註弧段圓心與虛線，並輸出座標清單。","usage":"執行 CDNINS → 對話框設定起始編號、單位與方向 → 選取聚合線 → 插入座標圖塊並輸出清單","level":9,"lt":"⚠️","ver":"2026-09 更新","author":"ChengBar (MyCAD)","video":"","fas":"fas/CDNINS.fas"},{"no":321,"file":"CDP-demo-1.LSP","cmd":"ADD_PROPS、GET_PROPS","cat":"圖面管理","desc":"示範以 SummaryInfo 介面新增與讀取圖檔標準及自訂內容資訊（標題、主旨、作者、關鍵字等）。","usage":"載入後執行 ADD_PROPS 新增圖檔資訊 → 執行 GET_PROPS 讀取","level":5,"lt":"✅","ver":"20230408","author":"CHENGSHUNYI（取自 Autodesk 說明範例）","video":"","fas":"fas/CDP-demo-1.fas"},{"no":322,"file":"CDP-demo-2.LSP","cmd":"PROPOUT、PROPIN、PROPIN-update","cat":"圖面管理","desc":"將圖檔自訂內容資訊匯出成文字檔，或從文字檔匯入／更新到目前圖檔。","usage":"執行 PROPOUT → 指定檔名儲存；PROPIN → 選取內容資訊檔匯入；PROPIN-update 更新","level":8,"lt":"✅","ver":"20230408","author":"CHENGSHUNYI","video":"","fas":"fas/CDP-demo-2.fas"},{"no":323,"file":"CDP-demo.lsp","cmd":"CDP-demo","cat":"圖面管理","desc":"讀取 projectgegevens.txt，將專案資訊（委託人、專案等）寫入圖檔內容資訊。","usage":"執行 CDP-demo → 自動讀檔並寫入圖檔資訊","level":8,"lt":"✅","ver":"2023-04-08","author":"CHENGSHUNYI","video":"","fas":"fas/CDP-demo.fas"},{"no":324,"file":"CDP-USP.LSP","cmd":"CDP-USP、CDP-readbykey","cat":"圖面管理","desc":"讀取圖檔自訂內容資訊中的單位（U）、比例（S）、圖紙（P）等設定值。","usage":"執行 CDP-USP → 讀取並顯示或設定單位、比例、圖紙","level":5,"lt":"✅","ver":"2023-04-08","author":"CHENGSHUNYI","video":"","fas":"fas/CDP-USP.fas"},{"no":325,"file":"ceiling-area-c-lays.lsp","cmd":"ceiling-area-c-lays","cat":"圖層","desc":"檢查並建立各種天花板材質的面積計算圖層（T 型明架礦纖板、暗架防潮板、矽酸鈣板等）。","usage":"執行 ceiling-area-c-lays → 自動建立天花面積圖層","level":3,"lt":"✅","ver":"20241006","author":"chengshunyi","video":"","fas":"fas/ceiling-area-c-lays.fas"},{"no":326,"file":"CeilingGrid.LSP","cmd":"CeilingGrid","cat":"繪圖","desc":"在封閉聚合線範圍內自動繪製天花水平與垂直分格線，可依線段角度旋轉並統計整格與餘格數量與線長。","usage":"執行 CeilingGrid → 對話框設定格尺寸 → 選封閉聚合線 → 點選分格起點與對應位置 → 繪格線並顯示統計","level":8,"lt":"✅","ver":"V1.1.1 2026-10-25","author":"ChengBar (MyCAD)","video":"","fas":"fas/CeilingGrid.fas"},{"no":327,"file":"centerPline.LSP","cmd":"CPL","cat":"繪圖","desc":"選取兩條聚合線，繪製其中間的中心線（曲線以雲形線表示），利用 loft 與 Express Tools 展平計算。","usage":"執行 CPL → 選第一條聚合線 → 選第二條聚合線 → 產生中心線","level":8,"lt":"❌","ver":"1.0 21.12.2013（檔案日期 2024-04-03）","author":"Gian Paolo Cattaneo","video":"","fas":"fas/centerPline.fas"},{"no":328,"file":"CF-Earthwork-ui.lsp","cmd":"CF-Earthwork-ui","cat":"剖面/結構","desc":"依設計線與地面線求交點，計算各區間挖方與填方面積與體積，對話框設定比例、字高與深度並著色標註。","usage":"執行 CF-Earthwork-ui → 對話框設定比例、字高係數、深度 → 選設計線與地面線 → 自動標註挖填方","level":8,"lt":"✅","ver":"2026-11-05 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/CF-Earthwork-ui.fas"},{"no":329,"file":"CF-Earthwork.lsp","cmd":"CF-Earthwork","cat":"剖面/結構","desc":"依設計線與地面線求交點，計算各區間挖方（紅）與填方（綠）面積，建立圖層與字型並標註。","usage":"執行 CF-Earthwork → 輸入比例與字高係數 → 選設計線與地面線 → 自動標註挖填方","level":8,"lt":"✅","ver":"2026-02-10 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/CF-Earthwork.fas"},{"no":330,"file":"CF.LSP","cmd":"cf","cat":"剖面/結構","desc":"Cut and Fill 挖填方計算修正版，對話框設定深度與縮放，先四捨五入面積再加總，填色後置底。","usage":"執行 cf → 對話框設定深度、縮放與文字定位 → 選設計線與地面線 → 自動標註挖填方","level":8,"lt":"✅","ver":"2026-02-10 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/CF.fas"},{"no":331,"file":"CF4M.lsp","cmd":"CF4M","cat":"修改","desc":"連續倒角／圓角工具，雙語對話框（中文／English）切換，可連續執行多組倒角與圓角。","usage":"執行 CF4M → 對話框選模式與距離 → 確定 → 連續選取兩物件倒角或圓角","level":6,"lt":"⚠️","ver":"2026 修正版","author":"ChengBar (MyCAD)","video":"","fas":"fas/CF4M.fas"},{"no":332,"file":"ch-all-ml.lsp","cmd":"ch-all-ml","cat":"修改","desc":"重建 WALL-V 圖層所有多線（MLINE）為開放端（-OPEN）樣式，保留圖層、比例與對正，刪除原多線。","usage":"執行 ch-all-ml → 自動處理 WALL-V 圖層所有多線","level":4,"lt":"✅","ver":"2008.05.10（20220716 更新）","author":"—","video":"","fas":"fas/ch-all-ml.fas"},{"no":333,"file":"ch-any-text.lsp","cmd":"ch-any-text","cat":"文字","desc":"以 Lee Mac 編輯框對話框修改選取文字或屬性的內容，不限文字型態。","usage":"執行 ch-any-text → 選取文字或屬性 → 在對話框修改內容 → 確定","level":6,"lt":"✅","ver":"20240302","author":"Lee Mac（chengshunyi 修改）","video":"","fas":"fas/ch-any-text.fas"},{"no":334,"file":"ch-area-gb-h.LSP","cmd":"ch-area-gb-h","cat":"面積/數量統計","desc":"對話框輸入牆高，計算 MY_GM 圖塊（含動態圖塊）的牆面綠建材面積，並更新圖塊屬性值。","usage":"執行 ch-area-gb-h → 選取 MY_GM 圖塊 → 對話框輸入牆高 → 自動更新屬性","level":6,"lt":"✅","ver":"2026-08-30 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/ch-area-gb-h.fas"},{"no":335,"file":"ch-axb-blk-layer.LSP","cmd":"ch-axb-blk-layer","cat":"圖層","desc":"依圖塊類型改圖層：外部參考改到 xref 圖層，一般圖塊到 block 圖層，有屬性的圖塊到 a-block 圖層。","usage":"執行 ch-axb-blk-layer → 自動處理全圖圖塊與外部參考","level":3,"lt":"✅","ver":"20210623（20220716 更新）","author":"CHENGBAR","video":"","fas":"fas/ch-axb-blk-layer.fas"},{"no":336,"file":"CH-B-SCA.LSP","cmd":"ch-b-sca","cat":"圖塊/屬性","desc":"依輸入的圖塊名稱，將全圖該圖塊以新比例縮放，並同步調整屬性位置與字高。","usage":"執行 ch-b-sca → 輸入圖塊名稱 → 輸入新比例 → 自動調整所有該圖塊與屬性","level":6,"lt":"✅","ver":"84.5.19 84.6.7 84.7.6（20220716 更新）","author":"Cheng Shun Yi","video":"","fas":"fas/CH-B-SCA.fas"},{"no":337,"file":"ch-bl-att-h.lsp","cmd":"ch-bl-att-h","cat":"圖塊/屬性","desc":"依圖塊名稱批次調整特定屬性的字高，並設定圖層與顏色 ByLayer。","usage":"執行 ch-bl-att-h → 選取圖塊 → 點選要調整的屬性 → 輸入字高","level":6,"lt":"✅","ver":"20231218","author":"chengshunyi","video":"","fas":"fas/ch-bl-att-h.fas"},{"no":338,"file":"ch-bl-att-w.lsp","cmd":"ch-bl-att-w","cat":"圖塊/屬性","desc":"依圖塊名稱批次調整特定屬性的字寬比例，並設定圖層與顏色 ByLayer。","usage":"執行 ch-bl-att-w → 選取圖塊 → 點選要調整的屬性 → 輸入字寬","level":6,"lt":"✅","ver":"20231218","author":"chengshunyi","video":"","fas":"fas/ch-bl-att-w.fas"},{"no":339,"file":"ch-bl-color.LSP","cmd":"blcc、encc","cat":"圖塊/屬性","desc":"blcc 變更所選圖塊的顏色；encc 變更所選物件（可為圖塊內元素）的顏色。","usage":"執行 blcc 或 encc → 選取圖塊或物件 → 輸入顏色","level":5,"lt":"✅","ver":"20211225（20220716 更新）","author":"Alaspher（forum.dwg.ru 網路程式）","video":"","fas":"fas/ch-bl-color.fas"},{"no":340,"file":"CH-BL-EL-TX.LSP","cmd":"ch-bl-el-tx","cat":"標註","desc":"自動修改高程圖塊標註：指定基準點後，依各圖塊 Y 座標算出相對高程，更新屬性並補零顯示。","usage":"執行 ch-bl-el-tx → 輸入圖塊名稱、屬性標籤、字高 → 指定基準點 GL → 自動更新所有高程屬性","level":6,"lt":"✅","ver":"94.10.14 97.03.07（20220716 更新）","author":"Cheng Shun-Yi","video":"","fas":"fas/CH-BL-EL-TX.fas"},{"no":341,"file":"CH-BL-EL-TX1-CM.LSP","cmd":"ch-bl-el-tx1-cm","cat":"標註","desc":"自動修改高程圖塊標註的相對高程版（公分單位），指定基準高程圖塊後依各圖塊 Y 座標更新屬性。","usage":"執行 ch-bl-el-tx1-cm → 輸入圖塊名稱、屬性標籤、字高 → 選基準高程圖塊與基準點 → 自動更新","level":6,"lt":"✅","ver":"2008.04.13（20220716 更新）","author":"Cheng Shun-Yi","video":"","fas":"fas/CH-BL-EL-TX1-CM.fas"},{"no":342,"file":"CH-BL-EL-TX1.LSP","cmd":"ch-bl-el-tx1","cat":"標註","desc":"自動修改高程圖塊標註的相對高程版，指定基準高程圖塊後依各圖塊 Y 座標更新屬性，可判斷 mm 或 cm 單位。","usage":"執行 ch-bl-el-tx1 → 輸入圖塊名稱、屬性標籤、字高 → 選基準高程圖塊與基準點 → 自動更新","level":6,"lt":"✅","ver":"2008.04.13（20220716 更新）","author":"Cheng Shun-Yi","video":"","fas":"fas/CH-BL-EL-TX1.fas"},{"no":343,"file":"CH-BL-EL-TX3.LSP","cmd":"ch-bl-el-tx3","cat":"標註","desc":"自動修改高程圖塊標註，指定基準點 GL 後依圖塊 Y 座標換算相對高程，更新屬性並補零。","usage":"執行 ch-bl-el-tx3 → 輸入圖塊名稱、屬性標籤、字高 → 指定基準點 GL → 自動更新","level":6,"lt":"✅","ver":"94.10.14 97.03.07（20220716 更新）","author":"Cheng Shun-Yi","video":"","fas":"fas/CH-BL-EL-TX3.fas"},{"no":344,"file":"CH-BL-FL-TX.LSP","cmd":"ch-bl-fl-tx","cat":"標註","desc":"自動修改樓層高程圖塊標註，依 Y 值排序圖塊後以 LEVEL 屬性寫入各層高程。","usage":"執行 ch-bl-fl-tx → 輸入圖塊名稱、屬性標籤、字高 → 自動依 Y 值排序並更新屬性","level":6,"lt":"✅","ver":"94.10.17（20220716 更新）","author":"Cheng Shun-Yi","video":"","fas":"fas/CH-BL-FL-TX.fas"},{"no":345,"file":"ch-blk-att-va.lsp","cmd":"ch-blk-att-va","cat":"圖塊/屬性","desc":"選取圖塊後修改指定標籤屬性的值（如設為 EL0），採 Lee Mac 的屬性設值函式。","usage":"執行 ch-blk-att-va → 選取圖塊 → 自動將指定屬性值改寫","level":5,"lt":"✅","ver":"20240319","author":"chengshunyi（含 Lee Mac 函式）","video":"","fas":"fas/ch-blk-att-va.fas"},{"no":346,"file":"ch-blk-ent-lay.lsp","cmd":"ch-blk-ent-lay","cat":"圖層","desc":"對話框選擇圖層，將選取屬性圖塊內的物件改到指定圖層，並同步屬性定義。","usage":"執行 ch-blk-ent-lay → 選取屬性圖塊 → 對話框選圖層 → 確定 → 自動變更並同步","level":6,"lt":"✅","ver":"20240221（原 Tharwat 2014）","author":"chengshunyi（原作 Tharwat）","video":"","fas":"fas/ch-blk-ent-lay.fas"},{"no":347,"file":"ch-blk-plw-zero.LSP","cmd":"ch-blk-plw-zero","cat":"圖塊/屬性","desc":"將圖面所有圖塊定義內的聚合線線寬改為 0。","usage":"執行 ch-blk-plw-zero → 自動處理所有圖塊內聚合線","level":3,"lt":"✅","ver":"20240328","author":"chengshunyi","video":"","fas":"fas/ch-blk-plw-zero.fas"},{"no":348,"file":"ch-color-rgb.lsp","cmd":"ch-color-rgb、createpresentationlayers","cat":"圖層","desc":"以 RGB 真彩色建立簡報用圖層（水、樹、混凝土、草地、標誌等 Pantone 色），並提供 RGB 轉真彩色函式。","usage":"執行 createpresentationlayers → 自動建立並設定各圖層真彩色；ch-color-rgb 為色彩設定","level":5,"lt":"⚠️","ver":"20240607","author":"chengshunyi（含 Lee Mac RGB->True）","video":"","fas":"fas/ch-color-rgb.fas"},{"no":349,"file":"ch-dim-LSF.lsp","cmd":"ch-dim-LSF","cat":"標註","desc":"依當前比例與目標比例（如 200/50）修改選取標註的長度係數與延伸線、尺寸線延伸等尺寸參數。","usage":"執行 ch-dim-LSF → 輸入「當前比例/目標比例」→ 選取標註 → 自動修改","level":5,"lt":"✅","ver":"20240206","author":"chengshunyi","video":"","fas":"fas/ch-dim-LSF.fas"},{"no":350,"file":"ch-dim-spec-c.lsp","cmd":"ch-dim-spec-c","cat":"標註","desc":"將選取標註設為斜線箭頭、指定線寬與灰色延伸線與尺寸線，用於電梯圖說整理。","usage":"執行 ch-dim-spec-c → 選取標註 → 自動套用樣式","level":5,"lt":"✅","ver":"2022-06-28","author":"Tharwat Al Choufi（chengshunyi 修改）","video":"","fas":"fas/ch-dim-spec-c.fas"},{"no":351,"file":"CH-DIM-ST.LSP","cmd":"ch-dim-st、ch-dim-ct、ch-dim-stm","cat":"標註","desc":"將指定圖層的標註物件改為斜線、圓點或其他標註樣式（slashm、cirm）。","usage":"執行 ch-dim-st → 輸入舊圖層 → 輸入新圖層 → 自動改變標註樣式","level":4,"lt":"✅","ver":"95.01.23","author":"—","video":"https://youtu.be/wq32L4ErqA8","fas":"fas/CH-DIM-ST.fas"},{"no":352,"file":"ch-dim-sty.lsp","cmd":"SLASHM、SLASHcirM、cirSLASHM、dotM、cirM","cat":"標註","desc":"建立 dim-8、dim-pak、dim-lic、dim-chk 等標註圖層，並將選取標註改為斜線、圓點、圓圈等樣式。","usage":"執行 SLASHM（或 dotM、cirM 等）→ 選取標註 → 自動套用樣式與圖層","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/ch-dim-sty.fas"},{"no":353,"file":"CH-DIMSTY-PROP.lsp","cmd":"CH-DIMSTY-PROP","cat":"標註","desc":"將選取標註改為指定樣式（pl-dim、pl-dim2）並設定箭頭、文字高度等尺寸變數。","usage":"執行 CH-DIMSTY-PROP → 選取標註 → 自動套用樣式與變數","level":4,"lt":"✅","ver":"2023-06-02 (檔案日期)","author":"—","video":"","fas":"fas/CH-DIMSTY-PROP.fas"},{"no":354,"file":"ch-dy-blk-sca-area.lsp","cmd":"ch-dy-blk-sca-area-ui、ch-dy-blk-sca-area","cat":"面積/數量統計","desc":"面積索引動態圖塊依比例尺縮放，並將縮放後的尺寸值寫回動態屬性，可用對話框或命令列輸入比例。","usage":"執行 ch-dy-blk-sca-area-ui → 對話框選比例尺 → 選取面積索引圖塊 → 自動縮放並回寫屬性","level":7,"lt":"✅","ver":"20250803（除錯優化 2026-10-28）","author":"chengshunyi","video":"","fas":"fas/ch-dy-blk-sca-area.fas"},{"no":355,"file":"ch-dy-blk-sca.lsp","cmd":"ch-dy-blk-sca、ch-dy-blk-sca-t、ch-dy-blk-sca-p、ch-dy-blk-sca-3、ch-dy-blk-sca-A","cat":"圖塊/屬性","desc":"動態圖塊縮放工具，處理矩形、梯形、平行四邊形、三角形、弧形面積圖塊，縮放後依序寫回動態屬性。","usage":"執行 ch-dy-blk-sca → 選取圖塊 → 輸入縮放比例（如 100）→ 自動縮放並還原屬性","level":7,"lt":"✅","ver":"20230112（除錯優化 2026-10-28）","author":"chengshunyi","video":"","fas":"fas/ch-dy-blk-sca.fas"},{"no":356,"file":"CH-ELV.LSP","cmd":"CH-ELV","cat":"修改","desc":"將 LINE、ARC、聚合線、SPLINE、TEXT、圖塊、HATCH、標註等物件的 Z 值（標高）全部歸零，XY 位置不變。","usage":"執行 CH-ELV → 對話框選範圍（全圖或選取）與物件類型 → 確定 → 顯示各類型修改數量","level":9,"lt":"⚠️","ver":"v2.1.0 2026-11-11（初版 2003-03-11）","author":"ChengBar (MyCAD)","video":"https://youtu.be/d8bpGKHBzPY","fas":"fas/CH-ELV.fas"},{"no":357,"file":"ch-hatch.lsp","cmd":"H5","cat":"修改","desc":"限制只選取填充線（排除鎖定圖層物件），呼叫 -HATCHEDIT 修改填充圖案，預設 ansi32。","usage":"執行 H5 → 選取填充線 → 輸入新圖案設定","level":1,"lt":"✅","ver":"2022-02-28 (檔案日期)","author":"—","video":"","fas":"fas/ch-hatch.fas"},{"no":358,"file":"ch-last-dim-sca.lsp","cmd":"ch-last-dim-sca","cat":"標註","desc":"取得最後一個物件，若為標註則套用預設的標註設定，並強制 DIMSCALE 為 1。","usage":"執行 ch-last-dim-sca → 自動套用至最後建立的標註","level":5,"lt":"✅","ver":"2025-09-22 (檔案日期)","author":"—","video":"https://youtu.be/OP_z3TIaOJ8","fas":"fas/ch-last-dim-sca.fas"},{"no":359,"file":"ch-last-dims.lsp","cmd":"ch-last-dims","cat":"標註","desc":"選取標註後依比例調整延伸線、文字高度等參數並強制 DIMSCALE 為 1。","usage":"執行 ch-last-dims → 選取標註 → 輸入比例 → 自動修改","level":5,"lt":"✅","ver":"2025-03-17 (檔案日期)","author":"—","video":"","fas":"fas/ch-last-dims.fas"},{"no":360,"file":"ch-lay-tab-color.lsp","cmd":"ch-lay-tab-color","cat":"圖層","desc":"將圖層表中某個區間的圖層顏色一次改成同一個顏色。","usage":"執行 ch-lay-tab-color → 自動修改指定區間圖層顏色","level":3,"lt":"✅","ver":"20240720","author":"chengshunyi","video":"","fas":"fas/ch-lay-tab-color.fas"},{"no":361,"file":"ch-ml.lsp","cmd":"ch-ml","cat":"繪圖","desc":"選取來源線、聚合線或多線，依其頂點以目前多線樣式重新畫成多線。","usage":"執行 ch-ml → 選取來源物件 → 自動產生多線","level":4,"lt":"✅","ver":"2008.05.10（20220716 更新）","author":"—","video":"","fas":"fas/ch-ml.fas"},{"no":362,"file":"ch-mleader-style.LSP","cmd":"ch-mleader-style","cat":"標註","desc":"將選取的多重引線改為指定的既有多重引線樣式。","usage":"執行 ch-mleader-style → 選取多重引線 → 自動套用樣式","level":3,"lt":"✅","ver":"20240430","author":"—","video":"","fas":"fas/ch-mleader-style.fas"},{"no":363,"file":"ch-mltext-color.lsp","cmd":"colorchange、test、TEST2、TEST3","cat":"標註","desc":"嘗試將多重引線內容的顏色統一改成單一顏色，並含取代內容的測試函式。","usage":"執行 colorchange → 選取多重引線 → 輸入顏色","level":5,"lt":"✅","ver":"20240724","author":"chengshunyi","video":"","fas":"fas/ch-mltext-color.fas"},{"no":364,"file":"ch-mtxt-up-low.lsp","cmd":"ch-mtxt-uper、ch-mtxt-uper-1chr、ch-mtxt-uper-1","cat":"文字","desc":"將選取的單行或多行文字轉為每字首大寫、句首大寫等英文大小寫格式，並可在第三字元後加空格。","usage":"執行 ch-mtxt-uper → 選取文字或多行文字 → 自動轉大小寫","level":5,"lt":"✅","ver":"20241122","author":"CHENGSHUNYI（含 Autodesk 論壇範例）","video":"","fas":"fas/ch-mtxt-up-low.fas"},{"no":365,"file":"ch-open-close.lsp","cmd":"ch-open-close","cat":"修改","desc":"重建 WALL-V 圖層所有多線為開放或封閉端樣式（-OPEN），刪除原多線。","usage":"執行 ch-open-close → 自動處理 WALL-V 圖層所有多線","level":4,"lt":"✅","ver":"2008.05.18（20220716 更新）","author":"—","video":"","fas":"fas/ch-open-close.fas"},{"no":366,"file":"ch-projectname.LSP","cmd":"ch-projectname","cat":"圖面管理","desc":"選擇資料夾內所有 DWG 圖檔，輸入專案名稱後產生 SCR 腳本，批次開啟圖檔修改專案名稱並存檔。","usage":"執行 ch-projectname → 輸入 Projectname → 選擇圖檔目錄 → Enter 開始 → 批次執行腳本","level":8,"lt":"⚠️","ver":"2018.01.21（20220716 更新）","author":"Cheng Shun-Yi","video":"","fas":"fas/ch-projectname.fas"},{"no":367,"file":"ch-room-pack-def.LSP","cmd":"ch-room-pack-def","cat":"圖塊/屬性","desc":"修改房間編號圖塊的 PACKAGE TYPE 屬性，將舊 FINISH TYPE 換成新值，並強制 P1、P2、P3 設為 01、02、03。","usage":"執行 ch-room-pack-def → 輸入舊 FINISH TYPE → 輸入新 FINISH TYPE → 自動修改圖塊屬性","level":6,"lt":"✅","ver":"20241030","author":"chengshunyi","video":"","fas":"fas/ch-room-pack-def.fas"},{"no":368,"file":"ch-table-column-w.LSP","cmd":"ch-table-column-w","cat":"修改","desc":"輸入欄寬後，將選取表格的所有欄寬統一改成該值。","usage":"執行 ch-table-column-w → 選取表格 → 輸入欄寬","level":2,"lt":"✅","ver":"2022-02-02 (檔案日期)","author":"—","video":"","fas":"fas/ch-table-column-w.fas"},{"no":369,"file":"ch-table-row-hi.LSP","cmd":"ch-table-row-hi","cat":"修改","desc":"輸入列高後，將選取表格的所有列高統一改成該值。","usage":"執行 ch-table-row-hi → 選取表格 → 輸入列高","level":2,"lt":"✅","ver":"2022-02-02 (檔案日期)","author":"—","video":"","fas":"fas/ch-table-row-hi.fas"},{"no":370,"file":"ch-table-text-hi.LSP","cmd":"ch-table-text-hi","cat":"修改","desc":"將選取表格所有儲存格文字高度改為指定值（預設 0.35cm 乘以 LTSCALE）。","usage":"執行 ch-table-text-hi → 選取表格 → 輸入文字高度","level":4,"lt":"✅","ver":"20220202","author":"—","video":"","fas":"fas/ch-table-text-hi.fas"},{"no":371,"file":"CH-TEXT_LAYER_BY_STYLE.LSP","cmd":"CH-TEXT_LAYER_BY_STYLE","cat":"圖層","desc":"依文字樣式名稱將文字移到對應圖層（如空間名稱、說明註解、規範說明、尺寸），並自動建立圖層。","usage":"執行 CH-TEXT_LAYER_BY_STYLE → 自動依樣式整理所有文字圖層","level":4,"lt":"✅","ver":"2019-10-01","author":"RJP（chengshunyi 修改）","video":"","fas":"fas/CH-TEXT_LAYER_BY_STYLE.fas"},{"no":372,"file":"ch-textstyle-w.lsp","cmd":"ch-textstyle-w","cat":"文字","desc":"將所有文字樣式的高度設為 0，並將字寬設為 0.75，列出被修改的樣式後重生圖面。","usage":"執行 ch-textstyle-w → 自動修改全部文字樣式","level":4,"lt":"✅","ver":"2008-03-08","author":"Jimmy Bergmark (JTB World)","video":"","fas":"fas/ch-textstyle-w.fas"},{"no":373,"file":"ch-tx-w-inblk.LSP","cmd":"TxtWidth、BTW、bdtw","cat":"文字","desc":"將圖面所有圖塊定義（含巢狀）內的文字與屬性寬度比例一次改成指定值，並同步屬性。","usage":"執行 BTW → 輸入文字寬度比例 → 自動修改所有圖塊內文字","level":5,"lt":"✅","ver":"20241120（Kent Cooper 2017）","author":"chengshunyi（含 Kent Cooper）","video":"","fas":"fas/ch-tx-w-inblk.fas"},{"no":374,"file":"ch-Txt-W-det.lsp","cmd":"ch-Txt-W-det-60、ch-Txt-W-det-75、ch-Txt-W-det","cat":"文字","desc":"將詳圖用文字的寬度比例改為 0.6、0.75 或自訂值。","usage":"執行 ch-Txt-W-det-75 → 選取文字 → 自動修改寬度比例","level":3,"lt":"✅","ver":"20241120","author":"chengshunyi","video":"","fas":"fas/ch-Txt-W-det.fas"},{"no":375,"file":"ch-walkdim-lay.lsp","cmd":"ch-walkdim-lay","cat":"標註","desc":"將選取標註在「步行距離」與「重複步行距離」兩個圖層之間切換。","usage":"執行 ch-walkdim-lay → 選取標註 → 自動切換圖層","level":3,"lt":"✅","ver":"20250608","author":"chengshunyi","video":"https://youtu.be/cK_cSLTuDNA","fas":"fas/ch-walkdim-lay.fas"},{"no":376,"file":"CH-XR-ALL-COL.LSP","cmd":"CH-XR-ALL-COL、CH-XR-ALL-COL-","cat":"圖層","desc":"點選外部參考內物件，將該外參圖檔所有圖層顏色統一改成同一種顏色（預設色可免選）。","usage":"執行 CH-XR-ALL-COL → 點選外參內物件 → 自動改色","level":4,"lt":"✅","ver":"20241024","author":"chengshunyi（含 RJP 2020）","video":"","fas":"fas/CH-XR-ALL-COL.fas"},{"no":377,"file":"ch-xref-la-bypick.lsp","cmd":"ChangeLayerColor、CH-XR-COL-PICKS、CH-XR-COL-PICK","cat":"圖層","desc":"點選外參內物件取得圖層清單，多選圖層後再選顏色，修改外部參考圖層顏色。","usage":"執行 CH-XR-COL-PICKS → 點選外參物件 → 選圖層編號 → 選顏色","level":4,"lt":"✅","ver":"20241023","author":"chengshunyi","video":"https://youtu.be/_w-t_BbO1YM","fas":"fas/ch-xref-la-bypick.fas"},{"no":378,"file":"CH-XREF-LA-COLOR.lsp","cmd":"（無，副程式庫）","cat":"圖層","desc":"選取外部參考後修改其圖層顏色並重生，非外參會提示錯誤。","usage":"載入後依提示選取外部參考 → 修改顏色","level":3,"lt":"✅","ver":"20230417","author":"chengshunyi","video":"","fas":"fas/CH-XREF-LA-COLOR.fas"},{"no":379,"file":"ch-xref-layer.lsp","cmd":"ch-xref-layer","cat":"圖層","desc":"將全圖外部參考與圖塊改到各自的圖層（XREF 與 block）。","usage":"執行 ch-xref-layer → 自動處理全圖","level":2,"lt":"✅","ver":"2022-04-01 (檔案日期)","author":"—","video":"","fas":"fas/ch-xref-layer.fas"},{"no":380,"file":"CH-XREF-OBJ-COLOR.LSP","cmd":"CH-XREF-OBJ-COLOR、CH-XREF-ALLOBJ-COLOR","cat":"圖層","desc":"改外部參考內物件的顏色（非圖層表），可點選外參圖層或全部物件並選顏色與透明度。","usage":"執行 CH-XREF-OBJ-COLOR → 點選外參內圖層物件 → 選顏色 → 自動修改","level":5,"lt":"✅","ver":"20220716更新","author":"chengshunyi（thanks Lee Mac）","video":"","fas":"fas/CH-XREF-OBJ-COLOR.fas"},{"no":381,"file":"CH-XREF-VP-COLOR.lsp","cmd":"CH-XREF-VP-COLOR","cat":"圖層","desc":"在視埠內以 VPLAYER 指令設定指定外參圖層的視埠顏色。","usage":"在視埠內執行 CH-XREF-VP-COLOR → 輸入視埠顏色號碼 → 選圖層","level":2,"lt":"✅","ver":"20241025","author":"CHENGSHUNYI","video":"","fas":"fas/CH-XREF-VP-COLOR.fas"},{"no":382,"file":"CH_COLOR_LAI.lsp","cmd":"CH_COLOR_LAI","cat":"修改","desc":"統一圖面顏色，MTEXT 改色並移除內嵌顏色碼，優先用真彩色，處理 Proxy、填充漸層、表格、標註與引線。","usage":"執行 CH_COLOR_LAI → 輸入顏色 → 自動處理全圖及圖塊內物件","level":8,"lt":"⚠️","ver":"2025-11-25 (檔案日期)","author":"LUCAS_LAI（網路程式）","video":"","fas":"fas/CH_COLOR_LAI.fas"},{"no":383,"file":"CH_COLOR_TO_ONE.LSP","cmd":"CH_COLOR_TO_ONE","cat":"修改","desc":"將圖元顏色統一為單一顏色而不改變圖層顏色，遞迴處理圖塊、屬性、MTEXT、多重引線、表格與 Proxy 物件。","usage":"執行 CH_COLOR_TO_ONE → 輸入顏色 → 自動處理全圖","level":8,"lt":"⚠️","ver":"2023-04-02 (檔案日期)","author":"LUCAS_LAI（含 Luis Esquivel）","video":"","fas":"fas/CH_COLOR_TO_ONE.fas"},{"no":384,"file":"ChamferFilletUI.lsp","cmd":"ChamferFilletUI、mychamfer、myfillet、mychafillet","cat":"修改","desc":"對話框設定倒角距離或圓角半徑與是否修剪，將設定存入 INI 後連續執行倒角或圓角。","usage":"執行 ChamferFilletUI → 對話框選倒角或圓角並輸入距離 → 確定 → 連續選取兩物件","level":6,"lt":"✅","ver":"2025-10-15 (檔案日期)","author":"MyCAD","video":"","fas":"fas/ChamferFilletUI.fas"},{"no":385,"file":"CHANGE-COLOR-ENT.LSP","cmd":"COLORP、COLORXD、COLORX、COLORXREF、COLORXL、COLORXREFL","cat":"修改","desc":"修改外參或圖塊內物件的顏色（含標註與引線），不改圖層表，各指令對應不同處理範圍與圖層鎖凍狀態。","usage":"執行 COLORX → 輸入顏色號碼 → 選取外參或圖塊 → 自動改色","level":6,"lt":"⚠️","ver":"2023-04-23 (檔案日期)","author":"網路程式","video":"","fas":"fas/CHANGE-COLOR-ENT.fas"},{"no":386,"file":"CHANGE-SPNAME-STYLE.lsp","cmd":"CHANGE-SPNAME-STYLE、foo","cat":"文字","desc":"建立空間名稱文字樣式（DANNY-S4 與 CHINESET 大字型），並將選取文字改用該樣式，再處理多行文字。","usage":"執行 CHANGE-SPNAME-STYLE → 選取文字 → 自動套用空間名稱樣式","level":3,"lt":"✅","ver":"2023-06-25 (檔案日期)","author":"—","video":"","fas":"fas/CHANGE-SPNAME-STYLE.fas"},{"no":387,"file":"chat.lsp","cmd":"chat","cat":"圖塊/屬性","desc":"以 ObjectDBX 不開啟圖檔，批次修改資料夾內多個 DWG 的標題欄圖塊指定屬性值（如標題第一行）。","usage":"執行 chat → 選取資料夾內任一 DWG → 輸入屬性值 → 批次修改","level":8,"lt":"❌","ver":"20231231","author":"Fatty The Old Horse（chengshunyi 修改）","video":"","fas":"fas/chat.fas"},{"no":388,"file":"check-cwccw.LSP","cmd":"set-pl-2CCW、set-pl-2CW、get-pl-CWccw","cat":"修改","desc":"檢查聚合線為順時針或逆時針，可一鍵反轉為逆時針或順時針，並顯示方向。","usage":"執行 get-pl-CWccw → 選取聚合線 → 顯示方向；set-pl-2CCW 或 set-pl-2CW 改方向","level":4,"lt":"✅","ver":"20240212","author":"chengshunyi（含 Alan H 2020、Kent Cooper）","video":"","fas":"fas/check-cwccw.fas"},{"no":389,"file":"check-pl-sept-revserve.LSP","cmd":"check-pl-sept-revserve","cat":"查詢","desc":"檢查聚合線起點與終點方向，依線寬識別，必要時反轉並改選擇點為起點。","usage":"執行 check-pl-sept-revserve → 點選聚合線 → 顯示起點並反轉","level":4,"lt":"✅","ver":"20231014","author":"chengshunyi / ChengBAR","video":"","fas":"fas/check-pl-sept-revserve.fas"},{"no":390,"file":"check-sq-pline.LSP","cmd":"test-square","cat":"查詢","desc":"判斷封閉聚合線形狀（三角形、矩形、平行四邊形、梯形、正方形）並提示結果。","usage":"執行 test-square → 選取聚合線 → 顯示形狀判斷結果","level":5,"lt":"✅","ver":"20230604","author":"Alan H（chengshunyi 修改）","video":"","fas":""},{"no":391,"file":"chk-att-plusminus.lsp","cmd":"chk-att-plusminus","cat":"查詢","desc":"找出屬性值含「+-」的圖塊，以聚合線標示並選取，用於高程屬性檢查。","usage":"執行 chk-att-plusminus → 選取圖塊取名稱 → 自動找出含 +- 的屬性圖塊並標示","level":5,"lt":"✅","ver":"20240707","author":"chengshunyi","video":"","fas":"fas/chk-att-plusminus.fas"},{"no":392,"file":"chk-att-plusminus2.lsp","cmd":"chk-att-plusminus2","cat":"標註","desc":"對話框選取目標屬性標籤，自動調整動態圖塊屬性與欄位值的正負號前綴（＋、－、±），避免重複疊加。","usage":"執行 chk-att-plusminus2 → 點選目標屬性標籤 → 對話框設定 → 自動調整所有屬性正負號","level":8,"lt":"✅","ver":"V4.0 2026/07/04","author":"ChengBar","video":"","fas":"fas/chk-att-plusminus2.fas"},{"no":393,"file":"chk-attblk-dup-sva.LSP","cmd":"chk-attblk-dup-sva-a、chk-attblk-dup-sva-b","cat":"查詢","desc":"檢查指定圖塊（NA-ROOM-L）屬性的重複值，列出重複項目。","usage":"執行 chk-attblk-dup-sva-a → 自動檢查圖面所有指定圖塊屬性","level":5,"lt":"✅","ver":"20240322","author":"chengshunyi","video":"","fas":"fas/chk-attblk-dup-sva.fas"},{"no":394,"file":"chk-attblk-dup-va.lsp","cmd":"chk-attblk-dup-va","cat":"查詢","desc":"檢查模型空間屬性圖塊的重複屬性值並亮顯重複圖塊。","usage":"執行 chk-attblk-dup-va → 自動檢查並亮顯重複圖塊","level":4,"lt":"✅","ver":"20240322","author":"chengshunyi","video":"","fas":"fas/chk-attblk-dup-va.fas"},{"no":395,"file":"chk-dim-lay-yn.lsp","cmd":"chk-dim-lay-yn","cat":"圖層","desc":"檢查圖面是否有標註圖層，沒有時依環境變數（名稱、顏色、線型）自動建立，載入時即自動執行一次。","usage":"載入程式（自動執行）或輸入 CHK-DIM-LAY-YN → 自動檢查並建立標註圖層","level":5,"lt":"✅","ver":"v1.1.0 2026-11-05","author":"ChengBar (chengshunyi)","video":"","fas":"fas/chk-dim-lay-yn.fas"},{"no":396,"file":"chk-dim-over.lsp","cmd":"chk-dim-over、dim-chk-ov、dim-chk-lsf","cat":"標註","desc":"找出尺寸文字被手動改過數值或線性比例被改過的標註，並移到指定圖層標示出來。","usage":"執行 chk-dim-over → 自動掃描全圖標註 → 顯示被改數據的尺寸數量並移至警示圖層","level":4,"lt":"✅","ver":"20231117","author":"chengshunyi","video":"","fas":"fas/chk-dim-over.fas"},{"no":397,"file":"chk-Dup-blk.lsp","cmd":"chk-Dup-blk","cat":"圖塊/屬性","desc":"快速檢查重複的圖塊、點、直線物件，縮放到重複處並用圓圈、連線標示位置。","usage":"執行 chk-Dup-blk → 自動掃描 → 顯示重複物件數量 → 於重複位置畫圓圈標註並縮放","level":7,"lt":"✅","ver":"20240322","author":"chengshunyi","video":"","fas":"fas/chk-Dup-blk.fas"},{"no":398,"file":"chk-open-pl.lsp","cmd":"chk-open-pl","cat":"修改","desc":"檢查選取的聚合線是否閉合，未閉合者標示出來或將其設為閉合。","usage":"執行 chk-open-pl → 選取聚合線 → 顯示未閉合結果並處理","level":3,"lt":"✅","ver":"20250314","author":"chengshunyi","video":"","fas":"fas/chk-open-pl.fas"},{"no":399,"file":"chk-pl-cwccw-da.lsp","cmd":"chk-pl-cwccw-da","cat":"標註","desc":"判斷封閉聚合線的順逆時針方向，並依方向加上箭頭標示。","usage":"執行 chk-pl-cwccw-da → 選取封閉聚合線 → 自動加方向箭頭","level":5,"lt":"✅","ver":"20240329","author":"chengshunyi","video":"","fas":"fas/chk-pl-cwccw-da.fas"},{"no":400,"file":"chxrefcols.lsp","cmd":"chxrefcols","cat":"圖層","desc":"選取外部參照後，將其內圖層顏色改為指定色號並重生圖面。","usage":"執行 chxrefcols → 選取 Xref → 輸入色號","level":3,"lt":"✅","ver":"20211225","author":"—","video":"https://youtu.be/PvKhJcMQ0gI","fas":"fas/chxrefcols.fas"},{"no":401,"file":"cir-tan-line2-ii.LSP","cmd":"cir-tan-line2-ii、cir-tan-line2-T","cat":"繪圖","desc":"指定兩圓圓心與半徑，繪製兩圓之外公切線與內公切線（含聚合線版本）。","usage":"執行 cir-tan-line2-ii → 點選第一圓心 → 輸入半徑 → 點選第二圓心 → 輸入半徑","level":4,"lt":"✅","ver":"20240210","author":"chengshunyi","video":"","fas":"fas/cir-tan-line2-ii.fas"},{"no":402,"file":"cir-tan-line2.lsp","cmd":"cir-tan-line2","cat":"繪圖","desc":"指定兩圓圓心與半徑，以聚合線繪製兩圓外切線。","usage":"執行 cir-tan-line2 → 點選第一圓心 → 輸入半徑 → 點選第二圓心 → 輸入半徑","level":4,"lt":"✅","ver":"20240210","author":"chengshunyi","video":"","fas":""},{"no":403,"file":"cl-mark.lsp","cmd":"cl-mark","cat":"標註","desc":"選取圓、弧或橢圓後，自動畫出十字中心線，線長與圖層依比例設定。","usage":"執行 cl-mark → 選取圓/弧/橢圓 → 自動畫中心線","level":5,"lt":"✅","ver":"20241105","author":"Lee Mac / chengshunyi","video":"https://youtu.be/hdExixIEvQ8","fas":"fas/cl-mark.fas"},{"no":404,"file":"cl-rec-l.LSP","cmd":"cl-rec-l","cat":"標註","desc":"選取矩形後，沿長邊方向畫出平行長邊的矩形中心線。","usage":"執行 cl-rec-l → 選取矩形 → 自動畫中心線","level":5,"lt":"✅","ver":"20240524","author":"chengshunyi","video":"","fas":"fas/cl-rec-l.fas"},{"no":405,"file":"clean-up_scale_lists.LSP","cmd":"ScaleListRemXRef、ScaleListRemImperial、ScaleListRemMetric、ScaleListImperial、ScaleListMetric、ScaleListStandard","cat":"圖面管理","desc":"清理比例清單：移除外參比例、英制或公制比例，並依 MEASUREMENT 補回標準比例。","usage":"執行 ScaleListStandard 等指令 → 自動清理並補回比例清單","level":5,"lt":"✅","ver":"20220716","author":"網路程式","video":"","fas":"fas/clean-up_scale_lists.fas"},{"no":406,"file":"CLEANBLOCKS.lsp","cmd":"CleanBlocks","cat":"圖塊/屬性","desc":"逐一開啟圖面內非外參、非匿名的圖塊於編輯器，執行清理後儲存關閉。","usage":"執行 CleanBlocks → 自動逐一處理所有圖塊","level":4,"lt":"✅","ver":"2025-12-06 (檔案日期)","author":"—","video":"","fas":"fas/CLEANBLOCKS.fas"},{"no":407,"file":"cleanup-one-color.LSP","cmd":"cleanup-one-color","cat":"圖層","desc":"將全圖物件（含圖塊內、標註、引線）改為 ByLayer，並把所有圖層設為單一指定顏色。","usage":"執行 cleanup-one-color → 輸入色號 → 自動處理並重生","level":5,"lt":"✅","ver":"20240724","author":"Azri (改自 p_mcknight) / chengshunyi","video":"","fas":"fas/cleanup-one-color.fas"},{"no":408,"file":"CleanupLauncher.LSP","cmd":"CleanupLauncher","cat":"其他","desc":"以對話框提供 CleanupRegapp 快速啟動器，可選擇執行 AutoCAD 或 AutoCAD LT 版本。","usage":"執行 CleanupLauncher → 選擇 AutoCAD 或 LT 版本按鈕","level":6,"lt":"✅","ver":"2026-06-14 (檔案日期)","author":"—","video":"","fas":"fas/CleanupLauncher.fas"},{"no":409,"file":"CLG.LSP","cmd":"clg","cat":"繪圖","desc":"依三點與類型畫出圓、並對封閉聚合線填入格網填充，用於特定柱網記號。","usage":"執行 clg → 點選 P0、P1、P2 → 選擇類型 → 選取封閉聚合線","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/CLG.fas"},{"no":410,"file":"CLIP.LSP","cmd":"clip","cat":"修改","desc":"以裁切框裁剪選取物件，框外部分以 TRIM 修剪並保留框內。","usage":"執行 clip → 選取物件 → 指定裁切框 → 完成","level":7,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/CLIP.fas"},{"no":411,"file":"CLIST.lsp","cmd":"CDA-B","cat":"圖塊/屬性","desc":"讀取座標圖塊屬性並排序，在圖面產生放樣座標表。","usage":"執行 CDA-B → 選取圖塊 → 指定表格位置","level":7,"lt":"✅","ver":"20230322","author":"chengshunyi（改自 cadtutor 程式）","video":"","fas":"fas/CLIST.fas"},{"no":412,"file":"close-Polylines.lsp","cmd":"close-Polylines、close-PolylinesX","cat":"修改","desc":"將框選範圍或全圖未閉合的聚合線自動設為閉合。","usage":"執行 close-Polylines → 框選範圍（X 版為全圖）→ 自動閉合","level":3,"lt":"✅","ver":"20250314","author":"chengshunyi","video":"","fas":"fas/close-Polylines.fas"},{"no":413,"file":"cloud-18-cm.lsp","cmd":"cloud-18-cm、ob2rev、CLOUD18-pc","cat":"標註","desc":"雲形線整合工具（公分圖面版），以對話框設定圖紙、比例、圖層、日期後連續畫雲形線並插入版次符號。","usage":"執行 cloud-18-cm → 對話框設定 → 指定範圍連續畫雲形線","level":9,"lt":"✅","ver":"2026-07-23 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/cloud-18-cm.fas"},{"no":414,"file":"cloud-18.lsp","cmd":"cloud-18、ob2rev、CLOUD18-pc","cat":"標註","desc":"雲形線整合工具，以對話框設定圖紙、比例、圖層、日期，連續畫雲形線並插入版次符號，支援角度雲形。","usage":"執行 cloud-18 → 對話框設定 → 指定範圍連續畫雲形線","level":9,"lt":"✅","ver":"20240818","author":"ChengBar (MyCAD) / chengshunyi","video":"https://youtu.be/qgYphW9ciYU","fas":"fas/cloud-18.fas"},{"no":415,"file":"cloud-24.lsp","cmd":"cloud-24","cat":"標註","desc":"MyCAD 雲狀線工具，以對話框設定並存成 TXT 記錄檔，繪製 REVCLOUD 與 3 點矩形並更新版次圖塊。","usage":"執行 cloud-24 → 對話框設定 → 指定 3 點矩形或範圍 → 自動產生雲線與版次","level":9,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/cloud-24.fas"},{"no":416,"file":"Cloud-hold-layout.lsp","cmd":"CLOUD-hold-layout","cat":"標註","desc":"在配置空間以兩點畫弧形雲形線並插入 DELTA14 變更符號（保持版本）。","usage":"執行 CLOUD-hold-layout → 點選第一點、第二點 → 指定符號位置","level":6,"lt":"✅","ver":"93.11.18","author":"—","video":"","fas":"fas/Cloud-hold-layout.fas"},{"no":417,"file":"Cloud-hold.lsp","cmd":"CLOUD-hold","cat":"標註","desc":"以兩點畫弧形雲形線並插入 DELTA14 變更符號，可判斷模型或配置空間。","usage":"執行 CLOUD-hold → 點選第一點、第二點 → 指定符號位置","level":6,"lt":"✅","ver":"20230222","author":"chengshunyi","video":"","fas":"fas/Cloud-hold.fas"},{"no":418,"file":"Cloud-layout.lsp","cmd":"CLOUD-layout","cat":"標註","desc":"在配置空間（mm 圖框）以兩點畫弧形雲形線並插入 DELTA14 變更符號。","usage":"執行 CLOUD-layout → 點選第一點、第二點 → 指定符號位置","level":6,"lt":"✅","ver":"93.11.16","author":"—","video":"","fas":"fas/Cloud-layout.fas"},{"no":419,"file":"Cloud-nomark.lsp","cmd":"Cloud-nomark","cat":"標註","desc":"以兩點畫弧形雲形線，不插入變更符號的版本。","usage":"執行 Cloud-nomark → 點選第一點、第二點","level":6,"lt":"✅","ver":"89.9.14","author":"—","video":"","fas":"fas/Cloud-nomark.fas"},{"no":420,"file":"CLOUD.LSP","cmd":"CLOUD","cat":"標註","desc":"以 SKETCH 手繪方式產生雲形線，轉成聚合線並插入 DELTA 符號。","usage":"執行 CLOUD → 手繪雲形 → 指定符號位置","level":3,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/CLOUD.fas"},{"no":421,"file":"CLOUD1.LSP","cmd":"CLOUD1","cat":"標註","desc":"以兩點畫雲形線並插入 DELTA1 變更符號。","usage":"執行 CLOUD1 → 點選第一點、第二點 → 指定符號位置","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/CLOUD1.fas"},{"no":422,"file":"Cloud14.lsp","cmd":"CLOUD14-pc、CLOUD14-dc、CLOUD14-d、CLOUD14、CLOUD14-0","cat":"標註","desc":"優化版雲形線工具，整合 PAK、DC、DM 與標準雲形線，依日期建立圖層並連續執行。","usage":"執行 CLOUD14 → 點選雲形區域兩對角點 → 可連續執行，Enter 結束","level":6,"lt":"✅","ver":"2026-01-07 (檔案日期)","author":"—","video":"","fas":"fas/Cloud14.fas"},{"no":423,"file":"CLOUD26-0.lsp","cmd":"CLOUD26","cat":"標註","desc":"以對話框設定圓弧角度、間距、凸度、單位、比例與符號後畫雲形線。","usage":"執行 CLOUD26 → 對話框設定參數 → 指定雲形範圍","level":6,"lt":"✅","ver":"2025-09-29 (檔案日期)","author":"—","video":"https://youtu.be/Ku-7aGbiC1Q","fas":"fas/CLOUD26-0.fas"},{"no":424,"file":"CLOUD26.lsp","cmd":"CLOUD26","cat":"標註","desc":"MyCAD 雲形線，對話框設定角度、間距、凸度、圖層、單位、比例與符號，畫雲形線並插入符號。","usage":"執行 CLOUD26 → 對話框設定參數 → 指定雲形範圍","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"ChengBar (MyCAD)","video":"https://youtu.be/Ku-7aGbiC1Q","fas":"fas/CLOUD26.fas"},{"no":425,"file":"clouds-t.LSP","cmd":"clouds-t","cat":"標註","desc":"弧狀雲形線繪製，沿多種曲線產生分點並以凸度弧線組成雲形。","usage":"執行 clouds-t → 選取曲線或指定點 → 產生弧狀雲形","level":7,"lt":"✅","ver":"2024-12-07 (檔案日期)","author":"—","video":"","fas":"fas/clouds-t.fas"},{"no":426,"file":"CLR-Measure.lsp","cmd":"C-measure、L-measure、R-measure","cat":"對齊/排列","desc":"置中等分量測，沿物件依指定長度或圖塊放置點或圖塊，餘數可置中、靠左或靠右。","usage":"執行 C-measure → 選取物件 → 輸入分段長度或選圖塊 → 是否對齊","level":7,"lt":"✅","ver":"20240212","author":"Lee Mac / chengshunyi","video":"","fas":"fas/CLR-Measure.fas"},{"no":427,"file":"CMD_PlineDimTool.lsp","cmd":"CMD_PlineDimTool","cat":"標註","desc":"聚合線邊長標註工具，以對話框設定單位與比例，標註各邊並在起點顯示加總公式。","usage":"執行 CMD_PlineDimTool → 對話框設定 → 選取聚合線","level":6,"lt":"✅","ver":"v1.0 (2025-07-19 檔案日期)","author":"ShunYi x AI","video":"","fas":""},{"no":428,"file":"CMLS-100.lsp","cmd":"cmls-100","cat":"標註","desc":"建立或修改多重引線樣式，預設為 1:100 比例的字型與參數。","usage":"執行 cmls-100 → 輸入樣式名稱 → 若已存在選擇是否修改","level":5,"lt":"✅","ver":"2023-04-08 (檔案日期)","author":"網路程式","video":"","fas":"fas/CMLS-100.fas"},{"no":429,"file":"CMLS.lsp","cmd":"cmls","cat":"標註","desc":"建立或修改多重引線樣式，可設定字型、字高等參數。","usage":"執行 cmls → 輸入樣式名稱 → 若已存在選擇是否修改","level":5,"lt":"✅","ver":"2023-04-08 (檔案日期)","author":"網路程式","video":"","fas":"fas/CMLS.fas"},{"no":430,"file":"cn-insert.lsp","cmd":"cn-copy、cn-insert-c、cn-insert-s、cn-insert-c2、cn-insert-s2、cn-insert-c5、cn-insert-s5、cn-insert-c25、cn-insert-s25、cn-insert","cat":"圖塊/屬性","desc":"插入柱心線符號動態圖塊，有 C、S 等多種形式，可設定折線端點、柱線長度與柱號角度。","usage":"執行 cn-insert-c 等 → 指定插入點 → 指定軸線方向 → 輸入柱號","level":7,"lt":"✅","ver":"20250223","author":"chengshunyi","video":"","fas":"fas/cn-insert.fas"},{"no":431,"file":"CN-X.lsp","cmd":"cn-x","cat":"圖塊/屬性","desc":"以對話框（幻燈片預覽）選擇 X 方向柱號符號並插入圖塊。","usage":"執行 cn-x → 對話框選擇符號 → 指定插入點","level":6,"lt":"✅","ver":"84.6.5","author":"—","video":"","fas":"fas/CN-X.fas"},{"no":432,"file":"CN-XY.LSP","cmd":"cn-xy","cat":"圖塊/屬性","desc":"以對話框選擇 X 或 Y 方向柱號符號並插入圖塊。","usage":"執行 cn-xy → 對話框選擇符號 → 指定插入點","level":6,"lt":"✅","ver":"84.4.10","author":"—","video":"","fas":"fas/CN-XY.fas"},{"no":433,"file":"CN-Y.LSP","cmd":"cn-y","cat":"圖塊/屬性","desc":"以對話框（幻燈片預覽）選擇 Y 方向柱號符號並插入圖塊。","usage":"執行 cn-y → 對話框選擇符號 → 指定插入點","level":6,"lt":"✅","ver":"84.6.5","author":"—","video":"","fas":"fas/CN-Y.fas"},{"no":434,"file":"CNSGrid.lsp","cmd":"CNSGrid","cat":"標註","desc":"CNS 柱網標註工具，以對話框設定比例、單位、標註方向與排序，依軸線畫圓並標註數字與字母。","usage":"執行 CNSGrid → 對話框設定 → 選取軸線/點位 → 自動標註","level":7,"lt":"✅","ver":"2026-05-20 (檔案日期)","author":"MyCAD","video":"","fas":"fas/CNSGrid.fas"},{"no":435,"file":"COL-1.LSP","cmd":"col-1","cat":"繪圖","desc":"依柱中心點、寬度與長度畫矩形柱（類型 1）。","usage":"執行 col-1 → 指定柱中心點 → 輸入寬度 → 輸入長度","level":2,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/COL-1.fas"},{"no":436,"file":"COL-2.LSP","cmd":"col-2","cat":"繪圖","desc":"依柱中心點、寬度與長度畫矩形柱（類型 2）。","usage":"執行 col-2 → 指定柱中心點 → 輸入寬度 → 輸入長度","level":2,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/COL-2.fas"},{"no":437,"file":"COL-3.LSP","cmd":"col-3","cat":"繪圖","desc":"依柱中心點、寬度與長度畫矩形柱（類型 3）。","usage":"執行 col-3 → 指定柱中心點 → 輸入寬度 → 輸入長度","level":2,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/COL-3.fas"},{"no":438,"file":"COL-4.LSP","cmd":"col-4","cat":"繪圖","desc":"依柱中心點、寬度與長度畫矩形柱（類型 4）。","usage":"執行 col-4 → 指定柱中心點 → 輸入寬度 → 輸入長度","level":2,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/COL-4.fas"},{"no":439,"file":"COL-5.LSP","cmd":"col-5","cat":"繪圖","desc":"依柱中心點、寬度與長度畫矩形柱（類型 5）。","usage":"執行 col-5 → 指定柱中心點 → 輸入寬度 → 輸入長度","level":2,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/COL-5.fas"},{"no":440,"file":"col-grid-radio.lsp","cmd":"col-grid-radio","cat":"圖塊/屬性","desc":"以單選按鈕對話框與預覽圖，挑選柱網符號型式後呼叫 cn-insert 插入。","usage":"執行 col-grid-radio → 選擇型式 → 確定 → 指定插入點","level":6,"lt":"✅","ver":"2025-08-23 (檔案日期)","author":"—","video":"","fas":"fas/col-grid-radio.fas"},{"no":441,"file":"col-grid-ui.LSP","cmd":"col-grid-ui","cat":"圖塊/屬性","desc":"橫排單選按鈕介面選擇柱網符號（C、C5、S、S5 等型式），記住上次選擇後插入。","usage":"執行 col-grid-ui → 選擇型式 → 確定 → 指定插入點","level":6,"lt":"✅","ver":"2025-08-23 (檔案日期)","author":"—","video":"https://youtu.be/GyJaMKOp4aY","fas":"fas/col-grid-ui.fas"},{"no":442,"file":"col-grid.lsp","cmd":"col-grid","cat":"圖塊/屬性","desc":"以 col_grid 對話框選擇柱網符號動態圖塊並載入插入。","usage":"執行 col-grid → 對話框選擇型式 → 確定","level":6,"lt":"✅","ver":"20240928","author":"chengshunyi","video":"","fas":"fas/col-grid.fas"},{"no":443,"file":"COL-SC.LSP","cmd":"（無，副程式庫）","cat":"其他","desc":"（加密檔 PROTECTED LISP，無法讀取原始碼）檔案內容為加密或二進位資料，無法讀取原始程式。","usage":"載入後依內含指令使用（無法判讀）","level":5,"lt":"❓","ver":"2021-03-28 (檔案日期)","author":"—","video":"","fas":"fas/COL-SC.fas"},{"no":444,"file":"COL.LSP","cmd":"col","cat":"繪圖","desc":"以對話框選擇五種柱型之一，輸入寬高後畫出柱斷面。","usage":"執行 col → 對話框點選柱型 → 輸入寬度、高度 → 指定位置","level":6,"lt":"✅","ver":"84.4.24","author":"—","video":"","fas":"fas/COL.fas"},{"no":445,"file":"COL1.lsp","cmd":"col1","cat":"繪圖","desc":"以對話框選擇五種柱型之一，輸入寬高後畫出柱斷面。","usage":"執行 col1 → 對話框點選柱型 → 輸入寬度、高度 → 指定位置","level":6,"lt":"✅","ver":"84.4.24","author":"—","video":"","fas":"fas/COL1.fas"},{"no":446,"file":"colorx-to-one.LSP","cmd":"COLORX、COLORXL、COLORXREF、COLORXREFL","cat":"圖層","desc":"將全圖物件（含圖塊內、標註、屬性，可含外參）統一改成指定顏色，可選擇是否略過鎖定圖層。","usage":"執行 COLORX → 輸入色號 → 自動改色（L 版處理鎖定圖層、XREF 版處理外參）","level":8,"lt":"⚠️","ver":"2024-07-24 (檔案日期)","author":"Vladimir Azarko (VVA) / chengshunyi","video":"","fas":"fas/colorx-to-one.fas"},{"no":447,"file":"COLUMN.LSP","cmd":"column","cat":"繪圖","desc":"以對話框選擇柱型與尺寸，依單位畫柱斷面並可填充，含 MyCAD LOGO 與版權資訊。","usage":"執行 column → 對話框選擇柱型、設定寬高、圖層 → 指定位置畫柱","level":9,"lt":"✅","ver":"20240919","author":"chengshunyi (MyCAD)","video":"https://youtu.be/ny8M_LMesuA","fas":"fas/COLUMN.fas"},{"no":448,"file":"CombineSelections-0.lsp","cmd":"CombineSelections-0","cat":"文字","desc":"對話框累積選取構件編號與斷面尺寸文字，組合成清單，可存成 TXT 或寫回圖面。","usage":"執行 CombineSelections-0 → 按鈕選取編號文字 → 選取尺寸文字 → 累積於清單 → 存 TXT 或寫到圖面","level":8,"lt":"✅","ver":"2025-12-01 (檔案日期)","author":"chengshunyi (AI 輔助)","video":"","fas":"fas/CombineSelections-0.fas"},{"no":449,"file":"CombineSelections.lsp","cmd":"CombineSelections","cat":"文字","desc":"對話框累積選取構件編號與斷面尺寸文字，組合清單後存成 INI 或寫回圖面。","usage":"執行 CombineSelections → 按鈕選取編號文字 → 選取尺寸文字 → 累積於清單 → 存 INI 或寫到圖面","level":8,"lt":"✅","ver":"2025-11-29 (檔案日期)","author":"chengshunyi (AI 輔助)","video":"","fas":"fas/CombineSelections.fas"},{"no":450,"file":"ConnectParallel.LSP","cmd":"ConnectParallel","cat":"繪圖","desc":"選取兩條平行線，在端點間連線打 X 並畫出中心線。","usage":"執行 ConnectParallel → 選取兩條平行線 → 自動畫 X 與中心線","level":4,"lt":"✅","ver":"20241106","author":"chengshunyi","video":"","fas":"fas/ConnectParallel.fas"},{"no":451,"file":"contarlayers.lsp","cmd":"contarlayers","cat":"圖塊/屬性","desc":"選取圖塊後列出該圖塊內含的圖層，並將這些圖層打開以便編輯特定圖塊。","usage":"執行 contarlayers → 選取圖塊 → 自動開啟圖塊內圖層","level":5,"lt":"✅","ver":"20211126","author":"—","video":"","fas":"fas/contarlayers.fas"},{"no":452,"file":"CONVERT-2-BLOCK.lsp","cmd":"setub、setnb、obj2blk1","cat":"圖塊/屬性","desc":"將選取物件轉成匿名圖塊或具名圖塊，以物件外擴範圍中心為插入點。","usage":"執行 setub（匿名）或 setnb（具名）→ 選取物件 → 輸入圖塊名稱","level":6,"lt":"✅","ver":"2024-05-09 (檔案日期)","author":"—","video":"","fas":"fas/CONVERT-2-BLOCK.fas"},{"no":453,"file":"Convert-FtInToCm.lsp","cmd":"Convert-FtInToCm","cat":"文字","desc":"選取英呎英吋格式的文字（含分數），轉換成公分並寫回文字內容。","usage":"執行 Convert-FtInToCm → 選取長度文字（如 2-2/3\"）→ 自動轉換成公分","level":4,"lt":"✅","ver":"2024-11-26 (檔案日期)","author":"—","video":"","fas":"fas/Convert-FtInToCm.fas"},{"no":454,"file":"coord2pline-LT.lsp","cmd":"coord2pline-LT","cat":"轉檔/匯出入","desc":"以對話框貼入地籍座標（地號、點號、X、Y），轉成聚合線並標註地號與點號，LT 相容版。","usage":"執行 coord2pline-LT → 對話框貼入座標資料 → 設定單位係數 → 確定","level":8,"lt":"✅","ver":"2025-11-03 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/coord2pline-LT.fas"},{"no":455,"file":"coord2pline.lsp","cmd":"coord2pline","cat":"轉檔/匯出入","desc":"將地籍座標（地號、點號、X、Y）轉成聚合線，並在中心與點位標註地號與點號。","usage":"執行 coord2pline → 文字編輯視窗貼入座標資料 → 設定單位係數 → 自動畫圖","level":7,"lt":"❌","ver":"20251103","author":"chengshunyi","video":"","fas":"fas/coord2pline.fas"},{"no":456,"file":"copy-bd-field.lsp","cmd":"copy-bd-field","cat":"圖塊/屬性","desc":"發包圖專用，從 ComputerSetting 資料夾找同名 -field.dwg 並以圖塊插入目前圖面。","usage":"執行 copy-bd-field → 自動找檔並插入圖塊","level":4,"lt":"✅","ver":"2023-08-20 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/copy-bd-field.fas"},{"no":457,"file":"Copy-BlksToCurve-LR5.LSP","cmd":"Copy-BlksToCurve-LR5","cat":"對齊/排列","desc":"沿曲線依指定間距連續複製圖塊並對齊曲線方向，可左右留 1/2 間距。","usage":"執行 Copy-BlksToCurve-LR5 → 選取曲線 → 輸入間距 → 連續選取圖塊","level":7,"lt":"✅","ver":"20240211","author":"Lee Mac / chengshunyi","video":"","fas":"fas/Copy-BlksToCurve-LR5.fas"},{"no":458,"file":"Copy-BlksToCurve-NC.LSP","cmd":"Copy-BlksToCurve-NC","cat":"對齊/排列","desc":"沿曲線依指定數量等分放置圖塊，並對齊曲線方向。","usage":"執行 Copy-BlksToCurve-NC → 選取曲線 → 輸入圖塊數量 → 連續選取圖塊","level":7,"lt":"✅","ver":"20240211","author":"Lee Mac / chengshunyi","video":"","fas":"fas/Copy-BlksToCurve-NC.fas"},{"no":459,"file":"Copy-BlksToCurve-NSE.lsp","cmd":"Copy-BlksToCurve-NSE","cat":"對齊/排列","desc":"沿曲線依指定數量等分放置圖塊，頭尾各留半格間距。","usage":"執行 Copy-BlksToCurve-NSE → 選取曲線 → 輸入圖塊數量 → 選取圖塊","level":7,"lt":"✅","ver":"20250511","author":"chengshunyi（改自 Lee Mac）","video":"","fas":"fas/Copy-BlksToCurve-NSE.fas"},{"no":460,"file":"Copy-BlksToCurve.LSP","cmd":"Copy-BlksToCurve","cat":"對齊/排列","desc":"MyCAD 對話框版，沿基準曲線依間距複製圖塊，並記憶上次間距輸入。","usage":"執行 Copy-BlksToCurve → 對話框設定間距 → 選取曲線 → 選取圖塊","level":9,"lt":"⚠️","ver":"v2.9 2026-10-24","author":"ChengBar (鄭順益)","video":"","fas":"fas/Copy-BlksToCurve.fas"},{"no":461,"file":"copy-nentselp-plw-any-v1.lsp","cmd":"copy-nentselp-plw-any-v1、copy-nentselp-plw-v1","cat":"修改","desc":"複製外參或圖塊內的巢狀物件到目前圖面（等同描圖），以清單選圖層顏色並設線寬。","usage":"執行 copy-nentselp-plw-v1 → 對話框選圖層與線寬 → 選取巢狀物件","level":8,"lt":"✅","ver":"2025-11-04 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/copy-nentselp-plw-any-v1.fas"},{"no":462,"file":"copy-nentselp-plw-LAW.LSP","cmd":"copy-nentselp-plw-LAW, copy-nentselp-plw","cat":"修改","desc":"法規圖描圖工具，以多選清單挑選圖層並依筆寬表顏色複製外參物件至目前圖面。","usage":"執行 copy-nentselp-plw-LAW → 對話框多選圖層 → 選取外參物件","level":8,"lt":"✅","ver":"2025-10-25 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/copy-nentselp-plw-LAW.fas"},{"no":463,"file":"copy-nentselp-plw-ui.lsp","cmd":"copy-nentselp-plw-ui","cat":"修改","desc":"MyCAD 外參描圖上色，對話框設定單位、比例、圖層與顏色後複製外參物件到目前圖面。","usage":"執行 copy-nentselp-plw-ui → 對話框設定參數 → 選取外參物件","level":8,"lt":"✅","ver":"2025-10-12 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/copy-nentselp-plw-ui.fas"},{"no":464,"file":"copy-nentselp-plw.lsp","cmd":"copy-nentselp-plw-any、copy-nentselp-plw-c30、copy-nentselp-plw-c50、copy-nentselp-plw","cat":"修改","desc":"複製外參或圖塊內物件到目前圖面描圖，可指定圖層（停車位、建築線、地界線等）及線寬。","usage":"執行 copy-nentselp-plw → 對話框選圖層 → 選取巢狀物件","level":8,"lt":"✅","ver":"20241213","author":"chengshunyi（含 RJP 程式）","video":"","fas":"fas/copy-nentselp-plw.fas"},{"no":465,"file":"copy-nentselp.lsp","cmd":"copy-nentselp","cat":"修改","desc":"選取外參或圖塊內的巢狀物件，複製到目前圖面（等同描圖）並依圖層對應。","usage":"執行 copy-nentselp → 選取巢狀物件 → 自動建立","level":5,"lt":"✅","ver":"20240403","author":"chengshunyi（含 RJP 程式）","video":"","fas":"fas/copy-nentselp.fas"},{"no":466,"file":"copy-obj-to-inters.lsp","cmd":"copy-obj-to-inters","cat":"對齊/排列","desc":"選取格線求交點，將選取物件以基準點複製到所有格線交點上。","usage":"執行 copy-obj-to-inters → 選取格線 → 選取要複製的物件 → 指定基準點","level":5,"lt":"✅","ver":"2025-06-02 (檔案日期)","author":"—","video":"","fas":"fas/copy-obj-to-inters.fas"},{"no":467,"file":"Copy-to-vertice.lsp","cmd":"Copy-to-vertice","cat":"對齊/排列","desc":"將選取的物件（如圖塊）複製到所選弧、線、聚合線或雲形線的所有頂點。","usage":"執行 Copy-to-vertice → 選取要複製物件 → 指定基準點 → 選取曲線","level":5,"lt":"✅","ver":"20230824","author":"Alan J. Thompson / chengshunyi","video":"","fas":"fas/Copy-to-vertice.fas"},{"no":468,"file":"Copy2Layouts.lsp","cmd":"c2l、c2al","cat":"圖面管理","desc":"將選取物件複製到其他配置，c2l 以對話框選擇配置，c2al 一次複製到全部配置。","usage":"執行 c2l → 選取物件 → 對話框選擇配置（c2al 則自動全部）","level":6,"lt":"✅","ver":"Version 1.0 10-02-2011","author":"Lee Mac","video":"","fas":"fas/Copy2Layouts.fas"},{"no":469,"file":"CopyAttrToMLeader.lsp","cmd":"CopyAttrToMLeader","cat":"圖塊/屬性","desc":"將來源動態圖塊的屬性值依標籤複製寫入多重引線內含的圖塊屬性。","usage":"執行 CopyAttrToMLeader → 選取來源圖塊 → 選取目標多重引線","level":6,"lt":"✅","ver":"2026-02-15 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/CopyAttrToMLeader.fas"},{"no":470,"file":"CopyBlockAtt2.lsp","cmd":"CopyBlockAtt2","cat":"圖塊/屬性","desc":"點選來源圖塊的屬性文字，將其值貼到目標圖塊指定屬性，不限相同標籤。","usage":"執行 CopyBlockAtt2 → 點選來源屬性 → 點選目標屬性","level":6,"lt":"✅","ver":"2026-05-25 (檔案日期)","author":"—","video":"","fas":"fas/CopyBlockAtt2.fas"},{"no":471,"file":"copylayouts-UI.lsp","cmd":"copylayouts-UI","cat":"出圖/列印","desc":"以對話框選擇字首、字尾、分類與頁數，批次建立並命名多個配置（圖紙）。","usage":"執行 copylayouts-UI → 對話框選擇字首、分類、頁數 → 預覽 → 確定","level":6,"lt":"✅","ver":"20251123","author":"chengshunyi + Copilot","video":"https://youtu.be/HTd5Nb62qxQ","fas":"fas/copylayouts-UI.fas"},{"no":472,"file":"copylayouts.LSP","cmd":"copylayouts","cat":"出圖/列印","desc":"依輸入字首、起始編號與頁數，複製目前配置並自動編號命名。","usage":"執行 copylayouts → 輸入字首 → 起始編號 → 頁數","level":2,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/copylayouts.fas"},{"no":473,"file":"copyMText2Word.LSP","cmd":"copyMText2Word","cat":"轉檔/匯出入","desc":"將模型空間所有多行文字匯出到 Microsoft Word 文件，並記錄位置。","usage":"執行 copyMText2Word → 自動開啟 Word → 逐一寫入多行文字","level":8,"lt":"❌","ver":"2025-06-27 (檔案日期)","author":"—","video":"","fas":"fas/copyMText2Word.fas"},{"no":474,"file":"CopyRenameBlock.lsp","cmd":"cb、rb","cat":"圖塊/屬性","desc":"複製並重新命名單一圖塊參照（cb）或只重新命名該參照（rb），自動產生新圖塊定義。","usage":"執行 cb 或 rb → 選取圖塊 → 輸入新圖塊名稱","level":7,"lt":"⚠️","ver":"2026-10-17 (檔案日期)","author":"Lee Mac","video":"","fas":"fas/CopyRenameBlock.fas"},{"no":475,"file":"cosnap.lsp","cmd":"cosnap","cat":"系統/授權","desc":"以對話框用滑桿與按鈕設定游標捕捉角度與十字游標大小。","usage":"執行 cosnap → 對話框選擇角度或拉動滑桿 → 確定","level":6,"lt":"✅","ver":"20220102","author":"—","video":"","fas":""},{"no":476,"file":"Count-C.lsp","cmd":"blkcount-C、blkcountsettings","cat":"面積/數量統計","desc":"進階圖塊計數器，統計選取或全圖圖塊數量，可輸出到命令列、TXT/CSV 或表格並排序。","usage":"執行 blkcount-C → 選取圖塊（Enter 全選）→ 依設定輸出表格或檔案","level":9,"lt":"⚠️","ver":"2025-03-27 (檔案日期)","author":"Lee Mac（中文化 chengshunyi）","video":"","fas":"fas/Count-C.fas"},{"no":477,"file":"CountBlock.LSP","cmd":"CountBlock","cat":"面積/數量統計","desc":"統計圖面中名為 TREE 的圖塊（喬木）數量並顯示。","usage":"執行 CountBlock → 自動統計並顯示數量","level":2,"lt":"✅","ver":"20240420","author":"chengshunyi（ChatGPT 設計）","video":"","fas":"fas/CountBlock.fas"},{"no":478,"file":"countmir-m.LSP","cmd":"countmir-m","cat":"圖塊/屬性","desc":"檢查圖塊是否被左右或上下鏡射，並將鏡射的圖塊翻轉回正常。","usage":"執行 countmir-m → 自動掃描圖塊 → 鏡射者翻轉回來","level":5,"lt":"✅","ver":"20240627","author":"chengshunyi","video":"","fas":"fas/countmir-m.fas"},{"no":479,"file":"countmir.LSP","cmd":"countmir","cat":"圖塊/屬性","desc":"檢查圖塊是否被左右或上下鏡射，並將鏡射的圖塊翻轉回正常。","usage":"執行 countmir → 自動掃描圖塊 → 鏡射者翻轉回來","level":5,"lt":"✅","ver":"20240627","author":"chengshunyi","video":"","fas":"fas/countmir.fas"},{"no":480,"file":"CPL.lsp","cmd":"CPL","cat":"繪圖","desc":"選取兩條聚合線，自動畫出兩者之間的中心線（曲線則用雲形線）。","usage":"執行 CPL → 選取第一條聚合線 → 選取第二條聚合線 → 自動畫中心線","level":8,"lt":"❌","ver":"20240523","author":"Gian Paolo Cattaneo / chengshunyi","video":"","fas":"fas/CPL.fas"},{"no":481,"file":"cpla.lsp","cmd":"test_closest_insertpoint、cpla","cat":"繪圖","desc":"求線、弧、圓與聚合線的交點或中點，在指定位置取得中心點，並含 Lee Mac 交點函式。","usage":"執行 cpla → 選取要閉合的物件 → 指定中心位置","level":6,"lt":"✅","ver":"2025-06-15 (檔案日期)","author":"Lee Mac / chengshunyi","video":"","fas":"fas/cpla.fas"},{"no":482,"file":"creat-block.lsp","cmd":"creat-block","cat":"圖塊/屬性","desc":"以 entmake 自動建立測試點屬性圖塊（含圓、屬性定義：測試點編號、Pad 編號），尺寸依比例。","usage":"執行 creat-block → 輸入測試點與 Pad 編號 → 自動建立圖塊","level":6,"lt":"✅","ver":"20240601","author":"chengshunyi","video":"","fas":"fas/creat-block.fas"},{"no":483,"file":"creat-blok-byentmake.lsp","cmd":"creat-blok-byentmake","cat":"圖塊/屬性","desc":"以 entmake 建立名為 test 的簡單圖塊（含直線）的範例程式。","usage":"執行 creat-blok-byentmake → 自動建立圖塊","level":2,"lt":"✅","ver":"2022-12-17 (檔案日期)","author":"—","video":"","fas":"fas/creat-blok-byentmake.fas"},{"no":484,"file":"CREAT-DIMSTYLE.lsp","cmd":"（無，副程式庫）","cat":"標註","desc":"以 VLA 建立或更新標註樣式的函式庫，可設定標註變數、顏色與箭頭，已存在則提示。","usage":"載入後由其他程式呼叫（函式庫）","level":6,"lt":"✅","ver":"2024-10-26 (檔案日期)","author":"—","video":"","fas":"fas/CREAT-DIMSTYLE.fas"},{"no":485,"file":"creat-law-layer.lsp","cmd":"creat-law-layer","cat":"圖層","desc":"檢查並載入線型，依設定建立法規圖用圖層（如 A-line 建築線）。","usage":"執行 creat-law-layer → 自動檢查線型並建立圖層","level":6,"lt":"✅","ver":"20221203","author":"chengshunyi（含 Lee Mac 載入線型函式）","video":"","fas":"fas/creat-law-layer.fas"},{"no":486,"file":"creat-law-linetype.lsp","cmd":"creat-law-linetype","cat":"圖層","desc":"檢查並載入法規線型（law.lin），建立建築線等法規圖層。","usage":"執行 creat-law-linetype → 自動載入線型並建立圖層","level":6,"lt":"✅","ver":"20221203","author":"chengshunyi","video":"","fas":"fas/creat-law-linetype.fas"},{"no":487,"file":"creat-style.lsp","cmd":"（無，副程式庫）","cat":"文字","desc":"以 entmake 建立文字樣式的函式庫，可指定字高、寬度、角度、字型與大字型。","usage":"載入後由其他程式呼叫（函式庫）","level":4,"lt":"✅","ver":"2022-12-10 (檔案日期)","author":"—","video":"","fas":"fas/creat-style.fas"},{"no":488,"file":"creat-test-styles.LSP","cmd":"creat-test-styles","cat":"文字","desc":"建立一組文字樣式，含 Design-Level 以 Arial Narrow 字型及 danny.shx 搭配大字型。","usage":"執行 creat-test-styles → 自動建立文字樣式","level":4,"lt":"✅","ver":"20230115","author":"chengshunyi（含 RJP 程式）","video":"","fas":"fas/creat-test-styles.fas"},{"no":489,"file":"Create-MLeaderStyle.LSP","cmd":"（無，副程式庫）","cat":"標註","desc":"建立多重引線樣式的函式 CreateMLeaderStyle，可設定文字樣式、箭頭與基線參數。","usage":"載入後以 (CreateMLeaderStyle 名稱 設定清單) 呼叫","level":5,"lt":"✅","ver":"2022-12-17 (檔案日期)","author":"Autodesk 論壇範例程式","video":"","fas":"fas/Create-MLeaderStyle.fas"},{"no":490,"file":"create_test_point_blocks.lsp","cmd":"（無，副程式庫）","cat":"圖塊/屬性","desc":"以 entmake 建立測試點圖塊（含圓與屬性定義 Test Point、Pad Number）的函式。","usage":"載入後呼叫函式建立圖塊","level":4,"lt":"✅","ver":"2024-08-17 (檔案日期)","author":"—","video":"","fas":"fas/create_test_point_blocks.fas"},{"no":491,"file":"CreateLayers-law-area.lsp","cmd":"CreateLayers-law-area","cat":"圖層","desc":"讀取 layersettings-law-area.txt 設定檔，批次建立法規面積概算用圖層。","usage":"執行 CreateLayers-law-area → 自動讀檔建立圖層","level":4,"lt":"✅","ver":"20250620","author":"—","video":"","fas":"fas/CreateLayers-law-area.fas"},{"no":492,"file":"CreateLayers-pak-lic.lsp","cmd":"CreateLayers-pak-lic","cat":"圖層","desc":"讀取 layersettings-pak-lic.txt 設定檔，批次建立停車位相關圖層。","usage":"執行 CreateLayers-pak-lic → 自動讀檔建立圖層","level":4,"lt":"✅","ver":"20221002","author":"—","video":"","fas":"fas/CreateLayers-pak-lic.fas"},{"no":493,"file":"CreateLayers-walk.lsp","cmd":"CreateLayers-walk","cat":"圖層","desc":"讀取 layersettings-walk.txt 設定檔，批次建立步行距離檢討用圖層。","usage":"執行 CreateLayers-walk → 自動讀檔建立圖層","level":4,"lt":"✅","ver":"20221002","author":"—","video":"","fas":"fas/CreateLayers-walk.fas"},{"no":494,"file":"CreateLayers.lsp","cmd":"CreateLayers","cat":"圖層","desc":"讀取 layersettings.txt 設定檔，批次建立圖層。","usage":"執行 CreateLayers → 自動讀檔建立圖層","level":3,"lt":"✅","ver":"2022-09-25 (檔案日期)","author":"—","video":"","fas":"fas/CreateLayers.fas"},{"no":495,"file":"CreateShortPath.LSP","cmd":"CreateShortPath","cat":"繪圖","desc":"依序指示多個中心點，畫出穿過這些點的聚合線作為最短路徑。","usage":"執行 CreateShortPath → 指定起點 → 依序點選各中心點 → Enter 結束","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/CreateShortPath.fas"},{"no":496,"file":"CreateTableStyle.lsp","cmd":"CreateTableStyle","cat":"圖面管理","desc":"以對話框依單位與比例建立表格樣式（文字樣式、邊距、顏色），含 MyCAD LOGO。","usage":"執行 CreateTableStyle → 對話框選單位、比例、字高 → 確定","level":8,"lt":"⚠️","ver":"2026-01-12 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/CreateTableStyle.fas"},{"no":497,"file":"creattableformate.LSP","cmd":"creattableformate","cat":"圖面管理","desc":"檢查表格樣式字典，不存在就建立新的表格樣式並設定儲存格對齊與顏色。","usage":"執行 creattableformate → 自動檢查並建立表格樣式","level":5,"lt":"⚠️","ver":"2022-02-01 (檔案日期)","author":"網路程式","video":"","fas":"fas/creattableformate.fas"},{"no":498,"file":"cross-2l-draw-cl.lsp","cmd":"cross-2l-draw-cl","cat":"繪圖","desc":"選兩線交叉的虛擬線段，自動計算兩側牆線的交會範圍並畫出中心線。","usage":"執行 cross-2l-draw-cl → 點選虛擬線起點 → 點選另一端 → 自動畫中心線","level":7,"lt":"✅","ver":"2024-11-11 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/cross-2l-draw-cl.fas"},{"no":499,"file":"cross-2l-draw-cl2.lsp","cmd":"cross-2l-draw-cl2","cat":"繪圖","desc":"以切點計算兩線之間的中心線，遇弧線時以三點畫弧，可連續執行。","usage":"執行 cross-2l-draw-cl2 → 點選虛擬線起點 → 點選另一端 → 連續畫中心線","level":8,"lt":"✅","ver":"2025-11-17 (檔案日期)","author":"chengshunyi（含 Lee Mac 三點圓函式）","video":"https://youtu.be/rsmDDD38Cdw","fas":"fas/cross-2l-draw-cl2.fas"},{"no":500,"file":"cross-2l-i-WP.lsp","cmd":"cross-2l-i-WP","cat":"圖塊/屬性","desc":"沿兩牆線切線求中心線並插入止水墩圖塊（WALL-WP），尺寸可設定高寬。","usage":"執行 cross-2l-i-WP → 點選虛擬線第一點、第二點 → 輸入止水墩尺寸","level":8,"lt":"✅","ver":"2025-03-19 (檔案日期)","author":"chengshunyi","video":"https://youtu.be/BWHE_SY6CiI","fas":"fas/cross-2l-i-WP.fas"},{"no":501,"file":"cross-2l-i-WT.lsp","cmd":"cross-2l-i-WT","cat":"圖塊/屬性","desc":"沿兩牆線切線求中心線並插入指定牆型式（WALL-type）圖塊。","usage":"執行 cross-2l-i-WT → 點選虛擬線第一點、第二點 → 輸入牆型式編號","level":8,"lt":"✅","ver":"2025-03-19 (檔案日期)","author":"chengshunyi","video":"https://youtu.be/7Ql9zsaDhBk","fas":"fas/cross-2l-i-WT.fas"},{"no":502,"file":"CTM.LSP","cmd":"ctm","cat":"文字","desc":"以第一次選取的文字內容取代第二次選取的文字（文字比對複製）。","usage":"執行 ctm → 選取來源文字 → 選取要改的文字","level":2,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/CTM.fas"},{"no":503,"file":"CTO-ui.LSP","cmd":"CTO-ui","cat":"對齊/排列","desc":"對話框版，把選取物件複製到曲線每個頂點，或依距離沿曲線等距放置。","usage":"執行 CTO-ui → 對話框選模式與間距 → 選取物件 → 指定基準點 → 選取曲線","level":7,"lt":"✅","ver":"2026-01-06 (檔案日期)","author":"MyCAD (chengshunyi)","video":"","fas":"fas/CTO-ui.fas"},{"no":504,"file":"CTO.lsp","cmd":"CTO","cat":"對齊/排列","desc":"命令列版，把選取物件複製到曲線每個頂點，或依距離沿曲線等距放置，記憶上次輸入。","usage":"執行 CTO → 選模式（折點或等距）→ 輸入距離 → 選取物件 → 基準點 → 選取曲線","level":6,"lt":"✅","ver":"2026-01-06 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/CTO.fas"},{"no":505,"file":"CursorRotate.lsp","cmd":"cr","cat":"系統/授權","desc":"旋轉十字游標（SNAPANG），可依物件角度、固定角度或坡度百分比對齊。","usage":"執行 cr → 點選物件或選 Angle/Grade → 輸入角度或坡度","level":4,"lt":"✅","ver":"Version 1.0 2015-09-25","author":"Lee Mac","video":"","fas":""},{"no":506,"file":"cut-dim-l.LSP","cmd":"cut-dim-l、cdli","cat":"標註","desc":"以切割線切齊或延伸尺寸標註的延伸線，cdli 僅處理內部延伸線。","usage":"執行 cut-dim-l → 選取尺寸 → 指定切割線兩點","level":6,"lt":"✅","ver":"20231002","author":"hak_vz / chengshunyi","video":"https://youtu.be/pPQssbJBMcw","fas":"fas/cut-dim-l.fas"},{"no":507,"file":"cut-line-put-dim.lsp","cmd":"cut-line-put-dim","cat":"標註","desc":"以兩點柵選穿過的線，求交點後切線並自動標註牆邊間距尺寸。","usage":"執行 cut-line-put-dim → 點選第一點 → 拖曳點選第二點 → 自動標註","level":5,"lt":"✅","ver":"2024-10-29 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/cut-line-put-dim.fas"},{"no":508,"file":"cut-line-put-dim2.lsp","cmd":"cut-line-put-dim2L、cut-line-put-dim2A、cut-line-put-dim2","cat":"標註","desc":"以虛擬線切過牆邊、牆心、柱心，自動計算並標註連續尺寸，L 為水平垂直、A 為對齊。","usage":"執行 cut-line-put-dim2L 或 2A → 點選虛擬線起點 → 點選另一端 → 自動標註","level":7,"lt":"✅","ver":"20241030","author":"chengshunyi","video":"","fas":"fas/cut-line-put-dim2.fas"},{"no":509,"file":"cut-line-put-dim2S.lsp","cmd":"cut-line-put-dim2LS、cut-line-put-dim2AS、cut-line-put-dim2S","cat":"標註","desc":"同 cut-line-put-dim2，切線自動標註牆邊牆心柱心，尺寸加入比例分類。","usage":"執行 cut-line-put-dim2LS 或 2AS → 點選虛擬線起點 → 點選另一端 → 自動標註","level":7,"lt":"✅","ver":"20251019","author":"chengshunyi","video":"","fas":"fas/cut-line-put-dim2S.fas"},{"no":510,"file":"CWS.lsp","cmd":"CWS","cat":"繪圖","desc":"以對話框設定前綴與最大 N 值，依等差 5 自動建立牆體複線（MLINE）樣式。","usage":"執行 CWS → 對話框設定前綴與最大值、是否強制更新 → 確定","level":7,"lt":"✅","ver":"2026-01-18 (檔案日期)","author":"MyCAD","video":"","fas":"fas/CWS.fas"},{"no":511,"file":"D-SLAB.LSP","cmd":"（無，副程式庫）","cat":"其他","desc":"（加密檔 PROTECTED LISP，無法讀取原始碼）檔案內容為加密或二進位資料，無法讀取原始程式。","usage":"載入後依內含指令使用（無法判讀）","level":5,"lt":"❓","ver":"2021-03-28 (檔案日期)","author":"—","video":"","fas":"fas/D-SLAB.fas"},{"no":512,"file":"DA.lsp","cmd":"DA","cat":"面積/數量統計","desc":"標註列式加總長度與面積，對話框選簡略或詳細公式、高度模式（依圖層名數字或統一值）與輸出圖層比例。","usage":"執行 DA → 對話框設定模式與高度 → 選取標註 → 指定輸出位置","level":8,"lt":"✅","ver":"v3.8 (2026-05-03 檔案日期)","author":"MyCAD (ChengBar)","video":"","fas":"fas/DA.fas"},{"no":513,"file":"data_col_plan.lsp","cmd":"data_col_plan","cat":"圖塊/屬性","desc":"讀取資料表圖塊的柱資料屬性，在平面圖自動插入柱線並標註尺寸。","usage":"執行 data_col_plan → 選取資料表圖塊 → 指定基準點 → 自動繪製柱與標註","level":8,"lt":"✅","ver":"20210612","author":"chengshunyi","video":"https://youtu.be/-pOpOSo1VmY","fas":"fas/data_col_plan.fas"},{"no":514,"file":"data_STAIR_sec-old.lsp","cmd":"data_STAIR_sec","cat":"剖面/結構","desc":"讀取樓梯資料表圖塊，自動繪製樓梯剖面，含級高級深、轉折、斜面、標註及扶手開關（舊版）。","usage":"執行 data_STAIR_sec → 選取資料表圖塊 → 點選起點 → 自動畫樓梯剖面","level":8,"lt":"✅","ver":"20211009","author":"cheng bar","video":"","fas":"fas/data_STAIR_sec-old.fas"},{"no":515,"file":"data_STAIR_sec.lsp","cmd":"data_STAIR_sec","cat":"剖面/結構","desc":"讀取樓梯資料表圖塊，自動繪製樓梯剖面（含轉折、斜面、側板、踢腳、扶手、尺寸），梯段群組化並可還原環境。","usage":"執行 data_STAIR_sec → 選取資料表圖塊 → 點選起點 → 自動畫樓梯剖面","level":9,"lt":"✅","ver":"20220405","author":"cheng bar","video":"","fas":"fas/data_STAIR_sec.fas"},{"no":516,"file":"data_STAIR_sec_b.lsp","cmd":"data_STAIR_sec_b","cat":"剖面/結構","desc":"樓梯剖面自動繪製，起踏在後版本，其餘功能同 data_STAIR_sec。","usage":"執行 data_STAIR_sec_b → 選取資料表圖塊 → 點選起點 → 自動畫樓梯剖面","level":9,"lt":"✅","ver":"20220405","author":"cheng bar","video":"","fas":"fas/data_STAIR_sec_b.fas"},{"no":517,"file":"data_STAIR_sec_cal.lsp","cmd":"data_STAIR_sec_cal","cat":"剖面/結構","desc":"讀取樓梯資料表屬性，計算實際級高並將餘數分配於前面，各梯段標註尺寸。","usage":"執行 data_STAIR_sec_cal → 選取資料表圖塊 → 點選基準點 → 自動標註各段級高","level":6,"lt":"✅","ver":"20210615","author":"chengshunyi","video":"","fas":"fas/data_STAIR_sec_cal.fas"},{"no":518,"file":"data_STAIR_sec_cal_M1.lsp","cmd":"data_STAIR_sec_cal_M1","cat":"剖面/結構","desc":"樓梯級高計算標註（M1 型），讀取資料表屬性並將餘數分配於前面。","usage":"執行 data_STAIR_sec_cal_M1 → 選取資料表圖塊 → 點選基準點","level":6,"lt":"✅","ver":"20210615","author":"chengshunyi","video":"","fas":"fas/data_STAIR_sec_cal_M1.fas"},{"no":519,"file":"data_STAIR_sec_cal_P1.lsp","cmd":"data_STAIR_sec_cal_P1","cat":"剖面/結構","desc":"樓梯級高計算標註（P1 型），讀取資料表屬性並將餘數分配於前面。","usage":"執行 data_STAIR_sec_cal_P1 → 選取資料表圖塊 → 點選基準點","level":6,"lt":"✅","ver":"20210615","author":"chengshunyi","video":"","fas":"fas/data_STAIR_sec_cal_P1.fas"},{"no":520,"file":"data_STAIR_sec_v2.lsp","cmd":"data_STAIR_sec_v2","cat":"剖面/結構","desc":"樓梯剖面自動繪製 v2 版，含斜面深度、尺寸及扶手開關，剖面方向往右。","usage":"執行 data_STAIR_sec_v2 → 選取資料表圖塊 → 點選起點 → 自動畫樓梯剖面","level":9,"lt":"✅","ver":"2025-04-25 (檔案日期)","author":"cheng bar","video":"","fas":"fas/data_STAIR_sec_v2.fas"},{"no":521,"file":"data_STAIR_secele.lsp","cmd":"data_STAIR_secele","cat":"剖面/結構","desc":"樓梯剖面與短向剖立面自動繪製，含斜面深度、扶手位置、樓梯寬度與尺寸。","usage":"執行 data_STAIR_secele → 選取資料表圖塊 → 點選起點 → 自動畫剖面與立面","level":9,"lt":"✅","ver":"2025-07-21 (檔案日期)","author":"cheng bar","video":"","fas":"fas/data_STAIR_secele.fas"},{"no":522,"file":"dataext_door_winddow_cabinet.lsp","cmd":"dataext_door_winddow_cabinet","cat":"面積/數量統計","desc":"以 Schedule.dxe 資料擷取設定檔，對窗與櫃體圖塊執行資料擷取產生表格。","usage":"執行 dataext_door_winddow_cabinet → 自動以 Schedule.dxe 擷取窗、櫃體圖塊","level":4,"lt":"✅","ver":"20250703","author":"chengshunyi","video":"","fas":"fas/dataext_door_winddow_cabinet.fas"},{"no":523,"file":"date-add-mil.LSP","cmd":"test1","cat":"其他","desc":"以 DIESEL 運算依目前日期加減天數，輸出各種日期格式字串的測試程式。","usage":"執行 test1 → 顯示日期加減後字串","level":3,"lt":"✅","ver":"2025-06-21 (檔案日期)","author":"—","video":"","fas":"fas/date-add-mil.fas"},{"no":524,"file":"DBCount.lsp","cmd":"dbcount","cat":"面積/數量統計","desc":"統計目前配置中標準、動態圖塊與外參數量，並依可見性狀態分別計數，可輸出 TXT/CSV。","usage":"執行 dbcount → 選取圖塊（Enter 全選）→ 選擇輸出 TXT 或 CSV","level":7,"lt":"✅","ver":"Version 1.1 2013-11-27","author":"Lee Mac","video":"","fas":"fas/DBCount.fas"},{"no":525,"file":"dbom-2-table.LSP","cmd":"dbom-2-table","cat":"圖塊/屬性","desc":"依圖塊屬性資料以 LINE、PLINE、TEXT 畫出表格（BOM 表）。","usage":"執行 dbom-2-table → 指定表格位置 → 自動畫表格線與文字","level":7,"lt":"✅","ver":"20250717","author":"chengshunyi","video":"","fas":"fas/dbom-2-table.fas"},{"no":526,"file":"DCE.lsp","cmd":"DCE","cat":"繪圖","desc":"以選取物件為中心，利用柵選射線找兩側邊界，畫出柱立面線，可設定柱寬、圖層、顏色與忽略圖層。","usage":"執行 DCE → 對話框設定柱寬、圖層、顏色 → 點選物件 → 自動畫柱立面線","level":9,"lt":"✅","ver":"2026-10-03 (檔案日期)","author":"ChengBar (Shun_Yi Studio)","video":"","fas":"fas/DCE.fas"},{"no":527,"file":"Dcl_Tiles.LSP","cmd":"DclT、Dcl_Tiles、DclR、Dcl_Renum","cat":"其他","desc":"AutoLISP DCL 對話框控制函式庫，附編輯、列表、頁籤範例，及 Dcl_Renum 重新編號。","usage":"執行 DclT 看範例，或載入後由其他程式呼叫函式庫","level":9,"lt":"⚠️","ver":"R13 (2-26-01 建立)","author":"Terry Miller (autolisp-exchange.com)","video":"","fas":"fas/Dcl_Tiles.fas"},{"no":528,"file":"DCLATT.LSP","cmd":"dclatt","cat":"圖塊/屬性","desc":"選取圖塊後動態生成含各屬性欄位的對話框，修改屬性值後回寫圖塊。","usage":"執行 dclatt → 選取圖塊 → 對話框編輯屬性 → 確定","level":6,"lt":"✅","ver":"20230414","author":"Kenny Ramage (AfraLISP) / chengshunyi","video":"","fas":"fas/DCLATT.fas"},{"no":529,"file":"def-LayerToolMenu.LSP","cmd":"def-LayerToolMenu、SetDimLayer、SetXrefLayer、SetHatchLayer、SetCenterLayer","cat":"圖層","desc":"對話框選單設定預設圖層：標註（DIMLAYER）、外參、填充（HPLAYER）、中心線圖層。","usage":"執行 def-LayerToolMenu → 選擇要設定的類別 → 從清單選圖層 → 確定","level":7,"lt":"✅","ver":"2025-10-07 (檔案日期)","author":"MyCAD","video":"","fas":"fas/def-LayerToolMenu.fas"},{"no":530,"file":"Del-dims.LSP","cmd":"Del-dims-w、Del-dims-w-pl、Del-dims-w-pl-la","cat":"修改","desc":"刪除標註，可依框選範圍、聚合線範圍或指定圖層進行。","usage":"執行 Del-dims-w → 框選範圍（或選聚合線 / 指定圖層）→ 刪除標註","level":3,"lt":"✅","ver":"20240810","author":"chengshunyi","video":"","fas":"fas/Del-dims.fas"},{"no":531,"file":"del-pl-la.lsp","cmd":"del-pl-la-sel、del-pl-la","cat":"修改","desc":"依圖層名稱清單過濾，刪除模型空間中該圖層的聚合線與填充。","usage":"執行 del-pl-la → 輸入或選取圖層 → 自動刪除聚合線與填充","level":4,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"—","video":"","fas":"fas/del-pl-la.fas"},{"no":532,"file":"del-type-object.lsp","cmd":"del-type-object","cat":"修改","desc":"依選取物件的類型，刪除圖面內同類型的所有物件（Enter 為全部）。","usage":"執行 del-type-object → 選取要刪除類型的物件或 Enter","level":3,"lt":"✅","ver":"20240208","author":"chengshunyi","video":"","fas":"fas/del-type-object.fas"},{"no":533,"file":"del-x-line.LSP","cmd":"del-x-line、del-x-line-be","cat":"修改","desc":"刪除模型空間中的 XLINE 構造線。","usage":"執行 del-x-line → 自動刪除構造線","level":2,"lt":"✅","ver":"2024-03-16 (檔案日期)","author":"—","video":"","fas":"fas/del-x-line.fas"},{"no":534,"file":"del-xreftitblk.LSP","cmd":"del-xreftitblk","cat":"圖面管理","desc":"選取物件後，刪除外參圖框圖塊並拆離相關外部參照。","usage":"執行 del-xreftitblk → 點選外參物件 → 自動刪除並拆離","level":4,"lt":"✅","ver":"2021-11-17 (檔案日期)","author":"—","video":"","fas":"fas/del-xreftitblk.fas"},{"no":535,"file":"deldim.lsp","cmd":"deldim-walk、deldim-all、deldim-all-w","cat":"修改","desc":"刪除標註：步行距離標註樣式（步行距離CM2M）、全圖標註或框選範圍內標註。","usage":"執行 deldim-walk 或 deldim-all → 自動刪除；deldim-all-w 需框選範圍","level":2,"lt":"✅","ver":"2022-11-20 (檔案日期)","author":"—","video":"","fas":"fas/deldim.fas"},{"no":536,"file":"delete_unload_xref.LSP","cmd":"delete_unload_xref","cat":"圖面管理","desc":"找出並拆離未載入（找不到路徑）的外部參照。","usage":"執行 delete_unload_xref → 自動拆離未載入外參","level":3,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/delete_unload_xref.fas"},{"no":537,"file":"DeleteInLayouts-some.lsp","cmd":"DeleteInLayouts-some","cat":"修改","desc":"逐一切換各配置（排除模型），刪除指定兩個範圍內的物件。","usage":"執行 DeleteInLayouts-some → 自動處理所有配置","level":4,"lt":"✅","ver":"20251117","author":"chengshunyi","video":"","fas":"fas/DeleteInLayouts-some.fas"},{"no":538,"file":"delvert.lsp","cmd":"delvert","cat":"修改","desc":"輸入距離，刪除聚合線中短於該距離的線段頂點（研發中）。","usage":"執行 delvert → 選取聚合線 → 輸入距離","level":5,"lt":"✅","ver":"20231001","author":"chengshunyi","video":"","fas":"fas/delvert.fas"},{"no":539,"file":"DEMO-VECTORS.lsp","cmd":"DEMO","cat":"其他","desc":"示範在 DCL 對話框圖像區以 Vectorize 函式繪製向量圖的範例。","usage":"執行 DEMO → 顯示示範對話框 → 確定關閉","level":6,"lt":"✅","ver":"2024-10-24 (檔案日期)","author":"網路範例程式","video":"","fas":"fas/DEMO-VECTORS.fas"},{"no":540,"file":"det-hat-reset.LSP","cmd":"det-hat-reset","cat":"修改","desc":"重設圖面中特定填充（AR-SAND、AR-CONC、PLAST、EARTH）的比例，依 LTSCALE 調整。","usage":"執行 det-hat-reset → 自動重設填充比例","level":4,"lt":"✅","ver":"2022-04-16 (檔案日期)","author":"—","video":"","fas":"fas/det-hat-reset.fas"},{"no":541,"file":"dh-layout-byname.lsp","cmd":"del-layout-byname-pak、del-layout-byname-lic、del-layout-byname-lan、del-layout-byname-rw、del-layout-ALL、del-layout-byname、hold-layout-byname-pak、hold-layout-byname-lic、hold-layout-byname-lan、hold-layout-byname-rw、hold-layout-byname","cat":"出圖/列印","desc":"依配置名稱刪除或保留特定類別（停車、法定、景觀等）的配置，也可全刪。","usage":"執行 del-layout-byname-pak 等 → 自動依名稱刪除或保留配置","level":6,"lt":"✅","ver":"2025-05-08 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/dh-layout-byname.fas"},{"no":542,"file":"dia5a.lsp","cmd":"dia5a","cat":"系統/授權","desc":"以對話框設定聚合線寬、圓角半徑、文字高度與自動存檔時間等系統變數。","usage":"執行 dia5a → 對話框輸入數值 → 確定","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"MyCAD","video":"","fas":""},{"no":543,"file":"dia6a.lsp","cmd":"dia6a","cat":"系統/授權","desc":"以對話框切換 APBOX、ATTDIA、ATTREQ、FILEDIA、FILLMODE 等系統變數開關，含向量圖示。","usage":"執行 dia6a → 對話框勾選各項開關 → 確定","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"MyCAD","video":"","fas":""},{"no":544,"file":"dia7c.lsp","cmd":"dia7c","cat":"文字","desc":"以對話框選擇字型、高度、角度後書寫文字，含範例字串與字型檢查。","usage":"執行 dia7c → 對話框選字型、高度、角度 → 確定 → 指定文字位置","level":6,"lt":"✅","ver":"2022-12-31 (檔案日期)","author":"—","video":"","fas":"fas/dia7c.fas"},{"no":545,"file":"Dialog.LSP","cmd":"（無，副程式庫）","cat":"其他","desc":"DCL 對話框函式庫，提供動態生成的圖層勾選（GetLayers）、圖塊選取等對話框函式。","usage":"載入後由其他程式呼叫函式（無獨立指令）","level":8,"lt":"⚠️","ver":"2024-09-21 (檔案日期)","author":"gile 等","video":"","fas":"fas/Dialog.fas"},{"no":546,"file":"DIM-1.LSP","cmd":"（無，副程式庫）","cat":"標註","desc":"（加密檔 PROTECTED LISP，無法讀取原始碼）檔案內容為加密或二進位資料，無法讀取原始程式，推測為標註相關舊程式。","usage":"載入後依內含指令使用（無法判讀）","level":5,"lt":"❓","ver":"2021-03-28 (檔案日期)","author":"—","video":"","fas":"fas/DIM-1.fas"},{"no":547,"file":"dim-acad.lsp","cmd":"RestoreDimByCannoscale","cat":"標註","desc":"依目前註解比例（CANNOSCALE）還原對應的標註樣式（如 DIM100）後啟動線性標註，並設定單位。","usage":"執行 RestoreDimByCannoscale → 自動還原尺寸型式 → 進入線性標註","level":5,"lt":"✅","ver":"2025-09-21 (檔案日期)","author":"—","video":"","fas":"fas/dim-acad.fas"},{"no":548,"file":"dim-add-0.lsp","cmd":"dim-add-0、dim-add-10","cat":"標註","desc":"為選取尺寸的文字字尾補 0，並可將尺寸係數放大十倍，例如顯示 ±<>。","usage":"執行 dim-add-0 → 選取尺寸 → 自動補字尾 0","level":4,"lt":"✅","ver":"20241121","author":"chengshunyi","video":"https://youtu.be/2JN87ETDHkI","fas":"fas/dim-add-0.fas"},{"no":549,"file":"dim-align.lsp","cmd":"dim-h-ext-cut、dim-v-ext-cut、dim-h-dim-align、dim-v-dim-align","cat":"標註","desc":"水平或垂直尺寸的延伸線切齊與尺寸線對齊，點選位置後批次修改。","usage":"執行 dim-h-ext-cut 等 → 選取尺寸 → 點選切斷或對齊位置","level":6,"lt":"✅","ver":"20240821","author":"chengshunyi（原 97'05'24）","video":"","fas":"fas/dim-align.fas"},{"no":550,"file":"dim-arrtxthig.lsp","cmd":"dim-arrtxthig","cat":"標註","desc":"選取尺寸後，依輸入的標註比例（1:100）重設箭頭、文字高度、文字間距與延伸線等參數。","usage":"執行 dim-arrtxthig → 輸入標註比例 → 選取尺寸","level":5,"lt":"✅","ver":"2022-11-20 (檔案日期)","author":"—","video":"","fas":"fas/dim-arrtxthig.fas"},{"no":551,"file":"dim-auto-align.LSP","cmd":"dim-auto-align","cat":"標註","desc":"自動對齊尺寸線，水平、垂直及角度尺寸均適用，點選切齊或延伸位置。","usage":"執行 dim-auto-align → 選取尺寸 → 點選要切齊或延伸的位置","level":6,"lt":"✅","ver":"20240822","author":"chengshunyi","video":"https://youtu.be/M6EHb40ZXOE","fas":"fas/dim-auto-align.fas"},{"no":552,"file":"dim-blk-reset.lsp","cmd":"dim-blk-reset","cat":"圖塊/屬性","desc":"強制重建標註用圖塊（斜線、柱心、牆心、圓點、箭頭等），以 entmake 建立。","usage":"執行 dim-blk-reset → 自動更新所有標註圖塊","level":6,"lt":"✅","ver":"20241109","author":"chengshunyi","video":"","fas":"fas/dim-blk-reset.fas"},{"no":553,"file":"dim-build-prop.LSP","cmd":"dim-build-prop","cat":"標註","desc":"選取房屋線與地界線，標註建物與地界的垂直距離。","usage":"執行 dim-build-prop → 選取房屋線 → 選取地界線","level":4,"lt":"✅","ver":"20240821","author":"chengshunyi","video":"","fas":"fas/dim-build-prop.fas"},{"no":554,"file":"DIM-CALC-la-row.lsp","cmd":"DIM-CALC-la-row","cat":"面積/數量統計","desc":"標註（圖層分類）列式計算，對話框設定比例、乘積高度、字高與換行長度，輸出分類計算式與結果。","usage":"執行 DIM-CALC-la-row → 對話框設定 → 選取標註 → 指定輸出位置","level":8,"lt":"✅","ver":"2026-04-20 (檔案日期)","author":"MyCAD","video":"","fas":"fas/DIM-CALC-la-row.fas"},{"no":555,"file":"DIM-CALC-LA.LSP","cmd":"DIM-CALC-LA","cat":"面積/數量統計","desc":"尺寸加總（加值面積）計算，對話框選精確度模式、比例、單位與文字型式，可依圖層分類並自動歸層。","usage":"執行 DIM-CALC-LA → 對話框設定 → 選取標註 → 指定輸出位置","level":8,"lt":"✅","ver":"2026-04-18 (檔案日期)","author":"MyCAD","video":"https://youtu.be/Gh9CfiijG_E","fas":"fas/DIM-CALC-LA.fas"},{"no":556,"file":"DIM-CALC-PRO.lsp","cmd":"DIM-CALC-PRO","cat":"面積/數量統計","desc":"標註分類計算，可依顯示值或原始值加總，並可依圖層分類計算且自動歸層。","usage":"執行 DIM-CALC-PRO → 對話框設定 → 選取標註 → 指定輸出位置","level":8,"lt":"✅","ver":"2026-04-18 (檔案日期)","author":"MyCAD","video":"","fas":"fas/DIM-CALC-PRO.fas"},{"no":557,"file":"dim-div-plan.lsp","cmd":"dim-div-plan","cat":"標註","desc":"選取尺寸後依建議等分數，寫出等分文字串（如 5@26=xxxx），以 26 為預設間距。","usage":"執行 dim-div-plan → 選取尺寸 → 輸入等分數 → 指定文字位置","level":4,"lt":"✅","ver":"20211120","author":"chengshunyi","video":"https://youtu.be/PiJ2BmEg8ww","fas":"fas/dim-div-plan.fas"},{"no":558,"file":"dim-div-sec.lsp","cmd":"dim-div-sec","cat":"標註","desc":"選取尺寸後依單位換算並寫出等分文字串（如 5@17.3=xxxx），用於剖面級高標註。","usage":"執行 dim-div-sec → 選取尺寸 → 輸入等分數 → 指定文字位置","level":5,"lt":"✅","ver":"2024-10-22 (檔案日期)","author":"chengshunyi","video":"https://youtu.be/a9kkYCtBEV8","fas":"fas/dim-div-sec.fas"},{"no":559,"file":"dim-div-st.lsp","cmd":"dim-div-st","cat":"標註","desc":"點選級高級深兩點，依單位換算寫出等分文字串，平面剖面通用，須能整除。","usage":"執行 dim-div-st → 點選第一點 → 點選第二點 → 輸入等分數","level":5,"lt":"✅","ver":"2024-10-23 (檔案日期)","author":"chengshunyi","video":"https://youtu.be/fBKGk0AL3uE","fas":"fas/dim-div-st.fas"},{"no":560,"file":"dim-div.lsp","cmd":"dim-div","cat":"標註","desc":"選取尺寸後依輸入等分數寫出等分文字串（如 5@17.3=xxxx）。","usage":"執行 dim-div → 選取尺寸 → 輸入等分數 → 指定文字位置","level":3,"lt":"✅","ver":"20211120","author":"chengshunyi","video":"","fas":"fas/dim-div.fas"},{"no":561,"file":"dim-ext-len-m.lsp","cmd":"dim-ext-len-m","cat":"標註","desc":"輸入偏移距離後，將選取尺寸的尺寸線與文字垂直方向平移。","usage":"執行 dim-ext-len-m → 輸入距離 → 選取尺寸","level":4,"lt":"✅","ver":"20250919","author":"—","video":"","fas":"fas/dim-ext-len-m.fas"},{"no":562,"file":"dim-ext-len.lsp","cmd":"dim-ext-len","cat":"標註","desc":"修改選取尺寸的延伸線長度（旋轉或對齊尺寸），以輸入延伸量調整端點。","usage":"執行 dim-ext-len → 輸入延伸線長度 → 選取尺寸","level":6,"lt":"✅","ver":"20231002","author":"chengshunyi","video":"","fas":"fas/dim-ext-len.fas"},{"no":563,"file":"dim-inch-cm.LSP","cmd":"dim-inch-cm、dim-add-10","cat":"標註","desc":"將英吋尺寸轉成公分，含分數處理，並可補字尾 0 或放大十倍。","usage":"執行 dim-inch-cm → 選取尺寸 → 自動轉換","level":5,"lt":"✅","ver":"20241121","author":"chengshunyi","video":"","fas":"fas/dim-inch-cm.fas"},{"no":564,"file":"dim-line-ext-l.lsp","cmd":"dim-line-ext-l","cat":"標註","desc":"輸入長度修改尺寸延伸線長度，通常設 0 供柱心線尺寸標註使用。","usage":"執行 dim-line-ext-l → 輸入延伸長度 → 選取尺寸","level":6,"lt":"✅","ver":"20240821","author":"chengshunyi","video":"","fas":"fas/dim-line-ext-l.fas"},{"no":565,"file":"dim-R-modify.lsp","cmd":"dim-r-modify","cat":"標註","desc":"對話框重設已標註尺寸的單位、比例、字高、字寬、字距與小數位數。","usage":"執行 dim-r-modify → 對話框設定參數 → 選取尺寸 → 確定","level":8,"lt":"✅","ver":"20250914","author":"MyCAD","video":"","fas":"fas/dim-R-modify.fas"},{"no":566,"file":"DIM-SET.LSP","cmd":"dim-set","cat":"標註","desc":"設定一組標註系統變數（DIMASZ、DIMCLRD 等），並插入 dim-base 圖塊的老式標註設定。","usage":"執行 dim-set → 輸入單位與比例 → 自動設定標註變數","level":4,"lt":"✅","ver":"87.09.25","author":"—","video":"","fas":"fas/DIM-SET.fas"},{"no":567,"file":"dim-sp-sc.lsp","cmd":"dim-sp-sc-2p、dim-sp-sc-o","cat":"標註","desc":"以特別比例標註尺寸（邊到邊等形式），標註前自動建立標註圖層並設定線型。","usage":"執行 dim-sp-sc-2p → 輸入比例 → 指定兩點標註（或 -o 選物件）","level":6,"lt":"✅","ver":"20250317","author":"chengshunyi","video":"https://youtu.be/9561J0p6KH4","fas":"fas/dim-sp-sc.fas"},{"no":568,"file":"dim-sp6.LSP","cmd":"dim-sp6","cat":"標註","desc":"以 DIMSPACE 將基準線尺寸的間距調整為指定值（預設 6mm）。","usage":"執行 dim-sp6 → 輸入間距 → 選取基準尺寸 → 選取要調整的尺寸","level":2,"lt":"✅","ver":"20220903","author":"chengshunyi","video":"","fas":"fas/dim-sp6.fas"},{"no":569,"file":"DIM-SUM-EX.LSP","cmd":"DIM-SUM-EX","cat":"面積/數量統計","desc":"尺寸加總（加值面積計算）對話框版，可依顯示值或原精度加總尺寸，輸出計算式與高度、比例。","usage":"執行 DIM-SUM-EX → 對話框設定 → 選取標註 → 指定輸出位置","level":8,"lt":"✅","ver":"2026-04-18 (檔案日期)","author":"MyCAD","video":"https://youtu.be/oc5TR-jLjPw","fas":"fas/DIM-SUM-EX.fas"},{"no":570,"file":"dim-sw-ab.lsp","cmd":"dim-sw-ab","cat":"標註","desc":"切換選取尺寸的文字位於尺寸線的上方或下方（換邊）。","usage":"執行 dim-sw-ab → 選取尺寸 → 自動換邊","level":2,"lt":"✅","ver":"20240221","author":"chengshunyi","video":"https://youtu.be/lcM1wYR3qL0","fas":"fas/dim-sw-ab.fas"},{"no":571,"file":"dim-text-move.LSP","cmd":"dim-text-move","cat":"標註","desc":"將尺寸文字位置鏡射（翻轉）到另一側，使用 Lee Mac 的矩陣鏡射函式。","usage":"執行 dim-text-move → 選取尺寸 → 自動鏡射文字","level":6,"lt":"✅","ver":"2024-09-29 (檔案日期)","author":"Lee Mac / chengshunyi","video":"","fas":"fas/dim-text-move.fas"},{"no":572,"file":"dim-to-int.LSP","cmd":"dim-to-int-0、dim-to-int-1","cat":"標註","desc":"將圖面標註的誤差小數點調整為整數（0）或一位 0.5（1），逐一選取尺寸修改端點。","usage":"執行 dim-to-int-0 → 逐一選取尺寸 → Enter 結束","level":5,"lt":"✅","ver":"20250602","author":"chengshunyi","video":"https://youtu.be/dWz4yZDQ1QM","fas":"fas/dim-to-int.fas"},{"no":573,"file":"DIM-TO-LENGTH.lsp","cmd":"DIM-TO-LENGTH","cat":"標註","desc":"輸入目標垂直距離，連續選取標註並將其端點調整成該距離。","usage":"執行 DIM-TO-LENGTH → 輸入目標距離 → 連續選取標註 → Enter 結束","level":5,"lt":"✅","ver":"2025-11-24 (檔案日期)","author":"—","video":"https://youtu.be/tDJSQ-oh26I","fas":"fas/DIM-TO-LENGTH.fas"},{"no":574,"file":"dim-total.lsp","cmd":"dim-total","cat":"面積/數量統計","desc":"選取多個尺寸，加總其量測值並在圖面寫出總和文字。","usage":"執行 dim-total → 選取標註 → 指定文字位置","level":4,"lt":"✅","ver":"2023-06-07 (檔案日期)","author":"—","video":"","fas":"fas/dim-total.fas"},{"no":575,"file":"dim-upd.lsp","cmd":"Dim-Upd-LSF、Dim-Upd-LO","cat":"標註","desc":"批次修改選取尺寸的長度倍數（LSF）或整體尺寸文字大小比例。","usage":"執行 Dim-Upd-LSF → 窗選尺寸 → 輸入長度倍數（或整體比例）","level":6,"lt":"✅","ver":"20240211","author":"Lee Mac / chengshunyi","video":"","fas":"fas/dim-upd.fas"},{"no":576,"file":"dim-VV1.LSP","cmd":"dim-VV1","cat":"標註","desc":"選取水平尺寸後，點選位置切齊或延伸尺寸線端點，只能改水平尺寸。","usage":"執行 dim-VV1 → 選取尺寸 → 點選要切齊或延伸的位置","level":5,"lt":"✅","ver":"20240822","author":"chengshunyi","video":"","fas":"fas/dim-VV1.fas"},{"no":577,"file":"dim-x-mm254.lsp","cmd":"dim-x-mm254","cat":"標註","desc":"將英吋小數尺寸乘以 25.4 轉成公制 mm 並覆寫尺寸文字。","usage":"執行 dim-x-mm254 → 選取尺寸 → 自動轉換","level":5,"lt":"✅","ver":"20241128","author":"chengshunyi","video":"","fas":"fas/dim-x-mm254.fas"},{"no":578,"file":"DIM.LSP","cmd":"（無，副程式庫）","cat":"標註","desc":"（加密檔 PROTECTED LISP，無法讀取原始碼）檔案內容為加密或二進位資料，無法讀取原始程式，推測為標註相關舊程式。","usage":"載入後依內含指令使用（無法判讀）","level":5,"lt":"❓","ver":"2021-03-28 (檔案日期)","author":"—","video":"","fas":"fas/DIM.fas"},{"no":579,"file":"DIM_TOTAL.LSP","cmd":"DIM_TOTAL","cat":"面積/數量統計","desc":"標註（步行距離）加總列式彙總整合版，對話框選一般累計、重複步行距離判斷或依首字分組三種模式。","usage":"執行 DIM_TOTAL → 對話框選圖層、文字樣式與模式 → 選取標註 → 指定輸出位置","level":8,"lt":"✅","ver":"2026-05-02 (檔案日期)","author":"MyCAD","video":"","fas":"fas/DIM_TOTAL.fas"},{"no":580,"file":"DIMA.LSP","cmd":"（無，副程式庫）","cat":"標註","desc":"（加密檔 PROTECTED LISP，無法讀取原始碼）檔案內容為加密或二進位資料，無法讀取原始程式，推測為標註相關舊程式。","usage":"載入後依內含指令使用（無法判讀）","level":5,"lt":"❓","ver":"2021-03-28 (檔案日期)","author":"—","video":"","fas":"fas/DIMA.fas"},{"no":581,"file":"DimAutoOrdinateMECH.lsp","cmd":"DimAutoOrdinateMECH","cat":"標註","desc":"選取聚合線後，以自訂原點自動在各頂點標註座標文字（機械式座標標註）。","usage":"執行 DimAutoOrdinateMECH → 選取聚合線 → 指定原點 → 自動標註","level":5,"lt":"✅","ver":"20230930","author":"chengshunyi","video":"","fas":"fas/DimAutoOrdinateMECH.fas"},{"no":582,"file":"DimCircles.LSP","cmd":"DimCircles","cat":"標註","desc":"選取多個圓後，選一條線或聚合線或弧，標註圓心投射到該物件的垂直尺寸。","usage":"執行 DimCircles → 選取圓 → 選取要標註到的物件","level":5,"lt":"✅","ver":"20240801","author":"chengshunyi","video":"","fas":"fas/DimCircles.fas"},{"no":583,"file":"DimConfigSetup-SCA.lsp","cmd":"DimConfigSetup-SCA、CheckDimBlocks、CreateDimBlocks","cat":"標註","desc":"對話框依比例清單（可複選）批次製作各種尺寸型式並建立標註用箭頭圖塊，可一次全部生成。","usage":"執行 DimConfigSetup-SCA → 複選比例與單位、小數位數 → 確定或按全部生成","level":9,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"MyCAD","video":"","fas":"fas/DimConfigSetup-SCA.fas"},{"no":584,"file":"DimConfigSetup.LSP","cmd":"DimConfigSetup","cat":"標註","desc":"對話框依比例與單位製作尺寸型式並更新圖面既有尺寸，清除樣式覆寫，含大中小型式。","usage":"執行 DimConfigSetup → 選擇比例、單位、小數位數 → 確定","level":9,"lt":"✅","ver":"2026-11-05 (檔案日期)","author":"MyCAD","video":"https://youtu.be/lsFgxnQAjr4","fas":"fas/DimConfigSetup.fas"},{"no":585,"file":"DIMEN.LSP","cmd":"dimen","cat":"標註","desc":"輸入 X、Y 軸總長與各軸柱數，自動畫軸線與柱號圓並標註柱間尺寸（老式柱網標註）。","usage":"執行 dimen → 輸入 X、Y 軸總長 → 輸入柱數與編號 → 自動畫軸線並標註","level":6,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/DIMEN.fas"},{"no":586,"file":"dimpoly.LSP","cmd":"dimpoly","cat":"標註","desc":"選取閉合多邊形（內角均為 90 度）後，指定偏移距離，沿各邊自動標註尺寸。","usage":"執行 dimpoly → 選取閉合聚合線 → 輸入偏移距離","level":6,"lt":"✅","ver":"2023-06-22 (檔案日期)","author":"Lee Mac / Kent Cooper","video":"","fas":"fas/dimpoly.fas"},{"no":587,"file":"DimPolyAssoc-1.lsp","cmd":"DPI、DPO","cat":"標註","desc":"標註聚合線各邊長度，DPI 標註在內側、DPO 標註在外側，並可記錄周長計算式於圖塊屬性。","usage":"執行 DPI 或 DPO → 選取聚合線 → 自動標註","level":7,"lt":"✅","ver":"2022.03 (Kent Cooper 2021.12.03 改編)","author":"Kent Cooper / cheng shunyi","video":"https://youtu.be/tDHAvs31GqU","fas":"fas/DimPolyAssoc-1.fas"},{"no":588,"file":"DimPolyAssoc-1h.lsp","cmd":"DimPolyAssoc-1h","cat":"面積/數量統計","desc":"含動態圖塊的聚合線面積牆高計算，輸入牆高後在圖塊屬性寫入牆面積等資料。","usage":"執行 DimPolyAssoc-1h → 選取聚合線與圖塊 → 輸入牆高","level":7,"lt":"✅","ver":"2021.06.06","author":"Cheng Shun-Yi (MyCAD)","video":"","fas":"fas/DimPolyAssoc-1h.fas"},{"no":589,"file":"DimPolyAssoc-1w.LSP","cmd":"DimPolyAssoc-1w","cat":"面積/數量統計","desc":"室內綠建材面積計算，依列索引寫出樓地板、天花、牆面積文字，並建立標註圖層。","usage":"執行 DimPolyAssoc-1w → 指定文字位置 → 選取聚合線與圖塊 → 自動輸出面積列","level":8,"lt":"✅","ver":"2022.03.20","author":"Cheng Shun-Yi (MyCAD)","video":"","fas":"fas/DimPolyAssoc-1w.fas"},{"no":590,"file":"DimPolyAssoc-2.lsp","cmd":"DPGI、DPGO","cat":"面積/數量統計","desc":"室內綠建材計算版，標註聚合線各邊長度（內側或外側），並將周長計算式寫入屬性。","usage":"執行 DPGI 或 DPGO → 選取聚合線 → 自動標註並寫入屬性","level":7,"lt":"✅","ver":"20230618","author":"Kent Cooper / cheng shunyi","video":"","fas":"fas/DimPolyAssoc-2.fas"},{"no":591,"file":"DimPolyAssoc.lsp","cmd":"DPI、DPO","cat":"標註","desc":"標註聚合線各邊長度於內側（DPI）或外側（DPO），使用文字定位與翻轉控制，並具尺寸關聯。","usage":"執行 DPI 或 DPO → 選取聚合線 → 自動標註","level":7,"lt":"✅","ver":"20250607","author":"Kent Cooper / chengshunyi","video":"https://youtu.be/tDHAvs31GqU","fas":"fas/DimPolyAssoc.fas"},{"no":592,"file":"Dims-lay-typ-c-old.lsp","cmd":"Dims-lay-typ-c-lh、Dims-lay-typ-c-llh、Dims-lay-typ-c","cat":"面積/數量統計","desc":"選取尺寸標註，依標註所在圖層名稱中的高度，統計總長×高=面積並輸出計算式文字；-lh 為簡式，-llh 為逐段明細。","usage":"執行指令 → 選取尺寸標註 → 指定文字起點 → 自動產生各圖層長×高=面積的計算式文字","level":6,"lt":"✅","ver":"20240810（2026-03-01 修改）","author":"chengshunyi","video":"","fas":"fas/Dims-lay-typ-c-old.fas"},{"no":593,"file":"Dims-lay-typ-c.lsp","cmd":"Dims-lay-typ-c-lh、Dims-lay-typ-c-llh、Dims-lay-typ-c","cat":"面積/數量統計","desc":"選取標註物件，依圖層名中的高度計算 L×H 面積，依座標由上而下、左至右排序輸出報告；可設定換行 Y 閾值。","usage":"執行指令 → 輸入 Y 換行差值 → 選取標註 → 指定文字起點 → 產生分類統計文字","level":7,"lt":"✅","ver":"20220716（檔案日期 2026-03-01）","author":"chengshunyi","video":"","fas":"fas/Dims-lay-typ-c.fas"},{"no":594,"file":"Dims2Field-d.lsp","cmd":"d2f-d","cat":"標註","desc":"將選取尺寸標註的量測值轉為 MText 欄位（Field）關聯物件，可放入表格儲存格，並以對話框設定單位、字高、字型與小數位。","usage":"執行 d2f-d → 於對話框設定單位/字高 → 選取尺寸標註 → 點選放置點或表格儲存格","level":8,"lt":"✅","ver":"20220716（檔案日期 2024-10-13）","author":"Lee Mac（原 Areas to Field）改寫 / chengshunyi","video":"","fas":"fas/Dims2Field-d.fas"},{"no":595,"file":"Dims2Field.lsp","cmd":"d2f","cat":"標註","desc":"將選取尺寸標註的量測值轉成 MText 欄位表達式，放在指定點或表格儲存格，量測值改變時可隨之更新，含比例單位判斷。","usage":"執行 d2f → 選取尺寸標註 → 點選放置點或表格儲存格","level":5,"lt":"✅","ver":"20220716（檔案日期 2024-10-13）","author":"Lee Mac（原 Areas to Field）改寫 / chengshunyi","video":"","fas":"fas/Dims2Field.fas"},{"no":596,"file":"DimStyleDemo.lsp","cmd":"DimStyleDemo","cat":"標註","desc":"逐一套用圖面內所有尺寸型式，並各畫一條 99 單位的線性標註，快速展示每個尺寸型式的外觀。","usage":"執行 DimStyleDemo → 自動依序切換尺寸型式並產生標註範例","level":2,"lt":"✅","ver":"2026-10-17（檔案日期）","author":"—","video":"","fas":"fas/DimStyleDemo.fas"},{"no":597,"file":"DimStyleSelector.lsp","cmd":"DimStyleSelector","cat":"標註","desc":"以對話框列出圖面所有尺寸型式並顯示數量，選取後記憶上次選擇，結果存於全域變數 DIMSTYLE_SELECTED。","usage":"執行 DimStyleSelector → 在清單選尺寸型式 → 按確定","level":6,"lt":"✅","ver":"2026-10-17（檔案日期）","author":"—","video":"https://youtu.be/sFK7Qalkwmw","fas":"fas/DimStyleSelector.fas"},{"no":598,"file":"DimSum45a.lsp","cmd":"DimSum45a","cat":"面積/數量統計","desc":"選取多個尺寸標註，將量測值四捨五入至小數二位後加總（排除角度標註），顯示總和。","usage":"執行 DimSum45a → 選取尺寸標註 → 命令列顯示 Total","level":3,"lt":"✅","ver":"20230828","author":"chengshunyi（改自 Alan J. Thompson）","video":"","fas":"fas/DimSum45a.fas"},{"no":599,"file":"DimSum45b.LSP","cmd":"DimSum45b","cat":"面積/數量統計","desc":"選取多個尺寸標註並加總量測值，結果以 MText 寫入圖面。","usage":"執行 DimSum45b → 選取尺寸標註 → 指定 MText 放置點","level":4,"lt":"✅","ver":"2023-08-28（檔案日期）","author":"Alan J. Thompson（網路程式）","video":"","fas":"fas/DimSum45b.fas"},{"no":600,"file":"DimUpd-sc.lsp","cmd":"DimUpd-sc","cat":"標註","desc":"批次更新圖面尺寸標註的線性比例係數（Linear Scale），用於外部參考／詳圖的比例調整。","usage":"執行 DimUpd-sc → 輸入線性比例係數 → 全圖尺寸標註自動更新","level":5,"lt":"✅","ver":"20230405","author":"chengshunyi（原 Lee Mac 2010）","video":"","fas":"fas/DimUpd-sc.fas"},{"no":601,"file":"DimWallCalc.lsp","cmd":"DimWallCalc","cat":"面積/數量統計","desc":"以對話框選擇牆體標註圖層，統計標註長度並計算牆面積，可選簡式或明細格式輸出文字。","usage":"執行 DimWallCalc → 於對話框選圖層（新增/刪除）並選簡式或明細 → 確定 → 指定輸出位置","level":6,"lt":"✅","ver":"v7.7（檔案日期 2026-04-25）","author":"ChengBar (MyCAD)","video":"","fas":"fas/DimWallCalc.fas"},{"no":602,"file":"DInfo.lsp","cmd":"DInfo","cat":"查詢","desc":"移動游標即時顯示物件資訊的動態資訊工具，可用 TAB 切換為 LAYISO 模式（點物件隔離其圖層）。","usage":"執行 DInfo → 移動游標於物件上檢視資訊 → +/- 調整拾取框，TAB 切換模式 → 點擊或 Enter 結束","level":7,"lt":"⚠️","ver":"Version 1.0 - 09-05-2009","author":"Lee Mac","video":"","fas":"fas/DInfo.fas"},{"no":603,"file":"DistNum.lsp","cmd":"DistNum","cat":"文字","desc":"兩點距離與間隔自動編號系統，沿兩點依間隔自動放置編號文字，並可批次修改文字字型與字高。","usage":"執行 DistNum → 於對話框設定間隔/字高/字型 → 指定兩點 → 自動產生編號","level":6,"lt":"✅","ver":"2026-07-14（檔案日期）","author":"Shun_Yi Studio (ChengBAR)","video":"","fas":"fas/DistNum.fas"},{"no":604,"file":"DIV-AREA.lsp","cmd":"DIV-AREA","cat":"面積/數量統計","desc":"土地分割工具：在封閉邊界內，依指定面積用迭代演算法找出分割線位置，將土地分出指定面積的一塊。","usage":"執行 DIV-AREA → 點選邊界內一點 → 輸入欲分割面積與分割方向 → 自動迭代畫出分割線並標註面積","level":7,"lt":"✅","ver":"2024-03-03（檔案日期）","author":"Yorgos Angelopoulos（原作）；Julio C. Jaramillo、Jose Hernandez 改寫","video":"","fas":"fas/DIV-AREA.fas"},{"no":605,"file":"div-xlin-dist-5.LSP","cmd":"div-xlin-dist-5","cat":"繪圖","desc":"在兩點或選取線段上等分並放置草稿點／線，兩端各留半個間距，可用於面盆、小便斗等衛生設備配置參考。","usage":"執行 div-xlin-dist-5 → 選取線段或指定兩點 → 輸入等分數 → 選 points/object → 產生等分點或參考線","level":5,"lt":"✅","ver":"20240406","author":"chengshunyi","video":"","fas":"fas/div-xlin-dist-5.fas"},{"no":606,"file":"Div2OBJECT.lsp","cmd":"Div2OBJECT","cat":"繪圖","desc":"選取線條（LINE／LWPOLYLINE）後，依等分數在最近一段上產生等分輔助線（LINE 或構造線），可偏移 1/2 對中，圖層為 0-REF。","usage":"執行 Div2OBJECT → 於對話框設定等分數與輔助線類型 → 確定 → 點選兩條線 → 產生等分輔助線","level":6,"lt":"✅","ver":"2026-10-17（檔案日期）","author":"ChengBar (MyCAD)","video":"https://youtu.be/Lk4WC6iHvDk","fas":"fas/Div2OBJECT.fas"},{"no":607,"file":"Div2OBJECTD.lsp","cmd":"Div2OBJECTD","cat":"繪圖","desc":"選取兩物件後，以固定等量距離（而非等分數）產生輔助線（LINE 或構造線），圖層為 0-REF。","usage":"執行 Div2OBJECTD → 於對話框輸入等量距離與輔助線類型 → 確定 → 點選兩條線 → 產生輔助線","level":6,"lt":"✅","ver":"2026-10-17（檔案日期）","author":"ChengBar (MyCAD)","video":"https://youtu.be/7sLuihwlINc","fas":"fas/Div2OBJECTD.fas"},{"no":608,"file":"Divarea.lsp","cmd":"DIVAREA","cat":"面積/數量統計","desc":"土地分割工具：點選封閉邊界內一點，依指定面積迭代求出分割線，從原地塊分割出指定面積。","usage":"執行 DIVAREA → 點選邊界內一點 → 輸入分割面積 → 自動畫出分割線","level":7,"lt":"✅","ver":"2024-03-02（檔案日期）","author":"Yorgos Angelopoulos（原作）；Julio C. Jaramillo 等改寫","video":"","fas":""},{"no":609,"file":"divcut_mescut.lsp","cmd":"divcut、mescut","cat":"修改","desc":"divcut 將選取物件依指定段數等分打斷；mescut 依指定段長度打斷物件，支援線段與聚合線。","usage":"執行 divcut（或 mescut）→ 選取物件 → 輸入段數（或段長）→ 物件被打斷","level":5,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/divcut_mescut.fas"},{"no":610,"file":"DivideByPointsWithGaps-0.lsp","cmd":"div-eq-gap、DivideByPointsWithGaps-0","cat":"繪圖","desc":"選取線段後依等分數與縫寬，在各等分點中間預留縫隙並產生分段線，可選兩端補線，對話框含幻燈片預覽。","usage":"執行 div-eq-gap → 於對話框輸入等分數、分割縫寬、2端補線 → 確定 → 選取線段 → 產生分段","level":6,"lt":"✅","ver":"2026-10-17（檔案日期）","author":"—","video":"https://youtu.be/-oxXnsuKXwQ","fas":"fas/DivideByPointsWithGaps-0.fas"},{"no":611,"file":"DivideByPointsWithGaps-2.lsp","cmd":"DivideByPointsWithGaps-2","cat":"繪圖","desc":"對話框輸入等分數與縫寬後，點選主線段與垂直線長度，在每段起迄處繪製垂直短線，形成含縫隙的分格。","usage":"執行 DivideByPointsWithGaps-2 → 於對話框輸入等分數與縫寬 → 點選起點與終點 → 指定垂直線長度 → 繪製","level":6,"lt":"✅","ver":"2026-10-17（檔案日期）","author":"—","video":"","fas":"fas/DivideByPointsWithGaps-2.fas"},{"no":612,"file":"DivideMeasurePlus.lsp","cmd":"DIV+、MEA+","cat":"繪圖","desc":"超級等分與等距分佈工具：沿聚合線等分(DIV+)或等距(MEA+)放置點、圖塊、垂直線或複製所選物件，含 DCL 與參數記憶。","usage":"執行 DIV+（或 MEA+）→ 於對話框選物件類型與數量/距離 → 確定 → 選取路徑 → 自動分佈放置","level":9,"lt":"✅","ver":"v2.2026.10-fix1","author":"ChengBar (鄭霸) / Shun_Yi Studio (MyCAD)","video":"","fas":"fas/DivideMeasurePlus.fas"},{"no":613,"file":"DivXLine(會當機).lsp","cmd":"DivXLine","cat":"繪圖","desc":"對話框設定等分數與方向（垂直於線段／水平／垂直），在線段等分點產生構造線。","usage":"執行 DivXLine → 於對話框輸入等分數與方向 → 確定 → 選取線段 → 產生構造線","level":6,"lt":"✅","ver":"2025-09-23（檔案日期）","author":"—","video":"","fas":"fas/DivXLine(會當機).fas"},{"no":614,"file":"donut_on_lines.LSP","cmd":"donut_on_lines","cat":"繪圖","desc":"在選取的線段／聚合線兩端，距端點指定距離處放置甜甜圈（Donut）標記，依線的圖層建立。","usage":"執行 donut_on_lines → 選取線條 → 兩端自動放置甜甜圈","level":3,"lt":"✅","ver":"20250614","author":"chengshunyi（含 Lee Mac Donut 函式）","video":"","fas":"fas/donut_on_lines.fas"},{"no":615,"file":"donut_on_plines.LSP","cmd":"donut_on_plines","cat":"繪圖","desc":"在選取聚合線／線段的起終端點沿線內縮 0.25 處放置小甜甜圈標記，並沿用物件圖層。","usage":"執行 donut_on_plines → 選取聚合線或線 → 兩端自動加甜甜圈","level":5,"lt":"✅","ver":"20220716（檔案日期 2025-06-15）","author":"chengshunyi","video":"https://youtu.be/ux51DPntML4","fas":"fas/donut_on_plines.fas"},{"no":616,"file":"DOOR-1.LSP","cmd":"door-1","cat":"圖塊/屬性","desc":"平面圖開門：指定門洞兩點與開門方向後，打斷牆線並插入單開門圖塊，輸入門寬與門編號。","usage":"執行 door-1 → 點選 A、B、C 三點 → 輸入門尺寸 → 輸入門編號","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/DOOR-1.fas"},{"no":617,"file":"DOOR-1S.LSP","cmd":"door-1s","cat":"圖塊/屬性","desc":"平面圖開門：指定門洞三點後打斷牆線並插入單開門（鏡射款）圖塊，輸入門寬與門編號。","usage":"執行 door-1s → 點選 A、B、C 三點 → 輸入門尺寸 → 輸入門編號","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/DOOR-1S.fas"},{"no":618,"file":"DOOR-2.LSP","cmd":"door-2","cat":"圖塊/屬性","desc":"平面圖開門：指定門洞三點後打斷牆線並插入雙開門（door-2）圖塊，輸入門寬與門編號。","usage":"執行 door-2 → 點選 A、B、C 三點 → 輸入門尺寸 → 輸入門編號","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/DOOR-2.fas"},{"no":619,"file":"DOOR-2S.LSP","cmd":"door-2s","cat":"圖塊/屬性","desc":"平面圖開門：雙開門鏡射款，三點定位後打斷牆線並插入 door-2 圖塊，輸入門寬與編號。","usage":"執行 door-2s → 點選 A、B、C 三點 → 輸入門尺寸 → 輸入門編號","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/DOOR-2S.fas"},{"no":620,"file":"DOOR-3.LSP","cmd":"door-3","cat":"圖塊/屬性","desc":"平面圖開門：三點定位後打斷牆線並插入 door-3 圖塊，輸入門寬與門編號。","usage":"執行 door-3 → 點選 A、B、C 三點 → 輸入門尺寸 → 輸入門編號","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/DOOR-3.fas"},{"no":621,"file":"DOOR-4S.LSP","cmd":"door-4s","cat":"圖塊/屬性","desc":"平面圖開窗：指定三點後打斷牆線，繪製窗線（含隱藏線型）與窗編號，輸入窗尺寸。","usage":"執行 door-4s → 點選 A、B、C 三點 → 輸入窗尺寸 → 輸入編號","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/DOOR-4S.fas"},{"no":622,"file":"door-d-p-i.lsp","cmd":"door-d-p-i","cat":"圖塊/屬性","desc":"單開門（雙扇款）參數化插入工具：對話框設定門寬、門框等參數與內外／左右翻轉，在牆線兩側自動打斷並插入動態圖塊，含單位判斷。","usage":"執行 door-d-p-i → 於對話框設定單位/門寬/門框/翻轉 → 確定 → 點選牆線與門位置 → 插入門圖塊","level":7,"lt":"✅","ver":"20230122","author":"chengshunyi","video":"","fas":"fas/door-d-p-i.fas"},{"no":623,"file":"door-d-p.lsp","cmd":"door-d-p","cat":"圖塊/屬性","desc":"雙扇門參數化插入工具：對話框設定門寬、門框、單位及翻轉，打斷牆線並插入動態圖塊，更新門扇尺寸欄位。","usage":"執行 door-d-p → 於對話框設定參數 → 確定 → 點選牆線與位置 → 插入門","level":7,"lt":"✅","ver":"20230122（檔案日期 2024-10-17）","author":"chengshunyi","video":"","fas":"fas/door-d-p.fas"},{"no":624,"file":"DOOR-Mline.LSP","cmd":"door-mline","cat":"圖塊/屬性","desc":"依 mline 雙線牆自動開門：對話框選門型（door-1~4S）與寬度，修剪牆線並插入對應圖塊。","usage":"執行 door-mline → 於對話框選門型與寬度 → 確定 → 點選牆位置 → 自動修剪並插入","level":6,"lt":"✅","ver":"2008.05.09（檔案日期 2022-07-16）","author":"—","video":"","fas":"fas/DOOR-Mline.fas"},{"no":625,"file":"DOOR-N.LSP","cmd":"door-n","cat":"圖塊/屬性","desc":"平面圖門窗繪製：對話框選門型（door-1~4S）與寬度、編號，依單位 mm／cm 預設門寬並打斷牆線插入。","usage":"執行 door-n → 於對話框選門型/寬度/編號 → 確定 → 點選 A、B、C 三點 → 插入門","level":6,"lt":"✅","ver":"84.3.11~94.03.13 民國年（檔案日期 2025-03-23）","author":"—","video":"","fas":"fas/DOOR-N.fas"},{"no":626,"file":"DOOR-N2.LSP","cmd":"door-n2","cat":"圖塊/屬性","desc":"door-n 改版：對話框新增單位（cm／mm）選單，選門型、寬度與編號後打斷牆線並插入門圖塊。","usage":"執行 door-n2 → 於對話框選單位/門型/寬度 → 確定 → 點選三點 → 插入門","level":7,"lt":"✅","ver":"84.3.11~94.03.13 民國年（檔案日期 2025-03-23）","author":"—","video":"","fas":"fas/DOOR-N2.fas"},{"no":627,"file":"door-r-p-i.lsp","cmd":"door-r-p-i","cat":"圖塊/屬性","desc":"單開門參數化插入（r 款）：對話框設定單位、門寬、門框與翻轉，打斷牆線並插入動態圖塊。","usage":"執行 door-r-p-i → 於對話框設定參數 → 確定 → 點選牆線與位置 → 插入門","level":7,"lt":"✅","ver":"20230122","author":"chengshunyi","video":"","fas":"fas/door-r-p-i.fas"},{"no":628,"file":"door-r-p.lsp","cmd":"door-r-p","cat":"圖塊/屬性","desc":"單開門參數化插入（r 款）：對話框設定門寬、門框與翻轉，打斷牆線並插入動態圖塊並同步門扇尺寸。","usage":"執行 door-r-p → 於對話框設定參數 → 確定 → 點選牆線與位置 → 插入門","level":7,"lt":"✅","ver":"20230122（檔案日期 2025-12-22）","author":"chengshunyi","video":"https://youtu.be/wE9d32ICG4Q","fas":"fas/door-r-p.fas"},{"no":629,"file":"door-s-p-i.lsp","cmd":"door-s-p-i","cat":"圖塊/屬性","desc":"單開門參數化插入（s 款，含內建圖塊）：對話框設定單位、門寬、門框與翻轉，打斷牆線並插入。","usage":"執行 door-s-p-i → 於對話框設定參數 → 確定 → 點選牆線與位置 → 插入門","level":7,"lt":"✅","ver":"20230122","author":"chengshunyi","video":"","fas":"fas/door-s-p-i.fas"},{"no":630,"file":"door-s-p.lsp","cmd":"door-s-p","cat":"圖塊/屬性","desc":"單開門參數化插入（s 款）：對話框設定單位、開口寬度與門框（預設 5cm），打斷牆線並插入動態圖塊。","usage":"執行 door-s-p → 於對話框設定參數 → 確定 → 點選牆線與位置 → 插入門","level":7,"lt":"✅","ver":"20230120（檔案日期 2024-10-17）","author":"chengshunyi","video":"https://youtu.be/yZ1YDR7MXXI","fas":"fas/door-s-p.fas"},{"no":631,"file":"door-type-cal.lsp","cmd":"door-type-cal","cat":"面積/數量統計","desc":"統計圖面圖塊屬性值個數（門窗號、type），依屬性分類計數並建立門號統計表格。","usage":"執行 door-type-cal → 選取圖塊 → 點選表格插入點 → 產生門窗號統計表","level":6,"lt":"✅","ver":"2024-11-28（檔案日期）","author":"—","video":"","fas":"fas/door-type-cal.fas"},{"no":632,"file":"dor-el.lsp","cmd":"dor-el-sd1、dor-el-sd2","cat":"繪圖","desc":"繪製門立面圖：單開／雙開、把手門鎖與推把手款，含門框、隱藏開門線與把手圓並建立專用圖層。","usage":"執行 dor-el-sd1（或 sd2）→ 點選門左下角 → 輸入門尺寸 → 自動繪製立面","level":7,"lt":"✅","ver":"20250504","author":"chengshunyi","video":"","fas":"fas/dor-el.fas"},{"no":633,"file":"DoubleOffset-beam.lsp","cmd":"DOff-b、DoubleOffset-beam","cat":"修改","desc":"將選取物件向兩側同時偏移指定距離，可控制是否刪除原物件與偏移後圖層，樑用版。","usage":"執行 DOff-b → 設定偏移距離/圖層/刪除原物件 → 選取物件 → 兩側產生偏移","level":5,"lt":"✅","ver":"2024-09-29（檔案日期）","author":"Lee Mac（改自 Double Offset）","video":"","fas":"fas/DoubleOffset-beam.fas"},{"no":634,"file":"DoubleOffset.lsp","cmd":"DOff、DoubleOffset","cat":"修改","desc":"將選取物件向兩側同時偏移指定距離，可設定是否刪除原物件及偏移圖層。","usage":"執行 DOff → 設定偏移距離/圖層/刪除原物件 → 選取物件 → 兩側產生偏移","level":5,"lt":"✅","ver":"2024-04-26（檔案日期）","author":"Lee Mac","video":"","fas":"fas/DoubleOffset.fas"},{"no":635,"file":"DP.lsp","cmd":"DPI、DPO","cat":"標註","desc":"對選取聚合線的每一線段做對齊標註，DPI 標於內側、DPO 標於外側，可指定標註與聚合線距離。","usage":"執行 DPI（或 DPO）→ 選取聚合線 → 自動標註各段長度","level":6,"lt":"✅","ver":"2022-07-16（檔案日期）","author":"—（原 DimPolyAssoc）","video":"https://youtu.be/tDHAvs31GqU","fas":"fas/DP.fas"},{"no":636,"file":"DPL-y.LSP","cmd":"DPL-y","cat":"標註","desc":"對選取聚合線自動標註各段尺寸，可選左／右／下側，並自動計算尺寸線間隔。","usage":"執行 DPL-y → 選取聚合線 → 選標註側 → 自動標註各線段","level":6,"lt":"✅","ver":"CADALYST 11/08 Tip 3026（檔案日期 2023-06-22）","author":"Terry Miller","video":"","fas":"fas/DPL-y.fas"},{"no":637,"file":"DPL.LSP","cmd":"DPL","cat":"標註","desc":"對選取聚合線形狀自動標註各邊尺寸，可選標註於左／右／下側，尺寸線間距依 DIMSCALE 計算。","usage":"執行 DPL → 選取聚合線 → 選標註側 → 自動標註各邊","level":6,"lt":"✅","ver":"Created 5-20-08（檔案日期 2024-06-01）","author":"Terry Miller (autolisp-exchange.com)","video":"","fas":"fas/DPL.fas"},{"no":638,"file":"DR-solid-block.lsp","cmd":"DR-solid-block","cat":"圖面管理","desc":"調整顯示順序：將 Solid/圖塊移到最下層、填充（Hatch）移到最上層，套用 acad_sortents 順序表。","usage":"執行 DR-solid-block → 圖面中圖塊與填充自動重排顯示順序","level":5,"lt":"✅","ver":"20220906","author":"chengshunyi（含 Lee Mac Move to Top）","video":"","fas":"fas/DR-solid-block.fas"},{"no":639,"file":"draw-ang45-pline.lsp","cmd":"draw-ang45-pline","cat":"繪圖","desc":"對話框輸入折線長度，繪製 45 度折線，確定後可連續繪製，Enter／Esc 結束。","usage":"執行 draw-ang45-pline → 於對話框輸入折線長度 → 確定 → 連續指定點繪製 → Enter 結束","level":6,"lt":"✅","ver":"v2.6 (2026-10-24)","author":"ChengBar (MyCAD)","video":"https://youtu.be/aa2o--ot6Vs","fas":"fas/draw-ang45-pline.fas"},{"no":640,"file":"draw-beam-sec-ss.lsp","cmd":"draw-beam-sec-ss","cat":"剖面/結構","desc":"對話框輸入樑寬高、樓板厚、分段等參數，繪製鋼樑（SS）斷面圖塊並放置於指定位置。","usage":"執行 draw-beam-sec-ss → 於對話框設定樑寬高/板厚 → 確定 → 指定插入點 → 產生斷面","level":7,"lt":"✅","ver":"20251009","author":"chengshunyi","video":"","fas":"fas/draw-beam-sec-ss.fas"},{"no":641,"file":"draw-beam-sec.lsp","cmd":"draw-beam-sec","cat":"剖面/結構","desc":"對話框輸入樑寬高、板厚及分段參數，繪製 RC 樑斷面並插入圖塊，圖塊置於下層。","usage":"執行 draw-beam-sec → 於對話框設定樑參數 → 確定 → 指定插入點 → 產生斷面","level":7,"lt":"✅","ver":"20251008","author":"chengshunyi","video":"","fas":"fas/draw-beam-sec.fas"},{"no":642,"file":"draw-cg-60.lsp","cmd":"draw-cg-60","cat":"繪圖","desc":"選取天花聚合線，在其內填充 60 格線（天花板格線）圖樣，用於輕鋼架天花格線表示。","usage":"執行 draw-cg-60 → 選取天花 LWPOLYLINE → 自動填充 60 格線","level":4,"lt":"✅","ver":"20231221","author":"chengshunyi","video":"https://youtu.be/89FYfpJTE6U","fas":"fas/draw-cg-60.fas"},{"no":643,"file":"draw-cg-61.lsp","cmd":"draw-cg-61","cat":"繪圖","desc":"選取天花聚合線，在其內填充 61 格線（天花板格線）圖樣。","usage":"執行 draw-cg-61 → 選取天花 LWPOLYLINE → 自動填充 61 格線","level":4,"lt":"✅","ver":"20231221","author":"chengshunyi","video":"https://youtu.be/YwUHXSZGbxI","fas":"fas/draw-cg-61.fas"},{"no":644,"file":"draw-cg.lsp","cmd":"draw-cg","cat":"繪圖","desc":"選取天花聚合線，輸入格線尺寸後填充天花格線圖樣。","usage":"執行 draw-cg → 輸入格線尺寸 → 選取天花 LWPOLYLINE → 自動填充格線","level":4,"lt":"✅","ver":"20231221","author":"chengshunyi","video":"https://youtu.be/CI4coqkRoHg","fas":"fas/draw-cg.fas"},{"no":645,"file":"draw-elastic.LSP","cmd":"draw-elastic","cat":"繪圖","desc":"對話框設定半徑、寬度、高度與各段厚度，繪製彈性材料（如橡膠墊）斷面並複製。","usage":"執行 draw-elastic → 於對話框設定參數 → 確定 → 點選基準點、右端、左端 → 繪製","level":6,"lt":"✅","ver":"20240210","author":"chengshunyi","video":"https://youtu.be/0TYRqg48w0s","fas":"fas/draw-elastic.fas"},{"no":646,"file":"draw-grid-xy-coord.lsp","cmd":"draw-grid-xy-coord","cat":"繪圖","desc":"依北／東座標繪製座標尺規（座標網格），標註座標值，可用於圖紙座標格網。","usage":"執行 draw-grid-xy-coord → 輸入起始座標與間距 → 指定範圍 → 自動繪製座標網格與標註","level":7,"lt":"✅","ver":"20240318","author":"Rodrigo Brigido（原 RULER）/ chengshunyi","video":"","fas":"fas/draw-grid-xy-coord.fas"},{"no":647,"file":"draw-grid-xy.LSP","cmd":"draw-grid-xy","cat":"繪圖","desc":"輸入方格總長、總高與 X／Y 間距，以直線與陣列繪製方格網。","usage":"執行 draw-grid-xy → 輸入總長/總高/X、Y 間距 → 指定基點 → 產生方格","level":3,"lt":"✅","ver":"20240318","author":"VVA（原作）/ chengshunyi","video":"","fas":"fas/draw-grid-xy.fas"},{"no":648,"file":"Draw-Grid.lsp","cmd":"dgrid、dgridd","cat":"繪圖","desc":"MyCAD 動態繪製網格：對話框設定行列數與間距，dgrid 選兩點標準繪製，dgridd 以 grread 即時預覽動態繪製。","usage":"執行 dgrid（或 dgridd）→ 於對話框設定行列數 → 確定 → 指定兩點（動態預覽）→ 產生網格","level":8,"lt":"⚠️","ver":"2026（檔案日期 2026-09-19）","author":"ChengBar (MyCAD)","video":"https://youtu.be/SB4Nrsnu_JA","fas":"fas/Draw-Grid.fas"},{"no":649,"file":"draw-line-Layers.lsp","cmd":"draw-line-Layers","cat":"圖層","desc":"列出圖面所有圖層，於指定位置為每個圖層畫一條線並寫上圖層名稱與說明，製作圖層圖例。","usage":"執行 draw-line-Layers → 指定基點 → 自動列出各圖層線與說明文字","level":5,"lt":"✅","ver":"20241114","author":"chengshunyi","video":"","fas":"fas/draw-line-Layers.fas"},{"no":650,"file":"Draw-RCColumn.lsp","cmd":"DRCC、Draw-RCColumn","cat":"剖面/結構","desc":"對話框設定 RC 柱尺寸與模式，自動建立柱圖塊（外框、中心線、斜線填充、屬性文字 WxH），含圖層建立。","usage":"執行 DRCC → 於對話框設定柱寬高/模式 → 確定 → 指定插入點 → 產生 RC 柱圖塊","level":8,"lt":"✅","ver":"2026-10-17（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/Draw-RCColumn.fas"},{"no":651,"file":"draw-sfoundation-ui.LSP","cmd":"draw-sfoundation-ui","cat":"剖面/結構","desc":"對話框輸入基礎寬 W 與高 H，繪製矩形基礎與交叉斜線，並在中心寫上尺寸文字 WxH。","usage":"執行 draw-sfoundation-ui → 於對話框輸入 W、H → 確定 → 點選起點 → 繪製基礎","level":6,"lt":"✅","ver":"2025-10-29（檔案日期）","author":"—","video":"","fas":"fas/draw-sfoundation-ui.fas"},{"no":652,"file":"Draw-SRCColumn.lsp","cmd":"DSRCC、Draw-SRCColumn","cat":"剖面/結構","desc":"對話框設定 SRC（鋼骨鋼筋混凝土）柱尺寸與內部鋼骨，自動建立柱斷面圖塊與屬性文字。","usage":"執行 DSRCC → 於對話框設定柱尺寸 → 確定 → 指定插入點 → 產生 SRC 柱圖塊","level":8,"lt":"✅","ver":"2026-10-17（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/Draw-SRCColumn.fas"},{"no":653,"file":"Draw-SSColumn.lsp","cmd":"DSSC、Draw-SSColumn","cat":"剖面/結構","desc":"繪製 SS（鋼骨）柱斷面圖塊，含外框與內偏矩形，支援參數化偏移與鋼骨填充比例，並記憶參數。","usage":"執行 DSSC → 於對話框設定柱尺寸/偏移/填充比例 → 確定 → 指定插入點 → 產生 SS 柱圖塊","level":8,"lt":"✅","ver":"2026-01-19（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/Draw-SSColumn.fas"},{"no":654,"file":"draw-table.lsp","cmd":"draw-table-","cat":"圖面管理","desc":"以字串列表建立 AutoCAD 表格物件（含標題與表頭），示範 list-to-table 函式，可畫各種表格。","usage":"執行 draw-table- → 點選插入點 → 產生範例表格","level":5,"lt":"✅","ver":"2024-10-09（檔案日期）","author":"Jonathan Handojo（JH:list-to-table）","video":"","fas":"fas/draw-table.fas"},{"no":655,"file":"Draw-Truss-trim-D.lsp","cmd":"Draw-Truss-trim-D","cat":"剖面/結構","desc":"桁架立面自動繪圖：對話框輸入尺寸，繪製中心線、弦桿、大小立柱與斜桿，以偏移端點交點過濾精確修剪。","usage":"執行 Draw-Truss-trim-D → 於對話框設定桁架尺寸與分段 → 確定 → 指定基點 → 自動繪製桁架","level":9,"lt":"✅","ver":"2026-03-05（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/Draw-Truss-trim-D.fas"},{"no":656,"file":"Draw-Truss-Trim.LSP","cmd":"Draw-Truss-trim","cat":"剖面/結構","desc":"桁架立面自動繪圖：偏移端點交點過濾版，繪製中心線、弦桿、立柱與精確修剪的斜桿。","usage":"執行 Draw-Truss-trim → 於對話框設定尺寸 → 確定 → 指定基點 → 自動繪製","level":8,"lt":"✅","ver":"2026-03-05（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/Draw-Truss-Trim.fas"},{"no":657,"file":"Draw-Truss.lsp","cmd":"Draw-Truss","cat":"剖面/結構","desc":"桁架立面雙線繪圖：依對話框尺寸繪製中心線、上下弦、大立柱、斜桿與小立柱並自動裁切。","usage":"執行 Draw-Truss → 於對話框輸入左右高度等參數 → 確定 → 指定基點 → 自動繪製","level":8,"lt":"✅","ver":"2026-03-04（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/Draw-Truss.fas"},{"no":658,"file":"draw-xline.LSP","cmd":"draw-xline","cat":"繪圖","desc":"於指定點繪製水平、垂直或指定角度的構造線（草稿線），圖層為輔助圖層。","usage":"執行 draw-xline → 選 Horiz/Vert/Angled → 指定插入點（角度則再指定旋轉點）→ 產生構造線","level":4,"lt":"✅","ver":"20240322","author":"chengshunyi","video":"","fas":"fas/draw-xline.fas"},{"no":659,"file":"DRAW_BEAM_FROM_LIST.LSP","cmd":"TEXT_TO_LIST、DRAW_BEAM_FROM_LIST","cat":"剖面/結構","desc":"選取如 B1-50X80 格式的樑尺寸文字，解析後存入全域變數，再依清單繪製樑斷面聚合線。","usage":"執行 TEXT_TO_LIST → 選取樑尺寸文字 → 資料存入全域變數 → 執行 DRAW_BEAM_FROM_LIST → 指定位置繪製","level":7,"lt":"✅","ver":"20251128","author":"chengshunyi","video":"","fas":"fas/DRAW_BEAM_FROM_LIST.fas"},{"no":660,"file":"DRAW_BEAM_FROM_TXT.LSP","cmd":"TEXT_TO_TXT、DRAW_BEAM_FROM_TXT","cat":"剖面/結構","desc":"選取樑尺寸文字匯出至 TEMP 資料檔，再從檔案讀取，依關鍵字插入樑斷面動態圖塊並寫屬性。","usage":"執行 TEXT_TO_TXT → 選取樑尺寸文字 → 寫入 PROJECT_DATA.TXT → 執行 DRAW_BEAM_FROM_TXT → 指定位置插入","level":8,"lt":"✅","ver":"2025-11-29（檔案日期）","author":"chengshunyi","video":"","fas":"fas/DRAW_BEAM_FROM_TXT.fas"},{"no":661,"file":"DRAW_BEAM_FROM_TXT_A.LSP","cmd":"TEXT_TO_TXT、DRAW_BEAM_FROM_TXT_A","cat":"剖面/結構","desc":"提取圖面樑尺寸文字存成資料庫檔，再依關鍵字多選文字、依 X 座標排序後統一高度插入動態樑圖塊。","usage":"執行 TEXT_TO_TXT → 選取樑尺寸文字 → 執行 DRAW_BEAM_FROM_TXT_A → 多選文字並指定基準 Y → 自動插入圖塊","level":8,"lt":"✅","ver":"2026-01-24（檔案日期）","author":"chengshunyi","video":"","fas":"fas/DRAW_BEAM_FROM_TXT_A.fas"},{"no":662,"file":"draw_cb.LSP","cmd":"draw_cb","cat":"繪圖","desc":"對話框選擇型號並讀取型號資料檔，繪製對應規格的圖形（線、聚合線、陣列、標註），並記憶使用者參數。","usage":"執行 draw_cb → 於對話框選型號/設定參數 → 確定 → 指定位置 → 自動繪圖","level":7,"lt":"✅","ver":"2025-10-30（檔案日期）","author":"—","video":"","fas":"fas/draw_cb.fas"},{"no":663,"file":"draw_num.lsp","cmd":"draw_num、number-0、number-1、number-2、number-3、number-4、number-5","cat":"文字","desc":"圖紙編號標示繪製：對話框選編號圖形類型與格式，依比例與單位在指定點繪製編號符號（含 mtext），可自動編碼。","usage":"執行 draw_num → 於對話框選類別/前置碼/字高 → 確定 → 指定左下角基準點 → 繪製編號","level":8,"lt":"✅","ver":"2024-10-18（檔案日期）","author":"—","video":"","fas":"fas/draw_num.fas"},{"no":664,"file":"DrawBeamFromTextX.LSP","cmd":"DrawBeamFromTextX","cat":"剖面/結構","desc":"選取註解尺寸文字，依單位與樓板厚度參數插入動態樑斷面圖塊並繪製 U 型線與水平總長線。","usage":"執行 DrawBeamFromTextX → 於對話框設定單位/板厚 → 確定 → 選取文字 → 自動插入圖塊","level":8,"lt":"✅","ver":"2026-01-24（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/DrawBeamFromTextX.fas"},{"no":665,"file":"DrawBigFontChars.lsp","cmd":"DrawBigFontChars","cat":"文字","desc":"讀取 BigFont SHP 檔案，將各編碼對應字元轉換為文字繪出並自動換行排版，用於檢視大字體字集。","usage":"執行 DrawBigFontChars → 選擇 BigFont SHP 檔案 → 自動繪製編碼標籤與字元","level":7,"lt":"✅","ver":"2026-04-06（檔案日期）","author":"—","video":"","fas":"fas/DrawBigFontChars.fas"},{"no":666,"file":"DrawCL.lsp","cmd":"DrawCL","cat":"繪圖","desc":"MyCAD 中心線產生器：對話框設定模式與線型並動態預覽幻燈片，於選取物件繪製中心線。","usage":"執行 DrawCL → 於對話框選模式與線型 → 確定 → 選取物件／指定點 → 產生中心線","level":8,"lt":"✅","ver":"2026-08-30（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/DrawCL.fas"},{"no":667,"file":"DrawGrid.lsp","cmd":"dgrid、dgridd、layermake","cat":"繪圖","desc":"依輸入的行數與列數在指定基點與對角點繪製網格，dgridd 為動態版，layermake 建立圖層。","usage":"執行 dgrid → 輸入行數、列數 → 指定基點與對角點 → 產生網格","level":6,"lt":"✅","ver":"2024-03-16（檔案日期）","author":"Lee Mac","video":"https://youtu.be/SB4Nrsnu_JA","fas":"fas/DrawGrid.fas"},{"no":668,"file":"drawhatch.lsp","cmd":"DrawHatch、SaveHatch","cat":"繪圖","desc":"HatchMaker：在 1x1 方格內以線或點繪製圖樣單元，再輸出成自訂填充圖樣 .pat 檔。","usage":"執行 DrawHatch → 在 1x1 方框內繪製線/點 → 執行 SaveHatch → 輸出 PAT 檔並以記事本開啟","level":7,"lt":"✅","ver":"CADALYST 10/05 Tip 2065（檔案日期 2024-03-07）","author":"Larry Schiele (TMI Systems)","video":"","fas":"fas/drawhatch.fas"},{"no":669,"file":"DrawLinetypes.lsp","cmd":"DrawLinetypes","cat":"繪圖","desc":"MyCAD 線型繪製工具：對話框選擇線型與參數，繪製線型示範線，含上方幻燈片與底部網址連結。","usage":"執行 DrawLinetypes → 於對話框選線型/設定參數 → 確定 → 指定點繪製","level":6,"lt":"⚠️","ver":"Copyright 2026（檔案日期 2026-10-28）","author":"ChengBar (MyCAD)","video":"","fas":"fas/DrawLinetypes.fas"},{"no":670,"file":"DrawMTextRowBox.lsp","cmd":"DrawMTextRowBox","cat":"文字","desc":"針對 MText 指定行，以行間距為高、左右外擴半個字高，繪製聚合線外框並上移 0.25 字高。","usage":"執行 DrawMTextRowBox → 選取 MText → 輸入行號（預設最後一行）→ 產生該行外框","level":4,"lt":"✅","ver":"2026-04-06（檔案日期）","author":"—","video":"","fas":"fas/DrawMTextRowBox.fas"},{"no":671,"file":"DrawOrder.lsp","cmd":"hatchbottom、hatchtop","cat":"圖面管理","desc":"將圖面所有填充（HATCH／SOLID）移到最下層（hatchbottom）或最上層（hatchtop）。","usage":"執行 hatchbottom（或 hatchtop）→ 自動調整全圖填充顯示順序","level":6,"lt":"✅","ver":"2023-08-18（檔案日期）","author":"Lee Mac（Move to Top 函式）/ chengshunyi","video":"","fas":"fas/DrawOrder.fas"},{"no":672,"file":"DrawRCBeamU.lsp","cmd":"DrawRCBeamU","cat":"剖面/結構","desc":"選取多個樑圖塊，依其外框於圖層 RCW 繪製 U 形聚合線（右側下降指定單位），表示 RC 樑斷面。","usage":"執行 DrawRCBeamU → 輸入下降單位 → 窗選圖塊 → 自動於 RCW 層畫 U 形線","level":6,"lt":"✅","ver":"20260303","author":"chengshunyi","video":"","fas":"fas/DrawRCBeamU.fas"},{"no":673,"file":"DrawSCP-S.LSP","cmd":"DrawSCP-S","cat":"剖面/結構","desc":"鋼構接合板自動繪圖：對話框輸入偏置距離，比較兩線夾角後自動繪製接合板與內部輔助線，支援選取圖塊內部線條。","usage":"執行 DrawSCP-S → 於對話框輸入偏置距離 → 確定 → 選取線段 → 自動繪製接合板","level":8,"lt":"✅","ver":"2026-01-25（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/DrawSCP-S.fas"},{"no":674,"file":"DrawSCP-UI-B.LSP","cmd":"DrawSCP-UI-B","cat":"剖面/結構","desc":"鋼構接合板自動繪圖：對話框輸入偏置距離，用 nentselp 支援選取圖塊內部線條，比較夾角後繪製接合板。","usage":"執行 DrawSCP-UI-B → 於對話框輸入偏置距離 → 確定 → 選取線段（可進圖塊）→ 繪製","level":8,"lt":"✅","ver":"2026-01-25（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/DrawSCP-UI-B.fas"},{"no":675,"file":"DrawSCP-UI.LSP","cmd":"DrawSCP-UI","cat":"剖面/結構","desc":"鋼構接合板自動繪圖：對話框輸入偏置距離並以 TXT 記憶，比較夾角後自動繪製接合板。","usage":"執行 DrawSCP-UI → 於對話框輸入偏置距離 → 確定 → 選取線段 → 繪製接合板","level":7,"lt":"✅","ver":"2026-01-25（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/DrawSCP-UI.fas"},{"no":676,"file":"DrawSCP.LSP","cmd":"DrawSCP","cat":"剖面/結構","desc":"鋼構接合板自動繪圖正式版：DCL 輸入偏置距離，自動繪製接合板與內部輔助線，支援一般線與圖塊內線，全象限自適應。","usage":"執行 DrawSCP → 於對話框輸入偏置距離 → 確定 → 選取線段或圖塊 → 自動繪製接合板","level":9,"lt":"✅","ver":"2026-06-24（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/DrawSCP.fas"},{"no":677,"file":"DrawShpChars.lsp","cmd":"DrawShpChars","cat":"文字","desc":"讀取 SHP 檔，依字元編碼將 Unicode 字型各字形繪出，上方標註編碼，自動排版。","usage":"執行 DrawShpChars → 選擇 simplex-unicode8.SHP → 自動繪製編碼與字元","level":5,"lt":"✅","ver":"2026-04-06（檔案日期）","author":"—","video":"","fas":"fas/DrawShpChars.fas"},{"no":678,"file":"DrawSiteProfile.LSP","cmd":"DrawSiteProfile","cat":"繪圖","desc":"MyCAD 縱斷面繪製：多選中心線，依垂直比例繪製高程斷面與里程標註，可選擇生成 3D 實體牆。","usage":"執行 DrawSiteProfile → 於對話框設定比例/間距/偏移 → 確定 → 選取中心線（多選）→ 繪製斷面","level":9,"lt":"⚠️","ver":"2026-01-28（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/DrawSiteProfile.fas"},{"no":679,"file":"DrawSiteSecProfile.LSP","cmd":"DrawSiteSecProfile","cat":"繪圖","desc":"地形剖面與 3D 實體工具：依距離與高程倍率收集點繪製 2D 剖面聚合線與標註，並可選擇產生 3D 方塊實體。","usage":"執行 DSSP → 於對話框設定參數 → 確定 → 逐點選取（距離/高程）→ 繪製剖面與標註","level":9,"lt":"⚠️","ver":"2026-01-28（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/DrawSiteSecProfile.fas"},{"no":680,"file":"DrawSSBeamFromTextX.LSP","cmd":"DrawSSBeamFromTextX","cat":"剖面/結構","desc":"選取如 H600x300 的鋼樑文字，依單位、字高與偏移參數自動插入動態鋼樑斷面圖塊。","usage":"執行 DrawSSBeamFromTextX → 於對話框設定單位/字高/偏移 → 確定 → 選取文字 → 插入圖塊","level":8,"lt":"✅","ver":"2026-01-24（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/DrawSSBeamFromTextX.fas"},{"no":681,"file":"DRCC-2.LSP","cmd":"DRCC-2","cat":"剖面/結構","desc":"DRCC 矩形柱繪製新版：對話框與 INI 記憶，建立柱圖塊並以屬性 COLNUM／COLSIZE 寫入柱編號與尺寸。","usage":"執行 DRCC-2 → 於對話框設定柱尺寸/編號 → 確定 → 指定插入點 → 插入含屬性的柱圖塊","level":8,"lt":"✅","ver":"2026-08-29（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/DRCC-2.fas"},{"no":682,"file":"DSP.lsp","cmd":"DSP","cat":"繪圖","desc":"MyCAD 縱斷面繪製系統：點選含高程屬性的圖塊，讀取屬性值繪製剖面，含幻燈片預覽對話框與授權驗證。","usage":"執行 DSP → 於對話框設定參數 → 確定 → 點選圖塊高程屬性文字 → 自動繪製縱斷面","level":9,"lt":"⚠️","ver":"2026-09-22（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/DSP.fas"},{"no":683,"file":"DSU.LSP","cmd":"DSU","cat":"標註","desc":"尺寸等比縮放：輸入整體比例係數，對全圖所有尺寸標註改寫其比例（dimscale）。","usage":"執行 DSU → 輸入尺寸整體比例係數 → 全圖尺寸自動更新","level":4,"lt":"✅","ver":"20211013","author":"chengshunyi","video":"","fas":"fas/DSU.fas"},{"no":684,"file":"DSU_all.LSP","cmd":"DSU_all","cat":"標註","desc":"尺寸通用縮放：輸入整體比例係數，對選取的尺寸標註改寫其整體比例。","usage":"執行 DSU_all → 輸入比例係數 → 選取尺寸標註 → 更新比例","level":4,"lt":"✅","ver":"20211013","author":"chengshunyi","video":"","fas":"fas/DSU_all.fas"},{"no":685,"file":"dtr.LSP","cmd":"dtr","cat":"3D","desc":"Delaunay 三角剖分：選取多個點，去重後計算並產生三角網（含凸包三角形），並顯示計算時間。","usage":"執行 dtr → 選取點物件 → 自動產生 Delaunay 三角網","level":8,"lt":"✅","ver":"2023-06-05（檔案日期）","author":"Marko Ribar","video":"","fas":"fas/dtr.fas"},{"no":686,"file":"DumpObject.lsp","cmd":"dump、dumpn","cat":"查詢","desc":"列出選取物件的 ActiveX 屬性與方法，dumpn 針對巢狀物件。","usage":"執行 dump → 選取物件 → 命令列列出 ActiveX 屬性與方法","level":3,"lt":"✅","ver":"2022-07-16（檔案日期）","author":"Lee Mac","video":"","fas":"fas/DumpObject.fas"},{"no":687,"file":"DWG-DAT1.LSP","cmd":"dwg-dat1","cat":"圖面管理","desc":"取得目前日期與圖檔名稱，組成字串寫入圖框的屬性（DWG_NAME）。","usage":"執行 dwg-dat1 → 自動取得日期與圖名並寫入圖框屬性","level":4,"lt":"✅","ver":"2022-07-16（檔案日期）","author":"—","video":"","fas":"fas/DWG-DAT1.fas"},{"no":688,"file":"DWG2SLD.lsp","cmd":"DWG2SLD","cat":"轉檔/匯出入","desc":"批次將資料夾內的 DWG 檔開啟並輸出成 SLD 幻燈片檔。","usage":"執行 DWG2SLD → 選擇輸入資料夾 → 選擇輸出資料夾 → 逐一開檔製作 SLD","level":6,"lt":"❌","ver":"20241114","author":"chengshunyi","video":"","fas":"fas/DWG2SLD.fas"},{"no":689,"file":"dwglayoff.LSP","cmd":"dwglayoff","cat":"圖層","desc":"選擇資料夾與圖層名稱，批次關閉資料夾內 DWG 檔的指定圖層（測試程式）。","usage":"輸入 TestPath → 於對話框選資料夾 → 輸入圖層名稱 → 確定","level":6,"lt":"⚠️","ver":"2025-01-21（檔案日期）","author":"Lee Mac（資料夾選取函式）","video":"","fas":"fas/dwglayoff.fas"},{"no":690,"file":"DynamicTextAlign.lsp","cmd":"TxAlign","cat":"文字","desc":"動態旋轉對齊文字：選取文字後，移動游標預覽並將文字旋轉到任意角度，可輸入角度或重設。","usage":"執行 TxAlign → 選取文字 → 移動游標動態旋轉 → 點擊或輸入角度確認","level":8,"lt":"⚠️","ver":"2022-04-24（檔案日期）","author":"Lee Mac","video":"","fas":"fas/DynamicTextAlign.fas"},{"no":691,"file":"DynAttWidth.lsp","cmd":"attw","cat":"圖塊/屬性","desc":"動態調整所選屬性的寬度比例：以游標拖曳或鍵盤增減，即時預覽屬性文字寬度。","usage":"執行 attw → 選取屬性 → 移動游標或按鍵調整寬度 → 點擊確認","level":8,"lt":"✅","ver":"20220716（檔案日期 2022-07-16）","author":"Lee Mac","video":"","fas":"fas/DynAttWidth.fas"},{"no":692,"file":"E-WIN.LSP","cmd":"e-win","cat":"繪圖","desc":"繪製窗立面圖：對話框輸入窗寬與窗高，點選基點後以聚合線與線繪出窗框（win-o、win-i 圖層）。","usage":"執行 e-win → 於對話框輸入窗寬/窗高 → 確定 → 點選基點 → 繪製窗立面","level":5,"lt":"✅","ver":"84.7.4~84.7.13 民國年（檔案日期 2022-07-16）","author":"—","video":"","fas":"fas/E-WIN.fas"},{"no":693,"file":"E-WIN1.LSP","cmd":"e-win1","cat":"繪圖","desc":"繪製窗立面圖款式 1：對話框輸入尺寸（依 mm／cm 預設窗寬），點選基點繪製窗框與窗線。","usage":"執行 e-win1 → 於對話框輸入尺寸 → 確定 → 點選基點 → 繪製","level":5,"lt":"✅","ver":"84.9.21（檔案日期 2025-01-11）；20250111 修改","author":"—","video":"","fas":"fas/E-WIN1.fas"},{"no":694,"file":"E-WIN2.LSP","cmd":"e-win2","cat":"繪圖","desc":"繪製窗立面圖款式 2：對話框輸入尺寸，依單位預設窗寬，點選基點繪製窗框與窗線。","usage":"執行 e-win2 → 於對話框輸入尺寸 → 確定 → 點選基點 → 繪製","level":5,"lt":"✅","ver":"84.9.21（檔案日期 2025-01-11）","author":"—","video":"","fas":"fas/E-WIN2.fas"},{"no":695,"file":"E-WIN3.LSP","cmd":"e-win3","cat":"繪圖","desc":"繪製窗立面圖款式 3：對話框輸入尺寸，依單位預設窗寬，點選基點繪製窗框與窗線。","usage":"執行 e-win3 → 於對話框輸入尺寸 → 確定 → 點選基點 → 繪製","level":5,"lt":"✅","ver":"84.9.21（檔案日期 2025-01-11）","author":"—","video":"","fas":"fas/E-WIN3.fas"},{"no":696,"file":"E2PL.lsp","cmd":"E2PL","cat":"修改","desc":"將樣條型橢圓（Spline Ellipse）轉換為聚合線。","usage":"執行 E2PL → 選取橢圓 → 轉換為聚合線","level":3,"lt":"✅","ver":"20250430","author":"—","video":"","fas":"fas/E2PL.fas"},{"no":697,"file":"ECO.lsp","cmd":"ECO","cat":"繪圖","desc":"選取等高線／範圍物件，於視埠或視圖範圍判斷後，以填充與屬性文字製作設備基座等標示範圍。","usage":"執行 ECO → 選取輪廓聚合線 → 自動填充並標示說明","level":7,"lt":"✅","ver":"20220716（檔案日期 2024-05-05）","author":"—","video":"","fas":"fas/ECO.fas"},{"no":698,"file":"Edit_bloc_3_eng.lsp","cmd":"edit_bloc","cat":"圖塊/屬性","desc":"批次修改圖塊內物件的顏色（ByLayer／ByBlock）與其他特性，可選擇圖塊清單，含對話框設定。","usage":"執行 edit_bloc → 於對話框選圖塊與顏色設定 → 確定 → 圖塊內物件特性更新","level":8,"lt":"✅","ver":"version 3.0 - 29/03/07；20240316","author":"Gilles Chanteau（gile）/ chengshunyi","video":"","fas":"fas/Edit_bloc_3_eng.fas"},{"no":699,"file":"ELEVATOR.LSP","cmd":"one-set、two-set","cat":"繪圖","desc":"繪製電梯平面：對話框選電梯規格，點選基點（雙座另選第二點）繪出電梯井與設備輪廓。","usage":"執行 one-set（或 two-set）→ 於對話框選電梯規格 → 確定 → 點選基點（第 2 點）→ 繪製","level":6,"lt":"✅","ver":"84.7.4~94.03.13 民國年；20210921（檔案日期 2024-10-17）","author":"—","video":"","fas":"fas/ELEVATOR.fas"},{"no":700,"file":"ElevProfile.LSP","cmd":"ElevProfile","cat":"剖面/結構","desc":"電梯升降道剖面圖繪製：對話框輸入各層樓名稱與樓高，繪製升降道剖面並標註樓層名稱與高度尺寸。","usage":"執行 ElevProfile → 於對話框輸入各層樓名/樓高 → 確定 → 指定起點 → 自動繪製剖面與標註","level":7,"lt":"✅","ver":"Version 1.0（2025-08-08）","author":"ShunYi","video":"","fas":"fas/ElevProfile.fas"},{"no":701,"file":"en.LSP","cmd":"en","cat":"查詢","desc":"選取物件後，於命令列列出其 SEQEND（子項目）資訊，用於檢查屬性圖塊的子物件。","usage":"執行 en → 選取物件 → 命令列顯示 SEQEND 子項資訊","level":2,"lt":"✅","ver":"20241002","author":"chengshunyi","video":"","fas":"fas/en.fas"},{"no":702,"file":"end-put-num.lsp","cmd":"end-put-num-ru、end-put-num-lu、end-put-num-ld、end-put-num-rd、end-put-num-rur、end-put-num-lur、end-put-num-ldr、end-put-num-rdr","cat":"文字","desc":"窗選範圍內線條端點，依方向排序（右上、左上、左下、右下，含 r 反向）後在每個端點寫入遞增編號文字。","usage":"執行 end-put-num-ru（等指令）→ 輸入起始編號 → 窗選兩角 → 依排序在線端點寫編號","level":8,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/end-put-num.fas"},{"no":703,"file":"end_insert_bylayer.lsp","cmd":"end_insert_bylayer","cat":"圖塊/屬性","desc":"在選取線段的端點依圖層插入標高圖塊，窗選範圍內過濾端點並排序後依序插入。","usage":"執行 end_insert_bylayer → 選取圖塊與線 → 窗選範圍 → 依序在端點插入標高圖塊","level":7,"lt":"✅","ver":"2008.06.17","author":"Shun_Yi Studio（鄭順益）","video":"","fas":"fas/end_insert_bylayer.fas"},{"no":704,"file":"end_insert_col_lab.lsp","cmd":"end_insert_col_lab","cat":"圖塊/屬性","desc":"在選取線端點上插入柱標區塊，可選字母或數字編號，窗選範圍內過濾端點並排序。","usage":"執行 end_insert_col_lab → 選字母或數字 → 窗選範圍 → 依序在端點插入柱標圖塊","level":7,"lt":"✅","ver":"2008.01.27；20220716","author":"Shun_Yi Studio（鄭順益）","video":"","fas":"fas/end_insert_col_lab.fas"},{"no":705,"file":"end_insert_dim.lsp","cmd":"end_insert_dim","cat":"標註","desc":"在選取線端點上插入尺寸標註，窗選範圍內過濾端點並排序後依序標註。","usage":"執行 end_insert_dim → 窗選範圍 → 依序在端點產生線性尺寸","level":7,"lt":"✅","ver":"2008.06.17；20220716","author":"Shun_Yi Studio（鄭順益）","video":"","fas":"fas/end_insert_dim.fas"},{"no":706,"file":"end_insert_ele.lsp","cmd":"end_insert_ele","cat":"圖塊/屬性","desc":"在選取線端點上插入標高圖塊與高程尺寸，窗選範圍內過濾端點並排序。","usage":"執行 end_insert_ele → 選取圖塊 → 窗選範圍 → 依序在端點插入標高","level":7,"lt":"✅","ver":"2008.06.17","author":"Shun_Yi Studio（鄭順益）","video":"","fas":"fas/end_insert_ele.fas"},{"no":707,"file":"end_insert_ele_bylayer.lsp","cmd":"end_insert_ele_bylayer","cat":"圖塊/屬性","desc":"在選取線端點上依圖層插入標高圖塊與高程尺寸，窗選範圍內過濾端點並排序。","usage":"執行 end_insert_ele_bylayer → 選取圖塊與線 → 窗選範圍 → 依序在端點插入標高","level":7,"lt":"✅","ver":"2008.06.17","author":"Shun_Yi Studio（鄭順益）","video":"","fas":"fas/end_insert_ele_bylayer.fas"},{"no":708,"file":"EntityToPointListV1-2.lsp","cmd":"Entity-to-Point-List","cat":"轉檔/匯出入","desc":"將線、圓、聚合線、橢圓、樣條等物件轉成 WCS 點座標清單，並可匯出 X/Y/Z 座標 CSV 檔。","usage":"執行 Entity-to-Point-List → 選取物件 → 產生座標點清單並輸出 CSV","level":7,"lt":"✅","ver":"2022-11-27（檔案日期）","author":"Lee Mac","video":"","fas":"fas/EntityToPointListV1-2.fas"},{"no":709,"file":"entmakex-hatch.LSP","cmd":"test1、test2、test3","cat":"繪圖","desc":"以 entmakex 建立填充物件的函式範例（座標、角度、圖樣名稱、比例），test 指令示範聚合線轉 SOLID 或 ANSI31 填充。","usage":"執行 test1（test2/test3）→ 選取聚合線 → 產生填充","level":6,"lt":"✅","ver":"2024-09-07（檔案日期）","author":"ElpanovEvgeniy","video":"","fas":"fas/entmakex-hatch.fas"},{"no":710,"file":"EPL.lsp","cmd":"EPL","cat":"繪圖","desc":"MyCAD 等分地塊系統：對話框設定後選取圖元，以面域與交集運算在多個區塊間做等面積分割並修正交界。","usage":"執行 EPL → 於對話框設定參數 → 確定 → 選取圖元 → 自動以面域/交集分割","level":9,"lt":"⚠️","ver":"2026-07-19（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/EPL.fas"},{"no":711,"file":"erase-ref-line.lsp","cmd":"erase-ref-sel、erase-ref","cat":"圖層","desc":"刪除 0-REF 圖層上的輔助線（xline、ray、line 等），erase-ref-sel 為選取刪除，erase-ref 為全圖刪除。","usage":"執行 erase-ref-sel → 選取輔助線 → 刪除；或執行 erase-ref → 一次刪除全部輔助線","level":4,"lt":"✅","ver":"20220716（檔案日期 2026-10-17）","author":"—","video":"https://youtu.be/Tsq4SdOc_OE","fas":"fas/erase-ref-line.fas"},{"no":712,"file":"ETBM.lsp","cmd":"ETBM","cat":"系統/授權","desc":"MyCAD 繪圖環境及工具列顯示管理：對話框設定背景色、字型、游標等繪圖環境與工具列顯示，含 RGB 轉 ACI。","usage":"執行 ETBM → 於對話框調整環境/工具列設定 → 確定 → 套用到繪圖環境","level":9,"lt":"⚠️","ver":"2026（檔案日期 2026-08-06）","author":"ChengBar / Shun_Yi Studio (MyCAD)","video":"","fas":""},{"no":713,"file":"EX-ATT-H-NAI.lsp","cmd":"EX-ATT-H-NAI","cat":"轉檔/匯出入","desc":"將選取圖塊的屬性值匯出到 Excel，橫向排列（每圖塊一列），排序方法結束後停駐 Excel 位置。","usage":"執行 EX-ATT-H-NAI → 選取圖塊 → 開啟 Excel 工作表 → 依序寫入屬性值","level":8,"lt":"❌","ver":"20240326（檔案日期 2024-04-12）","author":"chengshunyi（參考 exceed 2022-04-08 cadtutor 論壇）","video":"","fas":"fas/EX-ATT-H-NAI.fas"},{"no":714,"file":"EX-ATT-H.lsp","cmd":"EX-ATT-H","cat":"轉檔/匯出入","desc":"將選取圖塊的屬性值匯出到 Excel，橫向排列（每圖塊一列）。","usage":"執行 EX-ATT-H → 選取圖塊 → 開啟 Excel → 依序寫入屬性值","level":8,"lt":"❌","ver":"20240326（檔案日期 2024-04-12）","author":"chengshunyi（參考 exceed 2022-04-08）","video":"","fas":"fas/EX-ATT-H.fas"},{"no":715,"file":"EX-ATT-V.lsp","cmd":"EX-ATT-V","cat":"轉檔/匯出入","desc":"將選取圖塊的屬性值匯出到 Excel，縱向排列（每圖塊一欄／一組向下），完成後回頭換下一圖塊。","usage":"執行 EX-ATT-V → 選取圖塊 → 開啟 Excel → 依序往下寫入屬性值","level":8,"lt":"❌","ver":"20240326","author":"chengshunyi（參考 exceed 2022-04-08）","video":"","fas":"fas/EX-ATT-V.fas"},{"no":716,"file":"EX-PL-AREA.lsp","cmd":"EX-PL-AREA","cat":"轉檔/匯出入","desc":"匯出選取聚合線的面積與資料到 CSV 檔，並標註文字，完成後以記事本開啟。","usage":"執行 EX-PL-AREA → 選取聚合線 → 指定存檔位置 → 產生 CSV 並以記事本開啟","level":6,"lt":"✅","ver":"20221015","author":"pBe（Sep 2018）/ chengshunyi","video":"","fas":"fas/EX-PL-AREA.fas"},{"no":717,"file":"Example_ImportProfile.lsp","cmd":"Example_ImportProfile","cat":"系統/授權","desc":"示範匯入設定檔（Profile）：以假名稱 TestProfile 匯入 .arg 檔，不影響既有設定檔。","usage":"執行 Example_ImportProfile → 指定設定檔 → 匯入","level":2,"lt":"✅","ver":"2025-05-08（檔案日期）","author":"Autodesk 範例（網路程式）","video":"","fas":""},{"no":718,"file":"Exp-Layer2TXT.LSP","cmd":"Exp-Layer2TXT、AutoFreezeLayers、AutoThawLayers、AutoChangeLayercolor","cat":"圖層","desc":"匯出全部圖層名稱到「圖檔同名.txt」，並可依 TXT 清單批次凍結、解凍圖層或依 ch-color.txt 改圖層顏色。","usage":"執行 Exp-Layer2TXT 匯出清單 → 編輯 TXT → 執行 AutoFreezeLayers/AutoThawLayers/AutoChangeLayercolor 依清單處理","level":8,"lt":"✅","ver":"2026-11-07（檔案日期）","author":"—","video":"https://youtu.be/cRP5L8iwqLg","fas":"fas/Exp-Layer2TXT.fas"},{"no":719,"file":"exp11.lsp","cmd":"site-wb、plan-wb","cat":"文字","desc":"工地／平面圖文字詞庫工具：對話框從詞庫檔下拉選取內容，組成含日期前後置字串的文字或多重引線，依比例插入。","usage":"執行 site-wb（或 plan-wb）→ 於對話框選詞庫項目/日期選項 → 確定 → 指定位置 → 產生文字或引線","level":8,"lt":"✅","ver":"20250520（檔案日期 2025-11-10）","author":"chengshunyi","video":"","fas":"fas/exp11.fas"},{"no":720,"file":"exp12.lsp","cmd":"exp12","cat":"3D","desc":"3D 螺旋梯：對話框輸入圓柱內徑、階高、階數等，以圓、拉伸與旋轉複製產生 3D 螺旋樓梯。","usage":"執行 exp12 → 於對話框輸入樓梯參數 → 確定 → 指定位置 → 產生 3D 螺旋梯","level":6,"lt":"❌","ver":"20251025（檔案日期 2025-10-28）","author":"chengshunyi","video":"","fas":"fas/exp12.fas"},{"no":721,"file":"exp17.lsp","cmd":"exp17","cat":"圖塊/屬性","desc":"圖塊統計製表：依 blkhelp 資料取得圖塊名稱與說明，對話框設定表格尺寸後畫成方格表，並可輸出至 Excel。","usage":"執行 exp17 → 於對話框設定字高/框寬高/樣式 → 確定 → 指定位置 → 產生圖塊統計表","level":8,"lt":"⚠️","ver":"20221225；20241116","author":"chengshunyi","video":"https://youtu.be/FkRreP3D2L0","fas":"fas/exp17.fas"},{"no":722,"file":"exp21.lsp","cmd":"exp21","cat":"3D","desc":"規格櫃體 3D 模型：對話框從外部資料檔 exp21.dat 選型號、修改尺寸與層數，以聚合線拉伸成箱體並陣列挖空分層，產生 1 個 3D 實體櫃子，並切換西南等角與著色。","usage":"執行 exp21 → 於對話框選櫃體型號/修改尺寸、層數 → 確定 → 點選櫃子左下角點 → 產生 3D 櫃體","level":6,"lt":"❌","ver":"20221223","author":"chengshunyi","video":"","fas":"fas/exp21.fas"},{"no":723,"file":"exp3.LSP","cmd":"exp3","cat":"圖層","desc":"圖層管理對話框：從 exp3_lay.dat 圖層資料清單建立圖層、全選／反向選取，並可清理、變更圖層。","usage":"執行 exp3 → 於對話框從清單選圖層 → 選建立/清理/修改動作 → 確定","level":7,"lt":"✅","ver":"2022-12-26（檔案日期）","author":"chengshunyi","video":"","fas":"fas/exp3.fas"},{"no":724,"file":"exp4.lsp","cmd":"exp4","cat":"文字","desc":"對話框選字高與樣式後，建立 TXT 圖層與字型（SIMPLEX／CHINESET），依比例繪製文字外框、偏移與群組。","usage":"執行 exp4 → 於對話框選字高 h1/h2 → 確定 → 指定點 → 產生文字框","level":7,"lt":"✅","ver":"20221218","author":"chengshunyi","video":"","fas":"fas/exp4.fas"},{"no":725,"file":"exp5.lsp","cmd":"exp5","cat":"系統/授權","desc":"對話框設定鎖點角度（SNAPANG，快選 0/15/30/45/60 度）與十字游標大小（滑桿）。","usage":"執行 exp5 → 於對話框選鎖點角度或拖曳游標大小滑桿 → 確定","level":3,"lt":"✅","ver":"2022-12-12（檔案日期）","author":"—","video":"","fas":""},{"no":726,"file":"exp9.lsp","cmd":"exp9","cat":"出圖/列印","desc":"插入圖框：對話框選圖紙大小（含 A0/A1/A2）、比例、單位並填寫工程名稱、設計等標題欄屬性。","usage":"執行 exp9 → 於對話框選圖紙/比例/單位並填屬性 → 確定 → 指定插入點 → 插入圖框","level":7,"lt":"✅","ver":"20231203","author":"chengshunyi","video":"","fas":"fas/exp9.fas"},{"no":727,"file":"ExpLayToExcel.lsp","cmd":"ExpLayToExcel","cat":"轉檔/匯出入","desc":"選取物件，將其圖層名稱清單匯出到 Excel。","usage":"執行 ExpLayToExcel → 選取物件 → 開啟 Excel 並寫入圖層名稱","level":6,"lt":"❌","ver":"20220716（檔案日期 2024-12-19）","author":"—","video":"","fas":"fas/ExpLayToExcel.fas"},{"no":728,"file":"ExPlInfo-ML.LSP","cmd":"ExPlInfo-ML","cat":"標註","desc":"選取聚合線後，自動在其範圍內的多重引線寫入面積與長度，對話框可選靜態文字或動態欄位與單位。","usage":"執行 ExPlInfo → 於對話框選模式與單位 → 確定 → 選取聚合線 → 範圍內多重引線自動更新","level":8,"lt":"✅","ver":"20220716（檔案日期 2026-03-21）","author":"—","video":"","fas":"fas/ExPlInfo-ML.fas"},{"no":729,"file":"ExPlInfoToMl-auto.lsp","cmd":"ExPlInfoToMl-auto","cat":"標註","desc":"選取聚合線後，以射線算法自動比對其範圍內的多重引線（箭頭端點或中心點）並寫入面積與長度。","usage":"執行 ExportPlineInfoToMleader → 選單位 m/cm/mm → 選取聚合線（可多選）→ 自動匹配並寫入引線","level":7,"lt":"✅","ver":"2026-03-04（檔案日期）","author":"—","video":"","fas":"fas/ExPlInfoToMl-auto.fas"},{"no":730,"file":"ExPlInfoToMl.lsp","cmd":"ExPlInfoToMl","cat":"標註","desc":"1 對 1 模式：選取一條聚合線與一個多重引線，依單位換算後將面積與長度寫入該引線。","usage":"執行 ExPlInfoToMl → 選單位 m/cm/mm → 選聚合線 → 選多重引線 → 寫入面積與長度","level":5,"lt":"✅","ver":"2026-03-04（檔案日期）","author":"—","video":"","fas":"fas/ExPlInfoToMl.fas"},{"no":731,"file":"explode-and-reblock.lsp","cmd":"explode-and-reblock","cat":"圖塊/屬性","desc":"選取圖塊，炸開後在原地重新建立同名圖塊並清除舊定義。","usage":"執行 explode-and-reblock → 選取圖塊 → 自動炸開、重做圖塊並 purge","level":4,"lt":"✅","ver":"20250318","author":"chengshunyi","video":"","fas":"fas/explode-and-reblock.fas"},{"no":732,"file":"ExportLayers.lsp","cmd":"ExportLayers","cat":"轉檔/匯出入","desc":"圖層資訊匯出：對話框勾選匯出項目（顏色、線型、說明、開關、凍結、鎖定、列印），以檔案 I/O 寫成 CSV。","usage":"執行 ExportLayers → 於對話框勾選匯出項目 → 確定 → 指定儲存位置 → 產生 CSV","level":7,"lt":"✅","ver":"v23.0","author":"—","video":"","fas":"fas/ExportLayers.fas"},{"no":733,"file":"ExportLayers2Excel.lsp","cmd":"ExportLayers2Excel","cat":"轉檔/匯出入","desc":"圖層資訊匯出到 Excel：對話框勾選項目，透過 Excel COM 直接寫入並設定圖層名稱為文字格式與背景色。","usage":"執行 ExportLayers2Excel → 於對話框勾選匯出項目 → 確定 → 自動開啟 Excel 填入","level":9,"lt":"❌","ver":"v22.2","author":"—","video":"","fas":"fas/ExportLayers2Excel.fas"},{"no":734,"file":"ExportMleaderToCSV.lsp","cmd":"ExportMleaderToCSV","cat":"轉檔/匯出入","desc":"匯出選取的多重引線（Mleader）資料與 XY 座標到 CSV 檔，含 Handle 欄位。","usage":"執行 ExportMleaderToCSV → 選取多重引線（可全選）→ 指定儲存位置 → 產生 CSV","level":5,"lt":"✅","ver":"2026-02-15（檔案日期）","author":"—","video":"","fas":"fas/ExportMleaderToCSV.fas"},{"no":735,"file":"Ext-Att-CommaValues.lsp","cmd":"Ext-Att-CommaValues","cat":"轉檔/匯出入","desc":"遍歷所有佈局，讀取名為 TEXT_A3／TEXT_A3_N 的圖框圖塊屬性值，以逗號分隔寫入 TEMP 文字檔。","usage":"執行 Ext-Att-CommaValues → 自動逐一切換各佈局讀取圖框屬性 → 輸出至 TEMP\\TEXT_A3_Values_Comma.txt","level":6,"lt":"✅","ver":"20251206","author":"chengshunyi","video":"","fas":"fas/Ext-Att-CommaValues.fas"},{"no":736,"file":"fence-w-sec.lsp","cmd":"fence-w-sec","cat":"剖面/結構","desc":"繪製圍牆剖面：輸入基礎深度、基牆高度與欄杆高度，繪出基礎、牆身與欄杆並標註尺寸。","usage":"執行 fence-w-sec → 點選地面基準點 → 輸入基礎深度/基牆高/欄杆高 → 自動繪製剖面","level":5,"lt":"✅","ver":"20231222","author":"chengshunyi","video":"","fas":"fas/fence-w-sec.fas"},{"no":737,"file":"field-onoff.lsp","cmd":"field-off、field-on、field-onoff","cat":"系統/授權","desc":"切換 FIELDDISPLAY 系統變數（欄位灰底顯示）開關，field-onoff 為切換。","usage":"執行 field-off、field-on 或 field-onoff → 切換欄位底色顯示","level":1,"lt":"✅","ver":"20231214","author":"chengshunyi","video":"https://youtu.be/x2e_TjZJCHA","fas":""},{"no":738,"file":"field-upd-reactor-add.LSP","cmd":"field-upd-reactor-add","cat":"其他","desc":"加入 Command Reactor，在夾點拉伸（GRIP_STRETCH）後自動更新欄位，達成欄位即時更新。","usage":"執行 field-upd-reactor-add → 之後夾點拉伸即自動更新欄位","level":8,"lt":"✅","ver":"2025-10-18（檔案日期）","author":"—","video":"https://youtu.be/axS_ViaN7ko","fas":"fas/field-upd-reactor-add.fas"},{"no":739,"file":"field-upd-reactor-remove.lsp","cmd":"field-upd-reactor-remove","cat":"其他","desc":"移除所有 Command Reactor，停止欄位即時更新。","usage":"執行 field-upd-reactor-remove → 提示已停止即時更新","level":4,"lt":"✅","ver":"2025-10-18（檔案日期）","author":"—","video":"https://youtu.be/XgQAJbY2hGw","fas":"fas/field-upd-reactor-remove.fas"},{"no":740,"file":"FieldArithmetic.lsp","cmd":"fieldmath","cat":"標註","desc":"欄位運算：選取數個含欄位的物件，以加減乘除建立 MText 欄位運算式，結果隨來源物件自動更新，可建立於表格儲存格。","usage":"執行 fieldmath → 選擇運算子（Add/Subtract/Multiply/Divide）→ 選取物件（欄位）→ 選 Undo/Result → 指定放置點或儲存格","level":9,"lt":"✅","ver":"20220716（檔案日期 2025-03-25）","author":"Lee Mac（Field Arithmetic）/ chengshunyi","video":"","fas":"fas/FieldArithmetic.fas"},{"no":741,"file":"FieldArithmeticV1-2.lsp","cmd":"fieldmath","cat":"標註","desc":"欄位運算舊版（V1.2）：選取含欄位的物件，以加減乘除建立 MText 欄位運算式，結果可隨來源更新，可放入表格儲存格。","usage":"執行 fieldmath → 選擇運算子 → 選取物件 → 指定放置點","level":8,"lt":"✅","ver":"2022-11-23（檔案日期）","author":"Lee Mac","video":"","fas":"fas/FieldArithmeticV1-2.fas"},{"no":742,"file":"FieldFormat.lsp","cmd":"fieldformat","cat":"文字","desc":"選取含欄位的註解物件（文字、MText、屬性、多重引線、尺寸），修改欄位的格式代碼（如數字格式、單位）。","usage":"執行 fieldformat → 選取欄位物件 → 輸入或選擇格式代碼 → 欄位格式更新","level":6,"lt":"✅","ver":"2022-08-21（檔案日期）","author":"Lee Mac","video":"","fas":"fas/FieldFormat.fas"},{"no":743,"file":"FieldObjects.lsp","cmd":"fieldobjects","cat":"查詢","desc":"選取欄位文字後，顯示並高亮該欄位所參照的來源物件，按任意鍵結束。","usage":"執行 fieldobjects → 選取欄位文字 → 高亮來源物件 → 按任意鍵結束","level":5,"lt":"✅","ver":"20220716","author":"Lee Mac","video":"","fas":"fas/FieldObjects.fas"},{"no":744,"file":"Fiesta__Find_Intersection__Points__VDH-Bruno.lsp","cmd":"Fiesta","cat":"繪圖","desc":"選取多個物件，兩兩組合求交點，在每個交點放置點物件以標示交會處。","usage":"執行 Fiesta → 選取物件 → 在各交點建立點","level":6,"lt":"✅","ver":"2022-11-27（檔案日期）","author":"VDH-Bruno（網路程式）","video":"","fas":"fas/Fiesta__Find_Intersection__Points__VDH-Bruno.fas"},{"no":745,"file":"filter-o-group.lsp","cmd":"filter-o-group","cat":"修改","desc":"過濾特定顏色（白色）的線與弧物件，並依日期命名後群組。","usage":"執行 filter-o-group → 自動篩選白色線/弧 → 建立群組","level":5,"lt":"✅","ver":"20231222","author":"chengshunyi","video":"","fas":"fas/filter-o-group.fas"},{"no":746,"file":"filter-obj-del.LSP","cmd":"testfilter-dim-ch、DIMDEL、HatchDel","cat":"修改","desc":"過濾並刪除特定物件：DIMDEL 刪除尺寸標註，HatchDel 刪除填充，testfilter-dim-ch 為尺寸過濾測試。","usage":"執行 DIMDEL（或 HatchDel）→ 自動過濾並刪除全圖對應物件","level":6,"lt":"✅","ver":"20240208","author":"chengshunyi","video":"","fas":"fas/filter-obj-del.fas"},{"no":747,"file":"filterDyn-door.lsp","cmd":"filterDyn-door","cat":"面積/數量統計","desc":"過濾專用門動態圖塊（NO-SD-F-D），依 TYPE 屬性統計各類型數量並建立屬性總計表格。","usage":"執行 filterDyn-door → 自動篩選門圖塊 → 點選表格插入點 → 產生數量表","level":6,"lt":"✅","ver":"20220501","author":"chengshunyi","video":"","fas":"fas/filterDyn-door.fas"},{"no":748,"file":"filterDyn-win.lsp","cmd":"filterDyn-win","cat":"面積/數量統計","desc":"過濾專用窗動態圖塊（NO-W-F-D），依 TYPE 屬性統計各類型數量並建立屬性總計表格。","usage":"執行 filterDyn-win → 自動篩選窗圖塊 → 點選表格插入點 → 產生數量表","level":6,"lt":"✅","ver":"20220501","author":"chengshunyi","video":"","fas":"fas/filterDyn-win.fas"},{"no":749,"file":"FilterMLeaderMRS.lsp","cmd":"FilterMLeaderMRS","cat":"標註","desc":"MyCAD 多重引線過濾與鏡射：對話框選擇範圍（手動窗選等）與動作，篩選多重引線後選取或沿基準點鏡射，並可移到目標圖層。","usage":"執行 FilterMLeaderMRS → 於對話框選範圍/動作/鏡射方向/目標圖層 → 確定 → 窗選 → 套用","level":8,"lt":"✅","ver":"2026-06-02（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/FilterMLeaderMRS.fas"},{"no":750,"file":"FilterNoLinkMLeader.lsp","cmd":"FilterNoLinkMLeader","cat":"標註","desc":"MyCAD 過濾無引線的多重引線：對話框選過濾範圍與動作，篩選後高亮選取或搬到指定圖層。","usage":"執行 FilterNoLinkMLeader → 於對話框選範圍(窗選/全圖)與動作 → 確定 → 選取 → 套用","level":7,"lt":"✅","ver":"2026-05-30（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/FilterNoLinkMLeader.fas"},{"no":751,"file":"filterpoly-el-chcolor.LSP","cmd":"filterpoly-el-chcolor","cat":"修改","desc":"過濾 LWPOLYLINE 並依其高程改變顏色，目前程式僅為過濾骨架。","usage":"執行 filterpoly-el-chcolor → 選取聚合線 → 依高程改色","level":1,"lt":"✅","ver":"20221203","author":"chengshunyi","video":"","fas":"fas/filterpoly-el-chcolor.fas"},{"no":752,"file":"find-att-value-2.lsp","cmd":"find-d-string、find-dw-string、find-W-string","cat":"圖塊/屬性","desc":"在專用門、地下連續壁、窗圖塊中依輸入字串搜尋 TYPE 屬性值，並找出符合的圖塊。","usage":"執行 find-d-string（或 find-dw-string / find-W-string）→ 輸入搜尋字串 → 命令列/圖面標出符合圖塊","level":6,"lt":"✅","ver":"20230315","author":"chengshunyi","video":"","fas":"fas/find-att-value-2.fas"},{"no":753,"file":"find-gap.lsp","cmd":"find-gap","cat":"查詢","desc":"輸入最大／最小間隙與圓大小，在圖面中尋找兩物件間隙並以圓標示。","usage":"執行 find-gap → 輸入最大間隙 → 輸入最小間隙 → 輸入圓半徑 → 以圓標出間隙處","level":6,"lt":"✅","ver":"202410","author":"chengshunyi","video":"","fas":"fas/find-gap.fas"},{"no":754,"file":"find-objs-centerid.LSP","cmd":"find-objs-centerid","cat":"查詢","desc":"計算選取物件選集的包圍框（左下、右上座標），用以找出物件群中心。","usage":"執行 find-objs-centerid → 選取物件 → 命令列顯示包圍框","level":2,"lt":"✅","ver":"2024-05-01（檔案日期）","author":"Lee Mac（Selection Set Bounding Box）","video":"","fas":"fas/find-objs-centerid.fas"},{"no":755,"file":"find-rm-any.lsp","cmd":"find-rm-any","cat":"圖塊/屬性","desc":"依任意屬性 Tag 與輸入編號，在圖塊中尋找符合的房間編號並 ZOOM 至該圖塊。","usage":"執行 find-rm-any → 輸入編號 → 點選屬性 Tag → 自動搜尋並縮放到該圖塊","level":5,"lt":"✅","ver":"2021.03.21；20240419","author":"chengshunyi","video":"https://youtu.be/UNf8FLQAylw","fas":"fas/find-rm-any.fas"},{"no":756,"file":"find-rm-last-Any.lsp","cmd":"find-rm-last-any","cat":"圖塊/屬性","desc":"依任意屬性 Tag 找出最後一個房間編號的圖塊，顯示最後一碼並 ZOOM 到該處。","usage":"執行 find-rm-last-any → 點選屬性 Tag → 顯示最後編號並縮放","level":5,"lt":"✅","ver":"20080610；20240419","author":"chengshunyi","video":"","fas":"fas/find-rm-last-Any.fas"},{"no":757,"file":"find-rm-last.lsp","cmd":"find-rm-last","cat":"圖塊/屬性","desc":"輸入圖塊名稱，找出該圖塊最後一個房間編號並 ZOOM 到該處，顯示最後一碼。","usage":"執行 find-rm-last → 選取圖塊 → 顯示最後編號並縮放","level":5,"lt":"✅","ver":"20080610；20220716","author":"chengshunyi（鄭順益）","video":"https://youtu.be/xA1ReZF1G7M","fas":"fas/find-rm-last.fas"},{"no":758,"file":"find-rm.lsp","cmd":"find-rm","cat":"圖塊/屬性","desc":"輸入圖塊名稱與房間編號，搜尋對應圖塊並 ZOOM 到該處。","usage":"執行 find-rm → 輸入房間編號 → 選取圖塊 → 自動縮放到該圖塊","level":5,"lt":"✅","ver":"2021.03.21；20220716","author":"chengshunyi（鄭順益）","video":"https://youtu.be/OyS9_UODzCA","fas":"fas/find-rm.fas"},{"no":759,"file":"find_same_insert_blk.lsp","cmd":"find_same_insert_blk","cat":"查詢","desc":"尋找插入點重疊的圖塊（0.1 單位內），以線標示並於重疊處加註 SAME_BASE_POINT 說明。","usage":"執行 find_same_insert_blk → 自動檢查全圖圖塊 → 在重疊處加註標示","level":6,"lt":"✅","ver":"2024-10-09（檔案日期）","author":"RJP（2023-04-05）/ chengshunyi","video":"","fas":"fas/find_same_insert_blk.fas"},{"no":760,"file":"FindReplace.LSP","cmd":"FR、FindReplace","cat":"文字","desc":"對話框尋找並取代圖面文字（含屬性），可跨多個圖檔批次處理。","usage":"執行 FR → 於對話框輸入尋找/取代字串 → 確定 → 執行取代","level":8,"lt":"✅","ver":"Created 2023-04-05（檔案日期）","author":"Terry Miller (autolisp-exchange.com)","video":"","fas":"fas/FindReplace.fas"},{"no":761,"file":"FindTextLineInt.lsp","cmd":"FindTextLineInt","cat":"剖面/結構","desc":"MyCAD 鋼結構梁尺寸偵測：對話框輸入距離與字高，偵測文字與線的交點並標註。","usage":"執行 FindTextLineInt → 於對話框輸入距離/字高 → 確定 → 選取文字與線 → 偵測標註","level":7,"lt":"✅","ver":"2026-01-24（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/FindTextLineInt.fas"},{"no":762,"file":"fire-area-c-lays.lsp","cmd":"fire-area-c-lays","cat":"圖層","desc":"檢查並建立防火區劃相關圖層（名稱、顏色、線型），並載入 MY-CNS-線型.lin 線型。","usage":"執行 fire-area-c-lays → 自動建立防火區劃圖層與線型","level":5,"lt":"✅","ver":"20241006","author":"chengshunyi","video":"","fas":"fas/fire-area-c-lays.fas"},{"no":763,"file":"FIRE-AREA.lsp","cmd":"FIRE-AREA","cat":"面積/數量統計","desc":"防火區劃自動標註：對話框選單位與比例，選取聚合線後在中心放置標註圖塊與面積欄位。","usage":"執行 FIRE-AREA → 於對話框設定圖層/單位/比例尺 → 確定 → 選取聚合線 → 自動放置標註","level":9,"lt":"✅","ver":"20250716","author":"chengshunyi（MyCAD）","video":"","fas":"fas/FIRE-AREA.fas"},{"no":764,"file":"fire-SetPlW.lsp","cmd":"fire-SetPlW","cat":"圖層","desc":"選取防火牆各圖層上的聚合線，將線寬統一設為 10。","usage":"執行 fire-SetPlW → 自動選取防火牆圖層聚合線 → 線寬設為 10","level":3,"lt":"✅","ver":"2025-07-26（檔案日期）","author":"chengshunyi","video":"","fas":"fas/fire-SetPlW.fas"},{"no":765,"file":"FIRE-WALL-PICK.lsp","cmd":"FIRE-WALL-PICK","cat":"圖層","desc":"連續點選防火區劃聚合線的段落，複製到對應防火牆圖層（-ST／-SHAFT 等），圖層與線型自動建立。","usage":"執行 FIRE-WALL-PICK → 連續點選聚合線上任一點 → 自動複製段落到防火牆圖層 → 右鍵結束","level":6,"lt":"✅","ver":"2025-11-11（檔案日期）","author":"chengshunyi","video":"","fas":"fas/FIRE-WALL-PICK.fas"},{"no":766,"file":"FireAreaTable-ui.lsp","cmd":"FireAreaTable-ui","cat":"面積/數量統計","desc":"防火區劃標註及檢討：對話框選單位/比例/前置碼，標註各區劃面積圖塊並建立防火區劃檢討表。","usage":"執行 FireAreaTable-ui → 於對話框設定單位/比例/前置碼 → 確定 → 選取聚合線 → 標註並產生表格","level":9,"lt":"✅","ver":"2025-09-02（檔案日期）","author":"chengshunyi","video":"","fas":"fas/FireAreaTable-ui.fas"},{"no":767,"file":"FireAreaTable.lsp","cmd":"FireAreaTable","cat":"面積/數量統計","desc":"防火區劃標註及檢討（命令列版）：選單位與比例尺後標註各區劃面積並建立檢討表。","usage":"執行 FireAreaTable → 選 mm/cm/M → 選比例尺與前置碼 → 選取聚合線 → 標註並產生表格","level":8,"lt":"✅","ver":"2025-08-05（檔案日期）","author":"chengshunyi","video":"","fas":"fas/FireAreaTable.fas"},{"no":768,"file":"fix-hat-to-onelayer.lsp","cmd":"fix-hat-to-onelayer","cat":"圖層","desc":"將圖面 WALLHATCH 圖層的填充統一改到 my-HATCH 圖層，並移到最下層。","usage":"執行 fix-hat-to-onelayer → 自動改圖層並置底","level":3,"lt":"✅","ver":"20240409","author":"chengshunyi","video":"","fas":"fas/fix-hat-to-onelayer.fas"},{"no":769,"file":"fix-obj-color.LSP","cmd":"foc-1、foc-2、foc-3、foc-4、foc-5、foc-6、foc-7、foc-8、foc-9、fix-obj-color","cat":"修改","desc":"選取某物件的圖層，將該圖層所有物件改為指定顏色（foc-1~9 對應顏色），並置前。","usage":"執行 foc-1（或 foc-2 … foc-9）→ 選取物件取得圖層 → 該圖層物件改色並置前","level":5,"lt":"✅","ver":"20240409","author":"chengshunyi","video":"","fas":"fas/fix-obj-color.fas"},{"no":770,"file":"fixalltext.lsp","cmd":"fixalltext","cat":"文字","desc":"將一組屬性套用到所有文字、MText、圖塊屬性、屬性定義、多重引線與尺寸，統一字型與樣式。","usage":"執行 fixalltext → 設定字型/樣式等 → 套用到全圖文字物件","level":7,"lt":"⚠️","ver":"2026-10-17（檔案日期）","author":"Lee Mac（Fix All Text）","video":"https://youtu.be/TbwUcPxVOFQ","fas":"fas/fixalltext.fas"},{"no":771,"file":"fixatts-all.lsp","cmd":"fixatts-all","cat":"圖塊/屬性","desc":"更改全圖屬性圖塊內 D-NUM 屬性定義的圖層為 DEFPOINTS、顏色 ByLayer，並將字寬設為 0.8。","usage":"執行 fixatts-all → 自動修改全圖圖塊定義內 D-NUM 屬性","level":5,"lt":"✅","ver":"20220118","author":"chengshunyi","video":"","fas":"fas/fixatts-all.fas"},{"no":772,"file":"fixatts-byblkname.lsp","cmd":"fixatts-byblkname","cat":"圖塊/屬性","desc":"輸入圖塊名稱，更改該圖塊定義內 D-NUM 屬性定義的圖層、顏色與字寬。","usage":"執行 fixatts-byblkname → 輸入圖塊名稱 → 自動修改該圖塊 D-NUM 屬性","level":5,"lt":"✅","ver":"2022-08-17（檔案日期）","author":"Tharwat（03. March 2012）/ chengshunyi","video":"","fas":"fas/fixatts-byblkname.fas"},{"no":773,"file":"fixatts-one.lsp","cmd":"fixatts-one","cat":"圖塊/屬性","desc":"選取單一圖塊，更改其定義內屬性定義的圖層（DEFPOINTS）、顏色（ByLayer）與字寬 0.8。","usage":"執行 fixatts-one → 選取圖塊 → 自動修改屬性定義","level":4,"lt":"✅","ver":"20220118","author":"chengshunyi","video":"","fas":"fas/fixatts-one.fas"},{"no":774,"file":"fixatts.lsp","cmd":"fixatts","cat":"圖塊/屬性","desc":"更改屬性圖塊內物件的圖層、顏色與字寬（D-NUM 改為 DEFPOINTS、ByLayer、字寬 0.8）。","usage":"執行 fixatts → 自動修改屬性圖塊內物件","level":5,"lt":"✅","ver":"20220118","author":"chengshunyi","video":"","fas":"fas/fixatts.fas"},{"no":775,"file":"fixhatlay.LSP","cmd":"fixhatlay","cat":"圖層","desc":"將 AELE 圖層上的填充顏色改為綠色。","usage":"執行 fixhatlay → 自動將 AELE 層 HATCH 設為綠色","level":2,"lt":"✅","ver":"2022-09-09（檔案日期）","author":"—","video":"","fas":"fas/fixhatlay.fas"},{"no":776,"file":"FixLTSCALE.lsp","cmd":"FixLTSCALE","cat":"系統/授權","desc":"對話框顯示並修正線型比例相關變數（LTSCALE、MSLTSCALE、PSLTSCALE、CELTSCALE），並依 MEASUREMENT 預設選 iso／acad 線型檔。","usage":"執行 FixLTSCALE → 於對話框檢視並修改比例變數與線型檔 → 確定 → 重生圖形","level":6,"lt":"✅","ver":"20251225","author":"chengshunyi","video":"","fas":""},{"no":777,"file":"floor-line.lsp","cmd":"floor-line","cat":"繪圖","desc":"MyCAD 樓層線：對話框設定樓層名稱與高度，自動建立 Floor-Line 圖層與 dot 線型，繪製樓層線並插入樓層標高圖塊與尺寸。","usage":"執行 floor-line → 於對話框設定樓層參數 → 確定 → 指定起點 → 繪製樓層線與標註","level":8,"lt":"✅","ver":"2025-10-25（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/floor-line.fas"},{"no":778,"file":"fndreplace.LSP","cmd":"fndreplace","cat":"文字","desc":"透過 ObjectDBX 批次開啟資料夾內多個 DWG，尋找並取代指定字串。","usage":"執行 fndreplace → 輸入尋找字串 → 輸入取代字串 → 選取資料夾 → 批次取代","level":8,"lt":"❌","ver":"2023-12-31（檔案日期）","author":"Lee McDonnell（ObjectDBX）；RJP 修改（2009.10.24）","video":"","fas":"fas/fndreplace.fas"},{"no":779,"file":"FREZENTS.LSP","cmd":"frezents","cat":"圖層","desc":"選取物件後凍結其所在圖層，並可用 OK 框確認後繼續。","usage":"執行 frezents → 選取物件 → 該圖層被凍結 → 繼續或中止","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/FREZENTS.fas"},{"no":780,"file":"G-Attr2Table.lsp","cmd":"G-Attr2Table","cat":"圖塊/屬性","desc":"對話框選擇多個屬性欄位與排序欄位，將選取圖塊屬性匯出成表格物件。","usage":"執行 G-Attr2Table → 於對話框選屬性與排序欄位 → 確定 → 選取圖塊 → 指定插入點","level":7,"lt":"✅","ver":"20250716","author":"copilot（AI 產生）/ chengshunyi","video":"","fas":"fas/G-Attr2Table.fas"},{"no":781,"file":"G-atts2table.LSP","cmd":"G-atts2table-Dcl、G-atts2table","cat":"圖塊/屬性","desc":"MyCAD 圖塊屬性匯入表格：選取圖塊，將屬性值以欄位方式插入表格，並依需要新增列或欄，對話框設定選項。","usage":"執行 G-atts2table-Dcl → 於對話框設定選項 → 確定 → 選取圖塊 → 指定表格位置","level":8,"lt":"✅","ver":"2026-10-17（檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/G-atts2table.fas"},{"no":782,"file":"G-GET-BL-ATT.LSP","cmd":"G-GET-BL-ATT","cat":"轉檔/匯出入","desc":"選取圖塊讀取屬性資料（含面積、長度），依第一欄位排序後輸出到 Excel 並設定儲存格格式與顏色。","usage":"執行 G-GET-BL-ATT → 選取圖塊 → 自動開啟 Excel 並寫入排序後的屬性資料","level":8,"lt":"❌","ver":"2009.09.09；20240323","author":"chengshunyi（TO SSDC）","video":"","fas":"fas/G-GET-BL-ATT.fas"},{"no":783,"file":"g-hatch-a.lsp","cmd":"g-hatch-a-a、g-hatch-a-b、g-hatch-a-c","cat":"面積/數量統計","desc":"綠建材填充面積標註：選取填充或聚合線，計算面積並以圖塊、MText 或文字標註，含前置碼與自動編號。","usage":"執行 g-hatch-a-a（-b / -c）→ 輸入前置碼與起始編號 → 選取填充/聚合線 → 指定標註位置","level":9,"lt":"✅","ver":"PolyArea GC (gile) 03/03/2018；20220716","author":"gile / chengshunyi","video":"","fas":"fas/g-hatch-a.fas"},{"no":784,"file":"G-MAT-AREA-CEILING-PL.LSP","cmd":"G-MAT-AREA-CEILING-PL","cat":"面積/數量統計","desc":"綠建材天花以聚合線計算面積：對話框選單位與比例，在 PLINE 中心放置標註圖塊並寫入面積。","usage":"執行 G-MAT-AREA-CEILING-PL → 於對話框設定圖層/單位/比例 → 確定 → 選取聚合線 → 自動標註面積","level":9,"lt":"✅","ver":"20250720；20250724","author":"chengshunyi（MyCAD）","video":"","fas":"fas/G-MAT-AREA-CEILING-PL.fas"},{"no":785,"file":"G-MAT-AREA-CEILING.LSP","cmd":"G-MAT-AREA-CEILING","cat":"面積/數量統計","desc":"綠建材天花以填充（HATCH）計算面積：對話框選單位與比例，在填充中心放置標註圖塊並寫入面積。","usage":"執行 G-MAT-AREA-CEILING → 於對話框設定圖層/單位/比例 → 確定 → 選取填充 → 自動標註面積","level":9,"lt":"✅","ver":"20250720；20250724","author":"chengshunyi（MyCAD）","video":"","fas":"fas/G-MAT-AREA-CEILING.fas"},{"no":786,"file":"G-MAT-AREA-LEN.lsp","cmd":"G-MAT-AREA-LEN","cat":"面積/數量統計","desc":"綠建材自動標註（面積／長度）：對話框選前置碼、單位與比例，在聚合線中心放置標註並寫入面積或長度。","usage":"執行 G-MAT-AREA-LEN → 於對話框設定前置碼/單位/比例 → 確定 → 選取聚合線 → 自動標註","level":9,"lt":"✅","ver":"20250716（檔案日期 2026-10-17）","author":"chengshunyi（MyCAD）","video":"","fas":"fas/G-MAT-AREA-LEN.fas"},{"no":787,"file":"G-MAT-AREA.lsp","cmd":"G-MAT-AREA","cat":"面積/數量統計","desc":"綠建材自動標註面積：對話框選前置碼、單位與比例，在填充中心放置標註並寫入面積。","usage":"執行 G-MAT-AREA → 於對話框設定前置碼/單位/比例 → 確定 → 選取填充 → 自動標註","level":9,"lt":"✅","ver":"20250720；20250724","author":"chengshunyi（MyCAD）","video":"","fas":"fas/G-MAT-AREA.fas"},{"no":788,"file":"G-MAT-NUMBERING.lsp","cmd":"G-MAT-NUMBERING","cat":"圖塊/屬性","desc":"綠建材圖塊編號：對話框設定前置碼、位數與排序方式，為選取圖塊依序寫入屬性編號。","usage":"執行 G-MAT-NUMBERING → 於對話框設定前置碼/位數/排序 → 確定 → 選取圖塊 → 自動編號","level":7,"lt":"✅","ver":"2025-07-16（檔案日期）","author":"chengshunyi（MyCAD）","video":"","fas":"fas/G-MAT-NUMBERING.fas"},{"no":789,"file":"g-pl-ap.LSP","cmd":"g-pl-ap-a、ssdc-ap-b、ssdc-ap-c","cat":"面積/數量統計","desc":"選取封閉聚合線標註面積與周長（cm2 換算 m2），可選圖塊、MTEXT 或 TEXT 形式並自動編號，三個指令為不同標註版型。","usage":"執行 g-pl-ap-a → 設定字高/標註形式/字體 → 輸入前置碼與起始編號 → 選取聚合線 → 指定標註位置","level":6,"lt":"✅","ver":"20240322","author":"PolyArea (gile) 改寫 / chengshunyi","video":"","fas":"fas/g-pl-ap.fas"},{"no":790,"file":"G-RE-NUMBERING-TEXT.lsp","cmd":"G-RE-NUMBERING-TEXT","cat":"文字","desc":"以 DCL 設定前置碼、位數、排序方向與起始號，依位置順序（左右上下等七種）將選取的文字改寫成連續編號。","usage":"執行 G-RE-NUMBERING-TEXT → 於對話框設定前置/位數/順序/起始號/後置 → 框選文字 → 完成編號","level":6,"lt":"✅","ver":"2026-10-17(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/G-RE-NUMBERING-TEXT.fas"},{"no":791,"file":"G-RE-NUMBERING-V1.lsp","cmd":"G-RE-NUMBERING-V1","cat":"圖塊/屬性","desc":"MyCAD 屬性自動/手動編號系統，以 DCL 設定編碼規則，支援跨工作階段續編、手動逐一點選與 B 鍵回退上一筆。","usage":"執行 G-RE-NUMBERING-V1 → 點選樣本屬性 → 於對話框設定前置/位數/順序/起始號 → 自動框選或手動逐一點選 → 需要時按 B 回退","level":7,"lt":"✅","ver":"2026-05-26(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/G-RE-NUMBERING-V1.fas"},{"no":792,"file":"G-RE-NUMBERING.LSP","cmd":"G-RE-NUMBERING","cat":"圖塊/屬性","desc":"綠建材圖塊屬性編碼工具，以 DCL 設定前置碼、位數、排序方式與換行間隔，依插入點位置自動寫入編號。","usage":"執行 G-RE-NUMBERING → 選取要編號的屬性圖塊 → 於對話框設定前置碼/位數/順序/換行間隔 → 確定 → 依序編號","level":6,"lt":"✅","ver":"20250716","author":"chengshunyi + copilot","video":"","fas":"fas/G-RE-NUMBERING.fas"},{"no":793,"file":"gb-hatch-erase.lsp","cmd":"gb-hatch-erase","cat":"繪圖","desc":"選取範圍內只過濾出 HATCH 填充線並整批刪除，用於綠建築面積統計後清除分類填充。","usage":"執行 gb-hatch-erase → 框選範圍 → 自動刪除範圍內所有 HATCH","level":2,"lt":"✅","ver":"20240325","author":"Cheng Shun_Yi","video":"","fas":"fas/gb-hatch-erase.fas"},{"no":794,"file":"gb-hatch-la-area.LSP","cmd":"gb-hatch-la-area","cat":"面積/數量統計","desc":"以 HATCH 圖層為分類依據，統計各類（樓地板、機電、梯廳、陽台等）面積並累加，於指定位置標註採光面積計算結果。","usage":"執行 gb-hatch-la-area → 框選 HATCH → 依圖層分類計算 → 指定文字放置點 → 輸出分類面積文字","level":8,"lt":"✅","ver":"20240329","author":"Lee Mac 改寫 / Cheng Shun_Yi","video":"","fas":"fas/gb-hatch-la-area.fas"},{"no":795,"file":"gb-pl-la-area.LSP","cmd":"gb-pl-la-area","cat":"面積/數量統計","desc":"以聚合線圖層為分類依據，統計各類面積並四捨五入後累加，於指定位置標註採光面積計算結果，並可插入圖塊。","usage":"執行 gb-pl-la-area → 框選聚合線 → 依圖層分類計算 → 指定文字放置點 → 輸出分類面積文字","level":8,"lt":"✅","ver":"20240412","author":"Lee Mac 改寫 / Cheng Shun_Yi","video":"","fas":"fas/gb-pl-la-area.fas"},{"no":796,"file":"gb-pline-area.LSP","cmd":"gb-pline-area","cat":"面積/數量統計","desc":"以聚合線圖層為分類依據，統計各分類（樓地板、陽台、梯廳、機電、居室等）面積並依比例單位標註在圖面。","usage":"執行 gb-pline-area → 選取封閉聚合線 → 依圖層分類統計 → 指定文字放置點 → 標註分類面積","level":6,"lt":"✅","ver":"20240329","author":"Lee Mac 改寫 / Cheng Shun_Yi","video":"","fas":"fas/gb-pline-area.fas"},{"no":797,"file":"gb-pline-hatch.LSP","cmd":"gb-pl-hatch-s、gb-pl-hatch-l","cat":"繪圖","desc":"依聚合線所在圖層顏色在其範圍內建立 solid 填充（-s）或雙斜線填充（-l），供綠建築面積分類檢核。","usage":"執行 gb-pl-hatch-s 或 gb-pl-hatch-l → 框選聚合線/圓 → 自動依圖層色建立 HATCH","level":4,"lt":"✅","ver":"20240325","author":"Cheng Shun_Yi","video":"","fas":"fas/gb-pline-hatch.fas"},{"no":798,"file":"GeometryAreaReport.LSP","cmd":"GeometryAreaReport","cat":"面積/數量統計","desc":"辨識選取的聚合線為矩形、梯形或平行四邊形，或圓與弧，並輸出對應的面積公式與計算結果報表。","usage":"執行 GeometryAreaReport → 選取聚合線/圓/弧 → 顯示頂點數、圖形類型、公式與面積 → 可輸出報告","level":7,"lt":"✅","ver":"20250712","author":"copilot（AI 撰寫）","video":"","fas":"fas/GeometryAreaReport.fas"},{"no":799,"file":"get-area-box-W.LSP","cmd":"get-area-box-w","cat":"面積/數量統計","desc":"讀取圖面上的面積框動態圖塊（矩形、三角形、梯形、弧形、扇形、自定義形等），彙整並列出面積計算式及合計於圖面。","usage":"執行 get-area-box-w → 框選面積計算圖塊 → 指定文字放置點 → 輸出計算式與合計","level":8,"lt":"✅","ver":"2018.03.04 / 20250706","author":"Design By Cheng Shun-Yi","video":"https://youtu.be/g3GkQDN2Ocg","fas":"fas/get-area-box-W.fas"},{"no":800,"file":"get-area-by-type-m-d.LSP","cmd":"get-area-by-type-m-d","cat":"面積/數量統計","desc":"讀取面積計算圖塊並依分類（樓地板、機電空間等）分列加總，輸出各類計算式明細，並自動建立所需圖層。","usage":"執行 get-area-by-type-m-d → 框選計算式圖塊 → 依分類排序 → 指定文字放置點 → 輸出分類計算式明細","level":7,"lt":"✅","ver":"2021.11.28","author":"Cheng Shun-Yi（含 Lee Mac 副程式）","video":"","fas":"fas/get-area-by-type-m-d.fas"},{"no":801,"file":"get-area-by-type-m.LSP","cmd":"get-area-by-type-m","cat":"面積/數量統計","desc":"面積計算圖塊分類彙整工具，先以 DCL 設定比例與單位，選取後以第二個 DCL 管理分類順序（上移、下移、刪除、重選）再輸出。","usage":"執行 get-area-by-type-m → 於對話框設定比例/單位 → 選取圖塊 → 於分類管理對話框調整順序 → 指定位置輸出","level":7,"lt":"✅","ver":"V3.0 2026.09.30","author":"ChengBar (MyCAD)","video":"https://youtu.be/9Pos5TG33do","fas":"fas/get-area-by-type-m.fas"},{"no":802,"file":"get-area-by-type.LSP","cmd":"get-area-by-type","cat":"面積/數量統計","desc":"讀取面積計算圖塊並依分類加總，輸出各類計算式與面積合計，為 get-area-by-type 系列的基本版。","usage":"執行 get-area-by-type → 框選計算式圖塊 → 指定文字放置點 → 輸出各分類計算式","level":6,"lt":"✅","ver":"2021.09.01","author":"Design By Cheng Shun-Yi（含 Lee Mac 副程式）","video":"","fas":"fas/get-area-by-type.fas"},{"no":803,"file":"get-area-gb-List-A.LSP","cmd":"get-area-gb-List-A","cat":"面積/數量統計","desc":"讀取含動態區塊的面積圖塊，統計樓地板、牆面、平頂的綠建材面積，並依綠建材 Y/N 列出計算式。","usage":"執行 get-area-gb-List-A → 框選面積圖塊 → 指定文字放置點 → 輸出樓地板/牆面/平頂面積列表","level":5,"lt":"✅","ver":"2020.11.08","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/get-area-gb-List-A.fas"},{"no":804,"file":"get-area-gb-List-B.LSP","cmd":"get-area-gb-List-B","cat":"面積/數量統計","desc":"讀取含動態區塊的面積圖塊，統計樓地板、牆面、平頂綠建材面積，輸出另一種排列（B 版）的計算式列表。","usage":"執行 get-area-gb-List-B → 框選面積圖塊 → 指定文字放置點 → 輸出面積列表","level":5,"lt":"✅","ver":"2020.11.08","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/get-area-gb-List-B.fas"},{"no":805,"file":"get-area-gb-List.LSP","cmd":"get-area-gb-List","cat":"面積/數量統計","desc":"讀取含動態區塊的面積圖塊，統計樓地板、牆面、平頂綠建材面積並列出計算式與周長算式（基本版）。","usage":"執行 get-area-gb-List → 框選面積圖塊 → 指定文字放置點 → 輸出面積列表","level":5,"lt":"✅","ver":"2020.11.08","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/get-area-gb-List.fas"},{"no":806,"file":"get-area-gb-w.LSP","cmd":"get-area-gb-w","cat":"面積/數量統計","desc":"讀取面積動態圖塊，分別統計樓地板、牆面、天花面積，依字寬排版輸出計算式並建立所需圖層。","usage":"執行 get-area-gb-w → 框選動態圖塊 → 指定文字放置點 → 輸出樓地板/牆面/天花面積計算式","level":7,"lt":"✅","ver":"2020.11.08","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/get-area-gb-w.fas"},{"no":807,"file":"get-area-row-W-num-text0.LSP","cmd":"get-area-row-w-num-text0","cat":"面積/數量統計","desc":"面積計算圖塊列式計算工具，依首字（數字/大寫/小寫）判斷樓地板、扣除、容積及停車面積並輸出完整計算式與合計。","usage":"執行 get-area-row-w-num-text0 → 框選計算式圖塊 → 指定文字放置點 → 輸出分項計算式與容積/停車面積","level":9,"lt":"✅","ver":"2021.04.30","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/get-area-row-W-num-text0.fas"},{"no":808,"file":"get-area-row-W-num-text10.LSP","cmd":"get-area-row-w-num-text10","cat":"面積/數量統計","desc":"面積計算圖塊列式計算工具（text10 版），支援多類型小數點，輸出樓地板、容積、停車面積分項計算式。","usage":"執行 get-area-row-w-num-text10 → 框選計算式圖塊 → 指定文字放置點 → 輸出計算式","level":9,"lt":"✅","ver":"2021.04.30 / 20220716更新","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/get-area-row-W-num-text10.fas"},{"no":809,"file":"get-area-row-W-num-text7.LSP","cmd":"get-area-row-w-num-text7","cat":"面積/數量統計","desc":"面積計算圖塊列式計算舊版（text7），輸出樓地板、開口挑空、機電、安全梯、陽台、停車等分類計算式。","usage":"執行 get-area-row-w-num-text7 → 框選計算式圖塊 → 指定文字放置點 → 輸出分類計算式","level":8,"lt":"✅","ver":"2020.09.30","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/get-area-row-W-num-text7.fas"},{"no":810,"file":"get-area-row-W-num-text8.LSP","cmd":"get-area-row-w-num-text8","cat":"面積/數量統計","desc":"面積計算圖塊列式計算（text8 版），依首字分類樓地板與扣除面積，輸出分項計算式與合計。","usage":"執行 get-area-row-w-num-text8 → 框選計算式圖塊 → 指定文字放置點 → 輸出計算式","level":8,"lt":"✅","ver":"2020.09.30","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/get-area-row-W-num-text8.fas"},{"no":811,"file":"get-area-row-W-num-text9.LSP","cmd":"get-area-row-w-num-text9","cat":"面積/數量統計","desc":"面積計算圖塊列式計算（text9 版），新增多類型小數點支援，輸出樓地板與扣除面積分項計算式。","usage":"執行 get-area-row-w-num-text9 → 框選計算式圖塊 → 指定文字放置點 → 輸出計算式","level":8,"lt":"✅","ver":"2021.03.20","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/get-area-row-W-num-text9.fas"},{"no":812,"file":"get-area-row-W-num-textA.LSP","cmd":"get-area-row-w-num-textA","cat":"面積/數量統計","desc":"面積計算圖塊列式計算（textA 版），計算容積及停車樓地板面積，輸出分項計算式與合計。","usage":"執行 get-area-row-w-num-textA → 框選計算式圖塊 → 指定文字放置點 → 輸出計算式","level":9,"lt":"✅","ver":"2021.04.30 / 20220716更新","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/get-area-row-W-num-textA.fas"},{"no":813,"file":"get-area-row-W.LSP","cmd":"get-area-row-w","cat":"面積/數量統計","desc":"讀取矩形、三角形、梯形、弧形、扇形等計算式圖塊，依列式組合面積計算式與合計並寫入圖面。","usage":"執行 get-area-row-w → 框選計算式圖塊 → 指定文字放置點 → 輸出列式計算式","level":7,"lt":"✅","ver":"2018.03.04 / 檔案日期 2026-10-17","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/get-area-row-W.fas"},{"no":814,"file":"get-area-rows-w-ppmm.LSP","cmd":"get-area-rows-w-ppmm","cat":"面積/數量統計","desc":"讀取各形狀計算式圖塊，輸出含加減項（新增加加減減）的多列面積計算式與合計。","usage":"執行 get-area-rows-w-ppmm → 框選計算式圖塊 → 指定文字放置點 → 輸出多列計算式","level":6,"lt":"✅","ver":"20210421","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/get-area-rows-w-ppmm.fas"},{"no":815,"file":"get-area-rows-W-s.LSP","cmd":"get-area-rows-w-s","cat":"面積/數量統計","desc":"讀取計算式圖塊後輸出 1 列式，或 2 列式僅列頭尾（1+2+...+n=合計）的簡化面積計算式。","usage":"執行 get-area-rows-w-s → 框選計算式圖塊 → 指定文字放置點 → 輸出完整列式與簡式兩行","level":6,"lt":"✅","ver":"2021.04.27","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/get-area-rows-W-s.fas"},{"no":816,"file":"get-area-rows-W.LSP","cmd":"get-area-rows-w","cat":"面積/數量統計","desc":"讀取各形狀計算式圖塊，輸出多列面積計算式並以圖塊標示（無面積時用 no-area 圖塊），含取消還原。","usage":"執行 get-area-rows-w → 框選計算式圖塊 → 指定文字放置點 → 輸出多列計算式與標示圖塊","level":6,"lt":"✅","ver":"2018.03.04 / 20250614 換成圖塊","author":"Design By Cheng Shun-Yi","video":"https://youtu.be/-lsUl3oYkWg","fas":"fas/get-area-rows-W.fas"},{"no":817,"file":"GET-BL-ATT-R.lsp","cmd":"GET-BL-ATT-R","cat":"轉檔/匯出入","desc":"選取一個屬性圖塊，搜尋全圖同名圖塊，將所有屬性值匯出到 Excel（含標題格式），無法連線 Excel 時自動改輸出 CSV。","usage":"執行 GET-BL-ATT-R → 選取參考屬性圖塊 → 自動搜尋同名圖塊 → 匯出 Excel 或 CSV","level":8,"lt":"⚠️","ver":"2026-01-09(檔案日期)","author":"—","video":"","fas":"fas/GET-BL-ATT-R.fas"},{"no":818,"file":"GET-BL-ATT.LSP","cmd":"GET-BL-ATT","cat":"轉檔/匯出入","desc":"選取一個屬性圖塊後，把全圖同名圖塊的屬性值匯出到 Excel 活頁簿並設定儲存格格式。","usage":"執行 GET-BL-ATT → 選取圖塊 → 自動開啟 Excel → 寫入屬性資料","level":8,"lt":"❌","ver":"2009.09.09","author":"Shun_Yi Information Studio","video":"","fas":"fas/GET-BL-ATT.fas"},{"no":819,"file":"get-blk-ent-mid-wcs.lsp","cmd":"get-blk-ent-mid-wcs","cat":"查詢","desc":"取得圖塊內巢狀聚合線線段的中點世界座標並繪出對應線段，可再旋轉（程式疑似未完成）。","usage":"執行 get-blk-ent-mid-wcs → 點選圖塊內的聚合線線段 → 取得中點 WCS → 繪線","level":4,"lt":"✅","ver":"2025-03-18(檔案日期)","author":"—","video":"","fas":"fas/get-blk-ent-mid-wcs.fas"},{"no":820,"file":"get-blk-lay-list.LSP","cmd":"get-blk-lay-list","cat":"圖層","desc":"掃描圖面所有圖塊，回傳圖塊所在圖層清單，圖面無圖塊時提示。","usage":"執行 get-blk-lay-list → 自動掃描 → 顯示圖塊所在圖層清單","level":3,"lt":"✅","ver":"20240404","author":"chengshunyi","video":"","fas":"fas/get-blk-lay-list.fas"},{"no":821,"file":"get-blks-lay.lsp","cmd":"get-blks-lay-lst2、get-blks-lay-lst","cat":"圖層","desc":"取出圖面所有圖塊所在圖層並串成字串，供後續開關圖層使用，兩個指令為不同輸出版本。","usage":"執行 get-blks-lay-lst → 自動掃描全圖圖塊 → 回傳圖層名稱字串","level":3,"lt":"✅","ver":"20250219","author":"chengshunyi（含 Lee Mac 副程式）","video":"","fas":"fas/get-blks-lay.fas"},{"no":822,"file":"get-boundingbox.lsp","cmd":"test","cat":"查詢","desc":"以 Lee Mac 的邊界框函式取得選取物件的矩形外框，並在圖面建立對應的聚合線與點。","usage":"執行 test → 選取物件 → 於圖面產生外框聚合線","level":4,"lt":"✅","ver":"2024-02-07(檔案日期)","author":"Lee Mac","video":"","fas":"fas/get-boundingbox.fas"},{"no":823,"file":"get-CSV-to-table.LSP","cmd":"get-CSV-to-table","cat":"轉檔/匯出入","desc":"讀取 CSV 檔，以 DCL 設定文字高度、欄寬與列高，在圖面建立原生 AutoCAD 表格並置中填入資料。","usage":"執行 get-CSV-to-table → 於對話框設定文字高/欄寬/列高 → 選擇 CSV 檔 → 指定表格插入點","level":6,"lt":"✅","ver":"2026-08-29(檔案日期)","author":"ChengBar (MyCAD Studio)","video":"","fas":"fas/get-CSV-to-table.fas"},{"no":824,"file":"get-dd-b-w.lsp","cmd":"get-dd-b-w","cat":"面積/數量統計","desc":"讀取步行距離動態圖塊（步行距離-01 至 -10），整理距離值並以列式計算式標註於圖面。","usage":"執行 get-dd-b-w → 框選步行距離圖塊 → 指定文字放置點 → 輸出計算式","level":5,"lt":"✅","ver":"20211002","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/get-dd-b-w.fas"},{"no":825,"file":"get-dwgs-units.lsp","cmd":"get-dwgs-units","cat":"查詢","desc":"取得目前圖檔的插入單位與系統預設單位（公制/英制），並顯示在命令列。","usage":"執行 get-dwgs-units → 自動顯示圖檔單位與系統單位","level":3,"lt":"✅","ver":"20240825","author":"chengshunyi","video":"","fas":"fas/get-dwgs-units.fas"},{"no":826,"file":"get-excel-to-table.lsp","cmd":"get-excel-to-table","cat":"轉檔/匯出入","desc":"讀取已開啟 Excel 工作表的整個資料區，在圖面建立 AutoCAD 表格，標題在 A1、第 2 列為表頭。","usage":"執行 get-excel-to-table → 開啟 Excel 檔 → 指定表格插入點 → 建立表格","level":8,"lt":"❌","ver":"2022-08 (AlanH) / 20220716更新","author":"AlanH、Terry Miller (GetExcel)、Gilles Chanteau","video":"","fas":"fas/get-excel-to-table.fas"},{"no":827,"file":"get-hatch-area.lsp","cmd":"get-hatch-area","cat":"轉檔/匯出入","desc":"選取多個 HATCH 取得面積，並匯出到 Excel 儲存格列表。","usage":"執行 get-hatch-area → 框選 HATCH → 自動開啟 Excel → 寫入面積","level":8,"lt":"❌","ver":"2008.06.24","author":"Shun_Yi Studio","video":"","fas":"fas/get-hatch-area.fas"},{"no":828,"file":"get-hatch-center-p.lsp","cmd":"get-hatch-center-p","cat":"繪圖","desc":"取得選取 HATCH 的中心位置並在該處建立點物件。","usage":"執行 get-hatch-center-p → 選取 HATCH → 於中心建立 POINT","level":3,"lt":"✅","ver":"20221031","author":"cheng_shun_yi","video":"","fas":"fas/get-hatch-center-p.fas"},{"no":829,"file":"get-hatch-center-t.LSP","cmd":"get-hatch-center-t","cat":"文字","desc":"選取矩形範圍後縮放視圖並在其中心建立文字（程式內容很短，用途由指令推測）。","usage":"執行 get-hatch-center-t → 選取矩形 → 於中心產生文字","level":3,"lt":"✅","ver":"20221031","author":"cheng_shun_yi","video":"","fas":"fas/get-hatch-center-t.fas"},{"no":830,"file":"Get-pus-dic.lsp","cmd":"Get-pus-dic","cat":"圖面管理","desc":"讀取圖紙大小、單位、比例與單位/長度/面積換算係數的設定，並顯示在狀態列。","usage":"執行 Get-pus-dic → 自動讀取圖紙單位比例設定 → 狀態列顯示係數","level":3,"lt":"✅","ver":"20230812","author":"chengshunyi","video":"","fas":"fas/Get-pus-dic.fas"},{"no":831,"file":"Get-pus.lsp","cmd":"Get-pus、ACADMODE","cat":"圖面管理","desc":"讀取圖紙單位比例系數（單位、長度、面積）並顯示於狀態列，ACADMODE 則還原一般 AutoCAD 狀態列顯示。","usage":"執行 Get-pus → 狀態列顯示單位/長度/面積係數；執行 ACADMODE 還原狀態列","level":3,"lt":"✅","ver":"20230521","author":"chengshunyi","video":"","fas":"fas/Get-pus.fas"},{"no":832,"file":"get-tree.lsp","cmd":"get-tree","cat":"轉檔/匯出入","desc":"選取樹木圖塊，統計全圖各樹種（不分圖層）棵數並匯出到 Excel。","usage":"執行 get-tree → 選取樹木圖塊 → 統計同名圖塊 → 寫入 Excel","level":8,"lt":"❌","ver":"2008.06.25","author":"—","video":"","fas":"fas/get-tree.fas"},{"no":833,"file":"get-wdim-2-list-C.lsp","cmd":"get-wdim-2-list-C","cat":"標註","desc":"選取步行距離標註，依每個標註自己的精度四捨五入，彙總成列式計算式與合計，並以 DCL 指定輸出圖層與文字型式。","usage":"執行 get-wdim-2-list-C → 於對話框選圖層/文字型式 → 選取標註 → 指定位置 → 輸出計算式","level":6,"lt":"✅","ver":"2026-05-02(檔案日期)","author":"MyCAD","video":"","fas":"fas/get-wdim-2-list-C.fas"},{"no":834,"file":"get-wdim-2-list-C1.lsp","cmd":"get-wdim-2-list-C1","cat":"標註","desc":"步行距離標註彙總 C1 版，自動依各標註精度計算，並依標籤排序，另獨立統計重複步行距離。","usage":"執行 get-wdim-2-list-C1 → 對話框選圖層/文字型式 → 選取標註 → 指定位置 → 輸出總計與重複步行距離","level":6,"lt":"✅","ver":"2026-05-02(檔案日期)","author":"MyCAD","video":"","fas":"fas/get-wdim-2-list-C1.fas"},{"no":835,"file":"get-wdim-2-list-C2.lsp","cmd":"get-wdim-2-list-C2","cat":"標註","desc":"步行距離標註彙總 C2 版，依標籤首字（A、B、C…）分群，各群分別輸出總計與重複步行距離列式。","usage":"執行 get-wdim-2-list-C2 → 對話框選圖層/文字型式 → 選取標註 → 指定位置 → 依群組輸出計算式","level":7,"lt":"✅","ver":"2026-05-02(檔案日期)","author":"MyCAD","video":"","fas":"fas/get-wdim-2-list-C2.fas"},{"no":836,"file":"get-wdim-2-list-C3-D.lsp","cmd":"get-wdim-2-list-C3-d","cat":"標註","desc":"步行距離列計算式的大型整合版，含圖紙尺寸、比例單位、不檢討步距與重複步行選項，DCL 設定後標註計算式與欄位。","usage":"執行 get-wdim-2-list-C3-d → 於對話框設定步行距離參數/單位/文字 → 選取標註 → 指定位置 → 輸出計算式","level":9,"lt":"✅","ver":"20231121 / 20230128","author":"chengshunyi","video":"https://youtu.be/8zKQo0rqxx0","fas":"fas/get-wdim-2-list-C3-D.fas"},{"no":837,"file":"get-wdim-2-list-C3.lsp","cmd":"get-wdim-2-list-C3","cat":"標註","desc":"步行距離列計算式 C3 版，以 DCL 設定步行距離分類與文字，依標籤排序並判斷重複步行距離，輸出計算式。","usage":"執行 get-wdim-2-list-C3 → 於對話框設定參數 → 選取標註 → 指定位置 → 輸出計算式","level":7,"lt":"✅","ver":"20230128 / 20230423","author":"chengshunyi","video":"","fas":"fas/get-wdim-2-list-C3.fas"},{"no":838,"file":"get-wdim-2-list-N.lsp","cmd":"get-wdim-2-list-N","cat":"標註","desc":"過濾特定圖層的尺寸標註，依編號排序、四捨五入後組成步行距離計算式文字。","usage":"執行 get-wdim-2-list-N → 自動選取標註 → 指定文字位置 → 輸出計算式","level":4,"lt":"✅","ver":"20230110","author":"chengshunyi","video":"","fas":"fas/get-wdim-2-list-N.fas"},{"no":839,"file":"get-wdim-2-list.lsp","cmd":"get-wdim-2-list","cat":"標註","desc":"過濾指定圖層與樣式的尺寸標註，依編號排序並四捨五入，將公分換算成公尺後組成步行距離列式計算式文字，並建立 MY-TEXT 文字樣式。","usage":"執行 get-wdim-2-list → 自動選取標註 → 指定文字位置 → 輸出計算式","level":5,"lt":"✅","ver":"202300903（應為 20230903）","author":"chengshunyi","video":"","fas":"fas/get-wdim-2-list.fas"},{"no":840,"file":"get-xref-AL.lsp","cmd":"XRA、XRLA","cat":"圖層","desc":"點選外部參考或圖塊內的物件，取得其圖層名稱（外參圖層需去除 | 前綴），供外參填充面積寫入圖塊屬性使用。","usage":"執行 XRA 或 XRLA → 選取物件 → 命令列顯示圖層名稱","level":4,"lt":"✅","ver":"20240215","author":"chengshunyi（含 Lee Mac 副程式）","video":"","fas":""},{"no":841,"file":"get-xref-hatch-area-blk.lsp","cmd":"get-xref-hatch-area-blk","cat":"圖塊/屬性","desc":"選取外參內的填充線或物件提取面積與圖層，選擇插入 G-AREA-ML3T 標籤圖塊或更新既有標籤屬性，可連續執行並記憶上次模式。","usage":"執行 get-xref-hatch-area-blk → 選擇 插入(I)/更新(U) → 選取填充線 → 指定插入點或選取既有標籤 → 連續執行至按 Enter","level":6,"lt":"✅","ver":"2026-02-04(檔案日期)","author":"—","video":"","fas":"fas/get-xref-hatch-area-blk.fas"},{"no":842,"file":"get-xref-hatch-area2att.lsp","cmd":"get-xref-hatch-area2att","cat":"圖塊/屬性","desc":"選取外參內的 hatch 或聚合線，將其圖層名稱與面積（公式欄位）填入圖塊的第一、第二屬性，外參變動時不會連動。","usage":"執行 get-xref-hatch-area2att → 選取 hatch/pline → 選取目標圖塊 → 自動填入圖層與面積屬性","level":5,"lt":"✅","ver":"20240215","author":"chengshunyi","video":"","fas":"fas/get-xref-hatch-area2att.fas"},{"no":843,"file":"get-xref-hatch-area2tag.LSP","cmd":"get-xref-hatch-area2tag","cat":"圖塊/屬性","desc":"選取外參內的 Hatch 或聚合線，取得純文字面積（mm2 換算 m2）與圖層名稱，填入所選圖塊的 LAYER 與 AREA 屬性。","usage":"執行 get-xref-hatch-area2tag → 選取外參 Hatch/Polyline → 選取目標圖塊 → 自動寫入屬性","level":5,"lt":"✅","ver":"2026-02-03(檔案日期)","author":"—（含 Lee Mac 副程式）","video":"","fas":"fas/get-xref-hatch-area2tag.fas"},{"no":844,"file":"get-xref-line-coord.lsp","cmd":"get-xref-line-coord、get-xref-pline-coord、get-xref-pline-seg-coord","cat":"查詢","desc":"選取巢狀於圖塊或外參內的直線，在其端點產生點物件；另兩個指令對巢狀聚合線的頂點或線段取座標。","usage":"執行 get-xref-line-coord → 選取巢狀直線 → 於端點建立 POINT（pline 版選聚合線）","level":4,"lt":"✅","ver":"2025-07-05(檔案日期)","author":"Lee Mac 範例改寫","video":"","fas":"fas/get-xref-line-coord.fas"},{"no":845,"file":"GetBlockAttrs.lsp","cmd":"GetBlockAttrs","cat":"轉檔/匯出入","desc":"選取動態圖塊後提取同名圖塊的屬性值（可多選 Tag），或過濾排序圖面文字去除重複，輸出到圖面、TXT 或 CSV。","usage":"執行 GetBlockAttrs → 點選圖塊 → 於對話框選 Tag 或手動選取文字 → 選擇輸出模式（圖面/TXT/CSV） → 完成輸出","level":7,"lt":"✅","ver":"V1.2 2026/05/01","author":"Gemini AI Assistant","video":"","fas":"fas/GetBlockAttrs.fas"},{"no":846,"file":"getblocktitlename .LSP","cmd":"getblocktitlename","cat":"圖面管理","desc":"讀取圖框圖塊（NA-DWG2）中的圖名屬性，將特殊字元換成底線後，以該名稱另存圖檔。","usage":"執行 getblocktitlename → 自動讀取圖框圖名屬性 → 另存新檔","level":3,"lt":"✅","ver":"20200303","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/getblocktitlename .fas"},{"no":847,"file":"GetExcel.LSP","cmd":"（無，副程式庫）","cat":"轉檔/匯出入","desc":"Terry Miller 的 Excel 函式庫，提供讀寫 Excel 儲存格、欄列轉換、匯入範圍到圖面等副程式。","usage":"由其他程式呼叫，例如 (GetExcel 檔案路徑) 取得儲存格資料","level":8,"lt":"❌","ver":"GetExcel R10（原始 9-20-03）","author":"Terry Miller (autolisp-exchange.com)、Gilles Chanteau","video":"","fas":"fas/GetExcel.fas"},{"no":848,"file":"GetIcon.LSP","cmd":"ShowIcons、GetIcon、GetButtons、GetPT、Vector_Circle","cat":"其他","desc":"Terry Miller 的對話框函式庫，依字串寬度即時產生 DCL，顯示帶圖示（警告、問號、笑臉等）的訊息、選項與輸入視窗。","usage":"由其他程式呼叫 GetIcon/GetButtons 等函式，或執行 ShowIcons 預覽圖示","level":8,"lt":"✅","ver":"GetIcon R8（原始 4-1-00）","author":"Terry Miller (autolisp-exchange.com)","video":"","fas":"fas/GetIcon.fas"},{"no":849,"file":"getMac.lsp","cmd":"getMac","cat":"系統/授權","desc":"透過 WMI 查詢本機網路卡設定，取得 IP 位址（程式名稱為 getMac，可能用於授權識別）。","usage":"執行 getMac → 自動查詢並回傳網路位址","level":5,"lt":"❌","ver":"2025-01-18(檔案日期)","author":"—","video":"","fas":""},{"no":850,"file":"Getvals4-drawline.LSP","cmd":"（無，副程式庫）","cat":"繪圖","desc":"Alan H 的四欄位輸入對話框函式，加入點選功能，輸入總長、垂直與水平偏移與線數後以 ARRAY/COPY 繪製多條偏移線。","usage":"由程式呼叫 (ah:getval4 ...) → 於對話框輸入長度/偏移/數量 → 指定點 → 繪製多條線","level":6,"lt":"✅","ver":"20250119","author":"Alan H (Feb 2018) / chengshunyi 改","video":"","fas":"fas/Getvals4-drawline.fas"},{"no":851,"file":"Getvals4.lsp","cmd":"（無，副程式庫）","cat":"其他","desc":"Alan H 的四欄位輸入對話框函式庫（ah:getval4），回傳四個字串值，範例用於多線偏移複製。","usage":"由程式呼叫 (ah:getval4 標題 寬度 位數 預設值 ...) → 對話框輸入 → 取得結果","level":6,"lt":"✅","ver":"Feb 2018","author":"Alan H","video":"","fas":"fas/Getvals4.fas"},{"no":852,"file":"GetVectors.lsp","cmd":"GV、GetVectors、VV、ViewVectors、IA、ImageAtts、PI、Palet","cat":"其他","desc":"Terry Miller 的 DCL 圖像製作工具，把選取圖形分解成線段並輸出成對話框圖像向量碼，另含檢視向量、圖像屬性與色盤預覽。","usage":"執行 GV → 選取圖形並設定參數 → 輸出 C:\\Temp\\Vectors.lsp → 以 VV 檢視向量圖像；Palet 檢視 255 色","level":8,"lt":"✅","ver":"GetVectors R5（原始 12-7-01，11-1-22 修訂）","author":"Terry Miller (autolisp-exchange.com)","video":"","fas":"fas/GetVectors.fas"},{"no":853,"file":"gmat.lsp","cmd":"gmat","cat":"圖塊/屬性","desc":"以 DCL 設定前置碼、編碼長度與排序方式，收集同名圖塊的插入點並依序寫入屬性編號。","usage":"執行 gmat → 於對話框設定前置碼/編碼長度/排序方式 → 確定 → 自動編號圖塊屬性","level":6,"lt":"✅","ver":"2025-07-16(檔案日期)","author":"—","video":"","fas":"fas/gmat.fas"},{"no":854,"file":"green-c-lays.lsp","cmd":"green-c-lays","cat":"圖層","desc":"檢查並建立綠化與鋪面圖層（如 S1-樹蘭、S2-春不老、P1-高壓水泥磚、P2-天然崗石），已存在則略過。","usage":"執行 green-c-lays → 自動檢查並建立圖層","level":3,"lt":"✅","ver":"20241006","author":"chengshunyi","video":"","fas":"fas/green-c-lays.fas"},{"no":855,"file":"GRID-1.LSP","cmd":"grid-1","cat":"繪圖","desc":"指定軸線兩端點後在 DIM-INT 圖層畫線，並輸入軸線編號插入軸線符號圖塊（grid-1 樣式）。","usage":"執行 grid-1 → 指定 A 點 → 指定 B 點 → 輸入軸線編號 → 完成軸線與符號","level":2,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/GRID-1.fas"},{"no":856,"file":"GRID-2.LSP","cmd":"grid-2","cat":"繪圖","desc":"指定軸線兩端點後在 DIM-INT 圖層畫線，並輸入軸線編號插入軸線符號圖塊（grid-2 樣式）。","usage":"執行 grid-2 → 指定 A 點 → 指定 B 點 → 輸入軸線編號 → 完成軸線與符號","level":2,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/GRID-2.fas"},{"no":857,"file":"GRID-COL.LSP","cmd":"grid-col","cat":"繪圖","desc":"以 DCL 輸入 X、Y 方向間距與數量及圖塊尺寸，自動繪製柱網格線與軸線編號符號。","usage":"執行 grid-col → 於對話框輸入 X/Y 間距與數量、尺寸 → 指定基準點 → 產生軸線網格","level":6,"lt":"✅","ver":"84.5.31、84.7.5、84.9.25（民國年）","author":"—","video":"","fas":"fas/GRID-COL.fas"},{"no":858,"file":"grid-int-blkxy.lsp","cmd":"grid-int-blkxy、inter","cat":"標註","desc":"取兩條軸線或柱邊的交點，在交點插入座標圖塊（GRID-X）並寫入該點座標屬性，可搭配 NCOPY 取巢狀物件。","usage":"執行 grid-int-blkxy → 選取第一個物件 → 選取第二個物件 → 於交點自動放置座標圖塊","level":5,"lt":"✅","ver":"20250103","author":"chengshunyi（含 Lee Mac 副程式）","video":"","fas":"fas/grid-int-blkxy.fas"},{"no":859,"file":"GRIP_STRETCH_update.lsp","cmd":"（無，副程式庫）","cat":"其他","desc":"建立 reactor 於夾點拉伸（GRIP_STRETCH）後自動執行 Field 更新，讓欄位文字隨圖形變動即時刷新。","usage":"載入後自動啟用 → 以夾點拉伸物件 → 欄位自動更新","level":8,"lt":"✅","ver":"2025-10-12(檔案日期)","author":"—","video":"","fas":"fas/GRIP_STRETCH_update.fas"},{"no":860,"file":"groupattcounter-ui.lsp","cmd":"groupattcounter-ui","cat":"面積/數量統計","desc":"點選圖塊後以 DCL 選擇屬性 Tag 與分組依據，統計同名圖塊屬性值的群組數量，可上下移動排序並複製結果。","usage":"執行 groupattcounter-ui → 點選圖塊 → 於對話框選擇分組 Tag 與統計目標 Tag → 複製全部/選取 → 貼到圖面或表格","level":7,"lt":"✅","ver":"2026-10-17(檔案日期)","author":"MyCAD","video":"","fas":"fas/groupattcounter-ui.fas"},{"no":861,"file":"groupbykey.lsp","cmd":"（無，副程式庫）","cat":"其他","desc":"把以標籤為首的資料串列依 key（如 A1、A2）分組整理，檔內附步行距離資料範例，為列式計算輔助函式。","usage":"由其他程式呼叫分組函式，無獨立指令","level":3,"lt":"✅","ver":"2023-04-22(檔案日期)","author":"—","video":"","fas":"fas/groupbykey.fas"},{"no":862,"file":"GRPTank.LSP","cmd":"GRPTank","cat":"繪圖","desc":"GRP 模組化水箱室外設計繪圖工具：DCL 輸入水箱參數，自動繪製平面、前立面、縱橫剖面圖並標註尺寸，修正 GL 高程並輸出箱體單元板片統計計算書。","usage":"執行 GRPTank → 於對話框輸入水箱尺寸/參數 → 指定繪圖位置 → 自動繪製四視圖與標註 → 產生計算書","level":7,"lt":"✅","ver":"2026-03-30(檔案日期)","author":"強恩企業客製","video":"","fas":"fas/GRPTank.fas"},{"no":863,"file":"gtht.LSP","cmd":"gtht","cat":"文字","desc":"輸入文字高度後，將全圖所有 TEXT 與 MTEXT 一次改成該字高。","usage":"執行 gtht → 輸入文字高度 → 全圖文字自動改字高","level":2,"lt":"✅","ver":"2022-01-18(檔案日期)","author":"—","video":"","fas":"fas/gtht.fas"},{"no":864,"file":"H2-ARCONC.lsp","cmd":"H2-ARCONC","cat":"修改","desc":"將選取的 HATCH 改成 AR-CONC 混凝土圖案，圖層設為 L-HATCH（無則建立），圖案比例依圖紙比例（1/50 分界）自動調整。","usage":"執行 H2-ARCONC → 選取 HATCH → 自動換成 AR-CONC 並改圖層與比例","level":4,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/H2-ARCONC.fas"},{"no":865,"file":"H2-arsand.lsp","cmd":"H2-arsand","cat":"修改","desc":"將選取的 HATCH 改成 ar-sand 點型剖面符號，圖層設為 D-HATCH（無則建立），並依 LTSCALE 調整比例。","usage":"執行 H2-arsand → 選取 HATCH → 自動換成 ar-sand 並改圖層與比例","level":3,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/H2-arsand.fas"},{"no":866,"file":"H2-BRICK.lsp","cmd":"H2-BRICK","cat":"修改","desc":"將選取的 HATCH 改成磚牆線型剖面符號，圖層設為 L-HATCH（無則建立），並依 LTSCALE 調整比例。","usage":"執行 H2-BRICK → 選取 HATCH → 自動改圖案、圖層與比例","level":3,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/H2-BRICK.fas"},{"no":867,"file":"H2-earth.lsp","cmd":"H2-EARTH","cat":"修改","desc":"將選取的 HATCH 改成 EARTH 土壤剖面符號，圖層設為 L-HATCH（無則建立），並依 LTSCALE 調整比例。","usage":"執行 H2-EARTH → 選取 HATCH → 自動換成 EARTH 並改圖層與比例","level":3,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/H2-earth.fas"},{"no":868,"file":"H2-GRAVEL.lsp","cmd":"H2-GRAVEL","cat":"修改","desc":"將選取的 HATCH 改成 GRAVEL 碎石剖面符號，圖層設為 L-HATCH（無則建立），並依 LTSCALE 調整比例。","usage":"執行 H2-GRAVEL → 選取 HATCH → 自動換成 GRAVEL 並改圖層與比例","level":3,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/H2-GRAVEL.fas"},{"no":869,"file":"H2-plast.lsp","cmd":"H2-plast","cat":"修改","desc":"將選取的 HATCH 改成 plast 粉刷剖面符號，圖層設為 L-HATCH（無則建立），並依 LTSCALE 調整比例。","usage":"執行 H2-plast → 選取 HATCH → 自動換成 plast 並改圖層與比例","level":3,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/H2-plast.fas"},{"no":870,"file":"H2-RC.lsp","cmd":"H2-RC","cat":"修改","desc":"將選取的 HATCH 改成 AR-CONC-T 鋼筋混凝土剖面符號，圖層設為 L-HATCH，並依圖紙單位比例設定調整圖案比例。","usage":"執行 H2-RC → 選取 HATCH → 自動換圖案並改圖層與比例","level":4,"lt":"✅","ver":"20240105","author":"—","video":"","fas":"fas/H2-RC.fas"},{"no":871,"file":"H2-solid.lsp","cmd":"H2-solid","cat":"修改","desc":"將選取的 HATCH 改成 solid 實心填滿（RC 牆塗黑），圖層設為 RCW-HATCH，並設定透明度 50。","usage":"執行 H2-solid → 選取 HATCH → 自動改為 solid、圖層與透明度","level":3,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/H2-solid.fas"},{"no":872,"file":"H2-steel.lsp","cmd":"H2-steel","cat":"修改","desc":"將選取的 HATCH 改成 steel 鋼材剖面符號，圖層設為 L-HATCH（無則建立），並依 LTSCALE 調整比例。","usage":"執行 H2-steel → 選取 HATCH → 自動換成 steel 並改圖層與比例","level":3,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/H2-steel.fas"},{"no":873,"file":"H2-STONE.lsp","cmd":"H2-STONE","cat":"修改","desc":"將選取的 HATCH 改成 ANSI33 石材剖面符號，圖層設為 L-HATCH（無則建立），並依 LTSCALE 調整比例。","usage":"執行 H2-STONE → 選取 HATCH → 自動換成 ANSI33 並改圖層與比例","level":3,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/H2-STONE.fas"},{"no":874,"file":"H2-TM.lsp","cmd":"H2-TM","cat":"修改","desc":"將選取的 HATCH 改為 45 度斜線剖面符號，圖層設為 L-HATCH，並依公制/英制換算間距。","usage":"執行 H2-TM → 選取 HATCH → 自動改角度、間距、圖層","level":3,"lt":"✅","ver":"20220716更新 / 20260201","author":"—","video":"","fas":"fas/H2-TM.fas"},{"no":875,"file":"H2BF.lsp","cmd":"FS-H2B_w、FS-H2B_all、FS-H2F_w、FS-H2F_all、H2B_w、H2B_all、H2F_w、H2F_all","cat":"修改","desc":"調整 HATCH 的顯示順序：H2B 把填充線送到最下方、H2F 置於最上方，_w 為框選範圍、_all 為全圖，FS- 開頭版本另做縮放全圖與存檔。","usage":"執行 H2B_w（或 H2F_w）→ 框選範圍 → 填充線置底/置頂；全圖版直接執行 H2B_all/H2F_all","level":3,"lt":"✅","ver":"20211016","author":"CHENG-BAR","video":"","fas":"fas/H2BF.fas"},{"no":876,"file":"hatch-area-la-pt.LSP","cmd":"hatch-area-la-pt","cat":"面積/數量統計","desc":"選取 HATCH 後依填充圖案或圖層分類，累計該類別所有填充線的面積並顯示。","usage":"執行 hatch-area-la-pt → 選擇依圖案(Pattern)或圖層(Layer) → 選取 HATCH → 顯示面積","level":4,"lt":"✅","ver":"20230412","author":"chengshunyi","video":"","fas":"fas/hatch-area-la-pt.fas"},{"no":877,"file":"Hatch-Bldg.lsp","cmd":"Hatch-Bldg、HB","cat":"繪圖","desc":"沿建物外輪廓聚合線向內偏移固定寬度，產生 ANSI31 斜線填充，並依線段方向調整填充角度與依註解比例設定比例。","usage":"執行 Hatch-Bldg 或 HB → 選取建物聚合線 → 指定偏移方向/寬度 → 自動產生輪廓填充","level":5,"lt":"✅","ver":"v1.3（20240919）","author":"John F. Uhden (HatchBldg)、chengshunyi","video":"","fas":"fas/Hatch-Bldg.fas"},{"no":878,"file":"Hatch-bt-2pline.lsp","cmd":"Hatch-bt-2pline","cat":"繪圖","desc":"選取兩條相交的聚合線（至少兩個交點），在兩者之間的區域建立 SOLID 或線性填充並調整繪製順序。","usage":"執行 Hatch-bt-2pline → 選第一條聚合線 → 選第二條聚合線 → 自動建立中間填充","level":7,"lt":"✅","ver":"2013-09-15 (檔案無日期，20220716更新)","author":"Gian Paolo Cattaneo、Marko Ribar","video":"","fas":"fas/Hatch-bt-2pline.fas"},{"no":879,"file":"Hatch-bt-2plines.lsp","cmd":"hatch-bt-2plines","cat":"繪圖","desc":"取兩條聚合線頂點串列，依左右關係重新組合成封閉聚合線（供兩線之間填充用）。","usage":"執行 hatch-bt-2plines → 選取兩條聚合線 → 自動組合封閉聚合線","level":4,"lt":"✅","ver":"2022-12-31(檔案日期)","author":"—","video":"","fas":"fas/Hatch-bt-2plines.fas"},{"no":880,"file":"Hatch-bt-2pliness.lsp","cmd":"Hatch-bt-2pliness","cat":"繪圖","desc":"剖面圖用，選取兩條聚合線，以其頂點組成封閉區域並在 RCW-HATCH 圖層建立 solid 填充。","usage":"執行 Hatch-bt-2pliness → 選第一條聚合線 → 選第二條聚合線 → 自動建立 solid 填充","level":5,"lt":"✅","ver":"20221231","author":"chengshunyi","video":"","fas":"fas/Hatch-bt-2pliness.fas"},{"no":881,"file":"Hatch-bt-2plinesss.lsp","cmd":"Hatch-bt-2plinesss","cat":"繪圖","desc":"剖面圖用，兩條聚合線之間建立 solid 填充，新增 *error* 防呆與圖層、HPNAME 設定還原。","usage":"執行 Hatch-bt-2plinesss → 選第一條聚合線 → 選第二條聚合線 → 自動建立 solid 填充","level":5,"lt":"✅","ver":"20240907","author":"chengshunyi","video":"","fas":"fas/Hatch-bt-2plinesss.fas"},{"no":882,"file":"hatch-copy-to.LSP","cmd":"hatch-copy-to","cat":"修改","desc":"點選來源填充線，將其圖案名稱等特性套用到其他選取的填充線（以 entmod 修改圖案名稱）。","usage":"執行 hatch-copy-to → 選取來源 hatch → 選取目標 hatch → 套用相同圖案","level":4,"lt":"✅","ver":"RJP 2022-09-08","author":"RJP","video":"","fas":"fas/hatch-copy-to.fas"},{"no":883,"file":"Hatch-e-w2patterns.LSP","cmd":"Hatch-e-w2patterns","cat":"繪圖","desc":"對封閉物件同時以兩種圖案（AR-CONC 與 PLAST）填充，用於 1:50 至 1:10 大樣圖，並自動建立 hatch-L、hatch-D 圖層。","usage":"執行 Hatch-e-w2patterns → 選取封閉物件 → 自動雙圖案填充","level":5,"lt":"✅","ver":"20221203","author":"chengshunyi","video":"","fas":"fas/Hatch-e-w2patterns.fas"},{"no":884,"file":"hatch-lay-area.lsp","cmd":"hatch-lay-area-Y、pline-lay-area-Y、hatch-lay-area-N、pline-lay-area-N、hatch-lay-area","cat":"面積/數量統計","desc":"選取填充線或聚合線，依圖層或填充型式分類計算面積並標註，Y 版使用關聯欄位，N 版為純文字，另有互動選擇版。","usage":"執行 hatch-lay-area-Y（或其他變體）→ 選擇分類方式 [圖層/型式] → 選取物件 → 指定文字標註起點 → 輸出分類面積與總計","level":6,"lt":"✅","ver":"2026-10-17(檔案日期)","author":"—","video":"","fas":"fas/hatch-lay-area.fas"},{"no":885,"file":"hatch-pl.lsp","cmd":"hatch-pl","cat":"繪圖","desc":"連續選取聚合線並在 Duct-HA 圖層以 ANSI37 圖案建立填充，無效物件會提示重選。","usage":"執行 hatch-pl → 選取聚合線 → 自動填充 → 連續選取至結束","level":5,"lt":"✅","ver":"20250721","author":"chengshunyi（含 Lee Mac 副程式）","video":"","fas":"fas/hatch-pl.fas"},{"no":886,"file":"hatch-point-pline.LSP","cmd":"hatch-point-pline","cat":"繪圖","desc":"點選內部點，找出包含該點的封閉聚合線並以 ANSI31 建立填充。","usage":"執行 hatch-point-pline → 點選內部點 → 自動以封閉聚合線填充","level":4,"lt":"❌","ver":"20221231","author":"chengshunyi","video":"","fas":"fas/hatch-point-pline.fas"},{"no":887,"file":"hatch-rc.LSP","cmd":"hatch-rc","cat":"繪圖","desc":"保存圖層狀態並開啟 RC 圖層，點選內部點以 SOLID 填充並放到最下方，完成後還原相關系統變數。","usage":"執行 hatch-rc → 點選內部點 → 在 RC-HATCH 圖層建立 solid 填充並置底","level":4,"lt":"✅","ver":"20220507","author":"—","video":"","fas":"fas/hatch-rc.fas"},{"no":888,"file":"hatch2bottom.lsp","cmd":"hatch2bottom","cat":"修改","desc":"以 Lee Mac 繪製順序函式（置頂、置底、移到某物件上方）將全圖 HATCH 移到繪製順序最下方。","usage":"執行 hatch2bottom → 自動將所有 HATCH 置底","level":5,"lt":"✅","ver":"2022-09-06(檔案日期)","author":"Lee Mac 副程式","video":"","fas":"fas/hatch2bottom.fas"},{"no":889,"file":"HatchInfo-AP.lsp","cmd":"HatchInfo-AP","cat":"面積/數量統計","desc":"以 DCL 設定單位與比例，選取聚合線標註面積與周長，自動建立 JhengHei 文字樣式與 INFO 圖層，並可插入圖塊與標註。","usage":"執行 HatchInfo-AP → 於對話框勾選標註面積/周長並設定單位、比例 → 選取聚合線 → 指定標註位置","level":8,"lt":"✅","ver":"2025-08-17(檔案日期)","author":"—","video":"","fas":"fas/HatchInfo-AP.fas"},{"no":890,"file":"HATCHLEGEND.LSP","cmd":"HATCHLEGEND","cat":"面積/數量統計","desc":"掃描圖面所有 HATCH，依圖層彙整面積，指定起點後逐層產生圖例方框、圖層名稱與面積文字。","usage":"執行 HATCHLEGEND → 指定圖例插入起點 → 自動產生各圖層圖例與面積","level":5,"lt":"✅","ver":"2025-07-22(檔案日期)","author":"—","video":"","fas":"fas/HATCHLEGEND.fas"},{"no":891,"file":"HatchMaker.lsp","cmd":"DrawHatch、SaveHatch","cat":"繪圖","desc":"在 1x1 方格內用線與點繪製圖案，再存成自訂填充圖案檔（.pat），用於建立自製 Hatch 圖案。","usage":"執行 DrawHatch → 在 0,0 至 1,1 方格內以線/點繪製圖案 → 執行 SaveHatch → 輸入圖案名稱存檔","level":7,"lt":"✅","ver":"CADALYST 10/05 Tip 2065 (2005)","author":"Lanny Schiele (TMI Systems Design)","video":"","fas":"fas/HatchMaker.fas"},{"no":892,"file":"hatchor.LSP","cmd":"hatchor","cat":"修改","desc":"選取填充線後指定新的填充原點。","usage":"執行 hatchor → 選取 Hatch → 指定新的填充原點","level":1,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/hatchor.fas"},{"no":893,"file":"HatchRegions.lsp","cmd":"HatchRegions","cat":"繪圖","desc":"將選取的面域（REGION）以 ANSI31 建立填充，可選擇是否刪除原邊界。","usage":"執行 HatchRegions → 選取面域 → 自動填充 → 詢問是否刪除原邊界","level":2,"lt":"⚠️","ver":"20240329","author":"chengshunyi","video":"","fas":"fas/HatchRegions.fas"},{"no":894,"file":"hatchreport.lsp","cmd":"hatchreport","cat":"面積/數量統計","desc":"以 DCL 設定單位、比例與字高，統計全圖 HATCH 的面積與周長，插入 AutoCAD 表格並輸出 CSV，異常 Hatch 會亮顯。","usage":"執行 hatchreport → 於對話框設定單位/比例/字高 → 確定 → 指定表格插入點 → 產生報表","level":7,"lt":"✅","ver":"v2025.07.24","author":"ShunYi","video":"","fas":"fas/hatchreport.fas"},{"no":895,"file":"hatchsimplify.lsp","cmd":"hatchsimplify、FXHatch_Simplify","cat":"修改","desc":"優化 HATCH：將非關聯填充線產生邊界並轉成面域聯集後重建單一填充，沿用原填充特性（matchprop）。","usage":"執行 hatchsimplify → 選取填充線（或全圖掃描）→ 自動產生邊界、聯集並重建填充","level":6,"lt":"❌","ver":"20250724","author":"chengshunyi（FXHatch_Simplify）","video":"","fas":"fas/hatchsimplify.fas"},{"no":896,"file":"hatchwithin2lines.lsp","cmd":"hatchwithin2lines","cat":"繪圖","desc":"平面 RC 牆用，選取兩條線（非聚合線）後於其間建立 solid 填充，圖層為 RCW-hatch，並自動檢查建立圖層。","usage":"執行 hatchwithin2lines → 選取兩條牆線 → 自動建立 solid 填充","level":5,"lt":"✅","ver":"20221203","author":"chengshunyi","video":"","fas":"fas/hatchwithin2lines.fas"},{"no":897,"file":"HC-c-area.LSP","cmd":"HC-c-area-m、HC-c-area","cat":"面積/數量統計","desc":"統計 HATCH 面積並以動態圖塊與文字標示於圖面（自動建立 AREA-T 圖層與文字樣式），-m 版支援多選，另含 ZWCAD 判斷。","usage":"執行 HC-c-area（多選用 HC-c-area-m）→ 選取 HATCH → 指定標註位置 → 插入面積標註圖塊","level":7,"lt":"✅","ver":"20240501 / 20240721 增加多選","author":"chengshunyi","video":"","fas":"fas/HC-c-area.fas"},{"no":898,"file":"hh2.LSP","cmd":"hh2","cat":"繪圖","desc":"選取斜坡聚合線後輸入垂直偏移距離，沿斜坡線向下建立填充區域（坡下填充）。","usage":"執行 hh2 → 選取斜坡聚合線 → 輸入垂直偏移距離 → 自動建立填充","level":5,"lt":"✅","ver":"20221205","author":"chengshunyi","video":"","fas":"fas/hh2.fas"},{"no":899,"file":"hlight.LSP","cmd":"hlight、hlight2、hlight3","cat":"圖層","desc":"輸入圖層名稱後，將該圖層上的物件亮顯（高亮）顯示，三個指令為不同亮顯方式。","usage":"執行 hlight → 輸入要亮顯的圖層 → 游標移到物件上查看亮顯","level":4,"lt":"✅","ver":"20231117","author":"chengshunyi","video":"","fas":"fas/hlight.fas"},{"no":900,"file":"HPVarSetting.LSP","cmd":"HPVarSetting","cat":"系統/授權","desc":"以 DCL 一次設定填充與顯示效能相關系統變數（HPMAXLINES、HPQUICKPREVIEW、FACETRES、LWDISPLAY 等），並記憶使用者值。","usage":"執行 HPVarSetting → 於對話框調整各系統變數 → 確定 → 套用設定","level":6,"lt":"✅","ver":"2026-04-12(檔案日期)","author":"MyCAD","video":"","fas":""},{"no":901,"file":"hr-wall-fix.lsp","cmd":"hr-wall-fix-r、hr-wall-fix-c、hr-wall-fix、hr-wall-fix-ramp","cat":"繪圖","desc":"繪製扶壁式無障礙扶手：依起訖點與轉向畫扶手線，等分交點自動放置固定件圖塊，並依扶手角度旋轉，-ramp 為坡道版。","usage":"執行 hr-wall-fix → 點選起點 → 點選第 2 階 → 點選終點 → 自動畫扶手與固定件","level":7,"lt":"✅","ver":"20250425","author":"chengshunyi","video":"","fas":"fas/hr-wall-fix.fas"},{"no":902,"file":"ht-tt-bylayer.lsp","cmd":"ht-tt-bylayer","cat":"面積/數量統計","desc":"聚合線依圖層統計面積與步行距離等，以 DCL 設定單位、比例、文字樣式後寫出 MTEXT 計算式，含 reactor 欄位更新。","usage":"執行 ht-tt-bylayer → 於對話框設定圖層/單位/比例/文字 → 選取聚合線 → 指定位置 → 輸出分類面積與計算式","level":9,"lt":"✅","ver":"202311（試用版）","author":"chengshunyi","video":"","fas":"fas/ht-tt-bylayer.fas"},{"no":903,"file":"htb.lsp","cmd":"htb","cat":"修改","desc":"操作 ACAD_SORTENTS 繪製順序表，調整圖塊或空間內物件的顯示順序（程式很短，用途由程式碼推測）。","usage":"執行 htb → 選取物件 → 調整繪製順序","level":4,"lt":"✅","ver":"2022-09-03(檔案日期)","author":"—","video":"","fas":"fas/htb.fas"},{"no":904,"file":"HTLC-HATCH.LSP","cmd":"HTLC-HATCH","cat":"面積/數量統計","desc":"選取 HATCH 依圖層統計面積，在圖面插入表格，列出類別、面積（m2）與該圖層顏色色塊，表頭使用檔名。","usage":"執行 HTLC-HATCH → 框選 HATCH → 指定表格插入點 → 自動產生圖層面積表","level":7,"lt":"⚠️","ver":"20221030","author":"pBe、hak_vz、cheng_shun_yi","video":"","fas":"fas/HTLC-HATCH.fas"},{"no":905,"file":"HTLC-PLINE.LSP","cmd":"HTLC-PLINE","cat":"面積/數量統計","desc":"選取封閉聚合線、圓、橢圓等依圖層統計面積，插入表格並加上該圖層顏色色塊，表頭使用檔名。","usage":"執行 HTLC-PLINE → 框選聚合線 → 指定表格插入點 → 自動產生圖層面積表","level":7,"lt":"⚠️","ver":"20221030","author":"pBe、hak_vz、cheng_shun_yi","video":"","fas":"fas/HTLC-PLINE.fas"},{"no":906,"file":"HUS.LSP","cmd":"HUS","cat":"繪圖","desc":"Hatches Under Slope：以 DCL 設定基礎幾何，依坡度自動在剖面坡線下方產生填充線，改用 ActiveX 建立 HATCH 以避開命令列攔截問題。","usage":"執行 HUS → 於對話框設定幾何參數 → 選取坡度線/指定點 → 自動產生坡下填充","level":6,"lt":"⚠️","ver":"2026-09-16(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/HUS.fas"},{"no":907,"file":"HV-Bracing.lsp","cmd":"HV-Bracing","cat":"繪圖","desc":"指定斜撐寬度與三點後，自動將頂點投影到中垂線，繪製中心線與雙向斜撐線（bbeam 圖層），並檢查建立線型與圖層。","usage":"執行 HV-Bracing → 輸入斜撐寬度（記憶上次值）→ 指定起點 P1 → 指定頂點 P2 → 指定終點 P3 → 自動繪製","level":6,"lt":"✅","ver":"2026-04-29(檔案日期)","author":"—","video":"","fas":"fas/HV-Bracing.fas"},{"no":908,"file":"hyp-modify.lsp","cmd":"htxt、xurl、hyp-view、hyp-view-p、hyp-view1、hyp-add、AddTextAsHyperlink","cat":"其他","desc":"超連結工具組：為物件新增超連結（檔案或網址）、檢視物件超連結，或把選取文字內容轉成該物件的超連結。","usage":"執行 hyp-add → 選取物件 → 輸入超連結或選擇檔案；hyp-view 檢視超連結","level":5,"lt":"✅","ver":"2025-07-05(檔案日期)","author":"Lee Mac 改寫","video":"","fas":"fas/hyp-modify.fas"},{"no":909,"file":"i-blk-at-blk-cen-dor.LSP","cmd":"i-blk-at-blk-cen-dor","cat":"圖塊/屬性","desc":"選取要插入的圖塊與目標圖塊，在每個目標圖塊的中心插入圖塊，並依參考圖塊旋轉與同步 TYPE 屬性（門版）。","usage":"執行 i-blk-at-blk-cen-dor → 選取要插入的圖塊 → 框選目標圖塊 → 自動於各中心插入","level":6,"lt":"✅","ver":"2023-1-16","author":"Lee Mac 改寫 / chengshunyi","video":"","fas":"fas/i-blk-at-blk-cen-dor.fas"},{"no":910,"file":"i-blk-at-blk-cen.LSP","cmd":"i-blk-at-blk-cen","cat":"圖塊/屬性","desc":"在選取圖塊的中心插入另一圖塊，並把參考圖塊的 type、no 屬性值複製到新圖塊。","usage":"執行 i-blk-at-blk-cen → 選取要插入的圖塊 → 框選目標圖塊 → 自動於各中心插入並寫入屬性","level":6,"lt":"✅","ver":"2022-10-22","author":"Lee Mac 改寫 / chengshunyi","video":"","fas":"fas/i-blk-at-blk-cen.fas"},{"no":911,"file":"i-blk-by-dor.LSP","cmd":"i-blk-by-dor-a2、i-blk-by-dor-a1、i-blk-by-dor-a2-s、i-blk-by-dor-a1-s","cat":"圖塊/屬性","desc":"依門扇動態圖塊的尺寸與內外翻轉設定，自動在門旁放置門號圖塊（NO-DOOR、NO-D），A1/A2 為 TYPE 版本，-s 為單選。","usage":"執行 i-blk-by-dor-a1 → 選取門圖塊（或窗選範圍）→ 自動放置門號並寫入屬性","level":7,"lt":"✅","ver":"20250523","author":"chengshunyi","video":"https://youtu.be/lwQXu2w-lfw","fas":"fas/i-blk-by-dor.fas"},{"no":912,"file":"i-blk-by-ewin.lsp","cmd":"i-blk-by-ewin-a2、i-blk-by-ewin-a1、i-blk-by-ewin-a2-s、i-blk-by-ewin-a1-s","cat":"圖塊/屬性","desc":"立面圖用，依窗動態圖塊的窗扇尺寸、牆厚與翻轉，自動放置窗號圖塊（NO-WIN、NO-W），A1/A2 為 TYPE 版本。","usage":"執行 i-blk-by-ewin-a1 → 選取窗圖塊（或窗選範圍）→ 自動放置窗號並寫入屬性","level":7,"lt":"✅","ver":"20250526","author":"chengshunyi","video":"","fas":"fas/i-blk-by-ewin.fas"},{"no":913,"file":"i-blk-by-win.LSP","cmd":"i-blk-by-win-a2、i-blk-by-win-a1、i-blk-by-win-a2-s、i-blk-by-win-a1-s","cat":"圖塊/屬性","desc":"平面圖用，依窗動態圖塊的窗扇尺寸與內外翻轉，自動放置窗號圖塊（NO-WIN、NO-W），A1/A2 為 TYPE 版本。","usage":"執行 i-blk-by-win-a1 → 選取窗圖塊（或窗選範圍）→ 自動放置窗號並寫入屬性","level":7,"lt":"✅","ver":"20250525","author":"chengshunyi","video":"","fas":"fas/i-blk-by-win.fas"},{"no":914,"file":"i-chr.LSP","cmd":"i-chr、setup-chr","cat":"文字","desc":"依輸入的起始字母（或雙字母）連續在圖面點選位置，依序放置遞增的字母文字（A、B、C…）。","usage":"執行 setup-chr 設定字高 → 執行 i-chr → 輸入起始字母 → 連續點選位置 → 依序放字母","level":3,"lt":"✅","ver":"20240309","author":"chengshunyi","video":"","fas":"fas/i-chr.fas"},{"no":915,"file":"i-colnum-xy-h.lsp","cmd":"i-colnum-xy-h","cat":"圖塊/屬性","desc":"選取橫向與縱向兩個柱心線圖塊，讀取軸線編號，在指定座標位置插入柱號圖塊並填入 GRID-X、GRID-Y 屬性。","usage":"執行 i-colnum-xy-h → 選第一個柱軸線 → 選第二個柱軸線 → 指定座標位置 → 自動插入柱號","level":4,"lt":"✅","ver":"20250216","author":"chengshunyi（含 Lee Mac 副程式）","video":"","fas":"fas/i-colnum-xy-h.fas"},{"no":916,"file":"i-colnum-xy.lsp","cmd":"i-colnum-xy","cat":"圖塊/屬性","desc":"選取縱橫兩組軸線圖塊，自動計算交點並插入或更新柱位編號圖塊，支援雙屬性 col-num 與單屬性 col-num-xy 兩種類型。","usage":"執行 i-colnum-xy → 選擇圖塊類型 → 選取 X 方向軸線圖塊 → 選取 Y 方向軸線圖塊 → 自動於交點插入柱號","level":6,"lt":"✅","ver":"2026-03-18(檔案日期)","author":"—","video":"https://youtu.be/blFL6RFiSYk","fas":"fas/i-colnum-xy.fas"},{"no":917,"file":"i-dblk-cn.lsp","cmd":"i-dblk-cn、i-dblk-cn-chr","cat":"圖塊/屬性","desc":"放置柱心座標圖塊並自動連續編號，-chr 版改用英文字母編號（略過 I、O），依軸線方向決定柱線與柱號角度。","usage":"執行 i-dblk-cn → 輸入起始編號 → 指定插入點與軸線方向 → 連續放置編號圖塊","level":5,"lt":"✅","ver":"20231003","author":"chengshunyi","video":"","fas":"fas/i-dblk-cn.fas"},{"no":918,"file":"i-dy-block.lsp","cmd":"i-dy-block","cat":"圖塊/屬性","desc":"選取含可見性狀態的動態圖塊，以 DCL 選擇可見性狀態後，插入已設定該狀態的動態圖塊。","usage":"執行 i-dy-block → 選取動態圖塊 → 於對話框選可見性狀態 → 指定插入點","level":6,"lt":"✅","ver":"2013-12-24 (Lee Mac) / 2022-10-22","author":"Lee Mac 改寫 / chengshunyi","video":"","fas":"fas/i-dy-block.fas"},{"no":919,"file":"i-pagesetup.lsp","cmd":"i-pagesetup","cat":"出圖/列印","desc":"刪除圖面既有頁面設定，從專案 pagesetup.dwg 匯入頁面設定（如 A1 PDF），並設成目前的頁面設定。","usage":"執行 i-pagesetup → 自動刪除舊設定 → 匯入 pagesetup.dwg 頁面設定 → 設定目前頁面為 A1 PDF","level":5,"lt":"✅","ver":"20221016","author":"cheng_shun_yi","video":"","fas":"fas/i-pagesetup.fas"},{"no":920,"file":"i-wall-type-w.lsp","cmd":"i-wall-type-w","cat":"剖面/結構","desc":"窗選範圍內的 MLINE 牆線，判斷其邊數（4 點 3 邊等）後，依牆型在位置插入 WALL-TYPE 圖塊（視窗選取版）。","usage":"執行 i-wall-type-w → 窗選牆線範圍 → 自動判斷牆型並插入牆型圖塊","level":5,"lt":"✅","ver":"2008.05.18","author":"—","video":"","fas":"fas/i-wall-type-w.fas"},{"no":921,"file":"i-wall-type.lsp","cmd":"i-wall-type","cat":"剖面/結構","desc":"掃描圖面 MLINE 牆線，判斷其邊數後在對應位置插入 WALL-TYPE 牆型圖塊。","usage":"執行 i-wall-type → 選取牆線 → 自動判斷牆型並插入牆型圖塊","level":5,"lt":"✅","ver":"2008.05.18","author":"—","video":"","fas":"fas/i-wall-type.fas"},{"no":922,"file":"IAT.lsp","cmd":"IAT、NumberBlocks、IncAtts、natt、AttNum","cat":"圖塊/屬性","desc":"對含指定 Tag 的屬性圖塊依序遞增編號，可指定要變動的字元位數與遞增值，補零（01、02…），五個指令為不同介面。","usage":"執行 IAT → 輸入 Tag 名稱 → 輸入要變動位數與遞增值 → 輸入起始編號 → 依序點選圖塊","level":6,"lt":"✅","ver":"2023-12-04","author":"Iván Romero Cruz (cR0m3r014)","video":"","fas":"fas/IAT.fas"},{"no":923,"file":"ibbyint-lab.lsp","cmd":"ibbyint-lab","cat":"圖塊/屬性","desc":"窗選範圍內所有線的交點自動插入所選符號圖塊，並提示共有幾個交點（標籤圖塊版）。","usage":"執行 ibbyint-lab → 選取要插入的圖塊 → 窗選範圍 → 於各交點放置符號","level":4,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/ibbyint-lab.fas"},{"no":924,"file":"ibbyint.lsp","cmd":"ibbyint","cat":"圖塊/屬性","desc":"窗選範圍內所有線的交點自動插入所選圖塊，並提示共有幾個交點，圖塊縮放依 XEffectiveScaleFactor。","usage":"執行 ibbyint → 選取要插入的圖塊 → 窗選範圍 → 於各交點放置圖塊","level":4,"lt":"✅","ver":"20200320","author":"—","video":"","fas":"fas/ibbyint.fas"},{"no":925,"file":"IdentifyShape-ui.LSP","cmd":"IdentifyShape","cat":"面積/數量統計","desc":"以 DCL 設定比例與單位，批次辨識封閉聚合線形狀（弧形、三角形、四邊形、多邊形），繪製輔助線並標註面積公式與計算式總表。","usage":"執行 IdentifyShape → 於對話框設定比例/單位 → 選取封閉聚合線 → 指定總表放置點 → 自動標註公式","level":7,"lt":"✅","ver":"20251225","author":"chengshunyi / MyCAD","video":"","fas":"fas/IdentifyShape-ui.fas"},{"no":926,"file":"IdentifyShape.lsp","cmd":"IdentifyShape","cat":"面積/數量統計","desc":"批次辨識封閉聚合線形狀並標註面積公式，特別強化兩點封閉弧與三角形的詳細算式及輔助線（紅色虛線弦線等）。","usage":"執行 IdentifyShape → 輸入比例與單位 → 選取封閉聚合線 → 指定總表放置點 → 自動標註公式","level":7,"lt":"✅","ver":"20251225","author":"chengshunyi","video":"","fas":"fas/IdentifyShape.fas"},{"no":927,"file":"if-off2freeze.LSP","cmd":"if-off2freeze","cat":"圖層","desc":"把圖面上已關閉（off）的圖層全部改為凍結（freeze）。","usage":"執行 if-off2freeze → 自動將關閉的圖層凍結","level":3,"lt":"✅","ver":"20230611","author":"chengshunyi","video":"","fas":"fas/if-off2freeze.fas"},{"no":928,"file":"IF0.lsp","cmd":"IF0","cat":"圖面管理","desc":"將 IMAGEFRAME 設為 0，關閉點陣影像的外框顯示。","usage":"執行 IF0 → 影像框架關閉","level":1,"lt":"✅","ver":"2026-01-19(檔案日期)","author":"—","video":"","fas":"fas/IF0.fas"},{"no":929,"file":"ImpPgSetups.lsp","cmd":"psimportandcurrent、demo、demo1","cat":"出圖/列印","desc":"從 Plot Setting.dwg 匯入指定頁面設定（如 A1 PDF、A3 DWG2PDF），刪除既有設定並設為目前頁面設定，demo 為範例呼叫。","usage":"執行 psimportandcurrent → 自動刪除舊設定 → 匯入頁面設定 → 設為目前設定","level":5,"lt":"✅","ver":"2022-05-11(檔案日期)","author":"—","video":"","fas":"fas/ImpPgSetups.fas"},{"no":930,"file":"IncArray.lsp","cmd":"incarray、incarrayd","cat":"對齊/排列","desc":"陣列選取物件並同時遞增註解（文字、屬性、標註、MLeader）內的數字，incarrayd 為可動態預覽版，incarray 為標準快速版。","usage":"執行 incarray → 選取物件 → 指定基點 → 輸入遞增值 → 指定陣列向量與終點","level":7,"lt":"✅","ver":"Version 1.9","author":"Lee Mac","video":"","fas":"fas/IncArray.fas"},{"no":931,"file":"Increment.lsp","cmd":"incsuf、inctxt、incatt、incsel、incadd、incr","cat":"文字","desc":"一組遞增編號工具，對文字、屬性、選取物件末尾的數字或字母後綴自動遞增，並提供圖塊選單與複製遞增功能。","usage":"執行 inctxt（或 incatt/incsel）→ 選取文字/屬性 → 輸入遞增值 → 依序點選放置","level":8,"lt":"✅","ver":"2008-01-15 (INCSUFF v1.2)","author":"Gilles Chanteau","video":"","fas":"fas/Increment.fas"},{"no":932,"file":"INDEX.LSP","cmd":"index","cat":"標註","desc":"詳圖索引符號工具：以 DCL（含六張幻燈片）選擇索引符號樣式，繪製線、聚合線、圓點與圖塊並可加引線。","usage":"執行 index → 於對話框選索引符號樣式 → 指定位置與方向 → 繪製索引符號並輸入編號","level":6,"lt":"✅","ver":"86.7.30（民國年）","author":"—","video":"","fas":"fas/INDEX.fas"},{"no":933,"file":"INDEX1.LSP","cmd":"index1","cat":"標註","desc":"詳圖索引符號工具舊版：以 DCL 選擇索引符號樣式，繪製線、聚合線、圓點與圖塊。","usage":"執行 index1 → 於對話框選索引符號樣式 → 指定位置 → 繪製索引符號","level":6,"lt":"✅","ver":"90.05.30（民國年）","author":"—","video":"","fas":"fas/INDEX1.fas"},{"no":934,"file":"ins-blk-allblk.lsp","cmd":"BLK-INS","cat":"圖塊/屬性","desc":"把目前圖檔裡所有圖塊（含動態圖塊）定義，從指定點開始每隔固定距離依序全部插入圖面，用於檢視圖塊庫。","usage":"執行 BLK-INS → 指定第一個圖塊插入點 → 自動依序排列插入全部圖塊","level":4,"lt":"✅","ver":"20230926","author":"chengshunyi","video":"","fas":"fas/ins-blk-allblk.fas"},{"no":935,"file":"ins-blk-cen.LSP","cmd":"ins-blk-cen","cat":"圖塊/屬性","desc":"在所選圖塊的中心插入指定圖塊（Lee Mac 版本改寫），自動採用有效名稱並處理屬性與旋轉。","usage":"執行 ins-blk-cen → 選取要插入的圖塊 → 框選目標圖塊 → 自動於各中心插入","level":6,"lt":"✅","ver":"20240302","author":"Lee Mac 改寫 / chengshunyi","video":"","fas":"fas/ins-blk-cen.fas"},{"no":936,"file":"insertcolnumXY.lsp","cmd":"insertcolnumXY","cat":"圖塊/屬性","desc":"選取柱心線圖層（CCL 或 CCL5）上的線，插入柱號圖塊並寫入座標屬性，圖塊屬性限定兩個，可輸入圖塊名稱或瀏覽。","usage":"執行 insertcolnumXY → 選擇圖塊或輸入圖塊名稱 → 選取柱心線 → 自動插入柱號圖塊","level":5,"lt":"✅","ver":"20181110 / 20191007","author":"—","video":"","fas":"fas/insertcolnumXY.fas"},{"no":937,"file":"InsXYZ.lsp","cmd":"InsXYZ","cat":"圖塊/屬性","desc":"插入 DELTA14 圖塊並將點位座標（XYZ）寫入其屬性，可 ESC 中斷（由字串與函式推測）。","usage":"執行 InsXYZ → 指定點位 → 自動插入 DELTA14 並填入座標屬性","level":5,"lt":"✅","ver":"2023-04-13(檔案日期)","author":"Lee Mac 副程式","video":"","fas":"fas/InsXYZ.fas"},{"no":938,"file":"int-Dim-align.LSP","cmd":"int-Dim-align","cat":"標註","desc":"指定兩點定義一條虛擬線，找出它與圖面物件的所有交點，在交點之間依序標註對齊尺寸。","usage":"執行 int-Dim-align → 指定第一點 → 指定第二點 → 自動在交點之間標註尺寸","level":5,"lt":"✅","ver":"20231001","author":"chengshunyi（含 Lee Mac 副程式）","video":"","fas":"fas/int-Dim-align.fas"},{"no":939,"file":"int-Dim-hv-la.LSP","cmd":"int-Dim-hv-la","cat":"標註","desc":"指定兩點定義虛擬線，只對特定圖層（自然採光面積 NAi、WALL-OUT）的聚合線與直線交點，以旋轉尺寸（水平/垂直）依序標註。","usage":"執行 int-Dim-hv-la → 指定第一點 → 指定第二點 → 自動在交點之間標註水平/垂直尺寸","level":5,"lt":"✅","ver":"20231001 / 20240329","author":"chengshunyi（含 Lee Mac 副程式）","video":"","fas":"fas/int-Dim-hv-la.fas"},{"no":940,"file":"int-Dim-hv.LSP","cmd":"int-Dim-hv","cat":"標註","desc":"指定兩點定義虛擬線，找出與圖面物件的所有交點，以旋轉尺寸（水平/垂直）在交點之間依序標註。","usage":"執行 int-Dim-hv → 指定第一點 → 指定第二點 → 自動在交點之間標註水平/垂直尺寸","level":5,"lt":"✅","ver":"20231001","author":"chengshunyi（含 Lee Mac 副程式）","video":"","fas":"fas/int-Dim-hv.fas"},{"no":941,"file":"int-qblock.LSP","cmd":"int-qblock","cat":"圖塊/屬性","desc":"選取要複製的物件（圖塊可多選）與基準點，再畫一條切線，在切線與物件交點自動複製所選圖塊。","usage":"執行 int-qblock → 選取要複製的物件 → 指定基準點 → 指定切線起點與終點 → 於交點複製圖塊","level":5,"lt":"✅","ver":"2025-03-18(檔案日期)","author":"chengshunyi","video":"","fas":"fas/int-qblock.fas"},{"no":942,"file":"int-qDim-align.lsp","cmd":"int-qDim-align","cat":"標註","desc":"沿一條虛擬切線，在其與所有可相交物件（含圖塊、外參、標註）的交點之間產生共線連續對齊尺寸，可判斷柱心線。","usage":"執行 int-qDim-align → 指定切線起點 → 指定切線終點 → 自動產生連續對齊標註","level":6,"lt":"✅","ver":"20240727 / 20241031","author":"Kent Cooper (QuickDimAlignedB) 改寫 / chengshunyi","video":"","fas":"fas/int-qDim-align.fas"},{"no":943,"file":"int-qDim-linear-SCA.lsp","cmd":"int-qDim-linear-sca-v、int-qDim-linear-sca-H、int-qDim-linear-sca-v2、int-qDim-linear-sca-H2、int-qDim-linear-sca","cat":"標註","desc":"沿虛擬切線與物件交點自動產生連續線性尺寸（垂直 v、水平 H，v2/H2 為變化版），並依比例縮放標註（原 m 改為比例）。","usage":"執行 int-qDim-linear-sca-v（或 -H）→ 指定切線起點 → 指定切線終點 → 自動產生連續線性標註","level":6,"lt":"✅","ver":"2025-10-23(檔案日期)","author":"chengshunyi","video":"https://youtu.be/xvJwXAnLZ1Q","fas":"fas/int-qDim-linear-SCA.fas"},{"no":944,"file":"int-qDim-linear.lsp","cmd":"int-qDim-linear-v、int-qDim-linear-H、int-qDim-linear-v2、int-qDim-linear-H2、int-qDim-linear","cat":"標註","desc":"沿虛擬切線與物件交點自動產生連續線性尺寸（垂直 v、水平 H，v2/H2 為變化版），可判斷柱心線。","usage":"執行 int-qDim-linear-v（或 -H）→ 指定切線起點 → 指定切線終點 → 自動產生連續線性標註","level":6,"lt":"✅","ver":"20240727","author":"Kent Cooper (QuickDimAlignedB) 改寫 / chengshunyi","video":"https://youtu.be/9vbc-CFovqI","fas":"fas/int-qDim-linear.fas"},{"no":945,"file":"int-qNUM-se.lsp","cmd":"int-qNUM-se","cat":"文字","desc":"沿虛擬切線與物件交點自動放置連續編號文字，只取頭尾交點標註，並將編號建立成群組，圖層為 ST-NUM。","usage":"執行 int-qNUM-se → 輸入起始編號 → 指定切線起點 → 指定切線終點 → 自動於頭尾交點放編號","level":6,"lt":"✅","ver":"20250412","author":"chengshunyi","video":"","fas":"fas/int-qNUM-se.fas"},{"no":946,"file":"int-qNUM.lsp","cmd":"int-qNUM","cat":"文字","desc":"沿虛擬切線與物件交點自動依序放置編號文字，圖層為 ST-NUM。","usage":"執行 int-qNUM → 輸入起始編號 → 指定切線起點 → 指定切線終點 → 自動於各交點放編號","level":6,"lt":"✅","ver":"20250412","author":"chengshunyi","video":"","fas":"fas/int-qNUM.fas"},{"no":947,"file":"int-qREF.lsp","cmd":"int-qREF-V、int-qREF-H、int-qREF","cat":"繪圖","desc":"沿虛擬切線與物件的交點連續建立垂直或水平參考線（XLINE），圖層為 0-REF，可連續切線（用途由程式碼推測）。","usage":"執行 int-qREF-V（或 -H）→ 指定切線起點 → 指定切線終點 → 於交點建立參考線","level":5,"lt":"✅","ver":"20250510","author":"chengshunyi","video":"","fas":"fas/int-qREF.fas"},{"no":948,"file":"interset-copy-blk.LSP","cmd":"interset-copy-blk","cat":"圖塊/屬性","desc":"窗選範圍內所有物件的交點，以 COPY 方式複製所選特殊圖塊到各交點（取代 INSERT，供特殊功能圖塊使用）。","usage":"執行 interset-copy-blk → 選取要複製的圖塊 → 窗選範圍 → 於各交點複製圖塊","level":5,"lt":"✅","ver":"20240720","author":"Lee Mac 改寫 / chengshunyi","video":"","fas":"fas/interset-copy-blk.fas"},{"no":949,"file":"interset-put-point.lsp","cmd":"interset","cat":"繪圖","desc":"取得選集內所有物件相互之間的交點，並在每個交點建立點（POINT）物件。","usage":"執行 interset → 框選物件 → 自動於所有交點放置點","level":4,"lt":"✅","ver":"2022-09-17(檔案日期)","author":"Lee Mac","video":"","fas":"fas/interset-put-point.fas"},{"no":950,"file":"intersets.lsp","cmd":"intersets","cat":"繪圖","desc":"取得兩個選集之間物件的交點，並在每個交點建立點（POINT）物件。","usage":"執行 intersets → 選取第一組物件 → 選取第二組物件 → 自動於交點放置點","level":4,"lt":"✅","ver":"2022-11-27(檔案日期)","author":"Lee Mac","video":"","fas":"fas/intersets.fas"},{"no":951,"file":"JB.LSP","cmd":"JB","cat":"出圖/列印","desc":"BATCH FILES 批次工具：以 DCL 列出資料夾內 DWG 檔，勾選後逐檔開啟、縮放全部並批次列印。","usage":"執行 JB → 選擇資料夾 → 於對話框勾選 DWG 檔案 → 確定 → 逐檔批次列印","level":7,"lt":"❌","ver":"2024-04-05(檔案日期)","author":"Paul","video":"","fas":"fas/JB.fas"},{"no":952,"file":"join-same-attval.lsp","cmd":"join-same-attval","cat":"圖塊/屬性","desc":"選取圖塊後，把屬性值相同的同名圖塊依序用聚合線連起來（原用於電桿連線）。","usage":"執行 join-same-attval → 選取參考圖塊 → 自動依屬性值分組 → 以 PLINE 連線","level":5,"lt":"✅","ver":"AlanH Nov 2020 / 2024-07-07(檔案日期)","author":"AlanH","video":"","fas":"fas/join-same-attval.fas"},{"no":953,"file":"JoinLines.LSP","cmd":"JoinLines","cat":"修改","desc":"建築牆體封口工具：啟動 DCL 說明視窗後進入連續模式，交選牆體範圍，將共線的 LINE 與聚合線配對結合，並以範圍距離作為容差重繪封口線。","usage":"執行 JoinLines → 在說明對話框按「開始執行」→ 交選牆線範圍（兩個角點）→ 自動配對並封口 → 重複框選至結束","level":7,"lt":"✅","ver":"V4 / 2026-06-06(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/JoinLines.fas"},{"no":954,"file":"JoneTank.lsp","cmd":"JoneTank","cat":"繪圖","desc":"GRP 模組化水箱設計繪圖工具（DCL 整合版）：輸入水箱尺寸與水位參數，自動繪製平面、立面、縱橫剖面圖並產生單元板片計算書。","usage":"執行 JoneTank → 於對話框輸入水箱 L/W/高度分割等參數 → 指定繪圖位置 → 自動繪製各視圖與計算書","level":7,"lt":"✅","ver":"2026-03-29(檔案日期)","author":"強恩企業客製","video":"","fas":"fas/JoneTank.fas"},{"no":955,"file":"JustifyBasePoint.lsp","cmd":"jbp","cat":"圖塊/屬性","desc":"以 DCL 的九宮格選擇對齊位置，一次修改多個圖塊定義的基準點（左上、中、右下等九種），同名圖塊只需選一個。","usage":"執行 jbp → 選取圖塊 → 於對話框選擇九種基準點位置之一 → 確定 → 圖塊基準點更新","level":7,"lt":"✅","ver":"V1.0 / 20220716更新","author":"Lee Mac","video":"","fas":"fas/JustifyBasePoint.fas"},{"no":956,"file":"KERB.LSP","cmd":"KERB","cat":"剖面/結構","desc":"緣石（路緣）剖面繪製系統：以 DCL 與幻燈片選擇左右斜面方向，輸入底寬 B、豎直高 H、頂寬 T 等尺寸，自動繪製緣石剖面並建立圖層。","usage":"執行 KERB → 於對話框選擇方向並輸入 B/H/T 尺寸 → 指定插入點 → 自動繪製剖面","level":7,"lt":"✅","ver":"2026-09-16(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/KERB.fas"},{"no":957,"file":"L-CONTOUR.LSP","cmd":"L-CONTOUR","cat":"圖層","desc":"等高線設定：自動建立計曲線（每 5m）、首曲線（每 1m）圖層與等高線線型、文字樣式。","usage":"執行 L-CONTOUR → 自動建立等高線圖層、線型與文字樣式","level":3,"lt":"✅","ver":"2022-12-10(檔案日期)","author":"—","video":"","fas":"fas/L-CONTOUR.fas"},{"no":958,"file":"la-back-save.LSP","cmd":"la-back-save","cat":"圖層","desc":"透過 AutoCAD 圖層狀態管理員儲存、還原與刪除圖層狀態（Tony Tanzillo 版），供圖層操作前備份、之後還原。","usage":"執行 la-back-save → 自動儲存目前圖層狀態 → 之後可還原或刪除","level":5,"lt":"❌","ver":"20220507","author":"Tony Tanzillo","video":"","fas":"fas/la-back-save.fas"},{"no":959,"file":"la-nentsel-freeze.lsp","cmd":"nl、ffl、afl","cat":"圖層","desc":"點選巢狀物件（圖塊內物件）取得其圖層名稱清單，nl 取得圖層、ffl 與 afl 依選取結果凍結圖層（含圖塊內圖層與屬性圖層）。","usage":"執行 ffl → 選取基準物件取得圖層 → 選取要凍結的圖層（可點選巢狀物件）→ 完成凍結","level":5,"lt":"✅","ver":"2024-04-04(檔案日期)","author":"—","video":"","fas":"fas/la-nentsel-freeze.fas"},{"no":960,"file":"la-on-rc-only.LSP","cmd":"la-on-rc-only","cat":"圖層","desc":"只保留 RC 相關圖層（RC、RCW、slab-1、defpoints、rc-hatch、rcw-hatch）開啟，其餘關閉，並用圖層狀態管理員保存原狀態。","usage":"執行 la-on-rc-only → 自動儲存目前圖層狀態 → 關閉非 RC 圖層，只顯示結構圖層","level":5,"lt":"❌","ver":"20220507","author":"Tony Tanzillo 改寫","video":"","fas":"fas/la-on-rc-only.fas"},{"no":961,"file":"Label-Pl-Vertices.lsp","cmd":"Label-Pl-Vertices-T、Label-Pl-Vertices-M、Label-Pl-Vertices","cat":"標註","desc":"選取聚合線，在每個頂點旁標註 X、Y 座標，-T 以 TEXT、-M 以 MTEXT（字寬 0.75）建立標註。","usage":"執行 Label-Pl-Vertices-T（或 -M）→ 選取聚合線 → 自動標註各頂點座標","level":4,"lt":"✅","ver":"2025020（檔頭日期不完整）","author":"chengshunyi","video":"","fas":"fas/Label-Pl-Vertices.fas"},{"no":962,"file":"label_dist-vertex_po.LSP","cmd":"label_dist-vertex_po","cat":"標註","desc":"選取聚合線，在各線段旁標註其長度文字，使用 Label 圖層與 Romand-Label 文字樣式，字高可依圖紙輸入。","usage":"執行 label_dist-vertex_po → 選取聚合線 → 輸入字高 → 自動標註各段長度","level":5,"lt":"✅","ver":"20220312","author":"chengshunyi","video":"","fas":"fas/label_dist-vertex_po.fas"},{"no":963,"file":"LabelPline.lsp","cmd":"LabelPline","cat":"標註","desc":"剖面標註工具：以 DCL 設定字高、底線長度係數、位移係數與繪圖比例，選取聚合線後在旁邊產生 MTEXT 標註並畫底線。","usage":"執行 LabelPline → 於對話框設定字高/底線/位移/比例 → 確定 → 選取聚合線 → 自動標註","level":6,"lt":"✅","ver":"2026-02-10(檔案日期)","author":"MyCAD","video":"","fas":"fas/LabelPline.fas"},{"no":964,"file":"law-3D-erase.lsp","cmd":"law-3D-erase","cat":"3D","desc":"過濾出選取範圍內的 3DSOLID 實體並整批刪除，用於法規面積檢核後清除 3D 色塊。","usage":"執行 law-3D-erase → 框選範圍 → 自動刪除範圍內所有 3DSOLID","level":2,"lt":"⚠️","ver":"20211009","author":"Cheng Shun_Yi","video":"","fas":"fas/law-3D-erase.fas"},{"no":965,"file":"LAW-CreateLayers.lsp","cmd":"LAW-CreateLayers","cat":"圖層","desc":"依清單自動建立套繪圖用圖層（1-建物-新建、5-防火間隔、22-地界線等 30 多層，名稱_色號），已存在則略過。","usage":"執行 LAW-CreateLayers → 自動建立套繪圖層","level":3,"lt":"✅","ver":"20251025","author":"chengshunyi","video":"","fas":"fas/LAW-CreateLayers.fas"},{"no":966,"file":"law-hatch-area-carsp.LSP","cmd":"law-hatch-area-carsp","cat":"面積/數量統計","desc":"以 HATCH 圖層為分類依據統計各類面積，並加入防空避難室（停車空間）面積檢討，輸出分類計算式於圖面。","usage":"執行 law-hatch-area-carsp → 框選 HATCH → 依圖層分類計算 → 指定文字放置點 → 輸出計算式","level":8,"lt":"✅","ver":"20211009 / 20230901","author":"Lee Mac 改寫 / Cheng Shun_Yi","video":"","fas":"fas/law-hatch-area-carsp.fas"},{"no":967,"file":"law-hatch-area-f.LSP","cmd":"law-hatch-area-f","cat":"面積/數量統計","desc":"以 HATCH 圖層為分類依據統計各類面積，含防空避難室面積檢討，輸出分類計算式於圖面（f 版）。","usage":"執行 law-hatch-area-f → 框選 HATCH → 依圖層分類計算 → 指定文字放置點 → 輸出計算式","level":8,"lt":"✅","ver":"20211009 / 20230901","author":"Lee Mac 改寫 / Cheng Shun_Yi","video":"","fas":"fas/law-hatch-area-f.fas"},{"no":968,"file":"law-hatch-area.LSP","cmd":"law-hatch-area","cat":"面積/數量統計","desc":"以 HATCH 圖層為分類依據，統計樓地板、陽台、梯廳、機電、居室、安全梯等各類面積並標註於圖面。","usage":"執行 law-hatch-area → 框選 HATCH → 依圖層分類計算 → 指定文字放置點 → 輸出分類面積","level":8,"lt":"✅","ver":"20210911 / 20230901","author":"Lee Mac 改寫 / Cheng Shun_Yi","video":"","fas":"fas/law-hatch-area.fas"},{"no":969,"file":"law-hatch-erase.lsp","cmd":"law-hatch-erase","cat":"繪圖","desc":"選取範圍內只過濾出 HATCH 填充線並整批刪除，法規分類面積統計後清除填充。","usage":"執行 law-hatch-erase → 框選範圍 → 自動刪除範圍內所有 HATCH","level":2,"lt":"✅","ver":"20210914","author":"Cheng Shun_Yi","video":"https://youtu.be/Lv7865ZFwNk","fas":"fas/law-hatch-erase.fas"},{"no":970,"file":"law-pline-3D.LSP","cmd":"law-pline-3D","cat":"3D","desc":"依聚合線圖層複製並以 EXTRUDE 擠出成 3D 色塊，切換視覺型式與視角，供法規面積分類上色檢核。","usage":"執行 law-pline-3D → 框選聚合線 → 依圖層複製並擠出 → 自動切換 3D 視角檢核","level":7,"lt":"❌","ver":"20210913","author":"Cheng Shun_Yi","video":"","fas":"fas/law-pline-3D.fas"},{"no":971,"file":"law-pline-area-carsp.LSP","cmd":"law-pline-area-carsp","cat":"面積/數量統計","desc":"以聚合線圖層為分類依據統計各類面積，含防空避難室（停車空間）面積檢討，輸出計算式於圖面。","usage":"執行 law-pline-area-carsp → 框選聚合線 → 依圖層分類計算 → 指定文字放置點 → 輸出計算式","level":6,"lt":"✅","ver":"20211009","author":"Lee Mac 改寫 / Cheng Shun_Yi","video":"","fas":"fas/law-pline-area-carsp.fas"},{"no":972,"file":"law-pline-area-f.LSP","cmd":"law-pline-area-f","cat":"面積/數量統計","desc":"以聚合線圖層為分類依據統計各類面積，含防空避難室面積檢討，輸出分類計算式於圖面（f 版）。","usage":"執行 law-pline-area-f → 框選聚合線 → 依圖層分類計算 → 指定文字放置點 → 輸出計算式","level":6,"lt":"✅","ver":"20211009","author":"Lee Mac 改寫 / Cheng Shun_Yi","video":"","fas":"fas/law-pline-area-f.fas"},{"no":973,"file":"law-pline-area.LSP","cmd":"law-pline-area","cat":"面積/數量統計","desc":"以聚合線圖層為分類依據，統計樓地板、陽台、梯廳、機電、居室、安全梯、排煙室等各類面積並標註於圖面。","usage":"執行 law-pline-area → 框選聚合線 → 依圖層分類計算 → 指定文字放置點 → 輸出分類面積","level":6,"lt":"✅","ver":"20210911 / 檔案日期 2025-03-12","author":"Lee Mac 改寫 / Cheng Shun_Yi","video":"","fas":"fas/law-pline-area.fas"},{"no":974,"file":"law-pline-hatch.LSP","cmd":"law-pline-hatch","cat":"繪圖","desc":"依聚合線所在圖層顏色在其範圍內建立填充，作為法規面積分類上色檢核。","usage":"執行 law-pline-hatch → 框選聚合線/圓 → 自動依圖層色建立 HATCH","level":4,"lt":"✅","ver":"20210913","author":"Cheng Shun_Yi","video":"https://youtu.be/VJZTRXU8SWc","fas":"fas/law-pline-hatch.fas"},{"no":975,"file":"lay-f-AutoCAD.lsp","cmd":"lay-f-vp-e、lay-f-vp-b、lay-f-vp-n","cat":"圖層","desc":"使用 AutoCAD 2024 原生 LAYFRZ 指令的進階應用，三個指令分別以元件、圖塊所在圖層或預設值凍結選取物件的圖層。","usage":"執行 lay-f-vp-e（或 -b、-n）→ 選取物件 → 其圖層被凍結","level":1,"lt":"✅","ver":"20250214","author":"chengshunyi","video":"","fas":"fas/lay-f-AutoCAD.fas"},{"no":976,"file":"lay-f-t-sel-ns.lsp","cmd":"lay-freeze-sel、lay-freeze-sel-s、lay-off-sel-s、lay-thaw-sel、lay-on-sel、LayerOff、Layerfreeze","cat":"圖層","desc":"選取物件後凍結、解凍、關閉或開啟其所在圖層（含圖塊圖層判斷），-s 為連續選取，LayerOff/Layerfreeze 一次處理 0 層以外所有圖層。","usage":"執行 lay-freeze-sel → 選取物件（可連續）→ 其圖層被凍結；Esc 結束；解凍用 lay-thaw-sel","level":5,"lt":"✅","ver":"20240404 / 20250528","author":"chengshunyi","video":"","fas":"fas/lay-f-t-sel-ns.fas"},{"no":977,"file":"lay-f-t-sel.LSP","cmd":"lay-freeze-sel、lay-freeze-sel-s、nff、nfff、lay-off-sel-s、lay-thaw-sel、lay-on-sel、LayerOff、Layerfreeze","cat":"圖層","desc":"選取物件後凍結、解凍、關閉或開啟其所在圖層，nff/nfff 處理 0 層特例，LayerOff/Layerfreeze 一次處理 0 層以外所有圖層。","usage":"執行 lay-freeze-sel → 選取物件 → 其圖層被凍結；0 層物件用 nff 或 nfff 處理","level":5,"lt":"✅","ver":"20240404 / 20250709","author":"chengshunyi","video":"","fas":"fas/lay-f-t-sel.fas"},{"no":978,"file":"lay-freeze-thaw.lsp","cmd":"SFR、LAF1、LAF、LAFU","cat":"圖層","desc":"圖層凍結工具：SFR 凍結選取物件以外的所有圖層，LAF 凍結全部（除目前層），LAF1 凍結選取物件圖層，LAFU 解凍全部。","usage":"執行 SFR → 選取要保留的物件 → 其餘圖層凍結；LAFU 還原","level":5,"lt":"✅","ver":"2022.04.28 (exceed) / 20240401","author":"exceed、chengshunyi","video":"","fas":"fas/lay-freeze-thaw.fas"},{"no":979,"file":"lay-L-UL-sel.LSP","cmd":"lay-lock-sel、lay-unlock-sel","cat":"圖層","desc":"選取物件後鎖定或解鎖其所在圖層，並處理圖塊所在圖層。","usage":"執行 lay-lock-sel → 選取物件 → 其圖層被鎖定；解鎖用 lay-unlock-sel","level":4,"lt":"✅","ver":"20240404 / 20240904","author":"chengshunyi","video":"","fas":"fas/lay-L-UL-sel.fas"},{"no":980,"file":"lay-lst-to-file.LSP","cmd":"lay-lst-to-file","cat":"轉檔/匯出入","desc":"把所有圖層與其狀態（開關、凍結、鎖定、顏色、線型、線寬、列印屬性）寫成文字檔，可匯入 Excel。","usage":"執行 lay-lst-to-file → 指定輸出檔案 → 自動寫出圖層清單","level":6,"lt":"✅","ver":"2000-03-15 (檔案日期 2024-01-26)","author":"Jimmy Bergmark (JTB World)","video":"","fas":"fas/lay-lst-to-file.fas"},{"no":981,"file":"lay-obj-sel.lsp","cmd":"lay-obj-sel-w、lay-obj-sel-x、lay-obj-sel","cat":"圖層","desc":"以 DCL 多選清單挑選圖層後，選取目前配置中這些圖層上的所有物件，-w 為窗選、-x 為全圖版。","usage":"執行 lay-obj-sel → 於對話框多選圖層 → 確定 → 自動選取這些圖層上的物件","level":6,"lt":"✅","ver":"2009-05-11 (Alan J. Thompson)","author":"Alan J. Thompson","video":"","fas":"fas/lay-obj-sel.fas"},{"no":982,"file":"lay-off-on-sel.LSP","cmd":"lay-off-sel","cat":"圖層","desc":"選取物件後關閉其所在圖層（含圖塊圖層判斷），檔內另有只打開選取層的指令（lay-on-sel）。","usage":"執行 lay-off-sel → 選取物件 → 其圖層被關閉","level":4,"lt":"✅","ver":"20240404","author":"chengshunyi","video":"https://youtu.be/SdcJYfGnrTU","fas":"fas/lay-off-on-sel.fas"},{"no":983,"file":"layer-to-solid.lsp","cmd":"layer-to-solid","cat":"圖層","desc":"對圖面所有圖層各畫一個矩形色塊（solid 填充）並寫入圖層名稱，產生圖層色卡對照表。","usage":"執行 layer-to-solid → 指定起點 → 自動為每個圖層繪製色塊與名稱","level":4,"lt":"✅","ver":"20250112","author":"chengshunyi + ChatGPT","video":"","fas":"fas/layer-to-solid.fas"},{"no":984,"file":"Layer2Drawing.lsp","cmd":"Layer2Drawing","cat":"轉檔/匯出入","desc":"將選取物件所在圖層逐層 WBLOCK 成獨立 DWG 檔，存到指定資料夾（Lee Mac Layers 2 DWGs 改寫）。","usage":"執行 Layer2Drawing → 選取物件 → 選擇存放資料夾 → 逐層輸出 DWG","level":6,"lt":"⚠️","ver":"20220716更新（Lee Mac 2010）","author":"Lee Mac 改寫","video":"","fas":"fas/Layer2Drawing.fas"},{"no":985,"file":"layer_creation.lsp","cmd":"layer_creation、layer_creation_b","cat":"圖層","desc":"輸入樓層數後，依 layer_creation.txt 清單建立結構圖層（S-樓層+名稱），設定顏色與線型（Phantom 等），並可更新既有圖層。","usage":"執行 layer_creation → 輸入樓層 → 讀取清單 → 自動建立並更新圖層","level":6,"lt":"✅","ver":"20230416","author":"chengshunyi","video":"","fas":"fas/layer_creation.fas"},{"no":986,"file":"layer_lock_fast.LSP","cmd":"layer_lock_fast","cat":"圖層","desc":"連續點選物件並立即鎖定其所在圖層，可處理圖塊內嵌套物件、屬性與多段線頂點，Enter 結束。","usage":"執行 layer_lock_fast → 點選物件即鎖其圖層 → 連續點選下一個 → Enter 結束","level":3,"lt":"✅","ver":"2025-12-12(檔案日期)","author":"—","video":"","fas":"fas/layer_lock_fast.fas"},{"no":987,"file":"LAYER_ON.lsp","cmd":"LAYER_ON","cat":"圖層","desc":"以對話框列出關閉、凍結、鎖定、不列印與外部參考圖層，勾選後一次開啟或解凍選取的圖層。","usage":"執行 LAYER_ON → 於對話框勾選圖層類別／圖層 → 按確定開啟","level":6,"lt":"✅","ver":"20221227","author":"Stefan M. 改寫、chengshunyi","video":"","fas":"fas/LAYER_ON.fas"},{"no":988,"file":"LayerColorTool-D.LSP","cmd":"LayerColorTool、LCT","cat":"圖層","desc":"連續選取物件收集圖層與顏色並顯示於清單對話框，可儲存／載入 TXT，並可一鍵開啟與解凍清單內圖層。","usage":"執行 LCT → 連續選取物件 Enter 結束 → 於對話框檢視／刪除項目、儲存或載入、按顯示圖層","level":6,"lt":"✅","ver":"最終且最高兼容性修復版(2025-12-03 檔案日期)","author":"—","video":"","fas":"fas/LayerColorTool-D.fas"},{"no":989,"file":"LayerColorTool.lsp","cmd":"LayerColorTool、LCT","cat":"圖層","desc":"連續選取物件收集圖層與顏色並顯示於清單對話框，可儲存／載入 TXT，並可一鍵開啟與解凍清單內圖層。","usage":"執行 LCT → 連續選取物件 Enter 結束 → 於對話框檢視／刪除項目、儲存或載入、按顯示圖層","level":6,"lt":"✅","ver":"最終且最高兼容性修復版(2025-12-03 檔案日期)","author":"—","video":"","fas":"fas/LayerColorTool.fas"},{"no":990,"file":"LayerExtract.lsp","cmd":"LX、LayerExtract","cat":"圖層","desc":"掃描所選資料夾（含子資料夾）內所有 DWG，彙整各圖的圖層結構（顏色、線型、線寬等）並輸出報表。","usage":"執行 LX → 於對話框選擇資料夾與輸出選項 → 按確定產生報表","level":8,"lt":"❌","ver":"V1.4 28-04-2011","author":"Lee Mac","video":"","fas":"fas/LayerExtract.fas"},{"no":991,"file":"LayerQuellPick.lsp","cmd":"LOP、LOPN、LFP、LFPN、LLP、LuLP、LLPN、LuLPN","cat":"圖層","desc":"點選物件後對其圖層執行關閉、凍結、鎖定或解鎖，N 結尾版本可點選嵌套物件，必要時自動切換目前圖層。","usage":"輸入 LOP／LFP／LLP 等指令 → 點選物件 → 該圖層即被關閉／凍結／鎖定","level":5,"lt":"✅","ver":"20240908","author":"chengshunyi（改自 Layer Quell）","video":"","fas":"fas/LayerQuellPick.fas"},{"no":992,"file":"LayerResetAll.lsp","cmd":"LayerResetAll","cat":"圖層","desc":"一鍵重設圖層狀態：解凍、開啟、解鎖所有圖層，遇到受限圖層（如目前層）自動略過。","usage":"執行 LayerResetAll → 自動處理全部圖層並重生圖面","level":3,"lt":"✅","ver":"2025-12-22(檔案日期)","author":"—","video":"","fas":"fas/LayerResetAll.fas"},{"no":993,"file":"LayerS2Drawing.lsp","cmd":"LayerS2Drawing","cat":"轉檔/匯出入","desc":"選取物件後依其圖層，將各圖層內容以 WBLOCK 分別輸出成獨立 DWG 檔到指定資料夾。","usage":"執行 LayerS2Drawing → 框選物件 → 選擇輸出資料夾 → 自動依圖層輸出 DWG","level":5,"lt":"⚠️","ver":"20220716更新","author":"Lee Mac（Layers2Drawings 改版）","video":"","fas":"fas/LayerS2Drawing.fas"},{"no":994,"file":"Layers2Drawings.lsp","cmd":"Layers2Drawings","cat":"轉檔/匯出入","desc":"將圖面所有作用中圖層分別 WBLOCK 成獨立 DWG 檔，存到指定資料夾。","usage":"執行 Layers2Drawings → 選擇輸出資料夾 → 自動每圖層輸出一個 DWG","level":5,"lt":"⚠️","ver":"20220716更新","author":"Lee Mac","video":"","fas":"fas/Layers2Drawings.fas"},{"no":995,"file":"LayerState-Manager.lsp","cmd":"up-a0、up-a1、up-a3、up-a4、up-a5、rst-a0、rst-a1、rst-a3、rst-a4、rst-a5","cat":"圖層","desc":"預設 A0 拆除、A1 隔間、A3 天花、A4 完成、A5 家具五組圖層狀態，up-aN 更新儲存、rst-aN 一鍵還原。","usage":"設定好圖層顯示 → 輸入 up-a1 儲存狀態 → 之後輸入 rst-a1 還原","level":3,"lt":"✅","ver":"2025-12-09(檔案日期)","author":"—","video":"https://youtu.be/gF3j1m0wqwo","fas":"fas/LayerState-Manager.fas"},{"no":996,"file":"layout-add-str.lsp","cmd":"layout-add-str-pak、layout-add-str-dd、layout-add-str-per","cat":"出圖/列印","desc":"在目前配置頁籤名稱尾端加註「_發包圖_」「_細設圖_」「_建照圖_」，已加註則不重複。","usage":"切換到要標示的配置頁籤 → 執行對應指令 → 頁籤名稱自動加註","level":3,"lt":"✅","ver":"20250517","author":"chengshunyi","video":"","fas":"fas/layout-add-str.fas"},{"no":997,"file":"LayoutsToDwgs.lsp","cmd":"LayoutsToDwgs","cat":"轉檔/匯出入","desc":"將圖檔中每個非空白的配置（Layout）各別 WBLOCK 輸出成獨立 DWG，可指定檔名前綴與後綴。","usage":"執行 LayoutsToDwgs → 輸入檔名前綴 → 輸入檔名後綴 → 自動逐一輸出","level":5,"lt":"✅","ver":"2016-10-26","author":"Jimmy Bergmark (JTB World)","video":"","fas":"fas/LayoutsToDwgs.fas"},{"no":998,"file":"LBL(不規則2pline畫中心線).LSP","cmd":"LBL","cat":"繪圖","desc":"選取兩條開放曲線（線、弧、多段線、雲形線），依各頂點中點產生兩曲線之間的中心線多段線。","usage":"執行 LBL → 選第一條開放曲線 → 選下一條開放曲線 → 產生中心線","level":7,"lt":"✅","ver":"20230115","author":"Alan J. Thompson（chengshunyi 修改）","video":"","fas":"fas/LBL(不規則2pline畫中心線).fas"},{"no":999,"file":"LEG-DET.lsp","cmd":"LEG-DET","cat":"圖塊/屬性","desc":"以幻燈片圖示對話框挑選細部設計圖塊並插入，圖塊庫位於 SUPPORT4\\TG_DET，可開啟設定檔編輯。","usage":"執行 LEG-DET → 於對話框點選圖示 → 指定插入點與比例","level":6,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/LEG-DET.fas"},{"no":1000,"file":"LEG-LIB.lsp","cmd":"LEG-LIB","cat":"圖塊/屬性","desc":"以幻燈片圖示對話框挑選圖例庫圖塊（人物等）並插入，圖塊庫位於 SUPPORT4\\LIB，可開啟設定檔編輯。","usage":"執行 LEG-LIB → 於對話框點選圖示 → 指定插入點","level":6,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/LEG-LIB.fas"},{"no":1001,"file":"LenCal V1.7.lsp","cmd":"LenCal","cat":"面積/數量統計","desc":"計算選取物件的總長度，可依圖層、線型、顏色過濾，輸出成 AutoCAD 表格、TXT 或 CSV。","usage":"執行 LenCal → 於對話框設定過濾條件與輸出方式 → 選取物件 → 產生結果","level":8,"lt":"⚠️","ver":"V1.7","author":"Lee McDonnell (Lee Mac)","video":"","fas":"fas/LenCal V1.7.fas"},{"no":1002,"file":"LengthAreaField.lsp","cmd":"lf、lfm、lfmu、af、afm、afmu、afp、afpu","cat":"面積/數量統計","desc":"產生引用選取物件長度或面積的欄位運算式，可輸出成 mtext、表格儲存格或既有文字，支援 m、m2、坪換算。","usage":"輸入 lf／af 等指令 → 選取物件 → 指定文字插入點或表格儲存格","level":7,"lt":"✅","ver":"Lee Mac 版（檔案日期 2024-06-22）","author":"Lee Mac（chengshunyi 增修坪等單位）","video":"","fas":"fas/LengthAreaField.fas"},{"no":1003,"file":"LENGTHS.LSP","cmd":"lengths、bom_lines、bom_arcs、bom_polylines、bom_splines","cat":"面積/數量統計","desc":"統計選取之線、弧、多段線、雲形線的總長度，可選類型，依目前單位顯示結果。","usage":"執行 lengths → 輸入類型 Lines/Arcs/Polylines/Splines/ALL → 選取物件 → 顯示總長","level":4,"lt":"✅","ver":"2007-09-24","author":"Jimmy Bergmark (JTB World)","video":"","fas":"fas/LENGTHS.fas"},{"no":1004,"file":"lin-mid-pro.LSP","cmd":"lin-mid-pro","cat":"繪圖","desc":"點選兩條線自動以偏移、圓角與合併產生中心線多段線，放在 wall-cl 圖層，可連續操作。","usage":"執行 lin-mid-pro → 點選第一條線 → 點選第二條線 → 產生中心線 → Enter 結束","level":5,"lt":"✅","ver":"20240804","author":"chengshunyi（原 Alan H 2018）","video":"","fas":"fas/lin-mid-pro.fas"},{"no":1005,"file":"line-2-int.LSP","cmd":"line-2-int","cat":"修改","desc":"將選取線段兩端點座標修改為 0.5 的倍數，單位 cm 時使用，排除鎖定圖層。","usage":"執行 line-2-int → 選取線段 → 端點自動取整到 0.5","level":3,"lt":"✅","ver":"20241002","author":"chengshunyi","video":"","fas":"fas/line-2-int.fas"},{"no":1006,"file":"line-draw-wc-m.LSP","cmd":"line-draw-wc-m","cat":"繪圖","desc":"選取一條線後以對話框設定廁所隔間數、寬度、門與厚度，自動沿線繪製男廁隔間（含馬桶圖塊）。","usage":"執行 line-draw-wc-m → 選取線 → 於對話框輸入隔間參數 → 確定自動繪製","level":7,"lt":"✅","ver":"20231217","author":"chengshunyi","video":"","fas":"fas/line-draw-wc-m.fas"},{"no":1007,"file":"line-draw-wc.lsp","cmd":"line-draw-wc、mpt3","cat":"繪圖","desc":"選取一條線後以對話框設定廁所隔間數、深寬、門與厚度，自動繪製廁所隔間與蹲式／坐式馬桶配置。","usage":"執行 line-draw-wc → 選取線 → 於對話框輸入隔間參數 → 確定自動繪製","level":9,"lt":"✅","ver":"2026-10-17(檔案日期)","author":"chengshunyi","video":"","fas":"fas/line-draw-wc.fas"},{"no":1008,"file":"line-to-inte.lsp","cmd":"line-to-inte1、line-to-inte0","cat":"修改","desc":"將選取線段端點座標取整數或小數點 1 位（0.5 檢查），並提示修改的線數。","usage":"執行 line-to-inte1／inte0 → 選取線段 → 端點座標自動取整","level":4,"lt":"✅","ver":"2025/1/1、20250517","author":"chengshunyi","video":"","fas":"fas/line-to-inte.fas"},{"no":1009,"file":"linediv-2.lsp","cmd":"linediv-2","cat":"繪圖","desc":"選取兩條線，依等分數在兩線之間繪製等分連接線（預設 2 等分）。","usage":"執行 linediv-2 → 選兩條線 → 輸入等分數 → 繪出分隔線","level":4,"lt":"✅","ver":"20240803","author":"chengshunyi","video":"","fas":"fas/linediv-2.fas"},{"no":1010,"file":"linediv-m.lsp","cmd":"linediv-m","cat":"繪圖","desc":"選取兩條線，依輸入的等分數在兩線之間繪製等分連接線（預設 2 等分）。","usage":"執行 linediv-m → 選兩條線 → 輸入等分數 → 繪出分隔線","level":4,"lt":"✅","ver":"20240803","author":"chengshunyi","video":"","fas":"fas/linediv-m.fas"},{"no":1011,"file":"lines-mid.LSP","cmd":"lines-mid","cat":"繪圖","desc":"點選兩條線以偏移、圓角產生兩線中間的中心線，並可連續繪製，Enter 結束。","usage":"執行 lines-mid → 點選第一條線 → 點選第二條線 → 產生中心線 → Enter 結束","level":5,"lt":"✅","ver":"20240728","author":"chengshunyi（原 Alan H 2018）","video":"","fas":"fas/lines-mid.fas"},{"no":1012,"file":"linetype.lsp","cmd":"（無，副程式庫）","cat":"其他","desc":"線型工具函式庫：載入指定線型、檢查線型是否存在、清除所有未使用線型。","usage":"由其他程式呼叫，例如 (loadLinetype doc \"Divide\" \"acadiso.lin\")","level":3,"lt":"✅","ver":"20240218","author":"Jimmy Bergmark、chengshunyi","video":"","fas":"fas/linetype.fas"},{"no":1013,"file":"lins-d-mid.LSP","cmd":"lins-d-mid","cat":"繪圖","desc":"選兩條線以偏移與圓角畫出中心線，並自動建立「cl」圖層，抓最外側範圍。","usage":"執行 lins-d-mid → 點選第一條線 → 點選第二條線 → 產生中心線","level":5,"lt":"✅","ver":"2024","author":"chengshunyi（原 Alan H 2018）","video":"","fas":"fas/lins-d-mid.fas"},{"no":1014,"file":"list-draw_points.lsp","cmd":"draw_points","cat":"繪圖","desc":"於對話框貼入多行地號座標資料，依地號分組繪製各地號的封閉多段線。","usage":"執行 draw_points → 於對話框貼入座標資料 → 按繪製封閉 Pline","level":6,"lt":"✅","ver":"2025-01-19(檔案日期)","author":"ChatGPT 產生","video":"","fas":"fas/list-draw_points.fas"},{"no":1015,"file":"list-dwgs-layouts.LSP","cmd":"list-dwgs-layouts","cat":"轉檔/匯出入","desc":"選取資料夾後以 ObjectDBX 讀取其中所有 DWG 的配置名稱，輸出成 TXT 清單並以記事本開啟。","usage":"執行 list-dwgs-layouts → 選取圖檔資料夾 → 自動產生清單並開啟記事本","level":8,"lt":"❌","ver":"20230915","author":"chengshunyi（含 Lee Mac LM:ODBX）","video":"","fas":"fas/list-dwgs-layouts.fas"},{"no":1016,"file":"list2tablet.LSP","cmd":"（無，副程式庫）","cat":"其他","desc":"將清單資料逐列寫入 AutoCAD 表格物件各儲存格的函式（範例資料為設計費項目）。","usage":"由其他程式呼叫，傳入表格與資料清單","level":3,"lt":"✅","ver":"2023-02-27(檔案日期)","author":"—","video":"","fas":"fas/list2tablet.fas"},{"no":1017,"file":"ListAndCleanA$Blocks.LSP","cmd":"ListAndCleanA$Blocks","cat":"圖塊/屬性","desc":"收集圖面中所有 A$ 開頭的圖塊並列出，詢問後批次刪除（排除外部參照）。","usage":"執行 ListAndCleanA$Blocks → 檢視清單 → 輸入 Yes 確認刪除","level":4,"lt":"✅","ver":"2025-12-06(檔案日期)","author":"—","video":"","fas":"fas/ListAndCleanA$Blocks.fas"},{"no":1018,"file":"listbox-sample.lsp","cmd":"listbox-sample","cat":"其他","desc":"DCL 清單方塊（list_box）操作範例，動態產生 DCL 並示範項目選取。","usage":"執行 listbox-sample → 於對話框選取清單項目","level":6,"lt":"✅","ver":"2024-12-08(檔案日期)","author":"—","video":"","fas":"fas/listbox-sample.fas"},{"no":1019,"file":"LISTDICTS.lsp","cmd":"LISTDICTS","cat":"其他","desc":"示範建立與讀取自訂字典（CC_DICT）及 Xrecord（CC_VAR），存取文字樣式等設定值。","usage":"執行 LISTDICTS → 顯示或建立自訂字典資料","level":6,"lt":"✅","ver":"2023-02-11(檔案日期)","author":"—","video":"","fas":"fas/LISTDICTS.fas"},{"no":1020,"file":"LIT-1.LSP","cmd":"lit-1","cat":"繪圖","desc":"指定 A、B 兩點，暫時關閉物件鎖點後繪製多段線並修剪，建立燈具之類的簡易符號（短程式）。","usage":"執行 lit-1 → 指定 A 點 → 指定 B 點 → 自動繪製並修剪","level":2,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/LIT-1.fas"},{"no":1021,"file":"LIT-2.LSP","cmd":"lit-2","cat":"繪圖","desc":"指定 A、B 兩點，關閉鎖點後繪製多段線與直線並修剪，建立簡易符號（短程式）。","usage":"執行 lit-2 → 指定 A 點 → 指定 B 點 → 自動繪製","level":2,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/LIT-2.fas"},{"no":1022,"file":"LIT-3.LSP","cmd":"lit-3","cat":"繪圖","desc":"指定 A、B 兩點，關閉鎖點後繪製多段線與直線並修剪，建立簡易符號（短程式）。","usage":"執行 lit-3 → 指定 A 點 → 指定 B 點 → 自動繪製","level":2,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/LIT-3.fas"},{"no":1023,"file":"LIT-4.LSP","cmd":"lit-4","cat":"繪圖","desc":"指定 A、B 兩點，關閉鎖點後依兩點繪製多段線符號（短程式）。","usage":"執行 lit-4 → 指定 A 點 → 指定 B 點 → 自動繪製","level":2,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/LIT-4.fas"},{"no":1024,"file":"LIT-5.LSP","cmd":"lit-5","cat":"繪圖","desc":"指定 A、B 兩點，關閉鎖點後繪製多段線與直線並修剪，建立簡易符號（短程式）。","usage":"執行 lit-5 → 指定 A 點 → 指定 B 點 → 自動繪製","level":2,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/LIT-5.fas"},{"no":1025,"file":"LIT-6.LSP","cmd":"lit-6","cat":"繪圖","desc":"指定 A、B 兩點，關閉鎖點後繪製多段線與直線並修剪，建立簡易符號（短程式）。","usage":"執行 lit-6 → 指定 A 點 → 指定 B 點 → 自動繪製","level":2,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/LIT-6.fas"},{"no":1026,"file":"LL-To-i-u.lsp","cmd":"LL-To-i-u","cat":"修改","desc":"將選取線段長度修改為整數倍（四捨五入、無條件進位或捨去可選），以中點為準調整端點。","usage":"執行 LL-To-i-u → 選取線段 → 線長自動取整","level":4,"lt":"✅","ver":"20240417","author":"chengshunyi","video":"","fas":"fas/LL-To-i-u.fas"},{"no":1027,"file":"lml.lsp","cmd":"lml","cat":"繪圖","desc":"選取線、多段線或多線，依其路徑以目前多線樣式（含 -OPEN 樣式）重繪成多線 MLINE。","usage":"執行 lml → 選取 LINE／LWPOLYLINE／MLINE → 產生多線","level":5,"lt":"✅","ver":"2008.05.10","author":"—","video":"","fas":"fas/lml.fas"},{"no":1028,"file":"LoadLinetypesV1-3.lsp","cmd":"（無，副程式庫）","cat":"其他","desc":"線型載入函式庫：由支援路徑的 .lin 檔載入指定線型，依 MEASUREMENT 排除公制或英制定義檔，並可檢查線型是否定義。","usage":"由其他程式呼叫 (LM:loadlinetypes ...)","level":4,"lt":"✅","ver":"V1.3","author":"Lee Mac","video":"","fas":"fas/LoadLinetypesV1-3.fas"},{"no":1029,"file":"LOGO-MYCAD.lsp","cmd":"（無，副程式庫）","cat":"其他","desc":"在 DCL 影像按鈕內以向量繪製 MyCAD 標誌的函式，供各對話框右下角使用。","usage":"由其他程式呼叫，傳入 DCL 影像元件 key","level":4,"lt":"✅","ver":"2024-11-23(檔案日期)","author":"ChengBar (MyCAD)","video":"https://youtu.be/rck6VLloW6Q","fas":"fas/LOGO-MYCAD.fas"},{"no":1030,"file":"LSExport.lsp","cmd":"LSExport","cat":"圖面管理","desc":"以對話框選擇圖層狀態並匯出成 .las 檔，可瀏覽儲存目錄與檔名，相容 LT。","usage":"執行 LSExport → 於對話框選圖層狀態與儲存路徑 → 按確定匯出","level":6,"lt":"⚠️","ver":"2026-11-09(檔案日期)","author":"ChengBar (MyCAD)","video":"https://youtu.be/tLnYKAtyApY","fas":"fas/LSExport.fas"},{"no":1031,"file":"LSImport.lsp","cmd":"LSImport","cat":"圖面管理","desc":"以對話框選擇 .las 檔並匯入圖層狀態，相容 LT。","usage":"執行 LSImport → 於對話框瀏覽 .las 檔案 → 按確定匯入","level":6,"lt":"✅","ver":"2026-11-09(檔案日期)","author":"ChengBar (MyCAD)","video":"https://youtu.be/lY2jJ7zuGAY","fas":"fas/LSImport.fas"},{"no":1032,"file":"LSP2FAS-2024.lsp","cmd":"LSP2FAS-Help、LSP2FAS","cat":"轉檔/匯出入","desc":"選取一個 .lsp 檔並以 vlisp-compile 編譯為同資料夾的 .fas，另附說明指令。","usage":"執行 LSP2FAS → 選取 .lsp 檔 → 產生 .fas","level":2,"lt":"❌","ver":"2012-11-29（2024 版）","author":"Scot Harris（原 aqdam1978）","video":"","fas":"fas/LSP2FAS-2024.fas"},{"no":1033,"file":"LSP2FAS-new.lsp","cmd":"LSP2FAS-Help、LSP2FAS","cat":"轉檔/匯出入","desc":"選取一個 .lsp 檔並以 vlisp-compile 編譯為同資料夾的 .fas，另附說明指令。","usage":"執行 LSP2FAS → 選取 .lsp 檔 → 產生 .fas","level":2,"lt":"❌","ver":"2012-11-29","author":"Scot Harris（原 aqdam1978）","video":"","fas":"fas/LSP2FAS-new.fas"},{"no":1034,"file":"lsp2fas.lsp","cmd":"lsp2fas","cat":"轉檔/匯出入","desc":"選擇資料夾後產生批次編譯用的 SCR 草稿檔，將資料夾內所有 lsp 轉為 fas。","usage":"執行 lsp2fas → 選擇 lsp 目錄 → 按 Enter 產生 scr → 以 SCRIPT 執行","level":4,"lt":"❌","ver":"2008.06.18","author":"Design By Cheng Shun-Yi","video":"","fas":"fas/lsp2fas.fas"},{"no":1035,"file":"LspToFas.LSP","cmd":"LspToFas","cat":"轉檔/匯出入","desc":"以對話框選擇目錄，批次將其中所有 .lsp 編譯為 .fas，編譯前檢查括號平衡並寫入錯誤記錄檔。","usage":"執行 LspToFas → 於對話框選擇目錄 → 按開始轉換 → 查看記錄","level":8,"lt":"❌","ver":"v1.2 (2026-10-17)","author":"ChengBar (MyCAD)","video":"","fas":""},{"no":1036,"file":"LSSVPorts.lsp","cmd":"LSSVPorts","cat":"圖層","desc":"依日期為模型空間、各配置頁籤與各視埠分別儲存圖層狀態，以便日後還原視埠圖層設定。","usage":"執行 LSSVPorts → 自動走訪模型、配置與視埠並以日期儲存圖層狀態","level":5,"lt":"✅","ver":"20250104、20250706","author":"chengshunyi","video":"","fas":"fas/LSSVPorts.fas"},{"no":1037,"file":"lwpTo3d.LSP","cmd":"testlwpto3d、mlwpto3d","cat":"3D","desc":"將選取的輕量多段線轉換為 3D 多段線（函式 lwpTo3d），testlwpto3d 為測試指令。","usage":"執行 testlwpto3d → 選取 LWPolyLine → 轉為 3D 多段線","level":4,"lt":"✅","ver":"20220716更新","author":"—（Autodesk 範例改寫）","video":"","fas":"fas/lwpTo3d.fas"},{"no":1038,"file":"M-AREA.LSP","cmd":"m-area","cat":"面積/數量統計","desc":"以對話框設定圖紙、單位與比例後選取封閉範圍，計算面積並依比例與單位換算標註。","usage":"執行 m-area → 於對話框設定單位與比例 → 選取封閉物件／點選範圍 → 標註面積","level":6,"lt":"✅","ver":"86.8.13（民國）","author":"—（MyCAD）","video":"","fas":"fas/M-AREA.fas"},{"no":1039,"file":"m-bd-2-pp-c.lsp","cmd":"m-bd-c-a1-cm-c、m-bd-c-a1-cm-i、m-bd-c-a1-mm-c、m-bd-c-a1-mm-i、m-bd-c-a3-cm-c、m-bd-c-a3-cm-i、m-bd-c-a3-mm-c、m-bd-c-a3-mm-i、m-bd-2-pp-c","cat":"對齊/排列","desc":"選取物件移動，使其邊界框中心對齊到 A1 或 A3 圖框（cm/mm、中心/內縮）預設位置或另選目標物件的中心。","usage":"輸入對應指令 → 選取要移動的物件 → 自動移到圖框預設位置","level":5,"lt":"✅","ver":"20240202","author":"chengshunyi（原 Ronjonp、Alan H）","video":"","fas":"fas/m-bd-2-pp-c.fas"},{"no":1040,"file":"M-DimCfg.lsp","cmd":"M-DimCfg","cat":"標註","desc":"以對話框設定單位、比例、字高、字寬、小數點、字距與圖層，重設並建立尺寸標註樣式，可標示為 m。","usage":"執行 M-DimCfg → 於對話框設定各項參數 → 按確定套用","level":7,"lt":"✅","ver":"2025-08-17(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/M-DimCfg.fas"},{"no":1041,"file":"m-mtext.LSP","cmd":"m-mtext","cat":"文字","desc":"指定插入點以 entmake 建立多行文字（樣式 My_Style），並呼叫 MTEDIT 編輯。","usage":"執行 m-mtext → 指定插入點 → 編輯文字內容","level":3,"lt":"✅","ver":"2024-10-13(檔案日期)","author":"—","video":"","fas":"fas/m-mtext.fas"},{"no":1042,"file":"m-obj-2-obj-c.lsp","cmd":"m-obj-2-obj-c","cat":"對齊/排列","desc":"選取要移動的物件與目標物件，以兩者邊界框中心點為基準，將前者移到目標中心。","usage":"執行 m-obj-2-obj-c → 選取要移動的物件 → 選取目標物件 → 自動置中對齊","level":4,"lt":"✅","ver":"20240202","author":"chengshunyi（原 Ronjonp、Alan H）","video":"","fas":"fas/m-obj-2-obj-c.fas"},{"no":1043,"file":"m-walk-dim-sty.lsp","cmd":"m-walk-dim-sty","cat":"標註","desc":"建立並套用「步行距離」標註樣式，設定換算單位、箭頭、延伸線與線性比例係數（CM 換算 M）。","usage":"執行 m-walk-dim-sty → 自動建立並設定標註樣式","level":3,"lt":"✅","ver":"20220716更新","author":"chengshunyi","video":"","fas":"fas/m-walk-dim-sty.fas"},{"no":1044,"file":"MacAtt.lsp","cmd":"MacAttExt、MacAttEdit、MacAtt","cat":"圖塊/屬性","desc":"全域圖塊屬性編輯器與萃取器：批次編輯多張圖或擷取指定圖塊屬性並輸出到 Excel，可含子目錄。","usage":"執行 MacAtt → 選擇 Editor 或 eXtractor → 於對話框設定圖塊清單與選項 → 執行","level":9,"lt":"❌","ver":"3.11（中文化 2021）","author":"Lee Mac","video":"https://youtu.be/Jh3xO9nL7Fs","fas":"fas/MacAtt.fas"},{"no":1045,"file":"Make3dimBlock.lsp","cmd":"Make3dimBlock","cat":"標註","desc":"以 entmake 建立標註用符號圖塊（圓形、斜線、120 度箭頭等）並插入。","usage":"執行 Make3dimBlock → 自動建立圖塊並插入","level":6,"lt":"✅","ver":"2025-09-05(檔案日期)","author":"—","video":"","fas":"fas/Make3dimBlock.fas"},{"no":1046,"file":"MAKE3dsolidselLINES.LSP","cmd":"MAKE3dsolidselLINES","cat":"3D","desc":"選取多條 LINE 取端點，依質心角度排序建立封閉 LWPOLYLINE，並擠出為高度 50 的 3D 實體。","usage":"執行 MAKE3dsolidselLINES → 選取多條線段 → 自動建立封閉聚合線並擠出","level":7,"lt":"❌","ver":"2025-11-27(檔案日期)","author":"—","video":"","fas":"fas/MAKE3dsolidselLINES.fas"},{"no":1047,"file":"Make4dimBlock-UI.lsp","cmd":"Make4dimBlock-UI","cat":"標註","desc":"以對話框輸入顏色編號，建立或強制更新尺寸箭頭圖塊（cir、dot、slash、Arr120、arr）並重生圖面。","usage":"執行 Make4dimBlock-UI → 於對話框輸入或選取顏色 → 勾選是否覆蓋 → 按確定","level":6,"lt":"✅","ver":"2026-01-13(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/Make4dimBlock-UI.fas"},{"no":1048,"file":"Make4dimBlock.lsp","cmd":"Make4dimBlock","cat":"標註","desc":"以 entmake 建立五種尺寸箭頭圖塊（圓、點、斜線、120 度箭頭、箭頭）。","usage":"執行 Make4dimBlock → 自動建立圖塊","level":6,"lt":"✅","ver":"20250906","author":"chengshunyi","video":"https://youtu.be/PYogYzJBd7c","fas":"fas/Make4dimBlock.fas"},{"no":1049,"file":"Make6MLBlock.lsp","cmd":"Make6MLBlock","cat":"標註","desc":"以 entmake 建立 A-dot、A-ach、A-ach1、A-ach2、A-arr 等多重引線用箭頭／符號圖塊。","usage":"執行 Make6MLBlock → 自動建立多重引線符號圖塊","level":6,"lt":"✅","ver":"20250906","author":"chengshunyi","video":"https://youtu.be/JxbjC_oqtyU","fas":"fas/Make6MLBlock.fas"},{"no":1050,"file":"make_mleader_style-test.lsp","cmd":"msv","cat":"標註","desc":"以 VLA 建立自訂多重引線樣式（箭頭、文字、連接等屬性）並設為目前，示範範例。","usage":"執行 msv → 自動建立並套用多重引線樣式","level":5,"lt":"⚠️","ver":"2025-09-29(檔案日期)","author":"VVA（原作）","video":"","fas":"fas/make_mleader_style-test.fas"},{"no":1051,"file":"MakeDimBlocks.lsp","cmd":"CheckDimBlocks、CreateDimBlocks","cat":"標註","desc":"依名稱檢查並建立五個尺寸符號圖塊（cir、dot、slash、Arr120、arr），已存在則略過。","usage":"執行 CreateDimBlocks → 自動建立缺少的圖塊；CheckDimBlocks 檢查","level":5,"lt":"✅","ver":"20251029","author":"—","video":"","fas":"fas/MakeDimBlocks.fas"},{"no":1052,"file":"makedimstyle.lsp","cmd":"makedimstyle","cat":"標註","desc":"輸入比例後依比例（字高 0.25cm 等階梯）建立標註樣式，並插入 dim.dwg 底圖圖塊取得箭頭符號。","usage":"執行 makedimstyle → 輸入比例 → 自動建立標註樣式","level":6,"lt":"✅","ver":"20171119","author":"chengshunyi","video":"https://youtu.be/P_i_AgbX_7k","fas":"fas/makedimstyle.fas"},{"no":1053,"file":"MakeDirectory.lsp","cmd":"（無，副程式庫）","cat":"系統/授權","desc":"建立資料夾結構的函式 LM:MakeDirectory，包含多層子目錄，成功回傳 T。","usage":"由其他程式呼叫 (LM:MakeDirectory \"C:\\\\Folder\\\\Sub\")","level":3,"lt":"✅","ver":"2010","author":"Lee Mac (Lee McDonnell)","video":"","fas":""},{"no":1054,"file":"makml.lsp","cmd":"makml","cat":"標註","desc":"輸入名稱、說明與各線偏移值，以 entmake 建立自訂多線樣式（MLINESTYLE）。","usage":"執行 makml → 輸入樣式名稱 → 輸入說明 → 逐一輸入偏移值 → Enter 結束","level":6,"lt":"✅","ver":"Oct 2020","author":"Alan H（原 FIXO）","video":"","fas":"fas/makml.fas"},{"no":1055,"file":"MAP-NX.lsp","cmd":"MAP、MAPP、MAPL、MAPS、MAPR、MAPC、MAPCX、MAPD、MAPDX、MAPU、MAPUX、MAPN、MAPT","cat":"面積/數量統計","desc":"MyArea-Pro 不使用 XDATA 版：自動找封閉區域標註面積與編號，並產生計算式、空間性質統計、百分比、上色與重新編號。","usage":"執行 MAP → 選取線段／弧／多段線 → 自動標註面積；再用 MAPL／MAPS／MAPT 等圈選編號圖塊","level":9,"lt":"⚠️","ver":"2026-11-03（不使用圖塊版）","author":"ChengBar (MyCAD)","video":"https://youtu.be/mKn7ZT6DHeg","fas":"fas/MAP-NX.fas"},{"no":1056,"file":"MAP.lsp","cmd":"MAP、MAPP、MAPL、MAPS、MAPR、MAPC、MAPCX、MAPD、MAPDX、MAPUX、MAPU、MAPN、MAPT","cat":"面積/數量統計","desc":"MyArea-Pro 整合版：自動找封閉區域標註面積與編號，並產生計算式、空間性質統計、百分比、上色與重新編號（使用 XDATA）。","usage":"執行 MAP → 選取線段／弧／多段線 → 自動標註面積；再用 MAPL／MAPS／MAPT 等圈選編號圖塊","level":9,"lt":"⚠️","ver":"2026-11-03（檔案日期 2026-11-04）","author":"ChengBar (MyCAD)","video":"","fas":"fas/MAP.fas"},{"no":1057,"file":"match-dyblk.lsp","cmd":"（無，副程式庫）","cat":"圖塊/屬性","desc":"取得與設定動態圖塊屬性值及圖塊屬性文字的函式庫（Lee Mac），用於將來源圖塊參數與屬性複製到目標圖塊。","usage":"由其他程式呼叫；亦可選取來源與目標圖塊對照","level":6,"lt":"✅","ver":"2025-06-15(檔案日期)","author":"Lee Mac","video":"","fas":"fas/match-dyblk.fas"},{"no":1058,"file":"MATCH1.LSP","cmd":"MATCH1","cat":"圖層","desc":"選取一個物件，將目前圖層設為該物件所在的圖層。","usage":"執行 MATCH1 → 選取物件 → 目前圖層切換","level":2,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/MATCH1.fas"},{"no":1059,"file":"MATCH2.LSP","cmd":"MATCH2","cat":"修改","desc":"選取多個物件並指定屬性（顏色、高程、圖層、線型、厚度、插入點），再選取來源物件將其屬性套用到前者。","usage":"執行 MATCH2 → 選取要修改的物件 → 輸入要比對的屬性 → 選取來源物件","level":4,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/MATCH2.fas"},{"no":1060,"file":"MATCH3.LSP","cmd":"MATCH3","cat":"圖層","desc":"開啟全部圖層後，選取物件並將其所在圖層關閉，若包含目前圖層會先詢問確認。","usage":"執行 MATCH3 → 選取要關閉其圖層的物件 → 確認關閉目前層（如需要）","level":3,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/MATCH3.fas"},{"no":1061,"file":"MatchAttribs.lsp","cmd":"MatchAttribs","cat":"圖塊/屬性","desc":"選取來源屬性後，將其指定的屬性文字特性（樣式、字高、圖層等）套用到後續選取的屬性。","usage":"執行 MatchAttribs → 選來源屬性 → 選目標屬性 → Enter 結束","level":5,"lt":"✅","ver":"20220716更新","author":"Lee Mac","video":"","fas":"fas/MatchAttribs.fas"},{"no":1062,"file":"MatchFieldFormatting.lsp","cmd":"mff","cat":"文字","desc":"自來源欄位（Field）複製格式設定，套用到多個目的欄位，支援文字、屬性、多重引線與標註。","usage":"執行 mff → 選取來源欄位物件 → 連續選取目的欄位 → Enter 結束","level":7,"lt":"✅","ver":"Lee Mac（檔案日期 2022-08-21）","author":"Lee Mac","video":"","fas":"fas/MatchFieldFormatting.fas"},{"no":1063,"file":"MatchTextProps.lsp","cmd":"MTP、MatchTextProps","cat":"文字","desc":"選取來源文字、多行文字或屬性，將其樣式、字高等特性比對套用到後續選取的同類物件。","usage":"執行 MTP → 選來源物件 → 選目標物件 → Enter 結束","level":5,"lt":"✅","ver":"20220716更新","author":"Lee Mac","video":"","fas":"fas/MatchTextProps.fas"},{"no":1064,"file":"MCLAYSHOW.lsp","cmd":"MCLAYSHOW","cat":"圖層","desc":"點選起點，將圖面每個圖層畫成一條線，右側寫出圖層名、顏色、線型與說明，文字樣式與字高可於對話框設定。","usage":"執行 MCLAYSHOW → 於對話框選文字樣式與字高 → 點選起點 → 自動畫出圖層列表","level":8,"lt":"⚠️","ver":"v1.3.0 2026-11-11","author":"ChengBar (MyCAD)","video":"","fas":"fas/MCLAYSHOW.fas"},{"no":1065,"file":"MCTEXTLT.lsp","cmd":"MCTEXTLT","cat":"文字","desc":"對話框輸入文字、字高、線段長、圖層與顏色，自動建立含文字的複合線型並繪製或套用到圖形，文字保持正向。","usage":"執行 MCTEXTLT → 於對話框設定文字與線型 → 選擇繪製圖形或選取既有曲線","level":9,"lt":"⚠️","ver":"v1.2.2 2026-11-06","author":"ChengBar (MyCAD)","video":"https://youtu.be/DPcxwB9Y_n8","fas":"fas/MCTEXTLT.fas"},{"no":1066,"file":"menu_load_123.lsp","cmd":"menuload_my_archi_cad、menuload_mytoolbar、menuload_pro、menuload_tg_0、menuload_tg、menuload_tg2","cat":"系統/授權","desc":"卸載並載入 MyCAD 各系列 CUIX 選單與下拉選單（my_archi_cad、MY_CAD、my_cad_pro、mytoolbar 等）。","usage":"執行 menuload_xxx → 自動卸載並載入對應 cuix","level":4,"lt":"✅","ver":"2023-12-23(檔案日期)","author":"—","video":"","fas":""},{"no":1067,"file":"merge-pl.lsp","cmd":"merge-pl、outline","cat":"繪圖","desc":"選取多個物件，以 BOUNDARY 沿外緣產生單一封閉多段線輪廓，可選擇是否刪除原物件。","usage":"執行 merge-pl → 選取物件 → 輸入是否刪除原物件 → 產生外框","level":6,"lt":"✅","ver":"20250621（原 Lee Mac V1.0 2014-11-30）","author":"chengshunyi（原 Lee Mac）","video":"https://youtu.be/wWlA2IBPWo0","fas":"fas/merge-pl.fas"},{"no":1068,"file":"MergeHatch.lsp","cmd":"MergeHatch、MH","cat":"修改","desc":"選取一個填充圖樣作為依據，再選取多個填充物件，合併為單一 Hatch 物件。","usage":"執行 MH → 選取填充圖樣 → 選取要合併的填充 → 完成合併","level":6,"lt":"✅","ver":"2011-11-20","author":"Juan Villarreal（massoc 為 Jaysen Long）","video":"","fas":"fas/MergeHatch.fas"},{"no":1069,"file":"MinDistLine(兩個物體之間的最近距離).LSP","cmd":"MinDist、MD、MinDistMove、MDM、MinDistCopy、MDC、MinDistLine、MDL","cat":"查詢","desc":"求兩個曲線物件（線、圓、弧、橢圓、多段線、雲形線）間的最短距離，並可據此移動、複製或畫出最短連線。","usage":"執行 MD → 選取第一個物件 → 選取第二個物件 → 顯示距離（MDM 移動／MDC 複製／MDL 畫線）","level":8,"lt":"✅","ver":"1.0 5/28/2008","author":"Joe Burke、Charles Alan Butler、VovKa（TheSwamp）","video":"","fas":"fas/MinDistLine(兩個物體之間的最近距離).fas"},{"no":1070,"file":"MJOIN-MV.LSP","cmd":"MJOIN-MV","cat":"修改","desc":"結合兩條多線 MLINE（支援多節點），依第一條屬性重組頂點，共線則簡化、不共線則算交點，並刪除原物件。","usage":"執行 MJOIN-MV → 選取第一條 MLINE → 選取第二條 MLINE → 自動結合","level":7,"lt":"✅","ver":"2026-01-17(檔案日期)","author":"—","video":"","fas":"fas/MJOIN-MV.fas"},{"no":1071,"file":"MJOIN.LSP","cmd":"MJOIN","cat":"修改","desc":"結合兩條 MLINE，依第一條的樣式、比例與對正，共線則取兩遠端點，否則算交點轉折並刪除原物件。","usage":"執行 MJOIN → 選取第一條 MLINE → 選取第二條 MLINE → 自動結合","level":6,"lt":"✅","ver":"2026-01-16(檔案日期)","author":"—","video":"","fas":"fas/MJOIN.fas"},{"no":1072,"file":"mkslid.lsp","cmd":"mk-slide","cat":"系統/授權","desc":"指定矩形兩角點，調整視窗大小後以 MSLIDE 製作幻燈片（.sld），並還原螢幕尺寸。","usage":"執行 mk-slide → 指定兩個對角點 → 自動產生幻燈片","level":6,"lt":"✅","ver":"20230102","author":"chengshunyi","video":"","fas":""},{"no":1073,"file":"ml-2p-60d.lsp","cmd":"ml-2p-60d","cat":"標註","desc":"指定兩點，依左右方向建立 60 度引線的多重引線（喬木樹穴面積檢討 RLD／RLU 樣式），並自動建立樣式。","usage":"執行 ml-2p-60d → 選取第一點 → 選取第二點 → 輸入文字","level":7,"lt":"✅","ver":"20240501（原 Cadalyst 2008）","author":"chengshunyi（原 Lyle Hardin）","video":"","fas":"fas/ml-2p-60d.fas"},{"no":1074,"file":"ml-entmake.LSP","cmd":"msv-u、msv-d","cat":"標註","desc":"以 VLA 建立客製多重引線樣式「喬木樹穴面積檢討-RLU／RLD」（點狀箭頭、文字附著設定）。","usage":"執行 msv-u 或 msv-d → 自動建立並套用樣式","level":6,"lt":"⚠️","ver":"20240501","author":"chengshunyi（原 VVA）","video":"","fas":"fas/ml-entmake.fas"},{"no":1075,"file":"ML-F-EL.lsp","cmd":"ML-F-EL","cat":"標註","desc":"以對話框設定單位、前綴與小數位，將多重引線 Y 座標換算為標高（EL）寫入屬性標籤或文字內容。","usage":"執行 MLF → 於對話框設定屬性標籤、前綴、單位 → 選取多重引線 → 自動寫入標高","level":7,"lt":"✅","ver":"2026-03-23(檔案日期)","author":"—","video":"","fas":"fas/ML-F-EL.fas"},{"no":1076,"file":"ml_set_dgl_by_xy_anno_ui.LSP","cmd":"ml_set_dgl_by_xy_anno_ui","cat":"標註","desc":"以對話框設定固定水平段長度與 X 或 Y 對齊模式，將多重引線的 dogleg 依參考點對齊，並考慮註解比例。","usage":"執行 ml_set_dgl_by_xy_anno_ui → 於對話框設定長度與模式 → 點選參考點 → 選取多重引線","level":7,"lt":"✅","ver":"2026-03-22(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/ml_set_dgl_by_xy_anno_ui.fas"},{"no":1077,"file":"ml_set_dogleg_by_x_anno.lsp","cmd":"ml_set_dogleg_by_x_anno","cat":"標註","desc":"點選 X 參考點後，將所選多重引線的轉折點 X 對齊並調整 dogleg 長度，可處理註解式引線比例。","usage":"執行 ml_set_dogleg_by_x_anno → 點選 X 對齊參考點 → 選取多重引線","level":7,"lt":"✅","ver":"2026-03-21(檔案日期)","author":"—","video":"","fas":"fas/ml_set_dogleg_by_x_anno.fas"},{"no":1078,"file":"ml_set_dogleg_by_xy_anno.lsp","cmd":"ml_set_dogleg_by_xy_anno","cat":"標註","desc":"輸入固定 dogleg 水平段長度並選 X/Y 對齊軸向，點選參考點後對齊所選多重引線轉折點，記憶上次輸入。","usage":"執行 ml_set_dogleg_by_xy_anno → 輸入長度 → 選 X 或 Y → 點選參考點 → 選取多重引線","level":7,"lt":"✅","ver":"2026-03-22(檔案日期)","author":"—","video":"","fas":"fas/ml_set_dogleg_by_xy_anno.fas"},{"no":1079,"file":"MLA-pro.LSP","cmd":"MLA-pro","cat":"標註","desc":"將多重引線第一段角度調成右 60 度、左 120 度，並依 P2 的 Y 座標由低到高以字高倍數垂直堆疊對齊。","usage":"執行 MLA-pro → 選取多條多重引線 → 自動調角度並堆疊","level":7,"lt":"✅","ver":"2025-11-25(檔案日期)","author":"—","video":"https://youtu.be/qDpVzqMMHvg","fas":"fas/MLA-pro.fas"},{"no":1080,"file":"MLA-pro2.LSP","cmd":"MLA-pro2、mleader_set_dogleg_by_xlowest","cat":"標註","desc":"兩步驟：把多重引線角度調成 60/120 度（不堆疊），再讓 dogleg 長度對齊最低點 P2 的 X。","usage":"執行 MLA-pro2 → 選取多條多重引線 → 自動調角度並對齊 dogleg","level":7,"lt":"✅","ver":"20251125","author":"chengshunyi","video":"https://youtu.be/nUh9GX71uL0","fas":"fas/MLA-pro2.fas"},{"no":1081,"file":"MLA-pro3.LSP","cmd":"MLA-pro3、mleader_set_dogleg_by_xlowest","cat":"標註","desc":"三步驟：調整多重引線角度、依字高與行數堆疊行距、dogleg 對齊最低點，優化 MLA-pro。","usage":"執行 MLA-pro3 → 選取多條多重引線 → 自動調角度、行距與 dogleg","level":7,"lt":"✅","ver":"20251125","author":"chengshunyi","video":"https://youtu.be/zQj-TfVXjZU","fas":"fas/MLA-pro3.fas"},{"no":1082,"file":"MLA.lsp","cmd":"MLA","cat":"標註","desc":"將所選多重引線調整為右側 60 度、左側 120 度，保持箭頭位置與文字高度不變，只移動水平位置。","usage":"執行 MLA → 選取多重引線 → 角度自動調整","level":5,"lt":"✅","ver":"2025-11-24(檔案日期)","author":"—","video":"","fas":"fas/MLA.fas"},{"no":1083,"file":"MLAa.LSP","cmd":"MLAa","cat":"標註","desc":"進階版：輸入引線角度（預設 60，記憶上次值）後批次調整多條多重引線，避開 tan 無定義角度並可一次復原。","usage":"執行 MLAa → 輸入角度 → 選取多重引線 → 自動調整","level":6,"lt":"✅","ver":"2025-11-26(檔案日期)","author":"—","video":"https://youtu.be/sMMXWDdxbgs","fas":"fas/MLAa.fas"},{"no":1084,"file":"MLADDLEAD.lsp","cmd":"MLADDLEAD","cat":"標註","desc":"對話框設定連續模式後，批次對多重引線新增獨立射線引線，逐一呼叫 MLEADEREDIT 加入分支。","usage":"執行 MLADDLEAD → 於對話框設定 → 選取 MLeader → 逐一指定引線點 → Enter 結束","level":7,"lt":"✅","ver":"2026-09-09(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MLADDLEAD.fas"},{"no":1085,"file":"MLANG.lsp","cmd":"MLANG","cat":"標註","desc":"對話框輸入引線角度（預設 60，可快選 30/45/60/90）後選取多重引線，固定箭頭點與長度重新設定角度。","usage":"執行 MLANG → 於對話框設定角度 → 選取多重引線 → 自動調整","level":8,"lt":"⚠️","ver":"v1.1.0 2026-11-11","author":"ChengBar (MyCAD)","video":"https://youtu.be/w0lRHCPMhz4","fas":"fas/MLANG.fas"},{"no":1086,"file":"MLD.lsp","cmd":"MLD","cat":"面積/數量統計","desc":"以對話框選擇多重引線樣式、前綴、自動編號與單位，點選封閉物件自動計算面積並產生連動式多重引線標註。","usage":"執行 MLD → 於對話框設定樣式、前綴、起始編號與位數 → 選取封閉物件 → 指定引線位置","level":7,"lt":"✅","ver":"2026-03-26(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MLD.fas"},{"no":1087,"file":"Mleader-D.lsp","cmd":"Mleader45、Mleader60、Mleader90、Mleader120、Mleader135、Mleader270","cat":"標註","desc":"選取多重引線後，保持第一點不動，將第二點（折點）調整成 45、60、90、120、135、270 度的指定角度。","usage":"輸入 Mleader45 等指令 → 選取多重引線 → 引線角度自動調整","level":5,"lt":"✅","ver":"20220716更新","author":"chengshunyi","video":"","fas":"fas/Mleader-D.fas"},{"no":1088,"file":"mleader-Plant.lsp","cmd":"mleader-Plant","cat":"標註","desc":"以對話框選擇植栽文字、單位、密度與字高，點選封閉範圍後以多重引線標註植栽面積與數量。","usage":"執行 mleader-Plant → 於對話框設定 → 選取封閉範圍 → 指定引線位置","level":7,"lt":"✅","ver":"20241206（原 2014-08-21）","author":"Tharwat Al Shoufi（chengshunyi 修改）","video":"","fas":"fas/mleader-Plant.fas"},{"no":1089,"file":"mleader_angle.lsp","cmd":"（無，副程式庫）","cat":"標註","desc":"迴圈處理選集中的多重引線並調整角度，顯示剩餘待處理數量（定義為函式，無 c: 指令）。","usage":"由其他程式呼叫並傳入多重引線選集","level":4,"lt":"✅","ver":"20230212","author":"chengshunyi","video":"https://youtu.be/sQCxnuGArto","fas":"fas/mleader_angle.fas"},{"no":1090,"file":"mleader_angle_block.lsp","cmd":"mla90、mla-90、mla0、mla180、mleader_align_blk","cat":"標註","desc":"修改多重引線第一段角度，並可針對含圖塊內容的多重引線依參考點 X 對齊，考慮註解比例（CANNOSCALEVALUE）。","usage":"輸入 mla90 等指令 → 選取多重引線；或執行 mleader_align_blk → 點選參考點 X → 選取多重引線","level":7,"lt":"✅","ver":"2026-02-16(檔案日期)","author":"—","video":"","fas":"fas/mleader_angle_block.fas"},{"no":1091,"file":"mleader_reset.lsp","cmd":"MLRO、MleaderColorByStyle、MleaderByStyle","cat":"標註","desc":"以對話框勾選要移除的多重引線覆寫項目（顏色、線型、線寬、箭頭、水平段等），讓引線恢復受樣式控制。","usage":"執行 MLRO → 於對話框勾選要移除的覆寫項目 → 選取多重引線 → 完成","level":7,"lt":"✅","ver":"12-06-2022 / 12-09-2022","author":"BeekeeCZ、Eric Stiles、Lee Mac","video":"","fas":"fas/mleader_reset.fas"},{"no":1092,"file":"mleader_set_dogleg_by_x.lsp","cmd":"mleader_set_dogleg_by_x","cat":"標註","desc":"點選兩個 X 對齊參考點並框選多重引線，依點選 X 與折點差距設定 dogleg 長度，並依位置更新文字對齊方向。","usage":"執行 mleader_set_dogleg_by_x → 點選參考點 P1 → 點選參考點 P2 → 選取多重引線","level":6,"lt":"✅","ver":"20250907","author":"chengshunyi","video":"https://youtu.be/E5HJLPolnj8","fas":"fas/mleader_set_dogleg_by_x.fas"},{"no":1093,"file":"mleader_set_dogleg_by_x2.lsp","cmd":"mleader_set_dogleg_by_x2","cat":"標註","desc":"點選 X 對齊參考點，再選取（排除鎖定圖層）多重引線，依參考點 X 與折點差距設定 dogleg 長度與文字對齊。","usage":"執行 mleader_set_dogleg_by_x2 → 點選參考點 → 選取多重引線","level":6,"lt":"✅","ver":"20250907","author":"chengshunyi","video":"","fas":"fas/mleader_set_dogleg_by_x2.fas"},{"no":1094,"file":"mleader_set_dogleg_by_xlowest.lsp","cmd":"mleader_set_dogleg_by_xlowest","cat":"標註","desc":"選取多條多重引線，自動找出最低的 P2 點，將其餘引線的 dogleg 長度對齊到該點 X，並判斷文字對齊方向。","usage":"執行 mleader_set_dogleg_by_xlowest → 選取多重引線 → 自動對齊","level":6,"lt":"✅","ver":"20251125","author":"chengshunyi","video":"","fas":"fas/mleader_set_dogleg_by_xlowest.fas"},{"no":1095,"file":"mleader_set_dogleg_by_y.lsp","cmd":"mleader_set_dogleg_by_y","cat":"標註","desc":"點選指定 Y 座標的參考點，將多重引線第 2 點（折點）沿原引線延伸線移到與該 Y 水平線的交點。","usage":"執行 mleader_set_dogleg_by_y → 點選 Y 參考點 → 選取多重引線 → 折點自動移動","level":6,"lt":"✅","ver":"2025-11-23(檔案日期)","author":"—","video":"https://youtu.be/CEmbTqZQoyA","fas":"fas/mleader_set_dogleg_by_y.fas"},{"no":1096,"file":"MLeaderInc.lsp","cmd":"MLeaderInc","cat":"標註","desc":"輸入起始編號後連續點選位置，建立遞增編號的多重引線，可輸入 undo 復原。","usage":"執行 MLeaderInc → 輸入起始編號 → 指定起點與其他點 → 連續建立 → Enter 結束","level":5,"lt":"✅","ver":"2025-08-05(檔案日期)","author":"—","video":"","fas":"fas/MLeaderInc.fas"},{"no":1097,"file":"mleadersel-all.LSP","cmd":"mleadersel-all","cat":"其他","desc":"選取全圖所有多重引線（MULTILEADER）物件，供後續指令使用。","usage":"執行 mleadersel-all → 自動選取全圖多重引線","level":1,"lt":"✅","ver":"20221002","author":"chengshunyi","video":"","fas":"fas/mleadersel-all.fas"},{"no":1098,"file":"mleadersel.LSP","cmd":"（無，副程式庫）","cat":"其他","desc":"僅 4 行的選取片段，過濾 MULTILEADER 物件，無定義函式。","usage":"由其他程式載入使用","level":1,"lt":"✅","ver":"20221002","author":"chengshunyi","video":"","fas":"fas/mleadersel.fas"},{"no":1099,"file":"mleaderselbysty.LSP","cmd":"（無，副程式庫）","cat":"其他","desc":"依多重引線樣式名稱選取多重引線的函式。","usage":"由其他程式呼叫並傳入樣式名稱","level":3,"lt":"✅","ver":"20221002","author":"chengshunyi","video":"","fas":"fas/mleaderselbysty.fas"},{"no":1100,"file":"MLEADERSIZE.lsp","cmd":"MleaderSize","cat":"標註","desc":"依 ltscale 比例調整多重引線大小，並將其放到 TG-說明註解 圖層。","usage":"執行 MleaderSize → 選取多重引線 → 自動調整","level":3,"lt":"✅","ver":"2022-09-04(檔案日期)","author":"—","video":"","fas":"fas/MLEADERSIZE.fas"},{"no":1101,"file":"mlhgt.LSP","cmd":"mlhgt","cat":"標註","desc":"依目前比例從 my-mleader.txt 讀取字高、箭頭、延伸線、行距等參數，統一重設圖面所有多重引線大小。","usage":"執行 mlhgt → 確認或輸入比例 → 自動套用到所有多重引線","level":6,"lt":"✅","ver":"20230212、20240105","author":"chengshunyi","video":"https://youtu.be/XYQ2iV7xwJ4","fas":"fas/mlhgt.fas"},{"no":1102,"file":"mline-creat.lsp","cmd":"test","cat":"繪圖","desc":"建立多線樣式（加入 ACAD_MLINESTYLE 字典）並連續指定點繪製 MLINE，範例指令為 test。","usage":"執行 test → 指定第一點 → 指定下一點 → 繪出多線","level":6,"lt":"✅","ver":"20240524","author":"chengshunyi（原 Lee Mac 2010）","video":"","fas":"fas/mline-creat.fas"},{"no":1103,"file":"Mline-Open-i.lsp","cmd":"MOi、Mline-Open-i","cat":"圖塊/屬性","desc":"以對話框設定開口寬度、單位與開門型式（單開／雙開等），修剪多線 MLine 開口並插入動態門圖塊。","usage":"執行 MOI → 於對話框設定寬度、單位與門型 → 點選多線位置 → 自動開口並插入門","level":8,"lt":"✅","ver":"2026-01-16(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/Mline-Open-i.fas"},{"no":1104,"file":"Mline_TRENCH_Hatch.LSP","cmd":"Mline_TRENCH_Hatch","cat":"繪圖","desc":"以對話框設定填充寬度與圖案，沿路徑繪製溝渠雙線並於 TRENCH 圖層填充，用完即刪 DCL。","usage":"執行 Mline_TRENCH_Hatch → 於對話框設定寬度與圖案 → 指定路徑點 → 完成填充","level":7,"lt":"✅","ver":"20251222","author":"ChengBar (MyCAD)","video":"","fas":"fas/Mline_TRENCH_Hatch.fas"},{"no":1105,"file":"MLines2PLines.lsp","cmd":"ml2pl","cat":"修改","desc":"將選取的多線 MLINE 分解並合併成輕量多段線。","usage":"執行 ml2pl → 選取多線 → 自動轉成多段線","level":5,"lt":"✅","ver":"Version 1.1  10-06-2012","author":"Lee Mac","video":"","fas":"fas/MLines2PLines.fas"},{"no":1106,"file":"mljust.lsp","cmd":"mljust","cat":"修改","desc":"變更選取多線的對正方式（Top／Zero／Bottom），且不改變其在圖面的視覺位置，類似文字的 TJUST。","usage":"執行 mljust → 選擇新的對正方式 → 選取多線","level":6,"lt":"✅","ver":"Version 1.0","author":"Lee Mac","video":"","fas":"fas/mljust.fas"},{"no":1107,"file":"mll.LSP","cmd":"mll","cat":"查詢","desc":"步行距離量測：連續點選路徑產生多段線，並在端點加圓圈與距離文字，使用虛線 Dashed2 線型。","usage":"執行 mll → 指定路徑各點 → 完成後標註步行距離","level":6,"lt":"✅","ver":"20230410","author":"chengshunyi","video":"","fas":"fas/mll.fas"},{"no":1108,"file":"MLL2.LSP","cmd":"mll2","cat":"面積/數量統計","desc":"統計選取多線（如電纜架）依比例與線寬分組的總長度，封閉多線會加計首尾段並列印結果。","usage":"執行 mll2 → 選取多線 → 顯示各寬度的總長度","level":6,"lt":"✅","ver":"2022-07-30(檔案日期)","author":"網路程式","video":"","fas":"fas/MLL2.fas"},{"no":1109,"file":"MLMRR.LSP","cmd":"MLMRR","cat":"標註","desc":"智慧引線工具箱：對話框選擇連續左右或上下鏡射多重引線（引線不移位），或獨立新增、刪除引線，修改後自動 ANNORESET。","usage":"執行 MLMRR → 於對話框選鏡射或加減引線模式與長度 → 選取多重引線 → 完成","level":8,"lt":"✅","ver":"2026-06-09(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MLMRR.fas"},{"no":1110,"file":"MLNote-mv.LSP","cmd":"MLNote-mv","cat":"標註","desc":"MLine 智慧註解與填充 V7.8：對話框設定單位、樣式前綴與自動過濾，對多線填充並標註樣式與寬度／長度。","usage":"執行 MLNote-mv → 於對話框設定單位與選項 → 選取多線 → 自動填充並標註","level":8,"lt":"✅","ver":"V7.8","author":"ChengBar (MyCAD)","video":"","fas":"fas/MLNote-mv.fas"},{"no":1111,"file":"MLNote-v5.lsp","cmd":"MLNote","cat":"標註","desc":"MLine 智慧註解 V5.2：對話框選單位與長度，並提供 SOLID 或 AR-CONC-T／AR-CONC 兩種 Hatch 填充，文字註解置於 mline-note 圖層。","usage":"執行 MLNote → 於對話框設定 → 選取多線 → 自動填充並註解","level":7,"lt":"✅","ver":"V5.2","author":"—","video":"","fas":"fas/MLNote-v5.fas"},{"no":1112,"file":"MLNote.LSP","cmd":"MLNote","cat":"標註","desc":"MLine 智慧註解 V5.1：對話框選單位與長度，並以 SOLID 或 AR-CONC-T Hatch 填充多線，Hatch 角度依多線方向旋轉，RCW-HATCH 圖層透明度 50%。","usage":"執行 MLNote → 於對話框設定 → 選取多線 → 自動填充並註解","level":7,"lt":"✅","ver":"V5.1","author":"—","video":"","fas":"fas/MLNote.fas"},{"no":1113,"file":"MLR.lsp","cmd":"MLR","cat":"修改","desc":"以對話框輸入旋轉角度（預設 45，記憶上次值）旋轉多重引線，有引線以箭頭端點為中心，無引線以內容包圍框中心為旋轉點。","usage":"執行 MLR → 於對話框輸入角度 → 選取多重引線 → 完成旋轉","level":6,"lt":"✅","ver":"2026-05-27(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MLR.fas"},{"no":1114,"file":"MLRO.LSP","cmd":"MLRO","cat":"修改","desc":"對話框設定角度（預設 180）後，依點選位置鎖中點連續旋轉多重引線，旋轉後把引線起點還原回原座標。","usage":"執行 MLRO → 於對話框設定啟用與角度 → 連續點選多重引線 → Enter 結束","level":7,"lt":"✅","ver":"2026-05-28(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MLRO.fas"},{"no":1115,"file":"mlstyleslengths.LSP","cmd":"mlstyleslengths","cat":"面積/數量統計","desc":"統計各多線樣式（MLSTYLE）的總長度並列出結果，可選擇乘 2 或加計矩形多線。","usage":"執行 mlstyleslengths → 自動掃描模型空間多線 → 顯示各樣式總長度","level":4,"lt":"✅","ver":"20220716更新","author":"—","video":"","fas":"fas/mlstyleslengths.fas"},{"no":1116,"file":"MLT.lsp","cmd":"MLT","cat":"繪圖","desc":"以對話框列出多線樣式，選擇對正與比例後繪製 MLINE，並可依所有樣式建立對應圖層、繪圖時自動切換圖層。","usage":"執行 MLT → 於對話框選樣式、對正與比例 → 指定點繪製多線；可按鈕建立樣式圖層","level":7,"lt":"✅","ver":"2026-01-04(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MLT.fas"},{"no":1117,"file":"MLTL.LSP","cmd":"MLTL","cat":"面積/數量統計","desc":"選取多線並統計總長度後顯示。","usage":"執行 MLTL → 選取多線 → 顯示總長度","level":2,"lt":"✅","ver":"2022-07-30(檔案日期)","author":"網路程式","video":"","fas":"fas/MLTL.fas"},{"no":1118,"file":"mltopline.LSP","cmd":"mltopline","cat":"修改","desc":"連續點選多線，轉成多段線，Enter 結束。","usage":"執行 mltopline → 點選多線 → 連續轉換 → Enter 結束","level":3,"lt":"✅","ver":"20240727","author":"chengshunyi","video":"","fas":"fas/mltopline.fas"},{"no":1119,"file":"MMLV.lsp","cmd":"MMLV","cat":"標註","desc":"以對話框選擇來源屬性 A 與目標屬性 B、連接符號與合併位置，將多重引線屬性值合併覆蓋（如 A-B）。","usage":"執行 MMLV → 於對話框選屬性標籤、符號與前後位置 → 選取多重引線 → 完成合併","level":7,"lt":"✅","ver":"2026-05-26(檔案日期)","author":"—","video":"","fas":"fas/MMLV.fas"},{"no":1120,"file":"model-dim-lscaF.lsp","cmd":"model-dim-2M、model-dim-cm2M、model-dim-cm2mm、model-dim-mm2M、model-dim-M2M、model-dim-1、model-dim-pup0、model-dim-pup1、model-dim-pup2","cat":"標註","desc":"依目前 LTSCALE 與單位係數，將選取標註的線性比例（DIMLFAC）換算成 m、cm、mm，並控制是否加單位與小數位。","usage":"輸入 model-dim-cm2M 等指令 → 選取標註 → 比例與單位自動換算","level":6,"lt":"✅","ver":"20240304（初版 20230903）","author":"chengshunyi","video":"https://youtu.be/PU0PZfDqH2w","fas":"fas/model-dim-lscaF.fas"},{"no":1121,"file":"model-dim-rset.lsp","cmd":"model-dim-rset","cat":"標註","desc":"以對話框設定比例、單位、字高、字寬、字距等參數，重設模型空間標註樣式與選取標註，比例大於 150／200 時自動縮 0.8。","usage":"執行 model-dim-rset → 於對話框設定比例、單位與字體參數 → 選取標註 → 套用","level":8,"lt":"✅","ver":"20221231","author":"chengshunyi","video":"https://youtu.be/H0_4yluPsA0","fas":"fas/model-dim-rset.fas"},{"no":1122,"file":"model-draw-A.lsp","cmd":"model-draw-A","cat":"出圖/列印","desc":"以對話框選擇圖紙尺寸（讀取 Z-PAPERSIZE.txt）、單位與比例，在模型空間繪製圖紙範圍矩形並寫入比例文字。","usage":"執行 model-draw-A → 於對話框選圖紙、單位與比例 → 指定位置 → 繪出範圍","level":7,"lt":"✅","ver":"20230128","author":"chengshunyi","video":"","fas":"fas/model-draw-A.fas"},{"no":1123,"file":"model-draw-area-any.lsp","cmd":"model-draw-area-any","cat":"出圖/列印","desc":"輸入比例尺（預設 100）後，依圖紙視埠 718x556mm 在模型空間繪製對應繪圖範圍矩形並標示比例。","usage":"執行 model-draw-area-any → 輸入比例尺 → 指定位置 → 繪出範圍","level":4,"lt":"✅","ver":"20221230","author":"—","video":"","fas":"fas/model-draw-area-any.fas"},{"no":1124,"file":"model-draw-area-d.lsp","cmd":"model-draw-area-d","cat":"出圖/列印","desc":"以對話框選擇比例清單與文字高度、角度，在模型空間繪製繪圖範圍矩形並於指定點寫入比例文字。","usage":"執行 model-draw-area-d → 於對話框選擇比例與文字 → 指定位置 → 繪出範圍","level":6,"lt":"✅","ver":"20221231","author":"chengshunyi","video":"","fas":"fas/model-draw-area-d.fas"},{"no":1125,"file":"model-draw-area.lsp","cmd":"model-draw-area","cat":"出圖/列印","desc":"輸入常用比例（1:1 至 1:200）後，在模型空間以圖紙大小與比例繪製繪圖範圍矩形並標示比例。","usage":"執行 model-draw-area → 輸入比例 → 指定位置 → 繪出範圍","level":4,"lt":"✅","ver":"20221230","author":"—","video":"","fas":"fas/model-draw-area.fas"},{"no":1126,"file":"MODEL-PLOT-B.LSP","cmd":"MODEL-PLOT-B-A4、MODEL-PLOT-B-A3、MODEL-PLOT-B-A1、MODEL-PLOT-B-Ax、MODEL-PLOT-B","cat":"出圖/列印","desc":"模型空間批次出圖：選取資料夾與圖框、筆寬表後，產生 SCRIPT 對該資料夾所有圖檔，依圖塊計算範圍輸出 PDF。","usage":"執行 MODEL-PLOT-B → 於對話框選圖紙尺寸、圖塊與筆寬表 → 選擇資料夾 → 自動批次出圖","level":8,"lt":"❌","ver":"20220716更新","author":"chengshunyi（含 Lee Mac listbox）","video":"","fas":"fas/MODEL-PLOT-B.fas"},{"no":1127,"file":"MODEL-PLOT.lsp","cmd":"layout-plt-a4、layout-plt-a3、layout-plt-a1、MODEL-PLOT-A4-BLK、MODEL-PLOT-A4、MODEL-PLOT-A3、MODEL-PLOT-A1、MODEL-PLOT-A0","cat":"出圖/列印","desc":"依圖框圖塊比例自動計算出圖範圍並輸出 PDF，自動區分模型與配置，預設 A4／A3／A1 筆寬表。","usage":"執行 MODEL-PLOT-A3 等指令 → 選擇輸出資料夾 → 自動依圖框比例出 PDF","level":8,"lt":"✅","ver":"20240328","author":"chengshunyi","video":"","fas":"fas/MODEL-PLOT.fas"},{"no":1128,"file":"move-block-2int.lsp","cmd":"move-block-2int0、move-block-2int0-chk、move-selblock-2int0","cat":"修改","desc":"選取指定名稱圖塊，檢查插入點是否在 0.5 的倍數，不在整數點者自動移動到整數點，chk 指令僅檢查。","usage":"執行 move-block-2int0 → 選取圖塊名稱 → 全圖同名圖塊自動移到整數點；move-selblock 為選取圖塊","level":6,"lt":"✅","ver":"20250510、20250711","author":"chengshunyi","video":"","fas":"fas/move-block-2int.fas"},{"no":1129,"file":"move-pl-2int0.lsp","cmd":"move-pl-2int0","cat":"修改","desc":"選取多段線，將各頂點座標取整到小數點 0 位並以 Undo 群組包覆，並檢查 0.5 位置。","usage":"執行 move-pl-2int0 → 選取多段線 → 頂點自動取整","level":5,"lt":"✅","ver":"20250510、20250517","author":"chengshunyi","video":"","fas":"fas/move-pl-2int0.fas"},{"no":1130,"file":"move-pl-2int1.lsp","cmd":"move-pl-2int1","cat":"修改","desc":"選取多段線，將各頂點座標取整到小數點 1 位（0.5 倍數檢查）並以 Undo 群組包覆。","usage":"執行 move-pl-2int1 → 選取多段線 → 頂點自動取整","level":5,"lt":"✅","ver":"20220716更新（20250517 修改）","author":"chengshunyi","video":"","fas":"fas/move-pl-2int1.fas"},{"no":1131,"file":"move-selblock-2int1.lsp","cmd":"move-selblock-2int1","cat":"修改","desc":"點選圖塊後取其有效名稱，將全圖同名圖塊插入點取整到小數點 0.5，不在 0.5 位置者自動移動。","usage":"執行 move-selblock-2int1 → 點選圖塊 → 自動移動同名圖塊","level":6,"lt":"✅","ver":"20250718","author":"chengshunyi","video":"","fas":"fas/move-selblock-2int1.fas"},{"no":1132,"file":"MoveNoLeader.LSP","cmd":"MoveNoLeader","cat":"對齊/排列","desc":"以對話框輸入 X、Y 偏移量，將沒有引線（LeaderCount 為 0）的多重引線依偏移量移動。","usage":"執行 MoveNoLeader → 於對話框輸入 X、Y 偏移量 → 選取多重引線","level":6,"lt":"✅","ver":"2026-03-08(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MoveNoLeader.fas"},{"no":1133,"file":"MoveTextToMLine.lsp","cmd":"MTTML、MoveTextToMLine","cat":"對齊/排列","desc":"以對話框設定偵測長度、偏移模式與自動全圖過濾，將文字移到多線 MLINE 路徑的中間位置（可偏移 1/2 或再上移）。","usage":"執行 MTTML → 於對話框設定長度與偏移模式 → 點選文字樣本 → 自動（或窗選）處理 → 完成","level":8,"lt":"✅","ver":"2026-02-07(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MoveTextToMLine.fas"},{"no":1134,"file":"MPA.lsp","cmd":"MyCAD_PlineAreaAnalysis、MPA","cat":"面積/數量統計","desc":"多段線面積屬性與攤提統計分析：以 XData 記錄每塊多段線屬性，依面積比例漸層上色（Hatch）並產生統計表，保留設定記憶。","usage":"執行 MPA → 於對話框設定單位與參數 → 選取多段線 → 輸入屬性 → 產生上色與統計表","level":9,"lt":"✅","ver":"2026-09-21(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MPA.fas"},{"no":1135,"file":"MPAA.lsp","cmd":"MyCAD_PlineAreaAnalysis、MPAA","cat":"面積/數量統計","desc":"多段線面積屬性與攤提統計分析（MPA 的另一版本）：XData 記錄屬性、Hatch 依面積漸層上色並產生統計表。","usage":"執行 MPAA → 於對話框設定單位與參數 → 選取多段線 → 輸入屬性 → 產生上色與統計表","level":9,"lt":"✅","ver":"2026-09-21(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MPAA.fas"},{"no":1136,"file":"MSTXT.LSP","cmd":"txt","cat":"文字","desc":"整合對話框編輯文字、多行文字、屬性定義、多重引線、標註與帶屬性圖塊的內容，可多選同時編輯。","usage":"執行 txt → 選取文字／標註／圖塊 → 於對話框修改內容 → 按確定","level":6,"lt":"✅","ver":"20240218","author":"A.Batts、Jimmy Bergmark (JTB World)、chengshunyi","video":"","fas":"fas/MSTXT.fas"},{"no":1137,"file":"MTEXT-DESC.LSP","cmd":"MTEXT-DESC","cat":"文字","desc":"選取多行文字，依 ltscale 調整字高並將附著點改為 5（正中），同時放到 TG-規範說明 圖層。","usage":"執行 MTEXT-DESC → 選取多行文字 → 自動調整字高與圖層","level":3,"lt":"✅","ver":"2022-09-04(檔案日期)","author":"—","video":"","fas":"fas/MTEXT-DESC.fas"},{"no":1138,"file":"mtext-numcol.lsp","cmd":"mtext-numcol","cat":"文字","desc":"以正規表示式找出多行文字中的數字，將其顏色改為指定 ACI 色（預設 6）。","usage":"執行 mtext-numcol → 選取多行文字 → 數字自動變色","level":7,"lt":"❌","ver":"20240507","author":"Lee Mac（chengshunyi 修改）","video":"","fas":"fas/mtext-numcol.fas"},{"no":1139,"file":"MTEXT-ROOMNAME.LSP","cmd":"MTEXT-ROOMNAME","cat":"文字","desc":"選取多行文字，依 ltscale 調整字高並將附著點改為 5（正中），同時放到 TG-空間名稱 圖層。","usage":"執行 MTEXT-ROOMNAME → 選取多行文字 → 自動調整字高與圖層","level":3,"lt":"✅","ver":"2022-09-04(檔案日期)","author":"—","video":"","fas":"fas/MTEXT-ROOMNAME.fas"},{"no":1140,"file":"mtext2mleader.lsp","cmd":"mtext2mleader","cat":"標註","desc":"選取文字或多行文字，指定箭頭與落點位置後轉為多重引線（my-ach2 樣式），樣式不存在時由 mleader.dwg 帶入。","usage":"執行 mtext2mleader → 選取文字 → 指定箭頭位置 → 指定落點位置 → 產生多重引線","level":6,"lt":"✅","ver":"20241130","author":"chengshunyi","video":"https://youtu.be/vhaFMqp1yIo","fas":"fas/mtext2mleader.fas"},{"no":1141,"file":"MTextToMLeader.lsp","cmd":"MTextToMLeader","cat":"標註","desc":"選取文字或多行文字，依字高 5 倍偏移出落點，刪除原文字並以 MLEADER 建立同內容的多重引線。","usage":"執行 MTextToMLeader → 選取文字 → 指定箭頭位置 → 自動轉為多重引線","level":4,"lt":"✅","ver":"20220716更新","author":"chengshunyi","video":"","fas":"fas/MTextToMLeader.fas"},{"no":1142,"file":"MTiL.lsp","cmd":"MTIL、MMTIL","cat":"對齊/排列","desc":"選取文字後依單位 mm／cm／m 將其插入點移到指定新位置，座標可取整（捨去或四捨五入）。","usage":"執行 MTIL → 選取文字 → 指定新位置 → 文字移動到整數座標","level":6,"lt":"✅","ver":"20250517","author":"chengshunyi","video":"","fas":"fas/MTiL.fas"},{"no":1143,"file":"MTRIM.LSP","cmd":"mtrim","cat":"修改","desc":"選取切割邊後，以兩點定義窗選範圍連續修剪物件的快速修剪指令。","usage":"執行 mtrim → 選取切割邊 → 指定第一點與第二點 → 修剪","level":2,"lt":"✅","ver":"84.5.15（民國）","author":"—","video":"","fas":"fas/MTRIM.fas"},{"no":1144,"file":"mtxt-ADD-chr.LSP","cmd":"mtxt-ADD-chr-m、mtxt-ADD-chr-p、mtxt-ADD-chr-m2、mtxt-ADD-chr-m3、mtxt-ADD-chr","cat":"文字","desc":"選取文字或多行文字，在尾端批次加上指定字元（如 m、m2、坪）或空格，記憶上次空格數。","usage":"輸入 mtxt-ADD-chr-m 等指令 → 選取文字 → 自動加字元","level":4,"lt":"✅","ver":"20241122","author":"chengshunyi","video":"","fas":"fas/mtxt-ADD-chr.fas"},{"no":1145,"file":"MultilineCloseOpen.lsp","cmd":"MLC、MLO","cat":"修改","desc":"將選取的開放多線 MLINE 封閉（MLC），或將封閉多線改成開放（MLO），保留樣式、比例與圖層並刪除原物件。","usage":"輸入 MLC 或 MLO → 選取多線 → 自動重畫封閉／開放多線","level":6,"lt":"✅","ver":"6 July 2015","author":"Kent Cooper","video":"","fas":"fas/MultilineCloseOpen.fas"},{"no":1146,"file":"my-Atdf2txt.LSP","cmd":"my-ATDF2TXT","cat":"圖塊/屬性","desc":"將圖面中的屬性定義（ATTDEF）轉換為標籤文字（TEXT），可選取或全部轉換。","usage":"執行 my-ATDF2TXT → 選擇「選取」或「全部」→ 自動轉換","level":6,"lt":"✅","ver":"2026-10-17(檔案日期)","author":"Robert L. Zipprich","video":"","fas":"fas/my-Atdf2txt.fas"},{"no":1147,"file":"my-AtdfExplode.lsp","cmd":"my-AtdfExplode","cat":"圖塊/屬性","desc":"類似 Express Tools Burst，將圖塊的可見屬性轉為文字或多行文字後分解圖塊，忽略隱藏屬性。","usage":"執行 my-AtdfExplode → 選取圖塊 → 自動分解並將屬性轉文字","level":7,"lt":"✅","ver":"2023-12-13(檔案日期)","author":"Lee Mac（Burst Upgraded，2014）","video":"","fas":"fas/my-AtdfExplode.fas"},{"no":1148,"file":"my-bpoly-w.lsp","cmd":"my-bpoly-w","cat":"繪圖","desc":"可指定窗選範圍後使用 BOUNDARY 建立邊界多段線。","usage":"執行 my-bpoly-w → 指定範圍 → 產生邊界多段線","level":2,"lt":"✅","ver":"20240403","author":"chengshunyi","video":"","fas":"fas/my-bpoly-w.fas"},{"no":1149,"file":"My-logo-V.lsp","cmd":"（無，副程式庫）","cat":"其他","desc":"以向量資料繪製 MyCAD 空心字雙線 LOGO 的函式（vectors），供對話框影像元件使用。","usage":"由其他程式載入呼叫","level":4,"lt":"✅","ver":"2023-12-12(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/My-logo-V.fas"},{"no":1150,"file":"my-m-group.lsp","cmd":"my-m-group","cat":"其他","desc":"短程式，以 VLA 處理群組（Group）相關操作（15 行）。","usage":"執行 my-m-group → 依提示操作","level":2,"lt":"✅","ver":"2024-03-10(檔案日期)","author":"—","video":"","fas":"fas/my-m-group.fas"},{"no":1151,"file":"my-ncopy.lsp","cmd":"my-ncopy-c30、my-ncopy-c50、my-ncopy、nc","cat":"修改","desc":"以 NCOPY 複製嵌套物件（如外部參照或圖塊內物件）描圖，可指定新圖層與顏色，並可轉成指定線寬多段線。","usage":"執行 nc → 選取嵌套物件 → 自動複製到新圖層；c30／c50 為 pline 線寬版","level":5,"lt":"✅","ver":"20241214","author":"chengshunyi","video":"","fas":"fas/my-ncopy.fas"},{"no":1152,"file":"my-offset.lsp","cmd":"my-offset","cat":"修改","desc":"連續偏移同一物件並提供常用距離快選，每次只保留最後一個偏移結果（中間過程自動刪除）。","usage":"執行 my-offset → 輸入偏移距離或選常用值 → 選取物件 → 指定偏移側","level":5,"lt":"✅","ver":"20240316","author":"chengshunyi","video":"","fas":"fas/my-offset.fas"},{"no":1153,"file":"my-pagesetup-V1V2.lsp","cmd":"my-pagesetup-V1、my-pagesetup-V2、my-pagesetup、my-pagesetup-V1-mm、my-pagesetup-V2-mm、my-pagesetup-V1-cm、my-pagesetup-V2-cm、my-pagesetup-dwt","cat":"出圖/列印","desc":"從 my-cm 系列 dwt 範本匯入頁面設定（PSETUPIN），對應 818x574 或 841x594 圖框的 mm／cm 版，並套用到各配置。","usage":"輸入 my-pagesetup-V2-mm 等指令 → 自動匯入並套用頁面設定","level":5,"lt":"✅","ver":"20250411、20250427","author":"chengshunyi","video":"","fas":"fas/my-pagesetup-V1V2.fas"},{"no":1154,"file":"my-pagesetups.lsp","cmd":"my-pagesetups","cat":"出圖/列印","desc":"自 my-pagesetups.dwt 匯入頁面設定，找不到範本時提示檢查支援路徑。","usage":"執行 my-pagesetups → 自動匯入頁面設定","level":3,"lt":"✅","ver":"20231203","author":"chengshunyi","video":"","fas":"fas/my-pagesetups.fas"},{"no":1155,"file":"my-plot-AXB-C.lsp","cmd":"my-plot-AXB-C、MODEL-PLOT-A、MODEL-PLOT-Auto","cat":"出圖/列印","desc":"以對話框選擇圖紙尺寸與筆寬表，找圖框計算比例後批次出圖，通用 AutoCAD／ZWCAD，C 版為客製特殊規格。","usage":"執行 my-plot-AXB-C → 於對話框選圖紙與筆寬型式 → 自動依圖框出圖","level":9,"lt":"✅","ver":"2024-10-09(檔案日期)","author":"chengshunyi","video":"","fas":"fas/my-plot-AXB-C.fas"},{"no":1156,"file":"my-plot-AXB-PNG.lsp","cmd":"BP-PNG、my-plot-AXB-PNG、MODEL-PLOT-A-PNG","cat":"出圖/列印","desc":"依圖框以對話框選圖紙尺寸與筆寬後批次輸出 PNG 圖檔，通用 AutoCAD／ZWCAD。","usage":"執行 BP-PNG → 於對話框選圖紙與筆寬型式 → 自動依圖框輸出 PNG","level":9,"lt":"✅","ver":"2026-10-17(檔案日期)","author":"chengshunyi","video":"","fas":"fas/my-plot-AXB-PNG.fas"},{"no":1157,"file":"my-plot-AXB-s.lsp","cmd":"BP-S、my-plot-AXB-s、MODEL-PLOT-S","cat":"出圖/列印","desc":"以合併對話框選圖紙尺寸與筆寬型式，依圖框批次出圖，含到期日顯示，可參數切換模型或配置。","usage":"執行 BP-S → 於對話框選圖紙尺寸與筆寬 → 自動依圖框出圖","level":9,"lt":"✅","ver":"2026-10-31(檔案日期)","author":"chengshunyi","video":"","fas":"fas/my-plot-AXB-s.fas"},{"no":1158,"file":"my-plot-AXB-V2.lsp","cmd":"BP、my-plot-AXB、MODEL-PLOT-A","cat":"出圖/列印","desc":"以合併對話框選圖紙尺寸與筆寬型式，依圖框批次出圖，含到期日顯示，支援 AutoCAD／ZWCAD。","usage":"執行 BP → 於對話框選圖紙尺寸與筆寬 → 自動依圖框出圖","level":9,"lt":"✅","ver":"V2（2026-10-17 檔案日期）","author":"chengshunyi","video":"","fas":"fas/my-plot-AXB-V2.fas"},{"no":1159,"file":"my-plot-AXB-v3-test.lsp","cmd":"BP-M、BP-P、my-plot-AXB、MODEL-PLOT-A","cat":"出圖/列印","desc":"V3 測試版：以合併對話框選圖紙與筆寬，分別以 BP-M（模型）與 BP-P（配置）批次出圖。","usage":"執行 BP-M 或 BP-P → 於對話框選圖紙尺寸與筆寬 → 自動出圖","level":7,"lt":"✅","ver":"V3 測試（2026-02-04 檔案日期）","author":"chengshunyi","video":"","fas":"fas/my-plot-AXB-v3-test.fas"},{"no":1160,"file":"my-plot-AXB-V3.lsp","cmd":"BP-M、BP-P、my-plot-AXB、MODEL-PLOT-A","cat":"出圖/列印","desc":"V3 正式版：以對話框選圖紙尺寸與筆寬型式，BP-M 出模型空間、BP-P 出配置，含到期日顯示。","usage":"執行 BP-M 或 BP-P → 於對話框選圖紙與筆寬 → 自動依圖框出圖","level":9,"lt":"✅","ver":"V3（2026-10-17 檔案日期）","author":"chengshunyi","video":"","fas":"fas/my-plot-AXB-V3.fas"},{"no":1161,"file":"my-plot-AXB-V4.lsp","cmd":"BP-M、BP-P、my-plot-AXB、MODEL-PLOT-A","cat":"出圖/列印","desc":"V4 版：以對話框選圖紙尺寸與筆寬型式，BP-M 出模型空間、BP-P 出配置，含到期日與尺寸索引處理。","usage":"執行 BP-M 或 BP-P → 於對話框選圖紙與筆寬 → 自動依圖框出圖","level":9,"lt":"✅","ver":"V4（2026-10-31 檔案日期）","author":"chengshunyi","video":"","fas":"fas/my-plot-AXB-V4.fas"},{"no":1162,"file":"my-plot-AXB.lsp","cmd":"BP、my-plot-AXB、MODEL-PLOT-A","cat":"出圖/列印","desc":"以對話框選擇筆寬表，依圖框尺寸 A1／A0／A3／A4 計算比例批次出圖，通用 AutoCAD／ZWCAD。","usage":"執行 BP → 於對話框選筆寬表 → 自動依圖框出圖","level":9,"lt":"✅","ver":"2026-10-17(檔案日期)","author":"chengshunyi","video":"","fas":"fas/my-plot-AXB.fas"},{"no":1163,"file":"my-purge.lsp","cmd":"purge-but、purge-all","cat":"圖面管理","desc":"批次清除圖面未使用項目（圖塊、標註樣式、圖層、線型、材質、多重引線樣式等），purge-but 為排除部分項目。","usage":"執行 purge-all → 自動依清單逐項 PURGE；purge-but 只清除部分","level":4,"lt":"✅","ver":"20250216","author":"chengshunyi","video":"","fas":"fas/my-purge.fas"},{"no":1164,"file":"my-re-cal-v1.lsp","cmd":"my-re-cal","cat":"文字","desc":"選取多個文字或多行文字，解析含括號、四則運算與次方的算式並在後面更新計算結果，可設定小數位。","usage":"執行 my-re-cal → 輸入小數位數 → 選取文字 → 自動寫入「=結果」","level":7,"lt":"✅","ver":"2024","author":"—","video":"","fas":"fas/my-re-cal-v1.fas"},{"no":1165,"file":"my-re-cal.lsp","cmd":"MY-RE-CAL","cat":"文字","desc":"選取算式文字（TEXT／MTEXT 可多選），支援 + - * / ^ 括號與 ÷，計算後在後方寫入「=結果」，MTEXT 保留原格式。","usage":"執行 MY-RE-CAL → 於對話框設定小數位數與 LOG → 選取文字 → 自動寫入結果","level":8,"lt":"⚠️","ver":"v2.3.0 2026-11-04","author":"ChengBar (MyCAD)","video":"","fas":"fas/my-re-cal.fas"},{"no":1166,"file":"my-register-count.lsp","cmd":"my-register-count","cat":"系統/授權","desc":"以 SETCFG 在 AppData/ChengBAR 記錄使用次數，作為試用次數計數的測試程式。","usage":"執行 my-register-count → 自動累計並顯示試用次數","level":3,"lt":"✅","ver":"2023-05-14(檔案日期)","author":"chengshunyi","video":"","fas":""},{"no":1167,"file":"My-ShortCut.lsp","cmd":"dwb、dwrc、dwp、dwc、ddl、ddp、ddd、rw、hw","cat":"圖層","desc":"自訂快捷指令：切換到牆圖層後直接畫磚牆、RC 牆、輕隔間牆、帷幕牆，並提供標尺寸、法規、發包尺寸及拆除牆等快捷。","usage":"輸入 dwb（磚牆）、dwrc、dwp、dwc、ddl、ddp、ddd、rw、hw 等快捷 → 自動切換圖層並執行指令","level":4,"lt":"✅","ver":"20241011","author":"chengshunyi","video":"","fas":"fas/My-ShortCut.fas"},{"no":1168,"file":"my-sp-lib.lsp","cmd":"my-sp-lib","cat":"文字","desc":"建築空間文字庫：讀取 my-sp-lib.dat 以對話框選擇主類別與空間名稱，依比例單位、字型與圖層寫入文字。","usage":"執行 my-sp-lib → 於對話框選類別與名稱 → 指定插入位置","level":7,"lt":"✅","ver":"20231126、20231209","author":"chengshunyi","video":"","fas":"fas/my-sp-lib.fas"},{"no":1169,"file":"my-tCount.lsp","cmd":"my-tCount","cat":"面積/數量統計","desc":"統計選取文字、多行文字、多重引線、標註與圖塊屬性中各字串出現次數，並產生表格；可過濾特定屬性標籤。","usage":"執行 my-tCount → 選取物件 → 於對話框設定過濾 → 指定表格位置","level":8,"lt":"✅","ver":"Version 1.1（mycad 20250405）","author":"Lee Mac（chengshunyi 加入 tag 過濾）","video":"","fas":"fas/my-tCount.fas"},{"no":1170,"file":"my-text-lib.lsp","cmd":"my-text-lib","cat":"文字","desc":"建築文字庫：讀取 my-text-lib.dat 以對話框選擇主類別與房間名稱，依比例、字型與圖層寫入文字。","usage":"執行 my-text-lib → 於對話框選類別與名稱 → 指定插入位置","level":7,"lt":"✅","ver":"20231126","author":"chengshunyi","video":"","fas":"fas/my-text-lib.fas"},{"no":1171,"file":"My-toolbarHS.lsp","cmd":"SHOWMYtoolbar、toolbar_hide_show_sop、hide_toolbars_by_list、list_toolbars","cat":"系統/授權","desc":"依清單隱藏或顯示 MY_CAD_PRO 工具列群組（設定、面積、尺寸、圖層管理等），並可列出工具列。","usage":"執行 SHOWMYtoolbar → 自動顯示指定工具列並隱藏其他","level":5,"lt":"✅","ver":"2025-10-19(檔案日期)","author":"chengshunyi","video":"","fas":""},{"no":1172,"file":"My_BLK.lsp","cmd":"My_BLK","cat":"圖塊/屬性","desc":"圖庫選單：自動修正路徑斜線，以幻燈片圖示對話框挑選圖塊（可切換排版）並插入，支援開啟編輯清單檔。","usage":"執行 My_BLK → 於對話框點選圖示或分頁 → 指定插入點","level":8,"lt":"✅","ver":"20251228","author":"chengshunyi","video":"https://youtu.be/m9jQNK-2HLQ","fas":"fas/My_BLK.fas"},{"no":1173,"file":"my_regWinAcc_y.lsp","cmd":"my_regWinAcc_y","cat":"系統/授權","desc":"經銷商專用的授權檔製作工具：以對話框選擇要註冊的檔案，輸入註冊名稱、電腦帳號與到期日並加密產生授權檔。","usage":"執行 my_regWinAcc_y → 驗證經銷商 → 於對話框選檔案並輸入註冊名稱與到期日 → 產生授權檔","level":8,"lt":"✅","ver":"20250713","author":"chengshunyi","video":"","fas":""},{"no":1174,"file":"myarea.lsp","cmd":"MYAREA、MYAREAP","cat":"面積/數量統計","desc":"選取線、弧、多段線自動找出所有封閉區域，插入含編號的動態面積圖塊；MYAREAP 為手動點選區域內部。","usage":"執行 MYAREA → 選取線段／弧／多段線 → 自動插入面積圖塊並編號；MYAREAP 手動點選","level":9,"lt":"⚠️","ver":"2026-10-25(檔案日期)","author":"ChengBar (MyCAD)","video":"https://youtu.be/YTlb-DU2JP8","fas":"fas/myarea.fas"},{"no":1175,"file":"MyAreaPro.lsp","cmd":"MYAREAPRO、MYAREAPRO-P、MYAREAPRO-LIST、MYAREAPRO-STAT、MYAREAPRO-RATIO、MYAREAPRO-COLOR、MYAREAPRO-UNCOLOR、MYAREAPRO-STYPE、MYAREAPRO-UNSTYPE、MYAREAPRO-UNLINK、MYAREAPRO-UPDATE、MYAREAPRO-RENUM、MYAREAPRO-SETSTYPE","cat":"面積/數量統計","desc":"MyArea-Pro 不使用圖塊版：自動標註封閉區域面積與編號，並提供計算式、空間性質統計、百分比、上色、重新編號與更新等一整套面積作業。","usage":"執行 MYAREAPRO → 選取線段／弧／多段線 → 自動標註；再用 -LIST／-STAT／-SETSTYPE 等圈選編號圖塊","level":9,"lt":"⚠️","ver":"2026-11-03（檔案日期 2026-11-04）","author":"ChengBar (MyCAD)","video":"","fas":"fas/MyAreaPro.fas"},{"no":1176,"file":"myattblockcounter-ui.lsp","cmd":"myattblockcounter-ui","cat":"圖塊/屬性","desc":"點選圖塊後以對話框選擇屬性 Tag 與群組統計 Tag（可排序），統計圖塊屬性值數量並可複製全部結果。","usage":"執行 myattblockcounter-ui → 點選圖塊 → 於對話框選擇 Tag 與群組 → 檢視統計","level":8,"lt":"✅","ver":"2026-10-17(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/myattblockcounter-ui.fas"},{"no":1177,"file":"MyCAD-Addvalue-2025.lsp","cmd":"MyCAD-Addvalue","cat":"系統/授權","desc":"MyCAD 儲值管理對話框：以儲值碼為本機註冊名稱儲值點數，記錄最後儲值日期、總點數與已使用點數於 AppData/ChengBAR。","usage":"執行 MyCAD-Addvalue → 輸入儲值碼 → 按套用 → 顯示目前儲值狀態","level":8,"lt":"✅","ver":"20250809","author":"chengshunyi","video":"","fas":""},{"no":1178,"file":"MyCAD-Addvalue.lsp","cmd":"MyAV、MyCAD-Addvalue","cat":"系統/授權","desc":"MyCAD 儲值管理對話框：依儲值碼判讀註冊名稱、日期與點數，每天可定額儲值 500 點且已使用次數需小於 100。","usage":"執行 MyAV → 輸入儲值碼 → 按套用 → 顯示目前儲值狀態","level":8,"lt":"✅","ver":"20250809","author":"chengshunyi","video":"","fas":""},{"no":1179,"file":"MyCAD-DBAI.LSP","cmd":"MyCAD-DBAI","cat":"圖塊/屬性","desc":"點選動態或一般圖塊取得屬性標籤，計算多物件交點寫入 XDATA 文字，或於聚合線端點依角度插入屬性圖塊（CN-L、CN-R 等）並寫入 XDATA。","usage":"執行 MyCAD-DBAI → 點選來源圖塊 → 於對話框選 Tag 與字型圖層 → 選擇交點寫入或端點插入功能","level":9,"lt":"✅","ver":"2026-07-23(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MyCAD-DBAI.fas"},{"no":1180,"file":"MyCAD-DynamicStats.lsp","cmd":"MyCAD-DynamicStats、MCDS","cat":"面積/數量統計","desc":"選取動態圖塊樣本後以雙清單對話框挑選要統計的動態參數，輸出數量統計到 TXT 或 CSV 並自動開啟。","usage":"執行 MCDS → 選取動態圖塊樣本 → 於對話框挑選參數並排序 → 輸出 TXT／CSV","level":9,"lt":"✅","ver":"2026-05-17(檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MyCAD-DynamicStats.fas"},{"no":1181,"file":"Mycad-Install.lsp","cmd":"Mycad-Install","cat":"系統/授權","desc":"MyCAD 安裝與環境設定：重設設定檔（Profile）、加入支援路徑、載入 CUIX 選單與工具列、設定工作空間與背景色並精簡系統選項。","usage":"執行 Mycad-Install → 依提示確認 → 自動設定並可能重新啟動 CAD","level":8,"lt":"✅","ver":"20240107","author":"chengshunyi（EZCAD+MYCAD；AfraLisp 範例）","video":"","fas":""},{"no":1182,"file":"mycad-set-v.lsp","cmd":"mycad-set-v-2024","cat":"系統/授權","desc":"AutoCAD 系統優化：設定系統變數，關閉不實用的華麗效果（如 FRAME、SECURELOAD 等）。","usage":"執行 mycad-set-v-2024 → 自動設定系統變數","level":2,"lt":"✅","ver":"20250212","author":"chengshunyi","video":"","fas":""},{"no":1183,"file":"MyCAD_AccumArea.lsp","cmd":"MyCAD_AccumArea、QAA","cat":"面積/數量統計","desc":"點選封閉聚合線累計面積，可依單位轉換（mm2/cm2/m2/坪/才）、自動編號、標註計算式並輸出面積統計表與 SOLID 著色。","usage":"執行 QAA → 於對話框設定單位/編號/輸出格式 → 選取封閉聚合線或內部點 → 產生面積文字、計算式與統計表","level":9,"lt":"✅","ver":"2026-09-26 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MyCAD_AccumArea.fas"},{"no":1184,"file":"MYCAD_BURST.lsp","cmd":"MYCAD_BURST、pburst、nburst、burstall","cat":"圖塊/屬性","desc":"以對話框選擇炸開模式，炸開圖塊並保留屬性文字及原圖層、顏色、線型，可主層、巢狀或全圖炸開。","usage":"執行 MYCAD_BURST → 選擇模式（PBURST/NBURST/BURSTALL）→ 選取圖塊（全圖模式免選）→ 完成炸開","level":9,"lt":"⚠️","ver":"v3.8.0 2026-11-07","author":"ChengBar (MyCAD)，核心改寫自 Lee Mac Burst Upgraded","video":"https://youtu.be/2eE1vlP1jss","fas":"fas/MYCAD_BURST.fas"},{"no":1185,"file":"MyCAD_DimTool.lsp","cmd":"MyCAD_DimTool、MyCAD_DimScale、MyCAD_DimLinear、MyCAD_DimAligned","cat":"標註","desc":"建築等比標註與智慧連續標註工具，可選標註前綴與比例、指定標註圖層（預設 D-DIMS），水平/垂直/對齊連續標註。","usage":"執行 MyCAD_DimTool → 對話框選擇標註型式、比例與圖層 → 依提示點選標註點連續標註","level":6,"lt":"⚠️","ver":"v1.6.0 2026-10-29","author":"ChengBar (MyCAD)","video":"https://youtu.be/28cGnTo60-k","fas":"fas/MYCAD_DIMTOOL.fas"},{"no":1186,"file":"MYCAD_GenerateBatch.lsp","cmd":"MYCAD_GenerateBatch","cat":"系統/授權","desc":"選擇授權申請資料夾，讀取申請檔後以 certutil 計算 MD5 驗證碼，批次產生授權檔（管理者用）。","usage":"執行 MYCAD_GenerateBatch → 選擇申請資料夾 → 自動讀取 MYCAD_USER*.TXT 並產生 MD5 授權資料","level":8,"lt":"❌","ver":"2025-07-13 (檔案日期)","author":"MyCAD (偉辰工程)","video":"","fas":""},{"no":1187,"file":"MyCAD_HatchPoly.LSP","cmd":"MyCAD_HatchPoly","cat":"繪圖","desc":"選取含弧段/直線的聚合線，依寬度向視覺上方偏移 0.5 倍寬度，產生 EARTH 或 SOLID 填充。","usage":"執行 MyCAD_HatchPoly → 對話框設定圖案/比例/寬度 → 選取聚合線 → 自動產生填充","level":6,"lt":"✅","ver":"2026-09-17 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MyCAD_HatchPoly.fas"},{"no":1188,"file":"MYCAD_Request.lsp","cmd":"MYCAD_Request","cat":"系統/授權","desc":"顯示授權申請表單（姓名、部門、電子郵件、備註），產生申請檔供管理者核發授權。","usage":"執行 MYCAD_Request → 填寫姓名/部門/Email/備註 → 按確定 → 輸出申請檔","level":6,"lt":"✅","ver":"2025-07-13 (檔案日期)","author":"MyCAD","video":"","fas":""},{"no":1189,"file":"MyCAD_SOCPL_BPOLY.LSP","cmd":"SOCPL、sel-obj-creat-pl、bpolycheck234","cat":"面積/數量統計","desc":"選取線/弧/聚合線自動找出所有封閉區域，判斷形狀並在內部插入含面積的圖塊；bpolycheck234 可手動點選區域。","usage":"執行 SOCPL → 對話框設定單位/比例/起始編號 → 選取圖元 → 自動插入面積圖塊（或 BPOLYCHECK234 點選內部）","level":9,"lt":"⚠️","ver":"SOCPL v3.06 2026-09-30","author":"ChengBar (MyCAD)","video":"https://youtu.be/O8Sg5y2p-K8","fas":"fas/MyCAD_SOCPL_BPOLY.fas"},{"no":1190,"file":"MyCAD_Space.lsp","cmd":"MyCAD_Space","cat":"面積/數量統計","desc":"集合住宅專有/共用部分面積分類統計與標記系統，支援單位換算、MText 標記、SOLID 著色檢查及 CSV/TXT 匯出。","usage":"執行 MyCAD_Space → 對話框設定單位/棟別/戶別/樓層/字高 → 選取封閉區域標記 → 可著色、查詢、匯出統計","level":9,"lt":"✅","ver":"2026-05-17 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MyCAD_Space.fas"},{"no":1191,"file":"MYCAD_WALKDISTANCE.lsp","cmd":"WDC、MYCAD_WALKDISTANCE","cat":"查詢","desc":"依建築技術規則檢討步行距離：沿聚合線量測並標註、XData 記憶編號、產生檢討計算式，超限者以雲形亮顯。","usage":"執行 WDC → 對話框設定限制值/小數位/圖層 → 點選步行路徑線 → 產生距離標註與檢討式","level":9,"lt":"⚠️","ver":"v16.0.0 (2026/10)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MYCAD_WALKDISTANCE.fas"},{"no":1192,"file":"MyCAD_XLine5.lsp","cmd":"MyCAD_XLine5","cat":"繪圖","desc":"綜合輔助線（XLINE）自動繪製工具，提供多種模式（含兩點、角度預設 45 度），輔助線建於 0-REF 圖層並可選顏色。","usage":"執行 MyCAD_XLine5 → 對話框選擇模式/角度/圖層顏色 → 依提示指定點 → 產生輔助線","level":8,"lt":"⚠️","ver":"v1.9 2026-10-31","author":"ChengBar (MyCAD)","video":"https://youtu.be/BVlVpf2wQ5M","fas":"fas/MyCAD_XLine5.fas"},{"no":1193,"file":"MyCADCrypto-M.LSP","cmd":"MyCADCrypto-M","cat":"系統/授權","desc":"MyCAD 儲值碼產生工具，輸入電腦名稱、日期、點數，以 Base64 加密/解密並可儲存結果。","usage":"執行 MyCADCrypto-M → 輸入電腦名稱/日期/點數 → 按加密或解密 → 檢視結果並存檔","level":6,"lt":"✅","ver":"20250816","author":"MyCAD (chengshunyi)","video":"","fas":""},{"no":1194,"file":"MyCADCrypto.lsp","cmd":"MyCADCrypto","cat":"系統/授權","desc":"MyCAD 儲值碼 Base64 加密/解密對話框，含 trace/debug 模式與備援機制。","usage":"執行 MyCADCrypto → 輸入電腦名稱/日期/點數 → 按加密或解密 → 檢視結果","level":6,"lt":"✅","ver":"20250816 (檔案日期)","author":"ShunYi 工程級標準","video":"","fas":""},{"no":1195,"file":"MyCADEncryptor-v0.lsp","cmd":"MyCADEncryptor-v0","cat":"系統/授權","desc":"MyCAD 加密器初版，輸入電腦名稱、日期、點數後以 Base64 模擬加密並即時預覽，附 trace log。","usage":"執行 MyCADEncryptor-v0 → 輸入電腦名稱/日期/點數 → 預覽加密字串 → 確定","level":6,"lt":"✅","ver":"20250816 (檔案日期)","author":"—","video":"","fas":""},{"no":1196,"file":"MyCADProj.LSP","cmd":"MCP、MyCADProj","cat":"繪圖","desc":"選取平面弧或聚合線，依等分數於兩條邊界線間繪製立面投射等分線，可只處理弧段、指定圖層與投射方向。","usage":"執行 MCP → 對話框設定等分數/圖層/方向/弧線篩選 → 選取弧或聚合線與邊界線 → 產生投射線","level":8,"lt":"✅","ver":"2026-08-30 (檔案日期)","author":"ChengBar (MyCAD)","video":"https://youtu.be/5uqyv-Fsu2I","fas":"fas/MyCADProj.fas"},{"no":1197,"file":"mycha.lsp","cmd":"mycha、myfillet、mychafillet","cat":"修改","desc":"選取直線/聚合線先合併，再對聚合線轉角一次倒角或圓角（使用目前 CHAMFER/FILLET 設定）。","usage":"執行 mycha（或 myfillet）→ 選取線或聚合線 → 自動 Join 並對轉角倒角/圓角","level":5,"lt":"✅","ver":"2025-10-15 (檔案日期)","author":"—","video":"","fas":"fas/mycha.fas"},{"no":1198,"file":"MYGRID.lsp","cmd":"MYGRID","cat":"標註","desc":"對軸線寫入 XData 編號（數字/字母自動遞增），再依勾選方位於線端自動生成軸標圓圈圖塊並防重疊。","usage":"執行 MYGRID → 對話框設定編號/方位/比例 → 選取軸線寫入編號 → 批次生成軸標圖塊","level":9,"lt":"✅","ver":"2026-05-21 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MYGRID.fas"},{"no":1199,"file":"mylayer_curr.lsp","cmd":"mylayer_curr","cat":"圖層","desc":"點選外參或圖塊內的物件，把其圖層設為目前圖層。","usage":"執行 mylayer_curr → 點選物件（含外參內物件）→ 確認 Y/N → 圖層設為目前層","level":4,"lt":"✅","ver":"20220716","author":"chengshunyi","video":"","fas":"fas/mylayer_curr.fas"},{"no":1200,"file":"mylayer_curr_freeze.lsp","cmd":"mylayer_curr_freeze","cat":"圖層","desc":"點選外參或圖塊內物件，將其圖層設為目前層後再凍結其他/相關圖層。","usage":"執行 mylayer_curr_freeze → 點選物件 → 確認 Y/N → 設目前層並凍結","level":4,"lt":"✅","ver":"20220716","author":"chengshunyi","video":"","fas":"fas/mylayer_curr_freeze.fas"},{"no":1201,"file":"mylayer_curr_off.lsp","cmd":"mylayer_curr_off","cat":"圖層","desc":"點選外參或圖塊內物件，將其圖層設為目前層並關閉相關圖層。","usage":"執行 mylayer_curr_off → 點選物件 → 確認 Y/N → 設目前層並關閉","level":4,"lt":"✅","ver":"20220716","author":"chengshunyi","video":"","fas":"fas/mylayer_curr_off.fas"},{"no":1202,"file":"mylayer_folp.lsp","cmd":"mylayer_folp","cat":"圖層","desc":"點選外參物件，對其圖層一次執行凍結、關閉、不出圖、鎖定。","usage":"執行 mylayer_folp → 點選外參物件 → 圖層同時 FREEZE/OFF/NOPLOT/LOCK","level":4,"lt":"✅","ver":"20230611","author":"chengshunyi","video":"","fas":"fas/mylayer_folp.fas"},{"no":1203,"file":"mylayer_freeze.lsp","cmd":"mylayer_freeze","cat":"圖層","desc":"點選外參或圖塊內的物件，凍結其所在圖層。","usage":"執行 mylayer_freeze → 點選外參物件 → 圖層凍結（可連續）","level":3,"lt":"✅","ver":"20220716","author":"chengshunyi","video":"","fas":"fas/mylayer_freeze.fas"},{"no":1204,"file":"mylayer_freeze_vp.lsp","cmd":"mylayer_freeze_vp","cat":"圖層","desc":"點選外參物件，於目前視埠中凍結其圖層（VPLAYER）。","usage":"執行 mylayer_freeze_vp → 切到視埠內 → 點選外參物件 → 於該視埠凍結圖層","level":4,"lt":"✅","ver":"20210921 begin / 20220716 更新","author":"chengshunyi","video":"","fas":"fas/mylayer_freeze_vp.fas"},{"no":1205,"file":"mylayer_freeze_vp_l_p.LSP","cmd":"mylayer_freeze_vp_lic、mylayer_freeze_vp_pak","cat":"圖層","desc":"依圖層狀態（lic-/pak-）切換建照圖或發包圖視埠圖層顯示，lic 指令凍結建照圖層，pak 指令凍結發包圖層。","usage":"執行 mylayer_freeze_vp_lic（或 _pak）→ 自動載入/刪除 layer state → 於視埠凍結 lic-* 或 pak-* 圖層","level":5,"lt":"✅","ver":"20210921 begin / 20220716 更新","author":"chengshunyi","video":"","fas":"fas/mylayer_freeze_vp_l_p.fas"},{"no":1206,"file":"mylayer_freeze_vp_ppt.lsp","cmd":"mylayer_freeze_vp_ppt","cat":"圖層","desc":"出簡報圖用：以 ppt layer state 在視埠凍結 *|dim、txt、txt-t 等圖層。","usage":"執行 mylayer_freeze_vp_ppt → 自動檢查/刪除舊 ppt layerstate → 於視埠凍結 dim/txt/txt-t 圖層","level":5,"lt":"✅","ver":"20210921 begin / 20220716 更新","author":"chengshunyi","video":"","fas":"fas/mylayer_freeze_vp_ppt.fas"},{"no":1207,"file":"mylayer_lock.lsp","cmd":"mylayer_lock","cat":"圖層","desc":"點選外參或圖塊內物件，鎖定其所在圖層。","usage":"執行 mylayer_lock → 點選外參物件 → 圖層鎖定","level":3,"lt":"✅","ver":"20220716","author":"chengshunyi","video":"","fas":"fas/mylayer_lock.fas"},{"no":1208,"file":"mylayer_off.lsp","cmd":"mylayer_off","cat":"圖層","desc":"點選外參或圖塊內物件，關閉其所在圖層。","usage":"執行 mylayer_off → 點選外參物件 → 圖層關閉（可連續）","level":3,"lt":"✅","ver":"20220716","author":"chengshunyi","video":"","fas":"fas/mylayer_off.fas"},{"no":1209,"file":"MyMLeaderLister.LSP","cmd":"MyMLeaderLister","cat":"標註","desc":"讀取圖中所有多重引線型式，以對話框複選後依間距、換行數、引線角度與長度由下往上排列繪出樣品。","usage":"執行 MyMLeaderLister → 對話框勾選型式並設定間距/每行個數/角度/長度 → 指定插入點 → 產生樣品","level":6,"lt":"✅","ver":"2026-06-22 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/MyMLeaderLister.fas"},{"no":1210,"file":"MyPBFZ-AF.lsp","cmd":"MyPBFZ-AF","cat":"圖面管理","desc":"批次處理資料夾（含子目錄）內所有 DWG：Bind/Detach 外參、Purge、關閉/凍結指定圖層、另存版本，透過 script 執行。","usage":"執行 MyPBFZ-AF → 對話框選資料夾與勾選功能 → 按確定 → 產生 script 批次開檔處理","level":8,"lt":"❌","ver":"2026-03-05 (檔案日期)","author":"MyCAD","video":"","fas":"fas/MyPBFZ-AF.fas"},{"no":1211,"file":"MyPBFZ.LSP","cmd":"MyPBFZ","cat":"圖面管理","desc":"批次 Bind/Detach 外參、Purge、關閉/凍結圖層與另存版本，設定檔存 TEMP，指定資料夾內 DWG 逐一處理。","usage":"執行 MyPBFZ → 對話框選資料夾與勾選功能 → 確定 → script 批次處理 DWG","level":8,"lt":"❌","ver":"2026-04-20 (檔案日期)","author":"MyCAD","video":"","fas":"fas/MyPBFZ.fas"},{"no":1212,"file":"myprinterSetup.lsp","cmd":"（無，副程式庫）","cat":"出圖/列印","desc":"將印表機設定、描述與出圖樣式路徑（PrinterConfigDir 等）指向網路 ComputerSetting 資料夾，統一專案出圖環境。","usage":"載入檔案後由其他程式呼叫（需開啟網路位置的圖檔）→ 自動設定三個 Printer 路徑","level":3,"lt":"✅","ver":"20220716更新 / 2023-04-05 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/myprinterSetup.fas"},{"no":1213,"file":"myrect.LSP","cmd":"myrect","cat":"繪圖","desc":"選取兩條聚合線，求其交點並以其為對角建立 4 邊矩形聚合線。","usage":"執行 myrect → 選取兩條聚合線 → 自動畫出四邊矩形","level":4,"lt":"✅","ver":"20240524","author":"chengshunyi","video":"","fas":"fas/myrect.fas"},{"no":1214,"file":"MyRPATH-SET.LSP","cmd":"MyRPATH-SET","cat":"圖面管理","desc":"以對話框列出外部參考檔名，批次設定各外參的相對路徑，欄位可多組同時編輯。","usage":"執行 MyRPATH-SET → 對話框檢視外參清單 → 輸入/選取相對路徑 → 確定套用","level":8,"lt":"❌","ver":"20250212","author":"chengshunyi","video":"","fas":"fas/MyRPATH-SET.fas"},{"no":1215,"file":"MySlideImages_h.LSP","cmd":"MySlideImages","cat":"其他","desc":"DCL 幻燈片影像按鈕示範，顯示螺栓/螺帽等 slide 圖並回傳所選項。","usage":"執行 MySlideImages → 於對話框點選幻燈片圖 → 回傳選取名稱","level":6,"lt":"✅","ver":"2014-03-24 (檔案日期)","author":"—","video":"","fas":"fas/MySlideImages_h.fas"},{"no":1216,"file":"MyStart.lsp","cmd":"（無，副程式庫）","cat":"系統/授權","desc":"MyCAD 啟動載入檔，註冊文件切換 reactor，並載入 logo 與 read-pus-ez 等相依檔、設定系統/使用者圖庫路徑。","usage":"放入 acad 啟動載入 → 開啟/切換圖檔時自動載入 MyCAD 環境","level":8,"lt":"✅","ver":"2026-10-26 (檔案日期)","author":"MyCAD","video":"","fas":""},{"no":1217,"file":"ncopy-to-clayer.lsp","cmd":"ncopy-to-clayer","cat":"修改","desc":"選取外參或圖塊內的物件，複製到目前圖層上（以 nentsel 取巢狀物件）。","usage":"執行 ncopy-to-clayer → 點選外參/圖塊內物件 → 複製到目前層","level":4,"lt":"✅","ver":"20241217","author":"chengshunyi","video":"","fas":"fas/ncopy-to-clayer.fas"},{"no":1218,"file":"ncopy-to-DN.lsp","cmd":"ncopy-to-DN","cat":"文字","desc":"複製外參/圖塊內的圓（CIRCLE）至 DN 圖層，並以遞增編號文字標示於圓心，自動建立 DN 字型與圖層。","usage":"執行 ncopy-to-DN → 輸入起始編號 → 點選外參內的圓 → 複製圓並產生編號文字","level":5,"lt":"✅","ver":"20251114","author":"chengshunyi","video":"","fas":"fas/ncopy-to-DN.fas"},{"no":1219,"file":"NCOPY_LAYER.lsp","cmd":"NCOPY_LAYER","cat":"圖層","desc":"點選外參內物件，把外參中同圖層的所有物件複製到目前圖面，並可選擇刪除來源檔物件或凍結外參圖層。","usage":"執行 NCOPY_LAYER → 對話框選處理方式（刪除來源/凍結/不處理）→ 點選外參物件 → 複製同圖層物件","level":9,"lt":"⚠️","ver":"v1.2.4","author":"ChengBar (MyCAD)","video":"","fas":"fas/NCOPY_LAYER.fas"},{"no":1220,"file":"NCOPY_LAYER_HOLD.lsp","cmd":"NCOPY_LAYER","cat":"圖層","desc":"點選外參內物件，複製外參中同圖層物件至目前圖面，並可刪除來源檔物件或凍結外參圖層（舊版）。","usage":"執行 NCOPY_LAYER → 對話框選處理方式 → 點選外參物件 → 複製同圖層物件","level":9,"lt":"⚠️","ver":"v1.0.7","author":"ChengBar (MyCAD)","video":"","fas":"fas/NCOPY_LAYER_HOLD.fas"},{"no":1221,"file":"NestedEntInfo.lsp","cmd":"NESTEDENTINFO","cat":"查詢","desc":"分析外參或巢狀圖塊內圖元的真實圖層與屬性，可僅檢視、複製圖層/文字或於命令列傾印。","usage":"執行 NESTEDENTINFO → 點選外參/圖塊內物件 → 對話框顯示圖層與屬性 → 選擇檢視/複製/傾印","level":8,"lt":"⚠️","ver":"2026-08-04 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/NestedEntInfo.fas"},{"no":1222,"file":"nrefcopy.lsp","cmd":"nrefcopy","cat":"修改","desc":"以 REFEDIT 選取外參內的圖塊並複製到主圖，再關閉 REFEDIT 且不儲存修改。","usage":"執行 nrefcopy → 點選外參內物件 → 自動進入參考編輯、複製、移動後關閉","level":4,"lt":"✅","ver":"20231222","author":"chengshunyi","video":"","fas":"fas/nrefcopy.fas"},{"no":1223,"file":"NSUM.lsp","cmd":"NSUM","cat":"文字","desc":"連續點選含數字的文字（含圖塊內文字），過濾非數字字元後加總，並產生計算式文字，可設單位與小數位。","usage":"執行 NSUM → 對話框設字高/比例/單位/精度 → 連續點選數字文字（Enter 結束）→ 於指定處放置加總結果","level":6,"lt":"✅","ver":"20220716更新 / 2026-01-21 (檔案日期)","author":"MyCAD","video":"","fas":"fas/NSUM.fas"},{"no":1224,"file":"NUMBER.LSP","cmd":"number-0、number-1、number-2、number-3、number-4、number-5","cat":"文字","desc":"連續點選位置放置遞增序號文字，number-0~5 為不同格式（前綴、位數、對齊等）。","usage":"執行 number-1（等）→ 輸入起始編號 → 連續點選位置 → 依序產生編號文字","level":5,"lt":"✅","ver":"84.4.12 (民國年)","author":"—","video":"","fas":"fas/NUMBER.fas"},{"no":1225,"file":"numerotation.lsp","cmd":"numerotation","cat":"圖塊/屬性","desc":"建立序號圖塊（含屬性）並連續插入，自動遞增編號，必要時建立圖層與字型。","usage":"執行 numerotation → 指定起始編號 → 連續點選插入點 → 插入遞增序號圖塊","level":6,"lt":"✅","ver":"20240309","author":"chengshunyi","video":"","fas":"fas/numerotation.fas"},{"no":1226,"file":"NumInc.lsp","cmd":"numinc","cat":"文字","desc":"遞增編號套件：以文字、多行文字或屬性圖塊放置遞增的數字/字母，支援前綴後綴、多種定位工具及設定記憶。","usage":"執行 numinc → 於對話框設定類型/圖層/字型/字高/前後綴 → 依提示點選位置連續放置編號","level":9,"lt":"⚠️","ver":"2025-04-01 (檔案日期)","author":"Lee Mac","video":"","fas":"fas/NumInc.fas"},{"no":1227,"file":"nut-LT.lsp","cmd":"nut-LT","cat":"圖塊/屬性","desc":"對話框選擇 M4/M5/M6 螺帽，以免 ObjectDBX 方式從來源 DWG 載入動態圖塊定義後插入。","usage":"執行 nut-LT → 對話框選螺帽尺寸（含幻燈片預覽）→ 點選插入點 → 插入圖塊","level":6,"lt":"✅","ver":"2026-06-21 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/nut-LT.fas"},{"no":1228,"file":"nut.LSP","cmd":"nut","cat":"圖塊/屬性","desc":"對話框選擇 M4/M5/M6 螺帽，在支援路徑搜尋來源 DWG，以 ObjectDBX 複製圖塊定義後插入。","usage":"執行 nut → 對話框選螺帽尺寸 → 點選插入點 → 插入圖塊","level":6,"lt":"❌","ver":"2026-06-21 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/nut.fas"},{"no":1229,"file":"NV-from-MW.lsp","cmd":"NV-from-MW-mm、NV-from-MW-cm、NV-from-MW","cat":"出圖/列印","desc":"在模型空間框選範圍並設定比例，於指定配置空間自動建立視埠，可選圖框單位 mm 或 cm。","usage":"執行 NV-from-MW-mm → 框選模型範圍 → 輸入視埠比例 → 選配置並指定視埠中心點","level":7,"lt":"✅","ver":"20240217","author":"chengshunyi","video":"","fas":"fas/NV-from-MW.fas"},{"no":1230,"file":"obj-2-blk-n.lsp","cmd":"obj-2-blk-n","cat":"圖塊/屬性","desc":"依選取物件範圍自動以 BE-XX 命名建立圖塊，可略過圖塊與視埠物件並排除。","usage":"執行 obj-2-blk-n → 選取物件 → 自動依範圍取名建立圖塊","level":5,"lt":"✅","ver":"20240508","author":"chengshunyi","video":"","fas":"fas/obj-2-blk-n.fas"},{"no":1231,"file":"obj-2-blk.lsp","cmd":"obj-2-blk","cat":"圖塊/屬性","desc":"將選取的非圖塊物件逐一（或成組）轉成命名 BLOCK- 圖塊，並刪除原物件。","usage":"執行 obj-2-blk → 選取物件（排除圖塊/視埠）→ 自動建立圖塊並插入","level":5,"lt":"✅","ver":"20240509","author":"chengshunyi","video":"","fas":"fas/obj-2-blk.fas"},{"no":1232,"file":"obj-outline.lsp","cmd":"obj-outline","cat":"繪圖","desc":"選取多個物件，依各物件範圍（Bounding Box）畫出矩形外框聚合線。","usage":"執行 obj-outline → 選取物件 → 產生矩形外框","level":4,"lt":"✅","ver":"20240828","author":"chengshunyi（Bounding Box 取自 Lee Mac）","video":"","fas":"fas/obj-outline.fas"},{"no":1233,"file":"OBJ_ALIGN_CEN.LSP","cmd":"OBJ_ALIGN_CEN","cat":"對齊/排列","desc":"依指定圖層與篩選模式找出 LINE/CIRCLE，批次檢查指定圖塊是否干涉，干涉者以插入點為基準移到線圓幾何中心。","usage":"執行 OBJ_ALIGN_CEN → 對話框設定圖層/圖塊名稱/模式（全圖、窗選、圓內、360度掃描）→ 執行批次置中","level":9,"lt":"✅","ver":"2026-06-13","author":"ChengBar (MyCAD)","video":"","fas":"fas/OBJ_ALIGN_CEN.fas"},{"no":1234,"file":"objbb-align.lsp","cmd":"objbb-align","cat":"對齊/排列","desc":"將選取的多個物件依其幾何中心對齊於 X 軸或 Y 軸，基準可為集體中心或自訂點。","usage":"執行 objbb-align → 對話框選對齊方向與基準 → 選取物件（自訂點則指定點）→ 完成對齊","level":6,"lt":"✅","ver":"2026-06-19 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/objbb-align.fas"},{"no":1235,"file":"ObjectLock.lsp","cmd":"LockObjects、UnLockObjects、DisableLock","cat":"修改","desc":"以 reactor 鎖定選取物件使其無法被修改（修改即復原），可解鎖並停用，鎖定資訊存於圖面。","usage":"執行 LockObjects → 選取物件 → 物件被鎖定；UnLockObjects 解鎖；DisableLock 關閉機制","level":8,"lt":"✅","ver":"20220716更新 (檔案日期)","author":"Lee Mac","video":"","fas":"fas/ObjectLock.fas"},{"no":1236,"file":"obs-2-whipouto.lsp","cmd":"obs-2-whipouto","cat":"繪圖","desc":"由選取的圓、橢圓或含弧聚合線建立 Wipeout 遮罩（建在原物件圖層），可選擇刪除來源物件。","usage":"執行 obs-2-whipouto → 選取圓/橢圓/聚合線 → 輸入是否刪除來源 → 產生 Wipeout","level":6,"lt":"⚠️","ver":"20240310 (原版 OB2WO 10/03/07，2012 更新)","author":"Gilles Chanteau (gile)，chengshunyi 修改","video":"","fas":"fas/obs-2-whipouto.fas"},{"no":1237,"file":"OBT.lsp","cmd":"OBT","cat":"繪圖","desc":"為文字物件建立外框：以 BOUNDARY 轉 REGION 並 UNION 合併，再炸開成聚合線，並可刪除重複文字。","usage":"執行 OBT → 選取文字 → 自動產生輪廓聚合線","level":5,"lt":"❌","ver":"20231215","author":"chengshunyi","video":"","fas":"fas/OBT.fas"},{"no":1238,"file":"off-d-extline.lsp","cmd":"off-d-extline、off-d-extline-1、on-d-extline","cat":"標註","desc":"關閉或開啟尺寸標註兩側延伸線，並可把指定文字覆寫為尺寸文字、調整文字間距。","usage":"執行 off-d-extline → 選取標註 → 兩側延伸線關閉；on-d-extline 重新開啟","level":4,"lt":"✅","ver":"20230716","author":"chengshunyi","video":"","fas":"fas/off-d-extline.fas"},{"no":1239,"file":"offhat.LSP","cmd":"offhat","cat":"繪圖","desc":"對選取的聚合線雙側等距偏移，並在兩條偏移線之間的閉合區域建立 ANSI31 填充，可控制圖層與填充。","usage":"執行 offhat → 設定偏移距離 → 選取聚合線 → 自動雙側偏移並填充","level":6,"lt":"✅","ver":"20230404（Offset Hatch 原版 Lee Mac 2012）","author":"Lee Mac，chengshunyi 修改","video":"","fas":""},{"no":1240,"file":"offset2side.lsp","cmd":"offset2side","cat":"修改","desc":"輸入偏移距離，對選取物件向兩側各偏移一次。","usage":"執行 offset2side → 選取物件 → 輸入距離 → 兩側各產生偏移物件","level":3,"lt":"✅","ver":"20250708","author":"chengshunyi","video":"","fas":"fas/offset2side.fas"},{"no":1241,"file":"OffsetBoth.lsp","cmd":"OFFSETBOTH、OB-h、OB-d","cat":"修改","desc":"雙側偏移工具，可設偏移距離、是否刪除來源、結果圖層（來源/目前/指定）與顏色；OB-h 保留來源、OB-d 刪除來源。","usage":"執行 OFFSETBOTH → 對話框設定距離/圖層/顏色/保留或刪除 → 選取物件 → 雙側偏移","level":7,"lt":"⚠️","ver":"2026-09-14 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/OffsetBoth.fas"},{"no":1242,"file":"ol-align-gap.lsp","cmd":"ol-align-gap","cat":"對齊/排列","desc":"選取基準線後，將其他聚合線依指定距離等距對齊到基準線。","usage":"執行 ol-align-gap → 指定偏移距離（兩點或輸入）→ 選基準線 → 選其他物件 → 等距對齊","level":5,"lt":"✅","ver":"20240401","author":"chengshunyi","video":"","fas":"fas/ol-align-gap.fas"},{"no":1243,"file":"OPEN-PLOT-DWG2PDF-SCR.LSP","cmd":"OPEN-PLOT-DWG2PDF-SCR","cat":"出圖/列印","desc":"選擇資料夾後，將內含 DWG 逐一產生批次開圖、載入自動出圖程式的 script，輸出到 D:\\open-NOsave.scr。","usage":"執行 OPEN-PLOT-DWG2PDF-SCR → 選擇 DWG 資料夾 → 產生 scr → 以 SCRIPT 執行批次出 PDF","level":5,"lt":"❌","ver":"2017.03.29","author":"Cheng Shun-Yi","video":"","fas":"fas/OPEN-PLOT-DWG2PDF-SCR.fas"},{"no":1244,"file":"open-recover.lsp","cmd":"open-recover","cat":"圖面管理","desc":"批次開啟資料夾內 DWG 執行 Recover（可含外參）並儲存，產生 script 執行；LT 版以選檔取路徑。","usage":"執行 open-recover → 對話框選 DWG 目錄與選項 → 按執行 → 產生 scr 批次處理","level":8,"lt":"✅","ver":"2025-12-10 (檔案日期)","author":"MyCAD","video":"https://youtu.be/HrztKk_3KrE","fas":"fas/open-recover.fas"},{"no":1245,"file":"open-save-p5.lsp","cmd":"open-save-p5","cat":"圖面管理","desc":"選擇資料夾後產生 script，批次開啟 DWG 執行 -purge all、qsave 並關閉。","usage":"執行 open-save-p5 → 選擇 DWG 目錄 → 產生 D:\\open-save-p5.scr → SCRIPT 執行","level":5,"lt":"✅","ver":"20250927","author":"Cheng Shun-Yi","video":"","fas":"fas/open-save-p5.fas"},{"no":1246,"file":"open-save-pX-ui.LSP","cmd":"open-save-pX-ui","cat":"圖面管理","desc":"對話框設定 DWG 目錄、Purge 次數與是否儲存關閉，產生 script 批次開圖 purge 存圖。","usage":"執行 open-save-pX-ui → 對話框選目錄/Purge 次數/儲存 → 執行 → 自動跑 script","level":7,"lt":"❌","ver":"2025-09-27 (檔案日期)","author":"MyCAD","video":"","fas":"fas/open-save-pX-ui.fas"},{"no":1247,"file":"open-save-pXO-ui.LSP","cmd":"open-save-pXO-ui","cat":"圖面管理","desc":"批次 Purge（內建 Audit）工具，對話框設目錄/Purge 次數/儲存關閉，產生 script 批次處理 DWG，支援 LT。","usage":"執行 open-save-pXO-ui → 對話框選目錄與 Purge 次數 → 執行 → 批次開圖處理","level":7,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"MyCAD","video":"https://youtu.be/r_UYJ6FTMpY","fas":"fas/open-save-pXO-ui.fas"},{"no":1248,"file":"open-save.LSP","cmd":"open-save","cat":"圖面管理","desc":"選擇資料夾後產生 script，批次開啟 DWG 載入 delete_unload_xref、Purge、qsave 並關閉。","usage":"執行 open-save → 選擇 DWG 目錄 → 產生 D:\\open-save.scr → SCRIPT 執行","level":5,"lt":"✅","ver":"2017.03.29 / 20220716更新","author":"Cheng Shun-Yi","video":"","fas":"fas/open-save.fas"},{"no":1249,"file":"open-sym.LSP","cmd":"open-sym","cat":"圖塊/屬性","desc":"樓板開口符號及註解工具：依長寬自動建立 OPEN-長x寬 圖塊（含止水墩、護角選項、外框與交叉線）並插入。","usage":"執行 open-sym → 對話框輸入長/寬/文字高或選現有 OPEN 圖塊，勾選止水墩/護角 → 指定插入點","level":8,"lt":"✅","ver":"2026-01-08 (檔案日期)","author":"MyCAD","video":"","fas":"fas/open-sym.fas"},{"no":1250,"file":"open-x-sym.LSP","cmd":"open-x-sym","cat":"圖塊/屬性","desc":"樓板開口符號工具，產生僅含外框（不出圖）、交叉線及註解的 OPEN-X 開口圖塊並插入。","usage":"執行 open-x-sym → 對話框輸入尺寸或選現有圖塊 → 設定是否印出文字 → 指定插入點","level":8,"lt":"✅","ver":"2026-01-18 (檔案日期)","author":"MyCAD","video":"","fas":"fas/open-x-sym.fas"},{"no":1251,"file":"open-X.lsp","cmd":"open-X","cat":"繪圖","desc":"選取矩形聚合線，於每個矩形內畫交叉線（HIDDEN 線型）標示樓板開口。","usage":"執行 open-X → 選取矩形聚合線 → 自動畫交叉線","level":5,"lt":"✅","ver":"20250630（初版 20240616）","author":"chengshunyi","video":"","fas":"fas/open-X.fas"},{"no":1252,"file":"OpenDwgsCmds.LSP","cmd":"CDC、ODC、OpenDwgsCmds、QSA","cat":"圖面管理","desc":"對所有已開啟圖檔執行指令或函式（透過 DVB/VBA 輔助），QSA 為全部儲存，CDC 目前圖、ODC 全部圖。","usage":"執行 ODC → 輸入要執行的指令或函式（END 結束）→ 於所有開啟圖檔依序執行","level":8,"lt":"❌","ver":"R2（2-7-07，5-1-07 更新）","author":"Terry Miller","video":"","fas":"fas/OpenDwgsCmds.fas"},{"no":1253,"file":"OpenFolderUI.LSP","cmd":"OpenFolderUI","cat":"圖面管理","desc":"讀取 folders.txt 常用資料夾清單，以對話框按鈕列出，點選後以檔案總管開啟。","usage":"執行 OpenFolderUI → 對話框顯示資料夾按鈕 → 點選資料夾 → explorer 開啟","level":6,"lt":"✅","ver":"20220716更新 / 2025-08-06 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/OpenFolderUI.fas"},{"no":1254,"file":"OpenUI-cad.LSP","cmd":"OpenUI-cad-R、OpenUI-cad-O、OpenUI-cad","cat":"圖面管理","desc":"讀取專案常用資料夾清單，選資料夾後選取 DWG 開啟，-R 為唯讀、-O 為正常模式。","usage":"執行 OpenUI-cad → 對話框選專案資料夾 → 選取 dwg 檔 → 以唯讀或正常模式開啟","level":7,"lt":"⚠️","ver":"20220716更新 / 2025-08-05 (檔案日期)","author":"chengshunyi（含 Lee Mac LM:explore）","video":"","fas":"fas/OpenUI-cad.fas"},{"no":1255,"file":"outline-al-s.LSP","cmd":"outline-al-s","cat":"面積/數量統計","desc":"外殼面積簡算：讀取圖面單位與比例，由選取聚合線/圓計算周長、樓高與立面外殼面積及樓地板面積並標註 MText。","usage":"執行 outline-al-s → 選取外殼聚合線 → 輸入層數/樓高 → 放置計算結果文字","level":7,"lt":"✅","ver":"20240803","author":"chengshunyi","video":"","fas":"fas/outline-al-s.fas"},{"no":1256,"file":"OutlineObjects.lsp","cmd":"outline、outline-d、outline-h","cat":"繪圖","desc":"對選取的所有物件外圍產生封閉聚合線或面域外框（透過 BOUNDARY），可選擇是否刪除原物件。","usage":"執行 outline → 選取物件 → 選擇是否刪除原物件 → 產生外框","level":6,"lt":"✅","ver":"v1.0 2014-11-30","author":"Lee Mac","video":"https://youtu.be/wWlA2IBPWo0","fas":"fas/OutlineObjects.fas"},{"no":1257,"file":"P-BL-CH-SC.LSP","cmd":"p-bl-ch-sc","cat":"圖塊/屬性","desc":"點選圖塊，批次修改該圖塊所有參照的比例係數。","usage":"執行 p-bl-ch-sc → 點選圖塊 → 輸入新比例 → 同名圖塊全部更新","level":4,"lt":"✅","ver":"2008.05.29","author":"Shun_Yi Studio","video":"","fas":"fas/P-BL-CH-SC.fas"},{"no":1258,"file":"p-bl-move-tag.lsp","cmd":"p-bl-move-tag、p-bl-move-tag-re","cat":"圖塊/屬性","desc":"點選動態圖塊並修改其五金符號位置動態參數，移至原點（0,0）或指定位置，-re 為還原。","usage":"執行 p-bl-move-tag → 點選動態圖塊 → 輸入 X/Y 位移 → 更新動態參數","level":6,"lt":"✅","ver":"20250428","author":"chengshunyi","video":"","fas":"fas/p-bl-move-tag.fas"},{"no":1259,"file":"P2W.LSP","cmd":"P2W","cat":"繪圖","desc":"將弧、含弧聚合線或直線聚合線轉成 Wipeout，弧段可離散化，未刪原物件時自動置頂其繪圖順序。","usage":"執行 P2W → 對話框設定弧段等分數/刪除原物件/邊框顯示 → 選取物件 → 產生 Wipeout","level":8,"lt":"✅","ver":"2026-08-29 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/P2W.fas"},{"no":1260,"file":"pagesetup-to-dwg2pdf.LSP","cmd":"pagesetup-to-a1dwg2pdf、pagesetup-to-a3dwg2pdf","cat":"出圖/列印","desc":"將所有配置（layout）的頁面設定套用為 A1 或 A3 DWG2PDF 頁面設定。","usage":"執行 pagesetup-to-a1dwg2pdf（或 a3）→ 所有 layout 自動套用頁面設定","level":5,"lt":"✅","ver":"20231203","author":"chengshunyi","video":"","fas":"fas/pagesetup-to-dwg2pdf.fas"},{"no":1261,"file":"PAI.LSP","cmd":"PAI、PlineAreaInfo","cat":"面積/數量統計","desc":"針對聚合線寫入公寓大廈管理條例面積資訊（專有/大公/小公等）、標註、SOLID 著色，並輸出 CSV 或圖面表格統計。","usage":"執行 PAI → 對話框選棟別/戶別/類組 → 選取聚合線寫入與標註 → 依戶別/類組上色 → 輸出統計表","level":9,"lt":"✅","ver":"2026-09-06 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/PAI.fas"},{"no":1262,"file":"PAKFillCheck.LSP","cmd":"PFC、PAKFillCheck","cat":"文字","desc":"在多個 Layout 中選擇並自動填入版次日期等文字，設定存於 TEMP 的 TXT，文字樣式從清單選取。","usage":"執行 PFC → 對話框勾選 Layout、文字樣式與版次/日期 → 確定 → 自動填充","level":8,"lt":"✅","ver":"2026-09-08 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/PAKFillCheck.fas"},{"no":1263,"file":"PAKFillCheck5.lsp","cmd":"PFC5、PAKFillCheck5","cat":"文字","desc":"多 Layout 版次日期自動填充（解析修正版），讀寫 TEMP 組態 TXT 保存 PAK_STR 等設定，對話框選 Layout 與圖層/樣式。","usage":"執行 PFC5 → 對話框勾選 Layout、圖層、樣式與版次文字 → 確定 → 自動填充","level":8,"lt":"✅","ver":"2026-09-08 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/PAKFillCheck5.fas"},{"no":1264,"file":"paline2cplines(平行線2封閉pline).LSP","cmd":"paline2cplines","cat":"繪圖","desc":"選取 RCW 圖層的成對平行線，轉成封閉聚合線並建立 SOLID 填充，可選擇是否保留原線。","usage":"執行 paline2cplines → 選取 RCW 層平行線 → 自動產生封閉聚合線與 RCW-HATCH","level":7,"lt":"✅","ver":"20230115（原版 Tharwat 25.Mar.2021）","author":"Tharwat，chengshunyi 修改","video":"","fas":"fas/paline2cplines(平行線2封閉pline).fas"},{"no":1265,"file":"paline2hatch(平行線2hatch).LSP","cmd":"paline2hatch","cat":"繪圖","desc":"選取 RCW 圖層的成對平行線，產生封閉聚合線並 SOLID 填充到 RCW-HATCH 圖層。","usage":"執行 paline2hatch → 選取 RCW 層平行線 → 自動畫出填充","level":7,"lt":"✅","ver":"20230115（原版 Tharwat 25.Mar.2021）","author":"Tharwat，chengshunyi 修改","video":"","fas":"fas/paline2hatch(平行線2hatch).fas"},{"no":1266,"file":"paline2hatch.LSP","cmd":"paline2hatch","cat":"繪圖","desc":"選取 RCW 圖層平行線，自動建立 RCW-hatch 圖層並產生 SOLID 填充，完成後調整繪圖順序。","usage":"執行 paline2hatch → 選取平行線 → 自動建立圖層與填充 → 調整 draworder","level":7,"lt":"✅","ver":"20230115 / 2024-06-05 (檔案日期)","author":"Tharwat，chengshunyi 修改","video":"","fas":"fas/paline2hatch.fas"},{"no":1267,"file":"PatGrid.lsp","cmd":"PatGrid","cat":"繪圖","desc":"批次讀取資料夾內所有 .pat 檔，依方格尺寸排列繪出邊界、Hatch 與圖案名稱標註，可設比例。","usage":"執行 PatGrid → 對話框選 PAT 資料夾、方格尺寸 X/Y 與比例 → 確定 → 產生圖案樣本方格","level":8,"lt":"⚠️","ver":"v1.0.11 2026-10-27","author":"ChengBar (MyCAD)","video":"https://youtu.be/MYrprTZYNWU","fas":"fas/PatGrid.fas"},{"no":1268,"file":"path.lsp","cmd":"path","cat":"繪圖","desc":"依指定基準點排序選取的圖塊，取各圖塊外框中點連成一條聚合線路徑。","usage":"執行 path → 選取圖塊 → 指定排序起點 → 產生通過各圖塊中點的聚合線","level":5,"lt":"✅","ver":"20220716（原 6.1.2018）","author":"RJP，chengshunyi 修改","video":"","fas":"fas/path.fas"},{"no":1269,"file":"PathAverage.lsp","cmd":"PAv","cat":"繪圖","desc":"選取兩條路徑物件，依分段數在對應點取中點，繪出兩者平均路徑的聚合線。","usage":"執行 PAv → 選取第一條與第二條路徑 → 輸入分段數 → 產生平均路徑","level":7,"lt":"✅","ver":"2014-10-21","author":"Kent Cooper","video":"","fas":"fas/PathAverage.fas"},{"no":1270,"file":"pdim-c.lsp","cmd":"pdim-c","cat":"標註","desc":"選取多條聚合線一次標註各邊長度（步行距離專用），自動建立步行距離圖層與樣式，並可輸入文字代碼。","usage":"執行 pdim-c → 選取聚合線 → 輸入代碼 → 依邊長自動標註","level":7,"lt":"⚠️","ver":"20220716更新 / 2023-06-06 (檔案日期)","author":"chengshunyi（PDIM 原版他人）","video":"","fas":"fas/pdim-c.fas"},{"no":1271,"file":"pdim-c1-t49.lsp","cmd":"pdim-c1","cat":"標註","desc":"步行距離標尺寸（DCL 版）：選聚合線後依樣式、單位、字高標註各邊並寫計算式與編號，含使用期限/次數控管。","usage":"執行 pdim-c1 → 對話框設定圖層/樣式/單位/字高/編號 → 選取聚合線 → 標註尺寸與計算式","level":9,"lt":"✅","ver":"20231121 / 20230513更新","author":"chengshunyi","video":"https://youtu.be/FWPLZe2xz6A","fas":"fas/pdim-c1-t49.fas"},{"no":1272,"file":"pdim-c1.lsp","cmd":"pdim-c1","cat":"標註","desc":"步行距離標尺寸（新版）：對話框設定後選聚合線標註各邊，自動生成箭頭、計算式與編號，並判斷 CAD 版本。","usage":"執行 pdim-c1 → 對話框設定圖層/單位/字高/編號 → 選取聚合線 → 標註尺寸與計算式","level":9,"lt":"✅","ver":"20250506","author":"chengshunyi","video":"https://youtu.be/FWPLZe2xz6A","fas":"fas/pdim-c1.fas"},{"no":1273,"file":"pdim-i-bylayer.LSP","cmd":"pdim-i-bylayer、dim-sw-ab","cat":"標註","desc":"選取多條聚合線，把尺寸標在內側，標註改依聚合線圖層（DIM-PL 等）；dim-sw-ab 切換內外側。","usage":"執行 pdim-i-bylayer → 選取聚合線 → 自動標註內側邊長","level":7,"lt":"✅","ver":"20240803","author":"chengshunyi","video":"https://youtu.be/lcM1wYR3qL0","fas":"fas/pdim-i-bylayer.fas"},{"no":1274,"file":"pdim-i.LSP","cmd":"pdim-i、dim-sw-ab","cat":"標註","desc":"選取多條聚合線，將尺寸標在聚合線內側，文字位置置中並調整間隔。","usage":"執行 pdim-i → 選取聚合線 → 自動標註內側邊長","level":7,"lt":"✅","ver":"20240220","author":"chengshunyi","video":"https://youtu.be/lcM1wYR3qL0","fas":"fas/pdim-i.fas"},{"no":1275,"file":"pdim-lt.lsp","cmd":"pdim-lt","cat":"標註","desc":"選取多條聚合線一次標註各邊長度（使用專用標註型式 PDIM），LT 相容版。","usage":"執行 pdim-lt → 選取聚合線 → 依標註型式標註各邊","level":6,"lt":"✅","ver":"20211024 / 2022-11-20 (檔案日期)","author":"ChengBar（PDIM 原版他人）","video":"","fas":"fas/pdim-lt.fas"},{"no":1276,"file":"pdim-nc-i.LSP","cmd":"pdim-nc-i","cat":"標註","desc":"選取多條聚合線，尺寸預設標內側並加上關聯，支援 mm/cm/m 換算為公尺，可選 Outside/Inside。","usage":"執行 pdim-nc-i → 選取聚合線 → 選擇內外側 → 標註","level":7,"lt":"✅","ver":"20230824","author":"chengshunyi","video":"","fas":"fas/pdim-nc-i.fas"},{"no":1277,"file":"pdim-nc-in.LSP","cmd":"pdim-nc-in","cat":"標註","desc":"多聚合線尺寸標註，固定標在內側並加上關聯，單位依 read-pus 設定換算。","usage":"執行 pdim-nc-in → 選取聚合線 → 自動標註內側邊長","level":7,"lt":"✅","ver":"20230824","author":"chengshunyi","video":"","fas":"fas/pdim-nc-in.fas"},{"no":1278,"file":"pdim-nc-o.LSP","cmd":"pdim-nc-o","cat":"標註","desc":"選取多條聚合線，尺寸預設標外側並加上關聯，可選 Outside/Inside。","usage":"執行 pdim-nc-o → 選取聚合線 → 選擇內外側 → 標註","level":7,"lt":"✅","ver":"20230824","author":"chengshunyi","video":"","fas":"fas/pdim-nc-o.fas"},{"no":1279,"file":"pdim-nc-on.LSP","cmd":"pdim-nc-on","cat":"標註","desc":"多聚合線尺寸標註，固定標在外側並加上關聯，單位依 read-pus 設定換算。","usage":"執行 pdim-nc-on → 選取聚合線 → 自動標註外側邊長","level":7,"lt":"✅","ver":"20230824","author":"chengshunyi","video":"","fas":"fas/pdim-nc-on.fas"},{"no":1280,"file":"pdim-nc.LSP","cmd":"pdim-nc","cat":"標註","desc":"多聚合線尺寸標註 DCL 版：對話框選內/外側、單位、字高、圖層與型式，加上關聯並可加編號。","usage":"執行 pdim-nc → 對話框設定內外側/單位/字高/型式 → 選取聚合線 → 標註","level":8,"lt":"✅","ver":"20231111（初版 20230824）","author":"chengshunyi","video":"","fas":"fas/pdim-nc.fas"},{"no":1281,"file":"pdim-o-bylayer.lsp","cmd":"pdim-o-bylayer","cat":"標註","desc":"選取多條聚合線，把尺寸標在外側，圖層依聚合線圖層（DIM-PL）。","usage":"執行 pdim-o-bylayer → 選取聚合線 → 自動標註外側邊長","level":7,"lt":"✅","ver":"20240803","author":"chengshunyi","video":"","fas":"fas/pdim-o-bylayer.fas"},{"no":1282,"file":"pdim-o.lsp","cmd":"pdim-o","cat":"標註","desc":"選取多條聚合線，把尺寸標在聚合線外側，文字置中並調整間隔。","usage":"執行 pdim-o → 選取聚合線 → 自動標註外側邊長","level":7,"lt":"✅","ver":"20240220","author":"chengshunyi","video":"","fas":"fas/pdim-o.fas"},{"no":1283,"file":"pdim-s-1-l-c.lsp","cmd":"pdim-s-1-l-c","cat":"標註","desc":"選取聚合線標註各邊長度並寫出含編號與線段長度的計算式（可輸入代碼），自動匯入步行距離標註型式（CM 轉 M）。","usage":"執行 pdim-s-1-l-c → 輸入代碼/起始編號 → 選取聚合線 → 標註尺寸並放置計算式","level":7,"lt":"⚠️","ver":"20221119 (檔案日期)","author":"chengshunyi（PDIM 原版他人）","video":"","fas":"fas/pdim-s-1-l-c.fas"},{"no":1284,"file":"pdim-s-1-l-lt.lsp","cmd":"pdim-s-1-l-lt","cat":"標註","desc":"步行距離計算式標註 LT 版：選取聚合線產生含編號與線段長度的計算式文字，並顯示 OK/NO OK 檢核。","usage":"執行 pdim-s-1-l-lt → 選取聚合線 → 輸入文字位置 → 標註計算式與判定","level":7,"lt":"✅","ver":"20211024 / 2022-11-20 (檔案日期)","author":"ChengBAR","video":"","fas":"fas/pdim-s-1-l-lt.fas"},{"no":1285,"file":"pdim-s-1-l.lsp","cmd":"pdim-s-1-l","cat":"標註","desc":"步行距離計算式標註：選取聚合線產生含編號與線段長度的計算式，並顯示 OK/NO OK 判定。","usage":"執行 pdim-s-1-l → 選取聚合線 → 標註計算式","level":7,"lt":"✅","ver":"20211024 / 2022-07-16 (檔案日期)","author":"ChengBAR","video":"","fas":"fas/pdim-s-1-l.fas"},{"no":1286,"file":"pdim-s-1.lsp","cmd":"pdim-s-1","cat":"標註","desc":"選取聚合線產生含編號的計算式文字（簡化版）並標示 OK/NO OK 檢核。","usage":"執行 pdim-s-1 → 選取聚合線 → 標註計算式","level":6,"lt":"✅","ver":"20211024 / 2023-01-19 (檔案日期)","author":"ChengBAR","video":"","fas":"fas/pdim-s-1.fas"},{"no":1287,"file":"pdim-s-l-c.lsp","cmd":"pdim-s-l-c","cat":"標註","desc":"選取聚合線標註各邊長並寫出含線段長度的計算式，自動匯入步行距離標註型式。","usage":"執行 pdim-s-l-c → 輸入代碼 → 選取聚合線 → 標註尺寸與計算式","level":7,"lt":"⚠️","ver":"20221124 (檔案日期)","author":"chengshunyi（PDIM 原版他人）","video":"","fas":"fas/pdim-s-l-c.fas"},{"no":1288,"file":"pdim-s-l-lt .lsp","cmd":"pdim-s-l-lt","cat":"標註","desc":"步行距離計算式標註 LT 版（無編號）：選聚合線產生含線段長度的計算式與 OK/NO OK 判定。","usage":"執行 pdim-s-l-lt → 選取聚合線 → 標註計算式","level":7,"lt":"✅","ver":"20211024 / 2022-11-24 (檔案日期)","author":"ChengBAR","video":"","fas":"fas/pdim-s-l-lt .fas"},{"no":1289,"file":"pdim-s-l.lsp","cmd":"pdim-s-l","cat":"標註","desc":"選取聚合線標註含線段長度的計算式文字，並顯示 OK/NO OK 判定。","usage":"執行 pdim-s-l → 選取聚合線 → 標註計算式","level":6,"lt":"✅","ver":"20211024 / 2022-07-16 (檔案日期)","author":"ChengBAR","video":"","fas":"fas/pdim-s-l.fas"},{"no":1290,"file":"pdim-s.lsp","cmd":"pdim-s","cat":"標註","desc":"選取聚合線標註計算式文字（簡易版），並判定是否超過距離限制。","usage":"執行 pdim-s → 選取聚合線 → 標註計算式","level":6,"lt":"✅","ver":"20211024 / 2022-07-16 (檔案日期)","author":"ChengBAR","video":"","fas":"fas/pdim-s.fas"},{"no":1291,"file":"pdim.lsp","cmd":"pdim","cat":"標註","desc":"選取多條 LWPolyline 一次標註各邊長度，依目前標註型式，若無步行距離樣式則自動由範例 DWG 匯入。","usage":"執行 pdim → 選取聚合線 → 自動對各邊標註尺寸","level":7,"lt":"✅","ver":"20220716更新 / 2023-06-06 (檔案日期)","author":"ChengBar（PDIM 原版他人）","video":"","fas":"fas/pdim.fas"},{"no":1292,"file":"pe-join-line.lsp","cmd":"pe-join-line","cat":"修改","desc":"以 PEDIT 多重接合所選直線、弧、聚合線，指定接合距離（開口門窗）使不連續者也接成封閉聚合線。","usage":"執行 pe-join-line → 選取線/弧/聚合線 → 自動以容許距離接合","level":3,"lt":"✅","ver":"20240407","author":"chengshunyi","video":"","fas":""},{"no":1293,"file":"PFBWC.lsp","cmd":"（無，副程式庫）","cat":"圖塊/屬性","desc":"批次修改所選圖塊屬性的 tag 名稱（舊 PP 改新 P1），原圖塊定義需同步修改並重新插入。","usage":"載入後呼叫函式 → 窗選所有要更改的圖塊 → 屬性 tag 改名","level":5,"lt":"✅","ver":"2026-01-17 (檔案日期)","author":"—","video":"","fas":"fas/PFBWC.fas"},{"no":1294,"file":"pick-att-change-width.LSP","cmd":"pick-att-change-width","cat":"圖塊/屬性","desc":"點選屬性顯示目前寬度比，輸入新寬度（預設 0.7），可選是否套用到同名圖塊的所有屬性。","usage":"執行 pick-att-change-width → 點選屬性 → 輸入新寬度 → 選擇是否套用所有同名圖塊","level":5,"lt":"✅","ver":"20210610 / 20220716更新","author":"chengshunyi","video":"","fas":"fas/pick-att-change-width.fas"},{"no":1295,"file":"pick-AX-plt-pdf.lsp","cmd":"pick-A1-plt-pdf、pick-A3-plt-pdf","cat":"出圖/列印","desc":"點選圖框後以視窗範圍單張出圖為 PDF（A1 或 A3），自動換算比例並使用對應筆寬表，檔名取自圖檔位置。","usage":"執行 pick-A1-plt-pdf（或 A3）→ 點選圖框 → 自動計算比例並 -plot 輸出 PDF","level":7,"lt":"✅","ver":"20240412","author":"chengshunyi","video":"","fas":"fas/pick-AX-plt-pdf.fas"},{"no":1296,"file":"pick-bb.LSP","cmd":"pick-bb","cat":"標註","desc":"氣泡/標籤編號工具：對話框設定字高、圓點與箭頭，依 DIMTXT/DIMSCALE 繪製圓形編號泡泡引線。","usage":"執行 pick-bb → 對話框設定起始編號/字高/點或箭頭 → 點選位置 → 產生編號氣泡","level":7,"lt":"✅","ver":"20241006","author":"chengshunyi","video":"","fas":"fas/pick-bb.fas"},{"no":1297,"file":"pick-po-2list.lsp","cmd":"pick-po-2list","cat":"查詢","desc":"連續點選多個點並收集成點座標串列。","usage":"執行 pick-po-2list → 依序點選各點 → Enter 結束並回傳點串列","level":1,"lt":"✅","ver":"2024-12-15 (檔案日期)","author":"—","video":"","fas":"fas/pick-po-2list.fas"},{"no":1298,"file":"pick-xy-auto.lsp","cmd":"pick-xy-auto","cat":"文字","desc":"放置文字並以功能變數（Field）連動插入點 X、Y 座標值，座標變動時文字自動更新。","usage":"執行 pick-xy-auto → 指定插入點 → 產生連動座標的文字","level":5,"lt":"✅","ver":"20231223","author":"chengshunyi（ObjectID 函式 Lee Mac）","video":"","fas":"fas/pick-xy-auto.fas"},{"no":1299,"file":"picktxtstyle.LSP","cmd":"picktxtstyle、pckst","cat":"文字","desc":"點選一個文字物件，將其文字樣式設為目前文字樣式。","usage":"執行 pckst → 點選文字物件 → 該樣式設為目前樣式","level":3,"lt":"✅","ver":"20230115","author":"chengshunyi","video":"","fas":"fas/picktxtstyle.fas"},{"no":1300,"file":"pit-open.lsp","cmd":"pit-open","cat":"繪圖","desc":"選取矩形聚合線，於其中繪製 tree-hole/開口標示（交叉線 HIDDEN 線型與 solid 填充）。","usage":"執行 pit-open → 選取矩形聚合線 → 自動畫出開口符號","level":5,"lt":"✅","ver":"20240616","author":"chengshunyi","video":"","fas":"fas/pit-open.fas"},{"no":1301,"file":"pit-sym.lsp","cmd":"pit-sym","cat":"圖塊/屬性","desc":"集水坑符號及註解工具：依長寬深建立 PIT-長x寬x深 圖塊（外框、填充、標誌線、尺寸文字）並插入，可自動填入現有圖塊尺寸。","usage":"執行 pit-sym → 對話框輸入長/寬/深/文字高或選現有 PIT 圖塊 → 勾選填充/印出文字 → 指定插入點","level":8,"lt":"✅","ver":"2026-01-07 (檔案日期)","author":"MyCAD","video":"","fas":"fas/pit-sym.fas"},{"no":1302,"file":"pjl.lsp","cmd":"pjl","cat":"修改","desc":"將同圖層的線、弧、聚合線依圖層分組後自動接合（join）。","usage":"執行 pjl → 選取線/弧/聚合線 → 依圖層接合","level":3,"lt":"✅","ver":"20220225","author":"chengshunyi","video":"","fas":"fas/pjl.fas"},{"no":1303,"file":"pjname-bigfont.lsp","cmd":"（無，副程式庫）","cat":"系統/授權","desc":"依開啟圖檔所在網路路徑自動設定 projectname 系統變數（只取專案編號），已設定則略過。","usage":"圖檔開啟時由啟動檔載入 → 自動依 dwgprefix 設定 projectname","level":4,"lt":"✅","ver":"2001.09.05 / 20220727","author":"chengshunyi","video":"","fas":""},{"no":1304,"file":"pjname-border-p.lsp","cmd":"pjname-border-p","cat":"出圖/列印","desc":"依專案編號自動外部參考（XREF）圖框 -bdr-per.dwg（相對路徑）並建立圖層，用於發包圖框。","usage":"執行 pjname-border-p → 自動判斷專案資料夾 → 附加圖框外參於對應圖層","level":5,"lt":"✅","ver":"20221229 / 20250511","author":"chengshunyi","video":"","fas":"fas/pjname-border-p.fas"},{"no":1305,"file":"pjname-border.lsp","cmd":"pjname-border","cat":"出圖/列印","desc":"依專案編號自動外部參考圖框 -bdr.dwg（相對路徑）並建立圖層，用於發包圖。","usage":"執行 pjname-border → 自動判斷專案資料夾 → 附加圖框外參","level":5,"lt":"✅","ver":"20221229 / 20250511","author":"chengshunyi","video":"","fas":"fas/pjname-border.fas"},{"no":1306,"file":"pjname.lsp","cmd":"pjname","cat":"系統/授權","desc":"依開啟圖檔位置自動設定 projectname，只取專案編號，已設定則提示不需設定。","usage":"執行 pjname → 自動依檔案路徑設定 projectname","level":3,"lt":"✅","ver":"2001.09.05,2010.04.24 / 20220716更新","author":"chengshunyi","video":"","fas":""},{"no":1307,"file":"pjname2PFSP.lsp","cmd":"pjname2PFSP","cat":"系統/授權","desc":"依 projectname 自動在登錄檔 Project Files Search Path 新增專案名稱與路徑，讓外參/圖塊可搜尋專案資料夾。","usage":"執行 pjname2PFSP → 讀取 projectname → 寫入使用者 Profile 的 RefSearchPath","level":8,"lt":"✅","ver":"20230630","author":"chengshunyi","video":"","fas":""},{"no":1308,"file":"pk-obj-draw-rect.lsp","cmd":"pk-obj-draw-rect-ip、pk-obj-draw-rect-sp","cat":"繪圖","desc":"依指定長寬在選取物件位置畫矩形（Tree-Hole 樹穴）；-ip 以圖塊插入點、-sp 以形心為中心。","usage":"執行 pk-obj-draw-rect-ip → 輸入長/寬 → 選取物件 → 於其位置畫矩形（Enter 結束）","level":5,"lt":"✅","ver":"20240213","author":"chengshunyi（含 Lee Mac 2010）","video":"","fas":"fas/pk-obj-draw-rect.fas"},{"no":1309,"file":"pl-add-vertex-eq.lsp","cmd":"pl-add-vertex-eq、add-vert-one","cat":"修改","desc":"對聚合線依最大間距等距加入節點，add-vert-one 則在點選位置單點加入頂點。","usage":"執行 pl-add-vertex-eq → 選取聚合線 → 輸入最大節點間距 → 自動加節點","level":6,"lt":"✅","ver":"20240616","author":"chengshunyi","video":"","fas":"fas/pl-add-vertex-eq.fas"},{"no":1310,"file":"pl-area-l.lsp","cmd":"pl-area-l、lf、lfm、lfmu、af、afm","cat":"面積/數量統計","desc":"聚合線長度與面積標註 DCL 版：設定單位、字高、比例，標註長度/面積（含 M/M2 單位），lf/af 等為快捷指令。","usage":"執行 pl-area-l → 對話框設定單位/比例/字高 → 選取聚合線 → 標註長度或面積","level":9,"lt":"✅","ver":"20230120 / 20230122","author":"chengshunyi","video":"","fas":"fas/pl-area-l.fas"},{"no":1311,"file":"PL-AreaToML.lsp","cmd":"PL-AreaToML","cat":"面積/數量統計","desc":"聚合線範圍內的多重引線以精確幾何判斷，依區劃計算面積並標註，可設單位、前綴與編號補零。","usage":"執行 PL-AreaToML → 對話框設單位/前綴/編號 → 選取聚合線 → 範圍內多重引線標註面積","level":8,"lt":"✅","ver":"2026-03-26 (檔案日期)","author":"MyCAD","video":"","fas":"fas/PL-AreaToML.fas"},{"no":1312,"file":"Pl-Arrow.LSP","cmd":"Pl-Arrow","cat":"修改","desc":"以聚合線兩端使用不同寬度做出箭頭，可選起點、兩端或終點，依比例與單位換算大小。","usage":"執行 Pl-Arrow → 選取聚合線 → 輸入 Start/Both/End → 端部變為箭頭","level":5,"lt":"✅","ver":"20250614（原 beekeecz 21-08-01）","author":"beekeecz，chengshunyi 修改（Lee Mac 程式碼）","video":"","fas":"fas/Pl-Arrow.fas"},{"no":1313,"file":"pl-blk-count-na-la.lsp","cmd":"vox-sel-obj-in-poly、vox-sel-obj-in-poly2、pl-blk-count-na-la","cat":"面積/數量統計","desc":"選取聚合線範圍內的圖塊，依圖塊名稱及圖層統計數量並輸出清單（喬木數量計算）。","usage":"執行 pl-blk-count-na-la → 選取封閉聚合線 → 範圍內圖塊依名稱/圖層統計 → 輸出明細","level":8,"lt":"✅","ver":"20240414","author":"chengshunyi","video":"","fas":"fas/pl-blk-count-na-la.fas"},{"no":1314,"file":"pl-bnd-ang.lsp","cmd":"（無，副程式庫）","cat":"繪圖","desc":"依角度算出鋸齒聚合線的邊界點，並以 RECTANGLE 繪出矩形範圍（含 Count Items 工具函式）。","usage":"載入後由其他程式呼叫（c:pbnd）→ 選取聚合線 → 畫出邊界矩形","level":5,"lt":"✅","ver":"2024-06-08 (檔案日期)","author":"Lee Mac（Count Items）/ chengshunyi","video":"","fas":"fas/pl-bnd-ang.fas"},{"no":1315,"file":"pL-bnd.lsp","cmd":"pL-bnd","cat":"繪圖","desc":"依角度計算鋸齒聚合線的邊界點，以 RECTANGLE 繪出其外框矩形。","usage":"執行 pL-bnd → 選取聚合線 → 畫出邊界矩形","level":5,"lt":"✅","ver":"20241031","author":"chengshunyi（Count Items 為 Lee Mac）","video":"","fas":"fas/pL-bnd.fas"},{"no":1316,"file":"pl-c-area-q-N.LSP","cmd":"pl-c-area-2list、pl-c-area-2pluslist、pl-c-area-m-q-N、pl-c-area-q-n","cat":"面積/數量統計","desc":"客製化快速面積：選取聚合線標註每個 pline 的面積列式與加總，可選字高/比例，防火區劃用，含 N 版編號。","usage":"執行 pl-c-area-q-n → 於清單選字高 → 選取聚合線 → 放置面積列式與加總","level":9,"lt":"✅","ver":"20250705 / 2025-07-26 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/pl-c-area-q-N.fas"},{"no":1317,"file":"pl-c-area-q.lsp","cmd":"pl-c-area-m-q-ly、pl-c-area-m-q-ln、pl-c-area-m-q、pl-c-area-q","cat":"面積/數量統計","desc":"客製化快速面積：選取聚合線標註面積、周長、台灣坪與加總列式，支援 mm/cm/m 與多選，字高以選單選擇。","usage":"執行 pl-c-area-q → 清單選字高 → 選取聚合線 → 放置面積/周長/坪數與加總","level":9,"lt":"✅","ver":"20250624 / 2025-07-11 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/pl-c-area-q.fas"},{"no":1318,"file":"pl-c-area-ui.lsp","cmd":"pl-c-area-ui","cat":"面積/數量統計","desc":"快速面積選項對話框：勾選輸出面積/周長/坪數/才數、功能變數連動、加總、僅閉合 Pline 與繪圖單位。","usage":"執行 pl-c-area-ui → 對話框勾選輸出項目與單位 → 確定 → 選取聚合線標註","level":8,"lt":"✅","ver":"2026-04-23 (檔案日期)","author":"MyCAD","video":"https://youtu.be/FljDjhDWbIA","fas":"fas/pl-c-area-ui.fas"},{"no":1319,"file":"pl-c-area.lsp","cmd":"pl-c-area-m、pl-c-area、pl-c-area-quick","cat":"面積/數量統計","desc":"聚合線面積標註：以功能變數連動面積，可多選、加總列式、周長及台灣坪，字型 AREA-TXT。","usage":"執行 pl-c-area → 選取聚合線 → 放置面積文字（可連動 Field 與列式加總）","level":9,"lt":"✅","ver":"20240928 / 2025-01-20 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/pl-c-area.fas"},{"no":1320,"file":"pl-c-put-blk.LSP","cmd":"pl-c-put-blk","cat":"圖塊/屬性","desc":"取選取聚合線形心，在中心插入方格平均高程圖塊 cal-e-v。","usage":"執行 pl-c-put-blk → 選取聚合線 → 自動於中心插入圖塊","level":4,"lt":"✅","ver":"20240318","author":"chengshunyi（含 Lee Mac 2011）","video":"","fas":"fas/pl-c-put-blk.fas"},{"no":1321,"file":"pl-ccl.lsp","cmd":"pl-ccl","cat":"繪圖","desc":"於封閉聚合線形心畫十字中心線並延伸指定長度。","usage":"執行 pl-ccl → 點選聚合線邊 → 輸入延伸長度 → 畫出十字中心線","level":5,"lt":"✅","ver":"20240523（原版 2021-09-30）","author":"hak_vz，chengshunyi 修改","video":"","fas":"fas/pl-ccl.fas"},{"no":1322,"file":"pl-cen-i-blk-b.lsp","cmd":"pl-cen-i-blk-b","cat":"面積/數量統計","desc":"取全圖聚合線形心插入圖塊 my_gm 並標示文字，將面積等資料匯出至 Excel 表格（含儲存格格式）。","usage":"執行 pl-cen-i-blk-b → 自動選全圖聚合線 → 插入圖塊與文字 → 開啟 Excel 輸出明細","level":8,"lt":"❌","ver":"2008.06.24 / 2021.06.05","author":"chengshunyi","video":"","fas":"fas/pl-cen-i-blk-b.fas"},{"no":1323,"file":"pl-cen-i-blk.lsp","cmd":"pl-cen-i-blk","cat":"圖塊/屬性","desc":"取全圖聚合線形心插入 MY_GM 圖塊並依樓層類型（FLOOR、CELLING、GFLOOR）標示面積文字。","usage":"執行 pl-cen-i-blk → 自動選全圖聚合線 → 於各形心插入圖塊與文字","level":7,"lt":"✅","ver":"20220716更新","author":"chengshunyi","video":"","fas":"fas/pl-cen-i-blk.fas"},{"no":1324,"file":"pl-copy-at-same.LSP","cmd":"pl-copy-at-same","cat":"修改","desc":"在原位置複製選取的聚合線（重疊複製）。","usage":"執行 pl-copy-at-same → 選取聚合線 → 原位複製","level":3,"lt":"✅","ver":"20240402","author":"chengshunyi（Tharwat 21. may. 2012）","video":"","fas":"fas/pl-copy-at-same.fas"},{"no":1325,"file":"pl-del-arc.LSP","cmd":"0bulge、db、decurve","cat":"修改","desc":"將聚合線上的弧段改為直線（0bulge）、刪除弧段（db）或以零半徑圓角方式去曲線（decurve）。","usage":"執行 0bulge（或 db/decurve）→ 選取聚合線 → 弧段轉直線或刪除","level":6,"lt":"✅","ver":"20240402","author":"chengshunyi（Decurve 為 Lee Mac）","video":"","fas":"fas/pl-del-arc.fas"},{"no":1326,"file":"pl-del-ver-arc-safe.lsp","cmd":"pl-del-ver-arc-safe","cat":"修改","desc":"選取一條 LWPOLYLINE，窗選範圍內的頂點予以刪除（支援弧線 bulge），含 Undo 保護。","usage":"執行 pl-del-ver-arc-safe → 選取聚合線 → 指定窗選兩角點 → 刪除範圍內頂點","level":5,"lt":"✅","ver":"2025-11-18 (檔案日期)","author":"—","video":"","fas":"fas/pl-del-ver-arc-safe.fas"},{"no":1327,"file":"pl-del-ver-w.lsp","cmd":"pl-del-ver-w","cat":"修改","desc":"選取一條 LWPOLYLINE，窗選範圍內的頂點予以刪除，已更新支援弧線。","usage":"執行 pl-del-ver-w → 選取聚合線 → 指定窗選兩角點 → 刪除範圍內頂點","level":5,"lt":"✅","ver":"20231001 / 20251117","author":"chengshunyi","video":"","fas":"fas/pl-del-ver-w.fas"},{"no":1328,"file":"PL-DIM.lsp","cmd":"PL-DIM","cat":"標註","desc":"標註聚合線各段長度，終點可產生 (a+b+c=Sum) 計算式；可依 PLINE 圖層、只套用尺寸型式，並暫時縮放確保標註完整。","usage":"執行 PL-DIM → 對話框選尺寸型式/單位/精度/計算式與比例 → 選取聚合線 → 標註尺寸與計算式","level":9,"lt":"✅","ver":"2026-11-11 (檔案日期)","author":"MyCAD","video":"https://youtu.be/Vn5eQ8JbmS4","fas":"fas/PL-DIM.fas"},{"no":1329,"file":"PL-DIV-AREA.lsp","cmd":"PL-DIV-AREA","cat":"面積/數量統計","desc":"將封閉聚合線依面積等分（或切出指定面積），以虛擬分割線搭配 BOUNDARY 求解並畫出分割線。","usage":"執行 PL-DIV-AREA → 選封閉聚合線 → 選 Divide 或 Cut → 輸入等分數或面積 → 指定方向產生分割線","level":8,"lt":"✅","ver":"ver 2.0（舊版）/ 2024-04-06 (檔案日期)","author":"Yorgos Angelopoulos","video":"","fas":"fas/PL-DIV-AREA.fas"},{"no":1330,"file":"pl-div-offset-2side-eq.lsp","cmd":"ot-eq、offsettable-eq","cat":"查詢","desc":"選取線形（聚合線）並輸入左右偏移距離與樁距，等分產生左線、中心線、右線的樁號與座標表格。","usage":"執行 ot-eq → 選取線形 → 輸入左右偏移距與間距 → 指定表格位置 → 產生座標表","level":8,"lt":"✅","ver":"20241002（原版 ymg 2015-11）","author":"ymg，chengshunyi 修改（addtable 為 Lee Mac）","video":"","fas":"fas/pl-div-offset-2side-eq.fas"},{"no":1331,"file":"pl-div-offset-2side.lsp","cmd":"ot、offsettable","cat":"查詢","desc":"選取線形（聚合線），輸入左右偏移距離與樁距，產生左線、中心線、右線的樁號與座標表格。","usage":"執行 offsettable → 選取線形 → 輸入左右偏移距與間距 → 指定表格位置 → 產生座標表","level":8,"lt":"✅","ver":"20241002（原版 ymg 2015-11）","author":"ymg，chengshunyi 修改（addtable 為 Lee Mac）","video":"","fas":"fas/pl-div-offset-2side.fas"},{"no":1332,"file":"pl-div-put-attblk.lsp","cmd":"pl-div-put-attblk","cat":"圖塊/屬性","desc":"沿聚合線等分畫分割線並放置高程屬性圖塊（車道分割線），屬性寫入累計距離與相對高程。","usage":"執行 pl-div-put-attblk → 輸入圖塊名/等分數/起始相對高程 → 選取聚合線 → 等分畫線並放屬性圖塊","level":8,"lt":"✅","ver":"20240407 / 20240408","author":"chengshunyi（含 Tharwat 2015）","video":"","fas":"fas/pl-div-put-attblk.fas"},{"no":1333,"file":"pl-div-ramp-p.lsp","cmd":"pl-div-ramp-p","cat":"圖塊/屬性","desc":"沿聚合線等分畫分割線並放置高程屬性圖塊（車道坡道），對話框設定等分數、高度與起始相對高程，缺圖塊時自動插入。","usage":"執行 pl-div-ramp-p → 對話框設定等分數/高度/起始高程 → 選取聚合線 → 等分畫線並放屬性圖塊","level":8,"lt":"✅","ver":"20240407 / 20240408","author":"chengshunyi（含 Tharwat 2015）","video":"https://youtu.be/kfoc0_uVmg8","fas":"fas/pl-div-ramp-p.fas"},{"no":1334,"file":"pl-div-ui-4X.lsp","cmd":"pl-div-ui、boline","cat":"繪圖","desc":"封閉聚合線自動分割：對話框選水平線、垂直線、選線角度或三角形分割方式，於聚合線內繪出分割線，並同步顯示幻燈片。","usage":"執行 pl-div-ui → 對話框選分割方式 → 選取封閉聚合線 → 依輸入數量產生分割線","level":9,"lt":"✅","ver":"2026-05-03 (檔案日期)","author":"MyCAD","video":"https://youtu.be/r7dIO-xJ5bg","fas":"fas/pl-div-ui-4X.fas"},{"no":1335,"file":"pl-div-ui.LSP","cmd":"pl-div-ui、boline","cat":"繪圖","desc":"封閉聚合線自動分割，對話框記住上次分割方式（水平/垂直/選邊角度/三角形），再呼叫核心運算畫分割線。","usage":"執行 pl-div-ui → 對話框選分割方式 → 選取封閉聚合線 → 產生分割線","level":9,"lt":"✅","ver":"2026-05-03 (檔案日期)","author":"MyCAD","video":"https://youtu.be/r7dIO-xJ5bg","fas":"fas/pl-div-ui.fas"},{"no":1336,"file":"pl-div.lsp","cmd":"pl-div-h、pl-div-v、pl-div-t、boline","cat":"繪圖","desc":"選封閉聚合線以水平線(h)、垂直線(v)或三角形(t)方式分割，依面積/等分計算並繪出分割線。","usage":"執行 pl-div-h（或 v/t）→ 選取聚合線 → 輸入分割數或條件 → 產生分割線","level":9,"lt":"✅","ver":"20241121 / 2025-12-26 (檔案日期)","author":"chengshunyi","video":"https://youtu.be/qKS3OoMYhV0","fas":"fas/pl-div.fas"},{"no":1337,"file":"pl-dx-draw-xline.lsp","cmd":"pl-dx-draw-xline、pl-dy-draw-xline","cat":"繪圖","desc":"選外牆聚合線，在各折點（去除 X 或 Y 重複）畫垂直或水平 XLINE 輔助線。","usage":"執行 pl-dx-draw-xline → 選取聚合線 → 自動在折點畫 xline","level":6,"lt":"✅","ver":"20240512","author":"chengshunyi","video":"","fas":"fas/pl-dx-draw-xline.fas"},{"no":1338,"file":"pl-f-block.lsp","cmd":"pl-f-block","cat":"修改","desc":"選取 LWPOLYLINE 後，選取與其接觸的圖塊（CP/WP/F）。","usage":"執行 pl-f-block → 選取聚合線 → 選出相交/接觸的圖塊","level":4,"lt":"✅","ver":"20220522 / 20220716更新","author":"chengshunyi（Tharwat 15.09.2015）","video":"","fas":"fas/pl-f-block.fas"},{"no":1339,"file":"PL-FILTER-PL.lsp","cmd":"PL-FILTER-PL","cat":"修改","desc":"以選取的聚合線範圍（WP）選出範圍內同圖層的聚合線。","usage":"執行 PL-FILTER-PL → 選取範圍聚合線 → 選出範圍內同圖層聚合線","level":4,"lt":"✅","ver":"20240803","author":"chengshunyi（Tharwat 2014）","video":"","fas":"fas/PL-FILTER-PL.fas"},{"no":1340,"file":"pl-find-text.LSP","cmd":"pl-find-text","cat":"轉檔/匯出入","desc":"地籍圖撈地號：選封閉聚合線，抓範圍內文字、清除 MText 格式、去重排序後匯出 CSV。","usage":"執行 pl-find-text → 選取封閉聚合線 → 範圍內文字去重 → 匯出 CSV 到圖檔資料夾","level":6,"lt":"✅","ver":"2026-01-30 (檔案日期)","author":"MyCAD","video":"","fas":"fas/pl-find-text.fas"},{"no":1341,"file":"pl-hat.LSP","cmd":"pl-hat","cat":"繪圖","desc":"選取指定圖層的聚合線，以 ANSI37 圖案填充，並改為 BYLAYER。","usage":"執行 pl-hat（HAT）→ 選取要填充的聚合線圖層 → 自動 -hatch","level":3,"lt":"✅","ver":"20240302","author":"chengshunyi","video":"","fas":"fas/pl-hat.fas"},{"no":1342,"file":"pl-hatch-bylayer.LSP","cmd":"pl-hatch-bylayer","cat":"繪圖","desc":"依聚合線圖層（水池、通路、廠房、綠地、垂直/水平動線等）自動套用對應圖層與填充圖案。","usage":"執行 pl-hatch-bylayer → 自動搜尋全圖封閉聚合線 → 依圖層建立 hatch","level":6,"lt":"✅","ver":"20240929","author":"chengshunyi","video":"","fas":"fas/pl-hatch-bylayer.fas"},{"no":1343,"file":"PL-HH.lsp","cmd":"PL-HH-ANSI37、PL-HH-ARCONC、PL-HH","cat":"繪圖","desc":"選取封閉聚合線依常用圖案（ANSI37、AR-CONC）建立填充，指定圖層、關聯與角度，可選刪除原聚合線。","usage":"執行 PL-HH-ANSI37（或 ARCONC）→ 選取封閉聚合線 → 自動填充","level":5,"lt":"✅","ver":"20250607","author":"chengshunyi（Lee Mac 2010）","video":"","fas":"fas/PL-HH.fas"},{"no":1344,"file":"pl-in-dr-box.lsp","cmd":"pl-in-dr-box","cat":"繪圖","desc":"依 Bounding Box 在聚合線內部依間距與數量畫出內縮矩形（框內畫框）。","usage":"執行 pl-in-dr-box → 輸入間距 → 輸入數量 → 選取聚合線 → 畫出內縮矩形","level":5,"lt":"✅","ver":"20240426","author":"chengshunyi（Bounding Box 為 Lee Mac）","video":"","fas":"fas/pl-in-dr-box.fas"},{"no":1345,"file":"pl-info2ml.lsp","cmd":"pl-info2ml","cat":"標註","desc":"連續選取聚合線，以多重引線標註面積/周長，可選連動（欄位）或靜態文字、單位與比例。","usage":"執行 pl-info2ml → 對話框選模式(D/S)/單位/比例 → 連續點選聚合線並指定引線位置","level":7,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"MyCAD","video":"","fas":"fas/pl-info2ml.fas"},{"no":1346,"file":"pl-info2ml12P.LSP","cmd":"pl-info2ml12P","cat":"標註","desc":"對多條聚合線，取四角、中心與每邊 3 點共 12 點分析找最遠點，畫引線標註（以基準點 P0 為參考）。","usage":"執行 pl-info2ml12P → 點選基準點 P0 → 選取多條聚合線 → 自動畫引線到最遠點","level":7,"lt":"✅","ver":"2025-11-14 (檔案日期)","author":"—","video":"","fas":"fas/pl-info2ml12P.fas"},{"no":1347,"file":"pl-info2ml16P.LSP","cmd":"pl-info2ml16P","cat":"標註","desc":"對多條聚合線，取四角、中心與每邊 5 點共 16 點分析找最遠點，畫引線標註。","usage":"執行 pl-info2ml16P → 點選基準點 P0 → 選取多條聚合線 → 自動畫引線","level":7,"lt":"✅","ver":"2025-11-14 (檔案日期)","author":"—","video":"","fas":"fas/pl-info2ml16P.fas"},{"no":1348,"file":"pl-info2ml4P.lsp","cmd":"pl-info2ml4P","cat":"標註","desc":"對多條聚合線取四邊中點找最遠中點，延伸畫多重引線，內容以欄位連動面積與周長。","usage":"執行 pl-info2ml4P → 點選基準點 P0 → 選取多條聚合線 → 自動建立多重引線標註面積/周長","level":8,"lt":"✅","ver":"2025-11-14 (檔案日期)","author":"—","video":"","fas":"fas/pl-info2ml4P.fas"},{"no":1349,"file":"pl-intav1.lsp","cmd":"pl-intav1","cat":"修改","desc":"在聚合線與所選曲線（線、弧、圓、樣條等）的交點處加入頂點。","usage":"執行 pl-intav1 → 選取來源聚合線 → 選取相交曲線 → 在交點加入頂點","level":6,"lt":"✅","ver":"2024-06-17 (檔案日期)","author":"—（plintav1 網路程式）","video":"","fas":"fas/pl-intav1.fas"},{"no":1350,"file":"PL-lay-typ-c.lsp","cmd":"pl-lay-typ-c-lh、pl-lay-typ-c-llh、pl-lay-typ-c-l、PL-lay-typ-c","cat":"面積/數量統計","desc":"以圖層為分類依據統計選取聚合線的長度或長x高面積，輸出總長x高=面積及各別列式，字高依 textsize。","usage":"執行 pl-lay-typ-c-l（或 lh/llh）→ 選取聚合線 → 輸入高度 → 指定文字位置 → 產生分類統計文字","level":8,"lt":"✅","ver":"20240810 / 2026-10-17 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/PL-lay-typ-c.fas"},{"no":1351,"file":"Pl-OFFset-par.lsp","cmd":"Pl-OFFset-par-500","cat":"修改","desc":"在聚合線上點選兩點，將該區段局部偏移 500（自動點位），以 COPY 與 BREAK 完成。","usage":"執行 Pl-OFFset-par-500 → 點選第一點 → 點選第二點 → 局部偏移複製","level":5,"lt":"✅","ver":"20240328","author":"chengshunyi","video":"","fas":"fas/Pl-OFFset-par.fas"},{"no":1352,"file":"pl-prj-pl-dist.LSP","cmd":"pl-prj-pl-dist","cat":"標註","desc":"選兩條聚合線，依步距在第一條上取點投射到第二條，畫投射線並標註距離文字。","usage":"執行 pl-prj-pl-dist → 選取第一條聚合線 → 選取第二條聚合線 → 輸入步距 → 自動畫線並標距","level":6,"lt":"✅","ver":"20241117","author":"chengshunyi（含 Lee Mac ssget 包裝）","video":"","fas":"fas/pl-prj-pl-dist.fas"},{"no":1353,"file":"pl-put-cars.lsp","cmd":"pl-car、po-car、pol-car、pl-car-s、pl-car-m、pl-car-l、pl-car-mt1～mt10、pl-car-bc1～bc4、pl-car-mth、pl-car-hd1、pl-car-hd2、pl-car-1gs/2gs/3gs、pl-car-1gm/2gm/3gm、pl-car-1gl/2gl/3gl、pl-put-cars、po-put-cars","cat":"圖塊/屬性","desc":"沿聚合線依車位寬度等距擺放車位圖塊（大/小/寬減/機車/腳踏車/無障礙/裝卸/機械車位 1～3 層），共 30 多個快捷指令。","usage":"執行 pl-put-cars → 對話框選車位類型與尺寸 → 選取聚合線或點 → 沿路徑依寬度插入車位圖塊","level":9,"lt":"✅","ver":"20241103 / 20250329","author":"chengshunyi","video":"https://youtu.be/ndppuOcylTs","fas":"fas/pl-put-cars.fas"},{"no":1354,"file":"pl-recunion.LSP","cmd":"recunion、revunion、Region2Polyline、revmi","cat":"繪圖","desc":"將多條聚合線轉面域並聯集（UNION）後再轉回聚合線，另有面域轉聚合線與以雲形標示。","usage":"執行 recunion → 選取聚合線 → 轉 region 並 union → 輸出聯集聚合線","level":7,"lt":"❌","ver":"20240328（Gilles Chanteau 01/01/07）","author":"Gilles Chanteau (gile)，chengshunyi 修改","video":"","fas":"fas/pl-recunion.fas"},{"no":1355,"file":"pl-ro-obj.lsp","cmd":"pl-ro-obj","cat":"對齊/排列","desc":"選取聚合線或線段作為參考，將物件（含影像）旋轉到水平。","usage":"執行 pl-ro-obj → 選取物件 → 選取參考線 → 物件旋轉對齊","level":4,"lt":"✅","ver":"20250704","author":"chengshunyi","video":"","fas":"fas/pl-ro-obj.fas"},{"no":1356,"file":"pl-roomm-cp-SOP.lsp","cmd":"pl-roomm-cp-SOP","cat":"繪圖","desc":"選取線/弧/圓，自動依中心點排序交點並建立封閉聚合線，含 Undo 群組（SOP 版）。","usage":"執行 pl-roomm-cp-SOP → 選取線/弧/圓 → 指定中心點 → 自動生成封閉聚合線","level":7,"lt":"✅","ver":"2025-11-18 (檔案日期)","author":"—","video":"","fas":"fas/pl-roomm-cp-SOP.fas"},{"no":1357,"file":"pl-roomm-cp.lsp","cmd":"pl-roomm-cp","cat":"繪圖","desc":"室內空間自動做封閉聚合線：選取線/弧/圓，依與中心點角度排序交點、去除重複點後建立封閉聚合線。","usage":"執行 pl-roomm-cp → 選取線/弧/圓 → 指定中心點 → 自動建立封閉聚合線","level":7,"lt":"✅","ver":"20240402 / 20251117","author":"chengshunyi","video":"","fas":"fas/pl-roomm-cp.fas"},{"no":1358,"file":"Pl-s-Seg-A2L.lsp","cmd":"Pl-s-Seg-A2L","cat":"修改","desc":"點選聚合線的某一弧線段，將該段由弧改為直線。","usage":"執行 Pl-s-Seg-A2L → 點選聚合線弧段 → 該段改為直線","level":5,"lt":"✅","ver":"20240407","author":"chengshunyi（AT:GetSel 為 Alan J. Thompson）","video":"","fas":"fas/Pl-s-Seg-A2L.fas"},{"no":1359,"file":"Pl-s-Seg-W.lsp","cmd":"Pl-s-Seg-W、Pl-s-Seg-W0","cat":"修改","desc":"點選聚合線某一段，將該段線寬設為依比例的指定寬度（0.05cm×比例），W0 為歸零。","usage":"執行 Pl-s-Seg-W → 點選聚合線線段 → 該段線寬被設定","level":5,"lt":"✅","ver":"20240327","author":"chengshunyi（含 Alan J. Thompson 2010）","video":"","fas":"fas/Pl-s-Seg-W.fas"},{"no":1360,"file":"pl-seg-to-i-d.LSP","cmd":"pl-seg-to-i-d","cat":"修改","desc":"調整聚合線的某段長度至整數（取 i 值），本檔為無條件捨去（d），折點數可達 15。","usage":"執行 pl-seg-to-i-d → 選取聚合線 → 各段長度捨去至指定位數","level":8,"lt":"✅","ver":"20240417 / 20240418","author":"chengshunyi","video":"","fas":"fas/pl-seg-to-i-d.fas"},{"no":1361,"file":"pl-seg-to-i-r.LSP","cmd":"pl-seg-to-i-r","cat":"修改","desc":"調整聚合線各段長度至整數，本檔為四捨五入（r），折點數可達 15。","usage":"執行 pl-seg-to-i-r → 選取聚合線 → 各段長度四捨五入","level":8,"lt":"✅","ver":"20240417 / 20240418","author":"chengshunyi","video":"","fas":"fas/pl-seg-to-i-r.fas"},{"no":1362,"file":"pl-seg-to-i-u.LSP","cmd":"pl-seg-to-i-u","cat":"修改","desc":"調整聚合線各段長度至整數，本檔為無條件進位（u），折點數可達 15。","usage":"執行 pl-seg-to-i-u → 選取聚合線 → 各段長度進位","level":8,"lt":"✅","ver":"20240417 / 20240418","author":"chengshunyi","video":"","fas":"fas/pl-seg-to-i-u.fas"},{"no":1363,"file":"pl-seg-to-i-x.LSP","cmd":"pl-seg-to-i-RR、pl-seg-to-i-UU、pl-seg-to-i-DD、pl-seg-to-i","cat":"修改","desc":"點選聚合線某一段，將該段長度修改為整數（四捨五入 RR、進位 UU、捨去 DD），重畫聚合線。","usage":"執行 pl-seg-to-i-RR → 點選聚合線線段 → 該段長度被修整為整數","level":7,"lt":"✅","ver":"20240511","author":"chengshunyi","video":"","fas":"fas/pl-seg-to-i-x.fas"},{"no":1364,"file":"pl-sel-blk.lsp","cmd":"pl-sel-blk","cat":"圖塊/屬性","desc":"選取邊界聚合線（可多條），以 CP 選出範圍內圖塊並讀取 elev 屬性值（逐聚合線迴圈）。","usage":"執行 pl-sel-blk → 選取邊界聚合線 → 自動選出範圍內圖塊並處理其 elev 屬性","level":6,"lt":"✅","ver":"20240317","author":"chengshunyi","video":"","fas":"fas/pl-sel-blk.fas"},{"no":1365,"file":"pl-side-draw-rectangle.LSP","cmd":"pl-side-draw-rectangle","cat":"繪圖","desc":"於多邊形（聚合線）每一邊外側，依輸入高度畫矩形。","usage":"執行 pl-side-draw-rectangle → 輸入高度 → 選取聚合線 → 每邊外畫矩形","level":4,"lt":"✅","ver":"20240524","author":"chengshunyi","video":"","fas":"fas/pl-side-draw-rectangle.fas"},{"no":1366,"file":"pl-small-y.LSP","cmd":"pl-small-y","cat":"查詢","desc":"在所選聚合線 Y 值最小的頂點建立點物件，並顯示其座標。","usage":"執行 pl-small-y → 選取聚合線 → 於最低點建立 POINT 並顯示座標","level":4,"lt":"✅","ver":"20231207 / 2026-10-17 (檔案日期)","author":"Tharwat (15.06.2011)","video":"","fas":"fas/pl-small-y.fas"},{"no":1367,"file":"pl-sort-cars-dy-ui.lsp","cmd":"pl-sort-cars-dy-uix、pl-sort-cars-dy-ui","cat":"圖塊/屬性","desc":"沿選取聚合線路徑對車位圖塊依序編號，對話框設定起始碼、前後置碼與補零，設定存 INI，支援汽車/機車/機械車位。","usage":"執行 pl-sort-cars-dy-ui → 對話框設起始碼/前後置碼/圖塊類型 → 選取排序聚合線 → 圖塊屬性自動編號","level":9,"lt":"✅","ver":"2025-11-03 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/pl-sort-cars-dy-ui.fas"},{"no":1368,"file":"pl-sort-cars-dy.lsp","cmd":"pl-sort-cars-dy-ez、pl-sort-cars-dy","cat":"圖塊/屬性","desc":"沿選取聚合線路徑將車位圖塊依序編號（CARNUM、CARNUM2 屬性），配合 EZCAD 圖塊名稱，含無障礙車位。","usage":"執行 pl-sort-cars-dy → 選取排序聚合線 → 選取車位圖塊 → 依序寫入編號","level":7,"lt":"✅","ver":"20240519 / 2025-11-02 (檔案日期)","author":"chengshunyi","video":"https://youtu.be/lvbpks9ZarM","fas":"fas/pl-sort-cars-dy.fas"},{"no":1369,"file":"pl-sort-cars.lsp","cmd":"pl-sort-cars-ez、po-sort-cars、pos-sort-cars、pl-sort-cars","cat":"圖塊/屬性","desc":"沿聚合線或點選路徑對車位圖塊依序編號，讀取 cal-sort-list.txt 設定，可寫入 CARNUM、CARNUM2、CARNUM3 並含機械停車 1/2/3 層。","usage":"執行 pl-sort-cars → 選取聚合線（或 po 版點選路徑）→ 自動依序編號車位圖塊","level":8,"lt":"✅","ver":"20240519 / 20250427","author":"chengshunyi","video":"","fas":"fas/pl-sort-cars.fas"},{"no":1370,"file":"pl-to-area.LSP","cmd":"pl-to-area","cat":"面積/數量統計","desc":"連續點選點畫聚合線，封閉後自動在其內放面積文字（Field 連動），使面積隨聚合線變動更新。","usage":"執行 pl-to-area → 連續點選聚合線各點 → 封閉 → 於圖層 G-DC-AREA 產生連動面積文字","level":6,"lt":"✅","ver":"POLYLINE AREA LISP 2010-09-09 / 20240401","author":"Tyler Thompson，chengshunyi 修改","video":"","fas":"fas/pl-to-area.fas"},{"no":1371,"file":"pl-tt-bylayer.lsp","cmd":"pl-tt-bylayer","cat":"面積/數量統計","desc":"依圖層統計聚合線面積，對話框設定單位、字高與型式，結果以 MText 寫入圖面，含使用期限檢查。","usage":"執行 pl-tt-bylayer → 對話框設單位/字高/樣式 → 選取聚合線 → 依圖層統計面積並寫出 MText","level":9,"lt":"✅","ver":"202311","author":"chengshunyi","video":"","fas":"fas/pl-tt-bylayer.fas"},{"no":1372,"file":"pl-typesetting.lsp","cmd":"pl-sort-y、pl-sort-y3、pl-sort-y4、pl-sort-y5、pl-sort-yx、ro-obj-90、ro-obj-180、ro-obj-270、rotate-obj-center、copy-obj-center、copy-obj-center3、copy-obj-center4、copy-obj-center5、copy-obj-centerx、DBB、dbbm、dbbm3、DBBMx","cat":"對齊/排列","desc":"排版工具：依 Y 軸將聚合線及其內物件排序重排間距避免重疊，可旋轉 90/180/270 度、複製、並畫 Bounding Box 外框（排版專用圖層）。","usage":"執行 pl-sort-y → 選取聚合線與內含物件 → 自動依 Y 排序並重排 → 可接 copy-obj-center3 複製旋轉","level":9,"lt":"✅","ver":"20240426 / 2024-05-10 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/pl-typesetting.fas"},{"no":1373,"file":"pl-v-draw-xline.lsp","cmd":"pl-v-draw-xline、pl-v-draw-xline-h","cat":"繪圖","desc":"在聚合線各頂點畫垂直（或水平 -h）XLINE，並建立不出圖的等分線圖層。","usage":"執行 pl-v-draw-xline → 選取聚合線 → 各頂點產生 xline","level":5,"lt":"✅","ver":"20240510（原 RJP 2022-09-09）","author":"RJP，chengshunyi 修改","video":"","fas":"fas/pl-v-draw-xline.fas"},{"no":1374,"file":"pl-vert-2-txt.lsp","cmd":"3dpl-v、3DPLC、lwpl-v、flw23pel","cat":"轉檔/匯出入","desc":"將 3D 聚合線或 LWPOLYLINE 的頂點座標匯出為文字檔（預設 d:\\coordlist.txt），並可轉換 3D 聚合線。","usage":"執行 3dpl-v（或 lwpl-v）→ 選取聚合線 → 輸入檔名 → 寫出頂點座標 txt","level":8,"lt":"⚠️","ver":"20240616","author":"chengshunyi（POLYVERT Scott Bolton 原版）","video":"","fas":"fas/pl-vert-2-txt.fas"},{"no":1375,"file":"pl-vert-po.LSP","cmd":"pl-vert-po、pl-vert-po-txt","cat":"轉檔/匯出入","desc":"在聚合線每個頂點建立 POINT 物件，pl-vert-po-txt 另將座標寫入 d:\\coordlist.txt。","usage":"執行 pl-vert-po → 選取聚合線 → 各頂點產生點物件（-txt 另輸出文字檔）","level":6,"lt":"✅","ver":"20240616","author":"chengshunyi","video":"","fas":"fas/pl-vert-po.fas"},{"no":1376,"file":"pl-vtx-del-arc.LSP","cmd":"pl-vtx-del","cat":"修改","desc":"點選 LWPOLYLINE 的弧線或頂點並刪除，精準對應弧線起點 index，含 Undo。","usage":"執行 pl-vtx-del → 點選聚合線的弧線或頂點 → 刪除該節點","level":5,"lt":"✅","ver":"2025-11-18 (檔案日期)","author":"—","video":"","fas":"fas/pl-vtx-del-arc.fas"},{"no":1377,"file":"pl-vtx-del.LSP","cmd":"pl-vtx-del","cat":"修改","desc":"點選聚合線上的頂點或弧線並刪除該節點，已更新弧線處理。","usage":"執行 pl-vtx-del → 點選聚合線的頂點 → 刪除該節點","level":5,"lt":"✅","ver":"20230907 / 20251117","author":"chengshunyi","video":"","fas":"fas/pl-vtx-del.fas"},{"no":1378,"file":"pl-vtx.lsp","cmd":"pl-vtx","cat":"繪圖","desc":"在選取聚合線的每個頂點建立 POINT 物件。","usage":"執行 pl-vtx → 選取聚合線 → 各頂點產生點物件","level":1,"lt":"✅","ver":"2025-08-09 (檔案日期)","author":"—","video":"","fas":"fas/pl-vtx.fas"},{"no":1379,"file":"pl-wp-block.LSP","cmd":"pl-wp-block","cat":"修改","desc":"選取聚合線後，選出其範圍（WP）內的圖塊。","usage":"執行 pl-wp-block → 選取聚合線 → 選出範圍內圖塊","level":2,"lt":"✅","ver":"20220716更新","author":"chengshunyi","video":"","fas":"fas/pl-wp-block.fas"},{"no":1380,"file":"pl-zZeroRotation.LSP","cmd":"zZeroRotation","cat":"修改","desc":"選取聚合線後，以世界座標原點為基準點對該聚合線進行旋轉，用於依原點調整 pline 方向。","usage":"執行 zZeroRotation → 選取聚合線 → 輸入旋轉角度","level":2,"lt":"✅","ver":"2024-10-13 (檔案日期)","author":"—","video":"","fas":"fas/pl-zZeroRotation.fas"},{"no":1381,"file":"PL2ML.LSP","cmd":"pl2ml","cat":"修改","desc":"將選取的聚合線（LWPOLYLINE）轉換為多線（MLINE）。","usage":"執行 pl2ml → 選取聚合線 → 產生對應的多線","level":3,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/PL2ML.fas"},{"no":1382,"file":"Pl2Zero.LSP","cmd":"Pl2Zero","cat":"修改","desc":"將選取的 2D/3D 聚合線 Z 值（高程）歸零，把立體聚合線壓平到 Z=0。","usage":"執行 Pl2Zero → 選取聚合線 → 自動將高程歸零","level":3,"lt":"✅","ver":"20250317","author":"chengshunyi","video":"","fas":"fas/Pl2Zero.fas"},{"no":1383,"file":"pl_GetWidths.LSP","cmd":"pl_GetWidths","cat":"查詢","desc":"逐段讀取聚合線每個線段的起迄點與起訖線寬，找出有寬度的線段並複製／打斷出來，供採光開窗檢討（5m 深度）等後續判斷。","usage":"執行 pl_GetWidths → 選取聚合線 → 顯示各線段寬度並複製有寬度的段落","level":5,"lt":"✅","ver":"20240327","author":"chengshunyi（部分源自 Autodesk 範例）","video":"","fas":"fas/pl_GetWidths.fas"},{"no":1384,"file":"PLAreaTool.lsp","cmd":"PLAL、PLAreaTool","cat":"面積/數量統計","desc":"面積與周長自動化工具：文字轉區域名稱圖塊、封閉 PLINE 計算面積與周長並標示，可輸出明細／統計表並自動或手動編號。","usage":"執行 PLAreaTool → 於對話框設定單位、前置碼、小數位 → 選取區域名稱文字與封閉聚合線 → 標註並繪製明細／統計表","level":6,"lt":"✅","ver":"2026-01-04 (檔案日期)","author":"—","video":"","fas":"fas/PLAreaTool.fas"},{"no":1385,"file":"PLD.LSP","cmd":"PLD","cat":"查詢","desc":"以臨時箭頭顯示聚合線路徑方向，並可標示各段長度與頂點資訊。","usage":"執行 PLD → 選取聚合線 → 畫面顯示臨時方向箭頭","level":5,"lt":"✅","ver":"20220716","author":"Luis Esquival 原作，RonJonP 修改，網路程式","video":"","fas":"fas/PLD.fas"},{"no":1386,"file":"pline-area.lsp","cmd":"pline-area","cat":"面積/數量統計","desc":"透過對話框設定繪圖單位、字高與格式，選取聚合線後標註面積與周長，可分簡報或發包圖字型並計算損耗。","usage":"執行 pline-area → 於對話框選擇單位、字高、字型 → 選取聚合線 → 標註面積周長","level":6,"lt":"✅","ver":"2023-07-19 (檔案日期)","author":"—","video":"","fas":"fas/pline-area.fas"},{"no":1387,"file":"pline-int-point-list.LSP","cmd":"pline-int-point-list","cat":"查詢","desc":"取得多條選取聚合線之間的交點，並整理成 XY 座標串列。","usage":"執行 pline-int-point-list → 選取多條聚合線 → 輸出交點座標串列","level":4,"lt":"✅","ver":"20221203","author":"chengshunyi","video":"","fas":"fas/pline-int-point-list.fas"},{"no":1388,"file":"pline-lay-area.LSP","cmd":"pline-lay-area、pline-lay-area-to-listbox","cat":"面積/數量統計","desc":"以聚合線所在圖層為分類依據統計面積，不論繪圖單位均換算為 m2，分類合計後標註於圖面或以清單方塊顯示。","usage":"執行 pline-lay-area → 選取聚合線 → 設定字高與單位 → 顯示分類合計並指定文字位置","level":8,"lt":"✅","ver":"20250711","author":"chengshunyi","video":"","fas":"fas/pline-lay-area.fas"},{"no":1389,"file":"pline-p-2seg-draw-arc.lsp","cmd":"pline-p-2seg-draw-arc","cat":"繪圖","desc":"選取兩條相接的聚合線線段，找出共用端點與另外兩端點，依三點繪製圓弧。","usage":"執行 pline-p-2seg-draw-arc → 選線段 1 → 選線段 2 → 自動產生圓弧","level":4,"lt":"✅","ver":"2025-11-04 (檔案日期)","author":"—","video":"","fas":"fas/pline-p-2seg-draw-arc.fas"},{"no":1390,"file":"PLINE_DIM_GM.lsp","cmd":"PLINE_DIM_GM","cat":"標註","desc":"對封閉聚合線各線段自動標註尺寸（cm 轉 m 文字），並可讀取圖塊資訊配合樓地板、天花、牆面等分類。","usage":"執行 PLINE_DIM_GM → 選取聚合線 → 選取圖塊資訊 → 自動標註各段尺寸","level":5,"lt":"✅","ver":"2022.11.08","author":"chengshunyi","video":"","fas":"fas/PLINE_DIM_GM.fas"},{"no":1391,"file":"PlineAreaStat.lsp","cmd":"PlineAreaStat","cat":"面積/數量統計","desc":"自動計算聚合線面積並寫入 XData，於形心標註 MText；可依棟別、戶別統計，輸出至圖面或 CSV，並依類組自動換色與半透明填充。","usage":"執行 PlineAreaStat → 於對話框設定樓層、類組、輸出方式 → 選取聚合線 → 標註面積並統計","level":8,"lt":"✅","ver":"v4（2026-09-06 檔案日期）","author":"ChengBar (MyCAD)","video":"","fas":"fas/PlineAreaStat.fas"},{"no":1392,"file":"PlineClash.lsp","cmd":"PlineClash","cat":"查詢","desc":"多選封閉聚合線，檢查其外側指定距離與指定圖層內的干涉物件並亮顯，可選擇以雲形線標示並可調色、一鍵清除。","usage":"執行 PlineClash → 於對話框設定外側距離、圖層、雲形線選項與顏色 → 選取封閉聚合線 → 亮顯干涉物件並繪製雲形線","level":7,"lt":"✅","ver":"2026-05-12 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/PlineClash.fas"},{"no":1393,"file":"PLL-div-xline-D.LSP","cmd":"PLL-div-xline-D","cat":"繪圖","desc":"選取線或聚合線，依固定距離沿路徑產生 XLINE 輔助線，距離預設為上次輸入值。","usage":"執行 PLL-div-xline-D → 選取線／聚合線 → 輸入分割距離 → 產生 XLINE","level":5,"lt":"✅","ver":"2025-09-28 (檔案日期)","author":"—","video":"https://youtu.be/pP26z6BPyjo","fas":"fas/PLL-div-xline-D.fas"},{"no":1394,"file":"PLL-div-xline-DC.LSP","cmd":"PLL-div-xline-DC","cat":"繪圖","desc":"選取線或聚合線，依固定距離分割並以餘數對半置中分布，沿路徑產生 XLINE 輔助線。","usage":"執行 PLL-div-xline-DC → 選取線／聚合線 → 輸入分割距離 → 產生置中分布的 XLINE","level":5,"lt":"✅","ver":"2025-09-27 (檔案日期)","author":"—","video":"https://youtu.be/-Ddd6e9ZUOw","fas":"fas/PLL-div-xline-DC.fas"},{"no":1395,"file":"PLL-div-xline-sm.lsp","cmd":"PLL-div-xline-sm","cat":"繪圖","desc":"對線、弧、聚合線直線段與弧段等分並繪製 XLINE 輔助線，支援一般等分與中點起算雙模式，自動判斷物件類型並可連續選取。","usage":"執行 PLL-div-xline-sm → 對話框選擇等分模式與數量 → 選取物件 → 產生 XLINE，可連續選取","level":8,"lt":"⚠️","ver":"v2.1 2026/11/03","author":"ChengBar (鄭順益) (MyCAD)","video":"https://youtu.be/npmogE0JbZw","fas":"fas/PLL-div-xline-sm.fas"},{"no":1396,"file":"PLL-div-xline-UI.lsp","cmd":"PLL-div-xline-UI","cat":"繪圖","desc":"以對話框輸入等分數，將選取的線或聚合線等分並產生 XLINE 輔助線。","usage":"執行 PLL-div-xline-UI → 於對話框輸入等分數 → 選取物件 → 產生 XLINE","level":6,"lt":"✅","ver":"2025-09-24 (檔案日期)","author":"—","video":"","fas":"fas/PLL-div-xline-UI.fas"},{"no":1397,"file":"PLL-div-xline.lsp","cmd":"PLL-div-xline、ARC-div-xline","cat":"繪圖","desc":"依等分數將線／聚合線（PLL-div-xline）或圓弧（ARC-div-xline）等分，於分點產生 XLINE 輔助線。","usage":"執行 PLL-div-xline 或 ARC-div-xline → 選取物件 → 輸入等分數（預設為上次值）→ 產生 XLINE","level":5,"lt":"✅","ver":"20241117","author":"chengshunyi","video":"https://youtu.be/7V4bOqOtSHk","fas":"fas/PLL-div-xline.fas"},{"no":1398,"file":"PLL-mid-blk.LSP","cmd":"PLL-mid-blk-W、PLL-mid-blk-WP","cat":"圖塊/屬性","desc":"連續點選線、聚合線或多線，於幾何中點依線段角度放置牆類型圖塊並寫入屬性；W 為一般牆，WP 為防水牆。","usage":"執行 PLL-mid-blk-W 或 -WP → 於對話框設定比例、單位、TAG 與屬性值 → 連續點選牆線 → 自動插入圖塊","level":7,"lt":"✅","ver":"2026-09-09 (檔案日期)","author":"ChengBar (MyCAD)","video":"https://youtu.be/nGeP84ht3vQ","fas":"fas/PLL-mid-blk.fas"},{"no":1399,"file":"pll-tt-bylayer.LSP","cmd":"pll-tt-bylayer","cat":"面積/數量統計","desc":"依圖層（計算-*）統計物件長度或面積，產生含顏色標示塊的分類小計表格，並可換算不同單位。","usage":"執行 pll-tt-bylayer → 選取物件 → 指定表格插入點 → 產生依圖層分類的小計表","level":6,"lt":"⚠️","ver":"20231129","author":"chengshunyi（改自 pBe、hak_vz 等）","video":"","fas":"fas/pll-tt-bylayer.fas"},{"no":1400,"file":"PlLengthLabelBatch.lsp","cmd":"PLL、PlLengthLabelBatch","cat":"標註","desc":"以對話框設定繪圖單位、比例尺與起始編號，連續選取聚合線並標註其長度（m），可自動編號。","usage":"執行 PLL → 於對話框設定單位、比例、起始編號與文字樣式 → 連續選取聚合線 → 標註長度","level":6,"lt":"✅","ver":"2025-08-08 (檔案日期)","author":"MyCAD","video":"https://youtu.be/sfCcdDWxq3Q","fas":"fas/PlLengthLabelBatch.fas"},{"no":1401,"file":"plotpa2project.lsp","cmd":"plotpa2project","cat":"出圖/列印","desc":"將出圖設定（印表機、筆式樣式表等支援路徑）指向專案目錄下的 ComputerSetting\\Plotters 資料夾。","usage":"執行 plotpa2project → 依目前圖檔所在專案目錄自動設定繪圖機相關路徑","level":4,"lt":"✅","ver":"20230111","author":"chengshunyi","video":"","fas":"fas/plotpa2project.fas"},{"no":1402,"file":"PLWtoOutline.lsp","cmd":"PLWO","cat":"修改","desc":"將具固定寬度的聚合線轉為不含寬度、描繪外緣並封口的空心輪廓聚合線，並刪除原聚合線。","usage":"執行 PLWO → 選取有寬度的聚合線 → 自動產生輪廓並刪除原線","level":5,"lt":"✅","ver":"20230404","author":"Kent Cooper（2009）原作，chengshunyi 修改","video":"","fas":"fas/PLWtoOutline.fas"},{"no":1403,"file":"po-to-4side.lsp","cmd":"po-to-4side-v、po-to-4side-h、po-to-4side-hv、po-to-4side、test500","cat":"標註","desc":"於空間內點取一點，向垂直／水平方向發射射線找出四面牆交點，自動標註尺寸，供自然採光面積檢討使用；可選垂直、水平或兩者。","usage":"執行 po-to-4side-hv（或 -v、-h）→ 點取空間內一點 → 自動標註四向尺寸","level":7,"lt":"✅","ver":"20240413","author":"chengshunyi（部分源自 Tharwat Al Choufi）","video":"","fas":"fas/po-to-4side.fas"},{"no":1404,"file":"POL-POL.LSP","cmd":"pol-pol","cat":"繪圖","desc":"依輸入的圖層名稱，於兩條聚合線之間繪製連接線。","usage":"執行 pol-pol → 輸入圖層名稱 → 選取聚合線 → 自動繪製連接線","level":4,"lt":"✅","ver":"87.06.01","author":"—","video":"","fas":"fas/POL-POL.fas"},{"no":1405,"file":"poly-cen-x.LSP","cmd":"poly-cen-x","cat":"繪圖","desc":"選取 LWPOLYLINE 後，計算其中心點並在中心繪製 X 形交叉線。","usage":"執行 poly-cen-x → 選取聚合線 → 於中心自動畫 X","level":4,"lt":"✅","ver":"20240523","author":"chengshunyi（範例源自 Lee Mac）","video":"","fas":"fas/poly-cen-x.fas"},{"no":1406,"file":"poly-la-by-elv.LSP","cmd":"poly-la-by-elv","cat":"圖層","desc":"依聚合線的高程（Elevation）判斷，將其改到對應圖層（如 hatch-D），圖層不存在時自動建立。","usage":"執行 poly-la-by-elv → 選取聚合線 → 依高程自動分配圖層","level":4,"lt":"✅","ver":"20221203","author":"chengshunyi","video":"","fas":"fas/poly-la-by-elv.fas"},{"no":1407,"file":"poly-point.LSP","cmd":"poly-point","cat":"查詢","desc":"選取聚合線後讀取並列出其頂點座標。","usage":"執行 poly-point → 選取聚合線 → 顯示頂點座標","level":1,"lt":"✅","ver":"2022-11-26 (檔案日期)","author":"—","video":"","fas":"fas/poly-point.fas"},{"no":1408,"file":"polyarc2ml.lsp","cmd":"polyarc2ml","cat":"修改","desc":"將選取的聚合線、直線、圓或圓弧轉換為多線（MLINE），並以清單對話框選擇多線樣式。","usage":"執行 polyarc2ml → 選取要轉換的物件 → 於清單方塊選擇多線樣式 → 產生多線","level":6,"lt":"✅","ver":"20220716","author":"gile（ListBox 函式）、chengshunyi 修改","video":"","fas":"fas/polyarc2ml.fas"},{"no":1409,"file":"PolyArea_B.LSP","cmd":"PolyArea_B","cat":"面積/數量統計","desc":"選取封閉物件標註面積（cm2 換算 m2），可選 MTEXT/TEXT/圖塊輸出、自動編號，並產生計算式與合計。","usage":"執行 PolyArea_B → 選取物件或 Enter 全選 → 輸入前置碼 → 指定標註位置 → 輸出面積與合計","level":6,"lt":"✅","ver":"20240427","author":"GC(gile) 原作 2018，Patrice B. 修改，chengshunyi 增修","video":"","fas":"fas/PolyArea_B.fas"},{"no":1410,"file":"PolyArea_C.LSP","cmd":"PolyArea_C","cat":"面積/數量統計","desc":"選取封閉物件標註面積（cm2 換算 m2），可選 MTEXT/TEXT/圖塊輸出、自動編號，並產生計算式與合計，為 PolyArea_B 的後續版本。","usage":"執行 PolyArea_C → 選取物件或 Enter 全選 → 輸入前置碼 → 指定標註位置 → 輸出面積與合計","level":6,"lt":"✅","ver":"2024-06-09 (檔案日期)","author":"GC(gile) 原作 2018，Patrice B. 修改，chengshunyi 增修","video":"","fas":"fas/PolyArea_C.fas"},{"no":1411,"file":"polyline-hatch.lsp","cmd":"polyline-hatch","cat":"繪圖","desc":"選取多個封閉聚合線，以 entmake 方式快速建立 Hatch 填充，可設定圖案名稱、角度與比例。","usage":"執行 polyline-hatch → 選取封閉聚合線 → 自動建立 Hatch","level":4,"lt":"✅","ver":"20220701","author":"ElpanovEvgeniy","video":"","fas":"fas/polyline-hatch.fas"},{"no":1412,"file":"POLYTRIM.LSP","cmd":"POLYTRIM","cat":"修改","desc":"選取封閉聚合線為邊界，自動修剪或刪除其內部或外部所有干涉物件，以射線法判斷內外。","usage":"執行 POLYTRIM → 於對話框選擇修剪內部／外部或刪除 → 選取封閉聚合線 → 自動裁剪","level":7,"lt":"✅","ver":"2026-09-01 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/POLYTRIM.fas"},{"no":1413,"file":"PolyZag45.lsp","cmd":"PolyZag、Poly45","cat":"繪圖","desc":"依指定的 X、Y 段長，連續點選繪製鋸齒狀聚合線；PolyZag 為直角鋸齒，Poly45 為 45 度斜向鋸齒。","usage":"執行 PolyZag 或 Poly45 → 輸入 X、Y 段長 → 指定起點 → 連續指定下一點","level":4,"lt":"✅","ver":"20220716","author":"Tharwat Al Shoufi","video":"","fas":"fas/PolyZag45.fas"},{"no":1414,"file":"prefman.lsp","cmd":"prefman","cat":"系統/授權","desc":"以對話框管理 OPTIONS 重要設定，如開始對話框、備份、自動儲存、十字游標大小、指令行行數與筆寬表路徑。","usage":"執行 prefman → 於對話框調整各項開關與數值 → 按確定套用","level":6,"lt":"✅","ver":"2025-10-22 (檔案日期)","author":"MyCAD","video":"","fas":""},{"no":1415,"file":"prefman_sysvars.lsp","cmd":"prefman_sysvars","cat":"系統/授權","desc":"以對話框集中控制提升 AutoCAD 效能與操作的系統變數，如 SELECTIONCYCLING、UCSDETECT、ORTHOMODE、DYNMODE 等。","usage":"執行 prefman_sysvars → 勾選各系統變數開關 → 按確定套用","level":6,"lt":"✅","ver":"2025-10-22 (檔案日期)","author":"MyCAD","video":"https://youtu.be/pNcIK3s6Pzg","fas":""},{"no":1416,"file":"PS-add-TXT.lsp","cmd":"PS-add-TXT、PS-add-end-m、PS-add-end-m2、PS-add-end-m3、PS-add-end-pin、PS-add-end、PS-del-end-m、PS-del-end-m2、PS-del-end-m3、PS-del-end-pin、PS-del-end","cat":"文字","desc":"對 TEXT／MTEXT／屬性／多重引線文字批次於字串頭或尾加入字串（如 m、m2、m3、坪）；對應 PS-del 指令則移除字尾。","usage":"執行 PS-add-TXT → 選擇加在前綴或後綴 → 輸入字串 → 選取文字；或直接執行 PS-add-end-m 等快捷指令","level":4,"lt":"✅","ver":"20250108","author":"chengshunyi","video":"","fas":"fas/PS-add-TXT.fas"},{"no":1417,"file":"PSimple.lsp","cmd":"PSimple、PSimpleV","cat":"修改","desc":"刪除聚合線直線路徑上多餘的共線頂點（支援弧段與變寬度）；PSimpleV 為指令列選集版本。","usage":"執行 PSimple → 選取聚合線 → 自動移除多餘頂點","level":5,"lt":"✅","ver":"Version 1.7 Nov. 24, 2007（20230907 修改）","author":"Charles Alan Butler 原作，chengshunyi 修改","video":"","fas":"fas/PSimple.fas"},{"no":1418,"file":"PSM.lsp","cmd":"PSM","cat":"出圖/列印","desc":"批次更新全部 Layout 頁面設定，並穩定附加外部參考（Xref），支援絕對／相對路徑與附加／覆蓋類型。","usage":"執行 PSM → 於對話框設定頁面設定與外參檔案、路徑類型 → 按確定批次套用","level":8,"lt":"✅","ver":"2026-09-05 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/PSM.fas"},{"no":1419,"file":"pts-AddLWPolyline.lsp","cmd":"（無，副程式庫）","cat":"其他","desc":"提供以 ActiveX 在目前空間（模型／配置）建立 LWPOLYLINE 的函式 cd:ACX_AddLWPolyline，傳入頂點串列與是否封閉。","usage":"由其他程式呼叫，例如 (cd:ACX_AddLWPolyline (cd:ACX_ASpace) pts nil)","level":5,"lt":"⚠️","ver":"2025-01-20 (檔案日期)","author":"CAD Ideas 函式（波蘭語註解）","video":"","fas":"fas/pts-AddLWPolyline.fas"},{"no":1420,"file":"pts-hatch.LSP","cmd":"pts-hatch","cat":"繪圖","desc":"讀取聚合線頂點，以 -HATCH 繪製實心填充（剖面塗黑），套用 RCW-HATCH 圖層、50% 透明度並送至最後，可處理未封閉聚合線。","usage":"執行 pts-hatch → 選取聚合線 → 自動建立實心 Hatch","level":5,"lt":"✅","ver":"20220710","author":"—","video":"","fas":"fas/pts-hatch.fas"},{"no":1421,"file":"pts-to-surface-v2.LSP","cmd":"pts-to-surface-v2","cat":"3D","desc":"將選取的不規則 3D 點雲進行三角網格化，產生 3DFACE 地形曲面並顯示耗時。","usage":"執行 pts-to-surface-v2 → 選取多個 POINT 點 → 自動產生 3DFACE","level":7,"lt":"⚠️","ver":"20220716","author":"ElpanovEvgeniy（2008-10-17）","video":"","fas":"fas/pts-to-surface-v2.fas"},{"no":1422,"file":"pts-to-surface.LSP","cmd":"pts-to-surface","cat":"3D","desc":"以 Delaunay 三角化法由 3D 點雲建立 TIN 三角網（3DFACE），含圓周圓計算與耗時顯示。","usage":"執行 pts-to-surface → 選取多個 POINT 點 → 自動產生 3DFACE 地形網","level":7,"lt":"⚠️","ver":"20240616","author":"Daniele Piazza（原 Paul Bourke 演算法），CAB 修改，chengshunyi 增修","video":"","fas":"fas/pts-to-surface.fas"},{"no":1423,"file":"pts2-hatch-FIRE-auto.LSP","cmd":"pts2-hatch-FIRE-auto","cat":"繪圖","desc":"選取聚合線後，自動依其圖層（防火區劃-ST／防火區劃-SHAFT）判斷，在固定圖層以實心 Hatch 繪製防火區劃，並套 50% 透明度。","usage":"執行 pts2-hatch-FIRE-auto → 選取聚合線 → 自動建立對應防火區劃 Hatch","level":5,"lt":"✅","ver":"20250726","author":"chengshunyi","video":"https://youtu.be/1k3h8SyFGtg","fas":"fas/pts2-hatch-FIRE-auto.fas"},{"no":1424,"file":"pts2-hatch-FIRE.LSP","cmd":"pts2-hatch-FIRE-ST、pts2-hatch-FIRE-SHAFT、pts2-hatch-FIRE","cat":"繪圖","desc":"選取聚合線後，於 1HR-ST（樓梯）或 1HR-SHAFT（管道間）圖層建立實心 Hatch 作防火區劃表示；pts2-hatch-FIRE 可選擇類型。","usage":"執行 pts2-hatch-FIRE-ST 或 -SHAFT（或 pts2-hatch-FIRE 後選類型）→ 選取聚合線 → 自動建立 Hatch","level":5,"lt":"✅","ver":"20250726","author":"chengshunyi","video":"","fas":"fas/pts2-hatch-FIRE.fas"},{"no":1425,"file":"pts2-hatch-RC.LSP","cmd":"hatch-rc、hatch-rc-t、pts2-hatch","cat":"繪圖","desc":"依圖面比例（1/50 分界）於聚合線內填充 AR-CONC 混凝土剖面圖案；hatch-rc-t 使用 AR-CONC-t 變形圖案。","usage":"執行 hatch-rc 或 hatch-rc-t → 選取聚合線 → 自動建立混凝土剖面 Hatch","level":6,"lt":"✅","ver":"20220710","author":"—","video":"https://youtu.be/FLPTbDpQmWw","fas":"fas/pts2-hatch-RC.fas"},{"no":1426,"file":"pts2-hatch.LSP","cmd":"pts2-hatch","cat":"繪圖","desc":"讀取選取聚合線頂點，以 -HATCH 在 RCW-HATCH 圖層繪製實心填充（剖面塗黑），50% 透明度並送至最後。","usage":"執行 pts2-hatch → 選取聚合線 → 自動建立實心 Hatch","level":5,"lt":"✅","ver":"20220710","author":"—","video":"https://youtu.be/FLPTbDpQmWw","fas":"fas/pts2-hatch.fas"},{"no":1427,"file":"PURGE-LT.lsp","cmd":"purge-LT","cat":"圖面管理","desc":"以對話框設定 Purge 次數，依序執行 AUDIT、REGAPP 清理、多次 PURGE 與 DGN 孤立資料／比例清單重設，並顯示清理前後檔案大小與耗時。","usage":"執行 purge-LT → 於對話框設定 Purge 次數與各項勾選 → 按確定自動清理 → 顯示結果","level":6,"lt":"✅","ver":"2026-05-27 (檔案日期)","author":"ChengBar (MyCAD)","video":"https://youtu.be/7Py3ZauKkMo","fas":"fas/purge-lt.fas"},{"no":1428,"file":"PURGE_SCAN-M.lsp","cmd":"PURGE_LOG、PURGE_SCAN-M","cat":"圖面管理","desc":"整合圖層與多類符號表深度清理，並支援以腳本批次清理多張圖檔，顯示清理計數與前後比較，附 Logo 與狀態列。","usage":"執行 PURGE_SCAN-M → 於對話框勾選清理項目與批次選項 → 以 getfiled 選資料夾內任一 DWG → 執行清理並顯示摘要","level":9,"lt":"✅","ver":"Ver 4.0（2026-11-10）","author":"ChengBar (MyCAD)","video":"https://youtu.be/7nj0oanxxWE","fas":"fas/PURGE_SCAN-M.fas"},{"no":1429,"file":"PURGE_SCAN.lsp","cmd":"PURGE_SCAN","cat":"圖面管理","desc":"圖面深度掃描與清理工具，掃描圖層、樣式、圖塊、線型、DGN 資料等未使用項目，顯示計數並分類執行 -PURGE，附幻燈片預覽與向量 Logo。","usage":"執行 PURGE_SCAN → 於對話框勾選清理類別 → 按確定掃描並清理 → 顯示清理前後比較","level":8,"lt":"✅","ver":"Ver 3.2（2026-10-21）","author":"ChengBar (MyCAD)","video":"https://youtu.be/jpd5hnFHWjY","fas":"fas/PURGE_SCAN.fas"},{"no":1430,"file":"PurgeAuditFiles.lsp","cmd":"PurgeAuditFiles","cat":"圖面管理","desc":"選取資料夾後（可含子資料夾），以 COM 啟動 AutoCAD 逐一開啟其中的 DWG，執行 PURGE 與 AUDIT 後存檔，批次清理整個資料夾的圖檔。","usage":"執行 PurgeAuditFiles → 選取含 DWG 的資料夾 → 選擇是否含子資料夾 → 自動批次開啟、清理並存檔","level":8,"lt":"❌","ver":"20220716（原 CADALYST 03/05 Tip2023）","author":"Piyush Parihar (CADALYST)，chengshunyi 修改","video":"","fas":"fas/PurgeAuditFiles.fas"},{"no":1431,"file":"put-blk-in-pl.LSP","cmd":"put-blk-in-pl","cat":"圖塊/屬性","desc":"選取聚合線圖層與圖塊，在該圖層符合長度範圍（50～6500）的聚合線位置自動插入指定圖塊。","usage":"執行 put-blk-in-pl → 選取欲處理的聚合線圖層 → 選取要插入的圖塊 → 自動於各聚合線插入圖塊","level":5,"lt":"✅","ver":"20240302","author":"chengshunyi","video":"","fas":"fas/put-blk-in-pl.fas"},{"no":1432,"file":"put-center-mark.LSP","cmd":"put-center-mark、CIRCEN1","cat":"標註","desc":"對選取的圓或圓弧在圓心繪製十字中心線記號，並以圖層控制，可設定記號大小。","usage":"執行 put-center-mark（或 CIRCEN1）→ 選取圓／圓弧 → 自動繪製中心記號","level":4,"lt":"✅","ver":"20241106","author":"—（CIRCEN 類範例改編）","video":"","fas":"fas/put-center-mark.fas"},{"no":1433,"file":"put-layer-desc-sf.lsp","cmd":"put-layer-desc-sf","cat":"圖層","desc":"讀取圖層說明對照文字檔（layerlist.txt），依圖層名稱批次寫入圖層說明，可自行選取檔案。","usage":"執行 put-layer-desc-sf → 選取圖層說明對照文字檔 → 自動寫入圖層說明 → 顯示完成","level":6,"lt":"✅","ver":"20230826","author":"chengshunyi（Shun-Yi Studio）","video":"","fas":"fas/put-layer-desc-sf.fas"},{"no":1434,"file":"put-layer-desc.lsp","cmd":"put-layer-desc","cat":"圖層","desc":"讀取固定路徑的圖層說明對照文字檔（layerlist.txt），依圖層名稱批次寫入圖層說明。","usage":"執行 put-layer-desc → 自動讀取 layerlist.txt → 寫入圖層說明 → 顯示完成","level":6,"lt":"✅","ver":"2007.12.09 / 20220716","author":"chengshunyi（Shun-Yi Studio）","video":"","fas":"fas/put-layer-desc.fas"},{"no":1435,"file":"put-LineAng.lsp","cmd":"put-LineAng","cat":"標註","desc":"以欄位（Field）在直線端點標註其角度，字高與單位依圖紙設定自動換算，角度隨線條更新。","usage":"執行 put-LineAng → 選取直線 → 於端點放置角度欄位文字","level":6,"lt":"✅","ver":"20240420","author":"Lee Mac 原作，chengshunyi 修改","video":"","fas":"fas/put-LineAng.fas"},{"no":1436,"file":"put-obj-2-point.LSP","cmd":"put-obj-2-point","cat":"圖塊/屬性","desc":"於兩點之間依等分數量自動插入帶屬性圖塊，對話框含幻燈片預覽並記憶上次等分數。","usage":"執行 put-obj-2-point → 於對話框輸入等分數量 → 選取圖塊 → 點選兩點 → 自動等分插入並寫入屬性","level":7,"lt":"⚠️","ver":"v3.1 (2026 Edition)","author":"ChengBar (MyCAD)","video":"https://youtu.be/DRSW2NCm8xU","fas":"fas/put-obj-2-point.fas"},{"no":1437,"file":"put-obj-div-2-point-d.LSP","cmd":"put-obj-div-2-point-d","cat":"圖塊/屬性","desc":"於兩點之間依固定間距等距放置帶屬性圖塊，對話框驗證間距，一次 U 可還原全部圖塊。","usage":"執行 put-obj-div-2-point-d → 於對話框輸入間距 → 選取圖塊 → 點選兩點 → 自動等距插入","level":7,"lt":"✅","ver":"V2.3 (2026-10-25)","author":"ChengBar (鄭順益) (MyCAD)","video":"https://youtu.be/y5lyMYXASeQ","fas":"fas/put-obj-div-2-point-d.fas"},{"no":1438,"file":"put-obj-div-2-point.lsp","cmd":"put-obj-div-2-point","cat":"圖塊/屬性","desc":"選取圖塊後依其寬度自動判斷間距，於兩點之間等距排列圖塊，並可自動編號（含機械車位 1、2、3 層編號）。","usage":"執行 put-obj-div-2-point → 選取圖塊 → 點選第一點與第二點 → 自動排列並編號","level":6,"lt":"✅","ver":"20250320","author":"chengshunyi","video":"https://youtu.be/doL1Q88Hqjg","fas":"fas/put-obj-div-2-point.fas"},{"no":1439,"file":"put-rev-mutilayout.LSP","cmd":"put-packagename-mutilayout","cat":"圖塊/屬性","desc":"依序切換各個 Layout，於每個配置插入固定專案路徑的修訂表圖塊 12P9-REV.dwg 並縮放。","usage":"執行 put-packagename-mutilayout → 自動逐一切換配置並插入修訂圖框","level":4,"lt":"✅","ver":"20220716","author":"chengshunyi","video":"","fas":"fas/put-rev-mutilayout.fas"},{"no":1440,"file":"put-rev.LSP","cmd":"put-rev","cat":"圖塊/屬性","desc":"於目前配置插入固定專案路徑的修訂表圖塊 12P9-REV.dwg。","usage":"執行 put-rev → 自動切換至配置並插入修訂圖框","level":3,"lt":"✅","ver":"20220716","author":"chengshunyi","video":"","fas":"fas/put-rev.fas"},{"no":1441,"file":"QFC.lsp","cmd":"QFC","cat":"系統/授權","desc":"MyCAD 快速指令發射器：讀取 commands.txt 以清單對話框列出工具，可搜尋，選取後自動載入對應 LISP 並執行指令。","usage":"執行 QFC → 於清單對話框搜尋並選取工具 → 按確定自動載入並執行該指令","level":7,"lt":"⚠️","ver":"v1.0.7 (2026-10-04)","author":"ChengBar (MyCAD)","video":"","fas":""},{"no":1442,"file":"qp.lsp","cmd":"qp","cat":"剖面/結構","desc":"依現有等高線圖層沿剖線產生地形剖面圖，並列出樁號（chainage）資訊表格。","usage":"執行 qp → 輸入等高線圖層（可多個，逗號隔開）→ 指定剖線與比例 → 自動繪製地形剖面與樁號表","level":7,"lt":"✅","ver":"Version 1.0 (09 of May 2006)","author":"Pedro Miguel da Silva Ferreira，CAB 修改","video":"","fas":"fas/qp.fas"},{"no":1443,"file":"QuickMirror.lsp","cmd":"QM、QMD、QMO、QMOD","cat":"修改","desc":"快速鏡射：不需點兩點定義鏡射軸，單選物件可依選取邊的切線為軸鏡射，或選物件為軸；D 變形為鏡射後刪除原物件，O 變形為單物件模式。","usage":"執行 QM（或 QMD、QMO、QMOD）→ 選取要鏡射的物件／選集 → 選取作為鏡射軸的物件","level":5,"lt":"✅","ver":"Version 1.0 - 15-02-2011","author":"Lee Mac","video":"","fas":"fas/QuickMirror.fas"},{"no":1444,"file":"R-C.lsp","cmd":"R-C","cat":"修改","desc":"一次移除圖面中所有物件的幾何與標註約束（DELCONSTRAINT），並顯示處理訊息。","usage":"執行 R-C → 自動選取全部物件並刪除約束","level":1,"lt":"✅","ver":"2026-03-28 (檔案日期)","author":"—","video":"","fas":"fas/R-C.fas"},{"no":1445,"file":"RAC.lsp","cmd":"RAC","cat":"修改","desc":"將選取物件各自以其邊界框中心為基準點原地旋轉，輸入逆時針角度即可，排除射線、建構線與鎖定圖層物件。","usage":"執行 RAC → 選取物件 → 輸入旋轉角度 (逆時針為正)","level":5,"lt":"✅","ver":"20241215","author":"chengshunyi","video":"","fas":"fas/RAC.fas"},{"no":1446,"file":"RainStoreCalc-trial-V1.LSP","cmd":"RainStoreCalc、RSC、RainStoreCalc-trial","cat":"面積/數量統計","desc":"雨水貯集容量試算工具：依基地面積或建築面積與建蔽率試算最小設置容量，並將計算式文字寫入圖面。","usage":"執行 RSC → 於對話框輸入基地面積、建築面積、建蔽率、單位與比例 → 按試算 → 點選文字插入位置寫入計算式","level":6,"lt":"✅","ver":"2025-08-07 (檔案日期)","author":"ShunYi 團隊","video":"","fas":"fas/RainStoreCalc-trial-V1.fas"},{"no":1447,"file":"RainStoreCalc-trial-V2.LSP","cmd":"RainStoreCalc、RSC、RainStoreCalc-trial","cat":"面積/數量統計","desc":"雨水貯集容量試算工具試用版 V2：增加字高、行距與授權管理機制，試算最小設置容量並寫入圖面。","usage":"執行 RSC → 於對話框輸入基地面積、建築面積、建蔽率、單位、比例與字高 → 按試算 → 點選插入位置寫入計算式","level":6,"lt":"✅","ver":"2025-08-10 (檔案日期)","author":"ShunYi 團隊","video":"","fas":"fas/RainStoreCalc-trial-V2.fas"},{"no":1448,"file":"RainStoreCalc-trial.lsp","cmd":"RainStoreCalc、RSC、RainStoreCalc-trial","cat":"面積/數量統計","desc":"雨水貯集容量試算工具試用版：依基地面積或建築面積與建蔽率試算最小設置容量，並寫入圖面。","usage":"執行 RSC → 於對話框輸入面積與建蔽率 → 按試算 → 點選文字插入位置寫入計算式","level":6,"lt":"✅","ver":"2025-08-07 (檔案日期)","author":"ShunYi 團隊","video":"","fas":"fas/RainStoreCalc-trial.fas"},{"no":1449,"file":"RainStoreCalc-V1.LSP","cmd":"RainStoreCalc、RSC","cat":"面積/數量統計","desc":"雨水貯集容量試算工具正式版 V1：可設定單位、比例尺與字高，試算最小設置容量並寫入圖面。","usage":"執行 RSC → 於對話框輸入面積、建蔽率、單位、比例與字高 → 按試算 → 點選插入位置寫入計算式","level":6,"lt":"✅","ver":"2025-08-07 (檔案日期)","author":"ShunYi 團隊","video":"","fas":"fas/RainStoreCalc-V1.fas"},{"no":1450,"file":"RainStoreCalc.lsp","cmd":"RainStoreCalc、RainCalcTrial","cat":"面積/數量統計","desc":"雨水貯集容量試算工具：依有無合法建築物，以基地面積或建築面積與建蔽率試算最小設置容量，結果寫入圖面。","usage":"執行 RainStoreCalc → 於對話框輸入面積與建蔽率 → 按試算 → 點選文字插入位置寫入計算式","level":6,"lt":"✅","ver":"2025-08-07 (檔案日期)","author":"ShunYi 團隊","video":"","fas":"fas/RainStoreCalc.fas"},{"no":1451,"file":"RC.LSP","cmd":"rc","cat":"繪圖","desc":"輸入牆厚後，點選三點繪製 RC 牆線（兩平行線與端線）。","usage":"執行 rc → 輸入牆厚 → 點選第 1、2、3 點 → 自動畫牆線","level":4,"lt":"✅","ver":"85.07.17","author":"—","video":"","fas":"fas/RC.fas"},{"no":1452,"file":"RD-FL.lsp","cmd":"RD-FL、RISE_FLOOR_CORE、txtstylecheck、laycheck","cat":"繪圖","desc":"以對話框選擇高架或降板與高度／深度，自動切換對應圖層、文字樣式與線型，繪製高架／降板範圍聚合線。","usage":"執行 RD-FL → 於對話框選擇高架或降板與高度 → 點選範圍繪製聚合線","level":6,"lt":"✅","ver":"2025-12-24 (檔案日期)","author":"MyCAD","video":"","fas":"fas/RD-FL.fas"},{"no":1453,"file":"re-cal.lsp","cmd":"re-cal","cat":"查詢","desc":"選取含計算式的文字，載入 geomcal 計算機重算並驗算結果，把計算結果回填至文字。","usage":"執行 re-cal → 選取計算式文字 → 自動重算並更新結果","level":5,"lt":"❌","ver":"20250325","author":"chengshunyi","video":"","fas":"fas/re-cal.fas"},{"no":1454,"file":"re-cal2.lsp","cmd":"re-cal2","cat":"查詢","desc":"選取含計算式的文字，載入 geomcal 計算機重算並驗算結果，把計算結果回填至文字（re-cal 的複本）。","usage":"執行 re-cal2 → 選取計算式文字 → 自動重算並更新結果","level":5,"lt":"❌","ver":"20250325","author":"chengshunyi","video":"","fas":"fas/re-cal2.fas"},{"no":1455,"file":"read-pus-ez-pak.lsp","cmd":"（無，副程式庫）","cat":"系統/授權","desc":"讀取並設定圖紙、單位、比例與各係數（單位、長度、面積）全域變數，並顯示於狀態列 MODEMACRO，供面積與標註程式共用。","usage":"由其他程式載入呼叫，例如 (set-pusbyez)","level":5,"lt":"✅","ver":"20240104","author":"chengshunyi","video":"","fas":""},{"no":1456,"file":"read-pus-ez.lsp","cmd":"（無，副程式庫）","cat":"系統/授權","desc":"圖紙／單位／比例設定公用程式，讀取圖檔設定值並計算單位、長度、面積係數，LT 版改用自訂 DWG 屬性儲存，並更新狀態列顯示。","usage":"由其他程式載入呼叫，例如 (set-pusbyez)","level":6,"lt":"✅","ver":"20250111","author":"chengshunyi","video":"","fas":""},{"no":1457,"file":"read-pus-switch.lsp","cmd":"read-pus-switch","cat":"系統/授權","desc":"圖紙／單位／比例設定的切換工具，判斷是否為 AutoCAD LT，LT 以自訂 DWG 屬性儲存單位比例係數，並顯示目前設定。","usage":"執行 read-pus-switch → 切換圖紙、單位與比例設定","level":6,"lt":"✅","ver":"20250116","author":"chengshunyi","video":"","fas":""},{"no":1458,"file":"read-pus.lsp","cmd":"（無，副程式庫）","cat":"系統/授權","desc":"公用程式：從圖面字典取出紙張、比例、單位及各係數設定，並寫入 MODEMACRO。","usage":"由其他程式載入呼叫","level":5,"lt":"✅","ver":"20230827","author":"chengshunyi","video":"","fas":""},{"no":1459,"file":"rec-dim-wow-v1.lsp","cmd":"rec-dim-wow-v1","cat":"標註","desc":"矩形標尺寸並統計：對矩形聚合線標註長寬、編號並產生數量表，含編號泡泡屬性圖塊。","usage":"執行 rec-dim-wow-v1 → 選取矩形聚合線 → 指定位置 → 標註尺寸並產生表格","level":8,"lt":"✅","ver":"20241211","author":"alanH（Nov 2022）改編，chengshunyi 修改","video":"","fas":"fas/rec-dim-wow-v1.fas"},{"no":1460,"file":"rec-dim-wow-v2.LSP","cmd":"rec-dim-wow-v2","cat":"面積/數量統計","desc":"統計選取矩形聚合線的圖層、長度、寬度與數量，並在指定位置產生矩形數量表。","usage":"執行 rec-dim-wow-v2 → 選取矩形聚合線 → 指定表格位置 → 產生矩形統計表","level":6,"lt":"✅","ver":"version 2（2024-12-11 檔案日期）","author":"gile","video":"","fas":"fas/rec-dim-wow-v2.fas"},{"no":1461,"file":"Recreate-Mleader.LSP","cmd":"kaa-Recreate-Mleader-2D","cat":"標註","desc":"重新建立選取的多重引線，並處理註解性比例內容資料，用來修復或更新異常的 MLEADER。","usage":"執行 kaa-Recreate-Mleader-2D → 選取多重引線 → 自動重建","level":7,"lt":"✅","ver":"2025-12-17 (檔案日期)","author":"kaa（網路程式）","video":"","fas":"fas/Recreate-Mleader.fas"},{"no":1462,"file":"RectLeftSideWall.lsp","cmd":"wall-V、wall-P、wall-RC、wall-C、RCW、wall-B、wall-V-F、wall-P-F、wall-RC-F、wall-C-F、RCW-F、wall-B-F、RectLeftSideWall","cat":"繪圖","desc":"兩點畫各類隔間牆矩形（輕隔間、石膏板、RC 牆、混凝土、磚牆），自動切換圖層並填充 Hatch；-F 變形為含填充版。","usage":"執行 wall-RC 等牆種指令 → 指定牆厚 → 點選兩點 → 自動畫牆並切換圖層／填充","level":7,"lt":"✅","ver":"20250323","author":"chengshunyi","video":"https://youtu.be/c9hIXOjvze0","fas":"fas/RectLeftSideWall.fas"},{"no":1463,"file":"redraw-mline.lsp","cmd":"redraw-mline","cat":"修改","desc":"讀取選取多線的頂點，依原圖層與設定以 MLINE 指令重新繪製該多線。","usage":"執行 redraw-mline → 選取多線 → 自動重新繪製","level":4,"lt":"✅","ver":"2008.05.12","author":"—","video":"","fas":"fas/redraw-mline.fas"},{"no":1464,"file":"redraw-pl-1+.lsp","cmd":"redraw-pl-1+","cat":"修改","desc":"複製聚合線頂點串列重畫，並於點選的線段位置修改該段長度後更新聚合線。","usage":"執行 redraw-pl-1+ → 選取聚合線線段 → 輸入新增長度 → 自動重畫聚合線","level":6,"lt":"✅","ver":"20240511","author":"chengshunyi","video":"","fas":"fas/redraw-pl-1+.fas"},{"no":1465,"file":"RefCheck.lsp","cmd":"RefCheck、XRefChecker","cat":"圖面管理","desc":"參照關係檢查工具：選取多個主圖檔，以 ObjectDBX 背景掃描其外部參照名稱，與目標圖檔清單比對，可輸出報表。","usage":"執行 RefCheck → 於對話框選取待檢查圖檔與目標圖檔 → 設定輸出模式 → 按確定檢查並輸出結果","level":8,"lt":"❌","ver":"2026-07-02 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/RefCheck.fas"},{"no":1466,"file":"Region2Polyline.lsp","cmd":"Region2Polyline","cat":"修改","desc":"將選取的 REGION 區域物件轉換為聚合線，依邊界線與弧重建。","usage":"執行 Region2Polyline → 選取區域物件 → 自動轉為聚合線","level":5,"lt":"✅","ver":"01/01/07","author":"Gilles Chanteau (gile)","video":"","fas":"fas/Region2Polyline.fas"},{"no":1467,"file":"ReInsertAttBlock.lsp","cmd":"ReInsertAttBlock","cat":"圖塊/屬性","desc":"選取帶屬性圖塊，讀取其屬性值與位置、旋轉與鏡射資料，重新插入圖塊並還原屬性值，可用於更新圖塊定義。","usage":"執行 ReInsertAttBlock → 選取帶屬性圖塊 → 自動重新插入並還原屬性","level":6,"lt":"✅","ver":"20230127","author":"chengshunyi","video":"","fas":"fas/ReInsertAttBlock.fas"},{"no":1468,"file":"ReInsertdyAttBlock.LSP","cmd":"ReInsertdyAttBlock","cat":"圖塊/屬性","desc":"選取動態圖塊（含屬性），讀取動態屬性與屬性值，重新插入並還原所有動態參數與屬性。","usage":"執行 ReInsertdyAttBlock → 選取動態圖塊 → 自動刪除原圖塊並重新插入、還原動態值與屬性 → 顯示完成","level":6,"lt":"✅","ver":"20250615","author":"chengshunyi（含 Lee Mac 函式）","video":"","fas":"fas/ReInsertdyAttBlock.fas"},{"no":1469,"file":"ReloadXref.lsp","cmd":"ReloadXref","cat":"圖面管理","desc":"選取一個外部參考物件後，以 XREF 重新載入，並還原 VISRETAIN 設定。","usage":"執行 ReloadXref → 選取外部參考物件 → 自動重新載入","level":4,"lt":"✅","ver":"20250928","author":"chengshunyi","video":"https://youtu.be/-6pocgO9NB8","fas":"fas/ReloadXref.fas"},{"no":1470,"file":"REM_XREF_PATH.lsp","cmd":"REM_XREF_PATH","cat":"圖面管理","desc":"將圖面中所有外部參考的儲存路徑去除資料夾，只保留檔名（改為相對路徑）。","usage":"執行 REM_XREF_PATH → 自動讀取圖面外部參考 → 移除其路徑","level":5,"lt":"✅","ver":"20220716","author":"—（網路程式）","video":"","fas":"fas/REM_XREF_PATH.fas"},{"no":1471,"file":"RemakeShp.LSP","cmd":"RemakeShp","cat":"轉檔/匯出入","desc":"讀取 simplex-unicode8.SHP 字型原始檔，依縮放與偏移重新計算字元座標，輸出新的 SHP 檔。","usage":"執行 RemakeShp → 選擇原始 SHP 檔 → 自動重新計算並存成新檔","level":6,"lt":"✅","ver":"2026-04-06 (檔案日期)","author":"—","video":"","fas":"fas/RemakeShp.fas"},{"no":1472,"file":"remove-AEC.lsp","cmd":"remove-AEC","cat":"圖面管理","desc":"刪除圖面中的 AEC 代理物件與相關物件，清除建築軟體遺留的垃圾資料。","usage":"執行 remove-AEC → 自動刪除 AEC 代理物件","level":2,"lt":"✅","ver":"20241221","author":"chengshunyi","video":"","fas":"fas/remove-AEC.fas"},{"no":1473,"file":"Remove-dim-Annotative.lsp","cmd":"Remove-dim-Annotative、Add-dim-Annotative","cat":"標註","desc":"對圖面所有尺寸標註移除（或加入）註解性屬性，改用 CHANGE 指令處理。","usage":"執行 Remove-dim-Annotative（或 Add-dim-Annotative）→ 自動選取全部尺寸並處理","level":3,"lt":"✅","ver":"20250905","author":"chengshunyi","video":"","fas":"fas/Remove-dim-Annotative.fas"},{"no":1474,"file":"RemoveDimTextOverride.lsp","cmd":"RemoveDimTextOverride","cat":"標註","desc":"清除選取尺寸的文字覆寫（TextOverride 設為空字串），讓尺寸文字恢復為實測值。","usage":"執行 RemoveDimTextOverride → 選取尺寸標註 → 自動還原實測值","level":3,"lt":"✅","ver":"2025-12-12 (檔案日期)","author":"—","video":"","fas":"fas/RemoveDimTextOverride.fas"},{"no":1475,"file":"rename-block.lsp","cmd":"Rename-block","cat":"圖塊/屬性","desc":"選取圖塊後以內嵌對話框輸入新名稱，檢查名稱是否重複，並支援動態與匿名圖塊更名。","usage":"執行 Rename-block → 選取圖塊 → 於對話框輸入新圖塊名稱 → 按確定","level":6,"lt":"✅","ver":"Version 4 - 28/10/2012（20240818 修改）","author":"原作者義大利文註解（RB_en.lsp），chengshunyi 修改","video":"","fas":"fas/rename-block.fas"},{"no":1476,"file":"RenameBlockAttTags.lsp","cmd":"test-t、test-nil、test-nil-L","cat":"圖塊/屬性","desc":"依傳入清單批次重新命名圖塊定義內的屬性 TAG（轉大寫），可選擇是否執行 ATTSYNC 同步圖塊參照。","usage":"執行 test-t（改名並同步）、test-nil（改名不同步）或 test-nil-L → 自動處理圖塊 text_A3 的屬性標籤","level":6,"lt":"✅","ver":"20251205","author":"—","video":"","fas":"fas/RenameBlockAttTags.fas"},{"no":1477,"file":"RenameBlocksByDollarPureStd.lsp","cmd":"RenameBlocksByDollarPureStd","cat":"圖塊/屬性","desc":"對名稱含 $ 的圖塊（外參綁定後產生），取最右側 $ 之後的字串為新名稱，重複時自動加序號，批次更名。","usage":"執行 RenameBlocksByDollarPureStd → 自動掃描圖塊並更名 → 顯示成功與失敗數量","level":4,"lt":"✅","ver":"2025-12-05 (檔案日期)","author":"—","video":"","fas":"fas/RenameBlocksByDollarPureStd.fas"},{"no":1478,"file":"RenLayoutUI.LSP","cmd":"RenLayoutUI","cat":"圖面管理","desc":"以對話框輸入尋找字串與替換字串，批次替換目前或全部配置（Layout）的名稱。","usage":"執行 RenLayoutUI → 於對話框輸入尋找與替換字串 → 選擇範圍（當前／全部）→ 按確定","level":6,"lt":"✅","ver":"2026-04-12 (檔案日期)","author":"—","video":"","fas":"fas/RenLayoutUI.fas"},{"no":1479,"file":"renumber-att-any.lsp","cmd":"renumber-att-any","cat":"圖塊/屬性","desc":"連續點選屬性，依前置碼、位數與增量自動重新編號。","usage":"執行 renumber-att-any → 輸入前置碼、位數、遞增值 → 依序點選屬性逐一重新編號","level":5,"lt":"✅","ver":"20240814","author":"chengshunyi","video":"","fas":"fas/renumber-att-any.fas"},{"no":1480,"file":"renumber-mt-att.LSP","cmd":"renumber-mt-att-1、renumber-mt-att-2、renumber-mt-att-3、renumber-mt-att","cat":"文字","desc":"動態連續編號工具：點選 TEXT、MTEXT 或屬性，依前置碼、後置碼、起始號與位數自動改為編號文字，並記住上次設定；-1/-2/-3 為不同格式變形。","usage":"執行 renumber-mt-att → 輸入前置碼、起始號 → 依序點選文字或屬性逐一編號 → Esc 結束","level":5,"lt":"✅","ver":"20220716","author":"原作者 RENUM.LSP（網路程式），chengshunyi 修改","video":"","fas":"fas/renumber-mt-att.fas"},{"no":1481,"file":"RenumberLayouts.lsp","cmd":"rl","cat":"圖面管理","desc":"依圖面中 Layout 出現順序自動重新編號所有圖紙空間配置名稱，可加前置碼、後置碼並指定位數與起始號。","usage":"執行 rl → 輸入前置碼、後置碼、起始號 → 自動重新命名所有配置","level":5,"lt":"✅","ver":"Version 1.1 (2020-01-26)","author":"Lee Mac","video":"","fas":"fas/RenumberLayouts.fas"},{"no":1482,"file":"ReplaceBeamBlocks.lsp","cmd":"ReplaceBeamBlocks","cat":"圖塊/屬性","desc":"選取來源動態圖塊與目標圖塊樣式後，搜尋圖面所有同名圖塊，依原圖塊邊界框的寬高於上緣中點置換為新動態圖塊並設定 W、H 動態屬性，放到 A-BLOCK 圖層。","usage":"執行 ReplaceBeamBlocks → 選取要置換的原動態圖塊 → 選取目標新圖塊 → 自動批次置換","level":7,"lt":"✅","ver":"20260303","author":"chengshunyi","video":"","fas":"fas/ReplaceBeamBlocks.fas"},{"no":1483,"file":"Report_Layers.lsp","cmd":"（無，副程式庫）","cat":"查詢","desc":"建立目前圖檔的圖層清單報表，讀取各圖層狀態（凍結等）並輸出為 layer-report.csv。","usage":"由其他程式呼叫，輸出 CSV 至圖檔目錄","level":6,"lt":"✅","ver":"2024-11-16 (檔案日期)","author":"—（網路範例）","video":"","fas":"fas/Report_Layers.fas"},{"no":1484,"file":"Report_Lines.lsp","cmd":"（無，副程式庫）","cat":"查詢","desc":"圖層報表函式庫的延伸版，除輸出圖層清單 CSV 外，並可統計指定圖層上直線數量與長度，輸出 line-report.csv。","usage":"由其他程式呼叫，輸出 CSV 至圖檔目錄","level":6,"lt":"✅","ver":"2025-03-08 (檔案日期)","author":"—（網路範例）","video":"","fas":"fas/Report_Lines.fas"},{"no":1485,"file":"reset-and-trim-xref-rn.lsp","cmd":"resetXrefs、trim-Xrefs","cat":"圖面管理","desc":"批次修改外部參考的參考名稱：trim-Xrefs 取出「-」右邊檔名並更名，resetXrefs 還原為原檔名。","usage":"執行 trim-Xrefs（取檔名）或 resetXrefs（復原檔名）→ 自動重新命名全部外部參考","level":4,"lt":"✅","ver":"20230830","author":"chengshunyi","video":"","fas":"fas/reset-and-trim-xref-rn.fas"},{"no":1486,"file":"reset-scale-list.lsp","cmd":"reset-scale-list","cat":"系統/授權","desc":"重設圖面的註解比例清單（SCALELISTEDIT 重設），並重新產生圖面。","usage":"執行 reset-scale-list → 自動重設比例清單","level":2,"lt":"✅","ver":"20250710","author":"chengshunyi","video":"","fas":""},{"no":1487,"file":"resetannotext-tsmc.lsp","cmd":"resetannotext-tsmc、RemoveAnnoText-tsmc","cat":"文字","desc":"點選目標圖層文字後，分三階段處理該圖層全部文字：先移除可註解、統一字型 Standard/字高 0.35/字寬 0.75/正中對齊，再重新開啟可註解並同步比例；RemoveAnnoText 只移除可註解。","usage":"執行 resetannotext-tsmc → 點選目標圖層上任一文字 → 自動三階段處理並切到 1:100 預覽","level":7,"lt":"✅","ver":"20251222","author":"chengshunyi","video":"","fas":"fas/resetannotext-tsmc.fas"},{"no":1488,"file":"ResetMLeaderStyle.lsp","cmd":"ResetMLeaderStyle","cat":"標註","desc":"將選取的多重引線全部改套用指定的多重引線樣式 MY-ACH。","usage":"執行 ResetMLeaderStyle → 選取多重引線 → 自動套用樣式 MY-ACH","level":3,"lt":"✅","ver":"2025-12-17 (檔案日期)","author":"—","video":"","fas":"fas/ResetMLeaderStyle.fas"},{"no":1489,"file":"ResetStyleHeight.LSP","cmd":"ResetStyleHeight","cat":"文字","desc":"檢查所有文字樣式，把固定字高不為 0 的樣式高度重設為 0，並顯示修改的樣式清單。","usage":"執行 ResetStyleHeight → 自動檢查並重設全部文字樣式字高","level":3,"lt":"✅","ver":"2026-02-01 (檔案日期)","author":"—","video":"","fas":"fas/ResetStyleHeight.fas"},{"no":1490,"file":"ResetXRefLayers.lsp","cmd":"rxl","cat":"圖層","desc":"將外部參考相依圖層的屬性（顏色、線型、開關凍結等）重設為與外參來源圖檔一致，可選單一、多個或全部外參，並可設定要重設的屬性。","usage":"執行 rxl → 選取外參或輸入 Multiple/All/Settings → 自動重設相依圖層屬性","level":8,"lt":"❌","ver":"—（檔案日期 2026-01-11）","author":"Lee Mac","video":"https://youtu.be/yYolDAD2pC0","fas":"fas/ResetXRefLayers.fas"},{"no":1491,"file":"RestoreDimStyleUI-SCA.lsp","cmd":"RestoreDimStyleUI-SCA","cat":"標註","desc":"以對話框選擇尺寸型式、圖層與比例，還原並套用對應的標註型式（含斜線 SLASH、斜線圓點等端點變體）後進行線性標註。","usage":"執行 RestoreDimStyleUI-SCA → 於對話框選擇尺寸型式、圖層與比例 → 按確定 → 進入線性標註","level":6,"lt":"✅","ver":"2025-09-21 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/RestoreDimStyleUI-SCA.fas"},{"no":1492,"file":"RestoreDimStyleUI.lsp","cmd":"RestoreDimStyleUI","cat":"標註","desc":"以對話框選擇尺寸型式、圖層與比例，還原並套用該標註型式後進行線性標註。","usage":"執行 RestoreDimStyleUI → 於對話框選擇尺寸型式、圖層與比例 → 按確定 → 進入線性標註","level":6,"lt":"✅","ver":"2025-09-27 (檔案日期)","author":"chengshunyi","video":"https://youtu.be/sGgoMcIk8h4","fas":"fas/RestoreDimStyleUI.fas"},{"no":1493,"file":"RestoreMLeaderUI.lsp","cmd":"RestoreMLeaderUI","cat":"標註","desc":"以對話框選擇多重引線樣式、圖層、比例與註記文字，還原樣式後建立多重引線。","usage":"執行 RestoreMLeaderUI → 於對話框選擇樣式、圖層、比例並輸入註記文字 → 按確定 → 指定引線位置","level":6,"lt":"✅","ver":"2025-09-27 (檔案日期)","author":"chengshunyi","video":"https://youtu.be/3bHVzZPmDtc","fas":"fas/RestoreMLeaderUI.fas"},{"no":1494,"file":"REV2026-0.lsp","cmd":"REV2026","cat":"標註","desc":"修訂雲形線工具：於對話框設定凸度、圖層、單位、比例與修訂符號，沿選取聚合線產生雲形線並插入版次符號圖塊。","usage":"執行 REV2026 → 於對話框設定凸度、圖層、單位、比例、符號 → 選 PLINE 或指定範圍 → 自動繪製雲形線與插入版次符號","level":7,"lt":"✅","ver":"2025-09-29 (檔案日期)","author":"MyCAD","video":"https://youtu.be/q_ctNjPb_kc","fas":"fas/REV2026-0.fas"},{"no":1495,"file":"REV2026.LSP","cmd":"REV2026","cat":"標註","desc":"修訂雲形線工具：於對話框設定凸度、圖層、單位、比例、修訂符號與弧線樣式（Calligraphy／Normal），沿聚合線產生雲形線並插入版次符號。","usage":"執行 REV2026 → 於對話框設定各參數 → 選 PLINE 或指定範圍 → 自動繪製雲形線與插入版次符號","level":7,"lt":"✅","ver":"2026-04-18 (檔案日期)","author":"MyCAD","video":"https://youtu.be/q_ctNjPb_kc","fas":"fas/REV2026.fas"},{"no":1496,"file":"REVCLOUD-24.lsp","cmd":"CB:REVCLOUD","cat":"標註","desc":"MyCAD 雲狀線工具：以三點矩形繪製修訂雲形線，支援圖面內或外部 delta-rev.dwg 版次圖塊自動插入，更新 rev# 屬性，並可調弧長、線寬、圖層與顏色。","usage":"執行 CB:REVCLOUD → 於對話框設定弧長、線寬、圖層、版次 → 指定三點矩形範圍 → 自動繪製雲形線並插入／更新版次圖塊","level":9,"lt":"✅","ver":"2026-08-09 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/REVCLOUD-24.fas"},{"no":1497,"file":"REVCLOUD-24A.lsp","cmd":"CB:REVCLOUD","cat":"標註","desc":"MyCAD 雲狀線工具 24A 版：三點矩形繪製修訂雲形線並插入版次圖塊，版次屬性改為純數字更新。","usage":"執行 CB:REVCLOUD → 於對話框設定弧長、線寬、圖層、版次 → 指定三點矩形範圍 → 自動繪製雲形線並插入／更新版次圖塊","level":9,"lt":"✅","ver":"2026-08-09 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/REVCLOUD-24A.fas"},{"no":1498,"file":"RISE_DOWN_FLOOR.lsp","cmd":"RISE_FLOOR_5…RISE_FLOOR_200、DOWN_FLOOR_5…DOWN_FLOOR_200、RISE_FLOOR、txtstylecheck、laycheck","cat":"繪圖","desc":"高架地板與降板自動化：以預設高度（5～200）指令一鍵繪製高架／降板範圍聚合線，自動切換圖層、線型與文字樣式並標示高度。","usage":"執行 RISE_FLOOR_xx 或 DOWN_FLOOR_xx（xx 為高度）→ 點選範圍 → 自動繪製聚合線並標註","level":6,"lt":"✅","ver":"20250110","author":"chengshunyi","video":"","fas":"fas/RISE_DOWN_FLOOR.fas"},{"no":1499,"file":"RL-Layer.lsp","cmd":"（無，副程式庫）","cat":"圖層","desc":"純資料檔：每行列出圖層名稱、線型與顏色色號，供 RLL.lsp 讀取並建立標準圖層設定。","usage":"不單獨執行，由 RLL.lsp 讀取（RL-Layer.dat 格式）","level":1,"lt":"✅","ver":"2025-04-29 (檔案日期)","author":"—（荷蘭 RLX 圖層清單）","video":"","fas":"fas/RL-Layer.fas"},{"no":1500,"file":"RLL.lsp","cmd":"（無，副程式庫）","cat":"圖層","desc":"圖層設定公用程式：讀取集中檔案 RL-Layer.dat 內每行的圖層名稱、線型與顏色，依名稱自動建立／設定圖層並載入線型。","usage":"由其他程式呼叫，例如 (rll \"LayerName\")，圖層名稱需區分大小寫","level":6,"lt":"✅","ver":"28-01-02（2002年，最後更新 22-04-02）","author":"荷蘭程式（RLX）","video":"","fas":"fas/RLL.fas"},{"no":1501,"file":"RlxCloud.LSP","cmd":"RlxCloud","cat":"標註","desc":"RLX 雲形線程式：可選徒手、矩形或多邊形範圍繪製修訂雲，可含 Hatch 填色，設定線型比例與顏色，並自動填入修訂三角形版次屬性。","usage":"執行 RlxCloud → 於對話框選擇形式（徒手／矩形／多邊形）與選項 → 依提示指定範圍 → 自動繪製雲形線並插入修訂三角","level":9,"lt":"✅","ver":"RLX 09/2003（最後 11 jul 2017）","author":"RLX（荷蘭）","video":"","fas":"fas/RlxCloud.fas"},{"no":1502,"file":"RM-NUM.LSP","cmd":"rm-num","cat":"圖塊/屬性","desc":"連續點選 ROOMNUM 圖塊（NA-ROOM），依起始號自動以 ATTEDIT 重新編號房間屬性。","usage":"執行 rm-num → 輸入起始號 → 依序點選房間編號圖塊 → 自動編號","level":4,"lt":"✅","ver":"1994/12/07（20220716 更新）","author":"CHENG SHUN YI (chengshunyi)","video":"","fas":"fas/RM-NUM.fas"},{"no":1503,"file":"RMS-archi.lsp","cmd":"RMS-archi","cat":"系統/授權","desc":"以 DELETE 模式刪除所有可刪的註解比例，並重建建築用公制比例清單（1:1、1:2～1:2000，1:200 之後比例乘 0.8）。","usage":"執行 RMS-archi → 自動切到 1:1、清理並重建公制比例清單","level":5,"lt":"✅","ver":"20260222","author":"—","video":"","fas":""},{"no":1504,"file":"RMS.lsp","cmd":"RMS","cat":"系統/授權","desc":"重設公制註解比例：以 DELETE 模式清理比例清單，再建立指定的公制比例（1:1、1:2～1:2000）。","usage":"執行 RMS → 自動切到 1:1、清理並重建公制比例清單","level":5,"lt":"✅","ver":"20260222","author":"—","video":"","fas":""},{"no":1505,"file":"RMS_PRO.lsp","cmd":"RMS_PRO","cat":"系統/授權","desc":"可註解比例管理專業版：以對話框清理並重建標準公制比例，顯示公英制環境，處理外參幽靈引用，設定可存成外部 TXT 跨檔案使用。","usage":"執行 RMS_PRO → 於對話框勾選清理與重建項目、必要時按清除幽靈引用 → 按確定執行","level":8,"lt":"✅","ver":"2026 (檔案日期 2026-06-28)","author":"ChengBar (MyCAD)","video":"","fas":""},{"no":1506,"file":"road-chamfer-ui.lsp","cmd":"road-chamfer-ui、road-chamfer","cat":"修改","desc":"道路導角工具：以對話框設定導角長度、角度與是否裁線，自動以除以根號2的 CHAMFER 距離對線與聚合線導角，設定存於 INI 檔。","usage":"執行 road-chamfer-ui → 於對話框設定導角長度、角度、裁線模式 → 按確定 → 選取兩條線導角","level":7,"lt":"✅","ver":"2025-10-16","author":"ShunYi 工具鏈架構師","video":"","fas":"fas/road-chamfer-ui.fas"},{"no":1507,"file":"road-chamfer.LSP","cmd":"road-chamfer","cat":"修改","desc":"道路導角：依設定的導角長度（除以根號2換算）對線或聚合線自動導角，可選是否裁線。","usage":"執行 road-chamfer → 選取兩條線／聚合線 → 自動導角","level":5,"lt":"✅","ver":"2025-10-17 (檔案日期)","author":"—","video":"","fas":"fas/road-chamfer.fas"},{"no":1508,"file":"road-fillet-3T.LSP","cmd":"road-fillet-3T","cat":"繪圖","desc":"依序點選三點，繪製與三條線相切的圓（CIRCLE 3P TAN），用於道路三邊切圓。","usage":"執行 road-fillet-3T → 依序點選三條線的第 1、2、3 點 → 產生相切圓","level":2,"lt":"✅","ver":"2025-10-16 (檔案日期)","author":"—","video":"","fas":"fas/road-fillet-3T.fas"},{"no":1509,"file":"RoadDrain.lsp","cmd":"RoadDrain","cat":"剖面/結構","desc":"雙向拱形道路與圓角路緣石剖面外廓繪製工具：以對話框輸入車道寬、路拱坡度、路緣石尺寸與圓角半徑，自動繪出剖面外廓並標註。","usage":"執行 RoadDrain → 於對話框輸入車道寬、坡度、路緣石寬高、圓角半徑與字高 → 指定插入點 → 自動繪製剖面","level":7,"lt":"✅","ver":"2026-09-16 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/RoadDrain.fas"},{"no":1510,"file":"RoomDims.LSP","cmd":"RoomDims","cat":"面積/數量統計","desc":"選取封閉物件，以欄位（Field）標註面積與周長，依圖紙單位係數換算為 m 或 m2，並可填入房間屬性圖塊。","usage":"執行 RoomDims → 選取聚合線（或其他封閉物件）→ 選取房間圖塊 → 面積與周長欄位填入屬性","level":6,"lt":"✅","ver":"20250107","author":"chengshunyi","video":"","fas":"fas/RoomDims.fas"},{"no":1511,"file":"ROOMNAME2ATTBLOCK.lsp","cmd":"ROOMNAME2ATTBLOCK","cat":"圖塊/屬性","desc":"將選取的 TEXT／MTEXT 房間名稱取代為屬性圖塊 NA-ROOM-L，並把文字內容填入 NAME 屬性。","usage":"執行 ROOMNAME2ATTBLOCK → 選取房間名稱文字 → 自動以 NA-ROOM-L 屬性圖塊取代","level":5,"lt":"✅","ver":"19.Jun.2017","author":"Tharwat","video":"","fas":"fas/ROOMNAME2ATTBLOCK.fas"},{"no":1512,"file":"RoomNumber.LSP","cmd":"RoomNumber","cat":"圖塊/屬性","desc":"將選取的 TEXT／MTEXT 文字轉換為帶屬性的圖塊，指定要填入的屬性與替換用的屬性圖塊。","usage":"執行 RoomNumber → 選取要填入圖塊的屬性 → 選取替換用屬性圖塊 → 選取文字 → 自動轉換","level":6,"lt":"✅","ver":"copyright 2020（檔案日期 2023-11-27）","author":"Peter Jamtgaard","video":"","fas":"fas/RoomNumber.fas"},{"no":1513,"file":"RoomPline.lsp","cmd":"RoomPline","cat":"繪圖","desc":"於矩形窗選範圍內以 BOUNDARY 方式自動取得房間外廓聚合線，對話框可設定圖層名稱、顏色與自訂中心點。","usage":"執行 RoomPline → 於對話框設定圖層與顏色 → 矩形窗選範圍 → 於室內點取 → 自動產生房間聚合線","level":7,"lt":"✅","ver":"2026-06-20 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/RoomPline.fas"},{"no":1514,"file":"ROOMSPACE.lsp","cmd":"ROOMSPACE","cat":"面積/數量統計","desc":"空間性質與公設比分析系統：以對話框標記各空間的棟別、樓層、戶別、名稱與類別（專有、共用大公、共用小公、約定專用），自動換算面積、著色並繪製統計表。","usage":"執行 ROOMSPACE → 於對話框選擇棟別、樓層、戶別、名稱、類別與單位 → 選取空間聚合線 → 標註並產生統計表","level":9,"lt":"✅","ver":"2026-05-19 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/ROOMSPACE.fas"},{"no":1515,"file":"rp-text-with-blks.LSP","cmd":"rp-text-with-blks","cat":"圖塊/屬性","desc":"將選取的文字物件以指定圖塊取代，於文字位置插入圖塊並刪除原文字。","usage":"執行 rp-text-with-blks → 選取文字 → 選取或輸入圖塊名稱 → 自動置換","level":5,"lt":"✅","ver":"20231223","author":"Tharwat（2015-05-18）原作，chengshunyi 修改","video":"","fas":"fas/rp-text-with-blks.fas"},{"no":1516,"file":"RSB.lsp","cmd":"RSB","cat":"圖塊/屬性","desc":"MyCAD 圖塊重置工具：可依圖塊名稱過濾，將選取圖塊的比例、旋轉與動態狀態重設，並執行 ATTSYNC 同步屬性。","usage":"執行 RSB → 於對話框輸入圖塊名稱或按 Select > 於圖面選取 → 勾選重置項目 → 按確定","level":7,"lt":"✅","ver":"2026-08-31 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/RSB.fas"},{"no":1517,"file":"RSL.LSP","cmd":"RSL","cat":"圖塊/屬性","desc":"刪除選取圖塊中多餘的註解比例清單，解析擴充字典找出非目前比例的項目，再以 OBJECTSCALE 精確移除。","usage":"執行 RSL → 選取圖塊物件 → 自動移除多餘註解比例並顯示處理數量","level":7,"lt":"✅","ver":"2026-02-23 (檔案日期)","author":"—","video":"","fas":"fas/RSL.fas"},{"no":1518,"file":"RTC-2.LSP","cmd":"RTC-2","cat":"修改","desc":"以對話框輸入旋轉角度並選擇個別物件各自旋轉或群組以中心旋轉，對選取物件執行旋轉。","usage":"執行 RTC-2 → 於對話框輸入旋轉角度與模式 → 選取物件 → 自動旋轉","level":6,"lt":"✅","ver":"2026-03-28 (檔案日期)","author":"MyCAD","video":"","fas":"fas/RTC-2.fas"},{"no":1519,"file":"RTC.LSP","cmd":"RTC","cat":"修改","desc":"以記憶的旋轉角度（預設 90 度）將選取物件依其邊界框中心旋轉。","usage":"執行 RTC → 輸入旋轉角度（Enter 沿用上次值）→ 選取物件 → 自動繞中心旋轉","level":5,"lt":"✅","ver":"2026-03-28 (檔案日期)","author":"—","video":"","fas":"fas/RTC.fas"},{"no":1520,"file":"s-bind-d-unload.lsp","cmd":"s-bind-d-unload","cat":"圖面管理","desc":"單張圖綁定外部參考：先 detach 未載入（unload）的外參，再 bind 其餘外參，最後執行多次 purge 清理。","usage":"執行 s-bind-d-unload → 自動處理全部外參（detach unload → bind → purge）","level":6,"lt":"✅","ver":"20240503","author":"chengshunyi","video":"","fas":"fas/s-bind-d-unload.fas"},{"no":1521,"file":"s-bind.lsp","cmd":"s-bind","cat":"圖面管理","desc":"單張圖綁定外部參考，忽略未載入（unload）的外參，綁定後清理。","usage":"執行 s-bind → 自動綁定全部外參","level":5,"lt":"✅","ver":"20240502","author":"chengshunyi","video":"","fas":"fas/s-bind.fas"},{"no":1522,"file":"s-dim-2lst.lsp","cmd":"s-dim-2lst","cat":"標註","desc":"讀取指定圖層與標註型式的尺寸 override 字串（如 A1=123.00），依第一字串分組排序並計算實際長度，於指定位置產生分組計算式文字。","usage":"執行 s-dim-2lst → 自動收集 DES Dimensions 圖層的尺寸 → 點選文字放置位置 → 產生分組計算式","level":7,"lt":"✅","ver":"20231124","author":"chengshunyi","video":"","fas":"fas/s-dim-2lst.fas"},{"no":1523,"file":"s-g-m-offset.lsp","cmd":"s-g-m-offset、s-g-m-offset-lu、s-g-m-offset-lud、s-g-m-offset-ld、s-g-m-offset-ru、s-g-m-offset-rd、s-g-cp-offset-lu、s-g-cp-offset-ld、s-g-cp-offset-ru、s-g-cp-offset-rd","cat":"對齊/排列","desc":"選取物件後以基準點（左上、左下、右上、右下）為準，依水平或垂直偏移量移動或複製物件，並自動編號間距；各指令為不同基準點與移動／複製組合。","usage":"執行 s-g-m-offset-lu 等 → 輸入偏移量 → 選取物件 → 指定基準點 → 自動移動或複製","level":6,"lt":"✅","ver":"20240426（檔案日期 2026-10-17）","author":"chengshunyi","video":"","fas":"fas/s-g-m-offset.fas"},{"no":1524,"file":"S-L-div-xline.lsp","cmd":"S-L-div-xline","cat":"繪圖","desc":"選取兩點與一條線，依輸入的等分數沿線方向於「等分線」圖層以 entmake 繪製等分參考線（LINE／XLINE）。","usage":"執行 S-L-div-xline → 點選第一、二點 → 輸入等分數 → 選取要延伸的線 → 產生等分線","level":5,"lt":"✅","ver":"20240428","author":"chengshunyi","video":"","fas":"fas/S-L-div-xline.fas"},{"no":1525,"file":"s-lay-freeze.lsp","cmd":"s-lay-freeze","cat":"圖層","desc":"以過濾清單方塊列出圖層（可依顏色、凍結、鎖定、可否列印篩選），選取後批次凍結。","usage":"執行 s-lay-freeze → 在過濾清單方塊篩選並選取圖層 → 按確定 → 批次凍結","level":6,"lt":"✅","ver":"20240126","author":"chengshunyi（含 Lee Mac 清單方塊函式）","video":"","fas":"fas/s-lay-freeze.fas"},{"no":1526,"file":"s-lines-ext-l-164.LSP","cmd":"s-lines-ext-l-164","cat":"繪圖","desc":"建築物高度檢討：輸入外牆高度，依 1:3.6 公式投射參考線，於「建築物高度檢討」系列圖層建立封閉聚合線，供後續 Hatch 檢討。","usage":"執行 s-lines-ext-l-164 → 輸入外牆高度 → 選取聚合線 → 選取要投射的線 → 自動產生檢討聚合線","level":7,"lt":"✅","ver":"20250806","author":"chengshunyi","video":"","fas":"fas/s-lines-ext-l-164.fas"},{"no":1527,"file":"s-lines-ext-l.LSP","cmd":"s-lines-ext-l","cat":"繪圖","desc":"依名稱過濾選取線段，延伸取得交點並移除重複點位後，於 -REF 圖層繪製參考線。","usage":"執行 s-lines-ext-l → 依名稱過濾選線 → 選取要延伸的線 → 自動繪製參考線","level":6,"lt":"✅","ver":"20240308","author":"chengshunyi","video":"","fas":"fas/s-lines-ext-l.fas"},{"no":1528,"file":"S-obj-by-pl.LSP","cmd":"SSP、S-obj-by-pl","cat":"修改","desc":"以圓、橢圓或聚合線為邊界，選取落在其內部的物件（建立選集），供後續修改使用。","usage":"執行 SSP → 選取邊界物件（聚合線／圓／橢圓）→ 自動選取範圍內物件","level":5,"lt":"✅","ver":"2024-04-01 (檔案日期)","author":"—（網路程式，西班牙語註解）","video":"","fas":"fas/S-obj-by-pl.fas"},{"no":1529,"file":"s-pl-bylay-s-blk-cs.lsp","cmd":"s-pl-bylay-s-blk-cs","cat":"面積/數量統計","desc":"土方挖填方計算：選取聚合線圖層，找出聚合線內的高程圖塊求平均高程，與設計高程比較，乘以聚合線面積後將挖填方數量填入圖塊屬性。","usage":"執行 s-pl-bylay-s-blk-cs → 選取物件找出同圖層聚合線 → 以 CP/WP 找內部高程圖塊 → 自動計算並填入屬性","level":8,"lt":"✅","ver":"20240317","author":"chengshunyi","video":"","fas":"fas/s-pl-bylay-s-blk-cs.fas"},{"no":1530,"file":"s-pl-d-hi-2-blk.LSP","cmd":"s-pl-d-hi-2-blk","cat":"圖塊/屬性","desc":"以聚合線名稱作為設計高程，將其範圍內（CP/WP 篩選）的指定圖塊 D-HIG 屬性填入該設計高程。","usage":"執行 s-pl-d-hi-2-blk → 選取物件找出同圖層聚合線 → 選取圖塊 → 自動將設計高程填入範圍內圖塊屬性","level":7,"lt":"✅","ver":"20240319","author":"chengshunyi","video":"","fas":"fas/s-pl-d-hi-2-blk.fas"},{"no":1531,"file":"s-Plines-ext-Pl-164.LSP","cmd":"s-Plines-ext-Pl-164","cat":"繪圖","desc":"建築物高度檢討（建技規則第 164 條）：對話框輸入外牆高度（cm），依聚合線自動建立檢討圖層與投影聚合線，供高度檢討使用。","usage":"執行 s-Plines-ext-Pl-164 → 於對話框輸入建築物外牆高度 → 選取聚合線 → 自動建立 H/HL/D 圖層檢討聚合線","level":7,"lt":"✅","ver":"2025-08-07 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/s-Plines-ext-Pl-164.fas"},{"no":1532,"file":"s-projectfilesp-G.lsp","cmd":"s-projectfilesp-G","cat":"系統/授權","desc":"依圖檔 projectname 與 computersetting\\projectlist.txt，自動更新登錄機碼中的 Profile 專案檔案搜尋路徑（含第二層目錄）。","usage":"執行 s-projectfilesp-G → 自動讀取專案名稱與清單 → 更新專案搜尋路徑並顯示結果","level":8,"lt":"✅","ver":"20080301（20220716 更新，檔案日期 2023-08-10）","author":"ShunYi Studio (chengshunyi)","video":"","fas":""},{"no":1533,"file":"s-projectfilesp.lsp","cmd":"s-projectfilesp","cat":"系統/授權","desc":"依圖檔 projectname 與 computersetting\\projectlist.txt，自動更新登錄機碼中的 Profile 專案檔案搜尋路徑。","usage":"執行 s-projectfilesp → 自動讀取專案名稱與清單 → 更新專案搜尋路徑並顯示結果","level":8,"lt":"✅","ver":"20080301（20220716 更新）","author":"ShunYi Studio (chengshunyi)","video":"","fas":""},{"no":1534,"file":"s-style-ch-w.LSP","cmd":"s-style-ch-w75、s-style-ch-w75-b、s-style-ch-s、s-style-ch-w75-t、s-style-ch-w75-c、s-style-ch-w75-a","cat":"文字","desc":"以過濾清單選取文字樣式後，批次修改字體與寬度比例：w75 只改寬度 0.75，-b 手寫字加大字型，-s simplex+chineset，-t 微軟正黑體，-c Century Gothic，-a Arial。","usage":"執行 s-style-ch-w75 等指令 → 在清單方塊選取文字樣式 → 按確定 → 自動修改字體與寬度","level":7,"lt":"✅","ver":"20240126（檔案日期 2026-01-08）","author":"chengshunyi（含 Lee Mac 清單方塊函式）","video":"https://youtu.be/ckQQulYjMX4","fas":"fas/s-style-ch-w.fas"},{"no":1535,"file":"s-style-ch-w75-t.lsp","cmd":"s-style-ch-w75-t","cat":"文字","desc":"以過濾清單方塊選取文字樣式，將其字體改為微軟正黑體（msjh.ttc）並設定寬度比例 0.75。","usage":"執行 s-style-ch-w75-t → 在清單方塊選取文字樣式 → 按確定 → 自動改為微軟正黑體","level":6,"lt":"✅","ver":"2025-09-24 (檔案日期)","author":"chengshunyi（含 Lee Mac 清單方塊函式）","video":"","fas":"fas/s-style-ch-w75-t.fas"},{"no":1536,"file":"s-template-folder.lsp","cmd":"s-template-folder","cat":"系統/授權","desc":"依圖檔所在位置，自動把 computer setting 資料夾設定為 AutoCAD 樣板檔路徑並顯示完成訊息。","usage":"執行 s-template-folder → 自動設定樣板檔路徑","level":4,"lt":"✅","ver":"20080327（20220716 更新）","author":"chengshunyi","video":"","fas":""},{"no":1537,"file":"S-TEXT-CREATSTYLE.LSP","cmd":"S-TEXTs-SHX-CS、S-TEXTs-BIG-CS","cat":"文字","desc":"對目前配置內的 TEXT 依字高與插入點，逐一建立測試用文字樣式與範例字串（含英文字母與繁體中文字），分別示範 SHX 字體與大字型（Bigfont）效果。","usage":"執行 S-TEXTs-SHX-CS 或 S-TEXTs-BIG-CS → 自動建立樣式並產生預覽文字","level":6,"lt":"✅","ver":"20240101（檔案日期 2026-10-17）","author":"chengshunyi","video":"","fas":"fas/S-TEXT-CREATSTYLE.fas"},{"no":1538,"file":"s_d.LSP","cmd":"s_d","cat":"圖塊/屬性","desc":"依輸入尺寸建立門圖塊：單開門命名 s_d_寬_高_厚、雙開門 d_d_…，以聚合線繪製門扇與開啟弧並做成圖塊。","usage":"執行 s_d → 輸入門寬、高、厚度 → 指定插入點 → 自動建立門圖塊","level":6,"lt":"✅","ver":"20241110","author":"chengshunyi","video":"","fas":"fas/s_d.fas"},{"no":1539,"file":"SAC.lsp","cmd":"SAC","cat":"修改","desc":"將選取的多個物件各自以其邊界框中心為基準，按同一比例原地縮放，排除射線、建構線與鎖定圖層物件，並記住上次比例。","usage":"執行 SAC → 選取物件 → 輸入縮放倍數 (預設為上次值)","level":5,"lt":"✅","ver":"20240929","author":"Kent Cooper（2014）原作，chengshunyi 修改","video":"","fas":"fas/SAC.fas"},{"no":1540,"file":"SAE.lsp","cmd":"SAE","cat":"面積/數量統計","desc":"建築室內空間面積概算與占比分析：以對話框設定單位、比例、字高與圖層，對選取空間進行面積分類加總、著色、佔比顯示，並可輸出 CSV 與圖面表格。","usage":"執行 SAE → 於對話框設定單位、比例、圖層與小數位 → 選取空間聚合線 → 分析並輸出圖面表格或 CSV","level":9,"lt":"⚠️","ver":"2026 (檔案日期 2026-08-29)","author":"ChengBar (MyCAD)","video":"https://youtu.be/Ce6eX4i9WQU","fas":"fas/SAE.fas"},{"no":1541,"file":"SALL-BYLAYER.lsp","cmd":"SALL-BYLAYER","cat":"修改","desc":"點選一個物件後，自動選取全圖與該物件同圖層的所有物件，並顯示找到的數量。","usage":"執行 SALL-BYLAYER → 點選圖層代表物件 → 自動選取同圖層全部物件","level":3,"lt":"✅","ver":"20210623","author":"CHENGBAR","video":"","fas":"fas/SALL-BYLAYER.fas"},{"no":1542,"file":"SAMPLE1.LSP","cmd":"SAMPLE1","cat":"圖面管理","desc":"MyCAD 批次處理對話框範例：選取檔案路徑後，批次對 DWG 執行 BIND、PURGE、關閉圖層或凍結圖層等功能選項。","usage":"執行 SAMPLE1 → 於對話框選取檔案路徑與功能選項 → 按確定批次處理","level":6,"lt":"✅","ver":"20250122","author":"chengshunyi","video":"","fas":"fas/SAMPLE1.fas"},{"no":1543,"file":"SAR.lsp","cmd":"SAR","cat":"圖塊/屬性","desc":"選取帶屬性的圖塊，輸入新的屬性旋轉角度，批次將圖塊內屬性旋轉到指定角度，可依屬性名稱過濾。","usage":"執行 SAR → 選取帶屬性圖塊 → 輸入新的屬性旋轉角度","level":4,"lt":"✅","ver":"20220716","author":"—","video":"https://youtu.be/rZkmSXkrzA4","fas":"fas/SAR.fas"},{"no":1544,"file":"Save2Doc.lsp","cmd":"Save2Doc、SD","cat":"轉檔/匯出入","desc":"選取 TEXT／MTEXT 後，以 Word COM 啟動 Microsoft Word，將文字內容匯出至選取或新建的 Word 文件。","usage":"執行 Save2Doc（或 SD）→ 選取文字 → 選擇 Word 文件（或預設以圖檔名建立）→ 自動匯出","level":8,"lt":"❌","ver":"CADALYST 08/05 Tip 2053（檔案日期 2025-06-29）","author":"Andrzej Gumula (CADALYST)","video":"","fas":"fas/Save2Doc.fas"},{"no":1545,"file":"SAVEAS2LOCAL-DY.lsp","cmd":"SAVEAS2LOCAL-DY","cat":"圖面管理","desc":"選取輸出資料夾後，將目前所有開啟的圖檔另存到該資料夾（資料夾不存在時自動建立）。","usage":"執行 SAVEAS2LOCAL-DY → 選取輸出資料夾 → 自動將所有開啟圖檔另存","level":6,"lt":"❌","ver":"20220520（20220716 更新）","author":"chengshunyi","video":"","fas":"fas/SAVEAS2LOCAL-DY.fas"},{"no":1546,"file":"SAVEAS2LOCAL-I.lsp","cmd":"（無，副程式庫）","cat":"圖面管理","desc":"提供函式 (SAVEAS2LOCAL-I 路徑)，將所有開啟的圖檔另存到傳入的資料夾路徑。","usage":"由其他程式或指令列呼叫，例如 (SAVEAS2LOCAL-I \"D:\\\\SAVEAS FILES\\\\\")","level":4,"lt":"✅","ver":"20220520（20220716 更新）","author":"chengshunyi","video":"","fas":"fas/SAVEAS2LOCAL-I.fas"},{"no":1547,"file":"SAVEAS2LOCAL.lsp","cmd":"SAVEAS2LOCAL","cat":"圖面管理","desc":"將目前所有開啟的圖檔一次另存到固定資料夾 D:\\SAVEAS FILES。","usage":"執行 SAVEAS2LOCAL → 自動將所有開啟圖檔另存並顯示完成訊息","level":4,"lt":"✅","ver":"20220520（20220716 更新）","author":"chengshunyi","video":"","fas":"fas/SAVEAS2LOCAL.fas"},{"no":1548,"file":"SB.lsp","cmd":"SB","cat":"繪圖","desc":"SmartBoundary：在封閉空間內點取一點，以射線掃描與幾何交點排序法找出邊界，產生封閉聚合線；失敗時以 BPOLY 保底，對話框可設射線角度間距、破口容差與過濾圖層。","usage":"執行 SB → 於對話框設定射線角度間距、容差與過濾圖層 → 於空間內點取一點 → 自動產生封閉聚合線","level":8,"lt":"✅","ver":"2026-03-21 (檔案日期)","author":"MyCAD","video":"","fas":"fas/SB.fas"},{"no":1549,"file":"sbx.lsp","cmd":"sbx","cat":"圖塊/屬性","desc":"選取主線與多條相交線，在其交點處自動插入圖塊（SBblock）。","usage":"執行 sbx → 選取主線 → 選取交叉線 → 自動於交點插入圖塊","level":6,"lt":"✅","ver":"2022-12-04 (檔案日期)","author":"—","video":"","fas":"fas/sbx.fas"},{"no":1550,"file":"scal.lsp","cmd":"scal","cat":"系統/授權","desc":"輸入圖面比例後，同時設定 LTSCALE、DIMSCALE 等比例系統變數。","usage":"執行 scal → 輸入比例 → 自動設定線型比例與標註比例","level":1,"lt":"✅","ver":"88.10.07（20220716 更新）","author":"—","video":"","fas":""},{"no":1551,"file":"scale.lsp","cmd":"scale","cat":"系統/授權","desc":"輸入圖面比例後，同時設定 LTSCALE、DIMSCALE 等比例系統變數。","usage":"執行 scale → 輸入比例 → 自動設定線型比例與標註比例","level":1,"lt":"✅","ver":"88.10.07（20220716 更新）","author":"—","video":"","fas":""},{"no":1552,"file":"scalelistreset.lsp","cmd":"RES、SCE","cat":"系統/授權","desc":"重設圖面比例清單：先重設、再逐一刪除所有現存比例，最後安裝新的比例清單；SCE 為 ScaleListEdit 的縮寫。","usage":"執行 RES → 自動重設並重建比例清單；或執行 SCE 開啟比例清單編輯","level":4,"lt":"✅","ver":"v1.6（20250710）","author":"chengshunyi","video":"","fas":""},{"no":1553,"file":"screw-LT.LSP","cmd":"screw-LT","cat":"圖塊/屬性","desc":"快速插入螺絲對應動態圖塊（LT 版）：於支援路徑尋找 my-sample.dwg（找不到時手動指定並記憶），以對話框選擇螺絲類型後純 VLA 插入。","usage":"執行 screw-LT → 於對話框選擇螺絲類型 → 指定插入點 → 自動插入動態圖塊","level":7,"lt":"✅","ver":"2015.10.08（Updated 2026.06.21）","author":"ChengBar (MyCAD)","video":"","fas":"fas/screw-LT.fas"},{"no":1554,"file":"screw.LSP","cmd":"screw","cat":"圖塊/屬性","desc":"快速插入螺絲對應動態圖塊：以對話框選擇平頭、圓頭、SUS 自攻、自鉸螺絲、螺栓或膨脹螺栓，以 ObjectDBX 從 my-sample.dwg 匯入圖塊定義後以 vla-InsertBlock 插入。","usage":"執行 screw → 於對話框選擇螺絲類型 → 指定插入點 → 自動插入圖塊","level":7,"lt":"❌","ver":"2015.10.8（Updated 2026.06.21）","author":"minture 原作，MyCAD 修改","video":"","fas":"fas/screw.fas"},{"no":1555,"file":"screw4-LT.LSP","cmd":"screw4-LT","cat":"圖塊/屬性","desc":"自鉸螺絲自動化插入（LT 版）：對話框選擇 M4、M5 自鉸螺絲或 M6、M8 六角頭尖尾自鉸螺栓，以 vla-InsertBlock 載入外部 DWG 取得圖塊定義後插入並刪除暫時物件。","usage":"執行 screw4-LT → 於對話框選擇螺絲尺寸 → 指定插入點 → 自動插入動態圖塊","level":7,"lt":"✅","ver":"2026 (C) ChengBar（檔案日期 2026-06-21）","author":"ChengBar (MyCAD)","video":"","fas":"fas/screw4-LT.fas"},{"no":1556,"file":"screw4.LSP","cmd":"screw4","cat":"圖塊/屬性","desc":"自鉸螺絲自動化插入：對話框選擇螺絲尺寸，以 ObjectDBX 匯入外部圖塊後高效插入，支援支援路徑自動搜尋。","usage":"執行 screw4 → 於對話框選擇螺絲尺寸（M4／M5／M6／M8）→ 指定插入點 → 自動插入圖塊","level":7,"lt":"❌","ver":"2026 (C) ChengBar（檔案日期 2026-06-21）","author":"ChengBar (MyCAD)","video":"","fas":"fas/screw4.fas"},{"no":1557,"file":"SearchLspKeyword.lsp","cmd":"SearchLspKeyword","cat":"系統/授權","desc":"搜尋指定資料夾內所有 .lsp 檔，檢查是否包含關鍵字（預設 author_ymd_t），將符合的檔案清單輸出到指定 txt 檔，對話框附 MyCAD Logo 與幻燈片。","usage":"執行 SearchLspKeyword → 於對話框輸入目錄、關鍵字與輸出檔 → 按確定 → 產生結果 txt","level":7,"lt":"✅","ver":"V1.9 (除錯版，檔案日期 2026-10-17)","author":"MyCAD","video":"","fas":""},{"no":1558,"file":"SEC-1.LSP","cmd":"sec-1","cat":"剖面/結構","desc":"於指定 A、B 兩點畫剖面線並於 C 點標示剖面方向，輸入圖名與圖號後插入剖面符號，使用 dim-sec 圖層。","usage":"執行 sec-1 → 指定 A、B 點 → 指定 C 點 → 輸入圖名與圖號 → 自動畫剖面線與符號","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/SEC-1.fas"},{"no":1559,"file":"SEC-2.LSP","cmd":"sec-2","cat":"剖面/結構","desc":"於指定 A、B 兩點畫剖面線並於 C 點標示剖面方向，輸入圖名與圖號後插入剖面符號，使用 dim-sec 圖層。","usage":"執行 sec-2 → 指定 A、B 點 → 指定 C 點 → 輸入圖名與圖號 → 自動畫剖面線與符號","level":4,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/SEC-2.fas"},{"no":1560,"file":"sec-i.lsp","cmd":"sec-i","cat":"剖面/結構","desc":"整合 sec-1、sec-2 等剖面符號：以對話框圖像選擇剖面樣式並輸入圖號、圖名與詳圖，自動建立標準圖層並繪製剖面線與符號圖塊。","usage":"執行 sec-i → 於對話框點選剖面樣式並輸入圖名、圖號 → 指定剖面線位置 → 自動繪製","level":7,"lt":"✅","ver":"20241110","author":"chengshunyi","video":"","fas":"fas/sec-i.fas"},{"no":1561,"file":"sec-mark-ui.lsp","cmd":"sec-mark-ui、sec-insert-sl、sec-insert-sw、sec-insert-sp、sec-insert","cat":"剖面/結構","desc":"MyCAD 剖面線符號工具：以對話框選擇縱橫剖面、外牆剖面或局部剖面，依比例與端點長度插入對應剖面符號圖塊，可設跳線選項。","usage":"執行 sec-mark-ui → 於對話框選擇剖面類型（可看幻燈片預覽）→ 指定剖面線位置 → 自動插入符號圖塊","level":7,"lt":"✅","ver":"2025-10-07 (檔案日期)","author":"MyCAD","video":"","fas":"fas/sec-mark-ui.fas"},{"no":1562,"file":"SEC-MARK.LSP","cmd":"sec-mark","cat":"剖面/結構","desc":"指定兩點繪製剖面標示線，兩端插入剖面符號圖塊，圖層為 SML-4（色 12）。","usage":"執行 sec-mark → 點選第一點 → 點選第二點 → 自動畫剖面標示線並插入符號","level":5,"lt":"✅","ver":"85.06.14（20240218 修改）","author":"—","video":"","fas":"fas/SEC-MARK.fas"},{"no":1563,"file":"SEC-MRK1.LSP","cmd":"sec-mrk1","cat":"剖面/結構","desc":"指定兩點繪製剖面標示線並於兩端依比例插入符號，圖層為 SML-4（色 12），為 sec-mark 的另一種符號樣式。","usage":"執行 sec-mrk1 → 點選第一點 → 點選第二點 → 自動畫剖面標示線與符號","level":5,"lt":"✅","ver":"86.08.29（20240218 修改）","author":"—","video":"","fas":"fas/SEC-MRK1.fas"},{"no":1564,"file":"SEC-S2TF.LSP","cmd":"sec-s2tf","cat":"剖面/結構","desc":"繪製樓梯剖面（S2TF 型）：輸入插入點、樓層高、梯深、兩段階數、欄杆與扶手高度，自動畫樓梯、欄杆扶手並陣列踏階。","usage":"執行 sec-s2tf → 指定樓梯插入點 → 依序輸入樓層高、梯深、階數、欄杆高、扶手高 → 自動畫樓梯剖面","level":7,"lt":"✅","ver":"20220716","author":"—","video":"","fas":"fas/SEC-S2TF.fas"},{"no":1565,"file":"SEC-ST2.LSP","cmd":"sec-st2","cat":"剖面/結構","desc":"繪製樓梯剖面：輸入插入點、樓層高、梯深、階數、欄杆與扶手高，自動畫兩段式樓梯、欄杆與扶手並陣列踏階。","usage":"執行 sec-st2 → 指定樓梯插入點 → 依序輸入樓層高、梯深、階數、欄杆高、扶手高 → 自動畫樓梯剖面","level":7,"lt":"✅","ver":"84.4.11 / 84.4.14","author":"—","video":"","fas":"fas/SEC-ST2.fas"},{"no":1566,"file":"SEC-ST2T.LSP","cmd":"sec-st2t","cat":"剖面/結構","desc":"樓梯剖面的對話框版：於 stair.dcl 對話框輸入樓層高、階數、欄杆與扶手高，自動畫樓梯剖面並判斷圖面單位為 mm 或 cm，含文字標註。","usage":"執行 sec-st2t → 於對話框輸入參數 → 指定樓梯基點 → 自動畫樓梯剖面","level":7,"lt":"✅","ver":"84.4.11 / 84.4.14 / 84.7.10","author":"—","video":"","fas":"fas/SEC-ST2T.fas"},{"no":1567,"file":"SEC-ST3T.LSP","cmd":"sec-st3t","cat":"剖面/結構","desc":"樓梯剖面三階段版：於 stair3.dcl 對話框設定參數，自動畫 RC 或鋼梯樓梯、側版、欄杆、兩層扶手並標註斜邊與尺寸，依作業系統語言切換字型。","usage":"執行 sec-st3t → 於對話框輸入樓層高、階數、欄杆高、扶手高等 → 指定基點 → 自動畫樓梯剖面並標註","level":8,"lt":"✅","ver":"2008.06.23","author":"chengshunyi","video":"","fas":"fas/SEC-ST3T.fas"},{"no":1568,"file":"sec_cut_fill-ui.LSP","cmd":"sec_cut_fill-ui","cat":"剖面/結構","desc":"計算兩條聚合線間的挖填方面積與體積，對話框輸入字高、繪圖比例與計算深度，以 MTEXT 輸出詳細計算式（體積計算與計算式版）。","usage":"執行 sec_cut_fill-ui → 於對話框輸入字高、比例、深度 → 選取兩條聚合線 → 標示挖填方面積與體積計算式","level":8,"lt":"✅","ver":"2026-01-28 (檔案日期)","author":"ymg（SEC-CUT-FILL）","video":"","fas":"fas/sec_cut_fill-ui.fas"},{"no":1569,"file":"sec_cut_fill.lsp","cmd":"sec_cut_fill","cat":"剖面/結構","desc":"計算兩條聚合線間的挖填方面積與體積，對話框含繪圖單位係數（mm/cm/m），並記憶上次輸入，結果以多行 TEXT 輸出。","usage":"執行 sec_cut_fill → 於對話框輸入字高、比例、單位、計算深度 → 選取兩條聚合線 → 標示挖填方面積與體積","level":8,"lt":"✅","ver":"2026-01-28 (檔案日期)","author":"ymg（SEC-CUT-FILL）","video":"","fas":"fas/sec_cut_fill.fas"},{"no":1570,"file":"segment-mid.lsp","cmd":"segment-mid","cat":"繪圖","desc":"選取線、聚合線、2D／3D 聚合線或雲形線，於每個線段的中點自動產生 POINT 點。","usage":"執行 segment-mid → 選取物件 → 自動於各線段中點加點","level":5,"lt":"✅","ver":"20241127","author":"chengshunyi","video":"","fas":"fas/segment-mid.fas"},{"no":1571,"file":"sel-dim-w.lsp","cmd":"sel-dim-w","cat":"標註","desc":"選取目前配置中位於 defpoints 圖層的所有尺寸標註物件。","usage":"執行 sel-dim-w → 自動選取 defpoints 圖層上的尺寸","level":1,"lt":"✅","ver":"20221004","author":"chengshunyi","video":"","fas":"fas/sel-dim-w.fas"},{"no":1572,"file":"sel-obj-creat-pl-ui.lsp","cmd":"sel-obj-creat-pl-ui","cat":"圖層","desc":"顯示對話框列出圖層清單供選擇，記住上次選用的圖層，作為「選物件產生封閉聚合線」功能的圖層選擇介面。","usage":"執行 sel-obj-creat-pl-ui → 於對話框從下拉清單選取圖層 → 按確定","level":5,"lt":"✅","ver":"2025-08-10 (檔案日期)","author":"MyCAD","video":"","fas":"fas/sel-obj-creat-pl-ui.fas"},{"no":1573,"file":"sel-obj-creat-pl.lsp","cmd":"SOCPL、sel-obj-creat-pl-ui、sel-obj-creat-pl","cat":"繪圖","desc":"選取多個線段物件，建立封閉聚合線：對話框選擇生成圖層（含幻燈片預覽），以 EXPLODE/PEDIT 連接成封閉聚合線。","usage":"執行 SOCPL → 於對話框選擇生成圖層 → 選取多個線物件 → 自動產生封閉聚合線","level":8,"lt":"✅","ver":"20250822（原 Stefan M. v1.01 2014、v1.03 2018）","author":"Stefan M. 原作，chengshunyi 修改","video":"https://youtu.be/O8Sg5y2p-K8","fas":"fas/sel-obj-creat-pl.fas"},{"no":1574,"file":"sel-obj-entlay-chlay.lsp","cmd":"sel-obj-entlay-chlay","cat":"圖層","desc":"選取物件後依物件類別與圖層過濾，將符合的物件批次改到指定圖層，用於整理協力廠商或其他來源圖檔，並可過濾外參圖層。","usage":"執行 sel-obj-entlay-chlay → 選取物件 → 在清單對話框選取物件類別與圖層 → 選取目標圖層 → 自動修改圖層","level":7,"lt":"✅","ver":"20241115","author":"chengshunyi（含 Lee Mac 清單方塊函式）","video":"","fas":"fas/sel-obj-entlay-chlay.fas"},{"no":1575,"file":"sel-objs-ro.lsp","cmd":"DBB、DBBM、rotate-obj-center、bbc、ssc","cat":"修改","desc":"多選物件工具集：DBB 為每個物件畫邊界矩形，DBBM 為多個物件共畫一個外框，rotate-obj-center 為各物件原地轉 90 度，bbc、ssc 為相關輔助指令。","usage":"執行 DBB 或 DBBM → 選取物件 → 自動畫外框；或執行 rotate-obj-center → 選取物件 → 自動各自旋轉","level":6,"lt":"✅","ver":"20240426","author":"chengshunyi（含 Kent Cooper DBB/DBBM 程式碼）","video":"","fas":"fas/sel-objs-ro.fas"},{"no":1576,"file":"sel-pl-area2excel.lsp","cmd":"sel-pl-area2excel","cat":"轉檔/匯出入","desc":"連續選取聚合線，換算為平方公尺後輸出面積，可寫入 CSV，或以 Excel COM 開啟並填入 Excel 工作表（棟別、樓層、文字標示與面積）。","usage":"執行 sel-pl-area2excel → 輸入棟別與樓層 → 連續選取聚合線 → 面積寫入 CSV／Excel","level":8,"lt":"❌","ver":"20220716（檔案日期 2025-03-08）","author":"chengshunyi","video":"","fas":"fas/sel-pl-area2excel.fas"},{"no":1577,"file":"sel-pl-bylayer-sel-tree.lsp","cmd":"sel-pl-bylayer-sel-tree","cat":"面積/數量統計","desc":"選取某圖層的聚合線，找出線內的喬木圖塊並計算數量與最小樹穴面積，標註喬木間距與檢討結果，供綠建築計算使用。","usage":"執行 sel-pl-bylayer-sel-tree → 選取目標圖層上的聚合線 → 自動計數內部喬木並標註數量與樹穴面積","level":7,"lt":"✅","ver":"20240419","author":"chengshunyi","video":"","fas":"fas/sel-pl-bylayer-sel-tree.fas"},{"no":1578,"file":"SEL-PL-SEL-BLK.lsp","cmd":"PLWto10、sel-pl-bylayer-sel-blk-ap","cat":"圖塊/屬性","desc":"依圖層選取聚合線，辨識內部目標圖塊，把聚合線面積(AREA)與周長(LEN)寫入圖塊屬性；PLWto10 將該圖層聚合線寬度設為10。","usage":"執行 sel-pl-bylayer-sel-blk-ap → 選聚合線 → 選目標圖塊 → 於對話框選屬性 Tag 與單位 → 確定寫入","level":8,"lt":"⚠️","ver":"v3.0 2026/10/05","author":"Chengshunyi / ChengBar (MyCAD)","video":"","fas":"fas/SEL-PL-SEL-BLK.fas"},{"no":1579,"file":"sel-pl-sel-tree-la.lsp","cmd":"sel-pl-sel-tree-la、msv-u、msv-d","cat":"面積/數量統計","desc":"自由選取聚合線並依圖層判斷圖塊數量，以引線加多行文字框標註喬木數量與樹穴面積檢討；msv-u/msv-d 控制標註向上或向下。","usage":"執行 sel-pl-sel-tree-la → 選取聚合線 → 自動計數樹木 → 點選引線位置標註；msv-u/msv-d 切換方向","level":8,"lt":"⚠️","ver":"20240501","author":"chengshunyi","video":"","fas":"fas/sel-pl-sel-tree-la.fas"},{"no":1580,"file":"sel-pl-sel-tree.lsp","cmd":"sel-pl-sel-tree","cat":"面積/數量統計","desc":"自由選取聚合線，統計線內喬木圖塊數量並以每棵4m²檢討最小樹穴面積，標註 OK 與否，並標喬木間距尺寸。","usage":"執行 sel-pl-sel-tree → 選取聚合線 → 自動計算並標註喬木數量與樹穴面積","level":7,"lt":"✅","ver":"20240421","author":"chengshunyi","video":"","fas":"fas/sel-pl-sel-tree.fas"},{"no":1581,"file":"sel-pline-2.lsp","cmd":"sel-pline-2","cat":"繪圖","desc":"選取聚合線並將其改到 defpoints 圖層，顏色設為 2 黃色。","usage":"執行 sel-pline-2 → 選取聚合線 → 自動改圖層與顏色","level":1,"lt":"✅","ver":"20221002","author":"—","video":"","fas":"fas/sel-pline-2.fas"},{"no":1582,"file":"sel-pline.lsp","cmd":"sel-pline","cat":"繪圖","desc":"選取聚合線並將其改到 defpoints 圖層。","usage":"執行 sel-pline → 選取聚合線 → 自動改圖層","level":1,"lt":"✅","ver":"20221002","author":"—","video":"","fas":"fas/sel-pline.fas"},{"no":1583,"file":"select-pline-offset-2side.lsp","cmd":"select-pline-offset-2side","cat":"修改","desc":"選取封閉聚合線後向內外兩側偏移（0.5 或 2.0），分別放到指定圖層並產生 ANSI31 填充，做出雙邊牆或框型。","usage":"執行 select-pline-offset-2side → 選擇偏移值 1 或 2 → 選取聚合線 → 自動偏移並填充","level":4,"lt":"✅","ver":"20221207","author":"chengshunyi","video":"","fas":"fas/select-pline-offset-2side.fas"},{"no":1584,"file":"SET-ATT-SIZE-W.LSP","cmd":"SET-ATT-SIZE-W","cat":"圖塊/屬性","desc":"點選一個屬性後，以對話框設定字高與寬度比例，並自動掃描全圖同名圖塊與標籤批次修改。","usage":"執行 SET-ATT-SIZE-W → 點選屬性 → 在對話框輸入字高與寬度比例 → 確定，全圖同名圖塊更新","level":6,"lt":"✅","ver":"20260319","author":"chengshunyi","video":"","fas":"fas/SET-ATT-SIZE-W.fas"},{"no":1585,"file":"Set-Blk-T-To0.LSP","cmd":"Set-Blk-T-To0、ZeroAll-h-0、ZeroAll-Blk-T、ZeroAll-Ent-T","cat":"修改","desc":"將圖塊定義或模型空間物件的 THICKNESS 厚度批次設為 0；可只處理點選圖塊、全部圖塊定義或模型空間物件。","usage":"執行 Set-Blk-T-To0 → 點選圖塊參考 → 自動清除厚度；或執行 ZeroAll-Blk-T / ZeroAll-Ent-T 全圖處理","level":5,"lt":"✅","ver":"20251016","author":"chengshunyi（JAHAA 客製）","video":"https://youtu.be/NGWQJXSiE68","fas":"fas/Set-Blk-T-To0.fas"},{"no":1586,"file":"set-car-cat.lsp","cmd":"set-car-cat-W、set-car-cat","cat":"圖塊/屬性","desc":"讀取 CAR-CAT.txt 的車位分類（法定、自設、獎勵、其它），以清單對話框選擇後改寫車位圖塊的 CAT1 屬性。","usage":"執行 set-car-cat → 選取車位圖塊(預設全部) → 在清單選分類 → 確定寫入 CAT1","level":6,"lt":"✅","ver":"20250328","author":"chengshunyi","video":"https://youtu.be/Q8QDs0znZ9A","fas":"fas/set-car-cat.fas"},{"no":1587,"file":"set-clayer-byobj-ON.LSP","cmd":"set-clayer-byobj-ON、Layeroff","cat":"圖層","desc":"點選物件把其圖層設為目前層並開啟，（含圖塊／外參內的圖層）；Layeroff 關閉除 0 層以外所有圖層。","usage":"執行 set-clayer-byobj-ON → 點選物件 → 該圖層設為目前層並開啟；Layeroff 關閉全部其他圖層","level":5,"lt":"✅","ver":"20250319","author":"chengshunyi","video":"","fas":"fas/set-clayer-byobj-ON.fas"},{"no":1588,"file":"set-clayer-byobj-thaw.LSP","cmd":"set-clayer-byobj-THAW、Layerfreeze","cat":"圖層","desc":"點選物件把其圖層設為目前層並解凍（含圖塊／外參內圖層）；Layerfreeze 凍結除 0 層以外所有圖層。","usage":"執行 set-clayer-byobj-THAW → 點選物件 → 圖層解凍並設為目前層；Layerfreeze 凍結其餘圖層","level":5,"lt":"✅","ver":"20241115","author":"chengshunyi","video":"","fas":"fas/set-clayer-byobj-thaw.fas"},{"no":1589,"file":"set-clayer-byobj.LSP","cmd":"set-clayer-byobj","cat":"圖層","desc":"點選物件，將其所在圖層設為目前圖層，必要時以 entmake 建立缺少的圖層。","usage":"執行 set-clayer-byobj → 點選物件 → 該圖層成為目前層","level":2,"lt":"✅","ver":"20141110","author":"chengshunyi","video":"","fas":"fas/set-clayer-byobj.fas"},{"no":1590,"file":"set-dim-lay.LSP","cmd":"set-dim-lay","cat":"圖層","desc":"以可過濾的清單對話框選擇尺寸標註使用的圖層並記錄成環境設定，供其他標註程式取用。","usage":"執行 set-dim-lay → 在清單對話框過濾並選擇圖層 → 確定儲存設定","level":6,"lt":"✅","ver":"20220716 更新(檔頭)","author":"Lee Mac（Filtered List Box）、chengshunyi","video":"","fas":"fas/set-dim-lay.fas"},{"no":1591,"file":"set-dwg-pus.lsp","cmd":"set-dwg-pus","cat":"圖面管理","desc":"讀取 setpus.ini 與圖面自訂屬性的圖紙單位比例系數，依紙張尺寸建立外框與內框矩形並標示比例。","usage":"執行 set-dwg-pus → 在對話框選圖紙、單位、比例 → 確定自動繪製外框內框","level":8,"lt":"✅","ver":"2025-09-14 (檔案日期)","author":"Lee Mac（字串分割）、chengshunyi","video":"","fas":"fas/set-dwg-pus.fas"},{"no":1592,"file":"set-go-zoom.lsp","cmd":"SETZ、GOZ","cat":"圖面管理","desc":"SETZ 以對話框儲存目前視窗或框選範圍的縮放位置到 TXT；GOZ 讀取記錄快速跳回該縮放範圍。","usage":"執行 SETZ → 選目前視窗或框選範圍 → 確定儲存；之後執行 GOZ 即跳回","level":6,"lt":"✅","ver":"2026-02-23 (檔案日期)","author":"MyCAD","video":"","fas":"fas/set-go-zoom.fas"},{"no":1593,"file":"set-go-zoom5.LSP","cmd":"SETZ、GOZ","cat":"圖面管理","desc":"SETZ 以對話框將視窗範圍存入記憶組 A～E 五組之一；GOZ 跳回指定記憶組的縮放範圍。","usage":"執行 SETZ → 選記憶組 A~E 與定義方式 → 確定；之後 GOZ 選組別跳轉","level":6,"lt":"✅","ver":"2026-02-23 (檔案日期)","author":"MyCAD","video":"","fas":"fas/set-go-zoom5.fas"},{"no":1594,"file":"Set-la-transparency.lsp","cmd":"Set-la-transparency、Set-la-transparency-0","cat":"圖層","desc":"輸入透明度數值，批次設定圖層透明度並開啟透明度顯示；-0 版重設為 0。","usage":"執行 Set-la-transparency → 輸入透明度值 → 全部圖層套用","level":2,"lt":"✅","ver":"20220716更新","author":"chengshunyi","video":"","fas":"fas/Set-la-transparency.fas"},{"no":1595,"file":"Set-layout-TextW75.lsp","cmd":"Set-layout-TextW75","cat":"文字","desc":"在各配置空間以視窗選取範圍，將內部 TEXT、ATTRIB、ATTDEF 的寬度比例統一設為 0.75。","usage":"執行 Set-layout-TextW75 → 指定視窗角點 → 自動逐一配置處理","level":4,"lt":"✅","ver":"2025-11-20 (檔案日期)","author":"—","video":"","fas":"fas/Set-layout-TextW75.fas"},{"no":1596,"file":"set-layout-xref-var.LSP","cmd":"set-layout-xref-var","cat":"系統/授權","desc":"批次設定一組效能相關系統變數（XLOADCTL、WHIPTHREAD、SAVEFIDELITY、ISAVEPERCENT、GRIPOBJLIMIT 等）以優化大圖開啟與外參。","usage":"執行 set-layout-xref-var → 自動設定並列印各變數值","level":2,"lt":"✅","ver":"20240629","author":"chengshunyi","video":"","fas":""},{"no":1597,"file":"set-menu.LSP","cmd":"set-menu","cat":"系統/授權","desc":"自動從網路磁碟 O: 以 xcopy 同步 JJP2006L 的選單、資料庫與驅動程式到本機 C:，並記錄更新結果。","usage":"執行 set-menu → 自動檢查 O: 連線並複製檔案","level":3,"lt":"❌","ver":"20081024","author":"Cheng Shun-Yi","video":"","fas":""},{"no":1598,"file":"Set-ML-SD.LSP","cmd":"Set-ML-SD","cat":"標註","desc":"將圖面所有多重引線的行距設為固定距離（1.5 倍字高），並輸出處理記錄。","usage":"執行 Set-ML-SD（或 smlsd）→ 自動處理所有 MLeader","level":5,"lt":"✅","ver":"2025-11-26 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/Set-ML-SD.fas"},{"no":1599,"file":"Set-ML-Sty-UI.lsp","cmd":"Set-ML-Sty-UI、ShowMLeaderStyles","cat":"標註","desc":"以對話框設定比例、單位、箭頭、字高、顏色、Dogleg 等參數，建立或批次建立多重引線樣式，設定可存成 INI。","usage":"執行 Set-ML-Sty-UI → 對話框選比例單位箭頭字高顏色 → 確定或按批次建立全部","level":8,"lt":"⚠️","ver":"2026-02-27 (檔案日期)","author":"MyCAD","video":"","fas":"fas/Set-ML-Sty-UI.fas"},{"no":1600,"file":"SET-MLeaders.lsp","cmd":"Test、SET-MLeaders","cat":"標註","desc":"以參數清單建立多重引線樣式（文字樣式、字高、箭頭大小與符號、引線間隔等，預設1:100），並設為目前樣式。","usage":"執行 SET-MLeaders → 自動建立 NewMLeader2 樣式；Test 為範例呼叫","level":5,"lt":"⚠️","ver":"2024-10-13 (檔案日期)","author":"網路程式 (CreateMLeaderStyle)、chengshunyi 改寫","video":"","fas":"fas/SET-MLeaders.fas"},{"no":1601,"file":"set-plot2pdf-folder.lsp","cmd":"set-plot2pdf-folder","cat":"出圖/列印","desc":"在使用者文件夾下建立 My-PDF 資料夾並將 PLOTTOFILEPATH 設為該路徑，作為 PDF 出圖預設輸出位置。","usage":"執行 set-plot2pdf-folder → 自動建立資料夾並設定出圖路徑","level":3,"lt":"✅","ver":"20250613","author":"chengshunyi、Lee Mac（MakeDirectory）","video":"","fas":"fas/set-plot2pdf-folder.fas"},{"no":1602,"file":"set-ps-by-dwg.LSP","cmd":"set-ps-by-dwg","cat":"出圖/列印","desc":"刪除現有配置與頁面設定，自範本 JH-PS.dwg 匯入 JH-A3 等頁面設定並套用到各配置，依圖紙單位出圖。","usage":"執行 set-ps-by-dwg → 自動清除頁面設定並從範本匯入套用","level":5,"lt":"✅","ver":"20250927","author":"chengshunyi（JAHAA 客製）","video":"https://youtu.be/VoJ8gOrPQjA","fas":"fas/set-ps-by-dwg.fas"},{"no":1603,"file":"set-ps-by-sca.LSP","cmd":"set-ps-by-sca","cat":"出圖/列印","desc":"依各配置視埠的出圖比例，自 my-pagesetup.dwg 匯入並套用 A1/A3 DWG2PDF 頁面設定與對應筆寬（比例大於等於150用 A3 筆寬）。","usage":"執行 set-ps-by-sca → 自動讀視埠比例並套用對應頁面設定","level":6,"lt":"✅","ver":"20250215","author":"chengshunyi","video":"","fas":"fas/set-ps-by-sca.fas"},{"no":1604,"file":"set-pus-ui.lsp","cmd":"set-pus-ui","cat":"圖面管理","desc":"以對話框設定圖紙、單位與比例系數並存入圖面自訂屬性，可繪製外框、內框、尺寸檢查與插入圖框。","usage":"執行 set-pus-ui → 在對話框選圖紙尺寸、單位、比例 → 勾選外框/內框/尺寸 → 確定","level":9,"lt":"✅","ver":"20250111","author":"chengshunyi（MyCAD）","video":"https://youtu.be/dijsVbJ9WKM","fas":"fas/set-pus-ui.fas"},{"no":1605,"file":"set-pus.lsp","cmd":"set-pus","cat":"圖面管理","desc":"圖紙單位比例設定主程式：對話框設定圖紙、單位、比例，存入圖面屬性並可繪製外內框、尺寸，支援試用計次與 ZWCAD。","usage":"執行 set-pus → 對話框設定圖紙/單位/比例 → 勾選外框內框尺寸 → 確定","level":9,"lt":"✅","ver":"20250111","author":"chengshunyi（MyCAD）","video":"","fas":"fas/set-pus.fas"},{"no":1606,"file":"set-slide-size.lsp","cmd":"set-slide-size、set-slide-size8、set-slide-size2","cat":"系統/授權","desc":"調整 AutoCAD 視窗大小至 400x270/400x300 以製作幻燈片，並可還原原尺寸。","usage":"執行 set-slide-size → 視窗縮為指定大小；用 R 還原","level":3,"lt":"✅","ver":"2024-11-14 (檔案日期)","author":"—","video":"","fas":""},{"no":1607,"file":"set-slide-to-center.lsp","cmd":"set-slide-to-center","cat":"系統/授權","desc":"以 ZOOM 微調視窗上下位置，用於幻燈片製作時置中；檔頭註明測試後應不需要。","usage":"執行 set-slide-to-center → 視窗自動平移","level":1,"lt":"✅","ver":"20241114","author":"—","video":"","fas":""},{"no":1608,"file":"set-sysvar.lsp","cmd":"set-sysvar、my-set-sysvar","cat":"系統/授權","desc":"一次設定 AutoCAD 優化系統變數（關閉選取預覽、動態輸入、快速屬性、UCS 偵測、外框顯示等），提升效能與操作習慣。","usage":"執行 set-sysvar → 自動批次設定系統變數","level":2,"lt":"✅","ver":"20210404","author":"chengshunyi","video":"","fas":""},{"no":1609,"file":"set-table-textstyle.LSP","cmd":"set-table-textstyle","cat":"文字","desc":"點選表格後，將表格所有儲存格文字樣式改為指定的文字樣式，不存在則提示。","usage":"執行 set-table-textstyle → 輸入文字樣式名稱 → 點選表格","level":3,"lt":"✅","ver":"11.Jul.2017","author":"Tharwat","video":"","fas":"fas/set-table-textstyle.fas"},{"no":1610,"file":"Set3HorizontalVP.lsp","cmd":"Set3HorizontalVP","cat":"圖面管理","desc":"在模型空間建立三個水平分割視埠，依輸入的顯示比例以 ZOOM XP 方式統一各視埠比例。","usage":"執行 Set3HorizontalVP → 輸入視窗比例(如 0.02) → 自動分割並設定","level":4,"lt":"✅","ver":"2026-03-10 (檔案日期)","author":"—","video":"","fas":"fas/Set3HorizontalVP.fas"},{"no":1611,"file":"set_blk_desc.LSP","cmd":"set_blk_desc","cat":"圖塊/屬性","desc":"以清單對話框列出圖面所有圖塊定義，雙擊即可編輯並寫入圖塊說明（Description）。","usage":"執行 set_blk_desc → 在清單雙擊圖塊 → 輸入說明 → 確定","level":6,"lt":"✅","ver":"20250330","author":"chengshunyi（MyCAD）","video":"https://youtu.be/RCuB_3QqoCA","fas":"fas/set_blk_desc.fas"},{"no":1612,"file":"SET_EL_FIELD.lsp","cmd":"SET_EL_FIELD","cat":"圖塊/屬性","desc":"以對話框設定前綴、小數位、單位與字寬，將圖塊屬性改成引用圖塊 Y 座標的欄位（Field），可連續點選或自動過濾。","usage":"執行 SET_EL_FIELD → 對話框設前綴/位數/單位 → 確定 → 連續點選屬性，Enter 結束","level":7,"lt":"✅","ver":"2026-01-22 (檔案日期)","author":"MyCAD","video":"","fas":"fas/SET_EL_FIELD.fas"},{"no":1613,"file":"SET_EL_FIELD_XYZ.LSP","cmd":"SET_EL_FIELD_XYZ","cat":"圖塊/屬性","desc":"對話框設定 X/Y/Z 座標、前綴、位數、單位、正值加號與動態/靜態模式，將圖塊屬性改為座標欄位或靜態文字。","usage":"執行 SET_EL_FIELD_XYZ → 對話框設定 → 確定 → 連續點選屬性","level":7,"lt":"✅","ver":"2026-05-03 (檔案日期)","author":"MyCAD","video":"","fas":"fas/SET_EL_FIELD_XYZ.fas"},{"no":1614,"file":"SET_GL_FIELD.lsp","cmd":"SET_GL_FIELD","cat":"圖塊/屬性","desc":"以 Field 計算圖塊 Y 座標減參考屬性值（GL 高程差）並自動加正負號，支援單一或批次過濾修改。","usage":"執行 SET_GL_FIELD → 對話框選是否批次過濾 → 確定 → 點選屬性/圖塊","level":7,"lt":"✅","ver":"2026-05-23 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/SET_GL_FIELD.fas"},{"no":1615,"file":"Set_MATCH_LINES.LSP","cmd":"Set_MATCH_LINES","cat":"修改","desc":"將圖層「接合線」的聚合線在模型空間設線寬20、配置空間設線寬0.2，並設 LTSCALE 200與公制系統變數。","usage":"執行 Set_MATCH_LINES（提示字為 FIX_JOIN_LINES）→ 自動處理模型與各配置","level":5,"lt":"✅","ver":"2026-01-06 (檔案日期)","author":"—","video":"","fas":"fas/Set_MATCH_LINES.fas"},{"no":1616,"file":"SetAnnoText.LSP","cmd":"SetAnnoText、RemoveAnnoText、AddScaleList","cat":"文字","desc":"點選圖層後，將該層文字先移除可註解，統一為 Standard、字高0.35、寬度0.75、正中對齊，再重新設為可註解並掛載比例。","usage":"執行 SetAnnoText → 點選目標圖層物件 → 自動三階段處理並預覽 1:100","level":6,"lt":"✅","ver":"20251215","author":"chengshunyi","video":"","fas":"fas/SetAnnoText.fas"},{"no":1617,"file":"SetAreaType.lsp","cmd":"SetAreaType","cat":"圖塊/屬性","desc":"以對話框組合空間類型（樓地板面積、機電空間、停車、建築面積等）文字，寫入動態圖塊指定屬性（預設 AREATYPE），可從圖塊挑選 Tag。","usage":"執行 SetAreaType → 對話框用 Add/Del/Up/Down 組合空間類型 → 可 Pick Tag 選屬性標籤 → 確定 → 選取圖塊寫入","level":8,"lt":"✅","ver":"除錯修正版 (2026-09-05 檔案日期)","author":"ChengBar (MyCAD)","video":"https://youtu.be/G3QE2DNckNs","fas":"fas/SetAreaType.fas"},{"no":1618,"file":"SETATTRCTAB_Diesel.lsp","cmd":"SETATTRCTAB_Diesel-L、SETATTRCTAB_Diesel-P、SETATTRCTAB_Diesel","cat":"圖塊/屬性","desc":"以 Diesel 欄位公式將目前配置名稱(CTAB)拆解填入圖框屬性的第2與第4個屬性，使圖框與配置連動並更新欄位。","usage":"執行 SETATTRCTAB_Diesel → 選取含至少四個屬性的圖框圖塊 → 自動寫入欄位並更新","level":6,"lt":"✅","ver":"20251206","author":"chengshunyi（JH 專用）","video":"https://youtu.be/quvxkbMvNZ8","fas":"fas/SETATTRCTAB_Diesel.fas"},{"no":1619,"file":"SetAutoCADToolbarLayout.lsp","cmd":"SetAutoCADToolbarLayout","cat":"系統/授權","desc":"列出 ACAD 選單群組的工具列，依預設清單開啟並停靠到上、左、右側，其餘工具列關閉，整理 AutoCAD 工具列配置。","usage":"執行 SetAutoCADToolbarLayout → 自動排列工具列並顯示清單","level":5,"lt":"❌","ver":"20251227","author":"chengshunyi","video":"","fas":""},{"no":1620,"file":"SetLayerDefaults-4.lsp","cmd":"SetLayerDefaults-4","cat":"圖層","desc":"以對話框選擇並設定 DIMLAYER、XREFLAYER、HPLAYER、CENTERLAYER 四個系統變數的預設圖層，含預覽。","usage":"執行 SetLayerDefaults-4 → 在四個清單各選圖層 → 確定寫入系統變數","level":6,"lt":"✅","ver":"2025-10-06 (檔案日期)","author":"—","video":"","fas":"fas/SetLayerDefaults-4.fas"},{"no":1621,"file":"SetLayerDefaults-r4.LSP","cmd":"SetLayerDefaults-R4","cat":"圖層","desc":"以對話框設定 DIMLAYER、XREFLAYER、HPLAYER、CENTERLAYER 預設圖層，並新增「重設」按鈕還原初始系統變數值。","usage":"執行 SetLayerDefaults-R4 → 選各預設圖層 → 可按重設 → 確定","level":6,"lt":"✅","ver":"2025-10-06 (檔案日期)","author":"—","video":"","fas":"fas/SetLayerDefaults-r4.fas"},{"no":1622,"file":"SetMLS.LSP","cmd":"（無，副程式庫）","cat":"標註","desc":"取得 MLeader 樣式字典，檢查指定樣式是否存在，不存在則建立（預設1:100、箭頭圖塊），存在則設為目前樣式。","usage":"載入後以函式呼叫，建立或套用多重引線樣式（範例名 Test3）","level":5,"lt":"✅","ver":"20230408","author":"chengshunyi","video":"","fas":"fas/SetMLS.fas"},{"no":1623,"file":"SetMyToolbarLayout.lsp","cmd":"SetMyToolbarLayout","cat":"系統/授權","desc":"依清單開啟 MY_CAD_PRO 選單群組中的指定工具列（常用功能、面積、圖層管理等）並停靠，其他工具列關閉。","usage":"執行 SetMyToolbarLayout → 自動顯示/隱藏並停靠工具列，列出清單","level":5,"lt":"❌","ver":"20251215","author":"chengshunyi","video":"","fas":""},{"no":1624,"file":"SETSOLIDALPHA.LSP","cmd":"SETSOLIDALPHA","cat":"修改","desc":"以對話框輸入透明度值（0-90），批次設定圖面填充(HATCH)物件的透明度。","usage":"執行 SETSOLIDALPHA → 輸入透明度值 → 確定 → 自動處理 Hatch","level":6,"lt":"✅","ver":"2026-09-07 (檔案日期)","author":"MyCAD","video":"","fas":"fas/SETSOLIDALPHA.fas"},{"no":1625,"file":"SetSysVars-V1.lsp","cmd":"SSV、mySetSysVars、rollbackSysVars","cat":"系統/授權","desc":"以對話框顯示並套用一整批系統變數優化設定（ZOOMFACTOR、VTENABLE、SAVEFIDELITY、CURSORSIZE 等），可復原。","usage":"執行 SSV → 檢視新舊變數對照 → 確定套用；rollbackSysVars 還原","level":6,"lt":"✅","ver":"2025-09-20 (檔案日期)","author":"—","video":"","fas":""},{"no":1626,"file":"SetSysVars.lsp","cmd":"SSV、mySetSysVars","cat":"系統/授權","desc":"批次設定優化用系統變數（ZOOMFACTOR、INDEXCTL、SELECTIONPREVIEW、VTENABLE 等）與 SHADEMODE 2D，顯示前後對照並含試用期限。","usage":"執行 SSV → 檢視前後對照 → 確定套用","level":6,"lt":"✅","ver":"2025-09-06 (檔案日期)","author":"—","video":"","fas":""},{"no":1627,"file":"SetupDimStyle-V1.lsp","cmd":"SetupDimStyle","cat":"標註","desc":"以對話框選繪圖比例與單位，建立單一或批次建立所有比例的尺寸標註樣式（箭頭、中心記號、延伸線等隨比例）。","usage":"執行 SetupDimStyle → 選繪圖比例與單位 → 確定建立；或按批次建立所有尺寸樣式","level":7,"lt":"✅","ver":"20250914","author":"chengshunyi（FOR JAHAA）","video":"https://youtu.be/oEg9wwATjYw","fas":"fas/SetupDimStyle-V1.fas"},{"no":1628,"file":"SetupDimStyle-V2.lsp","cmd":"SetupDimStyle","cat":"標註","desc":"尺寸樣式設定 V2：新增尺寸前置碼、箭頭樣式（建築斜線）與文字顏色選項，並可批次建立並繪示範標註。","usage":"執行 SetupDimStyle → 選比例/單位/前置碼/箭頭/顏色 → 確定或批次建立","level":7,"lt":"✅","ver":"20250920","author":"chengshunyi（FOR JAHAA）","video":"https://youtu.be/oEg9wwATjYw","fas":"fas/SetupDimStyle-V2.fas"},{"no":1629,"file":"SetupDimStyle-V3.lsp","cmd":"SetupDimStyle","cat":"標註","desc":"依 MyCAD 規範重寫的尺寸樣式工具：選比例、單位、前置碼、箭頭、顏色建立單一樣式或批次建立全部，並繪製示範標註。","usage":"執行 SetupDimStyle → 對話框設定參數 → 確定建立單一樣式，或批次建立並繪示範標註","level":9,"lt":"⚠️","ver":"v1.2.0 2026-11-07","author":"ChengBar (MyCAD)","video":"https://youtu.be/oEg9wwATjYw","fas":"fas/SetupDimStyle-V3.fas"},{"no":1630,"file":"setupint(交點放圖塊).lsp","cmd":"setupint","cat":"圖塊/屬性","desc":"選取軸線文字與軸線，計算軸線交點並建立縱橫軸線配對，將交點的軸線編號寫入圖塊屬性（GRID_INT_VERT / HORZ）。","usage":"執行 setupint → 選軸線文字 → 選軸線 → 自動在交點處寫入編號","level":7,"lt":"✅","ver":"20230115","author":"Lee Mac（交點函式）、chengshunyi","video":"","fas":"fas/setupint(交點放圖塊).fas"},{"no":1631,"file":"SetupMLeaderStyle.LSP","cmd":"SetupMLeaderStyle","cat":"標註","desc":"以對話框選繪圖比例、箭頭、文字顏色與引線段數，建立單一或批次建立所有比例的多重引線樣式（JH_M_）。","usage":"執行 SetupMLeaderStyle → 對話框選比例/箭頭/顏色/段數 → 確定或批次建立","level":7,"lt":"✅","ver":"2025-09-29 (檔案日期)","author":"chengshunyi（JAHAA 客製）","video":"","fas":"fas/SetupMLeaderStyle.fas"},{"no":1632,"file":"SetVP.lsp","cmd":"SetVP","cat":"圖面管理","desc":"在模型空間以對話框選擇分割模式（3H、3V、2H、2V、4X）並輸入顯示比例，建立視埠並統一縮放比例。","usage":"執行 SetVP → 對話框選分割模式與比例 → 確定自動分割並縮放","level":6,"lt":"✅","ver":"2026-03-10 (檔案日期)","author":"MyCAD","video":"","fas":"fas/SetVP.fas"},{"no":1633,"file":"SetVPScale.LSP","cmd":"SetVPScale","cat":"出圖/列印","desc":"輸入比例分母後選取配置空間視埠，解鎖後進入視埠設定 XP 比例，再恢復鎖定。","usage":"執行 SetVPScale → 輸入比例分母（Enter 沿用上次）→ 選取視埠 → 自動設定比例","level":5,"lt":"✅","ver":"2026-04-19 (檔案日期)","author":"MyCAD","video":"","fas":"fas/SetVPScale.fas"},{"no":1634,"file":"sfsp-2018 -tg.lsp","cmd":"sfsp-2018-tg、sfsp-2018-tg-r","cat":"系統/授權","desc":"設定 AutoCAD 2018 的支援檔案搜尋路徑與信任路徑（MyPGP、support2、Font-tw、ez2018 等），-r 為還原重設。","usage":"執行 sfsp-2018-tg → 自動寫入路徑；sfsp-2018-tg-r 重設","level":5,"lt":"✅","ver":"20220716更新","author":"Lee Mac (LM:sfsp+n)、chengshunyi","video":"","fas":""},{"no":1635,"file":"sfsp-2018.lsp","cmd":"sfsp-2018、sfsp-2018-r","cat":"系統/授權","desc":"設定 AutoCAD 2018 的支援檔案搜尋路徑與信任路徑（加入 support4 等），-r 為還原重設。","usage":"執行 sfsp-2018 → 自動寫入路徑；sfsp-2018-r 重設","level":5,"lt":"✅","ver":"20220716更新","author":"Lee Mac (LM:sfsp+n)、chengshunyi","video":"","fas":""},{"no":1636,"file":"sfsp-2023.lsp","cmd":"sfsp-2023、sfsp-2023-r","cat":"系統/授權","desc":"設定 AutoCAD 2023 的支援檔案搜尋路徑與信任路徑（support2023、ez2023 等），-r 為還原重設。","usage":"執行 sfsp-2023 → 自動寫入路徑；sfsp-2023-r 重設","level":5,"lt":"✅","ver":"20220716更新","author":"Lee Mac (LM:sfsp+n)、chengshunyi","video":"","fas":""},{"no":1637,"file":"sfsp-2024-01.lsp","cmd":"（無，副程式庫）","cat":"系統/授權","desc":"重設 AutoCAD 更新版本後的各項路徑：建立 ComputerSetting 資料夾，設定存檔、印表機、樣板、暫存路徑，並重載選單與關閉功能區。","usage":"載入即執行環境設定（含 MENULOAD/RIBBONCLOSE）","level":8,"lt":"⚠️","ver":"20250127","author":"AlanH 2011、chengshunyi","video":"","fas":""},{"no":1638,"file":"sfsp-2024-tg.lsp","cmd":"sfsp-2024-tg、sfsp-2024-ezmy、sfsp-2024-reset","cat":"系統/授權","desc":"設定 AutoCAD 2024 支援路徑與信任路徑（support2024、My_BLK、ez2024 等），建立 ComputerSetting 目錄，ezmy 為 EZ+MyCAD 組合，reset 重設。","usage":"執行 sfsp-2024-tg（或 -ezmy / -reset）→ 自動設定路徑","level":6,"lt":"⚠️","ver":"20250429","author":"chengshunyi","video":"","fas":""},{"no":1639,"file":"sfsp-2024.lsp","cmd":"sfsp-2024、sfsp-2024-ezmy、sfsp-2024-reset","cat":"系統/授權","desc":"設定 AutoCAD 2024 支援路徑與信任路徑，建立 ComputerSetting 資料夾，提供 EZ+MyCAD 組合與重設指令。","usage":"執行 sfsp-2024 → 自動設定路徑；sfsp-2024-reset 重設","level":6,"lt":"⚠️","ver":"20250126","author":"chengshunyi","video":"","fas":""},{"no":1640,"file":"SFSP_2026LT.lsp","cmd":"SFSP_2026LT、sfsp-2026LT","cat":"系統/授權","desc":"對話框式選項設定：支援路徑、信任路徑、樣板、CTB、工具選項板、自動存檔、指令列字型、選取框大小、黑底背景，設定存 INI。","usage":"執行 SFSP_2026LT → 檢視各項（可勾選啟用/瀏覽資料夾/公司預設值）→ 確定寫入","level":9,"lt":"⚠️","ver":"v1.2.0 2026-11-14","author":"ChengBar (MyCAD)","video":"https://youtu.be/88ZMFNmB_R0","fas":""},{"no":1641,"file":"ShadowSimulation-m.LSP","cmd":"ShadowSimulation-m","cat":"繪圖","desc":"選取聚合線、直線或弧線，模擬 2D 外牆立面日照投射陰影並產生透明 HATCH，可指定圖層、連續執行與依圖層批次處理。","usage":"執行 ShadowSimulation-m → 對話框設方向/角度/圖層 → 選取物件 → 自動產生陰影填充","level":9,"lt":"⚠️","ver":"V11.2 (2026 Edition)","author":"ChengBar (MyCAD)","video":"","fas":"fas/ShadowSimulation-m.fas"},{"no":1642,"file":"ShadowSimulation-s.LSP","cmd":"ShadowSimulation","cat":"繪圖","desc":"選取聚合線、直線或弧線，模擬 2D 外牆立面日照陰影，以 HATCH 填滿並用 CHPROP 設透明度、置於最下層。","usage":"執行 ShadowSimulation → 對話框設參數 → 選取物件 → 自動繪出陰影","level":8,"lt":"⚠️","ver":"V8.2 (2026 Edition)","author":"ChengBar (MyCAD)","video":"","fas":"fas/ShadowSimulation-s.fas"},{"no":1643,"file":"SHP2UNI.LSP","cmd":"SHP2UNI","cat":"轉檔/匯出入","desc":"讀取 SHP 字型原始檔，將字型標頭編碼模式改為 Unicode(21)，並把字符編號與座標轉為 4 位 16 進位，產生新 SHP 供 COMPILE 編譯。","usage":"執行 SHP2UNI → 選擇 SHP 檔 → 自動轉換並產出新檔 → 用 COMPILE 轉 SHX","level":7,"lt":"✅","ver":"2026-04-04 (檔案日期)","author":"—","video":"","fas":"fas/SHP2UNI.fas"},{"no":1644,"file":"site-earth-cal.lsp","cmd":"ib-at-int-grid、ib-at-int、find-sur-elev","cat":"面積/數量統計","desc":"在方格交點放入高程圖塊，並以交點半徑內測量高程點平均值填入屬性，用於整地土方方格網計算。","usage":"執行 ib-at-int-grid → 選測量高程圖塊與屬性 → 選方格線 → 自動在交點放高程符號並寫平均高程","level":8,"lt":"✅","ver":"20240315","author":"chengshunyi","video":"","fas":"fas/site-earth-cal.fas"},{"no":1645,"file":"site-linetype.lsp","cmd":"a-line、m1-line、b-line、bl-line、bl4-line、bl6-line、bl8-line、bm-line、pk-line、h3-line、h1-line、h2-line、sf1-line、sf2-line","cat":"繪圖","desc":"一組快捷指令，自動建立字型樣式與圖層、載入 MY-CNS-線型.lin 的線型後切換圖層並啟動 PLINE，供基地剖面繪製各種界線（如道路、水溝、擋土牆）。","usage":"執行某個 xx-line 指令（如 bl-line）→ 自動切圖層與線型 → 依 PLINE 提示繪製","level":6,"lt":"✅","ver":"2025-12-24 (檔案日期)","author":"chengshunyi（DrawSiteSecProfile）","video":"","fas":"fas/site-linetype.fas"},{"no":1646,"file":"site-section-bytext-pl.lsp","cmd":"site-section-bytext-pl","cat":"繪圖","desc":"選樣例文字取得過濾圖層，並選封閉聚合線為範圍，擷取範圍內該層測量高程文字，依X排序畫出剖面線並標註高程，輸出到聚合線所在圖層。","usage":"執行 site-section-bytext-pl → 選樣例文字 → 選封閉聚合線範圍 → 點選剖面起點 → 自動畫剖面線與標註","level":7,"lt":"✅","ver":"2025-12-18 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/site-section-bytext-pl.fas"},{"no":1647,"file":"site-section-bytext.LSP","cmd":"site-section-bytext","cat":"繪圖","desc":"依測量圖文字高程繪製剖面線：選樣例文字取圖層，全圖過濾該層高程文字，依 X 排序、清理文字後以高程為 Y 繪出剖面 PLINE 並標註。","usage":"執行 site-section-bytext → 選樣例文字 → 點選剖面起點 → 自動畫高程線","level":7,"lt":"✅","ver":"20251217","author":"chengshunyi","video":"","fas":"fas/site-section-bytext.fas"},{"no":1648,"file":"site-section-pl-2cm.LSP","cmd":"site-section-pl-2cm","cat":"繪圖","desc":"依測量圖高程圖塊的XY座標與屬性高程值，在選取聚合線範圍內畫出剖面線並標註，PLINE 以圖塊名稱區別圖層（2cm 版）。","usage":"執行 site-section-pl-2cm → 選高程圖塊與屬性 → 選聚合線範圍 → 點選剖面起點 → 自動繪製","level":7,"lt":"✅","ver":"20220522","author":"chengshunyi","video":"","fas":"fas/site-section-pl-2cm.fas"},{"no":1649,"file":"site-section-pl-la.LSP","cmd":"site-section-pl-la","cat":"繪圖","desc":"依測量圖高程圖塊的XY座標與屬性高程值，在選取聚合線範圍內畫剖面線並標註文字，以圖層名稱區別 PLINE。","usage":"執行 site-section-pl-la → 選高程圖塊與屬性 → 選聚合線 → 點選剖面起點 → 自動繪製","level":7,"lt":"✅","ver":"20220522","author":"chengshunyi","video":"","fas":"fas/site-section-pl-la.fas"},{"no":1650,"file":"site-section-pl.LSP","cmd":"site-section-pl","cat":"繪圖","desc":"依測量圖高程圖塊的XY座標與屬性高程值，在選取聚合線範圍內畫剖面線並標註高程，Pline 以圖塊名稱區別。","usage":"執行 site-section-pl → 選高程圖塊與屬性 → 選聚合線範圍 → 點選起點 → 自動繪製","level":7,"lt":"✅","ver":"20220522","author":"chengshunyi","video":"","fas":"fas/site-section-pl.fas"},{"no":1651,"file":"site-section.LSP","cmd":"site-section","cat":"繪圖","desc":"依測量圖高程圖塊的XY座標與屬性高程值，直接框選圖塊後畫出剖面線並標註高程（最早期版本，無聚合線範圍）。","usage":"執行 site-section → 選高程圖塊與屬性 → 點選剖面起點 → 自動繪製","level":6,"lt":"✅","ver":"20210904","author":"chengshunyi","video":"","fas":"fas/site-section.fas"},{"no":1652,"file":"site-step-sec.lsp","cmd":"site-step-sec","cat":"剖面/結構","desc":"以對話框輸入平台長度、級深、高度、階數、版厚等參數，自動繪出樓梯／階梯剖面的外形線與版厚線。","usage":"執行 site-step-sec → 對話框輸入參數 → 確定 → 點選上平台起點 → 自動繪製","level":7,"lt":"✅","ver":"20230226","author":"chengshunyi","video":"","fas":"fas/site-step-sec.fas"},{"no":1653,"file":"SlopeCalc-3PD.lsp","cmd":"SlopeCalc-3PD","cat":"面積/數量統計","desc":"依建築技術規則第261條平均坡度分析：計算方格四邊交點數、總交點數n、坡度S%、傾斜角、坡級，分層標註並產生表格與CSV。","usage":"執行 SlopeCalc-3PD → 對話框設定參數 → 選取方格與等高線 → 自動標註、套色並插入表格，可匯出 CSV","level":9,"lt":"⚠️","ver":"2026-04-04 (檔案日期)","author":"MyCAD","video":"","fas":"fas/SlopeCalc-3PD.fas"},{"no":1654,"file":"SlopeCalc-3PDang.lsp","cmd":"SlopeCalc","cat":"面積/數量統計","desc":"建築技術規則第261條平均坡度分析 V18：從聚合線頂點取斜方格，自動標註編號、n值與坡度，可選純文字、屬性圖塊或併存，輸出統計表與CSV。","usage":"執行 SlopeCalc → 對話框選標註形式 → 選方格與等高線 → 自動標註、套色、統計表，可匯出 CSV","level":9,"lt":"⚠️","ver":"V18 (2026-05-22 檔案日期)","author":"MyCAD","video":"","fas":"fas/SlopeCalc-3PDang.fas"},{"no":1655,"file":"SlopeCalc-3PDangAV.lsp","cmd":"SlopeCalc-3PDangAV","cat":"面積/數量統計","desc":"平均坡度分析 V21：新增手動窗選範圍只算框選內方格、統計表依坡級套底色，最終加權平均坡度也依級坡套色。","usage":"執行 SlopeCalc-3PDangAV → 對話框設定 → 窗選方格範圍 → 計算、標註並產生套色表格與 CSV","level":9,"lt":"⚠️","ver":"V21 (2026-05-23 檔案日期)","author":"MyCAD","video":"","fas":"fas/SlopeCalc-3PDangAV.fas"},{"no":1656,"file":"SlopeCalc-3PDangAVs.lsp","cmd":"SlopeCalc-3PDangAVs","cat":"面積/數量統計","desc":"平均坡度分析 V22.1：屬性圖塊新增 AREA 欄位，表格加面積欄並修正語法，輸出各方格面積與坡級統計。","usage":"執行 SlopeCalc-3PDangAVs → 設定 → 窗選方格 → 自動標註、表格與 CSV","level":9,"lt":"⚠️","ver":"V22.1 (2026-05-23 檔案日期)","author":"MyCAD","video":"","fas":"fas/SlopeCalc-3PDangAVs.fas"},{"no":1657,"file":"SlopeCalc-3PDangAVsd.lsp","cmd":"SlopeCalc-3PDangAVsd","cat":"面積/數量統計","desc":"平均坡度分析 V22.5：修正標註表格中斷問題，以全區方格面積加權計算平均坡度，產生逐格明細與結果套色統計表。","usage":"執行 SlopeCalc-3PDangAVsd → 設定 → 窗選方格 → 自動標註、面積加權計算與表格","level":9,"lt":"⚠️","ver":"V22.5 (2026-05-23 檔案日期)","author":"MyCAD","video":"","fas":"fas/SlopeCalc-3PDangAVsd.fas"},{"no":1658,"file":"SlopeCalc-3PDangAVsdF.lsp","cmd":"SlopeCalc-3PDangAVsdF","cat":"面積/數量統計","desc":"平均坡度分析 V22.7：面積欄改用動態 Field，解決編譯警告並相容64位元，進行面積加權坡度分析與表格輸出。","usage":"執行 SlopeCalc-3PDangAVsdF → 設定 → 窗選方格 → 自動標註、動態面積欄位與表格","level":9,"lt":"⚠️","ver":"V22.7 (2026-09-07 檔案日期)","author":"MyCAD","video":"","fas":"fas/SlopeCalc-3PDangAVsdF.fas"},{"no":1659,"file":"SlopeCalc-3PDangAVsdFs.lsp","cmd":"SlopeCalc-3PDangAVsdFs","cat":"面積/數量統計","desc":"平均坡度分析 V22.8：新增文字型式下拉選單與方格圖層過濾，其餘為面積加權平均坡度、標註、表格與 CSV 輸出。","usage":"執行 SlopeCalc-3PDangAVsdFs → 選文字型式/方格圖層 → 窗選方格 → 自動標註與表格","level":9,"lt":"⚠️","ver":"V22.8 (2026-09-07 檔案日期)","author":"MyCAD","video":"","fas":"fas/SlopeCalc-3PDangAVsdFs.fas"},{"no":1660,"file":"SlopeCalc-3PDD.lsp","cmd":"SlopeCalc-3PDD","cat":"面積/數量統計","desc":"平均坡度分析 V9：強化大座標下交點去重，計算 n、S%、角度與坡級，圖例與統計表自動套色，可匯出 CSV 並以 Excel 開啟，含清除舊標註。","usage":"執行 SlopeCalc-3PDD → 設定 → 選方格與等高線 → 自動標註、圖例與表格 → 可清除舊標註","level":9,"lt":"⚠️","ver":"V9 (2026-04-04 檔案日期)","author":"MyCAD","video":"","fas":"fas/SlopeCalc-3PDD.fas"},{"no":1661,"file":"SlopeCalc-3PDDbl.lsp","cmd":"SlopeCalc-3PDDbl","cat":"面積/數量統計","desc":"平均坡度分析 V17：可選標註形式（純文字、屬性圖塊、併存），自動標註編號、四邊n值與中心數據，輸出統計表與CSV。","usage":"執行 SlopeCalc-3PDDbl → 對話框選標註形式 → 選方格 → 自動標註與表格","level":8,"lt":"⚠️","ver":"V17 (2026-04-11 檔案日期)","author":"MyCAD","video":"","fas":"fas/SlopeCalc-3PDDbl.fas"},{"no":1662,"file":"SM_OPEN.lsp","cmd":"SM_OPEN","cat":"繪圖","desc":"選取如「BG WxH cm」格式文字，依尺寸（支援 mm/cm/m）畫出開口矩形與交叉線，可外擴偏移矩形，完成後自動群組。","usage":"執行 SM_OPEN → 對話框設字高/偏移/寬高反轉 → 連續選取文字 → 自動畫矩形、交叉線與標籤","level":8,"lt":"✅","ver":"2026-01-15 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/SM_OPEN.fas"},{"no":1663,"file":"SmartHatchUnitLabel.lsp","cmd":"SmartHatchUnitLabel","cat":"面積/數量統計","desc":"選擇繪圖單位（mm/cm/m）後，為選取的所有 HATCH 在中心插入 MText 面積 Field，並換算為 m2。","usage":"執行 SmartHatchUnitLabel → 選繪圖單位 → 選取填充 → 自動在中心標註面積","level":6,"lt":"✅","ver":"20250712","author":"AI（Copilot）、chengshunyi","video":"","fas":"fas/SmartHatchUnitLabel.fas"},{"no":1664,"file":"SMP-s.LSP","cmd":"SMP","cat":"圖面管理","desc":"SuperMyPurge：深度清理圖檔，清除 Regapps、零長度幾何、空白文字與孤立資料，重複巢狀 PURGE 後做 AUDIT 稽核修復。","usage":"執行 SMP → 自動依序清理並稽核 → 完成提示","level":3,"lt":"✅","ver":"2026-04-30 (檔案日期)","author":"shunyi (MyCAD-APP.com)","video":"","fas":"fas/SMP-s.fas"},{"no":1665,"file":"SMP.lsp","cmd":"SMP","cat":"圖面管理","desc":"SuperMyPurge v8：對話框選單檔或批次處理目錄，以 SCR 腳本對每個圖檔巢狀 PURGE、Audit 並存檔，記憶選取目錄。","usage":"執行 SMP → 選模式（目前圖檔／批次目錄）→ 設巢狀次數與 Audit → 確定，批次產生 SCR 自動執行","level":8,"lt":"✅","ver":"v8.0 (2026-05-01 檔案日期)","author":"shunyi (MyCAD-APP.com)","video":"","fas":"fas/SMP.fas"},{"no":1666,"file":"SMT.LSP","cmd":"StripMtext、SMT","cat":"文字","desc":"Strip Mtext：以對話框勾選要移除的 MText 格式項目（字型、顏色、粗體、段落等），批次清除選取多行文字、引線與表格文字的格式碼。","usage":"執行 SMT → 對話框勾選要清除的格式（可全選/清除/儲存設定）→ 選取 MText/標註/表格 → 完成","level":6,"lt":"✅","ver":"2009-12-04 (檔案日期)","author":"網路程式（Strip Mtext，原作者 Express/Lee Mac 類）","video":"","fas":"fas/SMT.fas"},{"no":1667,"file":"SO-Col-Chr-05.LSP","cmd":"so-col-chr-05-ls、so-col-chr-05-rs、so-col-chr-05","cat":"對齊/排列","desc":"將柱編號圖塊依位置排序，重新以字母序號編碼，並在字母後加 .5 字串（05 版）；-ls 由左往右、-rs 由右往左，Y 由下往上。","usage":"執行 so-col-chr-05 → 輸入編號前綴與起始字母 → 自動搜尋柱編號圖塊並依 Y 再依 X 排序重編","level":7,"lt":"✅","ver":"2008.01.27 / 20250324","author":"Shun_Yi Studio（chengshunyi）","video":"","fas":"fas/SO-Col-Chr-05.fas"},{"no":1668,"file":"so-col-chr-U-05.lsp","cmd":"so-col-chr-U-05","cat":"對齊/排列","desc":"將柱編號圖塊依位置排序並重編字母序號（05 版 .5），排序方向為由上往下。","usage":"執行 so-col-chr-U-05 → 輸入編號前綴與起始字母 → 自動由上往下重編","level":7,"lt":"✅","ver":"20231220","author":"Shun_Yi Studio（chengshunyi）","video":"","fas":"fas/so-col-chr-U-05.fas"},{"no":1669,"file":"SO-Col-Chr-U.LSP","cmd":"so-col-chr-U","cat":"對齊/排列","desc":"將柱編號圖塊依位置排序並重編字母序號，排序方向為由上往下。","usage":"執行 so-col-chr-U → 輸入編號前綴與起始字母 → 自動由上往下重編","level":7,"lt":"✅","ver":"20231220","author":"Shun_Yi Studio（chengshunyi）","video":"","fas":"fas/SO-Col-Chr-U.fas"},{"no":1670,"file":"so-col-chr-ui.lsp","cmd":"so-col-chr-ui","cat":"對齊/排列","desc":"以對話框設定編號前綴、起始字母、排序方向（左右、上下）與是否加 .5，對柱編號圖塊做字母序號排序重編（跳過 I、O）。","usage":"執行 so-col-chr-ui → 對話框設前綴/起始/方向 → 確定 → 自動重編柱編號","level":8,"lt":"✅","ver":"V20.1 (2026-03-13 檔案日期)","author":"MyCAD","video":"","fas":"fas/so-col-chr-ui.fas"},{"no":1671,"file":"SO-Col-Chr.LSP","cmd":"so-col-chr-ls、so-col-chr-rs、so-col-chr","cat":"對齊/排列","desc":"將柱編號圖塊依位置排序，重新以字母序號編碼；-ls 由左往右、-rs 由右往左，Y 由下往上分段排序。","usage":"執行 so-col-chr → 輸入編號前綴與起始字母 → 自動搜尋並依 Y、X 排序重編","level":7,"lt":"✅","ver":"2008.01.27 / 20250324","author":"Shun_Yi Studio（chengshunyi）","video":"","fas":"fas/SO-Col-Chr.fas"},{"no":1672,"file":"SO-Col-Num-05.LSP","cmd":"so-col-num-05-ls、so-col-num-05-rs、so-col-num-05","cat":"對齊/排列","desc":"將柱編號圖塊依位置排序，重新以數字序號編碼並加 .5 字串（05 版）；-ls 由左往右、-rs 由右往左。","usage":"執行 so-col-num-05 → 輸入編號前綴與起始數字 → 自動依 Y、X 排序重編","level":7,"lt":"✅","ver":"2008.01.27 / 20250324","author":"Shun_Yi Studio（chengshunyi）","video":"","fas":"fas/SO-Col-Num-05.fas"},{"no":1673,"file":"so-col-num-i.lsp","cmd":"so-col-num-lr、so-col-num-rl、so-col-num-tb、so-col-num-bt、so-col-num","cat":"對齊/排列","desc":"柱編號圖塊數字序號重排優化版，提供由左到右、右到左、上到下、下到上四種排序指令，以容許誤差分組後重新編號。","usage":"執行 so-col-num-lr 等 → 輸入編號前綴與起始數字 → 選取柱圖塊 → 自動分組排序重編","level":7,"lt":"✅","ver":"v2.0 (2026-10-17 檔案日期)","author":"Shun_Yi Studio（chengshunyi）","video":"","fas":"fas/so-col-num-i.fas"},{"no":1674,"file":"so-col-num-if.lsp","cmd":"so-col-num-lr、so-col-num-lr-f、so-col-num-rl、so-col-num-rl-f、so-col-num-tb、so-col-num-tb-f、so-col-num-bt、so-col-num-bt-f、so-col-num-if","cat":"對齊/排列","desc":"柱編號圖塊數字序號重排 V3.0，四種排序方向各提供整數與浮點（加 .5）兩種編號類型，選取柱圖塊後分組排序重編。","usage":"執行 so-col-num-lr（或 -f 版）→ 輸入前綴與起始數字 → 選取柱圖塊 → 自動重編","level":7,"lt":"✅","ver":"V3.0 (2025-12-12 檔案日期)","author":"Shun_Yi Studio（chengshunyi）","video":"","fas":"fas/so-col-num-if.fas"},{"no":1675,"file":"so-col-num-ui.lsp","cmd":"so-col-num-ui","cat":"對齊/排列","desc":"以對話框設定編號前綴、起始數字、整數或 .5 類型與排序方向，對柱編號圖塊做數字序號排序重編（V7.0 核心）。","usage":"執行 so-col-num-ui → 對話框設前綴/起始/類型/方向 → 確定 → 選取柱圖塊 → 自動重編","level":8,"lt":"✅","ver":"V7.0 (2025-12-12 檔案日期)","author":"MyCAD","video":"","fas":"fas/so-col-num-ui.fas"},{"no":1676,"file":"SO-Col-Num.LSP","cmd":"so-col-num-ls、so-col-num-rs、so-col-num","cat":"對齊/排列","desc":"將柱編號圖塊依位置排序，重新以數字序號編碼；-ls 由左往右、-rs 由右往左（2025 新增）。","usage":"執行 so-col-num → 輸入編號前綴與起始數字 → 自動搜尋柱編號並依 Y、X 排序重編","level":7,"lt":"✅","ver":"2008.01.27 / 20250324","author":"Shun_Yi Studio（chengshunyi）","video":"","fas":"fas/SO-Col-Num.fas"},{"no":1677,"file":"SO-NUM-W.LSP","cmd":"so-num-w","cat":"圖塊/屬性","desc":"輸入樓層號碼後，以兩點視窗選取房間編號圖塊（含動態圖塊），依位置排序並重新編號。","usage":"執行 so-num-w → 輸入房間圖塊名稱與樓層號 → 指定視窗兩點 → 自動依 Y、X 排序重編","level":7,"lt":"✅","ver":"20080527","author":"Shun_Yi Studio（chengshunyi）","video":"https://youtu.be/p0rkaUFnHmM","fas":"fas/SO-NUM-W.fas"},{"no":1678,"file":"SO-NUM.LSP","cmd":"so-num","cat":"圖塊/屬性","desc":"輸入樓層號碼後選取房間編號圖塊（含動態圖塊），依位置排序並重新編號，行間距隨比例尺調整。","usage":"執行 so-num → 輸入房間圖塊名稱與樓層 → 選取圖塊 → 自動重編（會警告重編風險）","level":7,"lt":"✅","ver":"20080527（20250720 更新）","author":"Shun_Yi Studio（chengshunyi）","video":"https://youtu.be/w8x56hyAjOU","fas":"fas/SO-NUM.fas"},{"no":1679,"file":"SO-NUM3-w.LSP","cmd":"so-num3-w","cat":"圖塊/屬性","desc":"房間編號圖塊排序重編（3 版），輸入樓層後以兩點視窗選取圖塊，依位置排序編號。","usage":"執行 so-num3-w → 輸入樓層號 → 指定視窗兩點 → 自動排序重編","level":7,"lt":"✅","ver":"202103","author":"Shun_Yi Studio（chengshunyi）","video":"https://youtu.be/UWYxd1t-BRI","fas":"fas/SO-NUM3-w.fas"},{"no":1680,"file":"SO-NUM3.LSP","cmd":"so-num3","cat":"圖塊/屬性","desc":"房間編號圖塊排序重編（3 版），輸入樓層後選取圖塊，依 Y、X 位置排序重新編號。","usage":"執行 so-num3 → 輸入樓層號 → 選取圖塊 → 自動排序重編","level":7,"lt":"✅","ver":"202103","author":"Shun_Yi Studio（chengshunyi）","video":"https://youtu.be/3-jGVYMggy0","fas":"fas/SO-NUM3.fas"},{"no":1681,"file":"SOCPL.lsp","cmd":"SOCPL、sel-obj-creat-pl-ui、sel-obj-creat-pl","cat":"文字","desc":"選取多個圖元判斷封閉區域，在各區域中心自動標註單行文字（可設內容與字高），標完即清除暫存邊界，不保留 Polyline。","usage":"執行 SOCPL → 對話框選圖層、輸入文字與字高 → 選取圖元 → 自動在封閉區中心放文字","level":9,"lt":"⚠️","ver":"v3.08 2026-10-25","author":"Stefan M.（初版）、ChengShunYi、ChengBar (MyCAD)","video":"https://youtu.be/O8Sg5y2p-K8","fas":"fas/SOCPL.fas"},{"no":1682,"file":"SOLID2TRANSPARANCY.LSP","cmd":"SOLID2TRANSPARANCY","cat":"修改","desc":"選取 HATCH 或 SOLID 填充物件，改為白色（255,255,255）並設為 50% 透明度。","usage":"執行 SOLID2TRANSPARANCY → 自動選取填充 → 套用顏色與透明度","level":2,"lt":"✅","ver":"2022-09-04 (檔案日期)","author":"—","video":"","fas":"fas/SOLID2TRANSPARANCY.fas"},{"no":1683,"file":"Sort-AttNum.lsp","cmd":"Sort-AttNum-VLDU、Sort-AttNum-VLUD、Sort-AttNum-VRDU、Sort-AttNum-VRUD、Sort-AttNum-HLDU、Sort-AttNum-HLUD、Sort-AttNum-HRDU、Sort-AttNum-HRUD、Sort-AttNum","cat":"圖塊/屬性","desc":"選取一個屬性後，依八種排序基準（直排／橫排、左右、上下）將同圖塊的該屬性值依位置自動編號，序號長度固定。","usage":"執行 Sort-AttNum-xxxx（如 HLUD）→ 選取屬性 → 框選圖塊 → 輸入起始與位數 → 自動依位置寫入序號","level":7,"lt":"✅","ver":"20241012","author":"chengshunyi、Lee Mac","video":"","fas":"fas/Sort-AttNum.fas"},{"no":1684,"file":"SORT.LSP","cmd":"SORT","cat":"圖面管理","desc":"依輸入的視窗大小將圖面以方格範圍逐格 WBLOCK 重存，使圖形依空間排序以加速繪圖、存取與重繪。","usage":"執行 SORT → 按 C 繼續 → 輸入存檔檔名 → 輸入排序視窗 X、Y 大小 → 自動 WBLOCK 重存","level":5,"lt":"✅","ver":"20220716更新","author":"網路程式（舊 SORT.LST）","video":"","fas":"fas/SORT.fas"},{"no":1685,"file":"Special_Selections.LSP","cmd":"ssl、sse、ssc、sstl、ssatt、sscu、ssoc、ssof、inv_sel、ssd","cat":"修改","desc":"gile 的特殊選取集工具組：依圖層、物件類型、顏色、線型、屬性值、圖塊等條件建立選取集，並可反選、依原選取集加減。","usage":"執行 ssl（依圖層）、sse（依類型）、ssc（依顏色）、sstl（線型）、ssatt（屬性）等 → 依提示選取來源物件 → 建立選取集","level":7,"lt":"✅","ver":"20240921","author":"gile (Gilles Chanteau)","video":"","fas":"fas/Special_Selections.fas"},{"no":1686,"file":"spl2pl.LSP","cmd":"spl2pl-x、spl2pl","cat":"修改","desc":"將 SPLINE 轉換成 PLINE（SPLINEDIT 轉換，精度 0~99）；-x 版轉換後移除原物件。","usage":"執行 spl2pl → 選取 SPLINE → 自動轉為聚合線","level":2,"lt":"✅","ver":"20250327","author":"chengshunyi","video":"","fas":"fas/spl2pl.fas"},{"no":1687,"file":"SplitVP.lsp","cmd":"SplitVP","cat":"出圖/列印","desc":"在配置空間指定兩點，以對話框設定 X、Y 等分與間距，產生等分視埠，比例設為 1:100，置於 Defpoints 並鎖定。","usage":"執行 SplitVP → 對話框輸入 X、Y 等分與間距 → 確定 → 指定兩點範圍 → 自動建立視埠","level":7,"lt":"✅","ver":"2026-04-26","author":"shunyi (ChengBAR)","video":"","fas":"fas/SplitVP.fas"},{"no":1688,"file":"SQF.lsp","cmd":"SQF","cat":"繪圖","desc":"以對話框設定方形邊長、圖層與顏色，繪製山坡地平均坡度計算用的方形坵塊。","usage":"執行 SQF → 對話框輸入邊長/圖層/顏色 → 確定 → 指定位置自動繪製方格","level":6,"lt":"✅","ver":"2026-04-11 (檔案日期)","author":"MyCAD","video":"","fas":"fas/SQF.fas"},{"no":1689,"file":"SQR(對角線畫正方形).lsp","cmd":"SQR","cat":"繪圖","desc":"指定對角線的兩點，畫出以該對角線為對角的正方形聚合線。","usage":"執行 SQR → 點選第一點 → 點選第二點 → 自動畫出正方形","level":2,"lt":"✅","ver":"20240818","author":"—","video":"","fas":"fas/SQR(對角線畫正方形).fas"},{"no":1690,"file":"SQR.lsp","cmd":"SQR","cat":"繪圖","desc":"指定對角線的兩點，畫出以該對角線為對角的正方形聚合線。","usage":"執行 SQR → 點選第一點 → 點選第二點 → 自動畫出正方形","level":2,"lt":"✅","ver":"20240818","author":"—","video":"","fas":"fas/SQR.fas"},{"no":1691,"file":"ss-filter.LSP","cmd":"ssl、sse、ssc、sstl、ssatt、sscu、ssoc、ssof、inv_sel、ssd","cat":"修改","desc":"gile 的特殊選取集工具組：依圖層、物件類型、顏色、線型、屬性值、圖塊等條件建立選取集，並可反選、加減選取集。","usage":"執行 ssl（依圖層）、sse、ssc、sstl、ssatt 等 → 依提示選取來源物件 → 建立選取集","level":7,"lt":"✅","ver":"20240921","author":"gile (Gilles Chanteau)","video":"","fas":"fas/ss-filter.fas"},{"no":1692,"file":"SSC-STAR.LSP","cmd":"SSC-STAR","cat":"文字","desc":"字串拆解組合工具（僅繪製）：選編號字串（支援範圍 B131-B134、星號 G51* 展開 A~H、複合展開）與尺寸字串，逐行寫出組合文字清單。","usage":"執行 SSC-STAR → 點選輸出起始位置 → 連續選取編號字串與尺寸字串 → 自動寫入文字，Enter 結束","level":7,"lt":"✅","ver":"2026-04-25 (檔案日期)","author":"MyCAD","video":"","fas":"fas/SSC-STAR.fas"},{"no":1693,"file":"SSC.lsp","cmd":"SSC","cat":"文字","desc":"字串拆解組合（String Split & Combine）：選取編號字串（含範圍展開）與尺寸字串，結合後連續逐行寫入圖面清單。","usage":"執行 SSC → 點選輸出起始位置 → 連續選取編號字串與尺寸字串 → 自動寫入，Enter 結束","level":6,"lt":"✅","ver":"2026-01-24 (檔案日期)","author":"MyCAD","video":"","fas":"fas/SSC.fas"},{"no":1694,"file":"SSFHMS-LT.LSP","cmd":"SSFHMS-LT","cat":"圖塊/屬性","desc":"機械螺絲自動化插入工具：以對話框選螺絲尺寸（M4~M5 平頭等），透過 ObjectDBX 從外部 DWG 匯入圖塊並插入。","usage":"執行 SSFHMS-LT → 對話框選螺絲尺寸 → 確定 → 指定插入點 → 自動匯入並插入圖塊","level":8,"lt":"❌","ver":"2026 (版權 C 2026；檔案日期 2026-06-21)","author":"ChengBar (MyCAD)","video":"","fas":"fas/SSFHMS-LT.fas"},{"no":1695,"file":"SSFHMS.LSP","cmd":"SSFHMS","cat":"圖塊/屬性","desc":"機械螺絲自動化插入工具：以對話框選螺絲尺寸，透過 ObjectDBX 從外部 DWG 檢查並匯入圖塊後插入。","usage":"執行 SSFHMS → 對話框選螺絲尺寸 → 確定 → 指定插入點 → 自動匯入並插入","level":8,"lt":"❌","ver":"2026 (檔案日期 2026-06-21)","author":"ChengBar (MyCAD)","video":"","fas":"fas/SSFHMS.fas"},{"no":1696,"file":"SSM-SYS-CONTROL.LSP","cmd":"SSM_SYSVAR_CONTROL","cat":"系統/授權","desc":"圖紙集相關效能系統變數控制介面（LAYOUTREGENCTL、SELECTIONPREVIEW、UPDATETHUMBNAIL、DRAWORDERCTL），可一鍵設為效能建議值或預設值。","usage":"執行 SSM_SYSVAR_CONTROL → 檢視目前值 → 按建議值或預設值按鈕 → 確定","level":6,"lt":"✅","ver":"2025-12-02 (檔案日期)","author":"—","video":"","fas":""},{"no":1697,"file":"SSM_Opt.lsp","cmd":"SSM_Opt","cat":"系統/授權","desc":"圖紙集(SSM)效能優化對話框：9 個系統變數（圖紙集狀態更新、XLOADCTL、INDEXCTL、背景列印等）可套用 AutoCAD 預設或建議優化值。","usage":"執行 SSM_Opt → 檢視目前值 → 按預設值或建議值 → 確定套用","level":6,"lt":"✅","ver":"2026-04-12 (檔案日期)","author":"MyCAD","video":"","fas":""},{"no":1698,"file":"SSMOptimizer.lsp","cmd":"SSMOptimizer","cat":"系統/授權","desc":"圖紙集管理員(SSM)系統變數設定對話框：SSLOCATE、SSMAUTOOPEN、SSMPOLLTIME、SSMSHEETSTATUS、UPDATETHUMBNAIL、PUBLISHCOLLATE 等。","usage":"執行 SSMOptimizer → 勾選/輸入各變數 → 確定套用","level":6,"lt":"✅","ver":"2025-12-12 (檔案日期)","author":"MyCAD","video":"https://youtu.be/YXiN4o9_VHo","fas":""},{"no":1699,"file":"SSRHMS-LT.LSP","cmd":"SSRHMS-LT","cat":"圖塊/屬性","desc":"機械圓頭螺絲插入工具 LT 版：對話框選螺絲尺寸（M4~M6），以 vla-insertblock 將外部 DWG 匯入為圖塊定義後插入，不使用 ObjectDBX。","usage":"執行 SSRHMS-LT → 對話框選螺絲尺寸 → 確定 → 指定插入點 → 自動匯入並插入圖塊","level":7,"lt":"✅","ver":"2026 (檔案日期 2026-06-21)","author":"ChengBar (MyCAD)","video":"","fas":"fas/SSRHMS-LT.fas"},{"no":1700,"file":"SSRHMS.LSP","cmd":"SSRHMS","cat":"圖塊/屬性","desc":"機械圓頭螺絲插入工具：對話框選螺絲尺寸並顯示預覽圖片，透過 ObjectDBX 從外部 DWG 匯入圖塊後插入。","usage":"執行 SSRHMS → 對話框選螺絲尺寸 → 確定 → 指定插入點 → 自動匯入並插入","level":7,"lt":"❌","ver":"2026 (檔案日期 2026-06-21)","author":"ChengBar (MyCAD)","video":"","fas":"fas/SSRHMS.fas"},{"no":1701,"file":"SSUM.lsp","cmd":"SSUM","cat":"文字","desc":"選取多個含數字的字串，過濾非數字字元後加總（支援負數與小數精度），以對話框設字高、比例、單位，結果以文字寫在圖面。","usage":"執行 SSUM → 對話框輸入字高/比例/單位/精度 → 確定 → 選取多個數字文字 → 點選位置放合計","level":7,"lt":"✅","ver":"20220716更新 (檔案日期 2026-01-21)","author":"chengshunyi（MyCAD）","video":"","fas":"fas/SSUM.fas"},{"no":1702,"file":"st-num.LSP","cmd":"st-num","cat":"文字","desc":"沿指定起點與距離方向依序放置連續數字文字（可含前後綴），用於樓梯平面踏步標編號。","usage":"執行 st-num → 輸入起始與結束數字 → 指定起點 → 指定終點(固定距離) → 自動依序放置數字","level":4,"lt":"✅","ver":"1.0 ~ 05.04.2009 (Lee Mac)","author":"Lee Mac（Num.lsp）、chengshunyi 改寫","video":"","fas":"fas/st-num.fas"},{"no":1703,"file":"ST-PLAN.LSP","cmd":"stair-1p、stair-2p、stair-3p","cat":"繪圖","desc":"樓梯平面圖繪製：指定 A、B、C 三點並輸入踏寬、踏深與一至三段踏數，自動畫出樓梯踏面線與方向線，依單位 mm/cm 調整。","usage":"執行 stair-1p/2p/3p → 指定 A、B、C 點 → 輸入踏寬、踏深與各段階數 → 自動繪製","level":8,"lt":"✅","ver":"84.4.12 / 93.03.13","author":"chengshunyi","video":"","fas":"fas/ST-PLAN.fas"},{"no":1704,"file":"ST-PLAN2.lsp","cmd":"stair-2pp","cat":"繪圖","desc":"樓梯平面圖進階繪製：指定三點後輸入踏寬踏深、階數，繪出踏面、方向箭頭與可註解標示，含單線劃法選項與上下屬性文字。","usage":"執行 stair-2pp → 指定 A、B、C 點 → 於對話框設定踏寬/踏深/階數 → 確定自動繪製","level":9,"lt":"✅","ver":"20260118","author":"chengshunyi / MyCAD","video":"https://youtu.be/tqUgZV_89a8","fas":"fas/ST-PLAN2.fas"},{"no":1705,"file":"ST-PLAN3.LSP","cmd":"stair-2pp-out","cat":"繪圖","desc":"樓梯平面圖含外掛式扶手與鋼梯選項的版本，依比例單位換算並加入可註解功能，繪出踏面、扶手與箭頭文字。","usage":"執行 stair-2pp-out → 指定三點 → 對話框設定踏寬/階數/扶手/鋼梯選項 → 確定自動繪製","level":9,"lt":"✅","ver":"20260118","author":"chengshunyi / MyCAD","video":"https://youtu.be/WnHljBkfyNE","fas":"fas/ST-PLAN3.fas"},{"no":1706,"file":"STAIR CALCULATOR-樓梯計算機.LSP","cmd":"RST","cat":"查詢","desc":"住宅樓梯計算機對話框：輸入兩個高度與階數，計算總高與級高，具計算機按鈕、複製結果功能。","usage":"執行 RST → 在對話框輸入高度1、高度2、階數 → 按 = 計算 → 複製結果","level":6,"lt":"✅","ver":"April 10, 2025","author":"Grok 產生（AI，署名 CADConcepts）","video":"","fas":"fas/STAIR CALCULATOR-樓梯計算機.fas"},{"no":1707,"file":"stair-hr-OP.lsp","cmd":"stair-hr-f-s-d、stair-hr-f-s-s、stair-hr-b-s-d、stair-hr-b-s-s、stair-hr-f-d、stair-hr-f-s、stair-hr-b-d、stair-hr-b-s、stair-hr","cat":"繪圖","desc":"依詳圖繪製樓梯扶手立面，提供前/後位置、起踏/中間層、單/雙線共八種型式指令，並控制圖層與左右方向。","usage":"執行 stair-hr-xx（如 f-s-d）→ 點選起點 → 點選第2階 → 點選終點 → 自動畫扶手與欄杆","level":7,"lt":"✅","ver":"20250422 / 20251003","author":"chengshunyi","video":"https://youtu.be/NSgmd_h3E5Q","fas":"fas/stair-hr-OP.fas"},{"no":1708,"file":"stair-hr-rc-ui.lsp","cmd":"stair-hr-rc-ui","cat":"繪圖","desc":"RC 樓梯扶手欄杆立面對話框版：選繪製模式（起踏層、中間層、頂層、前後方、單雙線）與扶手高度、立桿間隔等參數後自動繪製。","usage":"執行 stair-hr-rc-ui → 對話框設定模式與尺寸 → 確定 → 點選起點、第2階、終點 → 自動繪製","level":8,"lt":"✅","ver":"20250422（檔案日期 2025-10-05）","author":"chengshunyi（MyCAD）","video":"https://youtu.be/iIj8vt3xA_g","fas":"fas/stair-hr-rc-ui.fas"},{"no":1709,"file":"stair-hr-RC.lsp","cmd":"stair-hr-rc-f-s-d、stair-hr-rc-f-s-s、stair-hr-rc-b-s-d、stair-hr-rc-b-s-s、stair-hr-rc-f-d、stair-hr-rc-f-s、stair-hr-rc-b-d、stair-hr-rc-b-s、stair-hr-rc","cat":"繪圖","desc":"依詳圖繪製 RC 樓梯扶手立面，提供前/後、起踏/中間、單/雙線多種指令，自動畫扶手線與欄杆。","usage":"執行 stair-hr-rc-xx → 點選起點 → 點選第2階 → 點選終點 → 自動繪製","level":7,"lt":"✅","ver":"20250422","author":"chengshunyi","video":"https://youtu.be/PZWvpg8cKqc","fas":"fas/stair-hr-RC.fas"},{"no":1710,"file":"stair-hr-ui.lsp","cmd":"stair-hr-ui","cat":"繪圖","desc":"SS 鋼樓梯扶手欄杆立面對話框版：設定扶手高度、踢腳高度、扶手直徑、延伸長度與前後位置、單雙線後自動繪製。","usage":"執行 stair-hr-ui → 對話框設參數與模式 → 確定 → 點選起點、第2階、終點 → 自動繪製","level":8,"lt":"✅","ver":"20250422（檔案日期 2025-10-05）","author":"chengshunyi（MyCAD）","video":"https://youtu.be/S9inOn1eHko","fas":"fas/stair-hr-ui.fas"},{"no":1711,"file":"stair-hr.lsp","cmd":"stair-hr-f-s-d、stair-hr-f-s-s、stair-hr-b-s-d、stair-hr-b-s-s、stair-hr-f-d、stair-hr-f-s、stair-hr-b-d、stair-hr-b-s、stair-hr","cat":"繪圖","desc":"依詳圖繪製樓梯扶手立面，提供前/後位置、起踏/中間層、單/雙線等多種指令，控制圖層與左右方向。","usage":"執行 stair-hr-xx → 點選起點 → 點選第2階 → 點選終點 → 自動繪製扶手","level":7,"lt":"✅","ver":"20250422","author":"chengshunyi","video":"https://youtu.be/NSgmd_h3E5Q","fas":"fas/stair-hr.fas"},{"no":1712,"file":"stair-sec-study.lsp","cmd":"stair-sec-study","cat":"剖面/結構","desc":"樓梯剖面研究：輸入樓層高度與折數，自動計算階數、每折階數與餘階，可增減一階後確認並以聚合線繪出剖面。","usage":"執行 stair-sec-study → 點選起點 → 輸入樓層高度、折數 → 確認或加減階數 → 自動繪製","level":6,"lt":"✅","ver":"20171209","author":"cheng bar","video":"","fas":"fas/stair-sec-study.fas"},{"no":1713,"file":"stair-sec.lsp","cmd":"stair-sec","cat":"剖面/結構","desc":"樓梯剖面參數設計：對話框輸入樓高、級高、折數等條件，自動繪出樓梯剖面、標註尺寸與階數編號，可選往右或往左繪製。","usage":"執行 stair-sec → 對話框設樓高/級高/折數/方向 → 確定 → 點選起點 → 自動繪製剖面與標註","level":9,"lt":"✅","ver":"20261104","author":"chengshunyi / ChengBar (MyCAD)","video":"","fas":"fas/stair-sec.fas"},{"no":1714,"file":"start-dr-gr-xy.lsp","cmd":"start-dr-gr-xy","cat":"繪圖","desc":"選取基地範圍聚合線，依選定方格尺寸（5/10/15/20/25）自動畫出X、Y方格線，供整地土方計算使用。","usage":"執行 start-dr-gr-xy → 選聚合線 → 輸入方格尺寸 → 自動畫方格線（外圍需另行 TRIM）","level":6,"lt":"✅","ver":"20240321","author":"chengshunyi","video":"","fas":"fas/start-dr-gr-xy.fas"},{"no":1715,"file":"Steal.lsp","cmd":"Steal、StealAll、StealTemplate、StealTemplates、StealLast","cat":"圖面管理","desc":"Lee Mac Steal：從另一份 DWG/DWT/DWS 匯入圖塊、圖層、線型、標註樣式、文字樣式、配置等項目到目前圖面，以對話框勾選。","usage":"執行 Steal → 選取來源圖檔 → 對話框勾選要匯入的項目 → 確定匯入","level":9,"lt":"❌","ver":"2022-09-10 (檔案日期)","author":"Lee Mac","video":"","fas":"fas/Steal.fas"},{"no":1716,"file":"steel-box.lsp","cmd":"steel-box","cat":"剖面/結構","desc":"從 boxcol-size.txt 取得鋼構箱型柱尺寸，以對話框選規格後在指定中心繪製箱型斷面（含厚度）與規格文字。","usage":"執行 steel-box → 對話框選規格 → 點選中心位置 → 自動繪製斷面","level":7,"lt":"✅","ver":"20250313","author":"chengshunyi（MyCAD）","video":"","fas":"fas/steel-box.fas"},{"no":1717,"file":"steel-c.LSP","cmd":"steel-c","cat":"剖面/結構","desc":"從 steelc-size.txt 取得 C 形輕型鋼尺寸，以對話框選規格後繪製斷面（含圓角與接合），並記錄尺寸文字。","usage":"執行 steel-c → 對話框選規格 → 點選起始點 → 自動繪製斷面","level":7,"lt":"✅","ver":"20250313","author":"chengshunyi（MyCAD）","video":"","fas":"fas/steel-c.fas"},{"no":1718,"file":"steel-Ca.LSP","cmd":"steel-Ca","cat":"剖面/結構","desc":"從 Steelca-size.txt 取得厚度漸變槽鋼尺寸，以對話框選規格後繪製槽鋼斷面（含圓角）與規格文字。","usage":"執行 steel-Ca → 對話框選規格 → 點選位置 → 自動繪製斷面","level":7,"lt":"✅","ver":"20250313","author":"chengshunyi（MyCAD）","video":"","fas":"fas/steel-Ca.fas"},{"no":1719,"file":"steel-cb.LSP","cmd":"steel-cb","cat":"剖面/結構","desc":"從 Steelcb-size.txt 取得等厚槽鋼尺寸，以對話框選規格後繪製斷面與規格文字。","usage":"執行 steel-cb → 對話框選規格 → 點選起始位置 → 自動繪製斷面","level":7,"lt":"✅","ver":"20250313","author":"chengshunyi（MyCAD）","video":"","fas":"fas/steel-cb.fas"},{"no":1720,"file":"steel-ct.lsp","cmd":"steel-ct","cat":"剖面/結構","desc":"從 ctbeam-size.txt 取得 CT 型鋼尺寸，以對話框選規格後繪製 T 型斷面與規格文字。","usage":"執行 steel-ct → 對話框選規格 → 點選起始位置 → 自動繪製斷面","level":7,"lt":"✅","ver":"20250311","author":"chengshunyi（MyCAD）","video":"","fas":"fas/steel-ct.fas"},{"no":1721,"file":"steel-i.lsp","cmd":"steel-i","cat":"剖面/結構","desc":"從 ibeam-size.txt 取得 H 型鋼（I 型）尺寸，以對話框選規格後繪製斷面，邊畫邊修圓角，標示規格文字。","usage":"執行 steel-i → 對話框選規格 → 點選位置 → 自動繪製 I 型鋼斷面","level":7,"lt":"✅","ver":"20250313","author":"chengshunyi（MyCAD）","video":"","fas":"fas/steel-i.fas"},{"no":1722,"file":"steel-Lab.LSP","cmd":"steel-La、steel-Lb、steel-Lab","cat":"剖面/結構","desc":"從 Steella-size.txt / Steellb-size.txt 取得等邊或不等邊角鋼尺寸，以對話框選規格後繪製 L 型斷面與規格文字。","usage":"執行 steel-La（或 -Lb）→ 對話框選規格 → 點選位置 → 自動繪製斷面","level":7,"lt":"✅","ver":"20250313","author":"chengshunyi（MyCAD）","video":"","fas":"fas/steel-Lab.fas"},{"no":1723,"file":"steel-rh.lsp","cmd":"steel-rh、steel-bh、steel-rhbh","cat":"剖面/結構","desc":"從 rhbeam-size.txt / bhbeam-size.txt 取得 RH、BH 組合型鋼尺寸，以對話框選規格後繪製 H 型鋼斷面與規格文字。","usage":"執行 steel-rh（或 steel-bh）→ 對話框選規格 → 點選起始位置 → 自動繪製斷面","level":7,"lt":"✅","ver":"20250309","author":"chengshunyi（MyCAD）","video":"","fas":"fas/steel-rh.fas"},{"no":1724,"file":"STEP-15.lsp","cmd":"STEP-15","cat":"繪圖","desc":"沿選取的聚合線畫出 0.15 高的階梯底面（下側踏階），自動關閉鎖點與指令回應並將線寬設為 0。","usage":"執行 STEP-15 → 選取一條或多條聚合線 → 自動畫出階梯","level":5,"lt":"✅","ver":"20220716","author":"Kent Cooper（12/20/18）","video":"","fas":"fas/STEP-15.fas"},{"no":1725,"file":"step-room-number.LSP","cmd":"step-room-number2","cat":"圖塊/屬性","desc":"以清單選單選擇房間圖塊／編號樣式後，依步驟對房間編號圖塊屬性進行編號。","usage":"執行 step-room-number2 → 從下拉清單選取項目 → 確定 → 依提示選取圖塊編號","level":6,"lt":"✅","ver":"20220716更新 (檔案日期 2024-11-16)","author":"chengshunyi","video":"","fas":"fas/step-room-number.fas"},{"no":1726,"file":"Stitch.lsp","cmd":"Stitch","cat":"繪圖","desc":"沿選取的線段或聚合線依固定分段距離等量畫出縫線（單線或矩形縫寬區域），可選是否將縫寬納入分段距離。","usage":"執行 Stitch → 回答是否含縫寬、是否用縫寬區域 → 選擇線段 → 自動沿線等量畫縫","level":6,"lt":"✅","ver":"20250923","author":"chengshunyi","video":"","fas":"fas/Stitch.fas"},{"no":1727,"file":"StitchUI.lsp","cmd":"StitchUI","cat":"繪圖","desc":"Stitch 的對話框版：設定分段距離、縫線寬度、縫線長度、是否用矩形縫寬與是否含縫寬，設定存環境變數後選線自動等量畫縫。","usage":"執行 StitchUI → 對話框輸入參數 → 確定 → 選擇線段 → 自動畫縫線","level":7,"lt":"✅","ver":"20250923","author":"chengshunyi","video":"","fas":"fas/StitchUI.fas"},{"no":1728,"file":"STR_PROCESS_TEXTS.LSP","cmd":"STR_PROCESS_TEXTS","cat":"面積/數量統計","desc":"選取 STR-TXT 圖層上如 B1-D10-1000 的文字，依編號排序寫回清單，並依群組加總長度輸出小計。","usage":"執行 STR_PROCESS_TEXTS → 選物件 → 指定排序清單寫入點 → 指定群組總結寫入點 → 自動輸出","level":7,"lt":"✅","ver":"2025-11-29 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/STR_PROCESS_TEXTS.fas"},{"no":1729,"file":"Strikethrough.lsp","cmd":"strike、mstrike、strike2、mstrike2、strike3、mstrike3、under、munder、under2、munder2、overunder2、moverunder2","cat":"文字","desc":"為文字、多行文字或屬性加上刪除線或底線（單、雙、三線及上下線），每種型式有單選與連續多選兩種指令，以聚合線繪製。","usage":"執行 strike（或 under 等）→ 選取文字/MText/屬性 → 自動在其上畫線；m 開頭指令可連續多選","level":7,"lt":"✅","ver":"2022-09-10 (檔案日期)","author":"網路程式（疑 Lee Mac 類）","video":"","fas":"fas/Strikethrough.fas"},{"no":1730,"file":"String_To_UniCode.lsp","cmd":"Str_To_Uni","cat":"文字","desc":"字串轉 Unicode 工具函式庫（如 ABC 轉 \\U+0041...）及十進位轉十六進位，並提供 Str_To_Uni 指令讀取文字轉換。","usage":"執行 Str_To_Uni → 輸入或選取文字 → 輸出 Unicode 編碼","level":5,"lt":"✅","ver":"2024-03-24 (檔案日期)","author":"網路程式（KGA / MT 轉換函式）","video":"","fas":"fas/String_To_UniCode.fas"},{"no":1731,"file":"Stripe.LSP","cmd":"Stripe","cat":"修改","desc":"將選取的聚合線依使用者指定的線段長度與間隔長度切成一段一段的條紋，最後可能留下較長餘段。","usage":"執行 Stripe → 選取聚合線 → 輸入條紋長度 → 輸入間隔長度 → 自動切段","level":6,"lt":"✅","ver":"v1.0 (6-06-2020)；20231215","author":"John F. Uhden","video":"","fas":"fas/Stripe.fas"},{"no":1732,"file":"StripMtext v5-0b.lsp","cmd":"StripMtext、SMT","cat":"文字","desc":"Steve Doman 與 Joe Burke 的 StripMtext v5.0b：以對話框選擇要移除的內嵌格式，批次清除 MText、引線、標註、表格與多行屬性的格式碼。","usage":"執行 SMT → 對話框勾選要清除的格式 → 選取物件 → 完成並顯示處理數量","level":9,"lt":"⚠️","ver":"v5.0b (2010)","author":"Steve Doman、Joe Burke","video":"","fas":"fas/StripMtext v5-0b.fas"},{"no":1733,"file":"StripMtext.lsp","cmd":"StripMtext、SMT","cat":"文字","desc":"Steve Doman 與 Joe Burke 的 StripMtext v5.0b（加授權檢查）：清除 MText、引線、標註、表格、多行屬性的內嵌格式。","usage":"執行 SMT → 對話框勾選要清除的格式 → 選取物件 → 完成","level":9,"lt":"⚠️","ver":"v5.0b (2010)；檔案日期 2024-09-29","author":"Steve Doman、Joe Burke","video":"","fas":"fas/StripMtext.fas"},{"no":1734,"file":"StripMTextFormat.lsp","cmd":"StripMTextFormat","cat":"文字","desc":"清除選取 MText 的內嵌格式，並在對話框選擇文字樣式後統一套用，使用正規表示式清格式。","usage":"執行 StripMTextFormat → 選取 MText → 在對話框選文字樣式 → 套用","level":7,"lt":"⚠️","ver":"2026 (檔案日期 2026-06-05)","author":"ChengBar (MyCAD)","video":"","fas":"fas/StripMTextFormat.fas"},{"no":1735,"file":"sub-Excel.lsp","cmd":"（無，副程式庫）","cat":"轉檔/匯出入","desc":"Terry Miller 的 GetExcel R6 函式庫：連線 Excel，讀取或寫入儲存格、範圍、欄列轉換等子函式，供其他程式匯入匯出 Excel。","usage":"由其他程式載入呼叫（如 GetExcel、PutCell），無單獨指令","level":8,"lt":"❌","ver":"R6 (9-20-03 起，2007 改版)","author":"Terry Miller（部分為 Gilles Chanteau）","video":"","fas":"fas/sub-Excel.fas"},{"no":1736,"file":"SubStrList.lsp","cmd":"SubStrList","cat":"文字","desc":"選取含「=」的文字，取出各數值後以第一個數為基準依序相減，在指定位置寫出相減算式（字高 0.35 x LTSCALE）。","usage":"執行 SubStrList → 選取含等號的文字 → 指定算式放置點 → 自動產生相減算式","level":5,"lt":"✅","ver":"20220716更新 (檔案日期 2026-02-10)","author":"chengshunyi","video":"","fas":"fas/SubStrList.fas"},{"no":1737,"file":"sum-mleader-attr-ui.lsp","cmd":"sum-mleader-attr-ui","cat":"面積/數量統計","desc":"以對話框選擇比例、單位與統計項目（面積、周長或兩者），統計多重引線屬性內的面積周長並以 MText 輸出合計。","usage":"執行 sum-mleader-attr-ui → 對話框設比例單位與統計項目 → 確定 → 選取引線/物件 → 點選位置輸出合計","level":7,"lt":"✅","ver":"2025-11-08 (檔案日期)","author":"chengshunyi（MyCAD）","video":"","fas":"fas/sum-mleader-attr-ui.fas"},{"no":1738,"file":"Sum-TXT.lsp","cmd":"Sum-TXT","cat":"文字","desc":"選取螢幕上多個文字或多行文字，將其數字加總並在指定位置產生含加計算式的總和文字。","usage":"執行 Sum-TXT（或 STX）→ 選取多個文字 → 指定文字位置 → 自動輸出加總","level":4,"lt":"✅","ver":"20231214","author":"Fixo、Reid B.、chengshunyi","video":"","fas":"fas/Sum-TXT.fas"},{"no":1739,"file":"sumMLeaderValues-ui.lsp","cmd":"sumMLeaderValues-ui","cat":"面積/數量統計","desc":"以對話框設定繪圖單位、比例與輸出字高，加總多重引線內容中的面積與周長並以 MText 輸出結果，設定存 INI。","usage":"執行 sumMLeaderValues-ui → 對話框設單位/比例/字高 → 確定 → 選取多重引線 → 點選輸出位置","level":7,"lt":"✅","ver":"2025-11-09 (檔案日期)","author":"MyCAD","video":"","fas":"fas/sumMLeaderValues-ui.fas"},{"no":1740,"file":"sumMLeaderValues-uix.lsp","cmd":"sumMLeaderValues-uix","cat":"面積/數量統計","desc":"MULTILEADER 加總工具對話框版：加總多重引線內的面積與周長並輸出 MText，另可按鈕將結果匯出 Excel。","usage":"執行 sumMLeaderValues-uix → 對話框設單位/比例/字高 → 確定或按匯出 Excel → 選取多重引線","level":8,"lt":"⚠️","ver":"2025-11-09 (檔案日期)","author":"MyCAD","video":"","fas":"fas/sumMLeaderValues-uix.fas"},{"no":1741,"file":"sumMLeaderValues.lsp","cmd":"sumMLeaderValues","cat":"面積/數量統計","desc":"選取多重引線，萃取其文字中的面積與周長並加總，輸出到 MText 並寫入記錄檔（無對話框版）。","usage":"執行 sumMLeaderValues → 輸入或確認單位與比例 → 選取多重引線 → 指定 MText 插入點","level":6,"lt":"✅","ver":"2025-11-09 (檔案日期)","author":"MyCAD","video":"","fas":"fas/sumMLeaderValues.fas"},{"no":1742,"file":"sump_sym.lsp","cmd":"sump_sym","cat":"圖塊/屬性","desc":"集水井（SUMP）自動繪圖：對話框可選既有 SUMP 圖塊帶入參數，設定型式、寬高深、填充密度與字寬後繪製外內框、填充、虛線對角線與標註，可強制更新。","usage":"執行 sump_sym → 對話框選既有圖塊或輸入型式/寬/高/深 → 確定 → 指定插入點 → 自動繪製圖塊","level":8,"lt":"✅","ver":"2026-01-14 (檔案日期)","author":"chengshunyi（MyCAD）","video":"","fas":"fas/sump_sym.fas"},{"no":1743,"file":"SumStrList.lsp","cmd":"SumStrList","cat":"文字","desc":"選取含「=」的文字，擷取等號右邊數字，組成以 + 連接並以 = 總計 結尾的加總算式，於指定位置寫出（字高 0.35 x LTSCALE）。","usage":"執行 SumStrList → 選取含等號的文字 → 指定算式放置點 → 自動產生算式","level":5,"lt":"✅","ver":"20220716更新 (檔案日期 2026-02-10)","author":"chengshunyi","video":"","fas":"fas/SumStrList.fas"},{"no":1744,"file":"SumTxt.lsp","cmd":"SUMTXT","cat":"面積/數量統計","desc":"選取文字或單行文字，依圖層顏色（含 RGB）分類加總數字（可含單位或算式文字），以對話框設定後輸出加總結果到圖面。","usage":"執行 SUMTXT → 對話框設定（含標註字寬）→ 確定 → 選取文字 → 指定位置輸出分色加總","level":9,"lt":"⚠️","ver":"V2.7 (2026-10-29 檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/SumTxt.fas"},{"no":1745,"file":"SW_DRAW.LSP","cmd":"SW_DRAW","cat":"剖面/結構","desc":"剪力牆（SW）圖塊自動繪製：對話框可選既有 SW 圖塊帶入參數，輸入長度、厚度、字寬與填充比例，繪出 SOLID 填充與矩形並建立圖塊（SW-厚x長），可強制更新。","usage":"執行 SW_DRAW → 對話框選既有圖塊或輸入長度/厚度 → 確定 → 指定插入點 → 自動繪製/更新圖塊","level":8,"lt":"✅","ver":"2026-01-14 (檔案日期)","author":"ChengBAR (MyCAD)","video":"","fas":"fas/SW_DRAW.fas"},{"no":1746,"file":"SwapXref.LSP","cmd":"SwapXref","cat":"圖面管理","desc":"外參精確替換工具：輸入舊外參名稱與新外參圖檔，以 Overlay 方式重新掛載並更新所有舊外參插入點，清理模型空間殘留。","usage":"執行 SwapXref → 對話框輸入舊外參圖塊名稱與新圖檔名稱 → 確定 → 自動替換","level":8,"lt":"✅","ver":"2026-04-14 (檔案日期)","author":"MyCAD","video":"","fas":"fas/SwapXref.fas"},{"no":1747,"file":"SWPOLY.LSP","cmd":"SWPOLY","cat":"繪圖","desc":"選取來源聚合線，沿用其線寬與性質接續繪製新的聚合線。","usage":"執行 SWPOLY → 選取來源聚合線 → 指定起點 → 依 PLINE 提示繼續畫","level":3,"lt":"✅","ver":"20240811","author":"chengshunyi","video":"","fas":"fas/SWPOLY.fas"},{"no":1748,"file":"SYM-LIB.lsp","cmd":"SYM-LIB","cat":"圖塊/屬性","desc":"讀取 C:\\\\SUPPORT4\\\\SYM 的 SYM.bss 幻燈片庫，以圖示對話框瀏覽符號圖塊並插入圖面。","usage":"執行 SYM-LIB → 在圖示對話框點選符號 → 指定插入點 → 插入圖塊","level":6,"lt":"✅","ver":"20231223","author":"chengshunyi","video":"","fas":"fas/SYM-LIB.fas"},{"no":1749,"file":"SYS3.LSP","cmd":"sys3_1、sys3_2","cat":"其他","desc":"列出 AutoLISP 所有已定義的功能函數與變數：sys3_1 以 write-line 寫入 family_w.txt，sys3_2 以 princ 寫入並用記事本開啟，並以 DCL 清單顯示。","usage":"執行 sys3_1 或 sys3_2 → 自動輸出清單檔並開啟記事本／對話框","level":4,"lt":"⚠️","ver":"2023-02-11 (檔案日期)","author":"—","video":"","fas":"fas/SYS3.fas"},{"no":1750,"file":"sys60.LSP","cmd":"sys60","cat":"3D","desc":"以對話框輸入階數、總寬、總高、階梯深度後，指定左下角點繪製 2D 樓梯輪廓並 EXTRUDE 拉伸成 3D 樓梯模型，再以 VPOINT、HIDE 檢視。","usage":"執行 sys60 → 對話框輸入階數/寬/高/深度 → 確定 → 選取左下角點 → 自動建立 3D 樓梯","level":6,"lt":"❌","ver":"2025-10-20 (檔案日期)","author":"—","video":"","fas":"fas/sys60.fas"},{"no":1751,"file":"SysVarMgr-4.lsp","cmd":"SVM-Reg、SVM-Dwg、SVM-Tmp、SVM-RO、SysVarMgr-4","cat":"系統/授權","desc":"系統變數分層管理工具 V15：以對話框分別管理登錄全域（含 WHIPTHREAD、LAYOUTREGENCTL、VTENABLE、GRIPOBJLIMIT 等效能變數）、圖檔、暫存與唯讀變數。","usage":"執行 SysVarMgr-4（或 SVM-Reg/Dwg/Tmp/RO）→ 對話框調整變數 → 確定套用或恢復預設","level":8,"lt":"✅","ver":"V15 (20260222)","author":"chengshunyi","video":"","fas":""},{"no":1752,"file":"SysVarUI-5.LSP","cmd":"SYSVARUI-5","cat":"系統/授權","desc":"以對話框勾選與設定系統變數（AUTOPLACEMENT、BLOCKSDATACOLLECTION、PLACEMENTSWITCH、UCSDETECT、WHIPTHREAD 等）並套用。","usage":"執行 SYSVARUI-5 → 對話框勾選設定 → 確定套用","level":6,"lt":"✅","ver":"2025-12-12 (檔案日期)","author":"chengshunyi","video":"https://youtu.be/rcjOwrmi15g","fas":""},{"no":1753,"file":"SYSVARUIV2.lsp","cmd":"SYSVARUIV2","cat":"系統/授權","desc":"以對話框勾選與設定常用系統變數（APBOX、ATTDIA、ATTREQ、FILEDIA、TEXTFILL、FILLMODE、OSNAPHATCH、XCLIPFRAME、MEASUREMENT 等）並套用。","usage":"執行 SYSVARUIV2 → 對話框勾選設定 → 確定套用","level":6,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"chengshunyi","video":"","fas":""},{"no":1754,"file":"T2M-LT.LSP","cmd":"T2M-LT","cat":"文字","desc":"點選一個物件取得圖層後，將該圖層所有 TEXT 轉成寬度0的 MTEXT，插入點取幾何中心並設正中對齊，保留內容、字高、樣式與旋轉，轉換後亮顯。","usage":"執行 T2M-LT → 點選目標圖層上的物件 → 自動轉換並亮顯 → 可 Undo 一次還原","level":6,"lt":"✅","ver":"2026-04-26 (檔案日期)","author":"MyCAD","video":"","fas":"fas/T2M-LT.fas"},{"no":1755,"file":"T2SS.LSP","cmd":"T2SS","cat":"文字","desc":"將圖面所有 Text、MText（含圖塊內、屬性與屬性定義）的文字樣式統一改為 Standard，並同步屬性（ATTSYNC）與重生。","usage":"執行 T2SS → 自動全圖改文字樣式 → 重生","level":5,"lt":"✅","ver":"2026-10-17 (檔案日期)","author":"網路程式（Text to Standard Style）、chengshunyi","video":"","fas":"fas/T2SS.fas"},{"no":1756,"file":"table-renumber.lsp","cmd":"table-renumber-all、table-renumber-all-chr、table-renumber-have-value-0、table-renumber-have-value-1、table-renumber-have-value","cat":"文字","desc":"點選表格後將表格編號欄重新依序編號：全部重編（數字或字母）、僅有資料的列重編，起始可由 0 或 1 開始。","usage":"執行 table-renumber-xx → 點選表格 → 自動重編序號","level":5,"lt":"✅","ver":"20241221","author":"chengshunyi","video":"","fas":"fas/table-renumber.fas"},{"no":1757,"file":"table-renumberall.LSP","cmd":"table-renumberall","cat":"文字","desc":"選取表格，取得儲存格內容並對表格編號欄全部重編，另含 Lee Mac 的由表格儲存格取得圖塊名稱函式。","usage":"執行 table-renumberall → 選取表格 → 自動重編序號","level":5,"lt":"✅","ver":"2024-12-11 (檔案日期)","author":"Lee Mac、chengshunyi","video":"","fas":"fas/table-renumberall.fas"},{"no":1758,"file":"TableDelLastChar.lsp","cmd":"TableDelLastChar","cat":"文字","desc":"點擊表格儲存格，自該列起往下將該欄每個儲存格的最後一個字元刪除。","usage":"執行 TableDelLastChar → 點擊表格儲存格 → 自動處理該欄","level":4,"lt":"✅","ver":"2026-04-12 (檔案日期)","author":"MyCAD","video":"","fas":"fas/TableDelLastChar.fas"},{"no":1759,"file":"Tag-renum-ByType.lsp","cmd":"Tag-renum-ByType","cat":"圖塊/屬性","desc":"全圖搜尋有屬性圖塊，依 LAYER 屬性值分類，各類別依插入點位置（Y 降序、X）排序後，在 ID 屬性寫入分類編號，並顯示分群結果。","usage":"執行 Tag-renum-ByType → 自動掃描全圖屬性圖塊 → 依類別與位置編號 → 顯示分群結果","level":7,"lt":"✅","ver":"20250722","author":"chengshunyi","video":"https://youtu.be/hjTbmOA9a2A","fas":"fas/Tag-renum-ByType.fas"},{"no":1760,"file":"TagByTypeNow.LSP","cmd":"TagByTypeNow","cat":"圖塊/屬性","desc":"依 LAYER 屬性值把有屬性圖塊分類，各類依插入點先 Y 後 X 排序編號，寫入分類編號並顯示分群結果。","usage":"執行 TagByTypeNow → 自動掃描屬性圖塊 → 依類別與位置編號 → 顯示結果","level":7,"lt":"✅","ver":"20250722 (檔案日期)","author":"chengshunyi","video":"","fas":"fas/TagByTypeNow.fas"},{"no":1761,"file":"TagSuffixBatch.LSP","cmd":"TagSuffixBatch","cat":"圖塊/屬性","desc":"選取一個圖塊後，以對話框挑選屬性 Tag 並輸入前置、後置字串，批次修改全圖同名圖塊該屬性值。","usage":"執行 TagSuffixBatch → 選取圖塊 → 對話框選 Tag 與前後置字串 → 確定批次修改","level":6,"lt":"✅","ver":"20250724","author":"AI（Copilot）、chengshunyi","video":"","fas":"fas/TagSuffixBatch.fas"},{"no":1762,"file":"TagSuffixDCL.lsp","cmd":"TagSuffixDCL","cat":"圖塊/屬性","desc":"選取圖塊參考後，在對話框挑選屬性 Tag 並輸入後置字串，為該圖塊屬性加上字尾。","usage":"執行 TagSuffixDCL → 選取圖塊 → 對話框選 Tag 與後置字串 → 確定更新","level":6,"lt":"✅","ver":"20250724","author":"chengshunyi","video":"","fas":"fas/TagSuffixDCL.fas"},{"no":1763,"file":"tank-sec-out.lsp","cmd":"tank-sec-out","cat":"剖面/結構","desc":"水箱剖面自動繪製（外部版）：對話框輸入水箱長高、分隔高度、夾層版厚、頂板厚、壁厚、水位頂空隙等，自動繪製剖面、水位虛線、爬梯與尺寸標註。","usage":"執行 tank-sec-out → 對話框輸入尺寸參數 → 確定 → 指定水箱左下角點 → 自動繪製","level":8,"lt":"✅","ver":"20221223","author":"chengshunyi","video":"","fas":"fas/tank-sec-out.fas"},{"no":1764,"file":"tank-sec-r1.lsp","cmd":"tank-sec-r1","cat":"剖面/結構","desc":"水箱剖面自動繪製（r1 版）：對話框輸入水箱各項尺寸，繪製剖面、水位虛線、爬梯並標註尺寸。","usage":"執行 tank-sec-r1 → 對話框輸入尺寸參數 → 確定 → 指定左下角點 → 自動繪製","level":8,"lt":"✅","ver":"20221223 (檔案日期 2023-01-09)","author":"chengshunyi","video":"","fas":"fas/tank-sec-r1.fas"},{"no":1765,"file":"tank-sec.lsp","cmd":"tank-sec","cat":"剖面/結構","desc":"水箱剖面自動繪製：對話框輸入水箱尺寸，繪製剖面、水位線、爬梯與尺寸標註，並於 20250718 版新增水量計算。","usage":"執行 tank-sec → 對話框輸入尺寸參數 → 確定 → 指定左下角點 → 自動繪製並顯示水量","level":8,"lt":"✅","ver":"20250718","author":"chengshunyi","video":"","fas":"fas/tank-sec.fas"},{"no":1766,"file":"TAP.lsp","cmd":"TAP","cat":"文字","desc":"TextAlignPro：以對話框設定文字樣式、基準對齊與軸向排列，將選取的 Text/MText 正中對齊並沿軸向對齊排列，先清洗寬度與對齊點。","usage":"執行 TAP → 對話框設定樣式/對齊/軸向 → 確定 → 選取文字 → 自動對齊排列","level":8,"lt":"✅","ver":"2026-06-06 (檔案日期)","author":"MyCAD","video":"","fas":"fas/TAP.fas"},{"no":1767,"file":"TC-TEST.lsp","cmd":"TC、TextCalc","cat":"文字","desc":"Lee Mac 文字計算機（中文化）：以對話框對文字、屬性、引線、標註中的數字進行四則運算，可將計算結果寫回圖面，已改用純 Lisp 提取數字（不依賴 RegExp）。","usage":"執行 TC → 選取含數字的文字 → 於對話框按 + - * / 運算 → 將結果寫到圖面","level":8,"lt":"✅","ver":"2024 修復版（檔案日期 2026-02-06）","author":"Lee Mac；cheng bar 中文化 2021-08-28","video":"","fas":"fas/TC-TEST.fas"},{"no":1768,"file":"TC-TEST4.lsp","cmd":"TC、TextCalc","cat":"文字","desc":"Lee Mac 文字計算機（強化版）：對話框即時預覽，加強四則運算先乘除後加減，數字取自文字、屬性、引線、標註並可寫回，除以零會警告。","usage":"執行 TC → 選取含數字的文字 → 對話框按運算符並預覽 → 將結果寫到圖面","level":8,"lt":"✅","ver":"2024 強化版（檔案日期 2026-02-06）","author":"Lee Mac；cheng bar 中文化","video":"","fas":"fas/TC-TEST4.fas"},{"no":1769,"file":"tcf.LSP","cmd":"tcf","cat":"文字","desc":"詞庫功能：以對話框管理詞庫清單（可直接新增、刪除、排序），可從圖上選取字串加入詞庫，選用詞條後依比例與單位在圖面插入文字，並自動加抬頭。","usage":"執行 tcf → 對話框選詞條或編輯詞庫 → 確定 → 指定插入點 → 放置文字","level":8,"lt":"✅","ver":"20240706","author":"chengshunyi、pBe（讀檔最佳化）","video":"","fas":"fas/tcf.fas"},{"no":1770,"file":"TCHANGE.LSP","cmd":"tchange","cat":"文字","desc":"選取文字物件後選擇要修改的屬性（樣式、顏色、標高、厚度、圖層、字高、寬度比例、傾斜角等），批次套用新值。","usage":"執行 tchange → 選取文字 → 選擇修改項目並輸入新值 → 自動套用","level":6,"lt":"✅","ver":"20220716更新","author":"網路程式（TCHANGE，類似 CHANGE 的文字版）","video":"","fas":"fas/TCHANGE.fas"},{"no":1771,"file":"TCount.lsp","cmd":"tCount","cat":"面積/數量統計","desc":"Lee Mac Text Count：統計選取的文字、多行文字、引線、標註覆寫文字與圖塊屬性中各字串出現次數，並以 ACAD Table 產出統計表。","usage":"執行 tCount → 選取文字或物件 → 指定表格插入點 → 自動產生字串計數表","level":7,"lt":"✅","ver":"1.1 (05.08.2011)","author":"Lee Mac","video":"","fas":"fas/TCount.fas"},{"no":1772,"file":"TCountV.lsp","cmd":"tCountV","cat":"面積/數量統計","desc":"Lee Mac Text Count 變體：統計選取文字、引線、標註與屬性中各字串出現次數，輸出為 ACAD Table 統計表。","usage":"執行 tCountV → 選取文字或物件 → 指定表格插入點 → 自動產生計數表","level":7,"lt":"✅","ver":"1.1 (05.08.2011)；檔案日期 2023-02-08","author":"Lee Mac","video":"","fas":"fas/TCountV.fas"},{"no":1773,"file":"test-20231223.LSP","cmd":"bro、cmb、Test1、TEST2","cat":"圖塊/屬性","desc":"測試程式：bro 批次旋轉選取的圖塊；cmb 統計圖面中鏡射過的圖塊數量；Test1/TEST2 為測試指令。","usage":"執行 bro → 選取圖塊 → 輸入旋轉角度；執行 cmb → 顯示鏡射圖塊總數","level":5,"lt":"✅","ver":"2023-12-26 (檔案日期)","author":"—","video":"https://youtu.be/X0-Et1bM3RE","fas":"fas/test-20231223.fas"},{"no":1774,"file":"TEST-20240213.lsp","cmd":"test","cat":"繪圖","desc":"測試用小程式，點選右上角後以 PLINE 畫出矩形輪廓並用 CHPROP 修改剛畫的物件屬性。","usage":"執行 test → 點選右上角點 → 自動繪製聚合線並變更屬性","level":2,"lt":"✅","ver":"2024-02-13 (檔案日期)","author":"—","video":"","fas":"fas/TEST-20240213.fas"},{"no":1775,"file":"TEST-AUTOCODE.lsp","cmd":"AutoCode","cat":"圖塊/屬性","desc":"點選圖塊屬性後以對話框設定前綴、位數與間隔，將流水編碼套用到相同名稱的圖塊屬性。","usage":"執行 AutoCode → 點選圖塊屬性 → 在對話框設定前綴/位數 → 確定 → 套用編碼","level":6,"lt":"✅","ver":"2025-07-20 (檔案日期)","author":"Copilot + ShunYi","video":"","fas":"fas/TEST-AUTOCODE.fas"},{"no":1776,"file":"test-font.lsp","cmd":"test-shxfont、test-bigfont","cat":"文字","desc":"依選取字串建立 SHX 或 SHX+大字體的文字樣式，並以範例中英文字串排出各字型的顯示效果供比對。","usage":"執行 test-shxfont 或 test-bigfont → 輸入/點選字型名稱 → 指定位置 → 自動寫出英文字母與中文測試字串","level":5,"lt":"✅","ver":"20240101","author":"chengshunyi","video":"","fas":"fas/test-font.fas"},{"no":1777,"file":"test-offset.LSP","cmd":"testoffset","cat":"修改","desc":"以 ActiveX vla-offset 將選取物件向兩側各偏移約 7.5 單位的測試程式。","usage":"執行 testoffset → 選取物件 → 自動向兩側偏移","level":1,"lt":"✅","ver":"2024-05-26 (檔案日期)","author":"—","video":"","fas":"fas/test-offset.fas"},{"no":1778,"file":"test-re-cal.lsp","cmd":"my-re-cal","cat":"文字","desc":"選取圖面算式文字，以三層（加減、乘除、括號）遞迴解析器計算後，在等號後寫回結果並可設定小數位數。","usage":"執行 my-re-cal → 輸入小數位數 → 選取算式文字 → 自動更新為「算式=結果」","level":7,"lt":"✅","ver":"2026-01-10 (檔案日期)","author":"—","video":"","fas":"fas/test-re-cal.fas"},{"no":1779,"file":"test-temp.LSP","cmd":"boline","cat":"繪圖","desc":"選取封閉 PLINE 後以遞迴三角形分割演算法自動繪出分割線，並含多個點線幾何判斷副程式。","usage":"執行 boline → 選取聚合線 → 自動繪製分割線","level":9,"lt":"✅","ver":"20241121","author":"chengshunyi","video":"","fas":"fas/test-temp.fas"},{"no":1780,"file":"test.lsp","cmd":"test","cat":"其他","desc":"遍歷圖塊定義與選取圖塊/標註/引線，測試圖塊名稱與顏色物件處理的雜項測試程式。","usage":"執行 test → 依程式內固定條件選取物件 → 輸出測試結果","level":5,"lt":"⚠️","ver":"2023-04-23 (檔案日期)","author":"—","video":"","fas":"fas/test.fas"},{"no":1781,"file":"test2.lsp","cmd":"DrawSiteSecProfile","cat":"剖面/結構","desc":"先以序號比對授權碼驗證，通過後輸入垂直比例（全域記憶）繪製基地剖面線型。","usage":"執行 DrawSiteSecProfile → 輸入授權碼 → 輸入垂直比例 → 依提示繪製剖面","level":6,"lt":"✅","ver":"2025-12-21 (檔案日期)","author":"—","video":"","fas":"fas/test2.fas"},{"no":1782,"file":"testxxx.LSP","cmd":"GetRecentFileCount、SetRecentFileCount","cat":"系統/授權","desc":"讀取與修改登錄機碼，調整應用程式選單(0-50)與開啟對話框(0-9)的最近使用檔案數量上限。","usage":"執行 GetRecentFileCount 查看目前值 → 執行 SetRecentFileCount → 輸入兩個上限 → 重啟 AutoCAD","level":4,"lt":"✅","ver":"2026-08-02 (檔案日期)","author":"—","video":"","fas":""},{"no":1783,"file":"Text-AH.lsp","cmd":"TAH-Y、TAH-X、Text-AH","cat":"對齊/排列","desc":"將多個文字依各自對齊點對齊到指定 X 或 Y 座標，TAH-Y 對齊水平基準、TAH-X 對齊垂直基準。","usage":"執行 TAH-Y 或 TAH-X → 指定基準座標點 → 選取要對齊的文字 → 自動移動","level":3,"lt":"✅","ver":"04/07/97 (檔案日期 2025-06-11)","author":"Jeff Foster","video":"","fas":"fas/Text-AH.fas"},{"no":1784,"file":"Text-Box.LSP","cmd":"TB、Text-Box","cat":"文字","desc":"為選取的文字、多行文字或標註畫出外框聚合線，可用於修剪背景或計算表格欄寬。","usage":"執行 TB → 選取文字/MTEXT/標註 → 自動繪出外框聚合線","level":4,"lt":"✅","ver":"Rev 2 (4-20-06)","author":"Terry Miller","video":"","fas":"fas/Text-Box.fas"},{"no":1785,"file":"TEXT-MO.LSP","cmd":"text-mo","cat":"對齊/排列","desc":"以幻燈片圖示選單修改文字：X 或 Y 對齊、改為左/中對齊、依行距由上而下等距排列。","usage":"執行 text-mo → 在圖示選單點選功能 → 確定 → 依提示點選基準文字並選取文字","level":6,"lt":"✅","ver":"86.8.13 90.7.4","author":"—","video":"","fas":"fas/TEXT-MO.fas"},{"no":1786,"file":"text-put-block-att.lsp","cmd":"text-put-block-att","cat":"圖塊/屬性","desc":"選圖塊屬性取得圖塊名與標籤後，依文字圖層窗選文字，把文字內容依位置填入對應圖塊的屬性值。","usage":"執行 text-put-block-att → 點選圖塊屬性 → 選文字所在圖層 → 窗選文字 → 自動寫入屬性","level":6,"lt":"✅","ver":"20240812","author":"chengshunyi","video":"","fas":"fas/text-put-block-att.fas"},{"no":1787,"file":"TEXT-WF.lsp","cmd":"TEXT-WF","cat":"文字","desc":"一次選取全圖所有單行文字，統一修改字體寬度比例。","usage":"執行 TEXT-WF → 輸入寬度比例 → 自動修改全圖 TEXT","level":2,"lt":"✅","ver":"20230312","author":"chengshunyi","video":"","fas":"fas/TEXT-WF.fas"},{"no":1788,"file":"Text2Beam.lsp","cmd":"beam-2line、TextBeam","cat":"3D","desc":"選兩條線或選梁編號文字後搜尋範圍內線段，合併為封閉聚合線並轉面域，拉伸成固定高度 50 的 3D 梁實體。","usage":"執行 beam-2line → 選第 1、2 條線；或執行 TextBeam → 選文字 → 自動找線、建 REGION 並 EXTRUDE","level":7,"lt":"❌","ver":"2025-11-27 (檔案日期)","author":"—","video":"","fas":"fas/Text2Beam.fas"},{"no":1789,"file":"text2CSV.LSP","cmd":"text2CSV","cat":"轉檔/匯出入","desc":"依圖層過濾選取單行與多行文字，連同座標輸出成 CSV 檔，並可用視窗選擇輸出資料夾。","usage":"執行 text2CSV → 輸入圖層名稱 → 選擇輸出資料夾 → 輸入檔名 → 產生 CSV","level":6,"lt":"⚠️","ver":"2025-05-06 (檔案日期)","author":"—","video":"","fas":"fas/text2CSV.fas"},{"no":1790,"file":"text2excel-RTC.LSP","cmd":"text2excel-RTC","cat":"轉檔/匯出入","desc":"選取多列文字，依座標列行關係轉置後輸出成 CSV 並以檔案總管開啟，將圖面的列轉成 Excel 的行。","usage":"執行 text2excel-RTC → 選取多列文字 → 自動輸出 .csv 並開啟","level":6,"lt":"✅","ver":"20230412","author":"chengshunyi","video":"","fas":"fas/text2excel-RTC.fas"},{"no":1791,"file":"text2field.lsp","cmd":"t2f","cat":"文字","desc":"選取面積、長度或標註物件，建立可隨物件更新的 Field 欄位並寫入文字或表格儲存格，支援計算式與格式。","usage":"執行 t2f → 選取圖形/標註 → 指定放置點或表格儲存格 → 自動建立關聯欄位","level":7,"lt":"✅","ver":"20231227","author":"chengshunyi（含 Lee Mac LM 函式）","video":"","fas":"fas/text2field.fas"},{"no":1792,"file":"text2MY.LSP","cmd":"text2MY","cat":"文字","desc":"一次建立 MY- 系列標準文字樣式（空間名稱、說明註解、規範說明、尺寸等），使用 danny 與 chineset 字型。","usage":"執行 text2MY → 自動建立所有 MY- 文字樣式","level":4,"lt":"✅","ver":"20231021","author":"chengshunyi","video":"","fas":"fas/text2MY.fas"},{"no":1793,"file":"text2table.LSP","cmd":"text2table","cat":"文字","desc":"將選取的單行文字、多行文字、引線、標註與屬性內容依位置整理成 AutoCAD 表格物件。","usage":"執行 text2table → 選取文字物件 → 指定表格插入點 → 自動建立表格","level":6,"lt":"✅","ver":"2021-11-07 (檔案日期)","author":"Lee Mac","video":"","fas":"fas/text2table.fas"},{"no":1794,"file":"text2TG.LSP","cmd":"text2TG","cat":"文字","desc":"一次建立 TG- 系列標準文字樣式（空間名稱、說明註解、規範說明、尺寸），並指定 danny 與 chineset 字型。","usage":"執行 text2TG → 自動建立所有 TG- 文字樣式","level":4,"lt":"✅","ver":"20220827","author":"chengshunyi","video":"","fas":"fas/text2TG.fas"},{"no":1795,"file":"TEXT2WORD.lsp","cmd":"demo2","cat":"轉檔/匯出入","desc":"開啟或建立 Word 應用程式並載入選定文件，將文字寫入指定行的示範程式。","usage":"執行 demo2 → 選取 Word 文件 → 自動寫入文字 → 等待關閉 Word","level":8,"lt":"❌","ver":"2025-06-27 (檔案日期)","author":"—","video":"","fas":"fas/TEXT2WORD.fas"},{"no":1796,"file":"text2協力廠商.lsp","cmd":"text2協力廠商","cat":"文字","desc":"建立 TG-協力廠商 文字樣式，並將選取的文字與多行文字改套用該樣式。","usage":"執行 text2協力廠商 → 選取文字/MTEXT → 自動改為 TG-協力廠商 樣式","level":4,"lt":"✅","ver":"2022-08-27 (檔案日期)","author":"Tharwat（改寫）","video":"","fas":"fas/text2協力廠商.fas"},{"no":1797,"file":"TEXT_TO_TXT_FILE-SD.LSP","cmd":"TEXT_TO_TXT_FILE-SD","cat":"轉檔/匯出入","desc":"以對話框指定檔名與儲存資料夾，將選取的 RC 梁編號尺寸文字解析後匯出成 TXT 資料檔。","usage":"執行 TEXT_TO_TXT_FILE-SD → 對話框輸入檔名/瀏覽資料夾 → 確定 → 選取文字 → 寫出 TXT","level":7,"lt":"✅","ver":"2026-01-24 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/TEXT_TO_TXT_FILE-SD.fas"},{"no":1798,"file":"TEXT_TO_TXT_FILE.lsp","cmd":"TEXT_TO_TXT_FILE","cat":"轉檔/匯出入","desc":"選取梁編號尺寸文字，解析 W X H 與 KEY-DIM 格式後寫入 TEMP 的 PROJECT_DATA.TXT 並讀回驗證。","usage":"執行 TEXT_TO_TXT_FILE → 選取 TEXT 字串 → 自動寫入暫存 TXT","level":7,"lt":"✅","ver":"2025-11-29 (檔案日期)","author":"—","video":"","fas":"fas/TEXT_TO_TXT_FILE.fas"},{"no":1799,"file":"TEXT_TO_TXT_FILENAME.LSP","cmd":"TEXT_TO_TXT_FILENAME","cat":"轉檔/匯出入","desc":"選取梁編號文字後，以對話框修改儲存檔名與目錄，將解析結果匯出成 TXT，並以全域變數記憶設定。","usage":"執行 TEXT_TO_TXT_FILENAME → 選取文字 → 對話框輸入檔名/目錄 → 確定 → 寫出 TXT","level":7,"lt":"✅","ver":"2026-04-25 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/TEXT_TO_TXT_FILENAME.fas"},{"no":1800,"file":"TextBBox2-3Dsolid-SD.LSP","cmd":"TextBBox2-3Dsolid-SD","cat":"3D","desc":"選取梁編號文字後自動搜尋週邊梁線，擠出為 3D 梁實體並於文字標註梁長，高度優先採外部 TXT，含對話框設定。","usage":"執行 TextBBox2-3Dsolid-SD → 對話框設定切線長度/高度/字高/TXT 路徑 → 確定 → 選取梁編號文字 → 自動建 3D 梁","level":8,"lt":"❌","ver":"20260124","author":"ChengBar (MyCAD)","video":"","fas":"fas/TextBBox2-3Dsolid-SD.fas"},{"no":1801,"file":"TextBBox2-3Dsolid.lsp","cmd":"TextBBox2-3Dsolid","cat":"3D","desc":"選取多個梁編號文字，依圖層對應過濾梁線並讀取 TXT 梁尺寸，自動擠出 3D 梁實體（無對話框版）。","usage":"執行 TextBBox2-3Dsolid → 輸入切線長度 → 選取梁編號文字 → 自動建 3D 梁","level":8,"lt":"❌","ver":"20251127","author":"—","video":"","fas":"fas/TextBBox2-3Dsolid.fas"},{"no":1802,"file":"TextCalc-LT.lsp","cmd":"TC-LT、TextCalc-LT","cat":"文字","desc":"選取含數字的文字，在對話框內以加減乘除先乘除後加減連續運算，並可把結果寫回圖面；LT 相容版，不依賴 RegExp。","usage":"執行 TC-LT → 點選數字文字 → 對話框按 + - * / 連續選取 → 按寫到圖面 → 指定位置","level":6,"lt":"✅","ver":"2025 更新 (檔案日期 2026-02-08)","author":"Lee Mac（cheng bar 中文化改寫）","video":"","fas":"fas/TextCalc-LT.fas"},{"no":1803,"file":"TextCalc.lsp","cmd":"TC、TextCalc","cat":"文字","desc":"Lee Mac 文字計算機中文化版，點選含數字的文字後在對話框中累加運算，並可將計算式與結果寫成 MText。","usage":"執行 TC → 點選數字文字 → 對話框選運算符號連續選取 → 按將計算結果寫到圖面 → 指定位置","level":6,"lt":"❌","ver":"2021 中文化 (檔案日期 2026-10-17)","author":"Lee Mac（cheng bar 中文化）","video":"","fas":"fas/TextCalc.fas"},{"no":1804,"file":"TextCalcV1-0.lsp","cmd":"TC、TextCalc","cat":"文字","desc":"Lee Mac Text Calculator 1.0 原始英文版，點選含數字文字後於對話框加減乘除並可輸出 MText。","usage":"執行 TC → 點選數字文字 → 對話框選運算符號 → 輸出結果到圖面","level":6,"lt":"❌","ver":"Version 1.0 07-04-2011","author":"Lee Mac","video":"","fas":"fas/TextCalcV1-0.fas"},{"no":1805,"file":"TextConverter.lsp","cmd":"TextConverter","cat":"文字","desc":"點選樣板文字取得圖層過濾，框選該圖層文字後以對話框選字型樣式，批次轉換格式並統一為正中對齊。","usage":"執行 TextConverter → 點選樣板文字 → 框選要轉換的文字 → 對話框選字型樣式 → 確定","level":7,"lt":"❌","ver":"2026-06-05 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/TextConverter.fas"},{"no":1806,"file":"TEXTEXTR.LSP","cmd":"textextr","cat":"轉檔/匯出入","desc":"選取一批文字，先依 Y 值再依 X 值排序後依序寫入文字檔。","usage":"執行 textextr → 輸入檔名 → 選取文字 → 自動排序並寫出","level":6,"lt":"✅","ver":"2022-07-16 (檔案日期)","author":"—","video":"","fas":"fas/TEXTEXTR.fas"},{"no":1807,"file":"TextOpt.LSP","cmd":"TextOpt","cat":"圖面管理","desc":"對話框快速切換文字顯示模式：正常（出圖）、快速、極速（僅外框），自動設定 TEXTFILL、QTEXT 與 TEXTQLTY。","usage":"執行 TextOpt → 選擇正常/快速/極速模式 → 確定 → 自動 REGEN","level":6,"lt":"✅","ver":"2026-04-06 (檔案日期)","author":"—","video":"","fas":""},{"no":1808,"file":"TextReviewByObj.lsp","cmd":"TextReviewByObj","cat":"圖塊/屬性","desc":"點選屬性或物件後依圖塊名稱篩選，可逐一縮放檢視、分析缺號、跳至最後一號或模糊搜尋編號。","usage":"執行 TextReviewByObj → 點選屬性 → 對話框選排序/縮放高度 → 按逐一檢視、檢查缺號、最後一號或找編號","level":7,"lt":"✅","ver":"Copyright 2026 (檔案日期 2026-06-13)","author":"ChengBar (MyCAD)","video":"","fas":"fas/TextReviewByObj.fas"},{"no":1809,"file":"texts2table.lsp","cmd":"texts2table","cat":"文字","desc":"選取多個單行文字，依指定欄數與字高排成表格物件，並設定儲存格對齊。","usage":"執行 texts2table → 指定表格左上角 → 輸入欄數與字高 → 依序點選文字","level":5,"lt":"✅","ver":"20220201","author":"—","video":"","fas":"fas/texts2table.fas"},{"no":1810,"file":"TextToMLeaderUI.LSP","cmd":"TextToMLeaderUI","cat":"標註","desc":"對話框選擇多重引線樣式後，將選取的文字依字高五倍偏移建立 MLEADER 並刪除原文字。","usage":"執行 TextToMLeaderUI → 對話框選 MLEADER 樣式 → 確定 → 選取文字 → 自動轉成多重引線","level":6,"lt":"✅","ver":"20220716 (檔案日期 2025-10-02)","author":"—","video":"","fas":"fas/TextToMLeaderUI.fas"},{"no":1811,"file":"TileLayou.LSP","cmd":"TileLayou","cat":"繪圖","desc":"以對話框設定磁磚寬深與最小/最大磚縫，在矩形範圍內以智能邊緣加均佈模式計算磚數並繪出排磚。","usage":"執行 TileLayou → 對話框輸入磚寬/深、磚縫範圍與模式 → 確定 → 指定範圍 → 自動排磚","level":7,"lt":"✅","ver":"2026-05-17 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":""},{"no":1812,"file":"TILELAYOUT.lsp","cmd":"TileLayout","cat":"繪圖","desc":"在封閉聚合線範圍內自動排磚（支援餘數磚、邊界裁切、向內偏移），並統計各規格磚數量輸出表格或文字。","usage":"執行 TileLayout → 對話框設定磚規格/磚縫/圖層 → 確定 → 選取封閉聚合線 → 自動排磚並產生統計表","level":8,"lt":"✅","ver":"V1.8.1 (2026-10-25)","author":"ChengBar (MyCAD)","video":"","fas":"fas/TILELAYOUT.fas"},{"no":1813,"file":"TLM.lsp","cmd":"TLM","cat":"標註","desc":"表格關聯標記系統：依表格欄位比對圖面文字，以圓圈、實心或文字標記並追蹤對應項目。","usage":"執行 TLM → 對話框選比對欄/分類欄/標記樣式/字高/圖層 → 確定 → 選取表格 → 自動標記","level":7,"lt":"✅","ver":"2026-06-05 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/TLM.fas"},{"no":1814,"file":"tm.LSP","cmd":"TM","cat":"文字","desc":"文字比對：點選樣板文字後，將其他單行文字、多行文字、屬性或標註文字內容取代為相同內容，可連續執行。","usage":"執行 TM → 選取要複製內容的樣板文字 → 連續點選要被取代的文字 → Enter 結束","level":3,"lt":"✅","ver":"Rev 3 (9-7-11)","author":"Terry Miller","video":"","fas":"fas/tm.fas"},{"no":1815,"file":"tml.LSP","cmd":"tml","cat":"面積/數量統計","desc":"選取多重線，依多重線比例分組統計總長度，並在指定位置產生明細 MText。","usage":"執行 tml → 選取多重線 → 指定插入點 → 產生各比例長度與總計","level":6,"lt":"✅","ver":"2022-07-30 (檔案日期)","author":"Jonathan Handojo","video":"","fas":"fas/tml.fas"},{"no":1816,"file":"toolbar-onoff-my.lsp","cmd":"toolbar-onoff-my、toolbar-onoff-EZ、toolbar-onoff-ACAD","cat":"系統/授權","desc":"以 ActiveX 一次顯示或隱藏 MY_CAD_PRO 選單群組中的自訂工具列，分為 My 系列、EZ 系列與 ACAD 預設三組。","usage":"執行 toolbar-onoff-my / -EZ / -ACAD → 工具列依清單批次開關","level":5,"lt":"✅","ver":"20250430","author":"chengshunyi","video":"","fas":""},{"no":1817,"file":"TOTAL-AREA-hatch-BYLAYER.lsp","cmd":"TOTAL-AREA-hatch-BYLAYER","cat":"面積/數量統計","desc":"選取含填充線在內的物件，讀取 Area 屬性依圖層分組加總面積並列出各圖層明細。","usage":"執行 TOTAL-AREA-hatch-BYLAYER → 選取物件(含 HATCH) → 命令列顯示各圖層面積與總計","level":5,"lt":"✅","ver":"12/2005 (檔案日期 2022-10-29)","author":"AAC Solutions (www.aac-solutions.cz)","video":"","fas":"fas/TOTAL-AREA-hatch-BYLAYER.fas"},{"no":1818,"file":"TOTAL-AREA-Pline-BYLAYER.lsp","cmd":"TOTAL-AREA-Pline-BYLAYER","cat":"面積/數量統計","desc":"選取圓、橢圓、聚合線、雲形線，依圖層分組累加面積並轉為 m2，列出各圖層明細與總計。","usage":"執行 TOTAL-AREA-Pline-BYLAYER → 選取封閉物件 → 命令列顯示各圖層面積與總計","level":5,"lt":"✅","ver":"20231107","author":"AAC Solutions，chengshunyi 增修","video":"","fas":"fas/TOTAL-AREA-Pline-BYLAYER.fas"},{"no":1819,"file":"TOTAL.LSP","cmd":"total","cat":"面積/數量統計","desc":"選取一批數字文字後加總，並在指定位置寫出 TOTAL= 加總結果文字。","usage":"執行 total → 選取數字文字 → 指定文字位置 → 寫出 TOTAL= 結果","level":2,"lt":"✅","ver":"2022-07-16 (檔案日期)","author":"—","video":"","fas":"fas/TOTAL.fas"},{"no":1820,"file":"TotalLengthPolylineV1-0.lsp","cmd":"tlpline","cat":"繪圖","desc":"動態繪製直線段聚合線並可限制總長度，滑鼠拖曳時即時限制長度，三點後可閉合。","usage":"執行 tlpline → 輸入長度上限(可 Enter 略過) → 依序指定點 → 可輸入 C 閉合 → Enter 結束","level":7,"lt":"⚠️","ver":"2023-04-10 (檔案日期)","author":"Lee Mac","video":"","fas":"fas/TotalLengthPolylineV1-0.fas"},{"no":1821,"file":"totalm-p-mm.LSP","cmd":"totalm-p-mm","cat":"面積/數量統計","desc":"選兩組文字，第一組數值加總減去第二組加總，並於指定點寫出含括號明細的 TOTAL= 運算式文字，可處理含等號的長字串。","usage":"執行 totalm-p-mm → 指定文字位置 → 選取第一組文字 → 選取第二組文字 → 寫出算式","level":4,"lt":"✅","ver":"20210423","author":"chengshunyi","video":"","fas":"fas/totalm-p-mm.fas"},{"no":1822,"file":"totalm-p.LSP","cmd":"totalm-p","cat":"面積/數量統計","desc":"選兩組文字，第一組加總減去第二組加總，於指定點寫出 TOTAL= 運算式，可處理含等號的長字串。","usage":"執行 totalm-p → 指定文字位置 → 選取第一組文字 → 選取第二組文字 → 寫出算式","level":4,"lt":"✅","ver":"20210423","author":"chengshunyi","video":"","fas":"fas/totalm-p.fas"},{"no":1823,"file":"TOTALm.LSP","cmd":"totalm","cat":"面積/數量統計","desc":"選兩組數字文字，以第一組加總減第二組加總，寫出 TOTAL=a-b=c 的結果文字。","usage":"執行 totalm → 指定文字位置 → 選取第一組文字 → 選取第二組文字 → 寫出結果","level":3,"lt":"✅","ver":"20220716更新 (檔案日期)","author":"—","video":"","fas":"fas/TOTALm.fas"},{"no":1824,"file":"TotalMLine.lsp","cmd":"tml","cat":"面積/數量統計","desc":"選取多重線，依多重線比例分組統計總長度，並在指定位置產生明細 MText。","usage":"執行 tml → 選取多重線 → 指定插入點 → 產生各比例長度與總計","level":6,"lt":"✅","ver":"2022-07-30 (檔案日期)","author":"Jonathan Handojo","video":"","fas":""},{"no":1825,"file":"tpb(製作屬性圖塊).LSP","cmd":"tpb","cat":"圖塊/屬性","desc":"以 entmake 用程式建立含屬性的標示圖塊（聚合線、線與屬性定義）並建立相關文字樣式，之後可依提示放置。","usage":"執行 tpb → 依提示指定放置點 → 自動建立並插入屬性圖塊","level":6,"lt":"✅","ver":"20230115","author":"chengshunyi（改自 Lee Mac 範例）","video":"","fas":"fas/tpb(製作屬性圖塊).fas"},{"no":1826,"file":"tracepoly.lsp","cmd":"tracepoly","cat":"繪圖","desc":"動態追蹤繪製聚合線並即時顯示長度，可限制總長、用 + - 調整比例、T 切換量測內容、F10 切換極軸，用於步行距離檢討。","usage":"執行 tracepoly → 依提示指定起點 → 移動滑鼠並按 + - T F10 調整 → Space/Enter 接受 → 完成","level":7,"lt":"✅","ver":"20230410","author":"chengshunyi（改自 Jonathan Handojo 的 tracepoly）","video":"","fas":""},{"no":1827,"file":"tree-hatch.LSP","cmd":"thb-l、thb-s、ths-l、ths-s、trees-hatch-bc、trees-hatch-sc、tree-hatch、test","cat":"繪圖","desc":"針對喬木圖塊，依外框範圍以實心或 45 度線填充大喬、小喬樹冠，圖層與透明度自動建立。","usage":"執行 thb-l 等指令 → 選取樹圖塊或圓 → 自動依大小喬木圖層填充 HATCH","level":6,"lt":"✅","ver":"20240929","author":"chengshunyi（含 Lee Mac Bounding Box）","video":"","fas":"fas/tree-hatch.fas"},{"no":1828,"file":"trench-sec-p.lsp","cmd":"trench-sec-p","cat":"剖面/結構","desc":"以對話框輸入溝寬、側牆、角鐵、蓋板厚、溝深與覆土深度，自動繪出含道路的陰井水溝剖面（有覆土版）。","usage":"執行 trench-sec-p → 對話框輸入尺寸 → 確定 → 指定溝頂起點 → 自動繪製剖面","level":6,"lt":"⚠️","ver":"20230226","author":"chengshunyi","video":"","fas":"fas/trench-sec-p.fas"},{"no":1829,"file":"trench-sec.lsp","cmd":"trench-sec","cat":"剖面/結構","desc":"以對話框輸入溝寬、側牆、角鐵、蓋板厚、溝深等尺寸，自動繪出水溝剖面與蓋板。","usage":"執行 trench-sec → 對話框輸入尺寸 → 確定 → 指定溝頂起點 → 自動繪製剖面","level":6,"lt":"⚠️","ver":"20230226","author":"chengshunyi","video":"","fas":"fas/trench-sec.fas"},{"no":1830,"file":"TrenchDesigner.lsp","cmd":"TrenchDesigner","cat":"剖面/結構","desc":"對話框設定水溝材質、寬深、壁厚、底板、蓋板與角鐵尺寸，繪出水溝剖面輪廓、填充並標註尺寸。","usage":"執行 TrenchDesigner → 對話框輸入參數與材質 → 確定 → 指定起點 → 自動繪製剖面","level":6,"lt":"✅","ver":"2025-07-14 (檔案日期)","author":"—","video":"","fas":""},{"no":1831,"file":"TrenchGen.lsp","cmd":"TrenchGen","cat":"繪圖","desc":"選取聚合線或手動點點，依對話框設定偏移出水溝本體、蓋板、陰影線與中心線，並可自訂各部位顏色與圖層。","usage":"執行 TrenchGen → 對話框選模式與偏移距離/顏色 → 確定 → 選取聚合線或指定點 → 自動繪製","level":7,"lt":"✅","ver":"2026-05-16 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/TrenchGen.fas"},{"no":1832,"file":"tsmc-base-dwg-purge-2025.LSP","cmd":"tsmc-base-dwg-purge-2025","cat":"圖面管理","desc":"選取資料夾後掃描所有 DWG，產生批次 SCRIPT 檔，逐檔開啟、卸載外參、purge、執行 DWG-PURGE 並存檔關閉，用於清理底圖。","usage":"執行 tsmc-base-dwg-purge-2025 → 選取目錄 → Enter 開始產生 .scr → 以 SCRIPT 指令執行","level":8,"lt":"❌","ver":"20250104 (原 2008.06.18)","author":"Cheng Shun-Yi","video":"","fas":"fas/tsmc-base-dwg-purge-2025.fas"},{"no":1833,"file":"tsmc-base-dwg-purge-F.LSP","cmd":"tsmc-base-dwg-purge-F","cat":"圖面管理","desc":"同底圖批次清理 SCRIPT 產生器，另在每檔加入載入 VP-FREEZE 與凍結 F 圖層的步驟。","usage":"執行 tsmc-base-dwg-purge-F → 選取目錄 → Enter 產生 .scr → 以 SCRIPT 指令執行","level":8,"lt":"❌","ver":"20250104 (檔案日期 2025-01-06)","author":"Cheng Shun-Yi","video":"","fas":"fas/tsmc-base-dwg-purge-F.fas"},{"no":1834,"file":"ttc.lsp","cmd":"ttc","cat":"文字","desc":"複製單行/多行文字、表格、標註、屬性與圖塊內文字的內容，貼到文字、表格、屬性等物件，支援多重與成對兩種模式。","usage":"執行 ttc → 選取來源文字 → 選擇模式 → 點選目的物件 → 貼上內容","level":7,"lt":"✅","ver":"V1.3 29 November 2005","author":"Riga, Latvia 網路程式(原作者未標示)","video":"","fas":"fas/ttc.fas"},{"no":1835,"file":"ttt.lsp","cmd":"ETBM","cat":"系統/授權","desc":"MyCAD 繪圖環境及工具列顯示管理：對話框切換功能區、選單列、檔案頁籤、游標、拾取框等顯示設定，設定記憶於登錄與 TXT 檔，並可掃描工具列。","usage":"執行 ETBM → 對話框勾選顯示項目與色彩/游標大小 → 確定 → 套用環境","level":8,"lt":"⚠️","ver":"2026 (檔案日期 2026-08-02)","author":"ChengBar (MyCAD)","video":"","fas":""},{"no":1836,"file":"turn.LSP","cmd":"turn、bv","cat":"繪圖","desc":"依選取路徑模擬車輛轉彎軌跡，沿路徑逐步繪出車身矩形與四輪軌跡線，分圖層呈現，用於迴轉半徑與通行檢討。","usage":"執行 turn → 輸入車輛參數 → 指定路徑 → 自動沿路徑繪製車身與輪跡；bv 為輔助指令","level":9,"lt":"✅","ver":"2025-05-17 (檔案日期)","author":"AutoCAD Wiki 網路程式","video":"","fas":""},{"no":1837,"file":"two-cir-tan-line.LSP","cmd":"two-cir-tan-line","cat":"繪圖","desc":"選取兩個分離的圓，畫出它們的外公切線（含內切線可由參數調整）。","usage":"執行 two-cir-tan-line → 點選第一個圓 → 點選第二個圓 → 自動畫切線","level":4,"lt":"✅","ver":"2022.12.27","author":"yangguoshe (ygs-羊羊羊)","video":"","fas":""},{"no":1838,"file":"txt-renember.LSP","cmd":"txt-renember","cat":"文字","desc":"文字重排序號：選取文字後依指定增量逐一重新編號（可 3/2/1/0/-1 等增量），含日期處理。","usage":"執行 txt-renember → 選樣板文字或輸入增量 → 依序點選要取代並遞增的文字 → E 結束","level":5,"lt":"✅","ver":"20240309","author":"chengshunyi","video":"","fas":""},{"no":1839,"file":"txt2excel.lsp","cmd":"（無，副程式庫）","cat":"轉檔/匯出入","desc":"提供將文字寫入 Excel 儲存格的函式與 Number2Alpha 欄位字母轉換，需由其他程式呼叫。","usage":"由其他程式呼叫 → 取得 Excel 物件 → 將文字寫入工作表範圍","level":8,"lt":"❌","ver":"2025-05-06 (檔案日期)","author":"Gilles Chanteau (gile) 的 Number2Alpha","video":"","fas":"fas/txt2excel.fas"},{"no":1840,"file":"TXTOUT.LSP","cmd":"（無，副程式庫）","cat":"其他","desc":"（加密檔 PROTECTED LISP，無法讀取原始碼）AutoCAD PROTECTED LISP 加密檔，內容無法閱讀，推測為文字輸出（TXTOUT）相關功能。","usage":"載入 TXTOUT.LSP → 依其內部定義的指令執行(未知)","level":3,"lt":"❓","ver":"2021-03-28 (檔案日期)","author":"—","video":"","fas":"fas/TXTOUT.fas"},{"no":1841,"file":"U-BLK.LSP","cmd":"u-blk","cat":"圖塊/屬性","desc":"點選圖塊後，依圖塊名稱到 details 資料夾插入對應的詳圖檔並縮放顯示，查看後刪除。","usage":"執行 u-blk → 點選圖塊 → 自動插入 details 資料夾同名圖 → ZOOM → 檢視後 ERASE","level":3,"lt":"✅","ver":"86.5.21","author":"—","video":"","fas":"fas/U-BLK.fas"},{"no":1842,"file":"UBA-ele.lsp","cmd":"UBA-ele","cat":"圖塊/屬性","desc":"點選屬性圖塊，以對話框輸入數值與分隔符號，選擇累加或覆蓋模式與小數位數，窗選範圍批次更新屬性並自動隱藏無意義的零。","usage":"執行 UBA-ele → 點選圖塊中目標屬性 → 對話框設定數值/分隔符/累加或覆蓋/小數 → 確定 → 窗選圖塊","level":7,"lt":"✅","ver":"2026-04-02 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/UBA-ele.fas"},{"no":1843,"file":"UCS_Pick_Object.LSP","cmd":"UCS_Pick_Object、UCS_2_point、UCS_w","cat":"修改","desc":"以點選線段/聚合線段或兩點設定 UCS 對齊該角度並 PLAN 檢視，UCS_w 回到世界座標，用於植栽槽轉角度繪製。","usage":"執行 UCS_Pick_Object → 點選物件 → UCS 與視圖轉正；或 UCS_2_point 指定兩點；UCS_w 還原","level":3,"lt":"✅","ver":"20240213","author":"chengshunyi","video":"","fas":"fas/UCS_Pick_Object.fas"},{"no":1844,"file":"UCSOP-org.LSP","cmd":"UCSOP-org","cat":"修改","desc":"以 UCS 物件選項對齊選取物件並 PLAN 轉正視圖的精簡舊版。","usage":"執行 UCSOP-org → 選取物件 → UCS 對齊並 PLAN","level":1,"lt":"✅","ver":"20211212","author":"—","video":"","fas":"fas/UCSOP-org.fas"},{"no":1845,"file":"UCSOP.LSP","cmd":"UCSOP、UCS2P","cat":"修改","desc":"UCSOP 以物件對齊 UCS 並 PLAN 轉正（不 Zoom Extents）；UCS2P 以兩點定義 UCS 並暫畫輔助線取方向。","usage":"執行 UCSOP → 選取物件；或 UCS2P → 指定兩點 → UCS 與視圖轉正","level":3,"lt":"✅","ver":"20250116","author":"chengshunyi","video":"","fas":"fas/UCSOP.fas"},{"no":1846,"file":"UNFL.lsp","cmd":"UNFL","cat":"圖層","desc":"將目前圖面所有未凍結的圖層一次解鎖。","usage":"執行 UNFL → 自動解鎖所有未凍結圖層","level":1,"lt":"✅","ver":"20250123","author":"chengshunyi","video":"","fas":"fas/UNFL.fas"},{"no":1847,"file":"UnFormat-MTEXT.lsp","cmd":"UnFormat-MTEXT","cat":"文字","desc":"移除單行/多行文字、標註、引線與屬性中的 MText 格式碼，轉為純文字內容。","usage":"執行 UnFormat-MTEXT → 選取文字物件 → 自動清除格式碼","level":5,"lt":"❌","ver":"2023-01-14 (檔案日期)","author":"Lee Mac","video":"","fas":"fas/UnFormat-MTEXT.fas"},{"no":1848,"file":"ungroup-m.lsp","cmd":"ungroup-m","cat":"修改","desc":"選取多個物件，一次解除其所屬的所有群組（Ungroup Multiple）。","usage":"執行 ungroup-m → 選取物件 → 自動解散群組","level":2,"lt":"✅","ver":"20240419","author":"Lee Mac，chengshunyi 增修","video":"","fas":"fas/ungroup-m.fas"},{"no":1849,"file":"ungroupm.lsp","cmd":"ungroupm","cat":"修改","desc":"選取多個物件，一次解除其所屬的所有群組。","usage":"執行 ungroupm → 選取物件 → 自動解散群組","level":2,"lt":"✅","ver":"20250327","author":"Lee Mac，chengshunyi 增修","video":"","fas":"fas/ungroupm.fas"},{"no":1850,"file":"UNIP.lsp","cmd":"UNIP","cat":"修改","desc":"選取聚合線、圓或面域，轉成面域聯集後再炸開、以 PEDIT 合併成單一外輪廓，並沿用第一個物件的圖層線型顏色。","usage":"執行 UNIP → 對話框(幻燈片說明)確定 → 選取封閉圖形 → 自動聯集成外輪廓聚合線","level":7,"lt":"❌","ver":"2025-10-20 (檔案日期)","author":"—","video":"","fas":"fas/UNIP.fas"},{"no":1851,"file":"unmirror.lsp","cmd":"unmirror","cat":"修改","desc":"原地復原被鏡射的圖塊，依對話框選擇左右或上下鏡射方向與 MIRRTEXT 設定，以自訂中心點連續處理。","usage":"執行 unmirror → 對話框選 MIRRTEXT 與鏡射方向 → 確定 → 選取被鏡射的圖塊 → 連續處理","level":7,"lt":"✅","ver":"2026-06-06 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/unmirror.fas"},{"no":1852,"file":"UpdateDimsByScale.lsp","cmd":"UpdateDimsByScale","cat":"標註","desc":"對話框輸入比例與繪圖單位，依比例批次更新尺寸標註型式的相關縮放設定。","usage":"執行 UpdateDimsByScale → 對話框輸入比例與單位 → 確定 → 自動更新尺寸型式","level":7,"lt":"✅","ver":"2025-10-07 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/UpdateDimsByScale.fas"},{"no":1853,"file":"UpdateDimStyle-SCA.lsp","cmd":"UpdateDimStyle-SCA","cat":"標註","desc":"舊尺寸型式移轉：輸入新比例後，依九組替換規則（如 SLASHM、CIRM、DOTM 等）把全圖尺寸改套用新比例命名的型式。","usage":"執行 UpdateDimStyle-SCA → 輸入新尺寸型式數值(如 50) → 自動比對並替換全圖標註","level":5,"lt":"✅","ver":"20260418","author":"chengshunyi","video":"","fas":"fas/UpdateDimStyle-SCA.fas"},{"no":1854,"file":"UpdateDimStyleByMyscale.lsp","cmd":"UpdateDimStyleByMyscale","cat":"標註","desc":"對話框選擇自動全選或窗選，輸入比例後把尺寸標註的型式名稱前綴改為新比例的對應型式。","usage":"執行 UpdateDimStyleByMyscale → 對話框選全選/窗選並輸入比例 → 確定 → 自動更新尺寸","level":6,"lt":"✅","ver":"20251019","author":"chengshunyi","video":"","fas":"fas/UpdateDimStyleByMyscale.fas"},{"no":1855,"file":"UpdateEL-RF.lsp","cmd":"UpdateEL-RF","cat":"圖塊/屬性","desc":"選取坡度聚合線與圖塊，依對話框設定的相對高度與基礎值，換算各圖塊位置的高程並填入屬性，可選 mm/cm/m 單位。","usage":"執行 UpdateEL-RF → 對話框輸入 H/BEL/BAEL/前綴/小數/單位 → 確定 → 選聚合線 → 批次選圖塊 → 自動寫入高程","level":7,"lt":"✅","ver":"2026-04-07 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/UpdateEL-RF.fas"},{"no":1856,"file":"UpdateEL-RFXY.LSP","cmd":"UpdateEL-RFXY","cat":"圖塊/屬性","desc":"平面高程自動計算：選聚合線長度並輸入高度，以 X 或 Y 軸為基準投影計算行程距離的高程，填入所在位置的屬性圖塊。","usage":"執行 UpdateEL-RFXY → 對話框輸入參數並選基準軸 X/Y → 確定 → 選聚合線 → 選圖塊 → 自動填入高程","level":7,"lt":"✅","ver":"20260412","author":"chengshunyi","video":"","fas":"fas/UpdateEL-RFXY.fas"},{"no":1857,"file":"UpdateEL-TAG.LSP","cmd":"UpdateEL-TAG","cat":"圖塊/屬性","desc":"以等分法計算坡道各圖塊位置高程，可自訂屬性標籤名稱、前綴與小數位數，寫入指定屬性。","usage":"執行 UpdateEL-TAG → 對話框輸入 H/BEL/BAEL/標籤名稱 → 確定 → 選聚合線 → 選圖塊 → 自動填入","level":7,"lt":"✅","ver":"2026-04-07 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":""},{"no":1858,"file":"UpdateEL-TAG3.lsp","cmd":"UpdateEL-TAG3","cat":"圖塊/屬性","desc":"高精度坡度高程計算版，除填入高程外並顯示三角函數計算過程（L1、H1、坡度與角度）。","usage":"執行 UpdateEL-TAG3 → 對話框輸入參數 → 確定 → 選聚合線 → 選圖塊 → 填入高程並顯示計算過程","level":7,"lt":"✅","ver":"2026-04-07 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":""},{"no":1859,"file":"UpdateFireDoor.lsp","cmd":"UpdateFireDoor","cat":"圖塊/屬性","desc":"對話框選擇搜尋範圍與防火門類型，讀取 FireDoorList.txt 資料庫，逐一檢查圖塊並更新防火門屬性。","usage":"執行 UpdateFireDoor → 對話框選全圖/窗選與防火門型號 → 確定 → 自動寫入屬性","level":8,"lt":"✅","ver":"v11.0 (檔案日期 2026-05-01)","author":"ChengBar (MyCAD)","video":"","fas":"fas/UpdateFireDoor.fas"},{"no":1860,"file":"UpdateMleaderAttVal.LSP","cmd":"UpdateMleaderAttVal","cat":"圖塊/屬性","desc":"輸入新值後選取區塊內容型多重引線，將其標籤為 NUM 的屬性值批次改寫。","usage":"執行 UpdateMleaderAttVal → 輸入新的屬性值 → 選取多重引線 → 自動更新 NUM 屬性","level":5,"lt":"✅","ver":"2026-02-09 (檔案日期)","author":"ChengBar (MyCAD)（參考 Lee Mac 邏輯）","video":"","fas":""},{"no":1861,"file":"UpdateScaleAttr.LSP","cmd":"UpdateScaleAttr","cat":"出圖/列印","desc":"讀取目前配置中所有視埠的比例，取最小或最大值轉成 1:X 字串，填入 TEXT_A3 等圖框圖塊的 SCALE 屬性。","usage":"執行 UpdateScaleAttr → 切到各配置 → 自動依視埠比例更新圖框 SCALE 屬性","level":6,"lt":"✅","ver":"2025-12-05 (檔案日期)","author":"—","video":"https://youtu.be/_jKWglC4M-g","fas":"fas/UpdateScaleAttr.fas"},{"no":1862,"file":"uunion.LSP","cmd":"uunion","cat":"修改","desc":"輸入檢查距離後選取線、弧與聚合線，依距離聯集合併成連續外輪廓聚合線，可多選後 JOIN。","usage":"執行 uunion → 輸入檢查距離 → 選取線/弧/聚合線 → 自動合併成外輪廓","level":7,"lt":"⚠️","ver":"20240608 (原 RJP 09.18.2017)","author":"RJP（chengshunyi 增修）","video":"","fas":"fas/uunion.fas"},{"no":1863,"file":"VECTORIZE(logo-sld).lsp","cmd":"VECTORIZE","cat":"其他","desc":"將圖面上的物件轉成 LISP 的 vector_image 函式碼，供 DCL 圖片方塊與按鈕貼入向量圖像，可調曲線與雲形線精細度。","usage":"執行 VECTORIZE → 對話框按 Select Objects → 選取圖形 → 設定敏感度 → 產生 LISP 函式","level":8,"lt":"✅","ver":"Version 1.1","author":"Richard Willis (Didge, theswamp.org)","video":"","fas":""},{"no":1864,"file":"Vectors.lsp","cmd":"（無，副程式庫）","cat":"其他","desc":"定義 vectors 函式，以 vector_image 在名為 vectors 的 DCL 圖片方塊上繪出一組向量圖形（座標資料，疑似 LOGO 字形）。","usage":"由對話框程式呼叫 (vectors) → 在 image tile 繪製向量圖","level":1,"lt":"✅","ver":"2023-01-01 (檔案日期)","author":"—","video":"","fas":"fas/Vectors.fas"},{"no":1865,"file":"view-rm-num-any.lsp","cmd":"view-rm-num-any","cat":"圖塊/屬性","desc":"點選圖塊及其任意屬性標籤，逐一縮放檢視全圖同名圖塊（如房間編號），每看一個按任意鍵繼續。","usage":"執行 view-rm-num-any → 點選圖塊 → 點選屬性 TAG → 自動逐一 ZOOM → 按鍵繼續","level":5,"lt":"✅","ver":"20240419 (原 2008.06.23)","author":"chengshunyi (Shun_Yi Studio)","video":"https://youtu.be/3JYFTJOxahQ","fas":"fas/view-rm-num-any.fas"},{"no":1866,"file":"view-rm-num.lsp","cmd":"view-rm-num","cat":"圖塊/屬性","desc":"點選圖塊後逐一縮放檢視全圖同名圖塊（房間編號），每次停留後按任意鍵繼續。","usage":"執行 view-rm-num → 點選圖塊 → 自動逐一 ZOOM → 按鍵繼續","level":4,"lt":"✅","ver":"2008.06.23 (檔案日期 2022-07-16)","author":"chengshunyi (Shun_Yi Studio)","video":"","fas":"fas/view-rm-num.fas"},{"no":1867,"file":"viewalllayouts.lsp","cmd":"（無，副程式庫）","cat":"出圖/列印","desc":"逐一切換到所有配置（Layout），並可將頁面設定複製套用到各配置後 ZOOM 檢視。","usage":"載入後呼叫其函式 → 自動切換所有 Layout 並套用頁面設定","level":5,"lt":"✅","ver":"20230728","author":"chengshunyi","video":"","fas":"fas/viewalllayouts.fas"},{"no":1868,"file":"ViewportScale.lsp","cmd":"ViewportScaleMin、ViewportScaleMax","cat":"出圖/列印","desc":"取得目前配置所有視埠的 CustomScale，轉成 1:X 字串，以最小或最大比例填入 TEXT_A3 圖框圖塊的 SCALE 屬性。","usage":"執行 ViewportScaleMin 或 ViewportScaleMax → 自動讀視埠比例並更新圖框 SCALE","level":6,"lt":"✅","ver":"2025-11-22 (檔案日期)","author":"—","video":"","fas":""},{"no":1869,"file":"vl-Ml-tree.lsp","cmd":"vl-Ml-tree","cat":"標註","desc":"建立或更新喬木樹穴面積檢討用的多重引線樣式（RLD/RLU），設定字型、文字框與引線位置，並連續標註。","usage":"執行 vl-Ml-tree → 輸入標註文字 → 點選引線起點 → 點選標籤位置 → 自動建立 MLEADER","level":6,"lt":"✅","ver":"20240430","author":"chengshunyi","video":"","fas":""},{"no":1870,"file":"VP-ch-color.lsp","cmd":"vp-color-lic、vp-color-pak、vp-color-lic-pak","cat":"圖層","desc":"逐一走訪各配置的視埠，以 VPLAYER 將指定圖層（RCW/RC/柱塗黑填充等）在視埠內改為灰色(252/241)，依建照或發包用途切換。","usage":"執行 vp-color-lic 或 vp-color-pak → 在各配置視埠依序處理 → 按 Enter 進下一個視埠","level":5,"lt":"✅","ver":"20230420 (檔案日期 2025-11-18)","author":"chengshunyi","video":"","fas":"fas/VP-ch-color.fas"},{"no":1871,"file":"vp-chxrefcols.lsp","cmd":"vp-chxrefcols、VPchcol、VPchcols、RVO-ALL、RemoveViewportOverrides、RVO-C1","cat":"圖層","desc":"在配置視埠內淡化外參底圖：點選外參或圖層物件，以 VPLAYER 改視埠圖層顏色；另可移除單一或全部視埠圖層覆寫。","usage":"執行 vp-chxrefcols → 點選外參或圖層上物件 → 設定視埠顏色；RVO-ALL 移除所有覆寫","level":5,"lt":"✅","ver":"20241228","author":"chengshunyi（含 RJP 2019-11-13 程式）","video":"https://youtu.be/lh0EAH8Z-VI","fas":"fas/vp-chxrefcols.fas"},{"no":1872,"file":"vp-freeze-lic-pak.lsp","cmd":"vp-freeze-lic-pak、freeze-lic、freeze-pak、freeze-lic-pak、unfreeze-lic-pak","cat":"圖層","desc":"在各建照、發包、細設配置的視埠中，凍結或解凍 lic-、pak-、client- 開頭圖層，並可改視埠圖層顏色。","usage":"執行 freeze-lic / freeze-pak / freeze-lic-pak 或 unfreeze-lic-pak → 依序處理各視埠 → 按 Enter 繼續","level":5,"lt":"✅","ver":"20230618","author":"chengshunyi","video":"","fas":"fas/vp-freeze-lic-pak.fas"},{"no":1873,"file":"VP-FREEZE-NS.lsp","cmd":"VPFAES、VPFAESS、VPFES、VPFESS、VPTALL、M-baseT-A、M-baseT-A-list、VPTxref、VPTxref-A、VPTxreflay","cat":"圖層","desc":"視埠圖層控制工具集：在目前視埠凍結或解凍選取圖層、外參圖層、建築底圖圖層，並可一次解凍所有外參圖層。","usage":"在配置進入視埠 → 執行 VPFES 等指令 → 點選物件或外參 → 在該視埠凍結/解凍對應圖層","level":6,"lt":"✅","ver":"20241229 (含 20250104 更新)","author":"chengshunyi","video":"https://youtu.be/8sCQ0X-oLHU","fas":"fas/VP-FREEZE-NS.fas"},{"no":1874,"file":"VP-FREEZE.lsp","cmd":"VPFAES、VPFAESS、VPFES、nff、nffv、VPFESS、VPTALL、M-baseT-A、M-baseT-A-list、VPTxref、VPTxref-A、VPTxreflay","cat":"圖層","desc":"視埠圖層控制工具集：在目前視埠凍結或解凍選取物件的圖層、外參圖層、建築底圖圖層，並可一次解凍全部外參圖層。","usage":"在配置進入視埠 → 執行 VPFES 等指令 → 點選物件或外參 → 於該視埠凍結/解凍對應圖層","level":6,"lt":"✅","ver":"20241229 (含 20250104 更新；檔案日期 2025-07-09)","author":"chengshunyi","video":"https://youtu.be/fy4r-80lVCg","fas":"fas/VP-FREEZE.fas"},{"no":1875,"file":"VP-LAYER.lsp","cmd":"VPFPAK、VPTAES、VPFLIC","cat":"圖層","desc":"在目前視埠以 VPLAYER 凍結或解凍 pak-* 與 lic-* 開頭圖層，指令分別對應包裝圖、建築與建照圖層。","usage":"進入配置視埠 → 執行 VPFPAK / VPFLIC / VPTAES → 點選物件取得圖層 → 於視埠凍結或解凍","level":2,"lt":"✅","ver":"2022-10-04 (檔案日期)","author":"—","video":"","fas":"fas/VP-LAYER.fas"},{"no":1876,"file":"VP-LAYOUTS-FREEZE.LSP","cmd":"VP-LAYOUTS-FREEZE","cat":"圖層","desc":"逐一切換所有配置，進入模型空間並用 VPLAYER 在各視埠凍結指定圖層，然後回到圖紙空間。","usage":"先將程式內 LAYER NAME 改成實際圖層 → 執行 VP-LAYOUTS-FREEZE → 自動處理所有配置","level":1,"lt":"✅","ver":"2022-10-06 (檔案日期)","author":"—","video":"","fas":"fas/VP-LAYOUTS-FREEZE.fas"},{"no":1877,"file":"VP-OvrCol.lsp","cmd":"VP-OvrCol","cat":"圖層","desc":"在使用者指定的視埠內，以 VPLAYER 覆寫符合萬用字元的圖層顏色，找不到符合圖層時停止。","usage":"執行 VP-OvrCol → 在要設定的視埠內點選 → 自動覆寫符合圖層的顏色","level":4,"lt":"✅","ver":"2022-10-10 (檔案日期)","author":"—","video":"","fas":"fas/VP-OvrCol.fas"},{"no":1878,"file":"vp-thaw-lic-pak.LSP","cmd":"vp-thaw-lic-pak","cat":"圖層","desc":"逐一走訪建照、發包、細設配置的視埠，以 VPLAYER 處理 pak- 與 lic- 開頭圖層，每個視埠按 Enter 進下一個。","usage":"執行 vp-thaw-lic-pak → 逐配置逐視埠處理 → 按 Enter 繼續","level":4,"lt":"✅","ver":"20220716 (檔案日期 2023-07-01)","author":"chengshunyi","video":"","fas":"fas/vp-thaw-lic-pak.fas"},{"no":1879,"file":"VP_Sync-LT.LSP","cmd":"VP_ShowLabels、VP_HideLabels、VP_Sync-LT","cat":"出圖/列印","desc":"視埠與模型空間框線同步對齊助手（LT 版）：依視埠自動產生模型空間框線，更新或重置連結紀錄，並可顯示視埠編號標籤。","usage":"在配置執行 VP_Sync-LT → 對話框選自動同步或重置 → 確定 → 視埠與框線同步對齊；VP_ShowLabels 顯示編號","level":8,"lt":"✅","ver":"2026-07-12 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/VP_Sync-LT.fas"},{"no":1880,"file":"VP_Sync.lsp","cmd":"VP_ShowLabels、VP_HideLabels、VP_Sync、BindAndZoom_Follow","cat":"出圖/列印","desc":"視埠與模型空間框線同步對齊工具：依視埠生成輕量聚合線框，將視埠畫面中心與比例對齊框線，連結資料存於擴充字典。","usage":"在配置執行 VP_Sync → 對話框選自動對齊/更新或清除紀錄 → 確定；VP_ShowLabels 顯示視埠編號","level":8,"lt":"✅","ver":"2026-07-12 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/VP_Sync.fas"},{"no":1881,"file":"VPFES.lsp","cmd":"VPFES、nff、nffv","cat":"圖層","desc":"在視埠內逐一點選物件，凍結其所在圖層（單選單選），0 層則提示改用 nff；nffv 為變體版。","usage":"進入視埠 → 執行 VPFES → 點選要凍結圖層的物件 → 連續執行 → Enter 結束","level":4,"lt":"✅","ver":"2025-12-12 (檔案日期)","author":"chengshunyi（FOR JAHAA）","video":"https://youtu.be/8sCQ0X-oLHU","fas":"fas/VPFES.fas"},{"no":1882,"file":"vpfreeze.LSP","cmd":"vpfreeze","cat":"圖層","desc":"選取視埠後以修改 XData 的方式，將固定圖層 pak-ss 在該視埠凍結，並重新顯示視埠使變更生效。","usage":"執行 vpfreeze → 選取視埠 → 自動凍結 pak-ss 圖層","level":5,"lt":"✅","ver":"2022-09-28 (檔案日期)","author":"—","video":"","fas":"fas/vpfreeze.fas"},{"no":1883,"file":"vpl.LSP","cmd":"vpl-mm、vpl-cm、vpl、vpc","cat":"出圖/列印","desc":"在模型空間畫出配置視埠所看到的範圍邊界，依圖框單位 mm 或 cm 係數換算，vpc 可畫視埠中心標記。","usage":"在配置執行 vpl-mm 或 vpl-cm → 選取視埠 → 於模型空間畫出視埠範圍框","level":6,"lt":"✅","ver":"2025-06-28 (檔案日期；原 2007)","author":"Rebecca L. Johnson（VPLIM）；chengshunyi 增修","video":"","fas":"fas/vpl.fas"},{"no":1884,"file":"VPlayers-SLC.lsp","cmd":"VPlayers-SLC、SaveVPlayers、LoadVPlayers、CopyVPlayers","cat":"圖層","desc":"以對話框選擇儲存、載入或複製視埠圖層凍結狀態，將某視埠凍結圖層存檔、還原或複製到其他視埠。","usage":"執行 VPlayers-SLC → 對話框選儲存/載入/複製 → 依提示選視埠並指定檔案","level":6,"lt":"✅","ver":"1997-2006 JTB World (檔案日期 2025-09-13)","author":"Jimmy Bergmark (JTB World)","video":"https://youtu.be/wmyjnGZt3kY","fas":"fas/VPlayers-SLC.fas"},{"no":1885,"file":"vplayers.lsp","cmd":"SaveVPlayers、LoadVPlayers、CopyVPlayers","cat":"圖層","desc":"儲存視埠凍結圖層到檔案、由檔案還原，或將一個視埠的圖層設定複製到其他視埠。","usage":"在配置 → 執行 SaveVPlayers / LoadVPlayers / CopyVPlayers → 選取視埠 → 存檔或套用","level":5,"lt":"✅","ver":"2000-09-07 初版 (檔案日期 2025-09-28)","author":"Jimmy Bergmark (JTB World)","video":"","fas":""},{"no":1886,"file":"VPort2Field.lsp","cmd":"VPort2Field-mm、VPort2Field-cm、VPort2Field","cat":"出圖/列印","desc":"選取視埠，在指定點建立顯示視埠比例（如 1:100）的 Field 文字，比例改變時自動更新。","usage":"在配置執行 VPort2Field-mm 或 -cm → 選取視埠 → 指定文字位置 → 建立比例欄位","level":6,"lt":"✅","ver":"20250511 (Lee Mac 25.02.10)","author":"Lee Mac，chengshunyi 增修","video":"","fas":"fas/VPort2Field.fas"},{"no":1887,"file":"VPortField2text.LSP","cmd":"VPortField2text-mm、VPortField2text-cm、VPortField2text","cat":"出圖/列印","desc":"選取視埠後，把比例 Field 寫進指定的單行/多行文字或建立新 MText，圖框單位為 mm 時需乘 10。","usage":"在配置執行 VPortField2text-mm 或 -cm → 選視埠 → 選文字 → 套用比例欄位","level":6,"lt":"✅","ver":"20250511 (Lee Mac 25.02.10)","author":"Lee Mac，chengshunyi 增修","video":"","fas":"fas/VPortField2text.fas"},{"no":1888,"file":"VPortFix.lsp","cmd":"VPortFix、VPortReactor","cat":"出圖/列印","desc":"把所有視埠移到 DEFPOINTS 圖層、設為二維線框並鎖定顯示；VPortReactor 註冊存檔前自動執行此動作的 reactor。","usage":"執行 VPortFix 立即固定視埠；執行 VPortReactor 切換自動存檔前固定","level":8,"lt":"✅","ver":"20220716 更新 (檔案日期)","author":"—","video":"","fas":"fas/VPortFix.fas"},{"no":1889,"file":"VPortUNFix.lsp","cmd":"VPortUNFix、VPortReactor","cat":"出圖/列印","desc":"把所有視埠移到 DEFPOINTS 圖層並解除顯示鎖定；VPortReactor 註冊存檔前自動執行解除的 reactor。","usage":"執行 VPortUNFix 立即解鎖視埠；執行 VPortReactor 切換存檔前自動解鎖","level":8,"lt":"✅","ver":"2022-07-16 (檔案日期)","author":"—","video":"","fas":"fas/VPortUNFix.fas"},{"no":1890,"file":"VPOutline.lsp","cmd":"vpo、vpol、vpoa","cat":"出圖/列印","desc":"在模型空間自動產生所選配置視埠的外框聚合線（含位置、比例、旋轉換算），vpol 處理目前配置、vpoa 處理所有配置。","usage":"在配置執行 vpo → 選取視埠 → 自動在模型空間建立 My-VPOutline 外框；vpoa 全部配置批次","level":7,"lt":"✅","ver":"2025-07-02 (檔案日期)","author":"Lee Mac，chengshunyi 增修","video":"","fas":"fas/VPOutline.fas"},{"no":1891,"file":"VPSCALE2MODEL.lsp","cmd":"VPSCALE2MODEL","cat":"出圖/列印","desc":"對話框設定圖框單位與視埠比例後，選取視埠自動縮放至該比例並在模型空間以 PLINE 繪出視埠範圍框，最後 Zoom 並鎖定。","usage":"執行 VPSCALE2MODEL → 對話框選 mm/cm/m 並輸入比例 → 確定 → 選取視埠 → 自動縮放並畫範圍框","level":6,"lt":"✅","ver":"2026-01-08 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/VPSCALE2MODEL.fas"},{"no":1892,"file":"walk-d-layer.lsp","cmd":"walk-d-layer","cat":"圖層","desc":"一次建立 A~E 區的步行距離圖層（-50、-70 兩組）及重複步行距離圖層，線型設為 hidden。","usage":"執行 walk-d-layer → 自動建立圖層與線型","level":2,"lt":"✅","ver":"2022-03-05 (檔案日期)","author":"—","video":"","fas":"fas/walk-d-layer.fas"},{"no":1893,"file":"walk-mark.lsp","cmd":"walk-mark","cat":"標註","desc":"步行距離標示：指定 A、B 兩點後，在步行距離圖層（綠色 hidden 線型）插入 walk-way2 圖塊標出路徑箭頭。","usage":"執行 walk-mark → 指定 A 點 → 指定 B 點 → 自動插入步行距離圖塊","level":4,"lt":"✅","ver":"20230603 (原 20200305)","author":"chengshunyi","video":"","fas":"fas/walk-mark.fas"},{"no":1894,"file":"walk_blocks.lsp","cmd":"wb","cat":"圖塊/屬性","desc":"圖塊逐一走訪工具：以清單對話框列出圖塊，逐一縮放檢視，並可隱藏其他圖塊、顯示全部。","usage":"執行 wb → 對話框選擇圖塊 → 逐一檢視 → 可 HIDEOTHERS / SHOWALL","level":8,"lt":"✅","ver":"2025-06-06 (檔案日期)","author":"Some Buddy（HIDEOTHERS/SHOWALL by balisteor）","video":"","fas":""},{"no":1895,"file":"wall-area-c-lays.LSP","cmd":"wall-area-c-lays","cat":"圖層","desc":"檢查並建立牆面積計算用圖層（輕隔間牆-3.5、磚牆-3.5、鋼筋混凝土牆-4.5 等），圖層名稱含牆高以供聚合線計算牆面積。","usage":"執行 wall-area-c-lays → 自動建立牆面積計算圖層","level":3,"lt":"✅","ver":"20241006","author":"chengshunyi","video":"","fas":"fas/wall-area-c-lays.fas"},{"no":1896,"file":"wall-ccl.lsp","cmd":"wall-ccl","cat":"繪圖","desc":"在牆兩側各點一點拖曳，以選取線與偏移找出牆中心線並放到 CL 圖層，可連續處理，Enter 結束。","usage":"執行 wall-ccl → 於牆外點選第 1 點 → 拖曳指定第 2 點 → 自動畫中心線 → Enter 結束","level":5,"lt":"✅","ver":"2024-07-29 (檔案日期)","author":"Alanh（wall c/l）","video":"","fas":""},{"no":1897,"file":"wall-clf.lsp","cmd":"wclf、wtee、wcl","cat":"繪圖","desc":"切線畫牆中心線：在牆內外點選兩點取兩線中點，建立中心線並以 FILLET 或 T 型相接，wclf 轉角、wtee 丁字、wcl 單段。","usage":"執行 wclf / wtee / wcl → 於牆內或外點選第 1 點 → 拖曳第 2 點 → 自動畫中心線 → 點選要相接的中心線","level":6,"lt":"✅","ver":"20240728 (原 wall c/l by Alanh March 2021)","author":"Alanh，chengshunyi 增修","video":"","fas":"fas/wall-clf.fas"},{"no":1898,"file":"wall-e-area-c-lays.LSP","cmd":"wall-e-area-c-lays","cat":"圖層","desc":"檢查並建立外殼面積計算用圖層（A棟屋頂平台面積、外殼_A棟_樓層_高度_序號等），供聚合線計算外殼面積。","usage":"執行 wall-e-area-c-lays → 自動建立外殼面積圖層","level":3,"lt":"✅","ver":"20241006","author":"chengshunyi","video":"","fas":"fas/wall-e-area-c-lays.fas"},{"no":1899,"file":"wall-open-c.lsp","cmd":"wall-open-s-d-c、wall-open-d-d-c、wall-open-r-d-c","cat":"繪圖","desc":"在兩條牆線上以牆中心對稱開口，裁斷牆線並插入單開門、雙開門、r 型門動態圖塊，可設門寬、開門方向與內外翻轉。","usage":"執行 wall-open-s-d-c / d-d-c / r-d-c → 選第一條牆線 → 選第二條牆線 → 指定開口位置與門寬/方向 → 自動開口並插入門","level":7,"lt":"✅","ver":"20230111 (檔案日期 2025-05-24)","author":"chengshunyi","video":"https://youtu.be/XFfb0_8KW0I","fas":"fas/wall-open-c.fas"},{"no":1900,"file":"wall-open-i.lsp","cmd":"wall-open-s-d-i、wall-open-d-d-i、wall-open-r-d-i","cat":"繪圖","desc":"在兩條牆線上依定位點距離開口，裁斷牆線並插入單開門、雙開門、r 型門動態圖塊，可設門寬與內外翻轉。","usage":"執行 wall-open-s-d-i / d-d-i / r-d-i → 選第一條、第二條牆線 → 指定定位點與門寬 → 自動開口並插入門","level":7,"lt":"✅","ver":"20230111 (檔案日期 2025-12-22)","author":"chengshunyi","video":"https://youtu.be/3DzWKzk8rnk","fas":"fas/wall-open-i.fas"},{"no":1901,"file":"wall-open-pl-c.lsp","cmd":"wall-open-s-d-pl-c、wall-open-d-d-pl-c、wall-open-r-d-pl-c、get-line-Vertex1、get-line-Vertex2、get-seg-Vertex1、get-seg-Vertex2","cat":"繪圖","desc":"牆為聚合線時的牆中心開口版，裁斷聚合線牆並插入單開門、雙開門、r 型門動態圖塊，內建取頂點與線段端點輔助指令。","usage":"執行 wall-open-s-d-pl-c 等 → 選取牆聚合線 → 指定開口位置與門寬 → 自動開口並插入門","level":8,"lt":"✅","ver":"20250117 (原 20230111)","author":"chengshunyi","video":"","fas":"fas/wall-open-pl-c.fas"},{"no":1902,"file":"wall-open-pl-i.lsp","cmd":"wall-open-s-d-pl-i、wall-open-d-d-pl-i、wall-open-r-d-pl-i、get-line-Vertex1、get-line-Vertex2、get-seg-Vertex1、get-seg-Vertex2","cat":"繪圖","desc":"牆為聚合線時的定位點開口版，裁斷聚合線牆並插入單開門、雙開門、r 型門動態圖塊。","usage":"執行 wall-open-s-d-pl-i 等 → 選取牆聚合線 → 指定定位點與門寬 → 自動開口並插入門","level":8,"lt":"✅","ver":"20250117 (原 20230111)","author":"chengshunyi","video":"","fas":"fas/wall-open-pl-i.fas"},{"no":1903,"file":"wall-open-pl.lsp","cmd":"wall-open-s-d-pl、wall-open-d-d-pl、wall-open-r-d-pl、get-line-Vertex1、get-line-Vertex2、get-seg-Vertex1、get-seg-Vertex2","cat":"繪圖","desc":"牆為聚合線時的基本開口版，裁斷聚合線牆並插入單開門、雙開門、r 型門動態圖塊。","usage":"執行 wall-open-s-d-pl 等 → 選取牆聚合線 → 指定開口位置與門寬 → 自動開口並插入門","level":8,"lt":"✅","ver":"20250117 (原 20230111)","author":"chengshunyi","video":"","fas":"fas/wall-open-pl.fas"},{"no":1904,"file":"wall-open-win-pl.LSP","cmd":"wall-open-w-PL1、wall-open-w-PL2、wall-open-w-PL3、wall-open-w-PL4、wall-open-w-PL5、wall-open-w-PL、wall-open-w-L1、wall-open-w-L2、wall-open-w-L3、wall-open-w-L4、wall-open-w-L5、wall-open-w-l、wall-open-w-F1、wall-open-w-F2、wall-open-w-F3、wall-open-w-F4、wall-open-w-F5、wall-open-w-f、get-line-Vertex1、get-line-Vertex2、get-seg-Vertex1、get-seg-Vertex2","cat":"繪圖","desc":"在線牆或聚合線牆上開窗口並插入推拉窗、百葉窗、固定窗動態圖塊（1~5 分格），可設離牆邊距與內外翻轉。","usage":"執行 wall-open-w-PL1~5 / L1~5 / F1~5 → 選取牆線或聚合線 → 指定窗位置與寬度 → 自動開口並插入窗","level":8,"lt":"✅","ver":"20250106 (檔案日期 2025-05-26)","author":"chengshunyi","video":"https://youtu.be/aOK49PQ27mA","fas":"fas/wall-open-win-pl.fas"},{"no":1905,"file":"wall-open-win.lsp","cmd":"wall-open-w-PL1、wall-open-w-PL2、wall-open-w-PL3、wall-open-w-PL4、wall-open-w-PL5、wall-open-w-PL、wall-open-w-L1、wall-open-w-L2、wall-open-w-L3、wall-open-w-L4、wall-open-w-L5、wall-open-w-l、wall-open-w-F1、wall-open-w-F2、wall-open-w-F3、wall-open-w-F4、wall-open-w-F5、wall-open-w-f","cat":"繪圖","desc":"在牆線上開窗口並插入推拉窗、百葉窗、固定窗動態圖塊（1~5 分格），可設窗寬並內外翻轉。","usage":"執行 wall-open-w-PL1~5 / L1~5 / F1~5 → 選取牆線 → 指定窗位置與寬度 → 自動開口並插入窗","level":8,"lt":"✅","ver":"20250106 (檔案日期 2025-01-09)","author":"chengshunyi","video":"https://youtu.be/aOK49PQ27mA","fas":"fas/wall-open-win.fas"},{"no":1906,"file":"wall-open.lsp","cmd":"wall-open-s-d、wall-open-d-d、wall-open-r-d","cat":"繪圖","desc":"在兩條牆線上開口並插入單開門、雙開門、r 型門動態圖塊，依圖紙單位與比例換算，預設門框厚 5cm。","usage":"執行 wall-open-s-d / d-d / r-d → 選第一條、第二條牆線 → 指定開口位置與門寬 → 自動開口並插入門","level":7,"lt":"✅","ver":"20230111 (含 20241222 更新)","author":"chengshunyi","video":"https://youtu.be/ueZNBjhz8M0","fas":"fas/wall-open.fas"},{"no":1907,"file":"wall-pline-3D.lsp","cmd":"wall-pline-3D、wall-3D-erase","cat":"3D","desc":"依聚合線所在圖層名稱中的高度值，將牆聚合線擠出成 3D 實體供檢核，wall-3D-erase 刪除檢核用實體。","usage":"執行 wall-pline-3D → 選取各圖層聚合線 → 自動依圖層高度 EXTRUDE 並切換視角；wall-3D-erase 清除","level":5,"lt":"❌","ver":"20241201","author":"chengshunyi（含 Lee Mac 字串函式）","video":"","fas":"fas/wall-pline-3D.fas"},{"no":1908,"file":"WALL.LSP","cmd":"RTEXT、WALL","cat":"文字","desc":"RTEXT 依全部、顏色、物件或圖層範圍，批次修改單行文字內容；WALL 為同檔提供的畫牆相關指令。","usage":"執行 RTEXT → 選擇 All/Color/Entity/Layer → 輸入新文字內容；WALL 依提示畫線","level":6,"lt":"✅","ver":"2022-07-16 (檔案日期)","author":"Hsiao Shun Hsiang","video":"","fas":"fas/WALL.fas"},{"no":1909,"file":"WallLenAreaSum.LSP","cmd":"WallLenAreaSum","cat":"面積/數量統計","desc":"牆體長度/面積統計：依尺寸圖層辨識牆體類別，全圖或手動窗選，自動切換長度或面積，以長度乘高度並輸出簡式或明細計算式文字。","usage":"執行 WallLenAreaSum → 對話框選全圖/窗選、簡式/明細、固定高度或依圖層後綴 → 確定 → 指定文字位置 → 輸出","level":8,"lt":"✅","ver":"v8.1.1 (檔案日期 2026-04-25)","author":"ChengBar (MyCAD)","video":"","fas":"fas/WallLenAreaSum.fas"},{"no":1910,"file":"WB.lsp","cmd":"WB、site-WB","cat":"標註","desc":"建築詞庫快速引線與文字標註：對話框選 site.dat 或 plan.dat 詞庫字詞，可取代或合併文字、設定角度與日期，連續點位以 MLEADER 標註。","usage":"執行 WB → 對話框選詞庫與字詞/字高/角度 → 確定 → 連續點位標註 → 右鍵或 Enter 結束","level":8,"lt":"✅","ver":"v4.0.0 (2026/10/05)","author":"ChengBar (MyCAD)","video":"","fas":"fas/WB.fas"},{"no":1911,"file":"wb01.lsp","cmd":"wb01","cat":"標註","desc":"文字詞庫標註舊版：對話框從 wb01.dat 取主類別與詞條，選字高與角度後在圖面插入文字或屬性。","usage":"執行 wb01 → 對話框選主類別/詞條/字高/角度 → 確定 → 指定位置 → 插入文字","level":7,"lt":"✅","ver":"20220101 (檔案日期 2023-12-31)","author":"—","video":"","fas":"fas/wb01.fas"},{"no":1912,"file":"wblock-to-folder.lsp","cmd":"WBLOCK-TO-FOLDER","cat":"圖塊/屬性","desc":"將圖檔內所有一般圖塊各自 WBLOCK 輸出為 DWG（檔名＝圖塊名），對話框設定目標資料夾與是否覆蓋，並排除匿名、外參與相依圖塊。","usage":"執行 WBLOCK-TO-FOLDER → 對話框輸入或瀏覽資料夾、選覆蓋選項 → 確定 → 自動逐一輸出","level":8,"lt":"⚠️","ver":"v2.1.0 (2026-11-14)","author":"ChengBar (MyCAD)（原 CHENGSHUNYI 2023-08-19）","video":"","fas":"fas/wblock-to-folder.fas"},{"no":1913,"file":"WC-M.LSP","cmd":"wc-m","cat":"繪圖","desc":"以對話框輸入深度、寬度、隔板厚度與隔間數，指定基點與方向後自動畫出一排廁所隔間並插入 u-316 圖塊。","usage":"執行 wc-m → 對話框輸入 D/W/T/NUM（可重設）→ 確定 → 指定基點 → 指定第二點定方向 → 自動繪製","level":6,"lt":"✅","ver":"2008.03.31 (檔案日期 2026-10-17)","author":"chengshunyi","video":"","fas":"fas/WC-M.fas"},{"no":1914,"file":"WC.LSP","cmd":"wc-D、wc-C、wc","cat":"繪圖","desc":"以對話框選擇廁所型式（含 1/3 蹲式等），輸入深度、寬度、門尺寸、隔板厚度與隔間數，自動畫出廁所隔間與衛生設備。","usage":"執行 wc → 對話框選型式並輸入 D/W/DOR/T/N → 確定 → 指定基點與方向 → 自動繪製","level":8,"lt":"✅","ver":"20240211 (原 2008.03.31)","author":"chengshunyi","video":"","fas":"fas/WC.fas"},{"no":1915,"file":"WH2BF.lsp","cmd":"Wipeout2B、Wipeout2F、Hatch2B、Hatch2F","cat":"修改","desc":"調整圖塊內部物件的顯示順序：將圖塊中的遮蔽(Wipeout)或填充線送到最底或最上。","usage":"執行 Wipeout2B / Wipeout2F / Hatch2B / Hatch2F → 選取圖塊 → 自動修改圖塊內物件前後順序","level":6,"lt":"✅","ver":"20211016","author":"CHENG-BAR（含 Lee Mac 17.06.11）","video":"","fas":"fas/WH2BF.fas"},{"no":1916,"file":"Win-ele.lsp","cmd":"Win-ele","cat":"繪圖","desc":"立面窗插入工具：用幻燈片單選窗型（百葉、百葉含窗台、固定窗、推拉窗），輸入寬高與分格數，插入對應動態圖塊並設定 W/H。","usage":"執行 Win-ele → 對話框點選窗型並輸入寬、高、分格數 → 確定 → 指定基準點 → 插入窗圖塊","level":7,"lt":"✅","ver":"20250527","author":"chengshunyi","video":"","fas":"fas/Win-ele.fas"},{"no":1917,"file":"WINDOW-1.LSP","cmd":"window-1","cat":"繪圖","desc":"指定牆線 A、B、C 三點與窗寬、分割數，裁斷牆線並畫出平面窗線型與窗框，圖層為 win-s。","usage":"執行 window-1 → 指定 A、B、C 點 → 輸入窗尺寸 → 輸入分割數 → 自動繪製平面窗","level":5,"lt":"✅","ver":"84.4.11 (20210425 改寫)","author":"—","video":"","fas":"fas/WINDOW-1.fas"},{"no":1918,"file":"WINDOW-123.LSP","cmd":"window-123","cat":"繪圖","desc":"合併 window-1、2、3 三種平面窗畫法，以幻燈片選窗型，輸入窗寬、分割數、門尺寸後裁斷牆線並繪窗。","usage":"執行 window-123 → 對話框點選窗型並輸入尺寸/分割/門寬 → 確定 → 指定 A、B、C 點 → 自動繪製","level":7,"lt":"✅","ver":"20241124 (原 84.4.11)","author":"chengshunyi","video":"https://youtu.be/P215Iffi0dQ","fas":"fas/WINDOW-123.fas"},{"no":1919,"file":"WINDOW-2.LSP","cmd":"window-2","cat":"繪圖","desc":"指定牆線 A、B、C 三點、窗寬與分割數，裁斷牆線並畫出另一種平面窗型。","usage":"執行 window-2 → 指定 A、B、C 點 → 輸入窗尺寸 → 輸入分割數 → 自動繪製平面窗","level":5,"lt":"✅","ver":"84.4.11 94.03.13","author":"—","video":"","fas":"fas/WINDOW-2.fas"},{"no":1920,"file":"WINDOW-3.LSP","cmd":"window-3","cat":"繪圖","desc":"指定牆線三點，輸入門加窗總寬、門寬與窗分割數，裁斷牆線並畫出門窗並置平面窗，含插入圖塊。","usage":"執行 window-3 → 指定 A、B、C 點 → 輸入門窗總寬/門寬/窗分割數 → 自動繪製","level":5,"lt":"✅","ver":"84.4.11 94.03.13","author":"—","video":"","fas":"fas/WINDOW-3.fas"},{"no":1921,"file":"WINDOW-ALL.LSP","cmd":"window-fix、window-pull、window-push、fix-w-cut、fix-dw-cut、fix-dw2-cut、fix-w-open、fix-dw-open、fix-dw2-open、pull-w-cut、pull-dw-cut、pull-dw2-cut、pull-w-open、pull-dw-open、pull-dw2-open、fix-push1-cut、fix-push2-cut、fix-push1-open、fix-push2-open","cat":"繪圖","desc":"平面窗整合工具：以對話框幻燈片選固定窗、推拉窗、推射窗及窗/門窗組合，分切牆(cut)或開口(open)兩種方式繪製。","usage":"執行 window-fix / window-pull / window-push → 對話框選窗型與尺寸 → 確定 → 指定 A、B、C 點 → 自動繪製","level":8,"lt":"✅","ver":"20250215 (原 84.4.11 94.03.13)","author":"chengshunyi","video":"https://youtu.be/jloOxlsq75E","fas":"fas/WINDOW-ALL.fas"},{"no":1922,"file":"WINDOW.LSP","cmd":"fix-w-cut、fix-dw-cut、fix-dw2-cut、fix-w-open、fix-dw-open、fix-dw2-open、pull-w-cut、pull-dw-cut、pull-dw2-cut、pull-w-open、pull-dw-open、pull-dw2-open、fix-push1-cut、fix-push2-cut、fix-push1-open、fix-push2-open","cat":"繪圖","desc":"平面窗繪製指令集：固定窗、推拉窗、推射窗及窗/門窗組合，分切牆(cut)與開口(open)兩種畫法，依指令輸入窗寬與分割數。","usage":"執行 fix-w-cut 等指令 → 指定 A、B、C 點 → 輸入窗寬/門寬/分割數 → 自動繪製","level":7,"lt":"✅","ver":"84.4.11 94.03.13 (檔案日期 2022-07-16)","author":"—","video":"","fas":"fas/WINDOW.fas"},{"no":1923,"file":"wj2.lsp","cmd":"wj2","cat":"繪圖","desc":"先選要跳的聚合線，再選與其相交的聚合線，在交叉點自動畫出弧形跳線（wire jumper）。","usage":"執行 wj2 → 選取要加跳線的聚合線 → 選取與其相交的所有聚合線 → 自動在交點產生弧跳線","level":6,"lt":"✅","ver":"2021-09-06 (檔案日期 2024-11-11)","author":"hak_vz","video":"","fas":""},{"no":1924,"file":"WLD.lsp","cmd":"WLD","cat":"繪圖","desc":"自動畫牆工具：對話框選擇 MLINE 型式、對齊方式（上/中/下）、牆厚與圖層，自動建立圖層並以 MLINE 畫牆。","usage":"執行 WLD → 對話框選 MLINE 型式/對齊/牆厚/圖層 → 確定 → 依提示指定牆線點位","level":6,"lt":"✅","ver":"2026-01-16 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/WLD.fas"},{"no":1925,"file":"working-bind.LSP","cmd":"working-bind","cat":"圖面管理","desc":"選取資料夾後掃描所有 DWG，產生批次 SCRIPT 檔：逐檔開啟、載入 delete_unload_xref、purge、切換 layout、另存 2007 版並關閉，用於整理 working 圖。","usage":"執行 working-bind → 選取 dwg 或資料夾 → Enter 開始產生 .scr → 以 SCRIPT 指令執行","level":8,"lt":"⚠️","ver":"20250124 (原 2017.03.29)","author":"Cheng Shun-Yi (MyCAD)","video":"","fas":"fas/working-bind.fas"},{"no":1926,"file":"working-purge.LSP","cmd":"working-purge","cat":"圖面管理","desc":"選取資料夾後掃描所有 DWG，產生批次 SCRIPT 檔：逐檔開啟、執行 DWG-PURGE 與 -purge all、delete_unload_xref、另存 2007 版並關閉。","usage":"執行 working-purge → 選取目錄 → Enter 開始產生 .scr → 以 SCRIPT 指令執行","level":8,"lt":"❌","ver":"2017.03.29 (檔案日期 2024-10-17)","author":"Cheng Shun-Yi","video":"","fas":"fas/working-purge.fas"},{"no":1927,"file":"wow(單線轉雙線).lsp","cmd":"breakall、BreakObject、breakwobjects、BreakWith、BreakTouching、BreakSelected、wow","cat":"修改","desc":"Break 系列工具：在相交處將選取的線、弧、聚合線、雲形線、圓與橢圓全部打斷，或用單一/多個物件打斷其他物件；wow 為單線轉雙線前置的打斷入口。","usage":"執行 breakall → 選取要打斷的物件 → Enter；或 BreakWith → 選被打斷物件 → 選打斷用物件","level":7,"lt":"✅","ver":"Version 1.3 April 9,2007 (檔案日期 2024-09-14)","author":"Charles Alan Butler (TheSwamp.org)","video":"","fas":""},{"no":1928,"file":"wow.lsp","cmd":"breakall、BreakObject、breakwobjects、BreakWith、BreakTouching、BreakSelected、wow","cat":"修改","desc":"Break 系列工具：在相交處打斷選取的線、弧、聚合線、雲形線、圓與橢圓，並可用單一或多個物件打斷其他物件，含 wow 入口。","usage":"執行 breakall / BreakWith 等 → 選取要打斷的物件 → 選打斷用物件 → 自動在交點打斷","level":7,"lt":"✅","ver":"Version 1.3 April 9,2007 (檔案日期 2025-03-14)","author":"Charles Alan Butler (TheSwamp.org)","video":"","fas":"fas/wow.fas"},{"no":1929,"file":"write-text2word.LSP","cmd":"write-text2word","cat":"轉檔/匯出入","desc":"建立 Word 應用程式並以標楷體將文字寫入文件的副程式範例。","usage":"由其他程式或手動呼叫 write-text2word → 自動開啟 Word 並寫入文字","level":8,"lt":"❌","ver":"20250629","author":"chengshunyi","video":"","fas":"fas/write-text2word.fas"},{"no":1930,"file":"write2word-demo.LSP","cmd":"demo2","cat":"轉檔/匯出入","desc":"開啟或建立 Word，選取 Word 文件後寫入標題、頁首、頁尾與指定行的示範程式。","usage":"執行 demo2 → 選取 Word 文件 → 自動寫入頁首/頁尾/內文 → 等待關閉 Word","level":8,"lt":"❌","ver":"2025-06-29 (檔案日期)","author":"—","video":"","fas":"fas/write2word-demo.fas"},{"no":1931,"file":"X-PATH.lsp","cmd":"X-PATH、X-P","cat":"圖面管理","desc":"若外部參考與影像檔可在 AutoCAD 搜尋路徑（含目前圖檔所在資料夾）找到，就刪除其絕對路徑並重新載入。","usage":"執行 X-PATH → 自動掃描外參與影像 → 移除路徑並重載 → 顯示處理數量","level":6,"lt":"✅","ver":"v2.0 (03-23-06)，檔案日期 2024-05-11","author":"John Uhden","video":"","fas":"fas/X-PATH.fas"},{"no":1932,"file":"X_level coordiinate.lsp","cmd":"xcoor","cat":"繪圖","desc":"選取聚合線，依各頂點座標產生垂直輔助線並可輸入 X 軸長度，同時將編號與座標輸出成 X_level_corrdinate.csv。","usage":"執行 xcoor → 選取聚合線 → 輸入 X 軸長度 → 自動畫輔助線並輸出 CSV","level":6,"lt":"✅","ver":"2022-11-26 (檔案日期)","author":"—","video":"","fas":"fas/X_level coordiinate.fas"},{"no":1933,"file":"XCLIP_Toggle.lsp","cmd":"XCLIP_Toggle","cat":"修改","desc":"以 VLA 屬性與 DXF 擴充字典三重檢查外參或圖塊是否有 XCLIP 邊界，並可切換 On、Off、Delete 或顯示邊界座標與類型。","usage":"執行 XCLIP_Toggle → 選取外參或圖塊 → 輸入 On/Off/Delete/Show → 自動切換或顯示邊界","level":7,"lt":"✅","ver":"2025-11-20 (檔案日期)","author":"—","video":"","fas":""},{"no":1934,"file":"xcoor.lsp","cmd":"xcoor","cat":"繪圖","desc":"選取聚合線，在頂點位置切垂直線並輸入 X 軸長度，同時把編號與座標輸出成 CSV 檔。","usage":"執行 xcoor → 選取聚合線 → 輸入 X 軸長度 → 自動畫垂直輔助線並輸出 CSV","level":6,"lt":"✅","ver":"2023-01-15 (檔案日期)","author":"—","video":"","fas":"fas/xcoor.fas"},{"no":1935,"file":"xctp.lsp","cmd":"xctp-h、xctp-v、xctp-hv、XCTP、XCTP-ang、xctpp-h、xctpp-v、xctpp-hv、xctpp、xctpp-el、xctpp-el-UCS","cat":"繪圖","desc":"依聚合線節點建立水平、垂直或水平加垂直輔助線（XLINE），可沿指定邊、角度或輸入高程作水平輔助線，並支援 UCS。","usage":"執行 xctp-h / xctp-v / xctpp-el 等 → 選取聚合線或指定點 → 自動在各節點建立 XLINE（0-REF 圖層）","level":7,"lt":"✅","ver":"20241108 (檔案日期 2025-09-26)","author":"chengshunyi","video":"https://youtu.be/rYw5rWFjxao","fas":"fas/xctp.fas"},{"no":1936,"file":"xctppd.lsp","cmd":"xctppd-h、xctppd-v、xctppd-hv、xctppd","cat":"繪圖","desc":"依聚合線節點建立水平、垂直或水平加垂直輔助線，並可輸入寬度沿聚合線某邊偏移產生成對輔助線。","usage":"執行 xctppd-h / -v / -hv → 選取聚合線 → 輸入寬度 → 自動建立 XLINE","level":7,"lt":"✅","ver":"20241108 (檔案日期 2025-05-10)","author":"chengshunyi","video":"","fas":"fas/xctppd.fas"},{"no":1937,"file":"Xhair-color.lsp","cmd":"Xhair-color、text-wind-color","cat":"系統/授權","desc":"以 setenv 修改十字游標、拾取框及命令列、文字視窗的前景與背景顏色，使用 R+G*256+B*65536 真彩色換算。","usage":"執行 Xhair-color 設定游標與拾取框色 → 執行 text-wind-color 設定命令列/文字視窗配色 → 重啟 CAD 或重生生效","level":4,"lt":"✅","ver":"20250501","author":"chengshunyi","video":"","fas":""},{"no":1938,"file":"xlin-dist-div-2p-D.LSP","cmd":"xlin-dist-div-2p-D","cat":"繪圖","desc":"指定兩點與等量分割距離，沿兩點方向每隔固定距離建立垂直 XLINE 輔助線，距離記憶於環境變數。","usage":"執行 xlin-dist-div-2p-D → 指定第一點 → 指定第二點 → 輸入分割距離(預設上次或 500) → 自動建立 XLINE","level":5,"lt":"✅","ver":"20251212 (檔案日期 2025-12-12)","author":"chengshunyi","video":"https://youtu.be/gMrGO_UrQFE","fas":"fas/xlin-dist-div-2p-D.fas"},{"no":1939,"file":"xlin-dist-div-2p-O.lsp","cmd":"xlin-dist-div-2p-O","cat":"繪圖","desc":"指定兩點與等距距離，沿方向建立垂直 XLINE，餘數平均分配在頭尾兩端（對中）。","usage":"執行 xlin-dist-div-2p-O → 指定第一點、第二點 → 輸入等距距離 → 自動建立對中 XLINE","level":5,"lt":"✅","ver":"2025-09-26 (檔案日期)","author":"chengshunyi","video":"https://youtu.be/Md_-riSBHtk","fas":"fas/xlin-dist-div-2p-O.fas"},{"no":1940,"file":"xlin-dist-div-sm.LSP","cmd":"xlin-dist-div-sm","cat":"繪圖","desc":"兩點等分輔助線產生器：對話框設定等分數並選 S 模式（含頭尾端點）或 M 模式（中央對稱），以幻燈片預覽後建立 XLINE。","usage":"執行 xlin-dist-div-sm → 對話框輸入等分數、選 S/M 模式 → 確定 → 指定兩點 → 自動建立 XLINE","level":7,"lt":"⚠️","ver":"V3.0 (2026 Edition)","author":"鄭霸 (ChengBar)","video":"https://youtu.be/ooYesvznrAI","fas":"fas/xlin-dist-div-sm.fas"},{"no":1941,"file":"xlin-dist-div.LSP","cmd":"xlin-dist-div-2p-S、xlin-dist-div-2p-M","cat":"繪圖","desc":"指定兩點與等分數，沿兩點方向建立 XLINE 輔助線：S 為含頭尾端點的兩點等分，M 為對中分。","usage":"執行 xlin-dist-div-2p-S 或 -M → 指定第一點 → 指定第二點 → 輸入等分數 → 自動建立 XLINE","level":5,"lt":"✅","ver":"20241117 (檔案日期 2026-01-02)","author":"chengshunyi","video":"https://youtu.be/y64r_nBoNx4","fas":"fas/xlin-dist-div.fas"},{"no":1942,"file":"xlindistdiv.lsp","cmd":"xlindistdiv","cat":"繪圖","desc":"選兩點或選直線段，指定要建立的 XLINE 數量，在兩點間等分建立垂直輔助線，可切換 points 或 object 模式。","usage":"執行 xlindistdiv → 選 points 或 object → 指定兩點或點選線段 → 輸入 XLINE 數量 → 自動建立","level":5,"lt":"✅","ver":"20240302","author":"chengshunyi","video":"","fas":""},{"no":1943,"file":"XLINE-FROM-XREF.lsp","cmd":"XLINE-FROM-XREF","cat":"繪圖","desc":"選取外參或嵌套圖塊內的 LINE 或 PLINE，以矩陣轉換取得世界座標位置，建立對應方向的 XLINE 輔助線。","usage":"執行 XLINE-FROM-XREF → 選取外參內 LINE/PLINE → 自動建立 XLINE（0-REF 圖層）","level":7,"lt":"✅","ver":"2025-10-03 (檔案日期)","author":"chengshunyi","video":"https://youtu.be/W56TcCbQIPY","fas":"fas/XLINE-FROM-XREF.fas"},{"no":1944,"file":"XLine.lsp","cmd":"xhv、xx、xh、xv、xa","cat":"繪圖","desc":"在預設圖層（0-REF，無則自動建立）直接建立水平加垂直、水平、垂直或指定角度的 XLINE，xx 可連續選項切換。","usage":"執行 xh / xv / xhv / xa → 指定交叉點 → 自動建立 XLINE；xx 以選項 [Horizontal/Vertical/Angle/Exit] 連續建立","level":5,"lt":"✅","ver":"Version 1.0 2025-01-18 (chengshunyi 20250301 改)","author":"Lee Mac，chengshunyi 增修","video":"https://youtu.be/JeXw803ZaD0","fas":"fas/XLine.fas"},{"no":1945,"file":"XlineFromObject.lsp","cmd":"XlineFromObject","cat":"繪圖","desc":"選取 LINE 或聚合線上的點，找最近兩頂點方向建立 XLINE；選到圓弧或圓則改畫一個 CIRCLE。","usage":"執行 XlineFromObject → 選取 LINE/PLINE/ARC/CIRCLE → 自動建立 XLINE 或圓","level":6,"lt":"✅","ver":"2025-12-12 (檔案日期)","author":"chengshunyi","video":"https://youtu.be/YmT_J78rK04","fas":"fas/XlineFromObject.fas"},{"no":1946,"file":"XLinePline.lsp","cmd":"XLinePline","cat":"繪圖","desc":"以對話框設定顏色、透明度與線寬，用 XLINE 取邊界或指定長度繪製聚合線，設定即時寫入 TXT 以跨工作階段記憶。","usage":"執行 XLinePline → 對話框設定顏色/透明度/線寬/指定長度/角度 → 按功能鈕 → 依提示指定點 → 繪製或管理","level":8,"lt":"✅","ver":"2026-11-03 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/XLinePline.fas"},{"no":1947,"file":"xr-clip.lsp","cmd":"xr-clip-v、xr-clip","cat":"圖面管理","desc":"MyCAD 批次外部參考裁剪：對話框選來源目錄與外參檔、設定間距、換行數與起點，批次附加外參、等距排列並依選取範圍 XCLIP，可插入圖框。","usage":"執行 xr-clip-v → 對話框選目錄/勾選圖檔/間距/起點 → 確定 → 自動批次附加、排列並裁剪外參","level":8,"lt":"⚠️","ver":"2026-05-30 (檔案日期)","author":"ChengBar (MyCAD)","video":"","fas":"fas/xr-clip.fas"},{"no":1948,"file":"XR253.LSP","cmd":"XR253","cat":"圖層","desc":"選取外參後，將該外參的所有圖層在目前圖面改為 253 號顏色，適用於 E-Base 現況底圖淡化。","usage":"執行 XR253 → 點選外參 → 自動將其圖層顏色改為 253","level":3,"lt":"✅","ver":"20230115","author":"—","video":"","fas":"fas/XR253.fas"},{"no":1949,"file":"XREF-2-AO.lsp","cmd":"x2a、x2o","cat":"圖面管理","desc":"一次把圖面所有外部參考的附加型態改成附著（x2a）或覆蓋（x2o），並暫時停用 reactor 避免干擾，保留圖層狀態與 XCLIP。","usage":"執行 x2a 或 x2o → 自動轉換所有外參型態 → 重新載入","level":8,"lt":"✅","ver":"Version 2.1a 12/07/2011 (檔案日期 2024-05-11)","author":"Chris Wade","video":"","fas":"fas/XREF-2-AO.fas"},{"no":1950,"file":"XREF-PATH-TYPE.LSP","cmd":"SXA、SXR、SXN","cat":"系統/授權","desc":"寫入登錄機碼，設定外部參考附加對話框預設的路徑類型：SXA 絕對路徑、SXR 相對路徑、SXN 不含路徑。","usage":"執行 SXA / SXR / SXN → 自動設定路徑類型 → 下次附加外參生效","level":4,"lt":"✅","ver":"20220716 更新 (檔案日期 2024-05-11)","author":"Jimmy Bergmark (JTB World)","video":"","fas":""},{"no":1951,"file":"XREFOPTIMIZE.lsp","cmd":"XREFOPTIMIZE","cat":"系統/授權","desc":"對話框一次設定外參與配置效能相關系統變數（DEMANDLOAD、INDEXCTL、UCS 偵測、HPMAXAREAS 等），提供建議值按鈕與變更記錄。","usage":"執行 XREFOPTIMIZE → 對話框勾選/輸入各變數或按建議值 → 確定 → 套用系統變數","level":6,"lt":"✅","ver":"2025-11-22 (檔案日期)","author":"—","video":"https://youtu.be/WOrN1cmzfSE","fas":""},{"no":1952,"file":"xrefpathchange.lsp","cmd":"xrefpathchange-r、xrefpathchange-c、xrefpathchange-r-pec","cat":"圖面管理","desc":"依檔名前綴規則（圖框 T、圖例 GN、-BDR、GRID、KEY、FURN 等）批次把外參改為 ..\\xref\\、..\\ARCH\\、..\\SITE\\ 等相對路徑，並可回上一層改同層。","usage":"執行 xrefpathchange-r（相對）或 -c → 自動掃描並改寫所有外參路徑","level":7,"lt":"✅","ver":"20241220 (檔案日期 2026-09-29)","author":"ronjonp（chengshunyi 改寫)","video":"","fas":"fas/xrefpathchange.fas"},{"no":1953,"file":"XREFROT90.lsp","cmd":"XREFROT90","cat":"修改","desc":"選取已裁剪的外參，用 XCLIP 暫時產生邊界聚合線取得 BoundingBox 中心，把外參旋轉 90 度後刪除邊界聚合線。","usage":"執行 XREFROT90 → 選取已 XCLIP 的外參 → 自動旋轉 90 度","level":5,"lt":"✅","ver":"2025-11-23 (檔案日期)","author":"—","video":"","fas":"fas/XREFROT90.fas"},{"no":1954,"file":"xrlayfrz.LSP","cmd":"xrlayfrz","cat":"圖層","desc":"選取外參後，將該外參下的所有圖層凍結。","usage":"執行 xrlayfrz → 點選外參 → 自動凍結其所有圖層","level":3,"lt":"✅","ver":"20230402","author":"chengshunyi","video":"","fas":"fas/xrlayfrz.fas"},{"no":1955,"file":"xro-clip.lsp","cmd":"xro-clip-H、xro-clip-V、xro-clip","cat":"圖面管理","desc":"批次外參（覆蓋）選檔並等距排列，橫向或縱向，再依選取的聚合線截圖範圍對各外參做 XCLIP。","usage":"執行 xro-clip-H / -V → 選取目錄 → 清單選多個 dwg → 輸入間距 → 選取截圖聚合線 → 自動附加、排列並裁剪","level":7,"lt":"❌","ver":"20211024 (更新 20250602)","author":"chengshunyi（含 Lee Mac LM:listbox）","video":"","fas":"fas/xro-clip.fas"},{"no":1956,"file":"xro.lsp","cmd":"xro","cat":"圖面管理","desc":"批次外參（覆蓋）選取目錄內多個 dwg，以清單選擇後輸入間距，等距排列到圖面。","usage":"執行 xro → 選取目錄 → 清單選多個 dwg → 輸入間距 → 自動附加並 MOVE 排列","level":6,"lt":"❌","ver":"20211024 (檔案日期 2022-07-16)","author":"chengshunyi（含 Lee Mac List Box）","video":"","fas":"fas/xro.fas"},{"no":1957,"file":"XRP.lsp","cmd":"xrp","cat":"圖面管理","desc":"掃描區塊表中所有外部參考與影像，將絕對路徑改成較短的相對路徑，去除多餘磁碟機代號與上層路徑，增進圖檔搬移性。","usage":"執行 xrp → 自動掃描外參與影像 → 重新設定相對路徑 → 顯示處理清單並按鍵繼續","level":7,"lt":"✅","ver":"Rev 7 10/21/2010 (檔案日期 2014-04-24)","author":"Mark McDonough","video":"","fas":""},{"no":1958,"file":"Y340.LSP","cmd":"Y340","cat":"圖塊/屬性","desc":"使用者 BLOCK 圖庫管理：以幻燈片分頁瀏覽並插入圖塊，具搜尋、新增/刪除/更名檔案、更新幻燈片、新增/刪除/更改目錄與多重複製功能。","usage":"執行 Y340 → 對話框選圖庫目錄 → 以幻燈片翻頁瀏覽 → 選圖塊 → 插入或管理檔案/目錄","level":9,"lt":"⚠️","ver":"v2.0 (2013/12/26，檔案日期 2026-08-30)","author":"俞雲霨","video":"","fas":"fas/Y340.fas"},{"no":1959,"file":"Y557.LSP","cmd":"Y557","cat":"面積/數量統計","desc":"周長與面積計算 v5.0：可選聚合線或點選內部點，計算周長、地面積、牆面積，公制或台制，並可輸出簡易訊息、圖面文字、表格或 Excel 文字檔。","usage":"執行 Y557 → 對話框選對象方式/計算項目/顯示方式/項目名稱 → 選取聚合線或內部點 → 輸出到圖面、表格或檔案","level":9,"lt":"✅","ver":"v5.0 2023/01/30 (檔案日期 2025-06-29)","author":"俞雲霨","video":"","fas":"fas/Y557.fas"},{"no":1960,"file":"Y580.LSP","cmd":"Y580","cat":"面積/數量統計","desc":"自動分割正多邊形並列表統計面積計算式 v1.1，以對話框設定圖層、字型與選項，分割後輸出各區面積計算式與小計表格。","usage":"執行 Y580 → 對話框設定 → 選取多邊形範圍 → 自動分割 → 輸出計算式與統計表","level":9,"lt":"❌","ver":"v1.1 2019/09/05 (檔案日期 2025-08-09)","author":"俞雲霨","video":"","fas":"fas/Y580.fas"},{"no":1961,"file":"程式做圖塊.LSP","cmd":"（無，副程式庫）","cat":"圖塊/屬性","desc":"以 entmake 用程式建立 G-MAT 與 Test_Points 等含屬性定義的圖塊（含圓與檔案日期屬性），示範程式建立圖塊。","usage":"載入後呼叫其函式 → 自動建立含屬性的圖塊定義","level":6,"lt":"✅","ver":"20250716","author":"—","video":"","fas":""},{"no":1962,"file":"變數設定-1.lsp","cmd":"（無，副程式庫）","cat":"系統/授權","desc":"以 setenv 設定 AutoCAD 偏好環境變數：塊編輯器與模型空間背景改黑、十字游標白、自動追蹤向量色、命令列字體 Consolas 與各項命令列/文字視窗配色（一級設定）。","usage":"載入後執行其設定函式（str 變數名、K 值）→ 重啟 CAD 後套用","level":4,"lt":"✅","ver":"20250305 (檔案日期 2025-05-05)","author":"chengshunyi","video":"","fas":""},{"no":1963,"file":"變數設定-2.lsp","cmd":"op1","cat":"系統/授權","desc":"AutoCAD 初始化設置通用版：視窗最大化、動態輸入關、快捷特性關、單位十進位度數、插入縮放單位毫米、MAXACTVP 64、極軸正交、ViewCube 等系統變數一次設定。","usage":"執行 op1 → 自動設定一整批系統變數","level":3,"lt":"✅","ver":"20250305","author":"chengshunyi","video":"","fas":""},{"no":1964,"file":"變數設定-3.LSP","cmd":"（無，副程式庫）","cat":"系統/授權","desc":"以 ActiveX 偏好設定開啟佈局頁籤、關閉捲軸、命令列字體 Consolas，並在佈局隱藏可列印範圍、圖紙背景與陰影，模型空間背景黑、十字游標 250 色。","usage":"載入 .lsp 即自動套用顯示設定","level":3,"lt":"✅","ver":"20250305","author":"chengshunyi","video":"","fas":""},{"no":1965,"file":"_backup_20261115\\blka-exph_v1.19.0.lsp","cmd":"BLKA-EXPH","cat":"圖塊/屬性","desc":"BLOCK 圖庫管理（建築圖框標題欄風格）：以幻燈片窗格分頁瀏覽並插入圖塊，支援目錄與圖檔新增、刪除、更名、批次更新幻燈片、可選排版與字體。","usage":"執行 BLKA-EXPH → 對話框選圖庫目錄 → 幻燈片翻頁 → 選圖塊插入，或管理目錄/圖檔/更新幻燈片","level":9,"lt":"⚠️","ver":"v1.19.0 (備份 2026-11-15)","author":"ChengBar (MyCAD)","video":"https://youtu.be/zMZkAvqKeOw","fas":""},{"no":1966,"file":"_backup_20261115\\blkmng-archi_v1.21.0.lsp","cmd":"BLKA","cat":"圖塊/屬性","desc":"BLOCK 圖庫管理（建築圖框標題欄風格），指令為 BLKA：幻燈片分頁瀏覽插入圖塊，目錄與圖檔新增、刪除、更名、批次更新幻燈片。","usage":"執行 BLKA → 對話框選圖庫目錄 → 幻燈片翻頁 → 選圖塊插入，或管理目錄/圖檔/更新幻燈片","level":9,"lt":"⚠️","ver":"v1.21.0 (備份 2026-11-15)","author":"ChengBar (MyCAD)","video":"https://youtu.be/wKyJtD75P3Y","fas":""}],"criteria":[{"item":"程式難易度","level":"1","text":"不到 30 行，只是 command 指令巨集或改系統變數"},{"item":"程式難易度","level":"2","text":"單一選取加上簡單修改（改圖層、顏色、字高）"},{"item":"程式難易度","level":"3","text":"用迴圈處理選集，讀寫 entget/entmod"},{"item":"程式難易度","level":"4","text":"有幾何計算（角度、距離、交點、偏移），或需要多個輸入"},{"item":"程式難易度","level":"5","text":"有用 VLA/ActiveX、*error* 還原，或寫成好幾個副程式"},{"item":"程式難易度","level":"6","text":"有 DCL 對話框、全域記憶，或處理圖塊屬性、表格"},{"item":"程式難易度","level":"7","text":"演算法比較複雜（自動標註、剖面自動繪製、排序比對）"},{"item":"程式難易度","level":"8","text":"會讀寫外部檔案或 Excel，或使用 reactor、跨圖檔處理"},{"item":"程式難易度","level":"9","text":"大型整合程式，有多個對話框、多種模式，超過 1000 行"},{"item":"LT 2024+","level":"✅","text":"沒有用到 LT 限制的功能"},{"item":"LT 2024+","level":"⚠️","text":"主要功能可以用，只有次要或備援功能用到 LT 不支援的項目"},{"item":"LT 2024+","level":"❌","text":"用到 vlax-create-object/get-object（Excel、Shell 等外部 COM）、Express Tools acet-*、VBA、ARX/.NET、或建立 3D 實體/曲面/網格"},{"item":"LT 2024+","level":"❓","text":"加密檔（PROTECTED LISP），無法讀取原始碼判定，需實測"},{"item":"說明","level":"","text":"LT 欄位是依程式碼靜態判定（依 Autodesk 官方 LT AutoLISP 限制），未在 LT 實機執行測試。"}]};
